ligeiwfg1rs	ligeiwfg1rs	{"parentId":"dskhrguykm4","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê đơn vị"},"stepParams":{"jsSettings":{"runJs":{"version":"1","code":"const { Alert, Card, Col, Row, Skeleton, Statistic } = ctx.libs.antd;\\n\\nctx.render(<Skeleton active paragraph={{ rows: 1 }} />);\\n\\ntry {\\n  const resource = ctx.makeResource('MultiRecordResource');\\n  resource.setResourceName('don_vi');\\n  resource.setPageSize?.(1000);\\n  await resource.refresh();\\n  const rows = resource.getData?.() || [];\\n  const metrics = [\\n    { key: 'total', title: ctx.t('Tổng đơn vị'), value: resource.getMeta?.()?.count ?? rows.length, color: '#1677ff' },\\n    { key: 'parent', title: ctx.t('Đơn vị cha'), value: rows.filter((row) => !row.parentId).length, color: '#52c41a' },\\n    { key: 'child', title: ctx.t('Đơn vị con'), value: rows.filter((row) => Boolean(row.parentId)).length, color: '#fa8c16' },\\n    { key: 'active', title: ctx.t('Đang hoạt động'), value: rows.filter((row) => row.trang_thai === 'hoat_dong').length, color: '#8c8c8c' },\\n  ];\\n\\n  ctx.render(\\n    <Row gutter={[16, 16]}>\\n      {metrics.map((metric) => (\\n        <Col key={metric.key} xs={24} sm={12} lg={6}>\\n          <Card size=\\"small\\" style={{ borderLeft: `4px solid ${metric.color}`, height: '100%' }}>\\n            <Statistic title={metric.title} value={metric.value} suffix={ctx.t('ĐV')} />\\n          </Card>\\n        </Col>\\n      ))}\\n    </Row>,\\n  );\\n} catch (error) {\\n  ctx.render(<Alert type=\\"error\\" showIcon message={ctx.t('Không tải được thống kê đơn vị')} description={String(error?.message || error)} />);\\n}"}},"__flowSurfaceMeta":{"declaredKey":"units.unitStats"}}}
