m9boatk0dhy	m9boatk0dhy	{"parentId":"2f4dn5lruky","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"1","code":"const { Alert, Card, Col, Row, Skeleton, Statistic } = ctx.libs.antd;\\nctx.render(<Skeleton active paragraph={{ rows: 1 }} />);\\ntry {\\n  const resource = ctx.makeResource('MultiRecordResource');\\n  resource.setResourceName('vai_tro');\\n  resource.setPageSize?.(1000);\\n  await resource.refresh();\\n  const rows = resource.getData?.() || [];\\n  const metrics = [\\n    { key: 'total', title: ctx.t('Tổng vai trò'), value: resource.getMeta?.()?.count ?? rows.length, color: '#1677ff' },\\n    { key: 'active', title: ctx.t('Đang hoạt động'), value: rows.filter((row) => row.trang_thai === 'active' && !row.is_deleted).length, color: '#52c41a' },\\n    { key: 'system', title: ctx.t('Nguồn hệ thống'), value: rows.filter((row) => row.nguon_du_lieu === 'he_thong').length, color: '#fa8c16' },\\n    { key: 'deleted', title: ctx.t('Đã xóa'), value: rows.filter((row) => Boolean(row.is_deleted)).length, color: '#8c8c8c' },\\n  ];\\n  ctx.render(<Row gutter={[16, 16]}>{metrics.map((metric) => <Col key={metric.key} xs={24} sm={12} lg={6}><Card size=\\"small\\" style={{ borderLeft: `4px solid ${metric.color}`, height: '100%' }}><Statistic title={metric.title} value={metric.value} suffix={ctx.t('VT')} /></Card></Col>)}</Row>);\\n} catch (error) { ctx.render(<Alert type=\\"error\\" showIcon message={ctx.t('Không tải được thống kê vai trò')} description={String(error?.message || error)} />); }"}}}}
