h7yksz1lzaw	h7yksz1lzaw	{"parentId":"xs8zbb57638","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê kết nối AI"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Card, Col, Row, Statistic } = ctx.libs.antd;\\nconst { ApiOutlined, CheckCircleOutlined, CloseCircleOutlined, QuestionCircleOutlined } = ctx.libs.antdIcons;\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('cau_hinh_ket_noi_ai');\\n  await ctx.resource.refresh();\\n  const rows = (ctx.resource.getData?.() || []).filter((r) => r.is_deleted !== true);\\n  const metrics = [\\n    { title: ctx.t('Tổng kết nối'), value: rows.length, color: '#1677ff', icon: <ApiOutlined /> },\\n    { title: ctx.t('Đang hoạt động'), value: rows.filter((r) => r.trang_thai === 'hoat_dong').length, color: '#389e0d', icon: <CheckCircleOutlined /> },\\n    { title: ctx.t('Mất kết nối / Lỗi'), value: rows.filter((r) => r.trang_thai === 'loi' || r.trang_thai === 'tam_ngung').length, color: '#cf1322', icon: <CloseCircleOutlined /> },\\n    { title: ctx.t('Chưa kiểm tra'), value: rows.filter((r) => !r.trang_thai || r.trang_thai === 'chua_kiem_tra').length, color: '#8c8c8c', icon: <QuestionCircleOutlined /> },\\n  ];\\n  ctx.render(\\n    <Row gutter={[12, 12]}>\\n      {metrics.map((m) => (\\n        <Col key={m.title} xs={24} sm={12} xl={6}>\\n          <Card size=\\"small\\" bordered>\\n            <Statistic title={m.title} value={m.value} prefix={m.icon} valueStyle={{ color: m.color }} />\\n          </Card>\\n        </Col>\\n      ))}\\n    </Row>,\\n  );\\n} catch (error) {\\n  ctx.render(<Alert showIcon type=\\"error\\" message={ctx.t('Error')} description={String(error?.message || error)} />);\\n}"}},"__flowSurfaceMeta":{"declaredKey":"main.statsBlock"}}}
