ilfzja3uzf2	ilfzja3uzf2	{"parentId":"oigkm0x7abu","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê ngành nghề"},"stepParams":{"jsSettings":{"runJs":{"version":"1","code":"const { Alert, Card, Col, Row, Skeleton, Statistic } = ctx.libs.antd;\\nctx.render(<Skeleton active paragraph={{ rows: 1 }} />);\\ntry {\\n  const resource = ctx.makeResource('MultiRecordResource');\\n  resource.setResourceName('nganh_nghe');\\n  resource.setPageSize?.(1000);\\n  await resource.refresh();\\n  const rows = resource.getData?.() || [];\\n  const groupKeys = new Set(rows.map((row) => row.nhom_nganh?.id || row.nhomNganhId).filter(Boolean));\\n  const metrics = [\\n    { key: 'total', title: ctx.t('Tổng ngành nghề'), value: resource.getMeta?.()?.count ?? rows.length, color: '#1677ff' },\\n    { key: 'training', title: ctx.t('Yêu cầu huấn luyện'), value: rows.filter((row) => Boolean(row.yeu_cau_huan_luyen)).length, color: '#52c41a' },\\n    { key: 'optional', title: ctx.t('Không bắt buộc huấn luyện'), value: rows.filter((row) => !row.yeu_cau_huan_luyen).length, color: '#fa8c16' },\\n    { key: 'groups', title: ctx.t('Nhóm ngành'), value: groupKeys.size, color: '#8c8c8c' },\\n  ];\\n  ctx.render(<Row gutter={[16, 16]}>{metrics.map((metric) => <Col key={metric.key} xs={24} sm={12} lg={6}><Card size=\\"small\\" style={{ borderLeft: `4px solid ${metric.color}`, height: '100%' }}><Statistic title={metric.title} value={metric.value} /></Card></Col>)}</Row>);\\n} catch (error) { ctx.render(<Alert type=\\"error\\" showIcon message={ctx.t('Không tải được thống kê ngành nghề')} description={String(error?.message || error)} />); }"}},"__flowSurfaceMeta":{"declaredKey":"occupations.occupationStats"}}}
