5mmrazy1mxf	5mmrazy1mxf	{"parentId":"z2ly8oc7y1o","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Badge, Button, Card, Col, Descriptions, Divider, Drawer, Input, Modal, Progress, Row, Select, Space, Statistic, Table, Tabs, Tag, Tooltip, Typography } = ctx.libs.antd;\\nconst { BankOutlined, BookOutlined, CheckCircleOutlined, CheckOutlined, ClockCircleOutlined, CloseCircleOutlined, EyeOutlined, ExclamationCircleOutlined, InfoCircleOutlined, ReloadOutlined, RollbackOutlined, SearchOutlined, StopOutlined, TeamOutlined, UserOutlined, WarningOutlined } = ctx.libs.antdIcons;\\nconst { useState, useMemo, useCallback } = ctx.libs.React;\\n\\nvar STATUS_HVL = [\\n  { value: 'vao_lop', label: 'Vào lớp', color: 'default' },\\n  { value: 'dang_hoc', label: 'Đang học', color: 'processing' },\\n  { value: 'hoan_thanh_hoc', label: 'Hoàn thành học', color: 'success' },\\n  { value: 'da_rut', label: 'Đã rút', color: 'error' },\\n];\\nvar STATUS_HVL_MAP = Object.fromEntries(STATUS_HVL.map(function(s) { return [s.value, s]; }));\\n\\nvar KET_QUA_MAP = {\\n  chua_danh_gia: { label: 'Chưa đánh giá', color: 'default' },\\n  dat: { label: 'Đạt', color: 'success' },\\n  khong_dat: { label: 'Không đạt', color: 'error' },\\n};\\n\\nvar STATUS_LOP = {\\n  du_kien: { label: 'Dự kiến', color: 'gold' },\\n  dang_hoc: { label: 'Đang học', color: 'blue' },\\n  hoan_thanh: { label: 'Hoàn thành', color: 'green' },\\n  huy: { label: 'Đã hủy', color: 'red' },\\n};\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('lop_hoc');\\n  ctx.resource.setFilter({ is_deleted: { $ne: true } });\\n  ctx.resource.setAppends(['don_vi', 'khoa_huan_luyen', 'giang_vien_nld', 'hoc_vien_lop', 'hoc_vien_lop.nguoi_lao_dong', 'hoc_vien_lop.nguoi_lao_dong.bac_tho', 'hoc_vien_lop.nguoi_lao_dong.don_vi', 'hoc_vien_lop.nguoi_xac_nhan']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(200);\\n  await ctx.resource.refresh();\\n  var initialClasses = ctx.resource.getData() || [];\\n\\n  var hvlCrudRes = ctx.makeResource('MultiRecordResource');\\n  hvlCrudRes.setResourceName('hoc_vien_lop');\\n\\n  async function fetchClasses() {\\n    var res = ctx.makeResource('MultiRecordResource');\\n    res.setResourceName('lop_hoc');\\n    res.setFilter({ is_deleted: { $ne: true } });\\n    res.setAppends(['don_vi', 'khoa_huan_luyen', 'giang_vien_nld', 'hoc_vien_lop', 'hoc_vien_lop.nguoi_lao_dong', 'hoc_vien_lop.nguoi_lao_dong.bac_tho', 'hoc_vien_lop.nguoi_lao_dong.don_vi', 'hoc_vien_lop.nguoi_xac_nhan']);\\n    res.setSort(['-createdAt']);\\n    res.setPageSize(200);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  async function updateHocVienLop(hvlId, data) {\\n    await ctx.request({\\n      url: 'hoc_vien_lop:update',\\n      method: 'post',\\n      params: { filterByTk: hvlId },\\n      data: data,\\n    });\\n  }\\n\\n  function formatDate(val) {\\n    if (!val) return '-';\\n    try {\\n      var d = new Date(val);\\n      if (isNaN(d.getTime())) return val;\\n      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();\\n    } catch (e) { return val; }\\n  }\\n\\n  function ClassProgressApp(props) {\\n    var [classes, setClasses] = useState(props.initialClasses);\\n    var [selectedClassId, setSelectedClassId] = useState(null);\\n    var [loading, setLoading] = useState(false);\\n    var [hvDetailRecord, setHvDetailRecord] = useState(null);\\n    var [searchText, setSearchText] = useState('');\\n    var [filterStatus, setFilterStatus] = useState(undefined);\\n    var [confirmModalOpen, setConfirmModalOpen] = useState(false);\\n    var [confirmRecord, setConfirmRecord] = useState(null);\\n    var [confirmNote, setConfirmNote] = useState('');\\n    var [actionLoading, setActionLoading] = useState(false);\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var data = await fetchClasses();\\n        setClasses(data);\\n      } catch (e) {\\n        ctx.message.error(ctx.t('Không tải được dữ liệu: ') + String(e?.message || e));\\n      }\\n      setLoading(false);\\n    }, []);\\n\\n    var selectedClass = useMemo(function() {\\n      if (!selectedClassId) return null;\\n      return classes.find(function(c) { return c.id === selectedClassId; }) || null;\\n    }, [classes, selectedClassId]);\\n\\n    var hocVienList = useMemo(function() {\\n      if (!selectedClass) return [];\\n      return (selectedClass.hoc_vien_lop || []).filter(function(h) { return h.is_deleted !== true; });\\n    }, [selectedClass]);\\n\\n    var filteredHV = useMemo(function() {\\n      var list = hocVienList;\\n      if (filterStatus) {\\n        list = list.filter(function(h) { return h.trang_thai === filterStatus; });\\n      }\\n      if (searchText) {\\n        var s = searchText.toLowerCase();\\n        list = list.filter(function(h) {\\n          var nld = h.nguoi_lao_dong || {};\\n          return (nld.ho_ten || '').toLowerCase().includes(s) ||\\n            (nld.ma_nguoi_lao_dong || '').toLowerCase().includes(s) ||\\n            (nld.so_giay_to || '').toLowerCase().includes(s);\\n        });\\n      }\\n      return list;\\n    }, [hocVienList, filterStatus, searchText]);\\n\\n    var stats = useMemo(function() {\\n      var total = hocVienList.length;\\n      var vaoLop = hocVienList.filter(function(h) { return h.trang_thai === 'vao_lop'; }).length;\\n      var dangHoc = hocVienList.filter(function(h) { return h.trang_thai === 'dang_hoc'; }).length;\\n      var hoanThanh = hocVienList.filter(function(h) { return h.trang_thai === 'hoan_thanh_hoc'; }).length;\\n      var duDKThi = hocVienList.filter(function(h) { return h.du_dieu_kien_thi === true; }).length;\\n      var daRut = hocVienList.filter(function(h) { return h.trang_thai === 'da_rut'; }).length;\\n      return { total: total, vaoLop: vaoLop, dangHoc: dangHoc, hoanThanh: hoanThanh, duDKThi: duDKThi, daRut: daRut };\\n    }, [hocVienList]);\\n\\n    var handleUpdateStatus = useCallback(async function(hvl, newStatus) {\\n      setActionLoading(true);\\n      try {\\n        await updateHocVienLop(hvl.id, { trang_thai: newStatus });\\n        ctx.message.success(ctx.t('Cập nhật trạng thái thành công'));\\n        await refreshData();\\n      } catch (e) {\\n        ctx.message.error(ctx.t('Lỗi: ') + String(e?.message || e));\\n      }\\n      setActionLoading(false);\\n    }, [refreshData]);\\n\\n    var openConfirmModal = useCallback(function(hvl) {\\n      setConfirmRecord(hvl);\\n      setConfirmNote('');\\n      setConfirmModalOpen(true);\\n    }, []);\\n\\n    var handleConfirmCompletion = useCallback(async function() {\\n      if (!confirmRecord) return;\\n      setActionLoading(true);\\n      try {\\n        await updateHocVienLop(confirmRecord.id, {\\n          trang_thai: 'hoan_thanh_hoc',\\n          du_dieu_kien_thi: true,\\n          ngay_xac_nhan: new Date().toISOString(),\\n          nguon_xac_nhan: 'thu_cong',\\n          ghi_chu: confirmNote || null,\\n        });\\n        ctx.message.success(ctx.t('Đã xác nhận hoàn thành học và đủ điều kiện thi'));\\n        setConfirmModalOpen(false);\\n        setConfirmRecord(null);\\n        await refreshData();\\n      } catch (e) {\\n        ctx.message.error(ctx.t('Lỗi: ') + String(e?.message || e));\\n      }\\n      setActionLoading(false);\\n    }, [confirmRecord, confirmNote, refreshData]);\\n\\n    var handleRevokeConfirm = useCallback(async function(hvl) {\\n      setActionLoading(true);\\n      try {\\n        await updateHocVienLop(hvl.id, {\\n          trang_thai: 'dang_hoc',\\n          du_dieu_kien_thi: false,\\n          ngay_xac_nhan: null,\\n          nguon_xac_nhan: null,\\n        });\\n        ctx.message.success(ctx.t('Đã hủy xác nhận'));\\n        await refreshData();\\n      } catch (e) {\\n        ctx.message.error(ctx.t('Lỗi: ') + String(e?.message || e));\\n      }\\n      setActionLoading(false);\\n    }, [refreshData]);\\n\\n    var classOptions = useMemo(function() {\\n      return classes.map(function(c) {\\n        var statusInfo = STATUS_LOP[c.trang_thai] || {};\\n        return {\\n          value: c.id,\\n          label: (c.ma_lop || '') + ' — ' + (c.ten_lop || '') + ' (' + (statusInfo.label || c.trang_thai) + ')',\\n        };\\n      });\\n    }, [classes]);\\n\\n    var hvColumns = [\\n      {\\n        title: ctx.t('STT'), key: 'stt', width: 55, align: 'center', fixed: 'left',\\n        render: function(_, __, idx) { return idx + 1; },\\n      },\\n      {\\n        title: ctx.t('Mã NV'), key: 'ma_nv', width: 110,\\n        render: function(_, record) { return record.nguoi_lao_dong?.ma_nguoi_lao_dong || '-'; },\\n      },\\n      {\\n        title: ctx.t('Họ và tên'), key: 'ho_ten', width: 180,\\n        render: function(_, record) {\\n          var name = record.nguoi_lao_dong?.ho_ten || '-';\\n          return (\\n            <Tooltip title={ctx.t('Xem chi tiết tiến độ')}>\\n              <Typography.Link onClick={function() { setHvDetailRecord(record); }}>{name}</Typography.Link>\\n            </Tooltip>\\n          );\\n        },\\n      },\\n      {\\n        title: ctx.t('Đơn vị'), key: 'don_vi', width: 150, ellipsis: true,\\n        render: function(_, record) { return record.nguoi_lao_dong?.don_vi?.ten_don_vi || '-'; },\\n      },\\n      {\\n        title: ctx.t('Bậc thợ'), key: 'bac_tho', width: 120,\\n        render: function(_, record) { return record.nguoi_lao_dong?.bac_tho?.ten_bac || '-'; },\\n      },\\n      {\\n        title: ctx.t('Ngày ghi danh'), dataIndex: 'ngay_ghi_danh', key: 'ngay_ghi_danh', width: 110,\\n        render: function(val) { return formatDate(val); },\\n      },\\n      {\\n        title: ctx.t('Trạng thái'), dataIndex: 'trang_thai', key: 'trang_thai', width: 130, align: 'center',\\n        render: function(val) {\\n          var s = STATUS_HVL_MAP[val];\\n          return s ? <Tag color={s.color}>{s.label}</Tag> : <span>{val || '-'}</span>;\\n        },\\n      },\\n      {\\n        title: ctx.t('ĐK Thi'), dataIndex: 'du_dieu_kien_thi', key: 'dk_thi', width: 80, align: 'center',\\n        render: function(val) {\\n          return val ? <Tag color=\\"green\\" icon={<CheckCircleOutlined />}>{ctx.t('Đủ')}</Tag> : <Tag color=\\"default\\">{ctx.t('Chưa')}</Tag>;\\n        },\\n      },\\n      {\\n        title: ctx.t('Ngày xác nhận'), dataIndex: 'ngay_xac_nhan', key: 'ngay_xac_nhan', width: 110,\\n        render: function(val) { return formatDate(val); },\\n      },\\n      {\\n        title: ctx.t('Thao tác'), key: 'actions', width: 160, fixed: 'right',\\n        render: function(_, record) {\\n          var isCompleted = record.trang_thai === 'hoan_thanh_hoc';\\n          var isDKThi = record.du_dieu_kien_thi === true;\\n          var isRut = record.trang_thai === 'da_rut';\\n          return (\\n            <Space size={4}>\\n              <Tooltip title={ctx.t('Xem chi tiết')}>\\n                <Button icon={<EyeOutlined />} onClick={function() { setHvDetailRecord(record); }} />\\n              </Tooltip>\\n              {!isRut && !isDKThi && (\\n                <Tooltip title={ctx.t('Xác nhận hoàn thành & ĐK thi')}>\\n                  <Button icon={<CheckOutlined />} style={{ color: '#52c41a', borderColor: '#b7eb8f' }} onClick={function() { openConfirmModal(record); }} />\\n                </Tooltip>\\n              )}\\n              {isDKThi && (\\n                <Tooltip title={ctx.t('Hủy xác nhận')}>\\n                  <Button icon={<RollbackOutlined />} danger onClick={function() { handleRevokeConfirm(record); }} />\\n                </Tooltip>\\n              )}\\n            </Space>\\n          );\\n        },\\n      },\\n    ];\\n\\n    var renderClassInfo = function() {\\n      if (!selectedClass) return null;\\n      var gvNames = (selectedClass.giang_vien_nld || []).map(function(g) { return g.ho_ten || '-'; }).join(', ') || '-';\\n      var statusInfo = STATUS_LOP[selectedClass.trang_thai] || {};\\n      return (\\n        <Card size=\\"small\\" style={{ marginBottom: 12 }}>\\n          <Descriptions column={{ xs: 1, sm: 2, md: 4 }} size=\\"small\\">\\n            <Descriptions.Item label={ctx.t('Mã lớp')}>\\n              <Typography.Text strong style={{ color: '#1677ff' }}>{selectedClass.ma_lop || '-'}</Typography.Text>\\n            </Descriptions.Item>\\n            <Descriptions.Item label={ctx.t('Tên lớp')}>{selectedClass.ten_lop || '-'}</Descriptions.Item>\\n            <Descriptions.Item label={ctx.t('Khóa huấn luyện')}>{selectedClass.khoa_huan_luyen?.ten_khoa_hoc || '-'}</Descriptions.Item>\\n            <Descriptions.Item label={ctx.t('Trạng thái')}>\\n              <Tag color={statusInfo.color}>{statusInfo.label || selectedClass.trang_thai}</Tag>\\n            </Descriptions.Item>\\n            <Descriptions.Item label={ctx.t('Đơn vị')}>{selectedClass.don_vi?.ten_don_vi || '-'}</Descriptions.Item>\\n            <Descriptions.Item label={ctx.t('Giảng viên')}>{gvNames}</Descriptions.Item>\\n            <Descriptions.Item label={ctx.t('Thời gian')}>{formatDate(selectedClass.ngay_bat_dau) + ' → ' + formatDate(selectedClass.ngay_ket_thuc)}</Descriptions.Item>\\n            <Descriptions.Item label={ctx.t('Sĩ số')}>{stats.total + ' / ' + (selectedClass.si_so_toi_da || '-')}</Descriptions.Item>\\n          </Descriptions>\\n        </Card>\\n      );\\n    };\\n\\n    var renderStats = function() {\\n      if (!selectedClass) return null;\\n      var items = [\\n        { title: ctx.t('Tổng HV'), value: stats.total, color: '#1677ff', icon: <TeamOutlined /> },\\n        { title: ctx.t('Vào lớp'), value: stats.vaoLop, color: '#8c8c8c', icon: <UserOutlined /> },\\n        { title: ctx.t('Đang học'), value: stats.dangHoc, color: '#1677ff', icon: <BookOutlined /> },\\n        { title: ctx.t('Hoàn thành'), value: stats.hoanThanh, color: '#52c41a', icon: <CheckCircleOutlined /> },\\n        { title: ctx.t('Đủ ĐK thi'), value: stats.duDKThi, color: '#722ed1', icon: <CheckOutlined /> },\\n        { title: ctx.t('Đã rút'), value: stats.daRut, color: '#ff4d4f', icon: <StopOutlined /> },\\n      ];\\n      return (\\n        <Row gutter={[8, 8]} style={{ marginBottom: 12 }}>\\n          {items.map(function(m) {\\n            return (\\n              <Col key={m.title} xs={12} sm={8} md={4}>\\n                <Card size=\\"small\\" bordered>\\n                  <Statistic title={m.title} value={m.value} prefix={m.icon} valueStyle={{ color: m.color, fontSize: 20 }} />\\n                </Card>\\n              </Col>\\n            );\\n          })}\\n        </Row>\\n      );\\n    };\\n\\n    var renderHvDetail = function() {\\n      if (!hvDetailRecord) return null;\\n      var nld = hvDetailRecord.nguoi_lao_dong || {};\\n      var statusInfo = STATUS_HVL_MAP[hvDetailRecord.trang_thai] || {};\\n      var kqInfo = KET_QUA_MAP[hvDetailRecord.ket_qua] || { label: hvDetailRecord.ket_qua || '-', color: 'default' };\\n      var xacNhanUser = hvDetailRecord.nguoi_xac_nhan;\\n      return (\\n        <Drawer\\n          title={ctx.t('Chi tiết tiến độ học viên')}\\n          open={!!hvDetailRecord}\\n          onClose={function() { setHvDetailRecord(null); }}\\n          width={600}\\n          extra={\\n            <Space>\\n              <Tooltip title={ctx.t('Tải lại')}>\\n                <Button icon={<ReloadOutlined />} onClick={refreshData} loading={loading} />\\n              </Tooltip>\\n            </Space>\\n          }\\n        >\\n          <Card title={ctx.t('Thông tin học viên')} size=\\"small\\" style={{ marginBottom: 16 }}>\\n            <Descriptions column={2} size=\\"small\\" bordered>\\n              <Descriptions.Item label={ctx.t('Họ và tên')} span={2}>\\n                <Typography.Text strong>{nld.ho_ten || '-'}</Typography.Text>\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Mã NV')}>{nld.ma_nguoi_lao_dong || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Số CCCD')}>{nld.so_giay_to || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Đơn vị')}>{nld.don_vi?.ten_don_vi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Bậc thợ')}>{nld.bac_tho?.ten_bac || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Điện thoại')}>{nld.dien_thoai || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Email')}>{nld.email || '-'}</Descriptions.Item>\\n            </Descriptions>\\n          </Card>\\n\\n          <Card title={ctx.t('Trạng thái ghi danh')} size=\\"small\\" style={{ marginBottom: 16 }}>\\n            <Descriptions column={2} size=\\"small\\" bordered>\\n              <Descriptions.Item label={ctx.t('Mã ghi danh')}>{hvDetailRecord.ma_ghi_danh || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Trạng thái')}>\\n                <Tag color={statusInfo.color}>{statusInfo.label || hvDetailRecord.trang_thai}</Tag>\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ngày ghi danh')}>{formatDate(hvDetailRecord.ngay_ghi_danh)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Đủ ĐK thi')}>\\n                {hvDetailRecord.du_dieu_kien_thi ? <Tag color=\\"green\\" icon={<CheckCircleOutlined />}>{ctx.t('Đủ điều kiện')}</Tag> : <Tag color=\\"default\\">{ctx.t('Chưa đủ')}</Tag>}\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Kết quả')}>\\n                <Tag color={kqInfo.color}>{kqInfo.label}</Tag>\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Điểm tổng kết')}>\\n                {hvDetailRecord.diem_tong_ket != null ? hvDetailRecord.diem_tong_ket : '-'}\\n              </Descriptions.Item>\\n            </Descriptions>\\n          </Card>\\n\\n          <Card title={ctx.t('Xác nhận hoàn thành')} size=\\"small\\" style={{ marginBottom: 16 }}>\\n            <Descriptions column={2} size=\\"small\\" bordered>\\n              <Descriptions.Item label={ctx.t('Ngày xác nhận')}>{formatDate(hvDetailRecord.ngay_xac_nhan)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Nguồn xác nhận')}>\\n                {hvDetailRecord.nguon_xac_nhan === 'thu_cong' ? ctx.t('Thủ công') : hvDetailRecord.nguon_xac_nhan === 'lms' ? ctx.t('LMS tự động') : '-'}\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Người xác nhận')} span={2}>{xacNhanUser?.nickname || xacNhanUser?.username || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ghi chú')} span={2}>{hvDetailRecord.ghi_chu || '-'}</Descriptions.Item>\\n            </Descriptions>\\n          </Card>\\n\\n          {hvDetailRecord.trang_thai === 'da_rut' && (\\n            <Card title={ctx.t('Thông tin rút khỏi lớp')} size=\\"small\\">\\n              <Descriptions column={1} size=\\"small\\" bordered>\\n                <Descriptions.Item label={ctx.t('Ngày rời')}>{formatDate(hvDetailRecord.ngay_roi)}</Descriptions.Item>\\n                <Descriptions.Item label={ctx.t('Lý do')}>{hvDetailRecord.ly_do_rut || '-'}</Descriptions.Item>\\n              </Descriptions>\\n            </Card>\\n          )}\\n\\n          <Divider />\\n          <Space>\\n            {!hvDetailRecord.du_dieu_kien_thi && hvDetailRecord.trang_thai !== 'da_rut' && (\\n              <Button type=\\"primary\\" icon={<CheckOutlined />} loading={actionLoading} onClick={function() { openConfirmModal(hvDetailRecord); setHvDetailRecord(null); }}>\\n                {ctx.t('Xác nhận hoàn thành & ĐK thi')}\\n              </Button>\\n            )}\\n            {hvDetailRecord.du_dieu_kien_thi && (\\n              <Button danger icon={<RollbackOutlined />} loading={actionLoading} onClick={function() { handleRevokeConfirm(hvDetailRecord); setHvDetailRecord(null); }}>\\n                {ctx.t('Hủy xác nhận')}\\n              </Button>\\n            )}\\n          </Space>\\n        </Drawer>\\n      );\\n    };\\n\\n    return (\\n      <>\\n        <Card size=\\"small\\" style={{ marginBottom: 12 }}>\\n          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>\\n            <Space size=\\"middle\\">\\n              <Typography.Text strong style={{ fontSize: 15 }}>{ctx.t('Quản lý tiến độ lớp học')}</Typography.Text>\\n              <Tooltip title={ctx.t('Tải lại')}>\\n                <Button type=\\"text\\" size=\\"small\\" icon={<ReloadOutlined />} onClick={refreshData} loading={loading} />\\n              </Tooltip>\\n            </Space>\\n            <Select\\n              showSearch\\n              optionFilterProp=\\"label\\"\\n              placeholder={ctx.t('Chọn lớp học để xem tiến độ...')}\\n              style={{ width: 440 }}\\n              value={selectedClassId}\\n              onChange={function(val) { setSelectedClassId(val); setSearchText(''); setFilterStatus(undefined); }}\\n              options={classOptions}\\n              allowClear\\n            />\\n          </div>\\n        </Card>\\n\\n        {selectedClass && renderClassInfo()}\\n        {selectedClass && renderStats()}\\n\\n        {selectedClass && (\\n          <Card size=\\"small\\" styles={{ body: { padding: 0 } }}>\\n            <div style={{ padding: '10px 16px', borderBottom: '1px solid #f0f0f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>\\n              <Typography.Text strong>\\n                {ctx.t('Danh sách học viên')} ({filteredHV.length})\\n              </Typography.Text>\\n              <Space size=\\"small\\">\\n                <Select\\n                  allowClear\\n                  placeholder={ctx.t('Lọc trạng thái')}\\n                  style={{ width: 160 }}\\n                  value={filterStatus}\\n                  onChange={function(val) { setFilterStatus(val); }}\\n                  options={STATUS_HVL.map(function(s) { return { value: s.value, label: s.label }; })}\\n                />\\n                <Input\\n                  placeholder={ctx.t('Tìm theo tên, mã NV...')}\\n                  prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n                  allowClear\\n                  style={{ width: 240 }}\\n                  value={searchText}\\n                  onChange={function(e) { setSearchText(e.target.value); }}\\n                />\\n              </Space>\\n            </div>\\n            <Table\\n              columns={hvColumns}\\n              dataSource={filteredHV}\\n              rowKey={function(r, idx) { return r.id || r.nguoiLaoDongId || idx; }}\\n              size=\\"small\\"\\n              loading={loading || actionLoading}\\n              scroll={{ x: 1300 }}\\n              pagination={{ pageSize: 20, showTotal: function(t) { return ctx.t('Tổng') + ': ' + t + ' ' + ctx.t('học viên'); }, size: 'small', showSizeChanger: false }}\\n            />\\n          </Card>\\n        )}\\n\\n        {!selectedClass && (\\n          <Card style={{ textAlign: 'center', padding: 40 }}>\\n            <InfoCircleOutlined style={{ fontSize: 48, color: '#bfbfbf' }} />\\n            <Typography.Paragraph type=\\"secondary\\" style={{ marginTop: 16 }}>\\n              {ctx.t('Chọn một lớp học từ danh sách trên để xem chi tiết tiến độ và quản lý học viên.')}\\n            </Typography.Paragraph>\\n          </Card>\\n        )}\\n\\n        {renderHvDetail()}\\n\\n        <Modal\\n          title={ctx.t('Xác nhận hoàn thành học')}\\n          open={confirmModalOpen}\\n          onOk={handleConfirmCompletion}\\n          onCancel={function() { setConfirmModalOpen(false); setConfirmRecord(null); }}\\n          okText={ctx.t('Xác nhận')}\\n          cancelText={ctx.t('Hủy')}\\n          confirmLoading={actionLoading}\\n        >\\n          {confirmRecord && (\\n            <>\\n              <Typography.Paragraph>\\n                {ctx.t('Xác nhận học viên')}{' '}\\n                <Typography.Text strong>{confirmRecord.nguoi_lao_dong?.ho_ten || '-'}</Typography.Text>{' '}\\n                {ctx.t('đã hoàn thành học và đủ điều kiện thi?')}\\n              </Typography.Paragraph>\\n              {confirmRecord.trang_thai !== 'hoan_thanh_hoc' && confirmRecord.trang_thai !== 'dang_hoc' && (\\n                <Alert\\n                  type=\\"warning\\"\\n                  showIcon\\n                  style={{ marginBottom: 12 }}\\n                  message={ctx.t('Lưu ý: Học viên hiện ở trạng thái \\"' + (STATUS_HVL_MAP[confirmRecord.trang_thai]?.label || confirmRecord.trang_thai) + '\\". Xác nhận sẽ chuyển sang \\"Hoàn thành học\\".')}\\n                />\\n              )}\\n              <Input.TextArea\\n                placeholder={ctx.t('Ghi chú (không bắt buộc)...')}\\n                rows={3}\\n                value={confirmNote}\\n                onChange={function(e) { setConfirmNote(e.target.value); }}\\n              />\\n            </>\\n          )}\\n        </Modal>\\n      </>\\n    );\\n  }\\n\\n  ctx.render(<ClassProgressApp initialClasses={initialClasses} />);\\n} catch (error) {\\n  ctx.render(\\n    <Alert showIcon type=\\"error\\" message={ctx.t('Không tải được dữ liệu tiến độ')} description={String(error?.message || error)} />,\\n  );\\n}\\n"}},"__flowSurfaceMeta":{"declaredKey":"tien-do-lop"}}}
