48wqjdne8bq	48wqjdne8bq	{"parentId":"9kg6ygu5i9o","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Badge, Button, Card, Col, Descriptions, Divider, Drawer, Empty, Form, Input, Modal, Popconfirm, Radio, Row, Select, Space, Statistic, Table, Tabs, Tag, Tooltip, Typography } = ctx.libs.antd;\\nconst { BulbOutlined, CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, DeleteOutlined, EditOutlined, ExclamationCircleOutlined, EyeOutlined, FileTextOutlined, PlusOutlined, QuestionCircleOutlined, ReloadOutlined, SearchOutlined, StopOutlined } = ctx.libs.antdIcons;\\nconst { useState, useMemo, useCallback, useEffect } = ctx.libs.React;\\n\\nvar HINH_THUC = [\\n  { value: 'trac_nghiem', label: 'Trắc nghiệm', color: 'blue' },\\n  { value: 'tu_luan', label: 'Tự luận', color: 'orange' },\\n];\\nvar HINH_THUC_MAP = Object.fromEntries(HINH_THUC.map(function(s) { return [s.value, s]; }));\\n\\nvar MUC_DO = [\\n  { value: 'de', label: 'Dễ', color: 'green' },\\n  { value: 'trung_binh', label: 'Trung bình', color: 'gold' },\\n  { value: 'kho', label: 'Khó', color: 'red' },\\n];\\nvar MUC_DO_MAP = Object.fromEntries(MUC_DO.map(function(s) { return [s.value, s]; }));\\n\\nvar TRANG_THAI_CH = [\\n  { value: 'nhap', label: 'Nháp', color: 'default' },\\n  { value: 'cho_phe_duyet', label: 'Chờ phê duyệt', color: 'processing' },\\n  { value: 'da_phe_duyet', label: 'Đã phê duyệt', color: 'success' },\\n  { value: 'tu_choi', label: 'Từ chối', color: 'error' },\\n];\\nvar TRANG_THAI_CH_MAP = Object.fromEntries(TRANG_THAI_CH.map(function(s) { return [s.value, s]; }));\\n\\nvar NGUON_TAO = [\\n  { value: 'thu_cong', label: 'Thủ công', color: 'default' },\\n  { value: 'ai', label: 'AI', color: 'purple' },\\n];\\nvar NGUON_TAO_MAP = Object.fromEntries(NGUON_TAO.map(function(s) { return [s.value, s]; }));\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('cau_hoi');\\n  ctx.resource.setFilter({ is_deleted: { $ne: true } });\\n  ctx.resource.setAppends(['nganh_nghe', 'bac_tho']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(500);\\n  await ctx.resource.refresh();\\n  var initialQuestions = ctx.resource.getData() || [];\\n\\n  var nganhNgheRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialNganhNghe = [];\\n  if (nganhNgheRes) {\\n    nganhNgheRes.setResourceName('nganh_nghe');\\n    nganhNgheRes.setSort(['ten_nganh']);\\n    nganhNgheRes.setPageSize(200);\\n    await nganhNgheRes.refresh();\\n    initialNganhNghe = nganhNgheRes.getData() || [];\\n  }\\n\\n  async function fetchQuestions() {\\n    var res = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (!res) return initialQuestions;\\n    res.setResourceName('cau_hoi');\\n    res.setFilter({ is_deleted: { $ne: true } });\\n    res.setAppends(['nganh_nghe', 'bac_tho']);\\n    res.setSort(['-createdAt']);\\n    res.setPageSize(500);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  function QuestionBankApp(props) {\\n    var [questions, setQuestions] = useState(props.initialQuestions);\\n    var [nganhNgheList] = useState(props.initialNganhNghe);\\n    var [loading, setLoading] = useState(false);\\n    var [searchText, setSearchText] = useState('');\\n    var [filterHinhThuc, setFilterHinhThuc] = useState(undefined);\\n    var [filterMucDo, setFilterMucDo] = useState(undefined);\\n    var [filterTrangThai, setFilterTrangThai] = useState(undefined);\\n    var [filterNganhNghe, setFilterNganhNghe] = useState(undefined);\\n    var [activeTab, setActiveTab] = useState('all');\\n    var [drawerOpen, setDrawerOpen] = useState(false);\\n    var [editRecord, setEditRecord] = useState(null);\\n    var [viewRecord, setViewRecord] = useState(null);\\n    var [formValues, setFormValues] = useState({});\\n    var [saving, setSaving] = useState(false);\\n    var [tnOptions, setTnOptions] = useState(['', '', '', '']);\\n    var [tnCorrect, setTnCorrect] = useState(0);\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var data = await fetchQuestions();\\n        setQuestions(data);\\n      } catch (e) {\\n        ctx.message.error('Không tải được dữ liệu: ' + String(e?.message || e));\\n      }\\n      setLoading(false);\\n    }, []);\\n\\n    var filteredQuestions = useMemo(function() {\\n      var list = questions;\\n      if (activeTab === 'approval') {\\n        list = list.filter(function(q) { return q.trang_thai === 'cho_phe_duyet'; });\\n      }\\n      if (filterHinhThuc) {\\n        list = list.filter(function(q) { return q.hinh_thuc === filterHinhThuc; });\\n      }\\n      if (filterMucDo) {\\n        list = list.filter(function(q) { return q.muc_do_kho === filterMucDo; });\\n      }\\n      if (filterTrangThai) {\\n        list = list.filter(function(q) { return q.trang_thai === filterTrangThai; });\\n      }\\n      if (filterNganhNghe) {\\n        list = list.filter(function(q) { return q.nganh_nghe?.id === filterNganhNghe; });\\n      }\\n      if (searchText) {\\n        var s = searchText.toLowerCase();\\n        list = list.filter(function(q) {\\n          return (q.ma_cau_hoi || '').toLowerCase().includes(s) ||\\n            (q.ten_cau_hoi || '').toLowerCase().includes(s) ||\\n            (q.noi_dung || '').toLowerCase().includes(s) ||\\n            (q.chu_de || '').toLowerCase().includes(s);\\n        });\\n      }\\n      return list;\\n    }, [questions, activeTab, filterHinhThuc, filterMucDo, filterTrangThai, filterNganhNghe, searchText]);\\n\\n    var stats = useMemo(function() {\\n      var total = questions.length;\\n      var tn = questions.filter(function(q) { return q.hinh_thuc === 'trac_nghiem'; }).length;\\n      var tl = questions.filter(function(q) { return q.hinh_thuc === 'tu_luan'; }).length;\\n      var approved = questions.filter(function(q) { return q.trang_thai === 'da_phe_duyet'; }).length;\\n      var pending = questions.filter(function(q) { return q.trang_thai === 'cho_phe_duyet'; }).length;\\n      return { total: total, tn: tn, tl: tl, approved: approved, pending: pending };\\n    }, [questions]);\\n\\n    var parseTnOptions = useCallback(function(dapAn) {\\n      if (!dapAn) return ['', '', '', ''];\\n      return dapAn.split(';').map(function(s) { return s.trim(); });\\n    }, []);\\n\\n    var findCorrectIndex = useCallback(function(options, dapAnDung) {\\n      if (!dapAnDung) return 0;\\n      for (var i = 0; i < options.length; i++) {\\n        if (options[i] === dapAnDung) return i;\\n      }\\n      return 0;\\n    }, []);\\n\\n    var openCreateDrawer = useCallback(function(type) {\\n      setEditRecord(null);\\n      setFormValues({\\n        hinh_thuc: type || 'trac_nghiem',\\n        muc_do_kho: 'trung_binh',\\n        trang_thai: 'nhap',\\n        nguon_tao: 'thu_cong',\\n      });\\n      setTnOptions(['A. ', 'B. ', 'C. ', 'D. ']);\\n      setTnCorrect(0);\\n      setDrawerOpen(true);\\n    }, []);\\n\\n    var openEditDrawer = useCallback(function(record) {\\n      setEditRecord(record);\\n      setFormValues({\\n        ma_cau_hoi: record.ma_cau_hoi,\\n        ten_cau_hoi: record.ten_cau_hoi,\\n        noi_dung: record.noi_dung,\\n        hinh_thuc: record.hinh_thuc,\\n        muc_do_kho: record.muc_do_kho,\\n        trang_thai: record.trang_thai,\\n        nguon_tao: record.nguon_tao,\\n        chu_de: record.chu_de,\\n        giai_thich: record.giai_thich,\\n        nganhNgheId: record.nganhNgheId || record.nganh_nghe?.id,\\n        dap_an: record.dap_an,\\n        dap_an_dung: record.dap_an_dung,\\n      });\\n      if (record.hinh_thuc === 'trac_nghiem') {\\n        var opts = parseTnOptions(record.dap_an);\\n        while (opts.length < 4) opts.push('');\\n        setTnOptions(opts);\\n        setTnCorrect(findCorrectIndex(opts, record.dap_an_dung));\\n    