y1sgkxhzcux	y1sgkxhzcux	{"parentId":"6kuw9bwnq7l","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Badge, Button, Card, Checkbox, Col, Descriptions, Divider, Drawer, Empty, Form, Input, InputNumber, Modal, Popconfirm, Row, Select, Space, Statistic, Table, Tabs, Tag, Tooltip, Typography } = ctx.libs.antd;\\nconst { CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, CopyOutlined, DeleteOutlined, EditOutlined, EyeOutlined, FileTextOutlined, OrderedListOutlined, PlusOutlined, ReloadOutlined, SearchOutlined } = ctx.libs.antdIcons;\\nconst { useState, useMemo, useCallback } = ctx.libs.React;\\n\\nvar TRANG_THAI_DT = [\\n  { value: 'nhap', label: 'Nháp', color: 'default' },\\n  { value: 'cho_phe_duyet', label: 'Chờ phê duyệt', color: 'processing' },\\n  { value: 'da_phe_duyet', label: 'Đã phê duyệt', color: 'success' },\\n  { value: 'tu_choi', label: 'Từ chối', color: 'error' },\\n];\\nvar TRANG_THAI_DT_MAP = Object.fromEntries(TRANG_THAI_DT.map(function(s) { return [s.value, s]; }));\\n\\nvar HINH_THUC_MAP = {\\n  trac_nghiem: { label: 'TN', color: 'blue' },\\n  tu_luan: { label: 'TL', color: 'orange' },\\n};\\n\\nvar MUC_DO_MAP = {\\n  de: { label: 'Dễ', color: 'green' },\\n  trung_binh: { label: 'TB', color: 'gold' },\\n  kho: { label: 'Khó', color: 'red' },\\n};\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('de_thi');\\n  ctx.resource.setFilter({ is_deleted: { $ne: true } });\\n  ctx.resource.setAppends(['cau_hoi', 'nganh_nghe', 'bac_tho']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(200);\\n  await ctx.resource.refresh();\\n  var initialExams = ctx.resource.getData() || [];\\n\\n  var chRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialCauHoi = [];\\n  if (chRes) {\\n    chRes.setResourceName('cau_hoi');\\n    chRes.setFilter({ is_deleted: { $ne: true }, trang_thai: 'da_phe_duyet' });\\n    chRes.setAppends(['nganh_nghe']);\\n    chRes.setSort(['ma_cau_hoi']);\\n    chRes.setPageSize(500);\\n    await chRes.refresh();\\n    initialCauHoi = chRes.getData() || [];\\n  }\\n\\n  var nganhRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialNganhNghe = [];\\n  if (nganhRes) {\\n    nganhRes.setResourceName('nganh_nghe');\\n    nganhRes.setSort(['ten_nganh']);\\n    nganhRes.setPageSize(200);\\n    await nganhRes.refresh();\\n    initialNganhNghe = nganhRes.getData() || [];\\n  }\\n\\n  async function fetchExams() {\\n    var res = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (!res) return initialExams;\\n    res.setResourceName('de_thi');\\n    res.setFilter({ is_deleted: { $ne: true } });\\n    res.setAppends(['cau_hoi', 'nganh_nghe', 'bac_tho']);\\n    res.setSort(['-createdAt']);\\n    res.setPageSize(200);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  async function fetchApprovedQuestions() {\\n    var res = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (!res) return initialCauHoi;\\n    res.setResourceName('cau_hoi');\\n    res.setFilter({ is_deleted: { $ne: true }, trang_thai: 'da_phe_duyet' });\\n    res.setAppends(['nganh_nghe']);\\n    res.setSort(['ma_cau_hoi']);\\n    res.setPageSize(500);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  function ExamManagementApp(props) {\\n    var [exams, setExams] = useState(props.initialExams);\\n    var [allQuestions, setAllQuestions] = useState(props.initialCauHoi);\\n    var [nganhNgheList] = useState(props.initialNganhNghe);\\n    var [loading, setLoading] = useState(false);\\n    var [searchText, setSearchText] = useState('');\\n    var [filterTrangThai, setFilterTrangThai] = useState(undefined);\\n    var [filterNganhNghe, setFilterNganhNghe] = useState(undefined);\\n    var [activeTab, setActiveTab] = useState('all');\\n\\n    var [drawerOpen, setDrawerOpen] = useState(false);\\n    var [editRecord, setEditRecord] = useState(null);\\n    var [formValues, setFormValues] = useState({});\\n    var [selectedQuestionIds, setSelectedQuestionIds] = useState([]);\\n    var [saving, setSaving] = useState(false);\\n    var [questionPickerOpen, setQuestionPickerOpen] = useState(false);\\n    var [qPickerSearch, setQPickerSearch] = useState('');\\n    var [qPickerFilterHT, setQPickerFilterHT] = useState(undefined);\\n\\n    var [previewExam, setPreviewExam] = useState(null);\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var data = await fetchExams();\\n        setExams(data);\\n        var qs = await fetchApprovedQuestions();\\n        setAllQuestions(qs);\\n      } catch (e) {\\n        ctx.message.error('Không tải được dữ liệu: ' + String(e?.message || e));\\n      }\\n      setLoading(false);\\n    }, []);\\n\\n    var filteredExams = useMemo(function() {\\n      var list = exams;\\n      if (activeTab === 'approval') {\\n        list = list.filter(function(d) { return d.trang_thai === 'cho_phe_duyet'; });\\n      }\\n      if (filterTrangThai) {\\n        list = list.filter(function(d) { return d.trang_thai === filterTrangThai; });\\n      }\\n      if (filterNganhNghe) {\\n        list = list.filter(function(d) { return d.nganh_nghe?.id === filterNganhNghe; });\\n      }\\n      if (searchText) {\\n        var s = searchText.toLowerCase();\\n        list = list.filter(function(d) {\\n          return (d.ma_de_thi || '').toLowerCase().includes(s) ||\\n            (d.ten_de_thi || '').toLowerCase().includes(s) ||\\n            (d.mo_ta || '').toLowerCase().includes(s);\\n        });\\n      }\\n      return list;\\n    }, [exams, activeTab, filterTrangThai, filterNganhNghe, searchText]);\\n\\n    var stats = useMemo(function() {\\n      var total = exams.length;\\n      var approved = exams.filter(function(d) { return d.trang_thai === 'da_phe_duyet'; }).length;\\n      var pending = exams.filter(function(d) { return d.trang_thai === 'cho_phe_duyet'; }).length;\\n      return { total: total, approved: approved, pending: pending };\\n    }, [exams]);\\n\\n    var openCreateDrawer = useCallback(function() {\\n      setEditRecord(null);\\n      setFormValues({ trang_thai: 'nhap', thoi_gian_lam_bai: 30, diem_dat: 5, phien_ban: 1 });\\n      setSelectedQuestionIds([]);\\n      setDrawerOpen(true);\\n    }, []);\\n\\n    var openEditDrawer = useCallback(function(record) {\\n      setEditRecord(record);\\n      setFormValues({\\n        ma_de_thi: record.ma_de_thi,\\n        ten_de_thi: record.ten_de_thi,\\n        mo_ta: record.mo_ta,\\n        thoi_gian_lam_bai: record.thoi_gian_lam_bai,\\n        diem_dat: record.diem_dat,\\n        phien_ban: record.phien_ban,\\n        trang_thai: record.trang_thai,\\n        nganhNgheId: record.nganhNgheId || record.nganh_nghe?.id,\\n      });\\n      setSelectedQuestionIds((record.cau_hoi || []).map(function(q) { return q.id; }));\\n      setDrawerOpen(true);\\n    }, []);\\n\\n    var handleFormChange = useCallback(function(field, value) {\\n      setFormValues(function(prev) {\\n        var next = Object.assign({}, prev);\\n        next[field] = value;\\n        return next;\\n      });\\n    }, []);\\n\\n    var handleSave = useCallback(async function() {\\n      if (!formValues.ten_de_thi) {\\n        ctx.message.warning('Vui lòng nhập tên đề thi');\\n        return;\\n      }\\n      setSaving(true);\\n      try {\\n        var data = Object.assign({}, formValues);\\n        data.so_cau_hoi = selectedQuestionIds.length;\\n        data.cau_hoi = selectedQuestionIds;\\n        if (editRecord) {\\n          await ctx.request({\\n            url: 'de_thi:update',\\n            method: 'post',\\n            params: { filterByTk: editRecord.id },\\n            data: data,\\n          });\\n          ctx.message.success('Cập nhật đề thi thành