cord) {\\n      try {\\n        await ctx.request({\\n          url: 'de_thi:update',\\n          method: 'post',\\n          params: { filterByTk: record.id },\\n          data: { trang_thai: 'cho_phe_duyet' },\\n        });\\n        ctx.message.success('Đã gửi phê duyệt');\\n        await refreshData();\\n      } catch (e) {\\n        ctx.message.error('Lỗi: ' + String(e?.message || e));\\n      }\\n    }, [refreshData]);\\n\\n    var columns = [\\n      {\\n        title: 'Mã', dataIndex: 'ma_de_thi', width: 100, fixed: 'left',\\n        sorter: function(a, b) { return (a.ma_de_thi || '').localeCompare(b.ma_de_thi || ''); },\\n      },\\n      {\\n        title: 'Tên đề thi', dataIndex: 'ten_de_thi', width: 260, ellipsis: true,\\n        render: function(text, record) {\\n          return ctx.libs.React.createElement('a', {\\n            onClick: function() { setPreviewExam(record); },\\n            style: { cursor: 'pointer' },\\n          }, text);\\n        },\\n      },\\n      {\\n        title: 'Số câu', dataIndex: 'so_cau_hoi', width: 80, align: 'center',\\n        render: function(val, record) {\\n          var actual = (record.cau_hoi || []).length;\\n          return actual;\\n        },\\n      },\\n      {\\n        title: 'Thời gian', dataIndex: 'thoi_gian_lam_bai', width: 100, align: 'center',\\n        render: function(val) { return val ? val + ' phút' : '-'; },\\n      },\\n      {\\n        title: 'Điểm đạt', dataIndex: 'diem_dat', width: 90, align: 'center',\\n      },\\n      {\\n        title: 'Ngành nghề', width: 160, ellipsis: true,\\n        render: function(_, record) { return record.nganh_nghe?.ten_nganh || '-'; },\\n      },\\n      {\\n        title: 'Trạng thái', dataIndex: 'trang_thai', width: 130, align: 'center',\\n        render: function(val) {\\n          var info = TRANG_THAI_DT_MAP[val] || { label: val, color: 'default' };\\n          return ctx.libs.React.createElement(Tag, { color: info.color }, info.label);\\n        },\\n      },\\n      {\\n        title: '', key: 'actions', width: 150, fixed: 'right', align: 'center',\\n        render: function(_, record) {\\n          var buttons = [];\\n          buttons.push(ctx.libs.React.createElement(Tooltip, { key: 'view', title: 'Xem trước' },\\n            ctx.libs.React.createElement(Button, {\\n              type: 'text', icon: ctx.libs.React.createElement(EyeOutlined), size: 'small',\\n              onClick: function() { setPreviewExam(record); },\\n            })\\n          ));\\n          buttons.push(ctx.libs.React.createElement(Tooltip, { key: 'edit', title: 'Sửa' },\\n            ctx.libs.React.createElement(Button, {\\n              type: 'text', icon: ctx.libs.React.createElement(EditOutlined), size: 'small',\\n              onClick: function() { openEditDrawer(record); },\\n            })\\n          ));\\n          if (record.trang_thai === 'nhap' || record.trang_thai === 'tu_choi') {\\n            buttons.push(ctx.libs.React.createElement(Tooltip, { key: 'submit', title: 'Gửi phê duyệt' },\\n              ctx.libs.React.createElement(Button, {\\n                type: 'text', icon: ctx.libs.React.createElement(ClockCircleOutlined), size: 'small',\\n                style: { color: '#1677ff' },\\n                onClick: function() { handleSubmitApproval(record); },\\n              })\\n            ));\\n          }\\n          if (activeTab === 'approval' && record.trang_thai === 'cho_phe_duyet') {\\n            buttons.push(ctx.libs.React.createElement(Tooltip, { key: 'approve', title: 'Phê duyệt' },\\n              ctx.libs.React.createElement(Button, {\\n                type: 'text', icon: ctx.libs.React.createElement(CheckCircleOutlined), size: 'small',\\n                style: { color: '#52c41a' },\\n                onClick: function() { handleApprove(record); },\\n              })\\n            ));\\n            buttons.push(ctx.libs.React.createElement(Popconfirm, {\\n              key: 'reject', title: 'Từ chối đề thi này?',\\n              onConfirm: function() { handleReject(record); },\\n            },\\n              ctx.libs.React.createElement(Tooltip, { title: 'Từ chối' },\\n                ctx.libs.React.createElement(Button, {\\n                  type: 'text', icon: ctx.libs.React.createElement(CloseCircleOutlined), size: 'small',\\n                  danger: true,\\n                })\\n              )\\n            ));\\n          }\\n          if (record.trang_thai !== 'da_phe_duyet') {\\n            buttons.push(ctx.libs.React.createElement(Popconfirm, {\\n              key: 'delete', title: 'Xoá đề thi này?',\\n              onConfirm: function() { handleDelete(record); },\\n            },\\n              ctx.libs.React.createElement(Tooltip, { title: 'Xoá' },\\n                ctx.libs.React.createElement(Button, {\\n                  type: 'text', icon: ctx.libs.React.createElement(DeleteOutlined), size: 'small',\\n                  danger: true,\\n                })\\n              )\\n            ));\\n          }\\n          return ctx.libs.React.createElement(Space, { size: 4 }, buttons);\\n        },\\n      },\\n    ];\\n\\n    var selectedQuestionsInDrawer = useMemo(function() {\\n      return allQuestions.filter(function(q) { return selectedQuestionIds.includes(q.id); });\\n    }, [allQuestions, selectedQuestionIds]);\\n\\n    var filteredPickerQuestions = useMemo(function() {\\n      var list = allQuestions;\\n      if (qPickerFilterHT) {\\n        list = list.filter(function(q) { return q.hinh_thuc === qPickerFilterHT; });\\n      }\\n      if (qPickerSearch) {\\n        var s = qPickerSearch.toLowerCase();\\n        list = list.filter(function(q) {\\n          return (q.ma_cau_hoi || '').toLowerCase().includes(s) ||\\n            (q.ten_cau_hoi || '').toLowerCase().includes(s) ||\\n            (q.chu_de || '').toLowerCase().includes(s);\\n        });\\n      }\\n      return list;\\n    }, [allQuestions, qPickerFilterHT, qPickerSearch]);\\n\\n    var renderQuestionPicker = function() {\\n      var pickerColumns = [\\n        {\\n          title: 'Mã', dataIndex: 'ma_cau_hoi', width: 90,\\n        },\\n        {\\n          title: 'Tên câu hỏi', dataIndex: 'ten_cau_hoi', width: 220, ellipsis: true,\\n        },\\n        {\\n          title: 'Loại', dataIndex: 'hinh_thuc', width: 70, align: 'center',\\n          render: function(val) {\\n            var info = HINH_THUC_MAP[val] || { label: val, color: 'default' };\\n            return ctx.libs.React.createElement(Tag, { color: info.color }, info.label);\\n          },\\n        },\\n        {\\n          title: 'Mức độ', dataIndex: 'muc_do_kho', width: 80, align: 'center',\\n          render: function(val) {\\n            var info = MUC_DO_MAP[val] || { label: val, color: 'default' };\\n            return ctx.libs.React.createElement(Tag, { color: info.color }, info.label);\\n          },\\n        },\\n        {\\n          title: 'Chủ đề', dataIndex: 'chu_de', width: 120, ellipsis: true,\\n        },\\n      ];\\n\\n      return ctx.libs.React.createElement(Modal, {\\n        title: 'Chọn câu hỏi', open: questionPickerOpen, width: 800,\\n        onCancel: function() { setQuestionPickerOpen(false); },\\n        onOk: function() { setQuestionPickerOpen(false); },\\n        okText: 'Xong (' + selectedQuestionIds.length + ' câu)',\\n      },\\n        ctx.libs.React.createElement(Space, { style: { marginBottom: 12 }, wrap: true },\\n          ctx.libs.React.createElement(Input, {\\n            placeholder: 'Tìm câu hỏi...',\\n            prefix: ctx.libs.React.createElement(SearchOutlined),\\n            value: qPickerSearch, onChange: function(e) { setQPickerSearch(e.target.value); },\\n            style: { width: 220 }, allowClear: true,\\n          }),\\n          ctx.libs.React.createElement(Select, {\\n            placeholder: 'Hình thức', allowClear: true, value: qPickerFilterHT,\\n            onChange: setQPickerFilterHT, style: { width: 130 },\\n            options: [{ value: 'trac_nghiem', label: 'Trắc nghiệm' }, { value: 'tu_luan', label: 'Tự luận' }],\\n          })\\n        ),\\n        ctx.libs.React.createElement(Table, {\\n          dataSource: filteredPickerQuestions, columns: pickerColumns,\\n          rowKey: 'id', size: 'small', scroll: { y: 400 },\\n          pagination: { pageSize: 50, showSizeChanger: false },\\n          rowSelection: {\\n            selectedRowKeys: selectedQuestionIds,\\n            onChange: function(keys) { setSelectedQuestionIds(keys); },\\n          },\\n        })\\n      );\\n    };\\n\\n    var renderFormDrawer = function() {\\n      return ctx.libs.React.createElement(Drawer, {\\n        title: editRecord ? 'Sửa đề thi' : 'Tạo đề thi', open: drawerOpen, width: 720,\\n        onClose: function() { setDrawerOpen(false); },\\n        extra: ctx.libs.React.createElement(Space, null,\\n          ctx.libs.React.createElement(Button, { onClick: function() { setDrawerOpen(false); } }, 'Huỷ'),\\n          ctx.libs.React.createElement(Button, { type: 'primary', loading: saving, onClick: handleSave }, 'Lưu')\\n        ),\\n      },\\n        ctx.libs.React.createElement(Form, { layout: 'vertical' },\\n          ctx.libs.React.createElement(Row, { gutter: 16 },\\n            ctx.libs.React.createElement(Col, { span: 8 },\\n              ctx.libs.React.createElement(Form.Item, { label: 'Mã đề thi' },\\n                ctx.libs.React.createElement(Input, {\\n                  value: formValues.ma_de_thi, placeholder: 'Tự sinh nếu để trống',\\n                  onChange: function(e) { handleFormChange('ma_de_thi', e.target.value); },\\n                })\\n              )\\n            ),\\n            ctx.libs.React.createElement(Col, { span: 8 },\\n              ctx.libs.React.createElement(Form.Item, { label: 'Ngành nghề' },\\n                ctx.libs.React.createElement(Select, {\\n                  value: formValues.nganhNgheId, allowClear: true, showSearch: true,\\n                  filt