),\\n            ctx.libs.React.createElement(Col, { span: 8 },\\n              ctx.libs.React.createElement(Form.Item, { label: 'Điểm đạt' },\\n                ctx.libs.React.createElement(InputNumber, {\\n                  value: formValues.diem_dat, min: 0, max: 10, step: 0.5, style: { width: '100%' },\\n                  onChange: function(v) { handleFormChange('diem_dat', v); },\\n                })\\n              )\\n            ),\\n            ctx.libs.React.createElement(Col, { span: 8 },\\n              ctx.libs.React.createElement(Form.Item, { label: 'Phiên bản' },\\n                ctx.libs.React.createElement(InputNumber, {\\n                  value: formValues.phien_ban, min: 1, style: { width: '100%' },\\n                  onChange: function(v) { handleFormChange('phien_ban', v); },\\n                })\\n              )\\n            )\\n          ),\\n          ctx.libs.React.createElement(Divider, null, 'Câu hỏi trong đề (' + selectedQuestionIds.length + ')'),\\n          ctx.libs.React.createElement(Space, { style: { marginBottom: 12 } },\\n            ctx.libs.React.createElement(Button, {\\n              icon: ctx.libs.React.createElement(PlusOutlined),\\n              onClick: function() { setQuestionPickerOpen(true); },\\n            }, 'Chọn câu hỏi')\\n          ),\\n          selectedQuestionsInDrawer.length > 0 ? ctx.libs.React.createElement(Table, {\\n            dataSource: selectedQuestionsInDrawer, rowKey: 'id', size: 'small',\\n            pagination: false,\\n            columns: [\\n              { title: '#', width: 40, render: function(_, __, idx) { return idx + 1; } },\\n              { title: 'Mã', dataIndex: 'ma_cau_hoi', width: 90 },\\n              { title: 'Tên', dataIndex: 'ten_cau_hoi', ellipsis: true },\\n              {\\n                title: 'Loại', dataIndex: 'hinh_thuc', width: 70, align: 'center',\\n                render: function(val) {\\n                  var info = HINH_THUC_MAP[val] || { label: val, color: 'd