.React.createElement(Descriptions.Item, { label: 'Điểm đạt' }, exam.diem_dat),\\n          ctx.libs.React.createElement(Descriptions.Item, { label: 'Ngành nghề' }, exam.nganh_nghe?.ten_nganh || '-'),\\n          ctx.libs.React.createElement(Descriptions.Item, { label: 'Trạng thái' },\\n            ctx.libs.React.createElement(Tag, { color: (TRANG_THAI_DT_MAP[exam.trang_thai] || {}).color }, (TRANG_THAI_DT_MAP[exam.trang_thai] || {}).label || exam.trang_thai)\\n          )\\n        ),\\n        exam.mo_ta ? ctx.libs.React.createElement(Typography.Paragraph, { type: 'secondary', style: { marginBottom: 16 } }, exam.mo_ta) : null,\\n        ctx.libs.React.createElement(Divider, null, 'Danh sách câu hỏi'),\\n        qs.map(function(q, idx) {\\n          var isTN = q.hinh_thuc === 'trac_nghiem';\\n          var opts = isTN ? (q.dap_an || '').split(';').map(function(s) { return s.trim(); }).filter(Boolean) : [];\\n          return ctx.libs.React.createElement(Card, {\\n            key: q.id, size: 'small', style: { marginBottom: 12 },\\n            title: ctx.libs.React.createElement(Space, null,\\n              ctx.libs.React.createElement(Tag, { color: (HINH_THUC_MAP[q.hinh_thuc] || {}).color }, (HINH_THUC_MAP[q.hinh_thuc] || {}).label),\\n              ctx.libs.React.createElement(Tag, { color: (MUC_DO_MAP[q.muc_do_kho] || {}).color }, (MUC_DO_MAP[q.muc_do_kho] || {}).label),\\n              'Câu ' + (idx + 1) + ': ' + (q.ten_cau_hoi || '')\\n            ),\\n          },\\n            ctx.libs.React.createElement(Typography.Paragraph, null, q.noi_dung),\\n            isTN ? opts.map(function(opt, oi) {\\n              var isCorrect = opt === q.dap_an_dung;\\n              return ctx.libs.React.createElement('div', {\\n                key: oi,\\n                style: { padding: '4px 8px', marginBottom: 4, borderRadius: 4, background: isCorrect ? '#f6ffed' : '#fafafa', border: isCorrect ? '1px solid #b7eb8f' : '1px solid #f0f0f0' },\\n              },\\n                ctx.libs.React.createElement(Space, null,\\n                  isCorrect ? ctx.libs.React.createElement(CheckCircleOutlined, { style: { color: '#52c41a' } }) : null,\\n                  opt\\n                )\\n              );\\n            }) : ctx.libs.React.createElement('div', null,\\n              ctx.libs.React.createElement(Typography.Text, { type: 'secondary' }, 'Hướng dẫn: '),\\n              ctx.libs.React.createElement(Typography.Text, null, q.dap_an || '-')\\n            )\\n          );\\n        }),\\n        qs.length === 0 ? ctx.libs.React.createElement(Empty, { description: 'Đề thi chưa có câu hỏi' }) : null\\n      );\\n    };\\n\\n    var tabItems = [\\n      {\\n        key: 'all',\\n        label: ctx.libs.React.createElement(Space, null,\\n          ctx.libs.React.createElement(FileTextOutlined),\\n          'Tất cả (' + exams.length + ')'\\n        ),\\n      },\\n      {\\n        key: 'approval',\\n        label: ctx.libs.React.createElement(Space, null,\\n          ctx.libs.React.createElement(Badge, { count: stats.pending, size: 'small', offset: [6, 0] },\\n            ctx.libs.React.createElement(ClockCircleOutlined)\\n          ),\\n          'Phê duyệt'\\n        ),\\n      },\\n    ];\\n\\n    return ctx.libs.React.createElement('div', null,\\n      ctx.libs.React.createElement(Row, { gutter: 16, style: { marginBottom: 16 } },\\n        ctx.libs.React.createElement(Col, { span: 6 },\\n          ctx.libs.React.createElement(Card, { size: 'small' },\\n            ctx.libs.React.createElement(Statistic, { title: 'Tổng đề thi', value: stats.total, prefix: ctx.libs.React.createElement(FileTextOutlined) })\\n          )\\n        ),\\n        ctx.libs.React.createElement(Col, { span: 6 },\\n          ctx.libs.React.createElement(Card, { size: 'small' },\\n            ctx.libs.React.createElement(Statistic, { title: 'Đã duyệt', value: stats.approved, valueStyle: { color: '#52c41a' } })\\n          )\\n        ),\\n        ctx.libs.React.cre