7pe7s9gea0d	7pe7s9gea0d	{"parentId":"mx2kcv7fi6x","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Badge, Button, Card, Col, DatePicker, Descriptions, Divider, Drawer, Empty, Form, Input, InputNumber, Modal, Popconfirm, Row, Select, Space, Statistic, Table, Tabs, Tag, Tooltip, Typography } = ctx.libs.antd;\\nconst { CalendarOutlined, CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, DeleteOutlined, EditOutlined, ExclamationCircleOutlined, EyeOutlined, FileTextOutlined, PlusOutlined, ReloadOutlined, SearchOutlined, TeamOutlined, UserOutlined } = ctx.libs.antdIcons;\\nconst { useState, useMemo, useCallback } = ctx.libs.React;\\n\\nvar TRANG_THAI_KT = [\\n  { value: 'nhap', label: 'Nháp', color: 'default' },\\n  { value: 'cho_phe_duyet', label: 'Chờ phê duyệt', color: 'processing' },\\n  { value: 'da_phe_duyet', label: 'Đã phê duyệt', color: 'cyan' },\\n  { value: 'dang_thi', label: 'Đang thi', color: 'blue' },\\n  { value: 'hoan_thanh', label: 'Hoàn thành', color: 'success' },\\n  { value: 'huy', label: 'Đã huỷ', color: 'error' },\\n];\\nvar TRANG_THAI_KT_MAP = Object.fromEntries(TRANG_THAI_KT.map(function(s) { return [s.value, s]; }));\\n\\nvar HINH_THUC_KT = [\\n  { value: 'truc_tiep', label: 'Trực tiếp', color: 'blue' },\\n  { value: 'truc_tuyen', label: 'Trực tuyến', color: 'green' },\\n];\\nvar HINH_THUC_KT_MAP = Object.fromEntries(HINH_THUC_KT.map(function(s) { return [s.value, s]; }));\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('ky_thi');\\n  ctx.resource.setFilter({ is_deleted: { $ne: true } });\\n  ctx.resource.setAppends(['de_thi', 'don_vi', 'lop_hoc', 'thi_sinh', 'thi_sinh.nguoi_lao_dong']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(200);\\n  await ctx.resource.refresh();\\n  var initialExamSessions = ctx.resource.getData() || [];\\n\\n  var dtRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialDeThiList = [];\\n  if (dtRes) {\\n    dtRes.setResourceName('de_thi');\\n    dtRes.setFilter({ is_deleted: { $ne: true }, trang_thai: 'da_phe_duyet' });\\n    dtRes.setSort(['ma_de_thi']);\\n    dtRes.setPageSize(200);\\n    await dtRes.refresh();\\n    initialDeThiList = dtRes.getData() || [];\\n  }\\n\\n  var dvRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialDonViList = [];\\n  if (dvRes) {\\n    dvRes.setResourceName('don_vi');\\n    dvRes.setSort(['ten_don_vi']);\\n    dvRes.setPageSize(200);\\n    await dvRes.refresh();\\n    initialDonViList = dvRes.getData() || [];\\n  }\\n\\n  var nnRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialNganhNghe = [];\\n  if (nnRes) {\\n    nnRes.setResourceName('nganh_nghe');\\n    nnRes.setSort(['ten_nganh']);\\n    nnRes.setPageSize(200);\\n    await nnRes.refresh();\\n    initialNganhNghe = nnRes.getData() || [];\\n  }\\n\\n  async function fetchWaitList() {\\n    var res = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (!res) return [];\\n    res.setResourceName('hang_cho_thi');\\n    res.setFilter({ trang_thai: 'cho_xep' });\\n    res.setAppends(['nguoi_lao_dong']);\\n    res.setPageSize(100);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  async function fetchExamSessions() {\\n    var res = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (!res) return initialExamSessions;\\n    res.setResourceName('ky_thi');\\n    res.setFilter({ is_deleted: { $ne: true } });\\n    res.setAppends(['de_thi', 'don_vi', 'lop_hoc', 'thi_sinh', 'thi_sinh.nguoi_lao_dong']);\\n    res.setSort(['-createdAt']);\\n    res.setPageSize(200);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  function formatDateTime(val) {\\n    if (!val) return '-';\\n    try {\\n      var d = new Date(val);\\n      if (isNaN(d.getTime())) return val;\\n      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear() + ' ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');\\n    } catch (e) { return val; }\\n  }\\n\\n  function formatDate(val) {\\n    if (!val) return '-';\\n    try {\\n      var d = new Date(val);\\n      if (isNaN(d.getTime())) return val;\\n      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();\\n    } catch (e) { return val; }\\n  }\\n\\n  function ExamSessionApp(props) {\\n    var [sessions, setSessions] = useState(props.initialSessions);\\n    var [deThiList] = useState(props.initialDeThiList);\\n    var [donViList] = useState(props.initialDonViList);\\n    var [nganhNgheList] = useState(props.initialNganhNghe);\\n    var [loading, setLoading] = useState(false);\\n    var [searchText, setSearchText] = useState('');\\n    var [filterTrangThai, setFilterTrangThai] = useState(undefined);\\n    var [filterHinhThuc, setFilterHinhThuc] = useState(undefined);\\n\\n    var [drawerOpen, setDrawerOpen] = useState(false);\\n    var [editRecord, setEditRecord] = useState(null);\\n    var [formValues, setFormValues] = useState({});\\n    var [saving, setSaving] = useState(false);\\n\\n    var [detailRecord, setDetailRecord] = useState(null);\\n    var [candidateModalOpen, setCandidateModalOpen] = useState(false);\\n    var [candidateSession, setCandidateSession] = useState(null);\\n    var [genLoading, setGenLoading] = useState(false);\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var data = await fetchExamSessions();\\n        setSessions(data);\\n      } catch (e) {\\n        ctx.message.error('Không tải được dữ liệu: ' + String(e?.message || e));\\n      }\\n      setLoading(false);\\n    }, []);\\n\\n    var filteredSessions = useMemo(function() {\\n      var list = sessions;\\n      if (filterTrangThai) {\\n        list = list.filter(function(s) { return s.trang_thai === filterTrangThai; });\\n      }\\n      if (filterHinhThuc) {\\n        list = list.filter(function(s) { return s.hinh_thuc === filterHinhThuc; });\\n      }\\n      if (searchText) {\\n        var s = searchText.toLowerCase();\\n        list = list.filter(function(item) {\\n          return (item.ma_ky_thi || '').toLowerCase().includes(s) ||\\n            (item.ten_ky_thi || '').toLowerCase().includes(s) ||\\n            (item.de_thi?.ten_de_thi || '').toLowerCase().includes(s) ||\\n            (item.don_vi?.ten_don_vi || '').toLowerCase().includes(s);\\n        });\\n      }\\n      return list;\\n    }, [sessions, filterTrangThai, filterHinhThuc, searchText]);\\n\\n    var stats = useMemo(function() {\\n      var total = sessions.length;\\n      var approved = sessions.filter(function(s) { return s.trang_thai === 'da_phe_duyet'; }).length;\\n      var ongoing = sessions.filter(function(s) { return s.trang_thai === 'dang_thi'; }).length;\\n      var done = sessions.filter(function(s) { return s.trang_thai === 'hoan_thanh'; }).length;\\n      return { total: total, approved: approved, ongoing: ongoing, done: done };\\n    }, [sessions]);\\n\\n    var openCreateDrawer = useCallback(function() {\\n      setEditRecord(null);\\n      setFormValues({\\n        hinh_thuc: 'truc_tiep',\\n        trang_thai: 'nhap',\\n        diem_dat: 5,\\n        ca_thi: '1',\\n        so_thi_sinh: 0,\\n        suc_chua: 30,\\n        muc_uu_tien: 0,\\n      });\\n      setDrawerOpen(true);\\n    }, []);\\n\\n    var openEditDrawer = useCallback(function(record) {\\n      setEditRecord(record);\\n      setFormValues({\\n        ma_ky_thi: record.ma_ky_thi,\\n        ten_ky_thi: record.ten_ky_thi,\\n        hinh_thuc: record.hinh_thuc,\\n        trang_thai: record.trang_thai,\\n        de_thi_id: record.de_thi_id,\\n        don_vi_id: record.don_vi_id,\\n        nganh_nghe_id: record.nganh_nghe_id,\\n        thoi_gian_bat_dau: record.thoi_gian_bat_dau,\\n        thoi_gian_ket_thuc: record.thoi_gian_ket_thuc,\\n        ca_thi: record.ca_thi,\\n        diem_dat: record.diem_dat,\\n        so_thi_sinh: record.so_thi_sinh,\\n        suc_chua: record.suc_chua,\\n        muc_uu_tien: record.muc_uu_tien,\\n        quy_che_thi: record.quy_che_thi,\\n      });\\n      setDrawerOpen(true);\\n    }, []);\\n\\n    var handleFormChange = useCallback(function(field, value) {\\n      setFormValues(function(prev) {\\n        var next = Object.assign({}, prev);\\n        next[field] = value;\\n        return next;\\n      });\\n    }, []);\\n\\n    var handleSave = useCallback(async function() {\\n      if (!formValues.ten_ky_thi) {\\n        ctx.message.warning('Vui lòng nhập tên kỳ thi');\\n        return;\\n      }\\n      setSaving(true);\\n      try {\\n        var data = Object.assign({}, formValues);\\n        if (editRecord) {\\n          await ctx.request({\\n            url: 'ky_thi:update',\\n            method: 'post',\\n            params: { filterByTk: editRecord.id },\\n            data: data,\\n          });\\n          ctx.message.success('Cập nhật kỳ thi thành công');\\n        } else {\\n          await ctx.request({\\n            url: 'ky_thi:create',\\n            method: 'post',\\n            data: data,\\n          });\\n          ctx.message.success('Tạo kỳ thi thành công');\\n        }\\n        setDrawerOpen(false);\\n        await refreshData();\\n      } catch (e) {\\n        ctx.message.error('Lỗi: ' + String(e?.message || e));\\n      }\\n      setSaving(false);\\n    }, [formValues, editRecord, refreshData]);\\n\\n    var handleDelete = useCallback(async function(record) {\\n      try {\\n        await ctx.request({\\n          url: 'ky_thi:update',\\n          method: 'post',\\n          params: { filterByTk: record.id },\\n          data: { is_deleted: true },\\n        });\\n        ctx.message.su