jpdeslixhdo	jpdeslixhdo	{"parentId":"gr59sq49rlt","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const React = ctx.libs.React;\\nconst { Spin, Alert, Button, Space, Typography, Empty } = ctx.libs.antd;\\nconst { FileExcelOutlined, FilePdfOutlined, FileWordOutlined, DownloadOutlined, ExpandOutlined } = ctx.libs.antdIcons;\\n\\nfunction DocViewer() {\\n  const [state, setState] = React.useState({ loading: true, file: null, error: null, htmlContent: null, pdfBlobUrl: null, isDocx: false });\\n  const dlRef = React.useRef(null);\\n  const docxContainerRef = React.useRef(null);\\n\\n  const loadFile = async () => {\\n    setState(s => ({ ...s, loading: true, error: null }));\\n    try {\\n      const pathParts = window.location.pathname.split('/');\\n      const fbtIdx = pathParts.indexOf('filterbytk');\\n      const recordId = fbtIdx >= 0 ? pathParts[fbtIdx + 1] : null;\\n      if (!recordId) { setState({ loading: false, file: null, error: 'Không tìm thấy mã bản ghi trong đường dẫn.', htmlContent: null, pdfBlobUrl: null, isDocx: false }); return; }\\n      const res = await fetch('/api/tai_lieu_huan_luyen:get?filterByTk=' + recordId + '&appends[]=tep_tai_lieu', { credentials: 'include' });\\n      const data = await res.json();\\n      const files = data && data.data && data.data.tep_tai_lieu;\\n      if (!files || !files.length) { setState({ loading: false, file: null, error: 'Tài liệu chưa có tệp đính kèm.', htmlContent: null, pdfBlobUrl: null, isDocx: false }); return; }\\n      const file = files[0];\\n      const ext = (file.extname || '').toLowerCase();\\n\\n      if (ext === '.pdf') {\\n        const fileRes = await fetch(file.url, { credentials: 'include' });\\n        if (!fileRes.ok) throw new Error('Không tải được tệp PDF (mã lỗi: ' + fileRes.status + ')');\\n        const blob = await fileRes.blob();\\n        const blobUrl = URL.createObjectURL(new Blob([blob], { type: 'application/pdf' }));\\n        setState({ loading: false, file, error: null, htmlContent: null, pdfBlobUrl: blobUrl, isDocx: false });\\n      } else if (ext === '.xlsx' || ext === '.xls') {\\n        const fileRes = await fetch(file.url, { credentials: 'include' });\\n        if (!fileRes.ok) throw new Error('Không tải được tệp Excel (mã lỗi: ' + fileRes.status + ')');\\n        const buf = await fileRes.arrayBuffer();\\n        const xlsxMod = await ctx.importAsync('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/+esm');\\n        const XLSX = xlsxMod.default || xlsxMod;\\n        const wb = XLSX.read(buf, { type: 'array' });\\n        const ws = wb.Sheets[wb.SheetNames[0]];\\n        const html = XLSX.utils.sheet_to_html(ws, { editable: false });\\n        setState({ loading: false, file, error: null, htmlContent: html, pdfBlobUrl: null, isDocx: false });\\n      } else if (ext === '.docx') {\\n        const fileRes = await fetch(file.url, { credentials: 'include' });\\n        if (!fileRes.ok) throw new Error('Không tải được tệp Word (mã lỗi: ' + fileRes.status + ')');\\n        const buf = await fileRes.arrayBuffer();\\n        setState({ loading: false, file, error: null, htmlContent: null, pdfBlobUrl: null, isDocx: true, docxData: buf });\\n      } else if (ext === '.doc') {\\n        setState({ loading: false, file, error: 'Định dạng .doc (Word cũ) chưa hỗ trợ xem trực tiếp. Vui lòng tải xuống để xem.', htmlContent: null, pdfBlobUrl: null, isDocx: false });\\n      } else {\\n        setState({ loading: false, file, error: null, htmlContent: null, pdfBlobUrl: null, isDocx: false });\\n      }\\n    } catch (err) {\\n      setState({ loading: false, file: null, error: 'Lỗi tải tài liệu: ' + (err.message || String(err)), htmlContent: null, pdfBlobUrl: null, isDocx: false });\\n    }\\n  };\\n\\n  React.useEffect(function() { loadFile(); }, []);\\n\\n  React.useEffect(function() {\\n    var url = state.pdfBlobUrl;\\n    return function() {\\n      if (url) URL.revokeObjectURL(url);\\n    };\\n  }, [state.pdfBlobUrl]);\\n\\n  React.useEffect(function() {\\n    if (!state.isDocx || !state.docxData || !docxContainerRef.current) return;\\n    var cancelled = false;\\n    (async function() {\\n      try {\\n        var docxPreview = await ctx.importAsync('https://cdn.jsdelivr.net/npm/docx-preview@0.3.3/+esm');\\n        var renderFn = docxPreview.renderAsync || (docxPreview.default && docxPreview.default.renderAsync);\\n        if (!renderFn) throw new Error('Thư viện docx-preview không có hàm renderAsync');\\n        if (cancelled) return;\\n        await renderFn(state.docxData, docxContainerRef.current, null, {\\n          className: 'docx-viewer',\\n          inWrapper: true,\\n          ignoreWidth: false,\\n          ignoreHeight: false,\\n          ignoreFonts: false,\\n          breakPages: true,\\n          ignoreLastRenderedPageBreak: true,\\n          experimental: false,\\n          useBase64URL: true\\n        });\\n      } catch (err) {\\n        if (!cancelled) {\\n          setState(function(s) { return { ...s, error: 'Lỗi hiển thị tài liệu Word: ' + (err.message || String(err)), isDocx: false }; });\\n        }\\n      }\\n    })();\\n    return function() { cancelled = true; };\\n  }, [state.isDocx, state.docxData]);\\n\\n  if (state.loading) return (<div style={{ textAlign: 'center', padding: 60 }}><Spin size=\\"large\\" /><div style={{ marginTop: 12 }}>Đang tải tài liệu...</div></div>);\\n  if (state.error && !state.file) return (<Alert type=\\"error\\" message=\\"Lỗi\\" description={state.error} showIcon />);\\n  if (!state.file) return (<Empty description=\\"Không có tệp tài liệu\\" />);\\n\\n  var file = state.file;\\n  var ext = (file.extname || '').toLowerCase();\\n\\n  var fileIcon = null;\\n  if (ext === '.pdf') fileIcon = <FilePdfOutlined style={{ fontSize: 20, color: '#cf1322' }} />;\\n  else if (ext === '.xlsx' || ext === '.xls') fileIcon = <FileExcelOutlined style={{ fontSize: 20, color: '#389e0d' }} />;\\n  else if (ext === '.docx' || ext === '.doc') fileIcon = <FileWordOutlined style={{ fontSize: 20, color: '#1677ff' }} />;\\n\\n  return (\\n    <div>\\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, padding: '0 4px' }}>\\n        <Space>{fileIcon}<Typography.Text strong>{file.title || file.filename}</Typography.Text><Typography.Text type=\\"secondary\\">({(file.size / 1024).toFixed(1)} KB)</Typography.Text></Space>\\n        <Space>\\n          <Button icon={<ExpandOutlined />} onClick={() => window.open(file.url, '_blank')}>Mở tab mới</Button>\\n          <a ref={dlRef} href={file.url} download={file.filename} style={{ display: 'none' }} />\\n          <Button icon={<DownloadOutlined />} onClick={() => dlRef.current && dlRef.current.click()}>Tải xuống</Button>\\n        </Space>\\n      </div>\\n      {ext === '.pdf' && state.pdfBlobUrl && (<iframe src={state.pdfBlobUrl} style={{ width: '100%', height: '78vh', border: '1px solid #d9d9d9', borderRadius: 6 }} />)}\\n      {state.htmlContent && (<div style={{ border: '1px solid #d9d9d9', borderRadius: 6, padding: 16, maxHeight: '78vh', overflow: 'auto', background: '#fff' }} dangerouslySetInnerHTML={{ __html: state.htmlContent }} />)}\\n      {state.isDocx && (<div ref={docxContainerRef} style={{ border: '1px solid #d9d9d9', borderRadius: 6, maxHeight: '78vh', overflow: 'auto', background: '#fff' }} />)}\\n      {state.error && state.file && (<Alert type=\\"warning\\" message={state.error} showIcon style={{ marginTop: 8 }} />)}\\n      {!state.htmlContent && !state.pdfBlobUrl && !state.isDocx && !state.error && ext !== '.pdf' && (<div style={{ textAlign: 'center', padding: 40 }}><Typography.Text type=\\"secondary\\">Định dạng {ext} không hỗ trợ xem trực tiếp. Vui lòng tải xuống hoặc mở trong tab mới.</Typography.Text></div>)}\\n    </div>\\n  );\\n}\\n\\nctx.render(<DocViewer />);\\n"}}}}
