wjpuxmk03sl	wjpuxmk03sl	{"use": "JSBlockModel", "props": {}, "subKey": "items", "subType": "array", "parentId": "8j8rbonn7is", "stepParams": {"jsSettings": {"runJs": {"code": "// ============================================================\\n// JS Block: Quản lý Bậc thợ theo Ngành nghề\\n// ============================================================\\n\\nconst {\\n  Table, Card, Button, Space, Tag, Tabs, Modal, Form,\\n  Input, InputNumber, Select, Tooltip, Popconfirm, Typography,\\n  Divider, Empty, Spin, Switch, Row, Col, Badge\\n} = ctx.libs.antd;\\nconst {\\n  PlusOutlined, EditOutlined, DeleteOutlined, ReloadOutlined,\\n  ArrowUpOutlined, CheckCircleOutlined, StopOutlined,\\n  OrderedListOutlined, FileTextOutlined, LinkOutlined,\\n  DisconnectOutlined, CopyOutlined\\n} = ctx.libs.antdIcons;\\nconst React = ctx.libs.React;\\nconst { useState, useCallback, useMemo, useEffect } = React;\\n\\n// === TOP-LEVEL DATA FETCH ===\\n\\nasync function fetchNganhNghe() {\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('nganh_nghe');\\n  r.setSort(['ma_nganh']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function fetchBacTho() {\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('bac_tho');\\n  r.setAppends(['nganh_nghe_truc_thuoc', 'bacKeTiep']);\\n  r.setSort(['nganhNgheTrucThuocId', 'thu_tu']);\\n  r.setPageSize(500);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nvar initialNganhNghe = await fetchNganhNghe();\\nvar initialBacTho = await fetchBacTho();\\n\\n// === DIEU KIEN MODAL COMPONENT ===\\n\\nfunction DieuKienModal({ open, onClose, record, bacThoList }) {\\n  var [activeTab, setActiveTab] = useState('khoa');\\n  var [loading, setLoading] = useState(false);\\n  var [khoaList, setKhoaList] = useState([]);\\n  var [deThiList, setDeThiList] = useState([]);\\n  var [allKhoa, setAllKhoa] = useState([]);\\n  var [allDeThi, setAllDeThi] = useState([]);\\n  var [selectedKhoa, setSelectedKhoa] = useState(undefined);\\n  var [selectedDeThi, setSelectedDeThi] = useState(undefined);\\n\\n  var loadData = useCallback(async function() {\\n    if (!record) return;\\n    setLoading(true);\\n    try {\\n      var khoaRes = await ctx.request({\\n        url: 'khoa_huan_luyen:list',\\n        params: { filter: { bacThoId: record.id }, pageSize: 200 }\\n      });\\n      var linked = (khoaRes && khoaRes.data && khoaRes.data.data) || (khoaRes && khoaRes.data) || [];\\n      if (Array.isArray(linked)) setKhoaList(linked);\\n      else if (linked.data) setKhoaList(linked.data);\\n      else setKhoaList([]);\\n\\n      var deRes = await ctx.request({\\n        url: 'de_thi:list',\\n        params: { filter: { bacThoId: record.id }, pageSize: 200 }\\n      });\\n      var linkedDt = (deRes && deRes.data && deRes.data.data) || (deRes && deRes.data) || [];\\n      if (Array.isArray(linkedDt)) setDeThiList(linkedDt);\\n      else if (linkedDt.data) setDeThiList(linkedDt.data);\\n      else setDeThiList([]);\\n\\n      var allKhoaRes = await ctx.request({\\n        url: 'khoa_huan_luyen:list',\\n        params: { filter: { $or: [{ bacThoId: { $empty: true } }] }, pageSize: 500 }\\n      });\\n      var ak = (allKhoaRes && allKhoaRes.data && allKhoaRes.data.data) || (allKhoaRes && allKhoaRes.data) || [];\\n      if (Array.isArray(ak)) setAllKhoa(ak);\\n      else if (ak.data) setAllKhoa(ak.data);\\n      else setAllKhoa([]);\\n\\n      var allDeRes = await ctx.request({\\n        url: 'de_thi:list',\\n        params: { filter: { $or: [{ bacThoId: { $empty: true } }] }, pageSize: 500 }\\n      });\\n      var ad = (allDeRes && allDeRes.data && allDeRes.data.data) || (allDeRes && allDeRes.data) || [];\\n      if (Array.isArray(ad)) setAllDeThi(ad);\\n      else if (ad.data) setAllDeThi(ad.data);\\n      else setAllDeThi([]);\\n    } catch (e) {\\n      ctx.message.error('Lỗi tải điều kiện: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [record]);\\n\\n  useEffect(function() {\\n    if (open && record) {\\n      setActiveTab('khoa');\\n      setSelectedKhoa(undefined);\\n      setSelectedDeThi(undefined);\\n      loadData();\\n    }\\n  }, [open, record]);\\n\\n  var handleLinkKhoa = useCallback(async function() {\\n    if (!selectedKhoa) return;\\n    setLoading(true);\\n    try {\\n      await ctx.request({\\n        url: 'khoa_huan_luyen:update',\\n        method: 'post',\\n        params: { filterByTk: selectedKhoa },\\n        data: { bacThoId: record.id }\\n      });\\n      ctx.message.success('Đã gắn khóa huấn luyện');\\n      setSelectedKhoa(undefined);\\n      await loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [selectedKhoa, record, loadData]);\\n\\n  var handleUnlinkKhoa = useCallback(async function(khoaId) {\\n    setLoading(true);\\n    try {\\n      await ctx.request({\\n        url: 'khoa_huan_luyen:update',\\n        method: 'post',\\n        params: { filterByTk: khoaId },\\n        data: { bacThoId: null }\\n      });\\n      ctx.message.success('Đã gỡ khóa huấn luyện');\\n      await loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [record, loadData]);\\n\\n  var handleLinkDeThi = useCallback(async function() {\\n    if (!selectedDeThi) return;\\n    setLoading(true);\\n    try {\\n      await ctx.request({\\n        url: 'de_thi:update',\\n        method: 'post',\\n        params: { filterByTk: selectedDeThi },\\n        data: { bacThoId: record.id }\\n      });\\n      ctx.message.success('Đã gắn đề thi');\\n      setSelectedDeThi(undefined);\\n      await loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [selectedDeThi, record, loadData]);\\n\\n  var handleUnlinkDeThi = useCallback(async function(deThiId) {\\n    setLoading(true);\\n    try {\\n      await ctx.request({\\n        url: 'de_thi:update',\\n        method: 'post',\\n        params: { filterByTk: deThiId },\\n        data: { bacThoId: null }\\n      });\\n      ctx.message.success('Đã gỡ đề thi');\\n      await loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [record, loadData]);\\n\\n  var khoaOptions = useMemo(function() {\\n    return allKhoa.map(function(k) {\\n      return { label: (k.ma_khoa_hoc || '') + ' — ' + (k.ten_khoa_hoc || ''), value: k.id };\\n    });\\n  }, [allKhoa]);\\n\\n  var deThiOptions = useMemo(function() {\\n    return allDeThi.map(function(d) {\\n      return { label: (d.ma_de_thi || '') + ' — ' + (d.ten_de_thi || ''), value: d.id };\\n    });\\n  }, [allDeThi]);\\n\\n  var khoaColumns = [\\n    { title: 'Mã khóa', dataIndex: 'ma_khoa_hoc', key: 'ma', width: 120 },\\n    { title: 'Tên khóa huấn luyện', dataIndex: 'ten_khoa_hoc', key: 'ten', ellipsis: true },\\n    {\\n      title: 'Thời lượng',\\n      dataIndex: 'thoi_luong_gio',\\n      key: 'tl',\\n      width: 100,\\n      render: function(v) { return v ? v + ' giờ' : '-'; }\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      key: 'tt',\\n      width: 120,\\n      render: function(v) {\\n        var map = { da_phe_duyet: { color: 'success', text: 'Đã duyệt' }, nhap: { color: 'default', text: 'Nháp' }, cho_phe_duyet: { color: 'warning', text: 'Chờ duyệt' } };\\n        var info = map[v] || { color: 'default', text: v || '-' };\\n        return React.createElement(Tag, { color: info.color }, info.text);\\n      }\\n    },\\n    {\\n      title: '',\\n      key: 'act',\\n      width: 50,\\n      render: function(_, rec) {\\n        return React.createElement(Tooltip, { title: 'Gỡ khóa' },\\n          React.createElement(Button, {\\n            size: 'small',\\n            danger: true,\\n            icon: React.createElement(DisconnectOutlined, null),\\n            onClick: function() { handleUnlinkKhoa(rec.id); }\\n          })\\n        );\\n      }\\n    }\\n  ];\\n\\n  var deThiColumns = [\\n    { title: 'Mã đề', dataIndex: 'ma_de_thi', key: 'ma', width: 100 },\\n    { title: 'Tên đề thi', dataIndex: 'ten_de_thi', key: 'ten', ellipsis: true },\\n    {\\n      title: 'Số câu hỏi',\\n      dataIndex: 'so_cau_hoi',\\n      key: 'sc',\\n      width: 100,\\n      render: function(v) { return v || '-'; }\\n    },\\n    {\\n      title: 'Điểm đạt',\\n      dataIndex: 'diem_dat',\\n      key: 'dd',\\n      width: 90,\\n      render: function(v) { return v != null ? v : '-'; }\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      key: 'tt',\\n      width: 120,\\n      render: function(v) {\\n        var map = { da_phe_duyet: { color: 'success', text: 'Đã duyệt' }, nhap: { color: 'default', text: 'Nháp' }, cho_phe_duyet: { color: 'warning', text: 'Chờ duyệt' } };\\n        var info = map[v] || { color: 'default', text: v || '-' };\\n        return React.createElement(Tag, { color: info.color }, info.text);\\n      }\\n    },\\n    {\\n      title: '',\\n      key: 'act',\\n      width: 50,\\n      render: function(_, rec) {\\n        return React.createElement(Tooltip, { title: 'Gỡ đề thi' },\\n          React.createElement(Button, {\\n            size: 'small',\\n            danger: true,\\n            icon: React.createElement(DisconnectOutlined, null),\\n            onClick: function() { handleUnlinkDeThi(rec.id); }\\n          })\\n        );\\n      }\\n    }\\n  ];\\n\\n  var nextBac = record && record.bacKeTiep ? record.bacKeTiep.ten_bac : null;\\n  var modalTitle = record\\n    ? 'Điều kiện lên bậc: ' + record.ten_bac + (nextBac ? ' → ' + nextBac : '')\\n    : 'Điều kiện lên bậc';\\n\\n  var tabItems = [\\n    {\\n      key: 'khoa',\\n      label: React.createElement(Badge, { count: khoaList.length, size: 'small', offset: [8, 0], showZero: true }, 'Khóa huấn luyện'),\\n      children: React.createElement('div', null,\\n        React.createElement(Space, { style: { marginBottom: 12, width: '100%' } },\\n          React.createElement(Select, {\\n            placeholder: 'Chọn khóa huấn luyện để gắn...',\\n            style: { minWidth: 360 },\\n            value: selectedKhoa,\\n            onChange: setSelectedKhoa,\\n            options: khoaOptions,\\n            showSearch: true,\\n            optionFilterProp: 'label',\\n            allowClear: true\\n          }),\\n          React.createElement(Tooltip, { title: 'Gắn khóa' },\\n            React.createElement(Button, {\\n              type: 'primary',\\n              icon: React.createElement(LinkOutlined, null),\\n              disabled: !selectedKhoa,\\n              onClick: handleLinkKhoa\\n            })\\n          )\\n        ),\\n        React.createElement(Table, {\\n          rowKey: 'id',\\n          columns: khoaColumns,\\n          dataSource: khoaList,\\n          loading: loading,\\n          pagination: false,\\n          size: 'small',\\n          locale: { emptyText: React.createElement(Empty, { description: 'Chưa gắn khóa huấn luyện nào', image: Empty.PRESENTED_IMAGE_SIMPLE }) }\\n        })\\n      )\\n    },\\n    {\\n      key: 'dethi',\\n      label: React.createElement(Badge, { count: deThiList.length, size: 'small', offset: [8, 0], showZero: true }, 'Đề thi'),\\n      children: React.createElement('div', null,\\n        React.createElement(Space, { style: { marginBottom: 12, width: '100%' } },\\n          React.createElement(Select, {\\n            placeholder: 'Chọn đề thi để gắn...',\\n            style: { minWidth: 360 },\\n            value: selectedDeThi,\\n            onChange: setSelectedDeThi,\\n            options: deThiOptions,\\n            showSearch: true,\\n            optionFilterProp: 'label',\\n            allowClear: true\\n          }),\\n          React.createElement(Tooltip, { title: 'Gắn đề thi' },\\n            React.createElement(Button, {\\n              type: 'primary',\\n              icon: React.createElement(LinkOutlined, null),\\n              disabled: !selectedDeThi,\\n              onClick: handleLinkDeThi\\n            })\\n          )\\n        ),\\n        React.createElement(Table, {\\n          rowKey: 'id',\\n          columns: deThiColumns,\\n          dataSource: deThiList,\\n          loading: loading,\\n          pagination: false,\\n          size: 'small',\\n          locale: { emptyText: React.createElement(Empty, { description: 'Chưa gắn đề thi nào', image: Empty.PRESENTED_IMAGE_SIMPLE }) }\\n        })\\n      )\\n    }\\n  ];\\n\\n  return React.createElement(Modal, {\\n    title: modalTitle,\\n    open: open,\\n    onCancel: onClose,\\n    footer: React.createElement(Button, { onClick: onClose }, 'Đóng'),\\n    width: 780,\\n    destroyOnClose: true\\n  },\\n    React.createElement(Tabs, {\\n      activeKey: activeTab,\\n      onChange: setActiveTab,\\n      items: tabItems\\n    })\\n  );\\n}\\n\\n// === MAIN COMPONENT ===\\n\\nfunction BacThoManager({ nganhNgheInit, bacThoInit, reloadNganh, reloadBac }) {\\n  var [nganhList, setNganhList] = useState(nganhNgheInit);\\n  var [bacThoList, setBacThoList] = useState(bacThoInit);\\n  var [loading, setLoading] = useState(false);\\n  var [activeTab, setActiveTab] = useState('all');\\n  var [modalOpen, setModalOpen] = useState(false);\\n  var [editRecord, setEditRecord] = useState(null);\\n  var [form] = Form.useForm();\\n  var [dkModalOpen, setDkModalOpen] = useState(false);\\n  var [dkRecord, setDkRecord] = useState(null);\\n\\n  var handleReload = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var nn = await reloadNganh();\\n      var bt = await reloadBac();\\n      setNganhList(nn);\\n      setBacThoList(bt);\\n      ctx.message.success('Đã tải lại dữ liệu');\\n    } catch (e) {\\n      ctx.message.error('Lỗi tải dữ liệu: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [reloadNganh, reloadBac]);\\n\\n  var filteredBacTho = useMemo(function() {\\n    if (activeTab === 'all') return bacThoList;\\n    if (activeTab === 'shared') return bacThoList.filter(function(b) { return !b.nganhNgheTrucThuocId; });\\n    return bacThoList.filter(function(b) {\\n      return String(b.nganhNgheTrucThuocId) === String(activeTab);\\n    });\\n  }, [bacThoList, activeTab]);\\n\\n  var bacThoByNganh = useMemo(function() {\\n    var map = {};\\n    bacThoList.forEach(function(b) {\\n      var key = b.nganhNgheTrucThuocId ? String(b.nganhNgheTrucThuocId) : 'shared';\\n      if (!map[key]) map[key] = [];\\n      map[key].push(b);\\n    });\\n    return map;\\n  }, [bacThoList]);\\n\\n  var openAdd = useCallback(function() {\\n    setEditRecord(null);\\n    var defaultNganh = activeTab !== 'all' && activeTab !== 'shared' ? Number(activeTab) : undefined;\\n    var filtered = activeTab !== 'all' && activeTab !== 'shared'\\n      ? bacThoList.filter(function(b) { return String(b.nganhNgheTrucThuocId) === String(activeTab); })\\n      : bacThoList;\\n    var maxOrder = 0;\\n    filtered.forEach(function(b) { if (b.thu_tu > maxOrder && b.thu_tu < 100) maxOrder = b.thu_tu; });\\n    form.resetFields();\\n    form.setFieldsValue({\\n      nganhNgheTrucThuocId: defaultNganh || undefined,\\n      thu_tu: maxOrder + 1,\\n      hieu_luc: 'dang_dung',\\n      la_bac_chinh: true,\\n      yeu_cau_huan_luyen: false\\n    });\\n    setModalOpen(true);\\n  }, [activeTab, bacThoList, form]);\\n\\n  var openEdit = useCallback(function(record) {\\n    setEditRecord(record);\\n    form.resetFields();\\n    form.setFieldsValue({\\n      ma_bac: record.ma_bac,\\n      ten_bac: record.ten_bac,\\n      mo_ta: record.mo_ta,\\n      thu_tu: record.thu_tu,\\n      hieu_luc: record.hieu_luc || 'dang_dung',\\n      la_bac_chinh: record.la_bac_chinh !== false,\\n      yeu_cau_huan_luyen: record.yeu_cau_huan_luyen === true,\\n      nganhNgheTrucThuocId: record.nganhNgheTrucThuocId || undefined,\\n      bacKeTiepId: record.bacKeTiepId || undefined\\n    });\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  var openDieuKien = useCallback(function(record) {\\n    setDkRecord(record);\\n    setDkModalOpen(true);\\n  }, []);\\n\\n  var handleSave = useCallback(async function() {\\n    try {\\n      var values = await form.validateFields();\\n      setLoading(true);\\n      if (editRecord) {\\n        await ctx.request({\\n          url: 'bac_tho:update',\\n          method: 'post',\\n          params: { filterByTk: editRecord.id },\\n          data: {\\n            ma_bac: values.ma_bac,\\n            ten_bac: values.ten_bac,\\n            mo_ta: values.mo_ta || null,\\n            thu_tu: values.thu_tu,\\n            hieu_luc: values.hieu_luc,\\n            la_bac_chinh: values.la_bac_chinh,\\n            yeu_cau_huan_luyen: values.yeu_cau_huan_luyen,\\n            nganhNgheTrucThuocId: values.nganhNgheTrucThuocId || null,\\n            bacKeTiepId: values.bacKeTiepId || null\\n          }\\n        });\\n        ctx.message.success('Cập nhật thành công');\\n      } else {\\n        await ctx.request({\\n          url: 'bac_tho:create',\\n          method: 'post',\\n          data: {\\n            ma_bac: values.ma_bac,\\n            ten_bac: values.ten_bac,\\n            mo_ta: values.mo_ta || null,\\n            thu_tu: values.thu_tu,\\n            hieu_luc: values.hieu_luc,\\n            la_bac_chinh: values.la_bac_chinh,\\n            yeu_cau_huan_luyen: values.yeu_cau_huan_luyen,\\n            nganhNgheTrucThuocId: values.nganhNgheTrucThuocId || null,\\n            bacKeTiepId: values.bacKeTiepId || null\\n          }\\n        });\\n        ctx.message.success('Thêm mới thành công');\\n      }\\n      setModalOpen(false);\\n      var bt = await reloadBac();\\n      setBacThoList(bt);\\n    } catch (e) {\\n      if (e.errorFields) return;\\n      ctx.message.error('Lỗi: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [editRecord, form, reloadBac]);\\n\\n  var handleDelete = useCallback(async function(record) {\\n    setLoading(true);\\n    try {\\n      await ctx.request({\\n        url: 'bac_tho:destroy',\\n        method: 'post',\\n        params: { filterByTk: record.id }\\n      });\\n      ctx.message.success('Đã xóa bậc thợ');\\n      var bt = await reloadBac();\\n      setBacThoList(bt);\\n    } catch (e) {\\n      ctx.message.error('Lỗi xóa: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [reloadBac]);\\n\\n  var nganhOptions = useMemo(function() {\\n    return nganhList.map(function(n) {\\n      return { label: n.ten_nganh + ' (' + n.ma_nganh + ')', value: n.id };\\n    });\\n  }, [nganhList]);\\n\\n  var bacKeTiepOptions = useMemo(function() {\\n    var nganhId = form.getFieldValue('nganhNgheTrucThuocId');\\n    var candidates = bacThoList.filter(function(b) {\\n      if (!nganhId) return !b.nganhNgheTrucThuocId;\\n      return String(b.nganhNgheTrucThuocId) === String(nganhId);\\n    });\\n    if (editRecord) {\\n      candidates = candidates.filter(function(b) { return b.id !== editRecord.id; });\\n    }\\n    return candidates.map(function(b) {\\n      return { label: b.ten_bac + ' (' + b.ma_bac + ')', value: b.id };\\n    });\\n  }, [bacThoList, form, editRecord]);\\n\\n  var columns = [\\n    {\\n      title: 'Thứ tự',\\n      dataIndex: 'thu_tu',\\n      key: 'thu_tu',\\n      width: 80,\\n      sorter: function(a, b) { return a.thu_tu - b.thu_tu; },\\n      defaultSortOrder: 'ascend',\\n      render: function(v) {\\n        return v >= 100 ? React.createElement(Tag, { color: 'purple' }, 'Đặc biệt') : v;\\n      }\\n    },\\n    {\\n      title: 'Mã bậc',\\n      dataIndex: 'ma_bac',\\n      key: 'ma_bac',\\n      width: 110,\\n      render: function(v) {\\n        return React.createElement(Typography.Text, { strong: true, copyable: true }, v);\\n      }\\n    },\\n    {\\n      title: 'Tên bậc',\\n      dataIndex: 'ten_bac',\\n      key: 'ten_bac',\\n      ellipsis: true\\n    },\\n    {\\n      title: 'Ngành nghề',\\n      key: 'nganh',\\n      width: 180,\\n      render: function(_, record) {\\n        var nn = record.nganh_nghe_truc_thuoc;\\n        if (!nn) return React.createElement(Tag, { color: 'default' }, 'Dùng chung');\\n        return React.createElement(Tag, { color: 'blue' }, nn.ten_nganh);\\n      }\\n    },\\n    {\\n      title: 'Bậc kế tiếp',\\n      key: 'bacKeTiep',\\n      width: 180,\\n      render: function(_, record) {\\n        var bkt = record.bacKeTiep;\\n        if (!bkt) return React.createElement(Tag, { color: 'default' }, 'Cao nhất');\\n        return React.createElement(Tag, { color: 'green', icon: React.createElement(ArrowUpOutlined, null) }, bkt.ma_bac);\\n      }\\n    },\\n    {\\n      title: 'Hiệu lực',\\n      dataIndex: 'hieu_luc',\\n      key: 'hieu_luc',\\n      width: 120,\\n      render: function(v) {\\n        if (v === 'dang_dung') return React.createElement(Tag, { color: 'success', icon: React.createElement(CheckCircleOutlined, null) }, 'Đang dùng');\\n        return React.createElement(Tag, { color: 'error', icon: React.createElement(StopOutlined, null) }, 'Ngừng dùng');\\n      }\\n    },\\n    {\\n      title: 'Thao tác',\\n      key: 'actions',\\n      width: 150,\\n      fixed: 'right',\\n      render: function(_, record) {\\n        return React.createElement(Space, { size: 4 },\\n          React.createElement(Tooltip, { title: 'Điều kiện lên bậc' },\\n            React.createElement(Button, {\\n              icon: React.createElement(FileTextOutlined, null),\\n              onClick: function() { openDieuKien(record); }\\n            })\\n          ),\\n          React.createElement(Tooltip, { title: 'Sửa' },\\n            React.createElement(Button, {\\n              icon: React.createElement(EditOutlined, null),\\n              onClick: function() { openEdit(record); }\\n            })\\n          ),\\n          React.createElement(Popconfirm, {\\n            title: 'Xác nhận xóa bậc thợ \\"' + record.ma_bac + '\\"?',\\n            okText: 'Xóa',\\n            cancelText: 'Hủy',\\n            onConfirm: function() { handleDelete(record); }\\n          },\\n            React.createElement(Tooltip, { title: 'Xóa' },\\n              React.createElement(Button, {\\n                danger: true,\\n                icon: React.createElement(DeleteOutlined, null)\\n              })\\n            )\\n          )\\n        );\\n      }\\n    }\\n  ];\\n\\n  if (activeTab === 'all') {\\n    // show nganh column only in 'all' tab\\n  } else {\\n    columns = columns.filter(function(c) { return c.key !== 'nganh'; });\\n  }\\n\\n  var tabItems = [\\n    {\\n      key: 'all',\\n      label: React.createElement(Badge, { count: bacThoList.length, size: 'small', offset: [8, 0] }, 'Tất cả')\\n    }\\n  ];\\n\\n  nganhList.forEach(function(n) {\\n    var count = (bacThoByNganh[String(n.id)] || []).length;\\n    tabItems.push({\\n      key: String(n.id),\\n      label: React.createElement(Badge, { count: count, size: 'small', offset: [8, 0] }, n.ten_nganh)\\n    });\\n  });\\n\\n  var sharedCount = (bacThoByNganh['shared'] || []).length;\\n  if (sharedCount > 0) {\\n    tabItems.push({\\n      key: 'shared',\\n      label: React.createElement(Badge, { count: sharedCount, size: 'small', offset: [8, 0] }, 'Dùng chung')\\n    });\\n  }\\n\\n  return React.createElement('div', null,\\n    React.createElement(Card, {\\n      title: React.createElement(Space, null,\\n        React.createElement(OrderedListOutlined, null),\\n        'Quản lý Bậc thợ theo Ngành nghề'\\n      ),\\n      extra: React.createElement(Space, { size: 4 },\\n        React.createElement(Tooltip, { title: 'Thêm bậc thợ' },\\n          React.createElement(Button, {\\n            type: 'primary',\\n            icon: React.createElement(PlusOutlined, null),\\n            onClick: openAdd\\n          }, 'Thêm bậc thợ')\\n        ),\\n        React.createElement(Tooltip, { title: 'Tải lại' },\\n          React.createElement(Button, {\\n            icon: React.createElement(ReloadOutlined, null),\\n            onClick: handleReload\\n          })\\n        )\\n      ),\\n      bodyStyle: { padding: 0 }\\n    },\\n      React.createElement(Tabs, {\\n        activeKey: activeTab,\\n        onChange: setActiveTab,\\n        tabBarStyle: { paddingLeft: 16, marginBottom: 0 },\\n        items: tabItems\\n      }),\\n      React.createElement(Table, {\\n        rowKey: 'id',\\n        columns: columns,\\n        dataSource: filteredBacTho,\\n        loading: loading,\\n        pagination: { pageSize: 50, showSizeChanger: true, showTotal: function(t) { return 'Tổng: ' + t + ' bậc'; } },\\n        size: 'middle',\\n        scroll: { x: 900 },\\n        locale: { emptyText: React.createElement(Empty, { description: 'Chưa có bậc thợ nào' }) }\\n      })\\n    ),\\n\\n    React.createElement(Modal, {\\n      title: editRecord ? 'Sửa bậc thợ' : 'Thêm bậc thợ mới',\\n      open: modalOpen,\\n      onOk: handleSave,\\n      onCancel: function() { setModalOpen(false); },\\n      confirmLoading: loading,\\n      okText: editRecord ? 'Cập nhật' : 'Tạo mới',\\n      cancelText: 'Hủy',\\n      width: 640,\\n      destroyOnClose: true\\n    },\\n      React.createElement(Form, {\\n        form: form,\\n        layout: 'vertical',\\n        preserve: false\\n      },\\n        React.createElement(Row, { gutter: 16 },\\n          React.createElement(Col, { span: 12 },\\n            React.createElement(Form.Item, {\\n              name: 'nganhNgheTrucThuocId',\\n              label: 'Ngành nghề trực thuộc',\\n              tooltip: 'Để trống nếu là bậc dùng chung'\\n            },\\n              React.createElement(Select, {\\n                placeholder: 'Chọn ngành nghề (hoặc để trống)',\\n                allowClear: true,\\n                options: nganhOptions,\\n                showSearch: true,\\n                optionFilterProp: 'label'\\n              })\\n            )\\n          ),\\n          React.createElement(Col, { span: 6 },\\n            React.createElement(Form.Item, {\\n              name: 'ma_bac',\\n              label: 'Mã bậc',\\n              rules: [{ required: true, message: 'Nhập mã bậc' }]\\n            },\\n              React.createElement(Input, { placeholder: 'VD: CK-B1' })\\n            )\\n          ),\\n          React.createElement(Col, { span: 6 },\\n            React.createElement(Form.Item, {\\n              name: 'thu_tu',\\n              label: 'Thứ tự',\\n              rules: [{ required: true, message: 'Nhập thứ tự' }]\\n            },\\n              React.createElement(InputNumber, { min: 1, max: 999, style: { width: '100%' } })\\n            )\\n          )\\n        ),\\n        React.createElement(Form.Item, {\\n          name: 'ten_bac',\\n          label: 'Tên bậc',\\n          rules: [{ required: true, message: 'Nhập tên bậc' }]\\n        },\\n          React.createElement(Input, { placeholder: 'VD: Thợ hàn - Bậc 1/7 Sơ cấp' })\\n        ),\\n        React.createElement(Form.Item, {\\n          name: 'mo_ta',\\n          label: 'Mô tả'\\n        },\\n          React.createElement(Input.TextArea, { rows: 2, placeholder: 'Mô tả bậc thợ (tùy chọn)' })\\n        ),\\n        React.createElement(Row, { gutter: 16 },\\n          React.createElement(Col, { span: 12 },\\n            React.createElement(Form.Item, {\\n              name: 'bacKeTiepId',\\n              label: 'Bậc kế tiếp',\\n              tooltip: 'Bậc sẽ được nâng lên khi đủ điều kiện'\\n            },\\n              React.createElement(Select, {\\n                placeholder: 'Chọn bậc kế tiếp',\\n                allowClear: true,\\n                options: bacKeTiepOptions,\\n                showSearch: true,\\n                optionFilterProp: 'label'\\n              })\\n            )\\n          ),\\n          React.createElement(Col, { span: 12 },\\n            React.createElement(Form.Item, {\\n              name: 'hieu_luc',\\n              label: 'Hiệu lực',\\n              rules: [{ required: true }]\\n            },\\n              React.createElement(Select, {\\n                options: [\\n                  { label: 'Đang dùng', value: 'dang_dung' },\\n                  { label: 'Ngừng dùng', value: 'ngung_dung' }\\n                ]\\n              })\\n            )\\n          )\\n        ),\\n        React.createElement(Row, { gutter: 16 },\\n          React.createElement(Col, { span: 12 },\\n            React.createElement(Form.Item, {\\n              name: 'la_bac_chinh',\\n              label: 'Là bậc chính',\\n              valuePropName: 'checked'\\n            },\\n              React.createElement(Switch, null)\\n            )\\n          ),\\n          React.createElement(Col, { span: 12 },\\n            React.createElement(Form.Item, {\\n              name: 'yeu_cau_huan_luyen',\\n              label: 'Yêu cầu huấn luyện',\\n              valuePropName: 'checked'\\n            },\\n              React.createElement(Switch, null)\\n            )\\n          )\\n        )\\n      )\\n    ),\\n\\n    React.createElement(DieuKienModal, {\\n      open: dkModalOpen,\\n      onClose: function() { setDkModalOpen(false); },\\n      record: dkRecord,\\n      bacThoList: bacThoList\\n    })\\n  );\\n}\\n\\nctx.render(\\n  React.createElement(BacThoManager, {\\n    nganhNgheInit: initialNganhNghe,\\n    bacThoInit: initialBacTho,\\n    reloadNganh: fetchNganhNghe,\\n    reloadBac: fetchBacTho\\n  })\\n);\\n", "version": "1"}}, "__flowSurfaceMeta": {"declaredKey": "workerGrades.workerGradeStats"}}, "decoratorProps": {"title": "Thống kê bậc thợ"}}
