ter3leonkgw	ter3leonkgw	{"parentId":"b9yxw81xe2w","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Badge, Button, Card, Col, Descriptions, Divider, Drawer, Empty, Form, Input, InputNumber, Modal, Popconfirm, Progress, Row, Select, Space, Statistic, Table, Tabs, Tag, Tooltip, Typography, message } = ctx.libs.antd;\\nconst { CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, DownloadOutlined, EditOutlined, ExclamationCircleOutlined, EyeOutlined, FileExcelOutlined, FilePdfOutlined, FileTextOutlined, LockOutlined, PrinterOutlined, ReloadOutlined, SearchOutlined, SendOutlined, TeamOutlined } = ctx.libs.antdIcons;\\nconst React = ctx.libs.React;\\nconst { useState, useMemo, useCallback } = ctx.libs.React;\\n\\nvar TRANG_THAI_DUYET = {\\n  'cho_duyet': { label: 'Chờ duyệt', color: 'warning' },\\n  'da_duyet': { label: 'Đã duyệt', color: 'success' },\\n  'tu_choi': { label: 'Từ chối', color: 'error' },\\n  'da_khoa': { label: 'Đã khóa điểm', color: 'purple' },\\n  'da_cong_bo': { label: 'Đã công bố', color: 'green' },\\n};\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('ky_thi');\\n  ctx.resource.setAppends(['de_thi', 'don_vi', 'lop_hoc', 'thi_sinh', 'thi_sinh.nguoi_lao_dong']);\\n  ctx.resource.setSort(['-ngay_thi']);\\n  ctx.resource.setPageSize(100);\\n  await ctx.resource.refresh();\\n  var initialKyThi = ctx.resource.getData() || [];\\n\\n  var blRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialBaiLam = [];\\n  if (blRes) {\\n    blRes.setResourceName('bai_lam_ky_thi');\\n    blRes.setAppends(['thi_sinh', 'nguoi_cham', 'nguoi_duyet']);\\n    blRes.setSort(['-createdAt']);\\n    blRes.setPageSize(500);\\n    await blRes.refresh();\\n    initialBaiLam = blRes.getData() || [];\\n  }\\n\\n  var tsRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialThiSinh = [];\\n  if (tsRes) {\\n    tsRes.setResourceName('ky_thi_thi_sinh');\\n    tsRes.setAppends(['nguoi_lao_dong', 'ky_thi']);\\n    tsRes.setPageSize(500);\\n    await tsRes.refresh();\\n    initialThiSinh = tsRes.getData() || [];\\n  }\\n\\n  async function fetchAll() {\\n    var res1 = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    var kt = initialKyThi, bl = initialBaiLam, ts = initialThiSinh;\\n    if (res1) { res1.setResourceName('ky_thi'); res1.setAppends(['de_thi','don_vi','lop_hoc','thi_sinh','thi_sinh.nguoi_lao_dong']); res1.setSort(['-ngay_thi']); res1.setPageSize(100); await res1.refresh(); kt = res1.getData() || []; }\\n    var res2 = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (res2) { res2.setResourceName('bai_lam_ky_thi'); res2.setAppends(['thi_sinh','nguoi_cham','nguoi_duyet']); res2.setSort(['-createdAt']); res2.setPageSize(500); await res2.refresh(); bl = res2.getData() || []; }\\n    var res3 = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (res3) { res3.setResourceName('ky_thi_thi_sinh'); res3.setAppends(['nguoi_lao_dong','ky_thi']); res3.setPageSize(500); await res3.refresh(); ts = res3.getData() || []; }\\n    return { kyThi: kt, baiLam: bl, thiSinh: ts };\\n  }\\n\\n  function formatDateTime(val) {\\n    if (!val) return '-';\\n    try { var d = new Date(val); if (isNaN(d.getTime())) return val; return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear()+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); } catch(e) { return val; }\\n  }\\n  function formatDate(val) {\\n    if (!val) return '-';\\n    try { var d = new Date(val); if (isNaN(d.getTime())) return val; return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(); } catch(e) { return val; }\\n  }\\n\\n  function DuyetCongBoApp(props) {\\n    var [kyThi, setKyThi] = useState(props.initialKyThi);\\n    var [baiLam, setBaiLam] = useState(props.initialBaiLam);\\n    var [thiSinh, setThiSinh] = useState(props.initialThiSinh);\\n    var [loading, setLoading] = useState(false);\\n    var [activeTab, setActiveTab] = useState('duyet');\\n    var [searchText, setSearchText] = useState('');\\n\\n    var [detailDrawer, setDetailDrawer] = useState(false);\\n    var [detailKyThi, setDetailKyThi] = useState(null);\\n    var [rejectModal, setRejectModal] = useState(false);\\n    var [rejectKyThiId, setRejectKyThiId] = useState(null);\\n    var [rejectReason, setRejectReason] = useState('');\\n    var [saving, setSaving] = useState(false);\\n    var [bienBanModal, setBienBanModal] = useState(false);\\n    var [bienBanKyThi, setBienBanKyThi] = useState(null);\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var data = await fetchAll();\\n        setKyThi(data.kyThi); setBaiLam(data.baiLam); setThiSinh(data.thiSinh);\\n      } catch(e) { message.error('Lỗi tải dữ liệu'); }\\n      setLoading(false);\\n    }, []);\\n\\n    function getKyThiStats(kt) {\\n      var ts = thiSinh.filter(function(t) { return t.ky_thi_id === kt.id; });\\n      var bl = baiLam.filter(function(b) { return b.ky_thi_id === kt.id; });\\n      var total = ts.length;\\n      var daCham = bl.filter(function(b) { return ['da_cham','cho_duyet','da_duyet','da_khoa','da_cong_bo'].indexOf(b.trang_thai_cham) >= 0; }).length;\\n      var dat = ts.filter(function(t) { return t.ket_qua === 'dat'; }).length;\\n      var khongDat = ts.filter(function(t) { return t.ket_qua === 'khong_dat'; }).length;\\n      var diemTB = 0;\\n      var coD = ts.filter(function(t) { return t.diem !== null && t.diem !== undefined; });\\n      if (coD.length > 0) diemTB = coD.reduce(function(s,t) { return s + (t.diem||0); }, 0) / coD.length;\\n      return { total: total, daCham: daCham, dat: dat, khongDat: khongDat, diemTB: diemTB, tiLeDat: total > 0 ? Math.round(dat/total*100) : 0 };\\n    }\\n\\n    var duyetData = useMemo(function() {\\n      return kyThi.filter(function(kt) {\\n        if (kt.trang_thai !== 'hoan_thanh' && kt.trang_thai !== 'da_phe_duyet') return false;\\n        var bl = baiLam.filter(function(b) { return b.ky_thi_id === kt.id; });\\n        var coDaCham = bl.some(function(b) { return ['da_cham','cho_duyet','da_duyet'].indexOf(b.trang_thai_cham) >= 0; });\\n        return coDaCham;\\n      }).map(function(kt) {\\n        var stats = getKyThiStats(kt);\\n        return Object.assign({}, kt, { stats: stats });\\n      });\\n    }, [kyThi, baiLam, thiSinh]);\\n\\n    var congBoData = useMemo(function() {\\n      return kyThi.filter(function(kt) {\\n        var bl = baiLam.filter(function(b) { return b.ky_thi_id === kt.id; });\\n        return bl.some(function(b) { return b.trang_thai_cham === 'da_duyet' || b.trang_thai_cham === 'da_khoa' || b.trang_thai_cham === 'da_cong_bo'; });\\n      }).map(function(kt) {\\n        return Object.assign({}, kt, { stats: getKyThiStats(kt) });\\n      });\\n    }, [kyThi, baiLam, thiSinh]);\\n\\n    var filtered = useMemo(function() {\\n      var src = activeTab === 'duyet' ? duyetData : congBoData;\\n      if (!searchText) return src;\\n      var s = searchText.toLowerCase();\\n      return src.filter(function(kt) { return (kt.ten_ky_thi||'').toLowerCase().indexOf(s) >= 0; });\\n    }, [activeTab, duyetData, congBoData, searchText]);\\n\\n    async function handleApprove(kyThiId) {\\n      setSaving(true);\\n      try {\\n        var bl = baiLam.filter(function(b) { return b.ky_thi_id === kyThiId && (b.trang_thai_cham === 'da_cham' || b.trang_thai_cham === 'cho_duyet'); });\\n        for (var i = 0; i < bl.length; i++) {\\n          await ctx.request({ url: 'bai_lam_ky_thi:update', method: 'post', params: { filterByTk: bl[i].id }, data: { trang_thai_cham: 'da_duyet' } });\\n        }\\n        message.success('Đã phê duyệt ' + bl.length + ' bài 