n2t08e4r8c1	n2t08e4r8c1	{"parentId":"8v0ms9bre6v","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Badge, Button, Card, Col, Descriptions, Divider, Drawer, Empty, Form, Input, InputNumber, List, Modal, Popconfirm, Progress, Row, Select, Space, Spin, Statistic, Table, Tabs, Tag, Tooltip, Typography, Upload, message } = ctx.libs.antd;\\nconst { BarChartOutlined, CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, CloudUploadOutlined, DeleteOutlined, DownloadOutlined, EditOutlined, ExclamationCircleOutlined, EyeOutlined, FileOutlined, FilePdfOutlined, FileTextOutlined, InboxOutlined, PlusOutlined, ReloadOutlined, SearchOutlined, TeamOutlined, UploadOutlined, UserOutlined } = ctx.libs.antdIcons;\\nconst React = ctx.libs.React;\\nconst { useState, useMemo, useCallback, useEffect } = ctx.libs.React;\\n\\nvar TRANG_THAI_CHAM = [\\n  { value: 'chua_cham', label: 'Chưa chấm', color: 'default' },\\n  { value: 'dang_cham', label: 'Đang chấm', color: 'processing' },\\n  { value: 'da_cham', label: 'Đã chấm', color: 'cyan' },\\n  { value: 'cho_duyet', label: 'Chờ duyệt', color: 'warning' },\\n  { value: 'da_duyet', label: 'Đã duyệt', color: 'success' },\\n  { value: 'tra_lai', label: 'Trả lại', color: 'error' },\\n  { value: 'da_khoa', label: 'Đã khóa', color: 'purple' },\\n  { value: 'da_cong_bo', label: 'Đã công bố', color: 'green' },\\n  { value: 'da_phe_duyet', label: 'Đã phê duyệt', color: 'success' },\\n];\\nvar TRANG_THAI_CHAM_MAP = Object.fromEntries(TRANG_THAI_CHAM.map(function(s) { return [s.value, s]; }));\\n\\nvar KET_QUA_MAP = {\\n  'chua_xac_dinh': { label: 'Chưa xác định', color: 'default' },\\n  'dat': { label: 'Đạt', color: 'success' },\\n  'khong_dat': { label: 'Không đạt', color: 'error' },\\n};\\n\\nvar TRANG_THAI_TS = {\\n  'cho_thi': { label: 'Chờ thi', color: 'default' },\\n  'da_xep_lich': { label: 'Đã xếp lịch', color: 'processing' },\\n  'da_nop': { label: 'Đã nộp bài', color: 'cyan' },\\n  'dang_cham': { label: 'Đang chấm', color: 'blue' },\\n  'cho_duyet': { label: 'Chờ duyệt', color: 'warning' },\\n  'dat': { label: 'Đạt', color: 'success' },\\n  'khong_dat': { label: 'Không đạt', color: 'error' },\\n};\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('bai_lam_ky_thi');\\n  ctx.resource.setAppends(['ky_thi', 'thi_sinh', 'nguoi_cham', 'nguoi_duyet']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(200);\\n  await ctx.resource.refresh();\\n  var initialBaiLam = ctx.resource.getData() || [];\\n\\n  var ktRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialKyThi = [];\\n  if (ktRes) {\\n    ktRes.setResourceName('ky_thi');\\n    ktRes.setFilter({ trang_thai: { $in: ['hoan_thanh', 'da_phe_duyet', 'dang_thi'] } });\\n    ktRes.setAppends(['de_thi', 'don_vi', 'lop_hoc']);\\n    ktRes.setSort(['-ngay_thi']);\\n    ktRes.setPageSize(100);\\n    await ktRes.refresh();\\n    initialKyThi = ktRes.getData() || [];\\n  }\\n\\n  var tsRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialThiSinh = [];\\n  if (tsRes) {\\n    tsRes.setResourceName('ky_thi_thi_sinh');\\n    tsRes.setAppends(['nguoi_lao_dong', 'ky_thi', 'nguoi_cham']);\\n    tsRes.setSort(['-id']);\\n    tsRes.setPageSize(200);\\n    await tsRes.refresh();\\n    initialThiSinh = tsRes.getData() || [];\\n  }\\n\\n  var userRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialUsers = [];\\n  if (userRes) {\\n    userRes.setResourceName('users');\\n    userRes.setSort(['nickname']);\\n    userRes.setPageSize(100);\\n    await userRes.refresh();\\n    initialUsers = userRes.getData() || [];\\n  }\\n\\n  var dtRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n  var initialDeThi = [];\\n  if (dtRes) {\\n    dtRes.setResourceName('de_thi');\\n    dtRes.setAppends(['cau_hoi']);\\n    dtRes.setFilter({ trang_thai: 'da_phe_duyet' });\\n    dtRes.setPageSize(100);\\n    await dtRes.refresh();\\n    initialDeThi = dtRes.getData() || [];\\n  }\\n\\n  async function fetchBaiLam() {\\n    var res = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (!res) return initialBaiLam;\\n    res.setResourceName('bai_lam_ky_thi');\\n    res.setAppends(['ky_thi', 'thi_sinh', 'nguoi_cham', 'nguoi_duyet']);\\n    res.setSort(['-createdAt']);\\n    res.setPageSize(200);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  async function fetchThiSinh() {\\n    var res = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\n    if (!res) return initialThiSinh;\\n    res.setResourceName('ky_thi_thi_sinh');\\n    res.setAppends(['nguoi_lao_dong', 'ky_thi', 'nguoi_cham']);\\n    res.setSort(['-id']);\\n    res.setPageSize(200);\\n    await res.refresh();\\n    return res.getData() || [];\\n  }\\n\\n  function formatDateTime(val) {\\n    if (!val) return '-';\\n    try { var d = new Date(val); if (isNaN(d.getTime())) return val; return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear()+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); } catch(e) { return val; }\\n  }\\n  function formatDate(val) {\\n    if (!val) return '-';\\n    try { var d = new Date(val); if (isNaN(d.getTime())) return val; return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(); } catch(e) { return val; }\\n  }\\n\\n  function ChamDiemApp(props) {\\n    var [baiLam, setBaiLam] = useState(props.initialBaiLam);\\n    var [thiSinh, setThiSinh] = useState(props.initialThiSinh);\\n    var [kyThiList] = useState(props.initialKyThi);\\n    var [userList] = useState(props.initialUsers);\\n    var [deThiList] = useState(props.initialDeThi);\\n    var [loading, setLoading] = useState(false);\\n    var [activeTab, setActiveTab] = useState('ds_bai_nop');\\n    var [searchText, setSearchText] = useState('');\\n    var [filterKyThi, setFilterKyThi] = useState(undefined);\\n    var [filterTrangThai, setFilterTrangThai] = useState(undefined);\\n\\n    var [gradingDrawer, setGradingDrawer] = useState(false);\\n    var [gradingRecord, setGradingRecord] = useState(null);\\n    var [gradingScore, setGradingScore] = useState(null);\\n    var [gradingComment, setGradingComment] = useState('');\\n    var [gradingResult, setGradingResult] = useState(undefined);\\n    var [saving, setSaving] = useState(false);\\n\\n    var [assignModal, setAssignModal] = useState(false);\\n    var [selectedRows, setSelectedRows] = useState([]);\\n    var [assignUserId, setAssignUserId] = useState(undefined);\\n\\n    var [uploadModal, setUploadModal] = useState(false);\\n    var [uploadKyThi, setUploadKyThi] = useState(undefined);\\n\\n    var [detailDrawer, setDetailDrawer] = useState(false);\\n    var [detailRecord, setDetailRecord] = useState(null);\\n\\n    var [reconTab, setReconTab] = useState('all');\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var newBL = await fetchBaiLam();\\n        setBaiLam(newBL);\\n        var newTS = await fetchThiSinh();\\n        setThiSinh(newTS);\\n      } catch(e) { message.error('Lỗi tải dữ liệu'); }\\n      setLoading(false);\\n    }, []);\\n\\n    var stats = useMemo(function() {\\n      var total = baiLam.length;\\n      var chuaCham = baiLam.filter(function(b) { return b.trang_thai_cham === 'chua_cham'; }).length;\\n      var dangCham = baiLam.filter(function(b) { return b.trang_thai_cham === 'dang_cham'; }).length;\\n      var daCham = baiLam.filter(function(b) { return ['da_cham','cho_duyet','da_duyet','da_khoa','da_cong_bo'].indexOf(b.trang_thai_cham) >= 0; }).length;\\n      var daDuyet = baiLam.filter(function(b) { return ['da_duyet','da_khoa','da_cong_bo'].indexOf(b.trang_thai_cham) >= 0; }).length;\\n      return { total: total, chuaCham: chuaCham, dangCham: dangCham, daCham: daCham, daDuyet: daDuyet };\\n    }, [baiLam]);\\n\\n    var filteredBaiLam = useMemo(function() {\\n      return baiLam.filter(function(b) {\\n        if (filterKyThi && b.ky_thi_id !== filterKyThi) return false;\\n        if (filterTrangThai && b.trang_thai_cham !== filterTrangThai) return false;\\n        if (searchText) {\\n          var s = searchText.toLowerCase();\\n          var tenTS = (b.thi_sinh && (b.thi_sinh.ho_ten || b.thi_sinh.ten)) || b.title || '';\\n          var tenKT = (b.ky_thi && b.ky_thi.ten_ky_thi) || '';\\n          if (tenTS.toLowerCase().indexOf(s) < 0 && tenKT.toLowerCase().indexOf(s) < 0 && (b.filename || '').toLowerCase().indexOf(s) < 0) return false;\\n        }\\n        if (activeTab === 'can_cham') {\\n          return b.trang_thai_cham === 'chua_cham' || b.trang_thai_cham === 'dang_cham';\\n        }\\n        return true;\\n      });\\n    }, [baiLam, filterKyThi, filterTrangThai, searchText, activeTab]);\\n\\n    var reconData = useMemo(function() {\\n      return thiSinh.filter(function(ts) {\\n        if (!ts.diem && ts.diem !== 0) return false;\\n        var bl = baiLam.find(function(b) { return b.thi_sinh_id === ts.nguoi_lao_dong_id && b.ky_thi_id === ts.ky_thi_id; });\\n        if (!bl || (!bl.diem && bl.diem !== 0)) return false;\\n        return true;\\n      }).map(function(ts) {\\n        var bl = baiLam.find(function(b) { return b.thi_sinh_id === ts.nguoi_lao_dong_id && b.ky_thi_id === ts.ky_thi_id; });\\n        var diff = bl ? Math.abs((ts.diem || 0) - (bl.diem || 0)) : 0;\\n        return { thiSinh: ts, baiLam: bl, chenhLech: diff };\\n      });\\n    }, [thiSinh, baiLam]);\\n\\n    async function handleAssignGrader() {\\n      if (!assignUserId || selectedRows.length === 0) return;\\n      setSaving(true);\\n      try {\\n        for (var i = 0; i < selectedRows.length; i++) {\\n          await ctx.request({\\n            url: 'bai_lam_ky_thi:update',\\n            method: 'post',\\n            params: { filterByTk: selectedRows[i] },\\n            data: { nguoi_cham_id: assignUserId, trang_thai_cham: 'dang_cham' }\\n          });\\n        }\\n        message.success('Đã gán ' + selectedRows.length + ' bài cho người chấm');\\n        setAssignModal(false);\\n        setSelectedRows([]);\\n        setAssignUserId(undefined);\\n        await refreshData();\\n      } catch(e) { message.error('Lỗi gán người chấm'); }\\n      setSaving(false);\\n    }\\n\\n    async function handleSaveGrading() {\\n      if (gradingScore === null || gradingScore === undefined) {\\n        message.warning('Vui lòng nhập điểm');\\n        return;\\n      }\\n      setSaving(true);\\n      try {\\n        var data = {\\n          diem: gradingScore,\\n          nhan_xet: gradingComment,\\n          ket_qua: gradingResult || 'chua_xac_dinh',\\n          trang_thai_cham: 'da_cham',\\n        };\\n        await ctx.request({\\n          url: 'bai_lam_ky_thi:update',\\n          method: 'post',\\n          params: { filterByTk: gradingRecord.id },\\n          data: data\\n        });\\n        if (gradingRecord.thi_sinh_id) {\\n          var tsRec = thiSinh.find(function(t) { return t.nguoi_lao_dong_id === gradingRecord.thi_sinh_id && t.ky_thi_id === gradingRecord.ky_thi_id; });\\n          if (tsRec) {\\n            await ctx.request({\\n              url: 'ky_thi_thi_sinh:update',\\n              method: 'post',\\n              params: { filterByTk: tsRec.id },\\n              data: { diem: gradingScore, ket_qua: gradingResult === 'dat' ? 'dat' : (gradingResult === 'khong_dat' ? 'khong_dat' : 'chua_co'), trang_thai: 'cho_duyet' }\\n            });\\n          }\\n        }\\n        message.success('Đã lưu kết quả chấm');\\n        setGradingDrawer(false);\\n        setGradingRecord(null);\\n        await refreshData();\\n      } catch(e) { message.error('Lỗi lưu điểm'); }\\n      setSaving(false);\\n    }\\n\\n    async function handleReturnSubmission(record, reason) {\\n      try {\\n        await ctx.request({\\n          url: 'bai_lam_ky_thi:update',\\n          method: 'post',\\n          params: { filterByTk: record.id },\\n          data: { trang_thai_cham: 'tra_lai', ly_do_tra_lai: reason, lan_tra_lai: (record.lan_tra_lai || 0) + 1 }\\n        });\\n        message.success('Đã trả lại bài thi');\\n        await refreshData();\\n      } catch(e) { message.error('Lỗi trả lại'); }\\n    }\\n\\n    async function handleSubmitForApproval(ids) {\\n      setSaving(true);\\n      try {\\n        for (var i = 0; i < ids.length; i++) {\\n          await ctx.request({\\n            url: 'bai_lam_ky_thi:update',\\n            method: 'post',\\n            params: { filterByTk: ids[i] },\\n            data: { trang_thai_cham: 'cho_duyet' }\\n          });\\n        }\\n        message.success('Đã gửi ' + ids.length + ' bài duyệt');\\n        setSelectedRows([]);\\n        await refreshData();\\n      } catch(e) { message.error('Lỗi gửi duyệt'); }\\n      setSaving(false);\\n    }\\n\\n    function openGrading(record) {\\n      setGradingRecord(record);\\n      setGradingScore(record.diem);\\n      setGradingComment(record.nhan_xet || '');\\n      setGradingResult(record.ket_qua || undefined);\\n      setGradingDrawer(true);\\n    }\\n\\n    function getThiSinhName(record) {\\n      if (record.thi_sinh) return record.thi_sinh.ho_ten || record.thi_sinh.ten || '-';\\n      return record.title || record.filename || '-';\\n    }\\n\\n    function getKyThiName(record) {\\n      if (record.ky_thi) return record.ky_thi.ten_ky_thi || '-';\\n      if (record.ky_thi_id) {\\n        var kt = kyThiList.find(function(k) { return k.id === record.ky_thi_id; });\\n        if (kt) return kt.ten_ky_thi || '-';\\n      }\\n      return '-';\\n    }\\n\\n    var baiLamColumns = [\\n      { title: 'Thí sinh / File', dataIndex: 'title', key: 'title', width: 200, render: function(_, r) {\\n 