kakfeggq4co	kakfeggq4co	{"parentId":"ofgbo89a2ow","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"1","code":"const { Alert, Card, Col, Row, Skeleton, Statistic } = ctx.libs.antd;\\nctx.render(<Skeleton active paragraph={{ rows: 1 }} />);\\ntry {\\n  const resource = ctx.makeResource('MultiRecordResource');\\n  resource.setResourceName('thang_diem');\\n  resource.setPageSize?.(1000);\\n  await resource.refresh();\\n  const rows = resource.getData?.() || [];\\n  const metrics = [\\n    { key: 'total', title: ctx.t('Tổng thang điểm'), value: resource.getMeta?.()?.count ?? rows.length, color: '#1677ff' },\\n    { key: 'active', title: ctx.t('Đang quản lý'), value: rows.filter((row) => row.trang_thai === 'dang_quan_ly').length, color: '#52c41a' },\\n    { key: 'stopped', title: ctx.t('Ngừng sử dụng'), value: rows.filter((row) => row.trang_thai === 'ngung_su_dung').length, color: '#fa8c16' },\\n    { key: 'shared', title: ctx.t('Dùng chung'), value: rows.filter((row) => row.pham_vi_ap_dung === 'dung_chung').length, color: '#8c8c8c' },\\n  ];\\n  ctx.render(<Row gutter={[16, 16]}>{metrics.map((metric) => <Col key={metric.key} xs={24} sm={12} lg={6}><Card size=\\"small\\" style={{ borderLeft: `4px solid ${metric.color}`, height: '100%' }}><Statistic title={metric.title} value={metric.value} suffix={ctx.t('Thang')} /></Card></Col>)}</Row>);\\n} catch (error) { ctx.render(<Alert type=\\"error\\" showIcon message={ctx.t('Không tải được thống kê thang điểm')} description={String(error?.message || error)} />); }"}}}}
1vwkq3mg6t7	1vwkq3mg6t7	{"parentId":"7n3ac3336os","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"1","code":"const { Alert, Card, Col, Row, Skeleton, Statistic } = ctx.libs.antd;\\nctx.render(<Skeleton active paragraph={{ rows: 1 }} />);\\ntry {\\n  const resource = ctx.makeResource('MultiRecordResource');\\n  resource.setResourceName('lich_su_phan_quyen');\\n  resource.setPageSize?.(1000);\\n  await resource.refresh();\\n  const rows = resource.getData?.() || [];\\n  const metrics = [\\n    { key: 'total', title: ctx.t('Tổng lượt thay đổi'), value: resource.getMeta?.()?.count ?? rows.length, color: '#1677ff' },\\n    { key: 'success', title: ctx.t('Thành công'), value: rows.filter((row) => row.ket_qua === 'thanh_cong').length, color: '#52c41a' },\\n    { key: 'failed', title: ctx.t('Thất bại'), value: rows.filter((row) => row.ket_qua === 'that_bai').length, color: '#ff4d4f' },\\n    { key: 'assign', title: ctx.t('Gán hoặc gỡ quyền'), value: rows.filter((row) => row.loai_thay_doi === 'gan' || row.loai_thay_doi === 'go').length, color: '#8c8c8c' },\\n  ];\\n  ctx.render(<Row gutter={[16, 16]}>{metrics.map((metric) => <Col key={metric.key} xs={24} sm={12} lg={6}><Card size=\\"small\\" style={{ borderLeft: `4px solid ${metric.color}`, height: '100%' }}><Statistic title={metric.title} value={metric.value} suffix={ctx.t('Lượt')} /></Card></Col>)}</Row>);\\n} catch (error) { ctx.render(<Alert type=\\"error\\" showIcon message={ctx.t('Không tải được thống kê phân quyền')} description={String(error?.message || error)} />); }"}}}}
