ic36b6t86i0	ic36b6t86i0	{"parentId":"tnln0mdum8m","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v1","code":"// === LMS-02: Dashboard Học Viên ===\\n// Top-level data loading (VHMT-217 §6.1)\\n\\nvar currentUser = await ctx.getVar('ctx.user');\\nvar currentUserId = currentUser ? currentUser.id : null;\\n\\n// 1. Load nguoi_lao_dong for current user\\nvar nld = null;\\nvar nldId = null;\\nif (currentUserId) {\\n  var nldRes = ctx.makeResource('MultiRecordResource');\\n  nldRes.setResourceName('nguoi_lao_dong');\\n  nldRes.setFilter({ taiKhoanId: currentUserId });\\n  nldRes.setAppends(['don_vi', 'nganh_nghe', 'bac_tho', 'vai_tro']);\\n  nldRes.setPageSize(1);\\n  await nldRes.refresh();\\n  var nldList = nldRes.getData() || [];\\n  nld = nldList.length > 0 ? nldList[0] : null;\\n  nldId = nld ? nld.id : null;\\n}\\n\\n// 2. Load hoc_vien_lop (enrollments) for this student\\nvar enrollments = [];\\nif (nldId) {\\n  var hvlRes = ctx.makeResource('MultiRecordResource');\\n  hvlRes.setResourceName('hoc_vien_lop');\\n  hvlRes.setFilter({ nguoiLaoDongId: nldId });\\n  hvlRes.setAppends(['lop_hoc', 'lop_hoc.khoa_huan_luyen', 'chung_nhan']);\\n  hvlRes.setPageSize(200);\\n  await hvlRes.refresh();\\n  enrollments = hvlRes.getData() || [];\\n}\\n\\n// 3. Load ky_thi_thi_sinh (exam participations) for this student\\nvar examParticipations = [];\\nif (nldId) {\\n  var kttRes = ctx.makeResource('MultiRecordResource');\\n  kttRes.setResourceName('ky_thi_thi_sinh');\\n  kttRes.setFilter({ nguoi_lao_dong_id: nldId });\\n  kttRes.setAppends(['ky_thi', 'lop_hoc']);\\n  kttRes.setPageSize(200);\\n  await kttRes.refresh();\\n  examParticipations = kttRes.getData() || [];\\n}\\n\\n// 4. Load chung_nhan_huan_luyen (certificates) for this student\\nvar certificates = [];\\nif (nldId) {\\n  var cnRes = ctx.makeResource('MultiRecordResource');\\n  cnRes.setResourceName('chung_nhan_huan_luyen');\\n  cnRes.setFilter({ nguoiLaoDongId: nldId });\\n  cnRes.setAppends(['khoa_huan_luyen', 'ky_thi']);\\n  cnRes.setSort(['-ngay_cap']);\\n  cnRes.setPageSize(200);\\n  await cnRes.refresh();\\n  certificates = cnRes.getData() || [];\\n}\\n\\n// Reload functions\\nasync function reloadEnrollments() {\\n  if (!nldId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('hoc_vien_lop');\\n  r.setFilter({ nguoiLaoDongId: nldId });\\n  r.setAppends(['lop_hoc', 'lop_hoc.khoa_huan_luyen', 'chung_nhan']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function reloadExams() {\\n  if (!nldId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('ky_thi_thi_sinh');\\n  r.setFilter({ nguoi_lao_dong_id: nldId });\\n  r.setAppends(['ky_thi', 'lop_hoc']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function reloadCertificates() {\\n  if (!nldId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('chung_nhan_huan_luyen');\\n  r.setFilter({ nguoiLaoDongId: nldId });\\n  r.setAppends(['khoa_huan_luyen', 'ky_thi']);\\n  r.setSort(['-ngay_cap']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\n// === UI Components (VHMT-217 §6.2) ===\\nvar { Card, Row, Col, Statistic, Tag, Table, Typography, Space, Empty, Avatar, Descriptions, Badge, Divider, Button, Tooltip, Progress } = ctx.libs.antd;\\nvar { UserOutlined, BookOutlined, TrophyOutlined, FileProtectOutlined, CalendarOutlined, ReloadOutlined, SafetyCertificateOutlined, CheckCircleOutlined, ClockCircleOutlined, ExclamationCircleOutlined } = ctx.libs.antdIcons;\\nvar { useState, useCallback, useMemo } = ctx.libs.React;\\nvar dayjs = ctx.libs.dayjs;\\nvar Title = Typography.Title;\\nvar Text = Typography.Text;\\n\\n// === React Component (VHMT-217 §6.3) ===\\nfunction DashboardHV(props) {\\n  var [enrollData, setEnrollData] = useState(props.enrollments);\\n  var [examData, setExamData] = useState(props.examParticipations);\\n  var [certData, setCertData] = useState(props.certificates);\\n  var [loading, setLoading] = useState(false);\\n  var profile = props.nld;\\n\\n  var handleReload = useCallback(async function () {\\n    setLoading(true);\\n    try {\\n      var results = await Promise.all([\\n        props.reloadEnrollments(),\\n        props.reloadExams(),\\n        props.reloadCertificates()\\n      ]);\\n      setEnrollData(results[0]);\\n      setExamData(results[1]);\\n      setCertData(results[2]);\\n    } catch (e) {\\n      console.error('Reload error:', e);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, []);\\n\\n  // Computed stats\\n  var stats = useMemo(function () {\\n    var activeEnrollments = enrollData.filter(function (e) { return e.trang_thai === 'dang_hoc' || e.trang_thai === 'active'; });\\n    var completedEnrollments = enrollData.filter(function (e) { return e.trang_thai === 'hoan_thanh' || e.trang_thai === 'completed'; });\\n    var upcomingExams = examData.filter(function (e) {\\n      var exam = e.ky_thi;\\n      if (!exam) return false;\\n      var examDate = exam.ngay_thi || exam.thoi_gian_bat_dau;\\n      return examDate && dayjs(examDate).isAfter(dayjs());\\n    });\\n    var passedExams = examData.filter(function (e) { return e.ket_qua === 'dat' || e.ket_qua === 'passed'; });\\n    var activeCerts = certData.filter(function (c) { return c.trang_thai === 'hieu_luc' || c.trang_thai === 'active'; });\\n    return {\\n      totalEnrollments: enrollData.length,\\n      activeEnrollments: activeEnrollments.length,\\n      completedEnrollments: completedEnrollments.length,\\n      totalExams: examData.length,\\n      upcomingExams: upcomingExams,\\n      passedExams: passedExams.length,\\n      totalCerts: certData.length,\\n      activeCerts: activeCerts.length\\n    };\\n  }, [enrollData, examData, certData]);\\n\\n  // Unique courses from enrollments\\n  var courses = useMemo(function () {\\n    var courseMap = {};\\n    enrollData.forEach(function (e) {\\n      var lop = e.lop_hoc;\\n      if (lop && lop.khoa_huan_luyen) {\\n        var khl = lop.khoa_huan_luyen;\\n        if (!courseMap[khl.id]) {\\n          courseMap[khl.id] = {\\n            id: khl.id,\\n            ten_khoa_hoc: khl.ten_khoa_hoc,\\n            ma_khoa_hoc: khl.ma_khoa_hoc,\\n            trang_thai: khl.trang_thai,\\n            ngay_bat_dau: lop.ngay_bat_dau || khl.ngay_bat_dau,\\n            ngay_ket_thuc: lop.ngay_ket_thuc || khl.ngay_ket_thuc,\\n            lop: lop.ten_lop,\\n            ma_lop: lop.ma_lop,\\n            trang_thai_hv: e.trang_thai,\\n            diem_tong_ket: e.diem_tong_ket,\\n            ket_qua: e.ket_qua\\n          };\\n        }\\n      }\\n    });\\n    return Object.values(courseMap);\\n  }, [enrollData]);\\n\\n  if (!profile) {\\n    return (<Card>\\n      <Empty description=\\"Không tìm thấy thông tin người lao động liên kết với tài khoản này. Vui lòng liên hệ quản trị viên.\\" />\\n    </Card>);\\n  }\\n\\n  var statusColor = function (s) {\\n    var map = {\\n      'dang_hoc': 'processing', 'active': 'processing',\\n      'hoan_thanh': 'success', 'completed': 'success',\\n      'chua_bat_dau': 'default', 'pending': 'default',\\n      'tam_dung': 'warning', 'paused': 'warning',\\n      'rut': 'error', 'cancelled': 'error',\\n      'dat': 'success', 'passed': 'success',\\n      'khong_dat': 'error', 'failed': 'error',\\n      'chua_danh_gia': 'default', 'chua_co': 'default',\\n      'hieu_luc': 'success', 'het_han': 'error', 'thu_hoi': 'error',\\n      'cho_thi': 'processing', 'dang_thi': 'processing', 'da_cham': 'default',\\n      'cho_duyet': 'warning'\\n    };\\n    return map[s] || 'default';\\n  };\\n\\n  var statusText = function (s) {\\n    var map = {\\n      'dang_hoc': 'Đang học', 'active': 'Đang học',\\n      'hoan_thanh': 'Hoàn thành', 'completed': 'Hoàn thành',\\n      'chua_bat_dau': 'Chưa bắt đầu', 'pending': 'Chờ xử lý',\\n      'tam_dung': 'Tạm dừng', 'paused': 'Tạm dừng',\\n      'rut': 'Đã rút', 'cancelled': 'Đã hủy',\\n      'dat': 'Đạt', 'passed': 'Đạt',\\n      'khong_dat': 'Không đạt', 'failed': 'Không đạt',\\n      'chua_danh_gia': 'Chưa đánh giá', 'chua_co': 'Chưa có',\\n      'hieu_luc': 'Hiệu lực', 'het_han': 'Hết hạn', 'thu_hoi': 'Thu hồi',\\n      'cho_thi': 'Chờ thi', 'dang_thi': 'Đang thi', 'da_cham': 'Đã chấm',\\n      'cho_duyet': 'Chờ duyệt'\\n    };\\n    return map[s] || s || '—';\\n  };\\n\\n  var courseColumns = [\\n    { title: 'Mã lớp', dataIndex: 'ma_lop', key: 'ma_lop', width: 100 },\\n    { title: 'Tên khóa học', dataIndex: 'ten_khoa_hoc', key: 'ten_khoa_hoc', ellipsis: true },\\n    { title: 'Lớp', dataIndex: 'lop', key: 'lop', width: 120 },\\n    {\\n      title: 'Thời gian', key: 'time', width: 200,\\n      render: function (_, r) {\\n        var start = r.ngay_bat_dau ? dayjs(r.ngay_bat_dau).format('DD/MM/YYYY') : '—';\\n        var end = r.ngay_ket_thuc ? dayjs(r.ngay_ket_thuc).format('DD/MM/YYYY') : '—';\\n        return start + ' → ' + end;\\n      }\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai_hv', key: 'trang_thai_hv', width: 120,\\n      render: function (s) { return <Tag color={statusColor(s)}>{statusText(s)}</Tag>; }\\n    },\\n    {\\n      title: 'Kết quả', key: 'ket_qua', width: 100,\\n      render: function (_, r) {\\n        if (r.diem_tong_ket != null) return <Text strong>{r.diem_tong_ket}</Text>;\\n        if (r.ket_qua) return <Tag color={statusColor(r.ket_qua)}>{statusText(r.ket_qua)}</Tag>;\\n        return <Text type=\\"secondary\\">—</Text>;\\n      }\\n    }\\n  ];\\n\\n  var examColumns = [\\n    { title: 'Kỳ thi', key: 'ten', ellipsis: true, render: function (_, r) { return r.ky_thi ? r.ky_thi.ten_ky_thi : '—'; } },\\n    {\\n      title: 'Ngày thi', key: 'ngay', width: 120,\\n      render: function (_, r) {\\n        if (!r.ky_thi) return '—';\\n        var d = r.ky_thi.ngay_thi || r.ky_thi.thoi_gian_bat_dau;\\n        return d ? dayjs(d).format('DD/MM/YYYY') : '—';\\n      }\\n    },\\n    { title: 'Lần thi', dataIndex: 'lan_thi', key: 'lan_thi', width: 80, render: function (v) { return v || 1; } },\\n    {\\n      title: 'Điểm', dataIndex: 'diem', key: 'diem', width: 80,\\n      render: function (v) { return v != null ? <Text strong>{v}</Text> : <Text type=\\"secondary\\">—</Text>; }\\n    },\\n    {\\n      title: 'Kết quả', key: 'ket_qua', width: 110,\\n      render: function (_, r) {\\n        if (!r.ket_qua && !r.trang_thai) return <Text type=\\"secondary\\">—</Text>;\\n        var display = r.ket_qua || r.trang_thai;\\n        return <Tag color={statusColor(display)}>{statusText(display)}</Tag>;\\n      }\\n    }\\n  ];\\n\\n  var certColumns = [\\n    { title: 'Mã chứng nhận', dataIndex: 'ma_chung_nhan', key: 'ma', width: 140 },\\n    { title: 'Khóa huấn luyện', key: 'khoa', ellipsis: true, render: function (_, r) { return r.khoa_huan_luyen ? r.khoa_huan_luyen.ten_khoa_hoc : '—'; } },\\n    { title: 'Ngày cấp', dataIndex: 'ngay_cap', key: 'ngay_cap', width: 120, render: function (v) { return v ? dayjs(v).format('DD/MM/YYYY') : '—'; } },\\n    { title: 'Ngày hết hạn', dataIndex: 'ngay_het_han', key: 'ngay_het_han', width: 120, render: function (v) { return v ? dayjs(v).format('DD/MM/YYYY') : '—'; } },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', key: 'trang_thai', width: 110,\\n      render: function (s) {\\n        var display = s || 'hieu_luc';\\n        return <Tag color={statusColor(display)}>{statusText(display)}</Tag>;\\n      }\\n    }\\n  ];\\n\\n  return (\\n    <div style={{ padding: '0' }}>\\n      {/* Header with reload */}\\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\\n        <Title level={4} style={{ margin: 0 }}>\\n          <UserOutlined style={{ marginRight: 8 }} />\\n          Xin chào, {profile.ho_ten}\\n        </Title>\\n        <Tooltip title=\\"Tải lại dữ liệu\\">\\n          <Button icon={<ReloadOutlined />} onClick={handleReload} loading={loading} />\\n        </Tooltip>\\n      </div>\\n\\n      {/* Profile card */}\\n      <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n        <Descriptions size=\\"small\\" column={{ xs: 1, sm: 2, md: 4 }}>\\n          <Descriptions.Item label=\\"Mã NLĐ\\">{profile.ma_nguoi_lao_dong || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Số giấy tờ\\">{profile.so_giay_to || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Đơn vị\\">{profile.don_vi ? profile.don_vi.ten_don_vi || profile.don_vi.name : '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngành nghề\\">{profile.nganh_nghe ? profile.nganh_nghe.ten_nganh_nghe || profile.nganh_nghe.name : '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Email\\">{profile.email || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Điện thoại\\">{profile.dien_thoai || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc thợ\\">{profile.bac_tho ? profile.bac_tho.ten_bac || profile.bac_tho.name : '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Trạng thái HL\\">\\n            <Tag color={statusColor(profile.trang_thai_huan_luyen)}>{statusText(profile.trang_thai_huan_luyen)}</Tag>\\n          </Descriptions.Item>\\n        </Descriptions>\\n      </Card>\\n\\n      {/* Statistics row */}\\n      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>\\n        <Col xs={12} sm={6}>\\n          <Card size=\\"small\\">\\n            <Statistic title=\\"Khóa đang học\\" value={stats.activeEnrollments} prefix={<BookOutlined />} valueStyle={{ color: '#1890ff' }} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card size=\\"small\\">\\n            <Statistic title=\\"Đã hoàn thành\\" value={stats.completedEnrollments} prefix={<CheckCircleOutlined />} valueStyle={{ color: '#52c41a' }} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card size=\\"small\\">\\n            <Statistic title=\\"Lượt thi\\" value={stats.totalExams} prefix={<TrophyOutlined />} suffix={'/ ' + stats.passedExams + ' đạt'} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card size=\\"small\\">\\n            <Statistic title=\\"Chứng nhận\\" value={stats.activeCerts} prefix={<SafetyCertificateOutlined />} valueStyle={{ color: '#722ed1' }} />\\n          </Card>\\n        </Col>\\n      </Row>\\n\\n      {/* Upcoming exams */}\\n      {stats.upcomingExams.length > 0 && (\\n        <Card size=\\"small\\" title={<span><CalendarOutlined style={{ marginRight: 8 }} />Lịch thi sắp tới</span>} style={{ marginBottom: 16 }}>\\n          <Row gutter={[12, 12]}>\\n            {stats.upcomingExams.slice(0, 4).map(function (e, idx) {\\n              var exam = e.ky_thi;\\n              var examDate = exam.ngay_thi || exam.thoi_gian_bat_dau;\\n              var daysLeft = dayjs(examDate).diff(dayjs(), 'day');\\n              return (\\n                <Col xs={24} sm={12} md={6} key={e.id || idx}>\\n                  <Card size=\\"small\\" style={{ background: daysLeft <= 3 ? '#fff2f0' : '#f6ffed' }}>\\n                    <Text strong ellipsis>{exam.ten_ky_thi}</Text>\\n                    <br />\\n                    <Text type=\\"secondary\\">{dayjs(examDate).format('DD/MM/YYYY')}</Text>\\n                    <br />\\n                    <Tag color={daysLeft <= 3 ? 'red' : daysLeft <= 7 ? 'orange' : 'green'}>\\n                      {daysLeft === 0 ? 'Hôm nay' : daysLeft === 1 ? 'Ngày mai' : 'Còn ' + daysLeft + ' ngày'}\\n                    </Tag>\\n                  </Card>\\n                </Col>\\n              );\\n            })}\\n          </Row>\\n        </Card>\\n      )}\\n\\n      {/* Courses table */}\\n      <Card size=\\"small\\" title={<span><BookOutlined style={{ marginRight: 8 }} />Khóa học của tôi</span>} style={{ marginBottom: 16 }}>\\n        {courses.length > 0 ? (\\n          <Table\\n            dataSource={courses}\\n            columns={courseColumns}\\n            rowKey={function (r, idx) { return r.id || idx; }}\\n            pagination={false}\\n            size=\\"small\\"\\n            scroll={{ x: 700 }}\\n          />\\n        ) : (\\n          <Empty description=\\"Chưa tham gia khóa học nào\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n        )}\\n      </Card>\\n\\n      {/* Exams table */}\\n      <Card size=\\"small\\" title={<span><TrophyOutlined style={{ marginRight: 8 }} />Lịch sử thi</span>} style={{ marginBottom: 16 }}>\\n        {examData.length > 0 ? (\\n          <Table\\n            dataSource={examData}\\n            columns={examColumns}\\n            rowKey={function (r, idx) { return r.id || r.nguoi_lao_dong_id || idx; }}\\n            pagination={examData.length > 10 ? { pageSize: 10 } : false}\\n            size=\\"small\\"\\n            scroll={{ x: 600 }}\\n          />\\n        ) : (\\n          <Empty description=\\"Chưa có lịch sử thi\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n        )}\\n      </Card>\\n\\n      {/* Certificates table */}\\n      <Card size=\\"small\\" title={<span><SafetyCertificateOutlined style={{ marginRight: 8 }} />Chứng nhận huấn luyện</span>}>\\n        {certData.length > 0 ? (\\n          <Table\\n            dataSource={certData}\\n            columns={certColumns}\\n            rowKey={function (r, idx) { return r.id || idx; }}\\n            pagination={certData.length > 10 ? { pageSize: 10 } : false}\\n            size=\\"small\\"\\n            scroll={{ x: 600 }}\\n          />\\n        ) : (\\n          <Empty description=\\"Chưa có chứng nhận\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n        )}\\n      </Card>\\n    </div>\\n  );\\n}\\n\\n// === Render (VHMT-217 §6.4) ===\\nctx.render(\\n  <DashboardHV\\n    nld={nld}\\n    enrollments={enrollments}\\n    examParticipations={examParticipations}\\n    certificates={certificates}\\n    reloadEnrollments={reloadEnrollments}\\n    reloadExams={reloadExams}\\n    reloadCertificates={reloadCertificates}\\n  />\\n);\\n"}},"__flowSurfaceMeta":{"declaredKey":"dashboard_hoc_vien"}}}
oid5mmtiget	oid5mmtiget	{"parentId":"rmadcck9332","subKey":"grid","subType":"object","use":"BlockGridModel","props":{"rows":{"autoRow1":[["4fg6vjqolbb"]]},"sizes":{"autoRow1":[24]},"rowOrder":["autoRow1"]},"stepParams":{"gridSettings":{"grid":{"rows":{"autoRow1":[["4fg6vjqolbb"]]},"sizes":{"autoRow1":[24]},"rowOrder":["autoRow1"]}}}}
4fg6vjqolbb	4fg6vjqolbb	{"parentId":"oid5mmtiget","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v1","code":"// === LMS-03~05,08: Khóa học của tôi ===\\n// Top-level data loading (VHMT-217 §6.1)\\n\\nvar currentUser = await ctx.getVar('ctx.user');\\nvar currentUserId = currentUser ? currentUser.id : null;\\n\\n// Load nguoi_lao_dong for current user\\nvar nld = null;\\nvar nldId = null;\\nif (currentUserId) {\\n  var nldRes = ctx.makeResource('MultiRecordResource');\\n  nldRes.setResourceName('nguoi_lao_dong');\\n  nldRes.setFilter({ taiKhoanId: currentUserId });\\n  nldRes.setPageSize(1);\\n  await nldRes.refresh();\\n  var nldList = nldRes.getData() || [];\\n  nld = nldList.length > 0 ? nldList[0] : null;\\n  nldId = nld ? nld.id : null;\\n}\\n\\n// Load enrollments with class + course data\\nvar enrollments = [];\\nif (nldId) {\\n  var hvlRes = ctx.makeResource('MultiRecordResource');\\n  hvlRes.setResourceName('hoc_vien_lop');\\n  hvlRes.setFilter({ nguoiLaoDongId: nldId });\\n  hvlRes.setAppends(['lop_hoc', 'lop_hoc.khoa_huan_luyen', 'lop_hoc.buoi_hoc', 'chung_nhan', 'lich_su_diem_danh']);\\n  hvlRes.setPageSize(200);\\n  await hvlRes.refresh();\\n  enrollments = hvlRes.getData() || [];\\n}\\n\\nasync function reloadEnrollments() {\\n  if (!nldId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('hoc_vien_lop');\\n  r.setFilter({ nguoiLaoDongId: nldId });\\n  r.setAppends(['lop_hoc', 'lop_hoc.khoa_huan_luyen', 'lop_hoc.buoi_hoc', 'chung_nhan', 'lich_su_diem_danh']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function loadCourseChapters(khlId) {\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('chuong_hoc');\\n  r.setFilter({ khoaHuanLuyenId: khlId });\\n  r.setAppends(['tai_lieu_chuong_hoc']);\\n  r.setSort(['thu_tu']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function loadCourseCertificates(enrollmentId) {\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('chung_nhan_huan_luyen');\\n  r.setFilter({ hocVienLopId: enrollmentId });\\n  r.setAppends(['khoa_huan_luyen', 'ky_thi']);\\n  r.setPageSize(50);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function loadAttendance(enrollmentId) {\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('diem_danh');\\n  r.setFilter({ hocVienLopId: enrollmentId });\\n  r.setAppends(['buoi_hoc']);\\n  r.setSort(['-ngay_diem_danh']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\n// === UI Components (VHMT-217 §6.2) ===\\nvar { Card, Row, Col, Table, Tag, Typography, Space, Empty, Button, Tooltip, Descriptions, Timeline, Badge, Collapse, List, Spin, Tabs, Progress, Divider, Statistic } = ctx.libs.antd;\\nvar { BookOutlined, ArrowLeftOutlined, ReloadOutlined, SafetyCertificateOutlined, CalendarOutlined, FileTextOutlined, CheckCircleOutlined, ClockCircleOutlined, ReadOutlined, ScheduleOutlined } = ctx.libs.antdIcons;\\nvar { useState, useCallback, useMemo, useEffect } = ctx.libs.React;\\nvar dayjs = ctx.libs.dayjs;\\nvar Title = Typography.Title;\\nvar Text = Typography.Text;\\nvar Panel = Collapse.Panel;\\n\\n// === React Component (VHMT-217 §6.3) ===\\nfunction KhoaHocCuaToi(props) {\\n  var [data, setData] = useState(props.enrollments);\\n  var [loading, setLoading] = useState(false);\\n  var [view, setView] = useState('list');\\n  var [selectedEnrollment, setSelectedEnrollment] = useState(null);\\n  var [chapters, setChapters] = useState([]);\\n  var [certs, setCerts] = useState([]);\\n  var [attendance, setAttendance] = useState([]);\\n  var [detailLoading, setDetailLoading] = useState(false);\\n\\n  var handleReload = useCallback(async function () {\\n    setLoading(true);\\n    try {\\n      var newData = await props.reloadEnrollments();\\n      setData(newData);\\n    } catch (e) {\\n      console.error('Reload error:', e);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, []);\\n\\n  var handleViewCourse = useCallback(async function (enrollment) {\\n    setSelectedEnrollment(enrollment);\\n    setView('detail');\\n    setDetailLoading(true);\\n    try {\\n      var khlId = enrollment.lop_hoc && enrollment.lop_hoc.khoa_huan_luyen ? enrollment.lop_hoc.khoa_huan_luyen.id : null;\\n      var results = await Promise.all([\\n        khlId ? props.loadChapters(khlId) : Promise.resolve([]),\\n        props.loadCertificates(enrollment.id),\\n        props.loadAttendance(enrollment.id)\\n      ]);\\n      setChapters(results[0]);\\n      setCerts(results[1]);\\n      setAttendance(results[2]);\\n    } catch (e) {\\n      console.error('Load detail error:', e);\\n    } finally {\\n      setDetailLoading(false);\\n    }\\n  }, []);\\n\\n  var handleBack = useCallback(function () {\\n    setView('list');\\n    setSelectedEnrollment(null);\\n    setChapters([]);\\n    setCerts([]);\\n    setAttendance([]);\\n  }, []);\\n\\n  // C1 fix: useMemo MUST be called before any conditional return\\n  var attendanceSummary = useMemo(function () {\\n    var present = attendance.filter(function (a) { return a.trang_thai === 'co_mat'; }).length;\\n    var absent = attendance.filter(function (a) { return a.trang_thai === 'vang'; }).length;\\n    var late = attendance.filter(function (a) { return a.trang_thai === 'di_muon' || a.trang_thai === 've_som'; }).length;\\n    return { present: present, absent: absent, late: late, total: attendance.length };\\n  }, [attendance]);\\n\\n  var statusColor = function (s) {\\n    var map = {\\n      'dang_hoc': 'processing', 'active': 'processing', 'dang_dien_ra': 'processing',\\n      'hoan_thanh': 'success', 'completed': 'success',\\n      'chua_bat_dau': 'default', 'pending': 'default',\\n      'tam_dung': 'warning', 'paused': 'warning',\\n      'rut': 'error', 'cancelled': 'error',\\n      'dat': 'success', 'passed': 'success',\\n      'khong_dat': 'error', 'failed': 'error',\\n      'chua_danh_gia': 'default',\\n      'hieu_luc': 'success', 'het_han': 'error', 'thu_hoi': 'error',\\n      'co_mat': 'success', 'vang': 'error', 'di_muon': 'warning', 've_som': 'warning'\\n    };\\n    return map[s] || 'default';\\n  };\\n\\n  var statusText = function (s) {\\n    var map = {\\n      'dang_hoc': 'Đang học', 'active': 'Đang học', 'dang_dien_ra': 'Đang diễn ra',\\n      'hoan_thanh': 'Hoàn thành', 'completed': 'Hoàn thành',\\n      'chua_bat_dau': 'Chưa bắt đầu', 'pending': 'Chờ xử lý',\\n      'tam_dung': 'Tạm dừng', 'paused': 'Tạm dừng',\\n      'rut': 'Đã rút', 'cancelled': 'Đã hủy',\\n      'dat': 'Đạt', 'passed': 'Đạt',\\n      'khong_dat': 'Không đạt', 'failed': 'Không đạt',\\n      'chua_danh_gia': 'Chưa đánh giá',\\n      'hieu_luc': 'Hiệu lực', 'het_han': 'Hết hạn', 'thu_hoi': 'Thu hồi',\\n      'co_mat': 'Có mặt', 'vang': 'Vắng', 'di_muon': 'Đi muộn', 've_som': 'Về sớm'\\n    };\\n    return map[s] || s || '—';\\n  };\\n\\n  var hinhThucText = function (s) {\\n    var map = {\\n      'ket_hop': 'Kết hợp', 'truc_tuyen': 'Trực tuyến', 'truc_tiep': 'Trực tiếp',\\n      'tu_hoc': 'Tự học', 'thuc_hanh': 'Thực hành'\\n    };\\n    return map[s] || s || '—';\\n  };\\n\\n  if (!nld) {\\n    return (<Card>\\n      <Empty description=\\"Không tìm thấy thông tin người lao động liên kết với tài khoản này.\\" />\\n    </Card>);\\n  }\\n\\n  // === LIST VIEW ===\\n  if (view === 'list') {\\n    return (\\n      <div>\\n        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\\n          <Title level={4} style={{ margin: 0 }}>\\n            <BookOutlined style={{ marginRight: 8 }} />\\n            Khóa học của tôi ({data.length})\\n          </Title>\\n          <Tooltip title=\\"Tải lại\\">\\n            <Button icon={<ReloadOutlined />} onClick={handleReload} loading={loading} />\\n          </Tooltip>\\n        </div>\\n\\n        {data.length === 0 ? (\\n          <Empty description=\\"Chưa tham gia khóa học nào\\" />\\n        ) : (\\n          <Row gutter={[16, 16]}>\\n            {data.map(function (enrollment, idx) {\\n              var lop = enrollment.lop_hoc || {};\\n              var khl = lop.khoa_huan_luyen || {};\\n              var buoiHocCount = (lop.buoi_hoc || []).length;\\n              var certCount = (enrollment.chung_nhan || []).length;\\n              var attendCount = (enrollment.lich_su_diem_danh || []).length;\\n\\n              return (\\n                <Col xs={24} sm={12} lg={8} key={enrollment.id || idx}>\\n                  <Card\\n                    size=\\"small\\"\\n                    hoverable\\n                    onClick={function () { handleViewCourse(enrollment); }}\\n                    style={{ height: '100%' }}\\n                    actions={[\\n                      <span key=\\"sessions\\"><ScheduleOutlined /> {buoiHocCount} buổi</span>,\\n                      <span key=\\"attend\\"><CheckCircleOutlined /> {attendCount} điểm danh</span>,\\n                      <span key=\\"cert\\"><SafetyCertificateOutlined /> {certCount} CN</span>\\n                    ]}\\n                  >\\n                    <Card.Meta\\n                      title={<Text ellipsis={{ tooltip: khl.ten_khoa_hoc }}>{khl.ten_khoa_hoc || 'Không rõ khóa học'}</Text>}\\n                      description={\\n                        <Space direction=\\"vertical\\" size={4} style={{ width: '100%' }}>\\n                          <Text type=\\"secondary\\">Lớp: {lop.ten_lop || lop.ma_lop || '—'}</Text>\\n                          <Text type=\\"secondary\\">\\n                            {lop.ngay_bat_dau ? dayjs(lop.ngay_bat_dau).format('DD/MM/YYYY') : '—'}\\n                            {' → '}\\n                            {lop.ngay_ket_thuc ? dayjs(lop.ngay_ket_thuc).format('DD/MM/YYYY') : '—'}\\n                          </Text>\\n                          <div>\\n                            <Tag color={statusColor(enrollment.trang_thai)}>{statusText(enrollment.trang_thai)}</Tag>\\n                            {enrollment.diem_tong_ket != null && (\\n                              <Tag color=\\"blue\\">Điểm: {enrollment.diem_tong_ket}</Tag>\\n                            )}\\n                          </div>\\n                        </Space>\\n                      }\\n                    />\\n                  </Card>\\n                </Col>\\n              );\\n            })}\\n          </Row>\\n        )}\\n      </div>\\n    );\\n  }\\n\\n  // === DETAIL VIEW ===\\n  var enrollment = selectedEnrollment;\\n  var lop = enrollment.lop_hoc || {};\\n  var khl = lop.khoa_huan_luyen || {};\\n\\n  var attendanceColumns = [\\n    {\\n      title: 'Buổi học', key: 'buoi', ellipsis: true,\\n      render: function (_, r) { return r.buoi_hoc ? r.buoi_hoc.tieu_de : '—'; }\\n    },\\n    {\\n      title: 'Ngày', dataIndex: 'ngay_diem_danh', key: 'ngay', width: 110,\\n      render: function (v) { return v ? dayjs(v).format('DD/MM/YYYY') : '—'; }\\n    },\\n    {\\n      title: 'Giờ vào', dataIndex: 'gio_vao', key: 'gio_vao', width: 80,\\n      render: function (v) { return v || '—'; }\\n    },\\n    {\\n      title: 'Giờ ra', dataIndex: 'gio_ra', key: 'gio_ra', width: 80,\\n      render: function (v) { return v || '—'; }\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', key: 'trang_thai', width: 100,\\n      render: function (s) { return <Tag color={statusColor(s)}>{statusText(s)}</Tag>; }\\n    }\\n  ];\\n\\n  var certColumns = [\\n    { title: 'Mã chứng nhận', dataIndex: 'ma_chung_nhan', key: 'ma', width: 140 },\\n    {\\n      title: 'Ngày cấp', dataIndex: 'ngay_cap', key: 'ngay_cap', width: 120,\\n      render: function (v) { return v ? dayjs(v).format('DD/MM/YYYY') : '—'; }\\n    },\\n    {\\n      title: 'Ngày hết hạn', dataIndex: 'ngay_het_han', key: 'het_han', width: 120,\\n      render: function (v) { return v ? dayjs(v).format('DD/MM/YYYY') : '—'; }\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', key: 'trang_thai', width: 100,\\n      render: function (s) {\\n        var display = s || 'hieu_luc';\\n        return <Tag color={statusColor(display)}>{statusText(display)}</Tag>;\\n      }\\n    }\\n  ];\\n\\n  return (\\n    <div>\\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\\n        <Space>\\n          <Button icon={<ArrowLeftOutlined />} onClick={handleBack}>Quay lại</Button>\\n          <Title level={4} style={{ margin: 0 }}>{khl.ten_khoa_hoc || 'Chi tiết khóa học'}</Title>\\n        </Space>\\n      </div>\\n\\n      {detailLoading ? <Spin size=\\"large\\" style={{ display: 'block', margin: '40px auto' }} /> : (\\n        <div>\\n          {/* Course info */}\\n          <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n            <Descriptions size=\\"small\\" column={{ xs: 1, sm: 2, md: 3 }}>\\n              <Descriptions.Item label=\\"Mã khóa học\\">{khl.ma_khoa_hoc || '—'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Lớp\\">{lop.ten_lop || lop.ma_lop || '—'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Hình thức\\">{hinhThucText(khl.hinh_thuc || lop.hinh_thuc)}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Thời lượng\\">{khl.thoi_luong_gio ? khl.thoi_luong_gio + ' giờ' : '—'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Ngày bắt đầu\\">{lop.ngay_bat_dau ? dayjs(lop.ngay_bat_dau).format('DD/MM/YYYY') : '—'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Ngày kết thúc\\">{lop.ngay_ket_thuc ? dayjs(lop.ngay_ket_thuc).format('DD/MM/YYYY') : '—'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Giảng viên\\">{khl.giang_vien || lop.giang_vien || '—'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Địa điểm\\">{lop.dia_diem || '—'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Trạng thái\\">\\n                <Tag color={statusColor(enrollment.trang_thai)}>{statusText(enrollment.trang_thai)}</Tag>\\n              </Descriptions.Item>\\n              {enrollment.diem_tong_ket != null && (\\n                <Descriptions.Item label=\\"Điểm tổng kết\\">\\n                  <Text strong style={{ fontSize: 16 }}>{enrollment.diem_tong_ket}</Text>\\n                </Descriptions.Item>\\n              )}\\n              {enrollment.ma_ghi_danh && (\\n                <Descriptions.Item label=\\"Mã ghi danh\\">{enrollment.ma_ghi_danh}</Descriptions.Item>\\n              )}\\n            </Descriptions>\\n          </Card>\\n\\n          <Tabs defaultActiveKey=\\"chapters\\" items={[\\n            {\\n              key: 'chapters',\\n              label: <span><ReadOutlined /> Nội dung ({chapters.length})</span>,\\n              children: chapters.length > 0 ? (\\n                <Collapse accordion>\\n                  {chapters.map(function (ch, idx) {\\n                    var taiLieu = ch.tai_lieu_chuong_hoc || [];\\n                    return (\\n                      <Panel\\n                        key={ch.id || idx}\\n                        header={\\n                          <Space>\\n                            <Badge count={ch.thu_tu || idx + 1} style={{ backgroundColor: '#1890ff' }} />\\n                            <Text strong>{ch.ten_chuong}</Text>\\n                            {taiLieu.length > 0 && <Tag>{taiLieu.length} tài liệu</Tag>}\\n                          </Space>\\n                        }\\n                      >\\n                        {ch.mo_ta && <Text type=\\"secondary\\" style={{ display: 'block', marginBottom: 8 }}>{ch.mo_ta}</Text>}\\n                        {taiLieu.length > 0 ? (\\n                          <List\\n                            size=\\"small\\"\\n                            dataSource={taiLieu}\\n                            renderItem={function (tl) {\\n                              return (\\n                                <List.Item>\\n                                  <Space>\\n                                    <FileTextOutlined />\\n                                    <Text>{tl.ten_tai_lieu || tl.name || 'Tài liệu'}</Text>\\n                                  </Space>\\n                                </List.Item>\\n                              );\\n                            }}\\n                          />\\n                        ) : (\\n                          <Text type=\\"secondary\\">Chưa có tài liệu</Text>\\n                        )}\\n                      </Panel>\\n                    );\\n                  })}\\n                </Collapse>\\n              ) : (\\n                <Empty description=\\"Chưa có nội dung chương học\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n              )\\n            },\\n            {\\n              key: 'attendance',\\n              label: <span><CalendarOutlined /> Điểm danh ({attendance.length})</span>,\\n              children: (\\n                <div>\\n                  <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>\\n                    <Col xs={12} sm={6}><Card size=\\"small\\"><Statistic title=\\"Có mặt\\" value={attendanceSummary.present} valueStyle={{ color: '#52c41a' }} /></Card></Col>\\n                    <Col xs={12} sm={6}><Card size=\\"small\\"><Statistic title=\\"Vắng\\" value={attendanceSummary.absent} valueStyle={{ color: '#ff4d4f' }} /></Card></Col>\\n                    <Col xs={12} sm={6}><Card size=\\"small\\"><Statistic title=\\"Đi muộn/Về sớm\\" value={attendanceSummary.late} valueStyle={{ color: '#faad14' }} /></Card></Col>\\n                    <Col xs={12} sm={6}><Card size=\\"small\\"><Statistic title=\\"Tổng\\" value={attendanceSummary.total} /></Card></Col>\\n                  </Row>\\n                  {attendance.length > 0 ? (\\n                    <Table\\n                      dataSource={attendance}\\n                      columns={attendanceColumns}\\n                      rowKey={function (r, idx) { return r.id || idx; }}\\n                      pagination={attendance.length > 10 ? { pageSize: 10 } : false}\\n                      size=\\"small\\"\\n                    />\\n                  ) : (\\n                    <Empty description=\\"Chưa có dữ liệu điểm danh\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n                  )}\\n                </div>\\n              )\\n            },\\n            {\\n              key: 'certs',\\n              label: <span><SafetyCertificateOutlined /> Chứng nhận ({certs.length})</span>,\\n              children: certs.length > 0 ? (\\n                <Table\\n                  dataSource={certs}\\n                  columns={certColumns}\\n                  rowKey={function (r, idx) { return r.id || idx; }}\\n                  pagination={false}\\n                  size=\\"small\\"\\n                />\\n              ) : (\\n                <Empty description=\\"Chưa có chứng nhận cho khóa học này\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n              )\\n            }\\n          ]} />\\n        </div>\\n      )}\\n    </div>\\n  );\\n}\\n\\n// === Render (VHMT-217 §6.4) ===\\nctx.render(\\n  <KhoaHocCuaToi\\n    enrollments={enrollments}\\n    reloadEnrollments={reloadEnrollments}\\n    loadChapters={loadCourseChapters}\\n    loadCertificates={loadCourseCertificates}\\n    loadAttendance={loadAttendance}\\n  />\\n);\\n"}},"__flowSurfaceMeta":{"declaredKey":"khoa_hoc_cua_toi"}}}
pbcq0102f55	pbcq0102f55	{"parentId":"0druque9hwc","subKey":"grid","subType":"object","use":"BlockGridModel","props":{"rows":{"autoRow1":[["o8l21w1pqet"]]},"sizes":{"autoRow1":[24]},"rowOrder":["autoRow1"]},"stepParams":{"gridSettings":{"grid":{"rows":{"autoRow1":[["o8l21w1pqet"]]},"sizes":{"autoRow1":[24]},"rowOrder":["autoRow1"]}}}}
o8l21w1pqet	o8l21w1pqet	{"parentId":"pbcq0102f55","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v1","code":"// === LMS-06~07: Ôn luyện ===\\n// Top-level data loading (VHMT-217 §6.1)\\n\\nvar currentUser = await ctx.getVar('ctx.user');\\nvar currentUserId = currentUser ? currentUser.id : null;\\n\\n// Load nguoi_lao_dong\\nvar nld = null;\\nvar nldId = null;\\nif (currentUserId) {\\n  var nldRes = ctx.makeResource('MultiRecordResource');\\n  nldRes.setResourceName('nguoi_lao_dong');\\n  nldRes.setFilter({ taiKhoanId: currentUserId });\\n  nldRes.setAppends(['nganh_nghe', 'bac_tho']);\\n  nldRes.setPageSize(1);\\n  await nldRes.refresh();\\n  var nldList = nldRes.getData() || [];\\n  nld = nldList.length > 0 ? nldList[0] : null;\\n  nldId = nld ? nld.id : null;\\n}\\n\\n// C2 fix: filter noi_dung_on_luyen by student's nganh_nghe when available\\nvar onLuyenData = [];\\nvar onLuyenRes = ctx.makeResource('MultiRecordResource');\\nonLuyenRes.setResourceName('noi_dung_on_luyen');\\nif (nld && nld.nganh_nghe_id) {\\n  onLuyenRes.setFilter({ nganh_nghe_id: nld.nganh_nghe_id });\\n}\\nonLuyenRes.setAppends(['nganh_nghe', 'bac_tho', 'khoa_huan_luyen']);\\nonLuyenRes.setSort(['-cap_nhat_gan_nhat']);\\nonLuyenRes.setPageSize(200);\\nawait onLuyenRes.refresh();\\nonLuyenData = onLuyenRes.getData() || [];\\n\\n// H4 fix: removed dead goi_y_cau_hoi loading (was never used)\\n\\n// C3 fix: load questions WITHOUT dap_an_dung to prevent cheating\\nasync function loadQuestions(filter) {\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('cau_hoi');\\n  if (filter) r.setFilter(filter);\\n  r.setPageSize(50);\\n  await r.refresh();\\n  var data = r.getData() || [];\\n  return data.map(function(q) {\\n    var copy = Object.assign({}, q);\\n    delete copy.dap_an_dung;\\n    delete copy.giai_thich;\\n    return copy;\\n  });\\n}\\n\\n// C3 fix: separate function to load answers after submission\\nasync function loadAnswers(questionIds) {\\n  if (!questionIds || questionIds.length === 0) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('cau_hoi');\\n  r.setFilter({ id: questionIds });\\n  r.setPageSize(50);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function reloadOnLuyen() {\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('noi_dung_on_luyen');\\n  if (nld && nld.nganh_nghe_id) {\\n    r.setFilter({ nganh_nghe_id: nld.nganh_nghe_id });\\n  }\\n  r.setAppends(['nganh_nghe', 'bac_tho', 'khoa_huan_luyen']);\\n  r.setSort(['-cap_nhat_gan_nhat']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\n// === UI Components (VHMT-217 §6.2) ===\\nvar { Card, Row, Col, Table, Tag, Typography, Space, Empty, Button, Tooltip, List, Spin, Tabs, Badge, Radio, Progress, Alert, Result, Divider, Input } = ctx.libs.antd;\\nvar { FormOutlined, ReloadOutlined, BookOutlined, CheckCircleOutlined, CloseCircleOutlined, BulbOutlined, RobotOutlined, QuestionCircleOutlined, TrophyOutlined, EditOutlined } = ctx.libs.antdIcons;\\nvar { useState, useCallback, useMemo } = ctx.libs.React;\\nvar dayjs = ctx.libs.dayjs;\\nvar Title = Typography.Title;\\nvar Text = Typography.Text;\\nvar Paragraph = Typography.Paragraph;\\nvar TextArea = Input.TextArea;\\n\\n// === React Component (VHMT-217 §6.3) ===\\nfunction OnLuyen(props) {\\n  var [data, setData] = useState(props.onLuyenData);\\n  var [loading, setLoading] = useState(false);\\n  var [view, setView] = useState('list');\\n  var [selectedContent, setSelectedContent] = useState(null);\\n  var [questions, setQuestions] = useState([]);\\n  var [quizLoading, setQuizLoading] = useState(false);\\n  var [answers, setAnswers] = useState({});\\n  var [submitted, setSubmitted] = useState(false);\\n  var [score, setScore] = useState(null);\\n\\n  var handleReload = useCallback(async function () {\\n    setLoading(true);\\n    try {\\n      var newData = await props.reloadOnLuyen();\\n      setData(newData);\\n    } catch (e) {\\n      console.error('Reload error:', e);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, []);\\n\\n  var handleStartQuiz = useCallback(async function (content) {\\n    setSelectedContent(content);\\n    setView('quiz');\\n    setQuizLoading(true);\\n    setAnswers({});\\n    setSubmitted(false);\\n    setScore(null);\\n    try {\\n      var filter = {};\\n      if (content.chu_de) filter.chu_de = content.chu_de;\\n      if (content.nganh_nghe_id) filter.nganh_nghe = content.nganh_nghe_id;\\n      var qs = await props.loadQuestions(Object.keys(filter).length > 0 ? filter : null);\\n      // M3 fix: proper null check instead of falsy || 20\\n      var numQuestions = (content.so_cau_hoi != null && content.so_cau_hoi > 0) ? content.so_cau_hoi : 20;\\n      setQuestions(qs.slice(0, numQuestions));\\n    } catch (e) {\\n      console.error('Load quiz error:', e);\\n    } finally {\\n      setQuizLoading(false);\\n    }\\n  }, []);\\n\\n  var handleBack = useCallback(function () {\\n    setView('list');\\n    setSelectedContent(null);\\n    setQuestions([]);\\n    setAnswers({});\\n    setSubmitted(false);\\n    setScore(null);\\n  }, []);\\n\\n  var handleAnswer = useCallback(function (questionId, answer) {\\n    setAnswers(function (prev) {\\n      var next = Object.assign({}, prev);\\n      next[questionId] = answer;\\n      return next;\\n    });\\n  }, []);\\n\\n  // C3 fix: load answers server-side after submission for scoring\\n  var handleSubmit = useCallback(async function () {\\n    setQuizLoading(true);\\n    try {\\n      var ids = questions.map(function(q) { return q.id; });\\n      var fullQuestions = await props.loadAnswers(ids);\\n      var answerMap = {};\\n      fullQuestions.forEach(function(q) { answerMap[q.id] = q; });\\n\\n      var correct = 0;\\n      var scorableCount = 0;\\n      questions.forEach(function(q) {\\n        var full = answerMap[q.id];\\n        if (!full || !full.dap_an_dung) return;\\n        var userAnswer = answers[q.id];\\n        if (!userAnswer) return;\\n        scorableCount++;\\n        // M5 fix: use String() for type-safe comparison\\n        var correctAnswer = String(full.dap_an_dung).trim().toLowerCase();\\n        if (String(userAnswer).trim().toLowerCase() === correctAnswer) {\\n          correct++;\\n        }\\n      });\\n\\n      // Update questions with answers + explanations for review\\n      setQuestions(questions.map(function(q) {\\n        var full = answerMap[q.id];\\n        if (full) return Object.assign({}, q, { dap_an_dung: full.dap_an_dung, giai_thich: full.giai_thich });\\n        return q;\\n      }));\\n      setScore({ correct: correct, total: scorableCount > 0 ? scorableCount : questions.length });\\n      setSubmitted(true);\\n    } catch (e) {\\n      console.error('Submit error:', e);\\n    } finally {\\n      setQuizLoading(false);\\n    }\\n  }, [questions, answers]);\\n\\n  var statusColor = function (s) {\\n    var map = {\\n      'active': 'processing', 'chua_lam': 'default', 'da_lam': 'success',\\n      'dat': 'success', 'khong_dat': 'error'\\n    };\\n    return map[s] || 'default';\\n  };\\n\\n  var statusText = function (s) {\\n    var map = {\\n      'active': 'Đang mở', 'chua_lam': 'Chưa làm', 'da_lam': 'Đã làm',\\n      'dat': 'Đạt', 'khong_dat': 'Không đạt'\\n    };\\n    return map[s] || s || '—';\\n  };\\n\\n  var difficultyColor = function (d) {\\n    var map = { 'de': 'green', 'trung_binh': 'orange', 'kho': 'red' };\\n    return map[d] || 'default';\\n  };\\n\\n  var difficultyText = function (d) {\\n    var map = { 'de': 'Dễ', 'trung_binh': 'Trung bình', 'kho': 'Khó' };\\n    return map[d] || d || '';\\n  };\\n\\n  if (!nld) {\\n    return (<Card>\\n      <Empty description=\\"Không tìm thấy thông tin người lao động liên kết với tài khoản này.\\" />\\n    </Card>);\\n  }\\n\\n  // === QUIZ VIEW ===\\n  if (view === 'quiz') {\\n    // H5 fix: diem_dat as percentage — compute threshold from total\\n    var passThreshold = selectedContent && selectedContent.diem_dat\\n      ? Math.ceil(questions.length * selectedContent.diem_dat / 100)\\n      : Math.ceil(questions.length * 0.5);\\n\\n    return (\\n      <div>\\n        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\\n          <Space>\\n            <Button onClick={handleBack}>← Quay lại</Button>\\n            <Title level={4} style={{ margin: 0 }}>\\n              {selectedContent ? selectedContent.ten_noi_dung : 'Ôn luyện'}\\n            </Title>\\n          </Space>\\n          {!submitted && questions.length > 0 && (\\n            <Space>\\n              <Text type=\\"secondary\\">Đã trả lời: {Object.keys(answers).length}/{questions.length}</Text>\\n              <Button type=\\"primary\\" onClick={handleSubmit} disabled={Object.keys(answers).length === 0} loading={quizLoading}>\\n                Nộp bài\\n              </Button>\\n            </Space>\\n          )}\\n        </div>\\n\\n        {quizLoading && !submitted ? <Spin size=\\"large\\" style={{ display: 'block', margin: '40px auto' }} /> : (\\n          <div>\\n            {submitted && score && (\\n              <Result\\n                status={score.correct >= passThreshold ? 'success' : 'warning'}\\n                title={score.correct + '/' + score.total + ' câu đúng'}\\n                subTitle={\\n                  score.correct >= passThreshold\\n                    ? 'Chúc mừng! Bạn đã đạt yêu cầu.'\\n                    : 'Bạn chưa đạt yêu cầu (cần đạt ' + passThreshold + '/' + questions.length + '). Hãy ôn luyện thêm.'\\n                }\\n                extra={[\\n                  <Button key=\\"retry\\" type=\\"primary\\" onClick={function () { handleStartQuiz(selectedContent); }}>Làm lại</Button>,\\n                  <Button key=\\"back\\" onClick={handleBack}>Quay lại danh sách</Button>\\n                ]}\\n                style={{ marginBottom: 16 }}\\n              />\\n            )}\\n\\n            {questions.length === 0 ? (\\n              <Empty description=\\"Chưa có câu hỏi cho nội dung này\\" />\\n            ) : (\\n              <List\\n                dataSource={questions}\\n                renderItem={function (q, idx) {\\n                  var optionsList = [];\\n                  try {\\n                    if (q.dap_an) {\\n                      var parsed = typeof q.dap_an === 'string' ? JSON.parse(q.dap_an) : q.dap_an;\\n                      if (Array.isArray(parsed)) {\\n                        optionsList = parsed;\\n                      }\\n                    }\\n                  } catch (e) {\\n                    if (typeof q.dap_an === 'string') {\\n                      var parts = q.dap_an.split('\\\\n').filter(function (o) { return o.trim(); });\\n                      if (parts.length <= 1 && q.dap_an.indexOf(';') !== -1) {\\n                        parts = q.dap_an.split(';').map(function (o) { return o.trim(); }).filter(function (o) { return o; });\\n                      }\\n                      optionsList = parts;\\n                    }\\n                  }\\n\\n                  var isEssay = optionsList.length === 0;\\n\\n                  // M5 fix: use String() for type-safe comparison\\n                  var isCorrect = submitted && answers[q.id] && q.dap_an_dung &&\\n                    String(answers[q.id]).trim().toLowerCase() === String(q.dap_an_dung).trim().toLowerCase();\\n\\n                  return (\\n                    <Card\\n                      size=\\"small\\"\\n                      style={{\\n                        marginBottom: 12,\\n                        borderLeft: submitted ? (isCorrect ? '3px solid #52c41a' : (answers[q.id] ? '3px solid #ff4d4f' : '3px solid #d9d9d9')) : 'none'\\n                      }}\\n                    >\\n                      <Space direction=\\"vertical\\" style={{ width: '100%' }}>\\n                        <Space>\\n                          <Badge count={idx + 1} style={{ backgroundColor: '#1890ff' }} />\\n                          <Text strong>{q.noi_dung || q.ten_cau_hoi}</Text>\\n                          {q.muc_do_kho && <Tag color={difficultyColor(q.muc_do_kho)}>{difficultyText(q.muc_do_kho)}</Tag>}\\n                          {isEssay && <Tag icon={<EditOutlined />}>Tự luận</Tag>}\\n                        </Space>\\n\\n                        {!isEssay ? (\\n                          <Radio.Group\\n                            value={answers[q.id]}\\n                            onChange={function (e) { handleAnswer(q.id, e.target.value); }}\\n                            disabled={submitted}\\n                          >\\n                            <Space direction=\\"vertical\\">\\n                              {optionsList.map(function (opt, optIdx) {\\n                                var optValue = typeof opt === 'object' ? (opt.value || opt.label || opt.text || String(optIdx)) : String(opt);\\n                                var optLabel = typeof opt === 'object' ? (opt.label || opt.text || opt.value || 'Lựa chọn ' + (optIdx + 1)) : String(opt);\\n                                return (\\n                                  <Radio key={optIdx} value={optValue}>\\n                                    {optLabel}\\n                                    {submitted && q.dap_an_dung && String(optValue).trim().toLowerCase() === String(q.dap_an_dung).trim().toLowerCase() && (\\n                                      <CheckCircleOutlined style={{ color: '#52c41a', marginLeft: 8 }} />\\n                                    )}\\n                                  </Radio>\\n                                );\\n                              })}\\n                            </Space>\\n                          </Radio.Group>\\n                        ) : (\\n                          // M4 fix: add TextArea input for essay questions\\n                          <div>\\n                            <TextArea\\n                              rows={3}\\n                              placeholder=\\"Nhập câu trả lời của bạn...\\"\\n                              value={answers[q.id] || ''}\\n                              onChange={function (e) { handleAnswer(q.id, e.target.value); }}\\n                              disabled={submitted}\\n                            />\\n                            {submitted && (\\n                              <Alert\\n                                type=\\"info\\"\\n                                message=\\"Câu tự luận cần giảng viên chấm thủ công\\"\\n                                style={{ marginTop: 8 }}\\n                              />\\n                            )}\\n                          </div>\\n                        )}\\n\\n                        {submitted && q.giai_thich && (\\n                          <Alert type=\\"info\\" message={<span><BulbOutlined /> {q.giai_thich}</span>} style={{ marginTop: 8 }} />\\n                        )}\\n                      </Space>\\n                    </Card>\\n                  );\\n                }}\\n              />\\n            )}\\n          </div>\\n        )}\\n      </div>\\n    );\\n  }\\n\\n  // === LIST VIEW ===\\n  return (\\n    <div>\\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\\n        <Title level={4} style={{ margin: 0 }}>\\n          <FormOutlined style={{ marginRight: 8 }} />\\n          Ôn luyện\\n        </Title>\\n        <Tooltip title=\\"Tải lại\\">\\n          <Button icon={<ReloadOutlined />} onClick={handleReload} loading={loading} />\\n        </Tooltip>\\n      </div>\\n\\n      {/* AI Practice placeholder */}\\n      <Card size=\\"small\\" style={{ marginBottom: 16, background: '#f0f5ff', borderColor: '#adc6ff' }}>\\n        <Space>\\n          <RobotOutlined style={{ fontSize: 24, color: '#1890ff' }} />\\n          <div>\\n            <Text strong>Ôn luyện với AI</Text>\\n            <br />\\n            <Text type=\\"secondary\\">Tính năng đang phát triển — AI sẽ tạo câu hỏi cá nhân hóa dựa trên ngành nghề và tiến độ học tập của bạn.</Text>\\n          </div>\\n          <Button disabled>Sắp ra mắt</Button>\\n        </Space>\\n      </Card>\\n\\n      {data.length === 0 ? (\\n        <Empty description=\\"Chưa có nội dung ôn luyện\\" />\\n      ) : (\\n        <Row gutter={[16, 16]}>\\n          {data.map(function (item, idx) {\\n            var khl = item.khoa_huan_luyen;\\n            var nn = item.nganh_nghe;\\n            return (\\n              <Col xs={24} sm={12} lg={8} key={item.id || idx}>\\n                <Card\\n                  size=\\"small\\"\\n                  hoverable\\n                  actions={[\\n                    <Button key=\\"start\\" type=\\"link\\" onClick={function () { handleStartQuiz(item); }}>\\n                      <FormOutlined /> Làm bài\\n                    </Button>\\n                  ]}\\n                >\\n                  <Card.Meta\\n                    avatar={<QuestionCircleOutlined style={{ fontSize: 24, color: '#1890ff' }} />}\\n                    title={<Text ellipsis={{ tooltip: item.ten_noi_dung }}>{item.ten_noi_dung}</Text>}\\n                    description={\\n                      <Space direction=\\"vertical\\" size={4} style={{ width: '100%' }}>\\n                        {item.chu_de && <Text type=\\"secondary\\">Chủ đề: {item.chu_de}</Text>}\\n                        {nn && <Text type=\\"secondary\\">Ngành: {nn.ten_nganh_nghe || nn.name}</Text>}\\n                        {khl && <Text type=\\"secondary\\">Khóa: {khl.ten_khoa_hoc}</Text>}\\n                        <Space>\\n                          <Tag>{item.so_cau_hoi != null ? item.so_cau_hoi : '—'} câu</Tag>\\n                          {item.so_lan_da_lam > 0 && <Tag color=\\"blue\\">Đã làm {item.so_lan_da_lam} lần</Tag>}\\n                          {item.ket_qua_gan_nhat && (\\n                            <Tag color={statusColor(item.ket_qua_gan_nhat)}>{statusText(item.ket_qua_gan_nhat)}</Tag>\\n                          )}\\n                        </Space>\\n                        {item.cap_nhat_gan_nhat && (\\n                          <Text type=\\"secondary\\" style={{ fontSize: 12 }}>\\n                            Cập nhật: {dayjs(item.cap_nhat_gan_nhat).format('DD/MM/YYYY')}\\n                          </Text>\\n                        )}\\n                      </Space>\\n                    }\\n                  />\\n                </Card>\\n              </Col>\\n            );\\n          })}\\n        </Row>\\n      )}\\n    </div>\\n  );\\n}\\n\\n// === Render (VHMT-217 §6.4) ===\\nctx.render(\\n  <OnLuyen\\n    onLuyenData={onLuyenData}\\n    reloadOnLuyen={reloadOnLuyen}\\n    loadQuestions={loadQuestions}\\n    loadAnswers={loadAnswers}\\n  />\\n);\\n"}},"__flowSurfaceMeta":{"declaredKey":"on_luyen_hoc_vien"}}}
