371dlxk1hdr	371dlxk1hdr	{"parentId":"ybhdq924r1b","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// === LMS-13, LMS-40: Kết quả thi ===\\n\\nvar currentUser = await ctx.getVar('ctx.user');\\nvar currentUserId = currentUser ? currentUser.id : null;\\n\\nvar nld = null;\\nvar nldId = null;\\nif (currentUserId) {\\n  var nldRes = ctx.makeResource('MultiRecordResource');\\n  nldRes.setResourceName('nguoi_lao_dong');\\n  nldRes.setFilter({ taiKhoanId: currentUserId });\\n  nldRes.setAppends(['nganh_nghe', 'bac_tho']);\\n  nldRes.setPageSize(1);\\n  await nldRes.refresh();\\n  var nldList = nldRes.getData() || [];\\n  nld = nldList.length > 0 ? nldList[0] : null;\\n  nldId = nld ? nld.id : null;\\n}\\n\\nvar resultsData = [];\\nif (nldId) {\\n  var kttsRes = ctx.makeResource('MultiRecordResource');\\n  kttsRes.setResourceName('ky_thi_thi_sinh');\\n  kttsRes.setFilter({ nguoi_lao_dong_id: nldId });\\n  kttsRes.setAppends(['ky_thi', 'ky_thi.de_thi', 'ky_thi.nganh_nghe', 'ky_thi.don_vi', 'nguoi_cham', 'nguoi_duyet']);\\n  kttsRes.setSort(['-createdAt']);\\n  kttsRes.setPageSize(200);\\n  await kttsRes.refresh();\\n  resultsData = kttsRes.getData() || [];\\n}\\n\\nasync function reloadResults() {\\n  if (!nldId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('ky_thi_thi_sinh');\\n  r.setFilter({ nguoi_lao_dong_id: nldId });\\n  r.setAppends(['ky_thi', 'ky_thi.de_thi', 'ky_thi.nganh_nghe', 'ky_thi.don_vi', 'nguoi_cham', 'nguoi_duyet']);\\n  r.setSort(['-createdAt']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function loadBaiLam(kyThiId, thiSinhId) {\\n  if (!kyThiId || !thiSinhId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('bai_lam_ky_thi');\\n  r.setFilter({ ky_thi_id: kyThiId, thi_sinh_id: thiSinhId });\\n  r.setAppends(['nguoi_cham']);\\n  r.setSort(['-createdAt']);\\n  r.setPageSize(50);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nvar { Card, Row, Col, Table, Tag, Typography, Space, Empty, Button, Tooltip, Spin, Badge, Tabs, Statistic, Descriptions, Timeline, Alert, List, Progress, Divider } = ctx.libs.antd;\\nvar { TrophyOutlined, ReloadOutlined, CheckCircleOutlined, CloseCircleOutlined, ClockCircleOutlined, FileTextOutlined, InfoCircleOutlined } = ctx.libs.antdIcons;\\nvar { useState, useCallback } = ctx.libs.React;\\nvar dayjs = ctx.libs.dayjs;\\nvar Title = Typography.Title;\\nvar Text = Typography.Text;\\nvar Paragraph = Typography.Paragraph;\\n\\nvar trangThaiColor = function(s) {\\n  var map = {\\n    'cho_thi': 'processing', 'da_xep_lich': 'cyan',\\n    'da_nop_bai': 'blue', 'da_nop': 'blue',\\n    'dang_cham': 'orange', 'cho_duyet': 'gold',\\n    'dat': 'success', 'khong_dat': 'error'\\n  };\\n  return map[s] || 'default';\\n};\\n\\nvar trangThaiText = function(s) {\\n  var map = {\\n    'cho_thi': 'Chờ thi', 'da_xep_lich': 'Đã xếp lịch',\\n    'da_nop_bai': 'Đã nộp bài', 'da_nop': 'Đã nộp bài',\\n    'dang_cham': 'Đang chấm', 'cho_duyet': 'Chờ duyệt',\\n    'dat': 'Đạt', 'khong_dat': 'Không đạt'\\n  };\\n  return map[s] || s || '—';\\n};\\n\\nvar ketQuaText = function(s) {\\n  var map = { 'chua_co': 'Chưa có', 'dat': 'Đạt', 'khong_dat': 'Không đạt' };\\n  return map[s] || s || '—';\\n};\\n\\nvar trangThaiChamText = function(s) {\\n  var map = {\\n    'chua_cham': 'Chưa chấm', 'dang_cham': 'Đang chấm', 'da_cham': 'Đã chấm',\\n    'cho_duyet': 'Chờ duyệt', 'da_duyet': 'Đã duyệt', 'tra_lai': 'Trả lại',\\n    'da_khoa': 'Đã khóa', 'da_cong_bo': 'Đã công bố'\\n  };\\n  return map[s] || s || '—';\\n};\\n\\nfunction KetQuaThi(props) {\\n  var [data, setData] = useState(props.resultsData);\\n  var [loading, setLoading] = useState(false);\\n  var [selectedItem, setSelectedItem] = useState(null);\\n  var [baiLamList, setBaiLamList] = useState([]);\\n  var [detailLoading, setDetailLoading] = useState(false);\\n\\n  var handleReload = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await props.reloadResults();\\n      setData(newData);\\n    } catch(e) {\\n      console.error('Reload error:', e);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, []);\\n\\n  var handleViewDetail = useCallback(async function(item) {\\n    setSelectedItem(item);\\n    setDetailLoading(true);\\n    try {\\n      var kt = item.ky_thi || {};\\n      var baiLam = await props.loadBaiLam(kt.id, nldId);\\n      setBaiLamList(baiLam);\\n    } catch(e) {\\n      console.error('Load detail error:', e);\\n    } finally {\\n      setDetailLoading(false);\\n    }\\n  }, []);\\n\\n  var handleBack = useCallback(function() {\\n    setSelectedItem(null);\\n    setBaiLamList([]);\\n  }, []);\\n\\n  if (!nld) {\\n    return (<Card>\\n      <Empty description=\\"Không tìm thấy thông tin người lao động liên kết với tài khoản này.\\" />\\n    </Card>);\\n  }\\n\\n  // === CHI TIẾT KẾT QUẢ ===\\n  if (selectedItem) {\\n    var kt = selectedItem.ky_thi || {};\\n    var deThi = kt.de_thi || {};\\n    var nn = kt.nganh_nghe;\\n    var diemDat = deThi.diem_dat || kt.diem_dat || 5;\\n\\n    return (\\n      <div>\\n        <Button onClick={handleBack} style={{ marginBottom: 16 }}>← Quay lại</Button>\\n\\n        <Card title={\\n          <Space>\\n            <TrophyOutlined style={{ color: '#1890ff' }} />\\n            <span>{kt.ten_ky_thi || 'Kỳ thi'}</span>\\n          </Space>\\n        } style={{ marginBottom: 16 }}>\\n          <Descriptions column={{ xs: 1, sm: 2, md: 3 }} bordered size=\\"small\\">\\n            <Descriptions.Item label=\\"Ngành nghề\\">{nn ? (nn.ten_nganh_nghe || nn.name) : '—'}</Descriptions.Item>\\n            <Descriptions.Item label=\\"Đề thi\\">{deThi.ten_de_thi || '—'}</Descriptions.Item>\\n            <Descriptions.Item label=\\"Thời gian làm bài\\">{deThi.thoi_gian_lam_bai || '—'} phút</Descriptions.Item>\\n            <Descriptions.Item label=\\"Điểm đạt\\">{diemDat}/10</Descriptions.Item>\\n            <Descriptions.Item label=\\"Lần thi\\">{selectedItem.lan_thi || 1}</Descriptions.Item>\\n            <Descriptions.Item label=\\"Trạng thái\\">\\n              <Tag color={trangThaiColor(selectedItem.trang_thai)}>{trangThaiText(selectedItem.trang_thai)}</Tag>\\n            </Descriptions.Item>\\n          </Descriptions>\\n        </Card>\\n\\n        <Row gutter={16} style={{ marginBottom: 16 }}>\\n          <Col xs={24} sm={8}>\\n            <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n              <Statistic title=\\"Điểm\\" value={selectedItem.diem != null ? selectedItem.diem : '—'}\\n                suffix={selectedItem.diem != null ? '/10' : ''}\\n                valueStyle={{ color: selectedItem.diem != null && selectedItem.diem >= diemDat ? '#52c41a' : '#ff4d4f' }} />\\n            </Card>\\n          </Col>\\n          <Col xs={24} sm={8}>\\n            <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n              <Statistic title=\\"Kết quả\\" value={ketQuaText(selectedItem.ket_qua)}\\n                valueStyle={{ color: selectedItem.ket_qua === 'dat' ? '#52c41a' : selectedItem.ket_qua === 'khong_dat' ? '#ff4d4f' : '#8c8c8c' }} />\\n            </Card>\\n          </Col>\\n          <Col xs={24} sm={8}>\\n            <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n              <Statistic title=\\"Trạng thái chấm\\" value={trangThaiText(selectedItem.trang_thai)} />\\n            </Card>\\n          </Col>\\n        </Row>\\n\\n        {/* LMS-40: Auto-grading notification */}\\n        {(selectedItem.trang_thai === 'da_nop_bai' || selectedItem.trang_thai === 'da_nop' || selectedItem.trang_thai === 'dang_cham') && (!selectedItem.ket_qua || selectedItem.ket_qua === 'chua_co') && (\\n          <Alert\\n            type=\\"info\\"\\n            icon={<ClockCircleOutlined />}\\n            showIcon\\n            message=\\"Bài thi đang được chấm điểm\\"\\n            description=\\"Hệ thống sẽ tự động chấm điểm phần trắc nghiệm. Phần tự luận sẽ do giảng viên chấm thủ công. Kết quả sẽ được cập nhật khi quá trình chấm hoàn tất.\\"\\n            style={{ marginBottom: 16 }}\\n          />\\n        )}\\n\\n        {/* Bài làm đã nộp */}\\n        <Card title=\\"Bài làm đã nộp\\" size=\\"small\\" loading={detailLoading}>\\n          {baiLamList.length === 0 ? (\\n            <Empty description=\\"Chưa có bài làm nào được ghi nhận\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n          ) : (\\n            <List\\n              dataSource={baiLamList}\\n              renderItem={function(bl) {\\n                return (\\n                  <List.Item>\\n                    <List.Item.Meta\\n                      avatar={<FileTextOutlined style={{ fontSize: 24, color: '#1890ff' }} />}\\n                      title={\\n                        <Space>\\n                          <Text>{bl.title || 'Bài làm'}</Text>\\n                          <Tag color={bl.trang_thai_cham === 'da_cham' || bl.trang_thai_cham === 'da_cong_bo' ? 'green' : 'processing'}>\\n                            {trangThaiChamText(bl.trang_thai_cham)}\\n                          </Tag>\\n                        </Space>\\n                      }\\n                      description={\\n                        <Space direction=\\"vertical\\" size={2}>\\n                          {bl.diem != null && <Text>Điểm: <Text strong>{bl.diem}</Text></Text>}\\n                          {bl.ket_qua && bl.ket_qua !== 'chua_xac_dinh' && (\\n                            <Tag color={bl.ket_qua === 'dat' ? 'green' : 'red'}>{ketQuaText(bl.ket_qua)}</Tag>\\n                          )}\\n                          {bl.nhan_xet && <Text type=\\"secondary\\">Nhận xét: {bl.nhan_xet}</Text>}\\n                          {bl.nguoi_cham && <Text type=\\"secondary\\">Người chấm: {bl.nguoi_cham.nickname || bl.nguoi_cham.username || '—'}</Text>}\\n                          {bl.createdAt && <Text type=\\"secondary\\">Ngày nộp: {dayjs(bl.createdAt).format('HH:mm DD/MM/YYYY')}</Text>}\\n                        </Space>\\n                      }\\n                    />\\n                  </List.Item>\\n                );\\n              }}\\n            />\\n          )}\\n        </Card>\\n      </div>\\n    );\\n  }\\n\\n  // === DANH SÁCH KẾT QUẢ ===\\n  var coKetQua = data.filter(function(d) {\\n    return d.ket_qua && d.ket_qua !== 'chua_co';\\n  });\\n  var dangCho = data.filter(function(d) {\\n    return !d.ket_qua || d.ket_qua === 'chua_co';\\n  });\\n\\n  // Stats\\n  var totalExams = data.length;\\n  var passCount = data.filter(function(d) { return d.ket_qua === 'dat'; }).length;\\n  var failCount = data.filter(function(d) { return d.ket_qua === 'khong_dat'; }).length;\\n  var waitCount = data.filter(function(d) { return !d.ket_qua || d.ket_qua === 'chua_co'; }).length;\\n\\n  return (\\n    <div>\\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\\n        <Title level={4} style={{ margin: 0 }}>\\n          <TrophyOutlined style={{ marginRight: 8 }} />\\n          Kết quả thi\\n        </Title>\\n        <Tooltip title=\\"Tải lại\\">\\n          <Button icon={<ReloadOutlined />} onClick={handleReload} loading={loading} />\\n        </Tooltip>\\n      </div>\\n\\n      {data.length === 0 ? (\\n        <Empty description=\\"Chưa có kết quả thi nào\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n      ) : (\\n        <div>\\n          {/* Thống kê tổng quan */}\\n          <Row gutter={16} style={{ marginBottom: 24 }}>\\n            <Col xs={12} sm={6}>\\n              <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n                <Statistic title=\\"Tổng kỳ thi\\" value={totalExams} />\\n              </Card>\\n            </Col>\\n            <Col xs={12} sm={6}>\\n              <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n                <Statistic title=\\"Đạt\\" value={passCount} valueStyle={{ color: '#52c41a' }} />\\n              </Card>\\n            </Col>\\n            <Col xs={12} sm={6}>\\n              <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n                <Statistic title=\\"Không đạt\\" value={failCount} valueStyle={{ color: '#ff4d4f' }} />\\n              </Card>\\n            </Col>\\n            <Col xs={12} sm={6}>\\n              <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n                <Statistic title=\\"Chờ kết quả\\" value={waitCount} valueStyle={{ color: '#faad14' }} />\\n              </Card>\\n            </Col>\\n          </Row>\\n\\n          {/* Danh sách đang chờ kết quả */}\\n          {dangCho.length > 0 && (\\n            <div style={{ marginBottom: 24 }}>\\n              <Title level={5}><ClockCircleOutlined style={{ marginRight: 8 }} />Đang chờ kết quả ({dangCho.length})</Title>\\n              <Row gutter={[16, 16]}>\\n                {dangCho.map(function(item, idx) {\\n                  var kt = item.ky_thi || {};\\n                  var nn = kt.nganh_nghe;\\n                  return (\\n                    <Col xs={24} sm={12} lg={8} key={item.id || idx}>\\n                      <Card size=\\"small\\" hoverable onClick={function() { handleViewDetail(item); }}>\\n                        <Card.Meta\\n                          avatar={<ClockCircleOutlined style={{ fontSize: 24, color: '#faad14' }} />}\\n                          title={<Text ellipsis={{ tooltip: kt.ten_ky_thi }}>{kt.ten_ky_thi || '—'}</Text>}\\n                          description={\\n                            <Space direction=\\"vertical\\" size={4} style={{ width: '100%' }}>\\n                              {nn && <Text type=\\"secondary\\">Ngành: {nn.ten_nganh_nghe || nn.name}</Text>}\\n                              <Space>\\n                                <Tag color={trangThaiColor(item.trang_thai)}>{trangThaiText(item.trang_thai)}</Tag>\\n                                {item.lan_thi > 1 && <Tag color=\\"orange\\">Lần {item.lan_thi}</Tag>}\\n                              </Space>\\n                            </Space>\\n                          }\\n                        />\\n                      </Card>\\n                    </Col>\\n                  );\\n                })}\\n              </Row>\\n            </div>\\n          )}\\n\\n          {/* Danh sách có kết quả */}\\n          {coKetQua.length > 0 && (\\n            <div>\\n              <Title level={5}><CheckCircleOutlined style={{ marginRight: 8 }} />Đã có kết quả ({coKetQua.length})</Title>\\n              <Row gutter={[16, 16]}>\\n                {coKetQua.map(function(item, idx) {\\n                  var kt = item.ky_thi || {};\\n                  var nn = kt.nganh_nghe;\\n                  return (\\n                    <Col xs={24} sm={12} lg={8} key={item.id || idx}>\\n                      <Card size=\\"small\\" hoverable onClick={function() { handleViewDetail(item); }}\\n                        style={{ borderLeft: item.ket_qua === 'dat' ? '3px solid #52c41a' : '3px solid #ff4d4f' }}>\\n                        <Card.Meta\\n                          avatar={\\n                            item.ket_qua === 'dat'\\n                              ? <CheckCircleOutlined style={{ fontSize: 24, color: '#52c41a' }} />\\n                              : <CloseCircleOutlined style={{ fontSize: 24, color: '#ff4d4f' }} />\\n                          }\\n                          title={<Text ellipsis={{ tooltip: kt.ten_ky_thi }}>{kt.ten_ky_thi || '—'}</Text>}\\n                          description={\\n                            <Space direction=\\"vertical\\" size={4} style={{ width: '100%' }}>\\n                              {nn && <Text type=\\"secondary\\">Ngành: {nn.ten_nganh_nghe || nn.name}</Text>}\\n                              <Space>\\n                                <Tag color={item.ket_qua === 'dat' ? 'green' : 'red'}>{ketQuaText(item.ket_qua)}</Tag>\\n                                {item.diem != null && <Tag color=\\"blue\\">Điểm: {item.diem}</Tag>}\\n                                {item.lan_thi > 1 && <Tag color=\\"orange\\">Lần {item.lan_thi}</Tag>}\\n                              </Space>\\n                            </Space>\\n                          }\\n                        />\\n                      </Card>\\n                    </Col>\\n                  );\\n                })}\\n              </Row>\\n            </div>\\n          )}\\n        </div>\\n      )}\\n    </div>\\n  );\\n}\\n\\nctx.render(\\n  <KetQuaThi\\n    resultsData={resultsData}\\n    reloadResults={reloadResults}\\n    loadBaiLam={loadBaiLam}\\n  />\\n);\\n"}}}}
yquk5lmw8oz	yquk5lmw8oz	{"parentId":"0fbglb0y0bs","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// === LMS-09~12: Thi trực tuyến ===\\n\\nvar currentUser = await ctx.getVar('ctx.user');\\nvar currentUserId = currentUser ? currentUser.id : null;\\n\\nvar nld = null;\\nvar nldId = null;\\nif (currentUserId) {\\n  var nldRes = ctx.makeResource('MultiRecordResource');\\n  nldRes.setResourceName('nguoi_lao_dong');\\n  nldRes.setFilter({ taiKhoanId: currentUserId });\\n  nldRes.setAppends(['nganh_nghe', 'bac_tho']);\\n  nldRes.setPageSize(1);\\n  await nldRes.refresh();\\n  var nldList = nldRes.getData() || [];\\n  nld = nldList.length > 0 ? nldList[0] : null;\\n  nldId = nld ? nld.id : null;\\n}\\n\\n// Load exam enrollments for this student\\nvar examData = [];\\nif (nldId) {\\n  var kttsRes = ctx.makeResource('MultiRecordResource');\\n  kttsRes.setResourceName('ky_thi_thi_sinh');\\n  kttsRes.setFilter({ nguoi_lao_dong_id: nldId });\\n  kttsRes.setAppends(['ky_thi', 'ky_thi.de_thi', 'ky_thi.nganh_nghe', 'ky_thi.don_vi']);\\n  kttsRes.setSort(['-createdAt']);\\n  kttsRes.setPageSize(200);\\n  await kttsRes.refresh();\\n  examData = kttsRes.getData() || [];\\n}\\n\\nasync function reloadExams() {\\n  if (!nldId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('ky_thi_thi_sinh');\\n  r.setFilter({ nguoi_lao_dong_id: nldId });\\n  r.setAppends(['ky_thi', 'ky_thi.de_thi', 'ky_thi.nganh_nghe', 'ky_thi.don_vi']);\\n  r.setSort(['-createdAt']);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function loadExamQuestions(deThiId) {\\n  if (!deThiId) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('cau_hoi');\\n  r.setFilter({});\\n  r.setAppends([]);\\n  r.setPageSize(200);\\n  await r.refresh();\\n  var allQuestions = r.getData() || [];\\n\\n  // Load de_thi with its cau_hoi association to get question IDs\\n  var dtRes = ctx.makeResource('MultiRecordResource');\\n  dtRes.setResourceName('de_thi');\\n  dtRes.setFilter({ id: deThiId });\\n  dtRes.setAppends(['cau_hoi']);\\n  dtRes.setPageSize(1);\\n  await dtRes.refresh();\\n  var dtData = dtRes.getData() || [];\\n  if (dtData.length === 0) return allQuestions;\\n\\n  var examQuestions = dtData[0].cau_hoi || [];\\n  if (examQuestions.length > 0) {\\n    return examQuestions.map(function(q) {\\n      var copy = Object.assign({}, q);\\n      delete copy.dap_an_dung;\\n      delete copy.giai_thich;\\n      return copy;\\n    });\\n  }\\n  return allQuestions.map(function(q) {\\n    var copy = Object.assign({}, q);\\n    delete copy.dap_an_dung;\\n    delete copy.giai_thich;\\n    return copy;\\n  });\\n}\\n\\nasync function loadAnswers(questionIds) {\\n  if (!questionIds || questionIds.length === 0) return [];\\n  var r = ctx.makeResource('MultiRecordResource');\\n  r.setResourceName('cau_hoi');\\n  r.setFilter({ id: questionIds });\\n  r.setPageSize(200);\\n  await r.refresh();\\n  return r.getData() || [];\\n}\\n\\nasync function saveExamResult(kyThiId, resultData) {\\n  if (!kyThiId || !nldId) return { ok: false, error: 'Thiếu thông tin kỳ thi' };\\n  try {\\n    var filterStr = JSON.stringify({ nguoi_lao_dong_id: nldId, ky_thi_id: kyThiId });\\n    var token = localStorage.getItem('NOCOBASE_TOKEN');\\n    var headers = { 'Content-Type': 'application/json' };\\n    if (token) headers['Authorization'] = 'Bearer ' + token;\\n    var resp = await fetch('/api/ky_thi_thi_sinh:update?filter=' + encodeURIComponent(filterStr), {\\n      method: 'POST',\\n      headers: headers,\\n      body: JSON.stringify(resultData)\\n    });\\n    if (!resp.ok) return { ok: false, error: 'Lỗi lưu kết quả (HTTP ' + resp.status + ')' };\\n    return { ok: true };\\n  } catch(e) {\\n    console.error('Save exam result error:', e);\\n    return { ok: false, error: 'Lỗi kết nối khi lưu kết quả' };\\n  }\\n}\\n\\nvar { Card, Row, Col, Table, Tag, Typography, Space, Empty, Button, Tooltip, Spin, Badge, Radio, Progress, Alert, Result, Divider, Input, Modal, Statistic, Steps, List } = ctx.libs.antd;\\nvar { FileTextOutlined, ReloadOutlined, ClockCircleOutlined, CheckCircleOutlined, CloseCircleOutlined, ExclamationCircleOutlined, RightOutlined, SendOutlined, QuestionCircleOutlined, WarningOutlined, EditOutlined, BulbOutlined } = ctx.libs.antdIcons;\\nvar { useState, useCallback, useMemo, useEffect, useRef } = ctx.libs.React;\\nvar dayjs = ctx.libs.dayjs;\\nvar Title = Typography.Title;\\nvar Text = Typography.Text;\\nvar Paragraph = Typography.Paragraph;\\nvar TextArea = Input.TextArea;\\nvar Countdown = Statistic.Countdown;\\n\\nvar trangThaiColor = function(s) {\\n  var map = {\\n    'cho_thi': 'processing', 'da_xep_lich': 'cyan',\\n    'da_nop_bai': 'green', 'da_nop': 'green',\\n    'dang_cham': 'orange', 'cho_duyet': 'gold',\\n    'dat': 'success', 'khong_dat': 'error'\\n  };\\n  return map[s] || 'default';\\n};\\n\\nvar trangThaiText = function(s) {\\n  var map = {\\n    'cho_thi': 'Chờ thi', 'da_xep_lich': 'Đã xếp lịch',\\n    'da_nop_bai': 'Đã nộp bài', 'da_nop': 'Đã nộp bài',\\n    'dang_cham': 'Đang chấm', 'cho_duyet': 'Chờ duyệt',\\n    'dat': 'Đạt', 'khong_dat': 'Không đạt'\\n  };\\n  return map[s] || s || '—';\\n};\\n\\nvar hinhThucText = function(s) {\\n  var map = {\\n    'truc_tuyen': 'Trực tuyến', 'ban_cung': 'Bản cứng',\\n    'ket_hop': 'Kết hợp', 'truc_tiep': 'Trực tiếp'\\n  };\\n  return map[s] || s || '—';\\n};\\n\\nvar kyThiTrangThaiText = function(s) {\\n  var map = {\\n    'ban_nhap': 'Bản nháp', 'lap_lich': 'Lập lịch',\\n    'sap_dien_ra': 'Sắp diễn ra', 'da_duyet': 'Đã duyệt',\\n    'da_phe_duyet': 'Đã phê duyệt', 'dang_mo': 'Đang mở',\\n    'dang_thi': 'Đang thi', 'dang_cham_diem': 'Đang chấm điểm',\\n    'hoan_thanh': 'Hoàn thành', 'da_huy': 'Đã hủy'\\n  };\\n  return map[s] || s || '—';\\n};\\n\\nfunction ThiTrucTuyen(props) {\\n  var [data, setData] = useState(props.examData);\\n  var [loading, setLoading] = useState(false);\\n  var [view, setView] = useState('list'); // list | room | exam | confirm | submitted\\n  var [selectedExam, setSelectedExam] = useState(null);\\n  var [questions, setQuestions] = useState([]);\\n  var [answers, setAnswers] = useState({});\\n  var [currentQ, setCurrentQ] = useState(0);\\n  var [quizLoading, setQuizLoading] = useState(false);\\n  var [timeLeft, setTimeLeft] = useState(0);\\n  var [examStartTime, setExamStartTime] = useState(null);\\n  var [showConfirm, setShowConfirm] = useState(false);\\n  var [timerExpired, setTimerExpired] = useState(false);\\n  var timerRef = useRef(null);\\n\\n  var handleReload = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await props.reloadExams();\\n      setData(newData);\\n    } catch(e) {\\n      console.error('Reload error:', e);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, []);\\n\\n  // Timer effect\\n  useEffect(function() {\\n    if (view === 'exam' && timeLeft > 0) {\\n      timerRef.current = setInterval(function() {\\n        setTimeLeft(function(prev) {\\n          if (prev <= 1) {\\n            clearInterval(timerRef.current);\\n            setTimerExpired(true);\\n            setView('confirm');\\n            return 0;\\n          }\\n          return prev - 1;\\n        });\\n      }, 1000);\\n      return function() { clearInterval(timerRef.current); };\\n    }\\n  }, [view, timeLeft > 0]);\\n\\n  // Auto-submit when timer expires\\n  useEffect(function() {\\n    if (timerExpired && view === 'confirm') {\\n      handleFinalSubmit();\\n      setTimerExpired(false);\\n    }\\n  }, [timerExpired, view]);\\n\\n  var handleEnterRoom = useCallback(function(examItem) {\\n    setSelectedExam(examItem);\\n    setView('room');\\n    setAnswers({});\\n    setCurrentQ(0);\\n    setQuestions([]);\\n  }, []);\\n\\n  var handleStartExam = useCallback(async function() {\\n    if (!selectedExam) return;\\n    setQuizLoading(true);\\n    try {\\n      var kt = selectedExam.ky_thi || {};\\n      var deThi = kt.de_thi || {};\\n      var qs = await props.loadExamQuestions(deThi.id);\\n      setQuestions(qs);\\n      var duration = (deThi.thoi_gian_lam_bai || 30) * 60;\\n      setTimeLeft(duration);\\n      setExamStartTime(Date.now());\\n      setCurrentQ(0);\\n      setAnswers({});\\n      setView('exam');\\n    } catch(e) {\\n      console.error('Start exam error:', e);\\n    } finally {\\n      setQuizLoading(false);\\n    }\\n  }, [selectedExam]);\\n\\n  var handleAnswer = useCallback(function(qId, value) {\\n    setAnswers(function(prev) {\\n      var next = Object.assign({}, prev);\\n      next[qId] = value;\\n      return next;\\n    });\\n  }, []);\\n\\n  var handleSubmitConfirm = useCallback(function() {\\n    if (timerRef.current) clearInterval(timerRef.current);\\n    setView('confirm');\\n  }, []);\\n\\n  var handleFinalSubmit = useCallback(async function() {\\n    setQuizLoading(true);\\n    try {\\n      var ids = questions.map(function(q) { return q.id; });\\n      var fullQuestions = await props.loadAnswers(ids);\\n      var answerMap = {};\\n      fullQuestions.forEach(function(q) { answerMap[q.id] = q; });\\n\\n      var correct = 0;\\n      var total = 0;\\n      questions.forEach(function(q) {\\n        var full = answerMap[q.id];\\n        if (!full || !full.dap_an_dung) return;\\n        total++;\\n        var userAnswer = answers[q.id];\\n        if (!userAnswer) return;\\n        if (String(userAnswer).trim().toLowerCase() === String(full.dap_an_dung).trim().toLowerCase()) {\\n          correct++;\\n        }\\n      });\\n\\n      setQuestions(questions.map(function(q) {\\n        var full = answerMap[q.id];\\n        if (full) return Object.assign({}, q, { dap_an_dung: full.dap_an_dung, giai_thich: full.giai_thich });\\n        return q;\\n      }));\\n\\n      var scorePercent = total > 0 ? Math.round(correct / total * 10 * 10) / 10 : 0;\\n      var kt = selectedExam ? selectedExam.ky_thi || {} : {};\\n      var deThi = kt.de_thi || {};\\n      var diemDat = deThi.diem_dat || kt.diem_dat || 5;\\n      var ketQua = scorePercent >= diemDat ? 'dat' : 'khong_dat';\\n      var saveRes = await props.saveExamResult(kt.id, {\\n        trang_thai: 'da_nop_bai',\\n        diem: scorePercent,\\n        ket_qua: ketQua\\n      });\\n      if (saveRes && !saveRes.ok) {\\n        Modal.warning({ title: 'Lưu kết quả chưa thành công', content: 'Bài thi đã được chấm điểm nhưng chưa lưu được lên hệ thống. Vui lòng liên hệ cán bộ quản lý để cập nhật kết quả.' });\\n      }\\n\\n      setView('submitted');\\n    } catch(e) {\\n      console.error('Submit error:', e);\\n    } finally {\\n      setQuizLoading(false);\\n    }\\n  }, [questions, answers, selectedExam]);\\n\\n  var handleBackToList = useCallback(function() {\\n    setView('list');\\n    setSelectedExam(null);\\n    setQuestions([]);\\n    setAnswers({});\\n    setCurrentQ(0);\\n    if (timerRef.current) clearInterval(timerRef.current);\\n    handleReload();\\n  }, []);\\n\\n  var formatTime = function(seconds) {\\n    var h = Math.floor(seconds / 3600);\\n    var m = Math.floor((seconds % 3600) / 60);\\n    var s = seconds % 60;\\n    if (h > 0) return h + ':' + (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;\\n    return m + ':' + (s < 10 ? '0' : '') + s;\\n  };\\n\\n  if (!nld) {\\n    return (<Card>\\n      <Empty description=\\"Không tìm thấy thông tin người lao động liên kết với tài khoản này.\\" />\\n    </Card>);\\n  }\\n\\n  // === LMS-12: XÁC NHẬN NỘP BÀI ===\\n  if (view === 'confirm') {\\n    var answeredCount = Object.keys(answers).length;\\n    var unansweredCount = questions.length - answeredCount;\\n    var kt = selectedExam ? selectedExam.ky_thi || {} : {};\\n    var deThi = kt.de_thi || {};\\n\\n    return (\\n      <Card>\\n        <div style={{ textAlign: 'center', padding: '24px 0' }}>\\n          <ExclamationCircleOutlined style={{ fontSize: 48, color: '#faad14', marginBottom: 16 }} />\\n          <Title level={3}>Xác nhận nộp bài</Title>\\n          <Paragraph type=\\"secondary\\">{kt.ten_ky_thi || 'Kỳ thi'}</Paragraph>\\n        </div>\\n\\n        <Row gutter={16} style={{ marginBottom: 24 }}>\\n          <Col span={8}>\\n            <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n              <Statistic title=\\"Tổng câu hỏi\\" value={questions.length} />\\n            </Card>\\n          </Col>\\n          <Col span={8}>\\n            <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n              <Statistic title=\\"Đã trả lời\\" value={answeredCount} valueStyle={{ color: '#52c41a' }} />\\n            </Card>\\n          </Col>\\n          <Col span={8}>\\n            <Card size=\\"small\\" style={{ textAlign: 'center' }}>\\n              <Statistic title=\\"Chưa trả lời\\" value={unansweredCount}\\n                valueStyle={{ color: unansweredCount > 0 ? '#ff4d4f' : '#52c41a' }} />\\n            </Card>\\n          </Col>\\n        </Row>\\n\\n        {timeLeft > 0 && (\\n          <Alert\\n            type=\\"info\\"\\n            message={'Thời gian còn lại: ' + formatTime(timeLeft)}\\n            style={{ marginBottom: 16, textAlign: 'center' }}\\n          />\\n        )}\\n\\n        {unansweredCount > 0 && (\\n          <Alert\\n            type=\\"warning\\"\\n            message={'Bạn còn ' + unansweredCount + ' câu chưa trả lời. Bạn có chắc muốn nộp bài?'}\\n            style={{ marginBottom: 16 }}\\n          />\\n        )}\\n\\n        <div style={{ textAlign: 'center' }}>\\n          <Space size=\\"large\\">\\n            <Button size=\\"large\\" onClick={function() { setView('exam'); }}>\\n              ← Quay lại làm bài\\n            </Button>\\n            <Button type=\\"primary\\" size=\\"large\\" danger onClick={handleFinalSubmit} loading={quizLoading}\\n              icon={<SendOutlined />}>\\n              Xác nhận nộp bài\\n            </Button>\\n          </Space>\\n        </div>\\n      </Card>\\n    );\\n  }\\n\\n  // === LMS-11 SUBMITTED: Kết quả nhanh sau nộp ===\\n  if (view === 'submitted') {\\n    var kt = selectedExam ? selectedExam.ky_thi || {} : {};\\n    var deThi = kt.de_thi || {};\\n    var diemDat = deThi.diem_dat || kt.diem_dat || 5;\\n\\n    var correct = 0;\\n    var scorable = 0;\\n    questions.forEach(function(q) {\\n      if (!q.dap_an_dung) return;\\n      scorable++;\\n      var ua = answers[q.id];\\n      if (ua && String(ua).trim().toLowerCase() === String(q.dap_an_dung).trim().toLowerCase()) correct++;\\n    });\\n\\n    var scorePercent = scorable > 0 ? Math.round(correct / scorable * 10 * 10) / 10 : 0;\\n    var passed = scorePercent >= diemDat;\\n\\n    return (\\n      <Card>\\n        <Result\\n          status={passed ? 'success' : 'warning'}\\n          title={passed ? 'Chúc mừng! Bạn đã đạt yêu cầu' : 'Bạn chưa đạt yêu cầu'}\\n          subTitle={correct + '/' + scorable + ' câu đúng — Điểm: ' + scorePercent + '/10 (cần đạt: ' + diemDat + ')'}\\n          extra={[\\n            <Button key=\\"back\\" type=\\"primary\\" onClick={handleBackToList}>Quay lại danh sách kỳ thi</Button>\\n          ]}\\n        />\\n\\n        <Divider>Chi tiết câu trả lời</Divider>\\n\\n        <List\\n          dataSource={questions}\\n          renderItem={function(q, idx) {\\n            var optionsList = [];\\n            try {\\n              if (q.dap_an) {\\n                var parsed = typeof q.dap_an === 'string' ? JSON.parse(q.dap_an) : q.dap_an;\\n                if (Array.isArray(parsed)) optionsList = parsed;\\n              }\\n            } catch(e) {\\n              if (typeof q.dap_an === 'string') {\\n                var parts = q.dap_an.split('\\\\n').filter(function(o) { return o.trim(); });\\n                if (parts.length <= 1 && q.dap_an.indexOf(';') !== -1) {\\n                  parts = q.dap_an.split(';').map(function(o) { return o.trim(); }).filter(function(o) { return o; });\\n                }\\n                optionsList = parts;\\n              }\\n            }\\n\\n            var isEssay = optionsList.length === 0;\\n            var userAnswer = answers[q.id];\\n            var isCorrect = userAnswer && q.dap_an_dung &&\\n              String(userAnswer).trim().toLowerCase() === String(q.dap_an_dung).trim().toLowerCase();\\n\\n            return (\\n              <Card size=\\"small\\" style={{\\n                marginBottom: 8,\\n                borderLeft: q.dap_an_dung ? (isCorrect ? '3px solid #52c41a' : (userAnswer ? '3px solid #ff4d4f' : '3px solid #d9d9d9')) : '3px solid #d9d9d9'\\n              }}>\\n                <Space direction=\\"vertical\\" style={{ width: '100%' }}>\\n                  <Space>\\n                    <Badge count={idx + 1} style={{ backgroundColor: '#1890ff' }} />\\n                    <Text strong>{q.noi_dung || q.ten_cau_hoi}</Text>\\n                    {isEssay && <Tag icon={<EditOutlined />}>Tự luận</Tag>}\\n                  </Space>\\n\\n                  {!isEssay ? (\\n                    <div>\\n                      {optionsList.map(function(opt, oi) {\\n                        var optValue = typeof opt === 'object' ? (opt.value || opt.label || opt.text || String(oi)) : String(opt);\\n                        var optLabel = typeof opt === 'object' ? (opt.label || opt.text || opt.value || 'Lựa chọn ' + (oi + 1)) : String(opt);\\n                        var isSelected = userAnswer && String(userAnswer).trim().toLowerCase() === String(optValue).trim().toLowerCase();\\n                        var isRight = q.dap_an_dung && String(optValue).trim().toLowerCase() === String(q.dap_an_dung).trim().toLowerCase();\\n                        return (\\n                          <div key={oi} style={{\\n                            padding: '4px 8px', marginBottom: 2, borderRadius: 4,\\n                            background: isRight ? '#f6ffed' : (isSelected && !isRight ? '#fff2f0' : 'transparent'),\\n                            border: isRight ? '1px solid #b7eb8f' : (isSelected && !isRight ? '1px solid #ffccc7' : '1px solid transparent')\\n                          }}>\\n                            {isRight && <CheckCircleOutlined style={{ color: '#52c41a', marginRight: 8 }} />}\\n                            {isSelected && !isRight && <CloseCircleOutlined style={{ color: '#ff4d4f', marginRight: 8 }} />}\\n                            <Text>{optLabel}</Text>\\n                            {isSelected && <Tag style={{ marginLeft: 8 }} color={isRight ? 'green' : 'red'}>Bạn chọn</Tag>}\\n                          </div>\\n                        );\\n                      })}\\n                    </div>\\n                  ) : (\\n                    <div>\\n                      <Text type=\\"secondary\\">Câu trả lời: </Text>\\n                      <Text>{userAnswer || <Text type=\\"secondary\\" italic>Chưa trả lời</Text>}</Text>\\n                      <Alert type=\\"info\\" message=\\"Câu tự luận cần giảng viên chấm thủ công\\" style={{ marginTop: 8 }} />\\n                    </div>\\n                  )}\\n\\n                  {q.giai_thich && (\\n                    <Alert type=\\"info\\" message={<span><BulbOutlined /> {q.giai_thich}</span>} style={{ marginTop: 4 }} />\\n                  )}\\n                </Space>\\n              </Card>\\n            );\\n          }}\\n        />\\n      </Card>\\n    );\\n  }\\n\\n  // === LMS-10: PHÒNG THI ===\\n  if (view === 'room') {\\n    var kt = selectedExam ? selectedExam.ky_thi || {} : {};\\n    var deThi = kt.de_thi || {};\\n    var thoiGianLamBai = deThi.thoi_gian_lam_bai || 30;\\n\\n    var canStart = true;\\n    var reasonNotStart = '';\\n    if (kt.trang_thai === 'da_huy') { canStart = false; reasonNotStart = 'Kỳ thi đã bị hủy'; }\\n    if (selectedExam.trang_thai === 'dat' || selectedExam.trang_thai === 'khong_dat') {\\n      canStart = false;\\n      reasonNotStart = 'Bạn đã hoàn thành kỳ thi này';\\n    }\\n    if (selectedExam.trang_thai === 'da_nop_bai' || selectedExam.trang_thai === 'da_nop') {\\n      canStart = false;\\n      reasonNotStart = 'Bạn đã nộp bài thi này';\\n    }\\n\\n    return (\\n      <Card>\\n        <Button onClick={handleBackToList} style={{ marginBottom: 16 }}>← Quay lại</Button>\\n\\n        <div style={{ textAlign: 'center', marginBottom: 24 }}>\\n          <FileTextOutlined style={{ fontSize: 48, color: '#1890ff', marginBottom: 16 }} />\\n          <Title level={3}>{kt.ten_ky_thi || 'Kỳ thi'}</Title>\\n          <Tag color={trangThaiColor(selectedExam.trang_thai)}>{trangThaiText(selectedExam.trang_thai)}</Tag>\\n        </div>\\n\\n        <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>\\n          <Col xs={24} sm={12} md={6}>\\n            <Card size=\\"small\\">\\n              <Statistic title=\\"Hình thức\\" value={hinhThucText(kt.hinh_thuc)} />\\n            </Card>\\n          </Col>\\n          <Col xs={24} sm={12} md={6}>\\n            <Card size=\\"small\\">\\n              <Statistic title=\\"Thời gian làm bài\\" value={thoiGianLamBai} suffix=\\"phút\\" />\\n            </Card>\\n          </Col>\\n          <Col xs={24} sm={12} md={6}>\\n            <Card size=\\"small\\">\\n              <Statistic title=\\"Số câu hỏi\\" value={deThi.so_cau_hoi || '—'} />\\n            </Card>\\n          </Col>\\n          <Col xs={24} sm={12} md={6}>\\n            <Card size=\\"small\\">\\n              <Statistic title=\\"Điểm đạt\\" value={deThi.diem_dat || kt.diem_dat || '—'} suffix=\\"/10\\" />\\n            </Card>\\n          </Col>\\n        </Row>\\n\\n        {kt.quy_che_thi && (\\n          <Card size=\\"small\\" title=\\"Quy chế thi\\" style={{ marginBottom: 16 }}>\\n            <Paragraph>{kt.quy_che_thi}</Paragraph>\\n          </Card>\\n        )}\\n\\n        <Card size=\\"small\\" title=\\"Lưu ý trước khi thi\\" style={{ marginBottom: 24 }}>\\n          <ul style={{ paddingLeft: 20 }}>\\n            <li>Đảm bảo kết nối internet ổn định trong suốt thời gian thi</li>\\n            <li>Thời gian làm bài là <strong>{thoiGianLamBai} phút</strong>, hệ thống sẽ tự động nộp bài khi hết giờ</li>\\n            <li>Không đóng trình duyệt hoặc chuyển tab trong khi thi</li>\\n            <li>Mỗi câu hỏi chỉ được chọn một đáp án (trắc nghiệm) hoặc nhập câu trả lời (tự luận)</li>\\n            <li>Sau khi nộp bài, không thể sửa đổi câu trả lời</li>\\n          </ul>\\n        </Card>\\n\\n        <div style={{ textAlign: 'center' }}>\\n          {canStart ? (\\n            <Button type=\\"primary\\" size=\\"large\\" onClick={handleStartExam} loading={quizLoading}\\n              icon={<RightOutlined />}>\\n              Bắt đầu làm bài\\n            </Button>\\n          ) : (\\n            <Alert type=\\"warning\\" message={reasonNotStart} style={{ maxWidth: 400, margin: '0 auto' }} />\\n          )}\\n        </div>\\n      </Card>\\n    );\\n  }\\n\\n  // === LMS-11: LÀM BÀI THI ===\\n  if (view === 'exam') {\\n    var q = questions[currentQ];\\n    var answeredCount = Object.keys(answers).length;\\n    var timerColor = timeLeft < 60 ? '#ff4d4f' : timeLeft < 300 ? '#faad14' : '#1890ff';\\n\\n    var optionsList = [];\\n    if (q) {\\n      try {\\n        if (q.dap_an) {\\n          var parsed = typeof q.dap_an === 'string' ? JSON.parse(q.dap_an) : q.dap_an;\\n          if (Array.isArray(parsed)) optionsList = parsed;\\n        }\\n      } catch(e) {\\n        if (typeof q.dap_an === 'string') {\\n          var parts = q.dap_an.split('\\\\n').filter(function(o) { return o.trim(); });\\n          if (parts.length <= 1 && q.dap_an.indexOf(';') !== -1) {\\n            parts = q.dap_an.split(';').map(function(o) { return o.trim(); }).filter(function(o) { return o; });\\n          }\\n          optionsList = parts;\\n        }\\n      }\\n    }\\n\\n    var isEssay = q && optionsList.length === 0;\\n\\n    return (\\n      <div>\\n        {/* Header with timer */}\\n        <Card size=\\"small\\" style={{ marginBottom: 8 }}>\\n          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>\\n            <Space>\\n              <Text strong>{(selectedExam.ky_thi || {}).ten_ky_thi || 'Kỳ thi'}</Text>\\n              <Tag>Câu {currentQ + 1}/{questions.length}</Tag>\\n            </Space>\\n            <Space>\\n              <Tag color={timerColor} style={{ fontSize: 16, padding: '4px 12px' }}>\\n                <ClockCircleOutlined /> {formatTime(timeLeft)}\\n              </Tag>\\n              <Text type=\\"secondary\\">Đã trả lời: {answeredCount}/{questions.length}</Text>\\n              <Button type=\\"primary\\" danger size=\\"small\\" onClick={handleSubmitConfirm}\\n                icon={<SendOutlined />}>\\n                Nộp bài\\n              </Button>\\n            </Space>\\n          </div>\\n        </Card>\\n\\n        <Row gutter={16}>\\n          {/* Question navigation sidebar */}\\n          <Col xs={24} md={6}>\\n            <Card size=\\"small\\" title=\\"Câu hỏi\\" style={{ marginBottom: 8 }}>\\n              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>\\n                {questions.map(function(qi, idx) {\\n                  var isAnswered = !!answers[qi.id];\\n                  var isCurrent = idx === currentQ;\\n                  return (\\n                    <Button key={idx} size=\\"small\\"\\n                      type={isCurrent ? 'primary' : (isAnswered ? 'default' : 'dashed')}\\n                      style={{\\n                        width: 36, height: 36, padding: 0,\\n                        background: isAnswered && !isCurrent ? '#e6f7ff' : undefined,\\n                        borderColor: isAnswered && !isCurrent ? '#91d5ff' : undefined\\n                      }}\\n                      onClick={function() { setCurrentQ(idx); }}>\\n                      {idx + 1}\\n                    </Button>\\n                  );\\n                })}\\n              </div>\\n            </Card>\\n          </Col>\\n\\n          {/* Question content */}\\n          <Col xs={24} md={18}>\\n            {q ? (\\n              <Card>\\n                <Space direction=\\"vertical\\" style={{ width: '100%' }} size=\\"middle\\">\\n                  <Space>\\n                    <Badge count={currentQ + 1} style={{ backgroundColor: '#1890ff' }} />\\n                    <Title level={5} style={{ margin: 0 }}>{q.noi_dung || q.ten_cau_hoi}</Title>\\n                  </Space>\\n\\n                  <Space>\\n                    {q.muc_do_kho && (\\n                      <Tag color={q.muc_do_kho === 'de' ? 'green' : q.muc_do_kho === 'kho' ? 'red' : 'orange'}>\\n                        {q.muc_do_kho === 'de' ? 'Dễ' : q.muc_do_kho === 'kho' ? 'Khó' : 'Trung bình'}\\n                      </Tag>\\n                    )}\\n                    {isEssay && <Tag icon={<EditOutlined />}>Tự luận</Tag>}\\n                  </Space>\\n\\n                  {!isEssay ? (\\n                    <Radio.Group\\n                      value={answers[q.id]}\\n                      onChange={function(e) { handleAnswer(q.id, e.target.value); }}\\n                      style={{ width: '100%' }}\\n                    >\\n                      <Space direction=\\"vertical\\" style={{ width: '100%' }}>\\n                        {optionsList.map(function(opt, oi) {\\n                          var optValue = typeof opt === 'object' ? (opt.value || opt.label || opt.text || String(oi)) : String(opt);\\n                          var optLabel = typeof opt === 'object' ? (opt.label || opt.text || opt.value || 'Lựa chọn ' + (oi + 1)) : String(opt);\\n                          return (\\n                            <Radio key={oi} value={optValue} style={{\\n                              display: 'block', padding: '8px 12px', borderRadius: 4,\\n                              border: '1px solid #d9d9d9', marginBottom: 4\\n                            }}>\\n                              {optLabel}\\n                            </Radio>\\n                          );\\n                        })}\\n                      </Space>\\n                    </Radio.Group>\\n                  ) : (\\n                    <TextArea\\n                      rows={5}\\n                      placeholder=\\"Nhập câu trả lời của bạn...\\"\\n                      value={answers[q.id] || ''}\\n                      onChange={function(e) { handleAnswer(q.id, e.target.value); }}\\n                    />\\n                  )}\\n\\n                  <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 16 }}>\\n                    <Button disabled={currentQ === 0}\\n                      onClick={function() { setCurrentQ(currentQ - 1); }}>\\n                      ← Câu trước\\n                    </Button>\\n                    {currentQ < questions.length - 1 ? (\\n                      <Button type=\\"primary\\" onClick={function() { setCurrentQ(currentQ + 1); }}>\\n                        Câu tiếp →\\n                      </Button>\\n                    ) : (\\n                      <Button type=\\"primary\\" danger onClick={handleSubmitConfirm} icon={<SendOutlined />}>\\n                        Nộp bài\\n                      </Button>\\n                    )}\\n                  </div>\\n                </Space>\\n              </Card>\\n            ) : (\\n              <Card><Empty description=\\"Không có câu hỏi\\" /></Card>\\n            )}\\n          </Col>\\n        </Row>\\n      </div>\\n    );\\n  }\\n\\n  // === LMS-09: DS KỲ THI CỦA TÔI ===\\n  var sapThi = data.filter(function(d) {\\n    return d.trang_thai === 'cho_thi' || d.trang_thai === 'da_xep_lich';\\n  });\\n  var daThi = data.filter(function(d) {\\n    return d.trang_thai !== 'cho_thi' && d.trang_thai !== 'da_xep_lich';\\n  });\\n\\n  return (\\n    <div>\\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\\n        <Title level={4} style={{ margin: 0 }}>\\n          <FileTextOutlined style={{ marginRight: 8 }} />\\n          Thi trực tuyến\\n        </Title>\\n        <Tooltip title=\\"Tải lại\\">\\n          <Button icon={<ReloadOutlined />} onClick={handleReload} loading={loading} />\\n        </Tooltip>\\n      </div>\\n\\n      {data.length === 0 ? (\\n        <Empty description=\\"Bạn chưa được xếp lịch thi nào\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />\\n      ) : (\\n        <div>\\n          {sapThi.length > 0 && (\\n            <div>\\n              <Title level={5}><ClockCircleOutlined style={{ marginRight: 8 }} />Kỳ thi sắp tới ({sapThi.length})</Title>\\n              <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>\\n                {sapThi.map(function(item, idx) {\\n                  var kt = item.ky_thi || {};\\n                  var deThi = kt.de_thi || {};\\n                  var nn = kt.nganh_nghe;\\n                  var thoiGian = deThi.thoi_gian_lam_bai || 30;\\n                  return (\\n                    <Col xs={24} sm={12} lg={8} key={item.id || idx}>\\n                      <Card size=\\"small\\" hoverable\\n                        actions={[\\n                          <Button key=\\"start\\" type=\\"link\\" onClick={function() { handleEnterRoom(item); }}>\\n                            <RightOutlined /> Vào phòng thi\\n                          </Button>\\n                        ]}\\n                      >\\n                        <Card.Meta\\n                          avatar={<FileTextOutlined style={{ fontSize: 24, color: '#1890ff' }} />}\\n                          title={<Text ellipsis={{ tooltip: kt.ten_ky_thi }}>{kt.ten_ky_thi || '—'}</Text>}\\n                          description={\\n                            <Space direction=\\"vertical\\" size={4} style={{ width: '100%' }}>\\n                              {nn && <Text type=\\"secondary\\">Ngành: {nn.ten_nganh_nghe || nn.name}</Text>}\\n                              <Text type=\\"secondary\\">Hình thức: {hinhThucText(kt.hinh_thuc)}</Text>\\n                              <Text type=\\"secondary\\">Thời gian: {thoiGian} phút — {deThi.so_cau_hoi || '?'} câu</Text>\\n                              {kt.thoi_gian_bat_dau && (\\n                                <Text type=\\"secondary\\">Bắt đầu: {dayjs(kt.thoi_gian_bat_dau).format('HH:mm DD/MM/YYYY')}</Text>\\n                              )}\\n                              <Space>\\n                                <Tag color={trangThaiColor(item.trang_thai)}>{trangThaiText(item.trang_thai)}</Tag>\\n                                {item.lan_thi > 1 && <Tag color=\\"orange\\">Lần thi {item.lan_thi}</Tag>}\\n                              </Space>\\n                            </Space>\\n                          }\\n                        />\\n                      </Card>\\n                    </Col>\\n                  );\\n                })}\\n              </Row>\\n            </div>\\n          )}\\n\\n          {daThi.length > 0 && (\\n            <div>\\n              <Title level={5}><CheckCircleOutlined style={{ marginRight: 8 }} />Kỳ thi đã tham gia ({daThi.length})</Title>\\n              <Row gutter={[16, 16]}>\\n                {daThi.map(function(item, idx) {\\n                  var kt = item.ky_thi || {};\\n                  var nn = kt.nganh_nghe;\\n                  return (\\n                    <Col xs={24} sm={12} lg={8} key={item.id || idx}>\\n                      <Card size=\\"small\\" hoverable\\n                        actions={[\\n                          <Button key=\\"view\\" type=\\"link\\" onClick={function() { handleEnterRoom(item); }}>\\n                            Xem chi tiết\\n                          </Button>\\n                        ]}\\n                      >\\n                        <Card.Meta\\n                          avatar={<FileTextOutlined style={{ fontSize: 24, color: '#8c8c8c' }} />}\\n                          title={<Text ellipsis={{ tooltip: kt.ten_ky_thi }}>{kt.ten_ky_thi || '—'}</Text>}\\n                          description={\\n                            <Space direction=\\"vertical\\" size={4} style={{ width: '100%' }}>\\n                              {nn && <Text type=\\"secondary\\">Ngành: {nn.ten_nganh_nghe || nn.name}</Text>}\\n                              <Text type=\\"secondary\\">Hình thức: {hinhThucText(kt.hinh_thuc)}</Text>\\n                              <Space>\\n                                <Tag color={trangThaiColor(item.trang_thai)}>{trangThaiText(item.trang_thai)}</Tag>\\n                                {item.diem != null && <Tag color=\\"blue\\">Điểm: {item.diem}</Tag>}\\n                                {item.ket_qua && item.ket_qua !== 'chua_co' && (\\n                                  <Tag color={item.ket_qua === 'dat' ? 'green' : 'red'}>\\n                                    {item.ket_qua === 'dat' ? 'Đạt' : 'Không đạt'}\\n                                  </Tag>\\n                                )}\\n                                {item.lan_thi > 1 && <Tag color=\\"orange\\">Lần {item.lan_thi}</Tag>}\\n                              </Space>\\n                            </Space>\\n                          }\\n                        />\\n                      </Card>\\n                    </Col>\\n                  );\\n                })}\\n              </Row>\\n            </div>\\n          )}\\n        </div>\\n      )}\\n    </div>\\n  );\\n}\\n\\nctx.render(\\n  <ThiTrucTuyen\\n    examData={examData}\\n    reloadExams={reloadExams}\\n    loadExamQuestions={loadExamQuestions}\\n    loadAnswers={loadAnswers}\\n    saveExamResult={saveExamResult}\\n  />\\n);\\n"}}}}
