7h0sjw56aoe	7h0sjw56aoe	{"parentId":"03aurxedv5g","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// KH-06: Phê duyệt tài liệu huấn luyện - CBAT\\nconst { useState, useEffect, useCallback } = ctx.libs.React;\\nconst { Table, Tag, Button, Modal, Space, Input, Descriptions, Badge, message, Empty, Typography } = ctx.libs.antd;\\nconst { TextArea } = Input;\\nconst { Text } = Typography;\\nconst dayjs = ctx.libs.dayjs;\\n\\nconst API_BASE = '/api';\\n\\nfunction getHeaders() {\\n  const headers = { 'Content-Type': 'application/json' };\\n  const token = localStorage.getItem('NOCOBASE_TOKEN');\\n  if (token) headers['Authorization'] = 'Bearer ' + token;\\n  return headers;\\n}\\n\\nasync function apiGet(resource, params) {\\n  const parts = [];\\n  if (params) {\\n    for (const [k, v] of Object.entries(params)) {\\n      if (Array.isArray(v)) {\\n        v.forEach(item => parts.push(k + '[]=' + encodeURIComponent(item)));\\n      } else if (typeof v === 'object') {\\n        parts.push('filter=' + encodeURIComponent(JSON.stringify(v)));\\n      } else {\\n        parts.push(k + '=' + encodeURIComponent(v));\\n      }\\n    }\\n  }\\n  const qs = parts.length ? '?' + parts.join('&') : '';\\n  const resp = await fetch(API_BASE + '/' + resource + ':list' + qs, { headers: getHeaders() });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nasync function apiUpdate(resource, filterObj, values) {\\n  const resp = await fetch(API_BASE + '/' + resource + ':update?filter=' + encodeURIComponent(JSON.stringify(filterObj)), {\\n    method: 'POST', headers: getHeaders(), body: JSON.stringify(values)\\n  });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nconst LOAI_MAP = { van_ban: 'Văn bản', video: 'Video', pdf: 'PDF', slide: 'Slide', khac: 'Khác' };\\nconst TRANG_THAI_MAP = {\\n  cho_phe_duyet: { text: 'Chờ phê duyệt', color: 'orange' },\\n  da_phe_duyet: { text: 'Đã phê duyệt', color: 'green' },\\n  tu_choi: { text: 'Từ chối', color: 'red' },\\n  nhap: { text: 'Nháp', color: 'default' }\\n};\\n\\nfunction App() {\\n  const [data, setData] = useState([]);\\n  const [loading, setLoading] = useState(true);\\n  const [detail, setDetail] = useState(null);\\n  const [showDetail, setShowDetail] = useState(false);\\n  const [showReject, setShowReject] = useState(false);\\n  const [rejectReason, setRejectReason] = useState('');\\n  const [rejectItem, setRejectItem] = useState(null);\\n  const [actionLoading, setActionLoading] = useState(false);\\n  const [filterStatus, setFilterStatus] = useState('cho_phe_duyet');\\n\\n  const loadData = useCallback(async () => {\\n    setLoading(true);\\n    try {\\n      const filter = {};\\n      if (filterStatus !== 'all') filter.trang_thai = filterStatus;\\n      const resp = await apiGet('tai_lieu_huan_luyen', {\\n        filter: JSON.stringify(filter),\\n        sort: ['-createdAt'],\\n        appends: ['nganh_nghe','bac_tho','nguoi_tai_len','nguoi_phe_duyet'],\\n        pageSize: 50\\n      });\\n      setData((resp.data && resp.data.data) || resp.data || []);\\n    } catch(err) {\\n      message.error('Lỗi tải danh sách tài liệu');\\n    }\\n    setLoading(false);\\n  }, [filterStatus]);\\n\\n  useEffect(() => { loadData(); }, [loadData]);\\n\\n  const handleApprove = (record) => {\\n    Modal.confirm({\\n      title: 'Xác nhận phê duyệt',\\n      content: <div><p>Phê duyệt tài liệu: <strong>{record.ten_tai_lieu}</strong>?</p><p style={{color:'#666'}}>Tài liệu sẽ được đưa vào kho chính thức.</p></div>,\\n      okText: 'Phê duyệt', cancelText: 'Hủy',\\n      okButtonProps: { style: { background: '#52c41a', borderColor: '#52c41a' } },\\n      onOk: async () => {\\n        setActionLoading(true);\\n        try {\\n          await apiUpdate('tai_lieu_huan_luyen', { id: record.id }, {\\n            trang_thai: 'da_phe_duyet', ngay_phe_duyet: new Date().toISOString(), trong_kho_chinh_thuc: true\\n          });\\n          message.success('Đã phê duyệt tài liệu');\\n          loadData();\\n        } catch(err) { message.error('Lỗi phê duyệt: ' + err.message); }\\n        setActionLoading(false);\\n      }\\n    });\\n  };\\n\\n  const openReject = (record) => { setRejectItem(record); setRejectReason(''); setShowReject(true); };\\n\\n  const handleReject = async () => {\\n    if (!rejectReason.trim()) { message.warning('Vui lòng nhập lý do từ chối'); return; }\\n    setActionLoading(true);\\n    try {\\n      await apiUpdate('tai_lieu_huan_luyen', { id: rejectItem.id }, {\\n        trang_thai: 'tu_choi', ngay_phe_duyet: new Date().toISOString(), y_kien_phe_duyet: rejectReason\\n      });\\n      message.success('Đã từ chối tài liệu');\\n      setShowReject(false); loadData();\\n    } catch(err) { message.error('Lỗi từ chối: ' + err.message); }\\n    setActionLoading(false);\\n  };\\n\\n  const columns = [\\n    { title: 'Mã', dataIndex: 'ma_tai_lieu', width: 110 },\\n    { title: 'Tên tài liệu', dataIndex: 'ten_tai_lieu', ellipsis: true,\\n      render: (v, r) => <a onClick={() => { setDetail(r); setShowDetail(true); }}>{v}</a> },\\n    { title: 'Loại', dataIndex: 'loai_tai_lieu', width: 100, render: v => LOAI_MAP[v] || v || '-' },\\n    { title: 'Ngành nghề', width: 150, render: (_, r) => (r.nganh_nghe && r.nganh_nghe.ten_nganh_nghe) || '-' },\\n    { title: 'Người gửi', width: 140, render: (_, r) => (r.nguoi_tai_len && r.nguoi_tai_len.ho_va_ten) || '-' },\\n    { title: 'Ngày gửi', dataIndex: 'ngay_gui_duyet', width: 120,\\n      render: v => v ? dayjs(v).format('DD/MM/YYYY') : '-' },\\n    { title: 'Trạng thái', dataIndex: 'trang_thai', width: 130,\\n      render: v => { const s = TRANG_THAI_MAP[v] || { text: v, color: 'default' }; return <Tag color={s.color}>{s.text}</Tag>; } },\\n    { title: 'Thao tác', width: 180, fixed: 'right',\\n      render: (_, r) => {\\n        if (r.trang_thai !== 'cho_phe_duyet') return <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>;\\n        return <Space>\\n          <Button type=\\"primary\\" size=\\"small\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => handleApprove(r)}>Duyệt</Button>\\n          <Button danger size=\\"small\\" onClick={() => openReject(r)}>Từ chối</Button>\\n          <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>\\n        </Space>;\\n      }\\n    }\\n  ];\\n\\n  const statusBtns = [\\n    { key: 'cho_phe_duyet', label: 'Chờ duyệt' },\\n    { key: 'da_phe_duyet', label: 'Đã duyệt' },\\n    { key: 'tu_choi', label: 'Từ chối' },\\n    { key: 'all', label: 'Tất cả' }\\n  ];\\n\\n  const pendingCount = filterStatus === 'cho_phe_duyet' ? data.length : 0;\\n\\n  return (\\n    <div style={{padding:16}}>\\n      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>\\n        <div style={{display:'flex',gap:8}}>\\n          {statusBtns.map(sb => (\\n            <Button key={sb.key} type={filterStatus === sb.key ? 'primary' : 'default'} size=\\"small\\" onClick={() => setFilterStatus(sb.key)}>\\n              {sb.label}{sb.key === 'cho_phe_duyet' && pendingCount > 0 ? <Badge count={pendingCount} size=\\"small\\" offset={[5,-3]} /> : null}\\n            </Button>\\n          ))}\\n        </div>\\n        <Button onClick={loadData} size=\\"small\\">Làm mới</Button>\\n      </div>\\n      <Table columns={columns} dataSource={data} rowKey=\\"id\\" loading={loading} size=\\"small\\"\\n        scroll={{x:1000}} pagination={{pageSize:20,showSizeChanger:true,showTotal:t=>'Tổng: '+t+' tài liệu'}}\\n        locale={{emptyText:<Empty description={filterStatus==='cho_phe_duyet'?'Không có tài liệu chờ duyệt':'Không có dữ liệu'} />}} />\\n\\n      <Modal title={detail ? detail.ten_tai_lieu : ''} open={showDetail} onCancel={() => setShowDetail(false)} width={700}\\n        footer={detail && detail.trang_thai === 'cho_phe_duyet' ? [\\n          <Button key=\\"reject\\" danger onClick={() => { setShowDetail(false); openReject(detail); }}>Từ chối</Button>,\\n          <Button key=\\"approve\\" type=\\"primary\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => { setShowDetail(false); handleApprove(detail); }}>Phê duyệt</Button>\\n        ] : null}>\\n        {detail && <Descriptions column={2} bordered size=\\"small\\">\\n          <Descriptions.Item label=\\"Mã tài liệu\\">{detail.ma_tai_lieu || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Loại\\">{LOAI_MAP[detail.loai_tai_lieu] || detail.loai_tai_lieu || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngành nghề\\">{(detail.nganh_nghe && detail.nganh_nghe.ten_nganh_nghe) || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc thợ\\">{(detail.bac_tho && detail.bac_tho.ten_bac_tho) || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Nhóm huấn luyện\\">{detail.nhom_huan_luyen || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Phiên bản\\">{detail.phien_ban_hien_tai || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Người gửi\\" span={2}>{(detail.nguoi_tai_len && detail.nguoi_tai_len.ho_va_ten) || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngày gửi duyệt\\" span={2}>{detail.ngay_gui_duyet ? dayjs(detail.ngay_gui_duyet).format('DD/MM/YYYY') : '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Mô tả\\" span={2}>{detail.mo_ta || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Căn cứ pháp lý\\" span={2}>{detail.can_cu_phap_ly || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Trạng thái\\" span={2}><Tag color={(TRANG_THAI_MAP[detail.trang_thai]||{}).color}>{(TRANG_THAI_MAP[detail.trang_thai]||{}).text || detail.trang_thai}</Tag></Descriptions.Item>\\n          {detail.trang_thai === 'tu_choi' && <Descriptions.Item label=\\"Lý do từ chối\\" span={2}><Text type=\\"danger\\">{detail.y_kien_phe_duyet || '-'}</Text></Descriptions.Item>}\\n          {detail.nguoi_phe_duyet && <Descriptions.Item label=\\"Người duyệt\\" span={2}>{detail.nguoi_phe_duyet.ho_va_ten || '-'}</Descriptions.Item>}\\n          {detail.ngay_phe_duyet && <Descriptions.Item label=\\"Ngày duyệt\\" span={2}>{dayjs(detail.ngay_phe_duyet).format('DD/MM/YYYY')}</Descriptions.Item>}\\n        </Descriptions>}\\n      </Modal>\\n\\n      <Modal title=\\"Từ chối tài liệu\\" open={showReject} onOk={handleReject} onCancel={() => setShowReject(false)}\\n        okText=\\"Xác nhận từ chối\\" cancelText=\\"Hủy\\" okButtonProps={{danger:true,loading:actionLoading}}>\\n        {rejectItem && <div>\\n          <p>Tài liệu: <strong>{rejectItem.ten_tai_lieu}</strong></p>\\n          <p style={{marginBottom:8}}>Lý do từ chối <span style={{color:'red'}}>*</span></p>\\n          <TextArea rows={3} value={rejectReason} onChange={e => setRejectReason(e.target.value)} placeholder=\\"Nhập lý do từ chối tài liệu...\\" />\\n        </div>}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);\\n"},"showBlockCard":{"showBlockCard":false}},"__flowSurfaceMeta":{"declaredKey":"pheDuyetTaiLieu"}}}
