0365hbsefpc	0365hbsefpc	{"parentId":"8vvuwldv06c","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// CH-05: Duyệt câu hỏi - CBAT\\nconst { useState, useEffect, useCallback } = ctx.libs.React;\\nconst { Table, Tag, Button, Modal, Space, Input, Descriptions, Badge, message, Empty, Typography } = ctx.libs.antd;\\nconst { TextArea } = Input;\\nconst { Text } = Typography;\\nconst dayjs = ctx.libs.dayjs;\\n\\nconst API_BASE = '/api';\\n\\nfunction getHeaders() {\\n  const headers = { 'Content-Type': 'application/json' };\\n  const token = localStorage.getItem('NOCOBASE_TOKEN');\\n  if (token) headers['Authorization'] = 'Bearer ' + token;\\n  return headers;\\n}\\n\\nasync function apiGet(resource, params) {\\n  const parts = [];\\n  if (params) {\\n    for (const [k, v] of Object.entries(params)) {\\n      if (Array.isArray(v)) {\\n        v.forEach(item => parts.push(k + '[]=' + encodeURIComponent(item)));\\n      } else if (typeof v === 'object') {\\n        parts.push('filter=' + encodeURIComponent(JSON.stringify(v)));\\n      } else {\\n        parts.push(k + '=' + encodeURIComponent(v));\\n      }\\n    }\\n  }\\n  const qs = parts.length ? '?' + parts.join('&') : '';\\n  const resp = await fetch(API_BASE + '/' + resource + ':list' + qs, { headers: getHeaders() });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nasync function apiUpdate(resource, filterObj, values) {\\n  const resp = await fetch(API_BASE + '/' + resource + ':update?filter=' + encodeURIComponent(JSON.stringify(filterObj)), {\\n    method: 'POST', headers: getHeaders(), body: JSON.stringify(values)\\n  });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nconst MUC_DO_MAP = { de: 'Dễ', trung_binh: 'Trung bình', kho: 'Khó' };\\nconst HINH_THUC_MAP = { trac_nghiem: 'Trắc nghiệm', tu_luan: 'Tự luận', dung_sai: 'Đúng/Sai' };\\nconst TRANG_THAI_MAP = {\\n  cho_phe_duyet: { text: 'Chờ phê duyệt', color: 'orange' },\\n  da_phe_duyet: { text: 'Đã phê duyệt', color: 'green' },\\n  tu_choi: { text: 'Từ chối', color: 'red' },\\n  nhap: { text: 'Nháp', color: 'default' }\\n};\\n\\nfunction App() {\\n  const [data, setData] = useState([]);\\n  const [loading, setLoading] = useState(true);\\n  const [detail, setDetail] = useState(null);\\n  const [showDetail, setShowDetail] = useState(false);\\n  const [showReject, setShowReject] = useState(false);\\n  const [rejectReason, setRejectReason] = useState('');\\n  const [rejectItem, setRejectItem] = useState(null);\\n  const [actionLoading, setActionLoading] = useState(false);\\n  const [filterStatus, setFilterStatus] = useState('cho_phe_duyet');\\n\\n  const loadData = useCallback(async () => {\\n    setLoading(true);\\n    try {\\n      const filter = {};\\n      if (filterStatus !== 'all') filter.trang_thai = filterStatus;\\n      const resp = await apiGet('cau_hoi', {\\n        filter: JSON.stringify(filter), sort: ['-createdAt'],\\n        appends: ['nganh_nghe','bac_tho'], pageSize: 50\\n      });\\n      setData((resp.data && resp.data.data) || resp.data || []);\\n    } catch(err) { message.error('Lỗi tải danh sách câu hỏi'); }\\n    setLoading(false);\\n  }, [filterStatus]);\\n\\n  useEffect(() => { loadData(); }, [loadData]);\\n\\n  const handleApprove = (record) => {\\n    Modal.confirm({\\n      title: 'Xác nhận duyệt câu hỏi',\\n      content: <div><p>Duyệt câu hỏi: <strong>{record.ten_cau_hoi || record.ma_cau_hoi}</strong>?</p><p style={{color:'#666'}}>Câu hỏi sẽ được đưa vào ngân hàng chính thức.</p></div>,\\n      okText: 'Duyệt', cancelText: 'Hủy',\\n      okButtonProps: { style: { background: '#52c41a', borderColor: '#52c41a' } },\\n      onOk: async () => {\\n        setActionLoading(true);\\n        try {\\n          await apiUpdate('cau_hoi', { id: record.id }, { trang_thai: 'da_phe_duyet' });\\n          message.success('Đã duyệt câu hỏi'); loadData();\\n        } catch(err) { message.error('Lỗi duyệt: ' + err.message); }\\n        setActionLoading(false);\\n      }\\n    });\\n  };\\n\\n  const openReject = (record) => { setRejectItem(record); setRejectReason(''); setShowReject(true); };\\n\\n  const handleReject = async () => {\\n    if (!rejectReason.trim()) { message.warning('Vui lòng nhập lý do từ chối'); return; }\\n    setActionLoading(true);\\n    try {\\n      await apiUpdate('cau_hoi', { id: rejectItem.id }, { trang_thai: 'tu_choi', y_kien_phe_duyet: rejectReason });\\n      message.success('Đã từ chối câu hỏi'); setShowReject(false); loadData();\\n    } catch(err) { message.error('Lỗi từ chối: ' + err.message); }\\n    setActionLoading(false);\\n  };\\n\\n  const MUC_DO_COLORS = { de: 'green', trung_binh: 'blue', kho: 'red' };\\n\\n  const columns = [\\n    { title: 'Mã', dataIndex: 'ma_cau_hoi', width: 110 },\\n    { title: 'Tên câu hỏi', dataIndex: 'ten_cau_hoi', ellipsis: true,\\n      render: (v, r) => <a onClick={() => { setDetail(r); setShowDetail(true); }}>{v || r.ma_cau_hoi}</a> },\\n    { title: 'Chủ đề', dataIndex: 'chu_de', width: 140, ellipsis: true },\\n    { title: 'Hình thức', dataIndex: 'hinh_thuc', width: 110, render: v => HINH_THUC_MAP[v] || v || '-' },\\n    { title: 'Mức độ', dataIndex: 'muc_do_kho', width: 110,\\n      render: v => <Tag color={MUC_DO_COLORS[v] || 'default'}>{MUC_DO_MAP[v] || v || '-'}</Tag> },\\n    { title: 'Ngành nghề', width: 140, render: (_, r) => (r.nganh_nghe && r.nganh_nghe.ten_nganh_nghe) || '-' },\\n    { title: 'Trạng thái', dataIndex: 'trang_thai', width: 130,\\n      render: v => { const s = TRANG_THAI_MAP[v] || { text: v, color: 'default' }; return <Tag color={s.color}>{s.text}</Tag>; } },\\n    { title: 'Thao tác', width: 180, fixed: 'right',\\n      render: (_, r) => {\\n        if (r.trang_thai !== 'cho_phe_duyet') return <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>;\\n        return <Space>\\n          <Button type=\\"primary\\" size=\\"small\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => handleApprove(r)}>Duyệt</Button>\\n          <Button danger size=\\"small\\" onClick={() => openReject(r)}>Từ chối</Button>\\n          <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>\\n        </Space>;\\n      }\\n    }\\n  ];\\n\\n  const statusBtns = [\\n    { key: 'cho_phe_duyet', label: 'Chờ duyệt' },\\n    { key: 'da_phe_duyet', label: 'Đã duyệt' },\\n    { key: 'tu_choi', label: 'Từ chối' },\\n    { key: 'all', label: 'Tất cả' }\\n  ];\\n\\n  const pendingCount = filterStatus === 'cho_phe_duyet' ? data.length : 0;\\n\\n  return (\\n    <div style={{padding:16}}>\\n      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>\\n        <div style={{display:'flex',gap:8}}>\\n          {statusBtns.map(sb => (\\n            <Button key={sb.key} type={filterStatus === sb.key ? 'primary' : 'default'} size=\\"small\\" onClick={() => setFilterStatus(sb.key)}>\\n              {sb.label}{sb.key === 'cho_phe_duyet' && pendingCount > 0 ? <Badge count={pendingCount} size=\\"small\\" offset={[5,-3]} /> : null}\\n            </Button>\\n          ))}\\n        </div>\\n        <Button onClick={loadData} size=\\"small\\">Làm mới</Button>\\n      </div>\\n      <Table columns={columns} dataSource={data} rowKey=\\"id\\" loading={loading} size=\\"small\\"\\n        scroll={{x:900}} pagination={{pageSize:20,showSizeChanger:true,showTotal:t=>'Tổng: '+t+' câu hỏi'}}\\n        locale={{emptyText:<Empty description={filterStatus==='cho_phe_duyet'?'Không có câu hỏi chờ duyệt':'Không có dữ liệu'} />}} />\\n\\n      <Modal title={detail ? (detail.ten_cau_hoi || detail.ma_cau_hoi) : ''} open={showDetail} onCancel={() => setShowDetail(false)} width={700}\\n        footer={detail && detail.trang_thai === 'cho_phe_duyet' ? [\\n          <Button key=\\"reject\\" danger onClick={() => { setShowDetail(false); openReject(detail); }}>Từ chối</Button>,\\n          <Button key=\\"approve\\" type=\\"primary\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => { setShowDetail(false); handleApprove(detail); }}>Duyệt</Button>\\n        ] : null}>\\n        {detail && <Descriptions column={2} bordered size=\\"small\\">\\n          <Descriptions.Item label=\\"Mã câu hỏi\\">{detail.ma_cau_hoi || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Hình thức\\">{HINH_THUC_MAP[detail.hinh_thuc] || detail.hinh_thuc || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Chủ đề\\">{detail.chu_de || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Mức độ\\"><Tag color={MUC_DO_COLORS[detail.muc_do_kho] || 'default'}>{MUC_DO_MAP[detail.muc_do_kho] || '-'}</Tag></Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngành nghề\\">{(detail.nganh_nghe && detail.nganh_nghe.ten_nganh_nghe) || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc thợ\\">{(detail.bac_tho && detail.bac_tho.ten_bac_tho) || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Nguồn tạo\\">{detail.nguon_tao || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Trạng thái\\"><Tag color={(TRANG_THAI_MAP[detail.trang_thai]||{}).color}>{(TRANG_THAI_MAP[detail.trang_thai]||{}).text || detail.trang_thai}</Tag></Descriptions.Item>\\n          <Descriptions.Item label=\\"Nội dung\\" span={2}><div style={{whiteSpace:'pre-wrap',maxHeight:200,overflow:'auto'}}>{detail.noi_dung || '-'}</div></Descriptions.Item>\\n          <Descriptions.Item label=\\"Đáp án\\" span={2}><div style={{whiteSpace:'pre-wrap',maxHeight:150,overflow:'auto'}}>{detail.dap_an || '-'}</div></Descriptions.Item>\\n          <Descriptions.Item label=\\"Đáp án đúng\\" span={2}><Text strong type=\\"success\\">{detail.dap_an_dung || '-'}</Text></Descriptions.Item>\\n          <Descriptions.Item label=\\"Giải thích\\" span={2}><div style={{whiteSpace:'pre-wrap',maxHeight:150,overflow:'auto'}}>{detail.giai_thich || '-'}</div></Descriptions.Item>\\n          {detail.trang_thai === 'tu_choi' && <Descriptions.Item label=\\"Lý do từ chối\\" span={2}><Text type=\\"danger\\">{detail.y_kien_phe_duyet || '-'}</Text></Descriptions.Item>}\\n        </Descriptions>}\\n      </Modal>\\n\\n      <Modal title=\\"Từ chối câu hỏi\\" open={showReject} onOk={handleReject} onCancel={() => setShowReject(false)}\\n        okText=\\"Xác nhận từ chối\\" cancelText=\\"Hủy\\" okButtonProps={{danger:true,loading:actionLoading}}>\\n        {rejectItem && <div>\\n          <p>Câu hỏi: <strong>{rejectItem.ten_cau_hoi || rejectItem.ma_cau_hoi}</strong></p>\\n          <p style={{marginBottom:8}}>Lý do từ chối <span style={{color:'red'}}>*</span></p>\\n          <TextArea rows={3} value={rejectReason} onChange={e => setRejectReason(e.target.value)} placeholder=\\"Nhập lý do từ chối câu hỏi...\\" />\\n        </div>}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);\\n"},"showBlockCard":{"showBlockCard":false}},"__flowSurfaceMeta":{"declaredKey":"duyetCauHoi"}}}
evj2o98yv9u	evj2o98yv9u	{"parentId":"kogk92gt22e","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// KH-04: Duyệt khóa huấn luyện - CBAT\\nconst { useState, useEffect, useCallback } = ctx.libs.React;\\nconst { Table, Tag, Button, Modal, Space, Input, Descriptions, Badge, message, Empty, Typography } = ctx.libs.antd;\\nconst { TextArea } = Input;\\nconst { Text } = Typography;\\nconst dayjs = ctx.libs.dayjs;\\n\\nconst API_BASE = '/api';\\n\\nfunction getHeaders() {\\n  const headers = { 'Content-Type': 'application/json' };\\n  const token = localStorage.getItem('NOCOBASE_TOKEN');\\n  if (token) headers['Authorization'] = 'Bearer ' + token;\\n  return headers;\\n}\\n\\nasync function apiGet(resource, params) {\\n  const parts = [];\\n  if (params) {\\n    for (const [k, v] of Object.entries(params)) {\\n      if (Array.isArray(v)) {\\n        v.forEach(item => parts.push(k + '[]=' + encodeURIComponent(item)));\\n      } else if (typeof v === 'object') {\\n        parts.push('filter=' + encodeURIComponent(JSON.stringify(v)));\\n      } else {\\n        parts.push(k + '=' + encodeURIComponent(v));\\n      }\\n    }\\n  }\\n  const qs = parts.length ? '?' + parts.join('&') : '';\\n  const resp = await fetch(API_BASE + '/' + resource + ':list' + qs, { headers: getHeaders() });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nasync function apiUpdate(resource, filterObj, values) {\\n  const resp = await fetch(API_BASE + '/' + resource + ':update?filter=' + encodeURIComponent(JSON.stringify(filterObj)), {\\n    method: 'POST', headers: getHeaders(), body: JSON.stringify(values)\\n  });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nconst HINH_THUC_MAP = { truc_tuyen: 'Trực tuyến', truc_tiep: 'Trực tiếp', ket_hop: 'Kết hợp' };\\nconst TRANG_THAI_MAP = {\\n  cho_phe_duyet: { text: 'Chờ phê duyệt', color: 'orange' },\\n  da_phe_duyet: { text: 'Đã phê duyệt', color: 'green' },\\n  tu_choi: { text: 'Từ chối', color: 'red' },\\n  nhap: { text: 'Nháp', color: 'default' },\\n  dang_dien_ra: { text: 'Đang diễn ra', color: 'blue' },\\n  hoan_thanh: { text: 'Hoàn thành', color: 'cyan' }\\n};\\n\\nfunction App() {\\n  const [data, setData] = useState([]);\\n  const [loading, setLoading] = useState(true);\\n  const [detail, setDetail] = useState(null);\\n  const [showDetail, setShowDetail] = useState(false);\\n  const [showReject, setShowReject] = useState(false);\\n  const [rejectReason, setRejectReason] = useState('');\\n  const [rejectItem, setRejectItem] = useState(null);\\n  const [actionLoading, setActionLoading] = useState(false);\\n  const [filterStatus, setFilterStatus] = useState('cho_phe_duyet');\\n\\n  const loadData = useCallback(async () => {\\n    setLoading(true);\\n    try {\\n      const filter = {};\\n      if (filterStatus !== 'all') filter.trang_thai = filterStatus;\\n      const resp = await apiGet('khoa_huan_luyen', {\\n        filter: JSON.stringify(filter), sort: ['-createdAt'],\\n        appends: ['nganh_nghe','bac_tho','bac_dich'], pageSize: 50\\n      });\\n      setData((resp.data && resp.data.data) || resp.data || []);\\n    } catch(err) { message.error('Lỗi tải danh sách khóa huấn luyện'); }\\n    setLoading(false);\\n  }, [filterStatus]);\\n\\n  useEffect(() => { loadData(); }, [loadData]);\\n\\n  const handleApprove = (record) => {\\n    Modal.confirm({\\n      title: 'Xác nhận duyệt khóa huấn luyện',\\n      content: <div><p>Duyệt khóa: <strong>{record.ten_khoa_hoc}</strong>?</p><p style={{color:'#666'}}>Khóa huấn luyện sẽ sẵn sàng xếp lớp.</p></div>,\\n      okText: 'Duyệt', cancelText: 'Hủy',\\n      okButtonProps: { style: { background: '#52c41a', borderColor: '#52c41a' } },\\n      onOk: async () => {\\n        setActionLoading(true);\\n        try {\\n          await apiUpdate('khoa_huan_luyen', { id: record.id }, { trang_thai: 'da_phe_duyet' });\\n          message.success('Đã duyệt khóa huấn luyện'); loadData();\\n        } catch(err) { message.error('Lỗi duyệt: ' + err.message); }\\n        setActionLoading(false);\\n      }\\n    });\\n  };\\n\\n  const openReject = (record) => { setRejectItem(record); setRejectReason(''); setShowReject(true); };\\n\\n  const handleReject = async () => {\\n    if (!rejectReason.trim()) { message.warning('Vui lòng nhập lý do từ chối'); return; }\\n    setActionLoading(true);\\n    try {\\n      await apiUpdate('khoa_huan_luyen', { id: rejectItem.id }, { trang_thai: 'tu_choi', y_kien_phe_duyet: rejectReason });\\n      message.success('Đã từ chối khóa huấn luyện'); setShowReject(false); loadData();\\n    } catch(err) { message.error('Lỗi từ chối: ' + err.message); }\\n    setActionLoading(false);\\n  };\\n\\n  const columns = [\\n    { title: 'Mã', dataIndex: 'ma_khoa_hoc', width: 110 },\\n    { title: 'Tên khóa học', dataIndex: 'ten_khoa_hoc', ellipsis: true,\\n      render: (v, r) => <a onClick={() => { setDetail(r); setShowDetail(true); }}>{v}</a> },\\n    { title: 'Hình thức', dataIndex: 'hinh_thuc', width: 110, render: v => HINH_THUC_MAP[v] || v || '-' },\\n    { title: 'Thời lượng', dataIndex: 'thoi_luong_gio', width: 100, render: v => v ? v + ' giờ' : '-' },\\n    { title: 'Ngày BĐ', dataIndex: 'ngay_bat_dau', width: 110, render: v => v ? dayjs(v).format('DD/MM/YYYY') : '-' },\\n    { title: 'Ngày KT', dataIndex: 'ngay_ket_thuc', width: 110, render: v => v ? dayjs(v).format('DD/MM/YYYY') : '-' },\\n    { title: 'Giảng viên', dataIndex: 'giang_vien', width: 140, ellipsis: true },\\n    { title: 'Trạng thái', dataIndex: 'trang_thai', width: 130,\\n      render: v => { const s = TRANG_THAI_MAP[v] || { text: v, color: 'default' }; return <Tag color={s.color}>{s.text}</Tag>; } },\\n    { title: 'Thao tác', width: 180, fixed: 'right',\\n      render: (_, r) => {\\n        if (r.trang_thai !== 'cho_phe_duyet') return <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>;\\n        return <Space>\\n          <Button type=\\"primary\\" size=\\"small\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => handleApprove(r)}>Duyệt</Button>\\n          <Button danger size=\\"small\\" onClick={() => openReject(r)}>Từ chối</Button>\\n          <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>\\n        </Space>;\\n      }\\n    }\\n  ];\\n\\n  const statusBtns = [\\n    { key: 'cho_phe_duyet', label: 'Chờ duyệt' },\\n    { key: 'da_phe_duyet', label: 'Đã duyệt' },\\n    { key: 'tu_choi', label: 'Từ chối' },\\n    { key: 'all', label: 'Tất cả' }\\n  ];\\n\\n  const pendingCount = filterStatus === 'cho_phe_duyet' ? data.length : 0;\\n\\n  return (\\n    <div style={{padding:16}}>\\n      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>\\n        <div style={{display:'flex',gap:8}}>\\n          {statusBtns.map(sb => (\\n            <Button key={sb.key} type={filterStatus === sb.key ? 'primary' : 'default'} size=\\"small\\" onClick={() => setFilterStatus(sb.key)}>\\n              {sb.label}{sb.key === 'cho_phe_duyet' && pendingCount > 0 ? <Badge count={pendingCount} size=\\"small\\" offset={[5,-3]} /> : null}\\n            </Button>\\n          ))}\\n        </div>\\n        <Button onClick={loadData} size=\\"small\\">Làm mới</Button>\\n      </div>\\n      <Table columns={columns} dataSource={data} rowKey=\\"id\\" loading={loading} size=\\"small\\"\\n        scroll={{x:1000}} pagination={{pageSize:20,showSizeChanger:true,showTotal:t=>'Tổng: '+t+' khóa huấn luyện'}}\\n        locale={{emptyText:<Empty description={filterStatus==='cho_phe_duyet'?'Không có khóa chờ duyệt':'Không có dữ liệu'} />}} />\\n\\n      <Modal title={detail ? detail.ten_khoa_hoc : ''} open={showDetail} onCancel={() => setShowDetail(false)} width={700}\\n        footer={detail && detail.trang_thai === 'cho_phe_duyet' ? [\\n          <Button key=\\"reject\\" danger onClick={() => { setShowDetail(false); openReject(detail); }}>Từ chối</Button>,\\n          <Button key=\\"approve\\" type=\\"primary\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => { setShowDetail(false); handleApprove(detail); }}>Duyệt</Button>\\n        ] : null}>\\n        {detail && <Descriptions column={2} bordered size=\\"small\\">\\n          <Descriptions.Item label=\\"Mã khóa học\\">{detail.ma_khoa_hoc || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Hình thức\\">{HINH_THUC_MAP[detail.hinh_thuc] || detail.hinh_thuc || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Thời lượng\\">{detail.thoi_luong_gio ? detail.thoi_luong_gio + ' giờ' : '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Đối tượng\\">{detail.doi_tuong || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngày bắt đầu\\">{detail.ngay_bat_dau ? dayjs(detail.ngay_bat_dau).format('DD/MM/YYYY') : '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngày kết thúc\\">{detail.ngay_ket_thuc ? dayjs(detail.ngay_ket_thuc).format('DD/MM/YYYY') : '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Giảng viên\\" span={2}>{detail.giang_vien || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Mô tả\\" span={2}><div style={{whiteSpace:'pre-wrap',maxHeight:150,overflow:'auto'}}>{detail.mo_ta || '-'}</div></Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngành nghề\\" span={2}>\\n            {detail.nganh_nghe ? (Array.isArray(detail.nganh_nghe)\\n              ? detail.nganh_nghe.map(n => n.ten_nganh_nghe).join(', ')\\n              : detail.nganh_nghe.ten_nganh_nghe) : '-'}\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Trạng thái\\" span={2}><Tag color={(TRANG_THAI_MAP[detail.trang_thai]||{}).color}>{(TRANG_THAI_MAP[detail.trang_thai]||{}).text || detail.trang_thai}</Tag></Descriptions.Item>\\n          {detail.trang_thai === 'tu_choi' && <Descriptions.Item label=\\"Lý do từ chối\\" span={2}><Text type=\\"danger\\">{detail.y_kien_phe_duyet || '-'}</Text></Descriptions.Item>}\\n        </Descriptions>}\\n      </Modal>\\n\\n      <Modal title=\\"Từ chối khóa huấn luyện\\" open={showReject} onOk={handleReject} onCancel={() => setShowReject(false)}\\n        okText=\\"Xác nhận từ chối\\" cancelText=\\"Hủy\\" okButtonProps={{danger:true,loading:actionLoading}}>\\n        {rejectItem && <div>\\n          <p>Khóa: <strong>{rejectItem.ten_khoa_hoc}</strong></p>\\n          <p style={{marginBottom:8}}>Lý do từ chối <span style={{color:'red'}}>*</span></p>\\n          <TextArea rows={3} value={rejectReason} onChange={e => setRejectReason(e.target.value)} placeholder=\\"Nhập lý do từ chối khóa huấn luyện...\\" />\\n        </div>}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);\\n"},"showBlockCard":{"showBlockCard":false}},"__flowSurfaceMeta":{"declaredKey":"duyetKhoaHL"}}}
8roejajq76s	8roejajq76s	{"parentId":"kfi7kzoq31m","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// DT-04: Duyệt đề thi - CBAT\\nconst { useState, useEffect, useCallback } = ctx.libs.React;\\nconst { Table, Tag, Button, Modal, Space, Input, Descriptions, Badge, message, Empty, Typography } = ctx.libs.antd;\\nconst { TextArea } = Input;\\nconst { Text } = Typography;\\nconst dayjs = ctx.libs.dayjs;\\n\\nconst API_BASE = '/api';\\n\\nfunction getHeaders() {\\n  const headers = { 'Content-Type': 'application/json' };\\n  const token = localStorage.getItem('NOCOBASE_TOKEN');\\n  if (token) headers['Authorization'] = 'Bearer ' + token;\\n  return headers;\\n}\\n\\nasync function apiGet(resource, params) {\\n  const parts = [];\\n  if (params) {\\n    for (const [k, v] of Object.entries(params)) {\\n      if (Array.isArray(v)) {\\n        v.forEach(item => parts.push(k + '[]=' + encodeURIComponent(item)));\\n      } else if (typeof v === 'object') {\\n        parts.push('filter=' + encodeURIComponent(JSON.stringify(v)));\\n      } else {\\n        parts.push(k + '=' + encodeURIComponent(v));\\n      }\\n    }\\n  }\\n  const qs = parts.length ? '?' + parts.join('&') : '';\\n  const resp = await fetch(API_BASE + '/' + resource + ':list' + qs, { headers: getHeaders() });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nasync function apiUpdate(resource, filterObj, values) {\\n  const resp = await fetch(API_BASE + '/' + resource + ':update?filter=' + encodeURIComponent(JSON.stringify(filterObj)), {\\n    method: 'POST', headers: getHeaders(), body: JSON.stringify(values)\\n  });\\n  if (!resp.ok) throw new Error('API error ' + resp.status);\\n  return resp.json();\\n}\\n\\nconst TRANG_THAI_MAP = {\\n  cho_phe_duyet: { text: 'Chờ phê duyệt', color: 'orange' },\\n  da_phe_duyet: { text: 'Đã phê duyệt', color: 'green' },\\n  tu_choi: { text: 'Từ chối', color: 'red' },\\n  nhap: { text: 'Nháp', color: 'default' }\\n};\\nconst MUC_DO_MAP = { de: 'Dễ', trung_binh: 'TB', kho: 'Khó' };\\n\\nfunction App() {\\n  const [data, setData] = useState([]);\\n  const [loading, setLoading] = useState(true);\\n  const [detail, setDetail] = useState(null);\\n  const [showDetail, setShowDetail] = useState(false);\\n  const [showReject, setShowReject] = useState(false);\\n  const [rejectReason, setRejectReason] = useState('');\\n  const [rejectItem, setRejectItem] = useState(null);\\n  const [actionLoading, setActionLoading] = useState(false);\\n  const [filterStatus, setFilterStatus] = useState('cho_phe_duyet');\\n\\n  const loadData = useCallback(async () => {\\n    setLoading(true);\\n    try {\\n      const filter = {};\\n      if (filterStatus !== 'all') filter.trang_thai = filterStatus;\\n      const resp = await apiGet('de_thi', {\\n        filter: JSON.stringify(filter), sort: ['-createdAt'],\\n        appends: ['nganh_nghe','bac_tho','cau_hoi'], pageSize: 50\\n      });\\n      setData((resp.data && resp.data.data) || resp.data || []);\\n    } catch(err) { message.error('Lỗi tải danh sách đề thi'); }\\n    setLoading(false);\\n  }, [filterStatus]);\\n\\n  useEffect(() => { loadData(); }, [loadData]);\\n\\n  const handleApprove = (record) => {\\n    Modal.confirm({\\n      title: 'Xác nhận duyệt đề thi',\\n      content: <div><p>Duyệt đề thi: <strong>{record.ten_de_thi}</strong>?</p><p style={{color:'#666'}}>Đề thi sẽ sẵn sàng sử dụng cho kỳ thi.</p></div>,\\n      okText: 'Duyệt', cancelText: 'Hủy',\\n      okButtonProps: { style: { background: '#52c41a', borderColor: '#52c41a' } },\\n      onOk: async () => {\\n        setActionLoading(true);\\n        try {\\n          await apiUpdate('de_thi', { id: record.id }, { trang_thai: 'da_phe_duyet' });\\n          message.success('Đã duyệt đề thi'); loadData();\\n        } catch(err) { message.error('Lỗi duyệt: ' + err.message); }\\n        setActionLoading(false);\\n      }\\n    });\\n  };\\n\\n  const openReject = (record) => { setRejectItem(record); setRejectReason(''); setShowReject(true); };\\n\\n  const handleReject = async () => {\\n    if (!rejectReason.trim()) { message.warning('Vui lòng nhập lý do từ chối'); return; }\\n    setActionLoading(true);\\n    try {\\n      await apiUpdate('de_thi', { id: rejectItem.id }, { trang_thai: 'tu_choi', y_kien_phe_duyet: rejectReason });\\n      message.success('Đã từ chối đề thi'); setShowReject(false); loadData();\\n    } catch(err) { message.error('Lỗi từ chối: ' + err.message); }\\n    setActionLoading(false);\\n  };\\n\\n  const columns = [\\n    { title: 'Mã', dataIndex: 'ma_de_thi', width: 110 },\\n    { title: 'Tên đề thi', dataIndex: 'ten_de_thi', ellipsis: true,\\n      render: (v, r) => <a onClick={() => { setDetail(r); setShowDetail(true); }}>{v}</a> },\\n    { title: 'Số câu', dataIndex: 'so_cau_hoi', width: 80, render: v => v || '-' },\\n    { title: 'Thời gian (phút)', dataIndex: 'thoi_gian_lam_bai', width: 120, render: v => v || '-' },\\n    { title: 'Điểm đạt', dataIndex: 'diem_dat', width: 90, render: v => v != null ? v : '-' },\\n    { title: 'Ngành nghề', width: 140, render: (_, r) => (r.nganh_nghe && r.nganh_nghe.ten_nganh_nghe) || '-' },\\n    { title: 'Phiên bản', dataIndex: 'phien_ban', width: 90 },\\n    { title: 'Trạng thái', dataIndex: 'trang_thai', width: 130,\\n      render: v => { const s = TRANG_THAI_MAP[v] || { text: v, color: 'default' }; return <Tag color={s.color}>{s.text}</Tag>; } },\\n    { title: 'Thao tác', width: 180, fixed: 'right',\\n      render: (_, r) => {\\n        if (r.trang_thai !== 'cho_phe_duyet') return <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>;\\n        return <Space>\\n          <Button type=\\"primary\\" size=\\"small\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => handleApprove(r)}>Duyệt</Button>\\n          <Button danger size=\\"small\\" onClick={() => openReject(r)}>Từ chối</Button>\\n          <Button size=\\"small\\" onClick={() => { setDetail(r); setShowDetail(true); }}>Xem</Button>\\n        </Space>;\\n      }\\n    }\\n  ];\\n\\n  const statusBtns = [\\n    { key: 'cho_phe_duyet', label: 'Chờ duyệt' },\\n    { key: 'da_phe_duyet', label: 'Đã duyệt' },\\n    { key: 'tu_choi', label: 'Từ chối' },\\n    { key: 'all', label: 'Tất cả' }\\n  ];\\n\\n  const pendingCount = filterStatus === 'cho_phe_duyet' ? data.length : 0;\\n\\n  return (\\n    <div style={{padding:16}}>\\n      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>\\n        <div style={{display:'flex',gap:8}}>\\n          {statusBtns.map(sb => (\\n            <Button key={sb.key} type={filterStatus === sb.key ? 'primary' : 'default'} size=\\"small\\" onClick={() => setFilterStatus(sb.key)}>\\n              {sb.label}{sb.key === 'cho_phe_duyet' && pendingCount > 0 ? <Badge count={pendingCount} size=\\"small\\" offset={[5,-3]} /> : null}\\n            </Button>\\n          ))}\\n        </div>\\n        <Button onClick={loadData} size=\\"small\\">Làm mới</Button>\\n      </div>\\n      <Table columns={columns} dataSource={data} rowKey=\\"id\\" loading={loading} size=\\"small\\"\\n        scroll={{x:950}} pagination={{pageSize:20,showSizeChanger:true,showTotal:t=>'Tổng: '+t+' đề thi'}}\\n        locale={{emptyText:<Empty description={filterStatus==='cho_phe_duyet'?'Không có đề thi chờ duyệt':'Không có dữ liệu'} />}} />\\n\\n      <Modal title={detail ? detail.ten_de_thi : ''} open={showDetail} onCancel={() => setShowDetail(false)} width={700}\\n        footer={detail && detail.trang_thai === 'cho_phe_duyet' ? [\\n          <Button key=\\"reject\\" danger onClick={() => { setShowDetail(false); openReject(detail); }}>Từ chối</Button>,\\n          <Button key=\\"approve\\" type=\\"primary\\" style={{background:'#52c41a',borderColor:'#52c41a'}} onClick={() => { setShowDetail(false); handleApprove(detail); }}>Duyệt</Button>\\n        ] : null}>\\n        {detail && <Descriptions column={2} bordered size=\\"small\\">\\n          <Descriptions.Item label=\\"Mã đề thi\\">{detail.ma_de_thi || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Phiên bản\\">{detail.phien_ban || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Số câu hỏi\\">{detail.so_cau_hoi || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Thời gian\\">{detail.thoi_gian_lam_bai ? detail.thoi_gian_lam_bai + ' phút' : '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Điểm đạt\\">{detail.diem_dat != null ? detail.diem_dat : '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngành nghề\\">{(detail.nganh_nghe && detail.nganh_nghe.ten_nganh_nghe) || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc thợ\\" span={2}>{(detail.bac_tho && detail.bac_tho.ten_bac_tho) || '-'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Mô tả\\" span={2}><div style={{whiteSpace:'pre-wrap',maxHeight:150,overflow:'auto'}}>{detail.mo_ta || '-'}</div></Descriptions.Item>\\n          <Descriptions.Item label=\\"Trạng thái\\" span={2}><Tag color={(TRANG_THAI_MAP[detail.trang_thai]||{}).color}>{(TRANG_THAI_MAP[detail.trang_thai]||{}).text || detail.trang_thai}</Tag></Descriptions.Item>\\n          {detail.cau_hoi && detail.cau_hoi.length > 0 && <Descriptions.Item label=\\"Danh sách câu hỏi\\" span={2}>\\n            <div style={{maxHeight:200,overflow:'auto'}}>\\n              <Table size=\\"small\\" pagination={false} rowKey=\\"id\\" dataSource={detail.cau_hoi}\\n                columns={[\\n                  { title: 'Mã', dataIndex: 'ma_cau_hoi', width: 100 },\\n                  { title: 'Tên', dataIndex: 'ten_cau_hoi', ellipsis: true },\\n                  { title: 'Mức độ', dataIndex: 'muc_do_kho', width: 100, render: v => MUC_DO_MAP[v] || v || '-' }\\n                ]} />\\n            </div>\\n          </Descriptions.Item>}\\n          {detail.trang_thai === 'tu_choi' && <Descriptions.Item label=\\"Lý do từ chối\\" span={2}><Text type=\\"danger\\">{detail.y_kien_phe_duyet || '-'}</Text></Descriptions.Item>}\\n        </Descriptions>}\\n      </Modal>\\n\\n      <Modal title=\\"Từ chối đề thi\\" open={showReject} onOk={handleReject} onCancel={() => setShowReject(false)}\\n        okText=\\"Xác nhận từ chối\\" cancelText=\\"Hủy\\" okButtonProps={{danger:true,loading:actionLoading}}>\\n        {rejectItem && <div>\\n          <p>Đề thi: <strong>{rejectItem.ten_de_thi}</strong></p>\\n          <p style={{marginBottom:8}}>Lý do từ chối <span style={{color:'red'}}>*</span></p>\\n          <TextArea rows={3} value={rejectReason} onChange={e => setRejectReason(e.target.value)} placeholder=\\"Nhập lý do từ chối đề thi...\\" />\\n        </div>}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);\\n"},"showBlockCard":{"showBlockCard":false}},"__flowSurfaceMeta":{"declaredKey":"duyetDeThi"}}}
