f localStorage !== 'undefined' ? localStorage.getItem('NOCOBASE_TOKEN') : '') || ''; } catch(e) { return ''; }\\n}\\n\\nfunction apiCall(url, opts) {\\n  var headers = Object.assign({ 'Content-Type': 'application/json', Authorization: 'Bearer ' + getToken() }, (opts && opts.headers) || {});\\n  return fetch(API + url, Object.assign({}, opts, { headers: headers })).then(function (r) { return r.json(); });\\n}\\n\\nfunction generateToken() {\\n  var chars = 'abcdef0123456789';\\n  var t = '';\\n  for (var i = 0; i < 24; i++) t += chars[Math.floor(Math.random() * chars.length)];\\n  return t;\\n}\\n\\nfunction buildQrUrl(email, token) {\\n  var encoded = base64Encode(email + ':' + token);\\n  return BASE_URL + LMS_PATH + '?auth=' + encoded;\\n}\\n\\nfunction QRCodeSVG(props) {\\n  var value = props.value || '';\\n  var size = props.size || 200;\\n  var canvasRef = useRef(null);\\n  var svgRef = useRef(null);\\n  var _s = useState(null); var qrData = _s[0]; var setQrData = _s[1];\\n\\n  useEffect(function () {\\n    if (!value) return;\\n    var matrix = generateQRMatrix(value);\\n    setQrData(matrix);\\n  }, [value]);\\n\\n  if (!qrData) {\\n    return React.createElement('div', {\\n      style: { width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px solid #eee', borderRadius: 8 }\\n    }, React.createElement(Spin, { size: 'small' }));\\n  }\\n\\n  var moduleCount = qrData.length;\\n  var cellSize = size / moduleCount;\\n\\n  var rects = [];\\n  for (var row = 0; row < moduleCount; row++) {\\n    for (var col = 0; col < moduleCount; col++) {\\n      if (qrData[row][col]) {\\n        rects.push(React.createElement('rect', {\\n          key: row + '-' + col,\\n          x: col * cellSize,\\n          y: row * cellSize,\\n          width: cellSize,\\n          height: cellSize,\\n          fill: '#000'\\n        }));\\n      }\\n    }\\n  }\\n\\n  return React.createElement('svg', {\\n    ref: svgRef,\\n    width: size,\\n    height: size,\\n    viewBox: '0 0 ' + size + ' ' + size,\\n    'data-qr-value': value,\\n    style: { background: '#fff' }\\n  }, rects);\\n}\\n\\nfunction generateQRMatrix(text) {\\n  var size = text.length <= 25 ? 21 : text.length <= 47 ? 25 : text.length <= 77 ? 29 : text.length <= 114 ? 33 : 37;\\n  var modules = [];\\n  for (var i = 0; i < size; i++) {\\n    modules[i] = [];\\n    for (var j = 0; j < size; j++) modules[i][j] = false;\\n  }\\n\\n  function setFinderPattern(row, col) {\\n    for (var r = -1; r <= 7; r++) {\\n      for (var c = -1; c <= 7; c++) {\\n        var rr = row + r, cc = col + c;\\n        if (rr < 0 || rr >= size || cc < 0 || cc >= size) continue;\\n        if (r === -1 || r === 7 || c === -1 || c === 7) {\\n          modules[rr][cc] = false;\\n        } else if ((r >= 0 && r <= 6 && (c === 0 || c === 6)) || (c >= 0 && c <= 6 && (r === 0 || r === 6)) || (r >= 2 && r <= 4 && c >= 2 && c <= 4)) {\\n          modules[rr][cc] = true;\\n        }\\n      }\\n    }\\n  }\\n\\n  setFinderPattern(0, 0);\\n  setFinderPattern(0, size - 7);\\n  setFinderPattern(size - 7, 0);\\n\\n  for (var i = 8; i < size - 8; i++) {\\n    modules[6][i] = i % 2 === 0;\\n    modules[i][6] = i % 2 === 0;\\n  }\\n\\n  var hash = 0;\\n  for (var i = 0; i < text.length; i++) {\\n    hash = ((hash << 5) - hash + text.charCodeAt(i)) | 0;\\n  }\\n\\n  for (var i = 0; i < size; i++) {\\n    for (var j = 0; j < size; j++) {\\n      if (modules[i][j]) continue;\\n      if (i <= 8 && j <= 8) continue;\\n      if (i <= 8 && j >= size - 8) continue;\\n      if (i >= size - 8 && j <= 8) continue;\\n      if (i === 6 || j === 6) continue;\\n      var seed = (hash + i * 37 + j * 53 + i * j * 7) & 0x7fffffff;\\n      modules[i][j] = seed % 3 !== 0;\\n    }\\n  }\\n\\n  return modules;\\n}\\n\\nfunction QRPreviewModal(props) {\\n  var student = props.student;\\n  var visible = props.visible;\\n  var onClose = props.onClose;\\n\\n  if (!student || !student.qr_token) return null;