wvu50mdd7kx	wvu50mdd7kx	{"parentId":"euz8ylw3ym4","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Danh mục dùng chung","description":"Quản trị loại danh mục, giá trị, phân cấp, trạng thái và bản dịch."},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const React = ctx.libs.React;\\nconst {\\n  Alert,\\n  Badge,\\n  Button,\\n  Card,\\n  Col,\\n  DatePicker,\\n  Descriptions,\\n  Divider,\\n  Empty,\\n  Form,\\n  Input,\\n  InputNumber,\\n  List,\\n  Modal,\\n  Popconfirm,\\n  Row,\\n  Select,\\n  Space,\\n  Spin,\\n  Switch,\\n  Table,\\n  Tabs,\\n  Tag,\\n  Tooltip,\\n  Typography,\\n} = ctx.libs.antd;\\nconst {\\n  EyeOutlined,\\n  EditOutlined,\\n  GlobalOutlined,\\n  PlusOutlined,\\n  ReloadOutlined,\\n  StopOutlined,\\n  CheckCircleOutlined,\\n} = ctx.libs.antdIcons;\\nconst dayjs = ctx.libs.dayjs;\\n\\nconst normalizeCode = (value) => String(value || '').trim().toUpperCase();\\nconst statusOptions = [\\n  { value: 'active', label: 'Đang sử dụng' },\\n  { value: 'inactive', label: 'Ngừng sử dụng' },\\n];\\nconst languageOptions = [\\n  { value: 'vi-VN', label: 'Tiếng Việt' },\\n  { value: 'en-US', label: 'Tiếng Anh' },\\n];\\n\\nconst api = async (url, options = {}) => {\\n  const response = await ctx.request({\\n    url,\\n    method: options.method || 'get',\\n    params: options.params,\\n    data: options.data,\\n    skipNotify: true,\\n  });\\n  return response?.data || response;\\n};\\n\\nconst CatalogManager = () => {\\n  const [loading, setLoading] = React.useState(true);\\n  const [error, setError] = React.useState('');\\n  const [types, setTypes] = React.useState([]);\\n  const [values, setValues] = React.useState([]);\\n  const [selectedTypeId, setSelectedTypeId] = React.useState(null);\\n  const [typeSearch, setTypeSearch] = React.useState('');\\n  const [typeStatus, setTypeStatus] = React.useState('all');\\n  const [valueSearch, setValueSearch] = React.useState('');\\n  const [valueStatus, setValueStatus] = React.useState('all');\\n  const [parentFilter, setParentFilter] = React.useState('all');\\n  const [typeModal, setTypeModal] = React.useState(null);\\n  const [valueModal, setValueModal] = React.useState(null);\\n  const [detailRecord, setDetailRecord] = React.useState(null);\\n  const [translationTarget, setTranslationTarget] = React.useState(null);\\n  const [translations, setTranslations] = React.useState([]);\\n  const [saving, setSaving] = React.useState(false);\\n  const [typeForm] = Form.useForm();\\n  const [valueForm] = Form.useForm();\\n  const [translationForm] = Form.useForm();\\n\\n  const roleNames = (ctx.user?.roles || ctx.auth?.user?.roles || []).map((role) => role.name || role);\\n  const canManage = roleNames.length === 0 || roleNames.includes('root') || roleNames.includes('admin');\\n\\n  const selectedType = types.find((item) => item.id === selectedTypeId) || null;\\n\\n  const loadData = React.useCallback(async (keepSelection = true) => {\\n    setLoading(true);\\n    setError('');\\n    try {\\n      const [typeResponse, valueResponse] = await Promise.all([\\n        api('/loai_danh_muc:list', {\\n          params: {\\n            pageSize: 500,\\n            sort: ['thu_tu', 'id'],\\n            filter: { is_deleted: { $isFalsy: true } },\\n          },\\n        }),\\n        api('/gia_tri_danh_muc:list', {\\n          params: {\\n            pageSize: 1000,\\n            sort: ['thu_tu', 'id'],\\n            appends: ['loai_danh_muc', 'gia_tri_cha'],\\n            filter: { is_deleted: { $isFalsy: true } },\\n          },\\n        }),\\n      ]);\\n      const nextTypes = typeResponse?.data || [];\\n      const nextValues = valueResponse?.data || [];\\n      const counts = nextValues.reduce((result, item) => {\\n        if (item.trang_thai === 'active') {\\n          result[item.loai_danh_muc_id] = (result[item.loai_danh_muc_id] || 0) + 1;\\n        }\\n        return result;\\n      }, {});\\n      const enrichedTypes = nextTypes.map((item) => ({\\n        ...item,\\n        so_gia_tri_hoat_dong: counts[item.id] || 0,\\n      }));\\n      setTypes(enrichedTypes);\\n      setValues(nextValues);\\n      const currentExists = enrichedTypes.some((item) => item.id === selectedTypeId);\\n      if (!keepSelection || !currentExists) {\\n        setSelectedTypeId(enrichedTypes[0]?.id || null);\\n      }\\n    } catch (loadError) {\\n      setError(String(loadError?.message || 'Không thể tải dữ liệu danh mục.'));\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [selectedTypeId]);\\n\\n  React.useEffect(() => {\\n    loadData(false);\\n  }, []);\\n\\n  const filteredTypes = types.filter((item) => {\\n    const keyword = typeSearch.trim().toLowerCase();\\n    const matchesText = !keyword || `${item.ma_loai} ${item.ten_loai}`.toLowerCase().includes(keyword);\\n    const matchesStatus = typeStatus === 'all' || item.trang_thai === typeStatus;\\n    return matchesText && matchesStatus;\\n  });\\n\\n  const typeValues = values.filter((item) => item.loai_danh_muc_id === selectedTypeId);\\n  const filteredValues = typeValues.filter((item) => {\\n    const keyword = valueSearch.trim().toLowerCase();\\n    const matchesText = !keyword || `${item.ma_gia_tri} ${item.ten_gia_tri} ${item.ten_viet_tat || ''}`.toLowerCase().includes(keyword);\\n    const matchesStatus = valueStatus === 'all' || item.trang_thai === valueStatus;\\n    const matchesParent = parentFilter === 'all' || String(item.gia_tri_cha_id || '') === String(parentFilter);\\n    return matchesText && matchesStatus && matchesParent;\\n  });\\n\\n  const openTypeModal = (record = null) => {\\n    typeForm.resetFields();\\n    typeForm.setFieldsValue(record ? {\\n      ...record,\\n      ma_loai: record.ma_loai,\\n    } : {\\n      trang_thai: 'active',\\n      cho_phep_phan_cap: false,\\n      cho_phep_da_ngon_ngu: false,\\n      thu_tu: (Math.max(0, ...types.map((item) => Number(item.thu_tu || 0))) + 1),\\n    });\\n    setTypeModal(record || { mode: 'create' });\\n  };\\n\\n  const openValueModal = (record = null, forcedTypeId = null) => {\\n    const targetTypeId = forcedTypeId || record?.loai_danh_muc_id || selectedTypeId;\\n    const targetValues = values.filter((item) => item.loai_danh_muc_id === targetTypeId);\\n    valueForm.resetFields();\\n    valueForm.setFieldsValue(record ? {\\n      ...record,\\n      hieu_luc_tu: record.hieu_luc_tu ? dayjs(record.hieu_luc_tu) : null,\\n      hieu_luc_den: record.hieu_luc_den ? dayjs(record.hieu_luc_den) : null,\\n    } : {\\n      loai_danh_muc_id: targetTypeId,\\n      trang_thai: 'active',\\n      thu_tu: Math.max(0, ...targetValues.map((item) => Number(item.thu_tu || 0))) + 1,\\n    });\\n    setValueModal(record || { mode: 'create', loai_danh_muc_id: targetTypeId });\\n  };\\n\\n  const saveType = async (continueToValue = false) => {\\n    const formValues = await typeForm.validateFields();\\n    const code = normalizeCode(formValues.ma_loai);\\n    if (!/^[A-Z0-9_]+$/.test(code)) {\\n      typeForm.setFields([{ name: 'ma_loai', errors: ['Mã chỉ gồm chữ không dấu, số và dấu gạch dưới.'] }]);\\n      return;\\n    }\\n    const duplicate = types.some((item) => item.ma_loai_chuan === code && item.id !== typeModal?.id);\\n    if (duplicate) {\\n      typeForm.setFields([{ name: 'ma_loai', errors: ['Mã loại danh mục đã tồn tại.'] }]);\\n      return;\\n    }\\n    if (typeModal?.id && typeModal.cho_phep_phan_cap && !formValues.cho_phep_phan_cap) {\\n      const hasChildren = values.some((item) => item.loai_danh_muc_id === typeModal.id && item.gia_tri_cha_id);\\n      if (hasChildren) {\\n        ctx.message.error('Không thể tắt phân cấp vì danh mục đang có giá trị con.');\\n        return;\\n      }\\n    }\\n    setSaving(true);\\n    try {\\n      const payload = {\\n        ...formValues,\\n        ma_loai: code,\\n        ma_loai_chuan: code,\\n        is_deleted: false,\\n      };\\n      let saved;\\n      if (typeModal?.id) {\\n        saved = await api(`/loai_danh_muc:update?filterByTk=${typeModal.id}`, { method: 'post', data: payload });\\n      } else {\\n        saved = await api('/loai_danh_muc:create', { method: 'post', data: { ...payload, la_danh_muc_he_thong: false } });\\n      }\\n      ctx.message.success(typeModal?.id ? 'Đã cập nhật loại danh mục.' : 'Đã tạo loại danh mục.');\\n      setTypeModal(null);\\n      await loadData(false);\\n      const savedId = saved?.data?.id || saved?.id;\\n      if (continueToValue && savedId) {\\n        setSelectedTypeId(savedId);\\n        openValueModal(null, savedId);\\n      }\\n    } catch (saveError) {\\n      ctx.message.error(String(saveError?.message || 'Không thể lưu loại danh mục.'));\\n    } finally {\\n      setSaving(false);\\n    }\\n  };\\n\\n  const descendantIds = (recordId) => {\\n    const result = new Set();\\n    function visit(id) {\\n      values.filter((item) => item.gia_tri_cha_id === id).forEach((child) => {\\n        if (!result.has(child.id)) {\\n          result.add(child.id);\\n          visit(child.id);\\n        }\\n      });\\n    }\\n    visit(recordId);\\n    return result;\\n  };\\n\\n  const saveValue = async (addAnother = false) => {\\n    const formValues = await valueForm.validateFields();\\n    const code = normalizeCode(formValues.ma_gia_tri);\\n    const typeId = formValues.loai_danh_muc_id;\\n    const targetType = types.find((item) => item.id === typeId);\\n    if (!/^[A-Z0-9_]+$/.test(code)) {\\n      valueForm.setFields([{ name: 'ma_gia_tri', errors: ['Mã chỉ gồm chữ không dấu, số và dấu gạch dưới.'] }]);\\n      return;\\n    }\\n    const duplicate = values.some((item) => item.loai_danh_muc_id === typeId && normalizeCode(item.ma_gia_tri) === code && item.id !== valueModal?.id);\\n    if (duplicate) {\\n      valueForm.setFields([{ name: 'ma_gia_tri', errors: ['Mã giá trị đã tồn tại trong loại danh mục này.'] }]);\\n      return;\\n    }\\n    if (formValues.gia_tri_cha_id) {\\n      const parent = values.find((item) => item.id === formValues.gia_tri_cha_id);\\n      if (!targetType?.cho_phep_phan_cap || !parent || parent.loai_danh_muc_id !== typeId) {\\n        ctx.message.error('Giá trị cha phải thuộc cùng loại danh mục có bật phân cấp.');\\n        return;\\n      }\\n      if (valueModal?.id && (formValues.gia_tri_cha_id === valueModal.id || descendantIds(valueModal.id).has(formValues.gia_tri_cha_id))) {\\n        ctx.message.error('Không thể chọn chính giá trị hoặc phần tử con làm giá trị cha.');\\n        return;\\n      }\\n    }\\n    if (formValues.hieu_luc_tu && formValues.hieu_luc_den && !formValues.hieu_luc_den.isAfter(formValues.hieu_luc_tu)) {\\n      valueForm.setFields([{ name: 'hieu_luc_den', errors: ['Hiệu lực đến phải sau hiệu lực từ.'] }]);\\n      return;\\n    }\\n    setSaving(true);\\n    try {\\n      const payload = {\\n        ...formValues,\\n        ma_gia_tri: code,\\n        khoa_duy_nhat: `${typeId}:${code}`,\\n        hieu_luc_tu: formValues.hieu_luc_tu?.toISOString() || null,\\n        hieu_luc_den: formValues.hieu_luc_den?.toISOString() || null,\\n        is_deleted: false,\\n      };\\n      if (valueModal?.id) {\\n        await api(`/gia_tri_danh_muc:update?filterByTk=${valueModal.id}`, { method: 'post', data: payload });\\n      } else {\\n        await api('/gia_tri_danh_muc:create', { method: 'post', data: payload });\\n      }\\n      ctx.message.success(valueModal?.id ? 'Đã cập nhật giá trị danh mục.' : 'Đã tạo giá trị danh mục.');\\n      await loadData(true);\\n      if (addAnother && !valueModal?.id) {\\n        valueForm.resetFields();\\n        valueForm.setFieldsValue({\\n          loai_danh_muc_id: typeId,\\n          trang_thai: 'active',\\n          thu_tu: Number(formValues.thu_tu || 0) + 1,\\n        });\\n      } else {\\n        setValueModal(null);\\n      }\\n    } catch (saveError) {\\n      ctx.message.error(String(saveError?.message || 'Không thể lưu giá trị danh mục.'));\\n    } finally {\\n      setSaving(false);\\n    }\\n  };\\n\\n  const toggleStatus = async (resource, record) => {\\n    const nextStatus = record.trang_thai === 'active' ? 'inactive' : 'active';\\n    setSaving(true);\\n    try {\\n      await api(`/${resource}:update?filterByTk=${record.id}`, { method: 'post', data: { trang_thai: nextStatus } });\\n      ctx.message.success(nextStatus === 'active' ? 'Đã kích hoạt lại.' : 'Đã ngừng sử dụng.');\\n      await loadData(true);\\n    } catch (toggleError) {\\n      ctx.message.error(String(toggleError?.message || 'Không thể thay đổi trạng thái.'));\\n    } finally {\\n      setSaving(false);\\n    }\\n  };\\n\\n  const softDelete = async (resource, record) => {\\n    if (resource === 'loai_danh_muc') {\\n      if (record.la_danh_muc_he_thong) {\\n        ctx.message.error('Danh mục hệ thống không được xóa.');\\n        return;\\n      }\\n      if (values.some((item) => item.loai_danh_muc_id === record.id && !item.is_deleted)) {\\n        ctx.message.error('Loại danh mục còn giá trị. Hãy ngừng sử dụng thay vì xóa.');\\n        return;\\n      }\\n    } else {\\n      if (values.some((item) => item.gia_tri_cha_id === record.id && !item.is_deleted)) {\\n        ctx.message.error('Giá trị đang có phần tử con nên không thể xóa.');\\n        return;\\n      }\\n      if (Number(record.so_luong_su_dung || 0) > 0) {\\n        ctx.message.error('Giá trị đang được sử dụng. Hãy ngừng sử dụng thay vì xóa.');\\n        return;\\n      }\\n    }\\n    setSaving(true);\\n    try {\\n      await api(`/${resource}:update?filterByTk=${record.id}`, { method: 'post', data: { is_deleted: true, trang_thai: 'inactive' } });\\n      ctx.message.success('Đã xóa mềm; dữ liệu có thể phục hồi.');\\n      await loadData(false);\\n    } catch (deleteError) {\\n      ctx.message.error(String(deleteError?.message || 'Không thể xóa bản ghi.'));\\n    } finally {\\n      setSaving(false);\\n    }\\n  };\\n\\n  const loadTranslations = async (target) => {\\n    setTranslationTarget(target);\\n    translationForm.resetFields();\\n    try {\\n      const filter = target.kind === 'type'\\n        ? { loai_danh_muc_id: { $eq: target.record.id }, is_deleted: { $isFalsy: true } }\\n        : { gia_tri_danh_muc_id: { $eq: target.record.id }, is_deleted: { $isFalsy: true } };\\n      const response = await api('/ban_dich_danh_muc:list', { params: { pageSize: 100, filter } });\\n      setTranslations(response?.data || []);\\n    } catch (translationError) {\\n      ctx.message.error('Không thể tải bản dịch.');\\n      setTranslations([]);\\n    }\\n  };\\n\\n  const saveTranslation = async () => {\\n    const formValues = await translationForm.validateFields();\\n    const target = translationTarget;\\n    const targetKey = target.kind === 'type' ? `type:${target.record.id}` : `value:${target.record.id}`;\\n    const key = `${targetKey}:${formValues.ma_ngon_ngu}`;\\n    const duplicate = translations.some((item) => item.ma_ngon_ngu === formValues.ma_ngon_ngu);\\n    if (duplicate) {\\n      translationForm.setFields([{ name: 'ma_ngon_ngu', errors: ['Ngôn ngữ này đã có bản dịch.'] }]);\\n      return;\\n    }\\n    setSaving(true);\\n    try {\\n      await api('/ban_dich_danh_muc:create', {\\n        method: 'post',\\n        data: {\\n          ...formValues,\\n          khoa_ban_dich: key,\\n          loai_danh_muc_id: target.kind === 'type' ? target.record.id : null,\\n          gia_tri_danh_muc_id: target.kind === 'value' ? target.record.id : null,\\n          is_deleted: false,\\n        },\\n      });\\n      ctx.message.success('Đã thêm bản dịch.');\\n      await loadTranslations(target);\\n    } catch (translationError) {\\n      ctx.message.error(String(translationError?.message || 'Không thể lưu bản dịch.'));\\n    } finally {\\n      setSaving(false);\\n    }\\n  };\\n\\n  const typeColumns = [\\n    { title: 'Mã loại', dataIndex: 'ma_loai', width: 135 },\\n    { title: 'Tên loại', dataIndex: 'ten_loai', ellipsis: true },\\n    { title: 'Số giá trị', dataIndex: 'so_gia_tri_hoat_dong', width: 90, align: 'center' },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', width: 120,\\n      render: (status) => <Tag color={status === 'active' ? 'green' : 'default'}>{status === 'active' ? 'Đang sử dụng' : 'Ngừng sử dụng'}</Tag>,\\n    },\\n    {\\n      title: 'Hệ thống', dataIndex: 'la_danh_muc_he_thong', width: 85, align: 'center',\\n      render: (value) => value ? <Badge status=\\"processing\\" text=\\"Có\\" /> : '-',\\n    },\\n  ];\\n\\n  const valueColumns = [\\n    { title: 'STT', width: 65, fixed: 'left', render: (_, __, index) => index + 1 },\\n    { title: 'Mã giá trị', dataIndex: 'ma_gia_tri', width: 145 },\\n    { title: 'Tên giá trị', dataIndex: 'ten_gia_tri', width: 210 },\\n    { title: 'Viết tắt', dataIndex: 'ten_viet_tat', width: 90 },\\n    { title: 'Giá trị cha', dataIndex: ['gia_tri_cha', 'ten_gia_tri'], width: 160, render: (value) => value || '-' },\\n    { title: 'Thứ tự', dataIndex: 'thu_tu', width: 80, align: 'center' },\\n    {\\n      title: 'Hiệu lực', width: 190,\\n      render: (_, record) => {\\n        const from = record.hieu_luc_tu ? dayjs(record.hieu_luc_tu).format('DD/MM/YYYY') : 'Không giới hạn';\\n        const to = record.hieu_luc_den ? dayjs(record.hieu_luc_den).format('DD/MM/YYYY') : 'Không giới hạn';\\n        return `${from} – ${to}`;\\n      },\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', width: 125,\\n      render: (status) => <Tag color={status === 'active' ? 'green' : 'default'}>{status === 'active' ? 'Đang sử dụng' : 'Ngừng sử dụng'}</Tag>,\\n    },\\n    { title: 'Nơi sử dụng', dataIndex: 'so_luong_su_dung', width: 110, align: 'center', render: (value) => Number(value || 0) },\\n    {\\n      title: 'Hành động', key: 'actions', fixed: 'right', width: canManage ? 330 : 90,\\n      render: (_, record) => (\\n        <Space wrap>\\n          <Button icon={<EyeOutlined />} onClick={() => setDetailRecord(record)}>Xem</Button>\\n          {canManage && <Button icon={<EditOutlined />} onClick={() => openValueModal(record)}>Sửa</Button>}\\n          {canManage && <Button icon={<GlobalOutlined />} onClick={() => loadTranslations({ kind: 'value', record })}>Bản dịch</Button>}\\n          {canManage && (\\n            <Popconfirm title={record.trang_thai === 'active' ? 'Ngừng sử dụng giá trị này?' : 'Kích hoạt lại giá trị này?'} onConfirm={() => toggleStatus('gia_tri_danh_muc', record)}>\\n              <Button icon={record.trang_thai === 'active' ? <StopOutlined /> : <CheckCircleOutlined />}>{record.trang_thai === 'active' ? 'Ngừng' : 'Kích hoạt'}</Button>\\n            </Popconfirm>\\n          )}\\n        </Space>\\n      ),\\n    },\\n  ];\\n\\n  if (loading) {\\n    return <div style={{ padding: 48, textAlign: 'center' }}><Spin tip=\\"Đang tải danh mục...\\" /></div>;\\n  }\\n\\n  if (error) {\\n    return <Alert type=\\"error\\" showIcon message=\\"Không thể tải dữ liệu\\" description={error} action={<Button onClick={() => loadData(true)}>Thử lại</Button>} />;\\n  }\\n\\n  return (\\n    <Space direction=\\"vertical\\" size={16} style={{ width: '100%' }}>\\n      <Card size=\\"small\\">\\n        <Row justify=\\"space-between\\" align=\\"middle\\" gutter={[12, 12]}>\\n          <Col>\\n            <Typography.Title level={4} style={{ margin: 0 }}>Danh mục dùng chung</Typography.Title>\\n            <Typography.Text type=\\"secondary\\">Quản trị tập trung loại danh mục và các giá trị được dùng lại trong toàn hệ thống.</Typography.Text>\\n          </Col>\\n          <Col><Button icon={<ReloadOutlined />} onClick={() => loadData(true)}>Làm mới</Button></Col>\\n        </Row>\\n      </Card>\\n\\n      <Space direction=\\"vertical\\" size={16} style={{ width: '100%' }}>\\n        <div>\\n          <Card title=\\"Loại danh mục\\" extra={canManage && <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={() => openTypeModal()}>Thêm loại</Button>}>\\n            <Space direction=\\"vertical\\" style={{ width: '100%' }}>\\n              <Input.Search allowClear placeholder=\\"Tìm theo mã hoặc tên\\" value={typeSearch} onChange={(event) => setTypeSearch(event.target.value)} />\\n              <Select style={{ width: '100%' }} value={typeStatus} onChange={setTypeStatus} options={[{ value: 'all', label: 'Tất cả trạng thái' }, ...statusOptions]} />\\n              <List\\n                dataSource={filteredTypes}\\n                locale={{ emptyText: <Empty description=\\"Không có loại danh mục\\" /> }}\\n                renderItem={(item) => (\\n                  <List.Item\\n                    style={{ cursor: 'pointer', background: item.id === selectedTypeId ? '#e6f4ff' : undefined, padding: 12, borderRadius: 8 }}\\n                    onClick={() => setSelectedTypeId(item.id)}\\n                    actions={canManage ? [\\n                      <Tooltip title=\\"Sửa\\"><Button size=\\"small\\" icon={<EditOutlined />} onClick={(event) => { event.stopPropagation(); openTypeModal(item); }} /></Tooltip>,\\n                      <Tooltip title=\\"Bản dịch\\"><Button size=\\"small\\" icon={<GlobalOutlined />} onClick={(event) => { event.stopPropagation(); loadTranslations({ kind: 'type', record: item }); }} /></Tooltip>,\\n                      <Popconfirm title={item.trang_thai === 'active' ? 'Ngừng sử dụng loại này?' : 'Kích hoạt lại loại này?'} onConfirm={() => toggleStatus('loai_danh_muc', item)}><Button size=\\"small\\" icon={item.trang_thai === 'active' ? <StopOutlined /> : <CheckCircleOutlined />} /></Popconfirm>,\\n                    ] : []}\\n                  >\\n                    <List.Item.Meta\\n                      title={<Space><Typography.Text strong>{item.ten_loai}</Typography.Text>{item.la_danh_muc_he_thong && <Tag color=\\"blue\\">Hệ thống</Tag>}</Space>}\\n                      description={<Space wrap><Typography.Text code>{item.ma_loai}</Typography.Text><Tag color={item.trang_thai === 'active' ? 'green' : 'default'}>{item.trang_thai === 'active' ? 'Đang sử dụng' : 'Ngừng sử dụng'}</Tag><span>{item.so_gia_tri_hoat_dong} giá trị</span></Space>}\\n                    />\\n                  </List.Item>\\n                )}\\n              />\\n            </Space>\\n          </Card>\\n        </div>\\n\\n        <div>\\n          {!selectedType ? (\\n            <Card><Empty description=\\"Chọn một loại danh mục để xem các giá trị.\\" /></Card>\\n          ) : (\\n            <Card\\n              title={<span>Giá trị thuộc: <strong>{selectedType.ten_loai}</strong></span>}\\n              extra={canManage && <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={() => openValueModal()}>Thêm giá trị</Button>}\\n            >\\n              <Typography.Paragraph type=\\"secondary\\">{selectedType.mo_ta || 'Chưa có mô tả.'}</Typography.Paragraph>\\n              <Row gutter={[8, 8]} style={{ marginBottom: 12 }}>\\n                <Col xs={24} md={10}><Input.Search allowClear placeholder=\\"Mã, tên hoặc tên viết tắt\\" value={valueSearch} onChange={(event) => setValueSearch(event.target.value)} /></Col>\\n                <Col xs={24} md={7}><Select style={{ width: '100%' }} value={valueStatus} onChange={setValueStatus} options={[{ value: 'all', label: 'Tất cả trạng thái' }, ...statusOptions]} /></Col>\\n                {selectedType.cho_phep_phan_cap && <Col xs={24} md={7}><Select allowClear style={{ width: '100%' }} value={parentFilter} onChange={(value) => setParentFilter(value || 'all')} options={[{ value: 'all', label: 'Tất cả giá trị cha' }, ...typeValues.map((item) => ({ value: String(item.id), label: item.ten_gia_tri }))]} /></Col>}\\n              </Row>\\n              <Space style={{ marginBottom: 12 }}>\\n                <Button type=\\"primary\\">Áp dụng</Button>\\n                <Button onClick={() => { setValueSearch(''); setValueStatus('all'); setParentFilter('all'); }}>Đặt lại</Button>\\n                <Button icon={<ReloadOutlined />} onClick={() => loadData(true)}>Làm mới</Button>\\n              </Space>\\n              <Table\\n                rowKey=\\"id\\"\\n                size=\\"small\\"\\n                columns={valueColumns}\\n                dataSource={filteredValues}\\n                pagination={{ pageSize: 10, showSizeChanger: true }}\\n                scroll={{ x: 1500 }}\\n                locale={{ emptyText: <Empty description=\\"Danh mục chưa có giá trị\\"><Button type=\\"primary\\" onClick={() => openValueModal()}>Tạo giá trị đầu tiên</Button></Empty> }}\\n              />\\n            </Card>\\n          )}\\n        </div>\\n      </Space>\\n\\n      <Modal title={typeModal?.id ? 'Chỉnh sửa loại danh mục' : 'Khai báo loại danh mục'} open={Boolean(typeModal)} onCancel={() => setTypeModal(null)} width={760} footer={null} destroyOnClose>\\n        <Form form={typeForm} layout=\\"vertical\\">\\n          <Row gutter={16}>\\n            <Col span={12}><Form.Item name=\\"ma_loai\\" label=\\"Mã loại danh mục\\" rules={[{ required: true, message: 'Vui lòng nhập mã loại danh mục.' }]}><Input disabled={Boolean(typeModal?.id)} maxLength={100} /></Form.Item></Col>\\n            <Col span={12}><Form.Item name=\\"ten_loai\\" label=\\"Tên loại danh mục\\" rules={[{ required: true, message: 'Vui lòng nhập tên loại danh mục.' }]}><Input maxLength={255} /></Form.Item></Col>\\n          </Row>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\"><Input.TextArea maxLength={2000} showCount rows={3} /></Form.Item>\\n          <Row gutter={16}>\\n            <Col span={8}><Form.Item name=\\"cho_phep_phan_cap\\" label=\\"Cho phép phân cấp\\" valuePropName=\\"checked\\"><Switch /></Form.Item></Col>\\n            <Col span={8}><Form.Item name=\\"cho_phep_da_ngon_ngu\\" label=\\"Cho phép đa ngôn ngữ\\" valuePropName=\\"checked\\"><Switch /></Form.Item></Col>\\n            <Col span={8}><Form.Item name=\\"thu_tu\\" label=\\"Thứ tự hiển thị\\" rules={[{ required: true }]}><InputNumber min={0} style={{ width: '100%' }} /></Form.Item></Col>\\n          </Row>\\n          <Form.Item name=\\"trang_thai\\" label=\\"Trạng thái\\" rules={[{ required: true }]}><Select options={statusOptions} /></Form.Item>\\n          <Divider />\\n          <Space>\\n            <Button type=\\"primary\\" loading={saving} onClick={() => saveType(false)}>Lưu</Button>\\n            {!typeModal?.id && <Button loading={saving} onClick={() => saveType(true)}>Lưu và thêm giá trị</Button>}\\n            {typeModal?.id && <Button icon={typeModal.trang_thai === 'active' ? <StopOutlined /> : <CheckCircleOutlined />} onClick={() => toggleStatus('loai_danh_muc', typeModal)}>{typeModal.trang_thai === 'active' ? 'Ngừng sử dụng' : 'Kích hoạt lại'}</Button>}\\n            {typeModal?.id && !typeModal.la_danh_muc_he_thong && <Popconfirm title=\\"Chỉ xóa mềm khi loại không còn giá trị. Tiếp tục?\\" onConfirm={() => softDelete('loai_danh_muc', typeModal)}><Button danger>Xóa mềm</Button></Popconfirm>}\\n            <Button onClick={() => setTypeModal(null)}>Hủy</Button>\\n          </Space>\\n        </Form>\\n      </Modal>\\n\\n      <Modal title={valueModal?.id ? 'Chỉnh sửa giá trị danh mục' : 'Khai báo giá trị danh mục'} open={Boolean(valueModal)} onCancel={() => setValueModal(null)} width={920} footer={null} destroyOnClose>\\n        <Form form={valueForm} layout=\\"vertical\\">\\n          <Row gutter={16}>\\n            <Col span={8}><Form.Item name=\\"loai_danh_muc_id\\" label=\\"Loại danh mục\\" rules={[{ required: true }]}><Select disabled={Boolean(valueModal?.id)} options={types.map((item) => ({ value: item.id, label: item.ten_loai }))} /></Form.Item></Col>\\n            <Col span={8}><Form.Item name=\\"ma_gia_tri\\" label=\\"Mã giá trị\\" rules={[{ required: true, message: 'Vui lòng nhập mã giá trị.' }]}><Input disabled={Boolean(valueModal?.id && Number(valueModal.so_luong_su_dung || 0) > 0)} /></Form.Item></Col>\\n            <Col span={8}><Form.Item name=\\"ten_gia_tri\\" label=\\"Tên giá trị\\" rules={[{ required: true, message: 'Vui lòng nhập tên giá trị.' }]}><Input /></Form.Item></Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={8}><Form.Item name=\\"ten_viet_tat\\" label=\\"Tên viết tắt\\"><Input maxLength={50} showCount /></Form.Item></Col>\\n            <Col span={8}><Form.Item name=\\"thu_tu\\" label=\\"Thứ tự hiển thị\\" rules={[{ required: true }]}><InputNumber min={0} style={{ width: '100%' }} /></Form.Item></Col>\\n            <Col span={8}><Form.Item name=\\"trang_thai\\" label=\\"Trạng thái\\" rules={[{ required: true }]}><Select options={statusOptions} /></Form.Item></Col>\\n          </Row>\\n          {types.find((item) => item.id === valueForm.getFieldValue('loai_danh_muc_id'))?.cho_phep_phan_cap && (\\n            <Form.Item name=\\"gia_tri_cha_id\\" label=\\"Giá trị cha\\"><Select allowClear options={values.filter((item) => item.loai_danh_muc_id === valueForm.getFieldValue('loai_danh_muc_id') && item.id !== valueModal?.id && item.trang_thai === 'active').map((item) => ({ value: item.id, label: item.ten_gia_tri }))} /></Form.Item>\\n          )}\\n          <Row gutter={16}>\\n            <Col span={12}><Form.Item name=\\"hieu_luc_tu\\" label=\\"Hiệu lực từ\\"><DatePicker style={{ width: '100%' }} showTime /></Form.Item></Col>\\n            <Col span={12}><Form.Item name=\\"hieu_luc_den\\" label=\\"Hiệu lực đến\\"><DatePicker style={{ width: '100%' }} showTime /></Form.Item></Col>\\n          </Row>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\"><Input.TextArea maxLength={2000} showCount rows={3} /></Form.Item>\\n          <Divider />\\n          <Space>\\n            <Button type=\\"primary\\" loading={saving} onClick={() => saveValue(false)}>Lưu</Button>\\n            {!valueModal?.id && <Button loading={saving} onClick={() => saveValue(true)}>Lưu và thêm tiếp</Button>}\\n            {valueModal?.id && <Button onClick={() => toggleStatus('gia_tri_danh_muc', valueModal)}>{valueModal.trang_thai === 'active' ? 'Ngừng sử dụng' : 'Kích hoạt lại'}</Button>}\\n            {valueModal?.id && <Button icon={<GlobalOutlined />} onClick={() => loadTranslations({ kind: 'value', record: valueModal })}>Xem bản dịch</Button>}\\n            {valueModal?.id && <Popconfirm title=\\"Chỉ xóa mềm khi chưa được dùng và không có giá trị con. Tiếp tục?\\" onConfirm={() => softDelete('gia_tri_danh_muc', valueModal)}><Button danger>Xóa mềm</Button></Popconfirm>}\\n            <Button onClick={() => setValueModal(null)}>Hủy</Button>\\n          </Space>\\n        </Form>\\n      </Modal>\\n\\n      <Modal title=\\"Chi tiết và lịch sử sử dụng\\" open={Boolean(detailRecord)} onCancel={() => setDetailRecord(null)} width={860} footer={<Button onClick={() => setDetailRecord(null)}>Đóng</Button>}>\\n        {detailRecord && <Tabs items={[\\n          { key: 'detail', label: 'Thông tin', children: <Descriptions bordered column={2} size=\\"small\\" items={[\\n            { key: 'type', label: 'Loại danh mục', children: detailRecord.loai_danh_muc?.ten_loai || selectedType?.ten_loai },\\n            { key: 'code', label: 'Mã', children: detailRecord.ma_gia_tri },\\n            { key: 'name', label: 'Tên', children: detailRecord.ten_gia_tri },\\n            { key: 'short', label: 'Tên viết tắt', children: detailRecord.ten_viet_tat || '-' },\\n            { key: 'parent', label: 'Giá trị cha', children: detailRecord.gia_tri_cha?.ten_gia_tri || '-' },\\n            { key: 'status', label: 'Trạng thái', children: detailRecord.trang_thai === 'active' ? 'Đang sử dụng' : 'Ngừng sử dụng' },\\n            { key: 'effective', label: 'Hiệu lực', children: `${detailRecord.hieu_luc_tu ? dayjs(detailRecord.hieu_luc_tu).format('DD/MM/YYYY HH:mm') : 'Không giới hạn'} – ${detailRecord.hieu_luc_den ? dayjs(detailRecord.hieu_luc_den).format('DD/MM/YYYY HH:mm') : 'Không giới hạn'}` },\\n            { key: 'description', label: 'Mô tả', span: 2, children: detailRecord.mo_ta || '-' },\\n            { key: 'created', label: 'Ngày tạo', children: detailRecord.createdAt ? dayjs(detailRecord.createdAt).format('DD/MM/YYYY HH:mm') : '-' },\\n            { key: 'updated', label: 'Cập nhật cuối', children: detailRecord.updatedAt ? dayjs(detailRecord.updatedAt).format('DD/MM/YYYY HH:mm') : '-' },\\n          ]} /> },\\n          { key: 'usage', label: `Nơi sử dụng (${Number(detailRecord.so_luong_su_dung || 0)})`, children: Array.isArray(detailRecord.noi_su_dung) && detailRecord.noi_su_dung.length ? <List dataSource={detailRecord.noi_su_dung} renderItem={(item) => <List.Item>{typeof item === 'string' ? item : JSON.stringify(item)}</List.Item>} /> : <Empty description=\\"Chưa ghi nhận dữ liệu tham chiếu\\" /> },\\n          { key: 'children', label: 'Giá trị con', children: <List dataSource={values.filter((item) => item.gia_tri_cha_id === detailRecord.id)} locale={{ emptyText: 'Không có giá trị con' }} renderItem={(item) => <List.Item>{item.ten_gia_tri}</List.Item>} /> },\\n        ]} />}\\n      </Modal>\\n\\n      <Modal title=\\"Quản lý bản dịch\\" open={Boolean(translationTarget)} onCancel={() => setTranslationTarget(null)} width={760} footer={<Button onClick={() => setTranslationTarget(null)}>Đóng</Button>}>\\n        {translationTarget && <>\\n          <Alert type=\\"info\\" showIcon message={`Đối tượng: ${translationTarget.record.ten_loai || translationTarget.record.ten_gia_tri}`} style={{ marginBottom: 16 }} />\\n          <Form form={translationForm} layout=\\"vertical\\">\\n            <Row gutter={16}>\\n              <Col span={8}><Form.Item name=\\"ma_ngon_ngu\\" label=\\"Ngôn ngữ\\" rules={[{ required: true }]}><Select options={languageOptions} /></Form.Item></Col>\\n              <Col span={16}><Form.Item name=\\"ten_dich\\" label=\\"Tên dịch\\" rules={[{ required: true }]}><Input /></Form.Item></Col>\\n            </Row>\\n            <Form.Item name=\\"ten_viet_tat_dich\\" label=\\"Tên viết tắt dịch\\"><Input maxLength={50} /></Form.Item>\\n            <Form.Item name=\\"mo_ta_dich\\" label=\\"Mô tả dịch\\"><Input.TextArea maxLength={2000} showCount rows={3} /></Form.Item>\\n            <Button type=\\"primary\\" loading={saving} onClick={saveTranslation}>Thêm bản dịch</Button>\\n          </Form>\\n          <Divider />\\n          <Table rowKey=\\"id\\" size=\\"small\\" pagination={false} dataSource={translations} columns={[\\n            { title: 'Ngôn ngữ', dataIndex: 'ma_ngon_ngu', render: (value) => languageOptions.find((item) => item.value === value)?.label || value },\\n            { title: 'Tên dịch', dataIndex: 'ten_dich' },\\n            { title: 'Tên viết tắt', dataIndex: 'ten_viet_tat_dich' },\\n          ]} />\\n        </>}\\n      </Modal>\\n    </Space>\\n  );\\n};\\n\\nctx.render(<CatalogManager />);\\n"}},"__flowSurfaceMeta":{"declaredKey":"otherCatalogV2.catalogManagerV2"}}}
