bzerp4mwfr8	bzerp4mwfr8	{"parentId":"he0k6fvajwn","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"12","code":"const { useState, useEffect, useCallback, useMemo } = ctx.libs.React;\\nconst { Table, Button, Input, Select, Space, Tag, Modal, Form, Tooltip, Popconfirm, Typography, Card, Row, Col, Divider, Descriptions, Radio, Badge } = ctx.libs.antd;\\nconst { SearchOutlined, PlusOutlined, DeleteOutlined, EyeOutlined, ReloadOutlined, EditOutlined, SendOutlined, QuestionCircleOutlined, CheckCircleOutlined } = ctx.libs.antdIcons;\\n\\nctx.initResource('MultiRecordResource');\\nconst resource = ctx.resource;\\nresource.setResourceName('cau_hoi');\\nresource.setAppends(['nganh_nghe', 'bac_tho']);\\nresource.setSort(['-createdAt']);\\nresource.setPageSize(15);\\n\\nconst nganhNgheRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nnganhNgheRes?.setResourceName('nganh_nghe');\\nnganhNgheRes?.setPageSize(200);\\n\\nconst bacThoRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nbacThoRes?.setResourceName('bac_tho');\\nbacThoRes?.setPageSize(200);\\n\\nconst statusMap = {\\n  nhap: { color: 'default', label: 'Bản nháp' },\\n  cho_phe_duyet: { color: 'gold', label: 'Chờ phê duyệt' },\\n  da_phe_duyet: { color: 'green', label: 'Đã phê duyệt' },\\n  tu_choi: { color: 'red', label: 'Từ chối' },\\n  ngung_su_dung: { color: 'volcano', label: 'Ngừng sử dụng' }\\n};\\nconst hinhThucMap = { trac_nghiem: { color: 'blue', label: 'Trắc nghiệm' }, tu_luan: { color: 'purple', label: 'Tự luận' } };\\nconst mucDoMap = { de: { color: 'green', label: 'Dễ' }, trung_binh: { color: 'gold', label: 'Trung bình' }, kho: { color: 'red', label: 'Khó' } };\\nconst nguonMap = { thu_cong: 'Thủ công', ai: 'AI gợi ý' };\\n\\nfunction App() {\\n  const [loading, setLoading] = useState(true);\\n  const [data, setData] = useState([]);\\n  const [meta, setMeta] = useState({});\\n  const [search, setSearch] = useState('');\\n  const [filterStatus, setFilterStatus] = useState(null);\\n  const [filterHinhThuc, setFilterHinhThuc] = useState(null);\\n  const [filterMucDo, setFilterMucDo] = useState(null);\\n  const [modalOpen, setModalOpen] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [detailOpen, setDetailOpen] = useState(false);\\n  const [detailRecord, setDetailRecord] = useState(null);\\n  const [saving, setSaving] = useState(false);\\n  const [nganhNgheList, setNganhNgheList] = useState([]);\\n  const [bacThoList, setBacThoList] = useState([]);\\n  const [selectedHinhThuc, setSelectedHinhThuc] = useState('trac_nghiem');\\n  const [form] = Form.useForm();\\n\\n  const loadOptions = useCallback(async () => {\\n    try {\\n      if (nganhNgheRes) { await nganhNgheRes.refresh(); setNganhNgheList(nganhNgheRes.getData() || []); }\\n      if (bacThoRes) { await bacThoRes.refresh(); setBacThoList(bacThoRes.getData() || []); }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadData = useCallback(async (page) => {\\n    setLoading(true);\\n    try {\\n      const filter = { is_deleted: { $ne: true } };\\n      if (search) filter.$or = [\\n        { ten_cau_hoi: { $includes: search } },\\n        { noi_dung: { $includes: search } },\\n        { ma_cau_hoi: { $includes: search } }\\n      ];\\n      if (filterStatus) filter.trang_thai = { $eq: filterStatus };\\n      if (filterHinhThuc) filter.hinh_thuc = { $eq: filterHinhThuc };\\n      if (filterMucDo) filter.muc_do_kho = { $eq: filterMucDo };\\n      resource.setFilter(filter);\\n      if (page) resource.setPage(page);\\n      await resource.refresh();\\n      setData(resource.getData() || []);\\n      setMeta(resource.getMeta() || {});\\n    } catch (e) {\\n      ctx.message.error('Lỗi tải dữ liệu');\\n    }\\n    setLoading(false);\\n  }, [search, filterStatus, filterHinhThuc, filterMucDo]);\\n\\n  useEffect(() => { loadData(1); loadOptions(); }, []);\\n\\n  const handleSearch = useCallback(() => { loadData(1); }, [loadData]);\\n\\n  const openCreate = useCallback(() => {\\n    setEditRecord(null);\\n    form.resetFields();\\n    setSelectedHinhThuc('trac_nghiem');\\n    form.setFieldsValue({ hinh_thuc: 'trac_nghiem', nguon_tao: 'thu_cong', muc_do_kho: 'trung_binh' });\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const openEdit = useCallback((record) => {\\n    setEditRecord(record);\\n    setSelectedHinhThuc(record.hinh_thuc || 'trac_nghiem');\\n    form.setFieldsValue({\\n      ten_cau_hoi: record.ten_cau_hoi,\\n      noi_dung: record.noi_dung,\\n      chu_de: record.chu_de,\\n      hinh_thuc: record.hinh_thuc,\\n      muc_do_kho: record.muc_do_kho,\\n      nguon_tao: record.nguon_tao,\\n      nganhNgheId: record.nganhNgheId || (record.nganh_nghe && record.nganh_nghe.id),\\n      bacThoId: record.bacThoId || (record.bac_tho && record.bac_tho.id),\\n      dap_an: record.dap_an,\\n      dap_an_dung: record.dap_an_dung,\\n      giai_thich: record.giai_thich\\n    });\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const handleSave = useCallback(async () => {\\n    try {\\n      const values = await form.validateFields();\\n      setSaving(true);\\n      const payload = {\\n        ten_cau_hoi: values.ten_cau_hoi,\\n        noi_dung: values.noi_dung,\\n        chu_de: values.chu_de,\\n        hinh_thuc: values.hinh_thuc,\\n        muc_do_kho: values.muc_do_kho,\\n        nguon_tao: values.nguon_tao || 'thu_cong',\\n        nganhNgheId: values.nganhNgheId || null,\\n        bacThoId: values.bacThoId || null,\\n        dap_an: values.dap_an,\\n        dap_an_dung: values.dap_an_dung,\\n        giai_thich: values.giai_thich\\n      };\\n      if (editRecord) {\\n        payload.trang_thai = 'nhap';\\n        await resource.update(editRecord.id, payload);\\n        ctx.message.success('Cập nhật câu hỏi thành công, trạng thái đã chuyển về Bản nháp');\\n      } else {\\n        await resource.create({ ...payload, trang_thai: 'nhap', is_deleted: false });\\n        ctx.message.success('Tạo câu hỏi thành công');\\n      }\\n      setModalOpen(false);\\n      form.resetFields();\\n      loadData();\\n    } catch (e) {\\n      if (e.errorFields) { setSaving(false); return; }\\n      ctx.message.error('Lỗi lưu câu hỏi');\\n    }\\n    setSaving(false);\\n  }, [form, editRecord, loadData]);\\n\\n  const handleDelete = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { is_deleted: true });\\n      ctx.message.success('Đã xoá câu hỏi');\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi xoá'); }\\n  }, [loadData]);\\n\\n  const handleSendApproval = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'cho_phe_duyet' });\\n      ctx.message.success('Đã gửi duyệt câu hỏi');\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi gửi duyệt'); }\\n  }, [loadData]);\\n\\n  const handleApprove = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'da_phe_duyet' });\\n      ctx.message.success('Đã phê duyệt câu hỏi');\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi phê duyệt'); }\\n  }, [loadData]);\\n\\n  const columns = useMemo(() => [\\n    { title: 'Mã CH', dataIndex: 'ma_cau_hoi', width: 110, ellipsis: true, render: (v) => v || '-' },\\n    {\\n      title: 'Tên câu hỏi', dataIndex: 'ten_cau_hoi', ellipsis: true,\\n      render: (text, record) => (\\n        <Typography.Link onClick={() => { setDetailRecord(record); setDetailOpen(true); }}>\\n          {text || record.noi_dung?.substring(0, 50) || '-'}\\n        </Typography.Link>\\n      )\\n    },\\n    {\\n      title: 'Hình thức', dataIndex: 'hinh_thuc', width: 120,\\n      render: (v) => { const h = hinhThucMap[v]; return h ? <Tag color={h.color}>{h.label}</Tag> : (v || '-'); }\\n    },\\n    {\\n      title: 'Mức độ', dataIndex: 'muc_do_kho', width: 110,\\n      render: (v) => { const m = mucDoMap[v]; return m ? <Tag color={m.color}>{m.label}</Tag> : (v || '-'); }\\n    },\\n    {\\n      title: 'Ngành nghề', dataIndex: 'nganh_nghe', width: 140, ellipsis: true,\\n      render: (v) => v?.ten_nganh || '-'\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', width: 130,\\n      render: (v) => { const s = statusMap[v] || { color: 'default', label: v || '-' }; return <Tag color={s.color}>{s.label}</Tag>; }\\n    },\\n    {\\n      title: 'Thao tác', width: 200, fixed: 'right',\\n      render: (_, record) => (\\n        <Space size={4}>\\n          <Tooltip title=\\"Xem\\"><Button icon={<EyeOutlined />} onClick={() => { setDetailRecord(record); setDetailOpen(true); }} /></Tooltip>\\n          <Tooltip title=\\"Sửa\\"><Button icon={<EditOutlined />} onClick={() => openEdit(record)} /></Tooltip>\\n          {(!record.trang_thai || record.trang_thai === 'nhap' || record.trang_thai === 'tu_choi') && (\\n            <Tooltip title=\\"Gửi duyệt\\"><Button icon={<SendOutlined />} onClick={() => handleSendApproval(record)} /></Tooltip>\\n          )}\\n          {record.trang_thai === 'cho_phe_duyet' && (\\n            <Popconfirm title=\\"Phê duyệt câu hỏi này?\\" onConfirm={() => handleApprove(record)} okText=\\"Phê duyệt\\" cancelText=\\"Huỷ\\">\\n              <Tooltip title=\\"Phê duyệt\\"><Button style={{ color: '#52c41a', borderColor: '#52c41a' }} icon={<CheckCircleOutlined />} /></Tooltip>\\n            </Popconfirm>\\n          )}\\n          <Popconfirm title=\\"Xoá câu hỏi này?\\" onConfirm={() => handleDelete(record)} okText=\\"Xoá\\" cancelText=\\"Huỷ\\">\\n            <Tooltip title=\\"Xoá\\"><Button danger icon={<DeleteOutlined />} /></Tooltip>\\n          </Popconfirm>\\n        </Space>\\n      )\\n    }\\n  ], [openEdit, handleDelete, handleSendApproval, handleApprove]);\\n\\n  return (\\n    <div style={{ padding: '0 4px' }}>\\n      <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n        <Row gutter={[12, 12]} align=\\"middle\\">\\n          <Col flex=\\"auto\\">\\n            <Space wrap size={8}>\\n              <Input placeholder=\\"Tìm câu hỏi...\\" prefix={<SearchOutlined />} value={search} onChange={e => setSearch(e.target.value)} onPressEnter={handleSearch} style={{ width: 200 }} allowClear />\\n              <Select placeholder=\\"Hình thức\\" value={filterHinhThuc} onChange={setFilterHinhThuc} allowClear style={{ width: 140 }} options={Object.entries(hinhThucMap).map(([k, v]) => ({ label: v.label, value: k }))} />\\n              <Select placeholder=\\"Mức độ\\" value={filterMucDo} onChange={setFilterMucDo} allowClear style={{ width: 130 }} options={Object.entries(mucDoMap).map(([k, v]) => ({ label: v.label, value: k }))} />\\n              <Select placeholder=\\"Trạng thái\\" value={filterStatus} onChange={setFilterStatus} allowClear style={{ width: 150 }} options={Object.entries(statusMap).map(([k, v]) => ({ label: v.label, value: k }))} />\\n              <Button icon={<SearchOutlined />} type=\\"primary\\" onClick={handleSearch}>Tìm</Button>\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Tooltip title=\\"Tải lại\\"><Button icon={<ReloadOutlined />} onClick={() => loadData()} /></Tooltip>\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={openCreate}>Tạo câu hỏi</Button>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Table rowKey=\\"id\\" columns={columns} dataSource={data} loading={loading} size=\\"middle\\" scroll={{ x: 1000 }}\\n        pagination={{\\n          current: meta.page || 1, pageSize: meta.pageSize || 15, total: meta.count || 0,\\n          showTotal: (total) => `Tổng ${total} câu hỏi`, showSizeChanger: true,\\n          onChange: (page, pageSize) => { resource.setPageSize(pageSize); loadData(page); }\\n        }}\\n      />\\n\\n      <Modal title={editRecord ? 'Sửa câu hỏi' : 'Tạo câu hỏi mới'} open={modalOpen} onCancel={() => setModalOpen(false)} onOk={handleSave} confirmLoading={saving} okText={editRecord ? 'Cập nhật' : 'Tạo'} cancelText=\\"Huỷ\\" width={800} destroyOnClose>\\n        <Form form={form} layout=\\"vertical\\" style={{ marginTop: 16 }}>\\n          <Row gutter={16}>\\n            <Col span={16}>\\n              <Form.Item name=\\"ten_cau_hoi\\" label=\\"Tên câu hỏi\\" rules={[{ required: true, message: 'Nhập tên câu hỏi' }]}>\\n                <Input placeholder=\\"Tên ngắn gọn cho câu hỏi\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"chu_de\\" label=\\"Chủ đề\\">\\n                <Input placeholder=\\"Chủ đề\\" />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={8}>\\n              <Form.Item name=\\"hinh_thuc\\" label=\\"Hình thức\\" rules={[{ required: true, message: 'Chọn hình thức' }]}>\\n                <Select options={Object.entries(hinhThucMap).map(([k, v]) => ({ label: v.label, value: k }))} onChange={v => setSelectedHinhThuc(v)} />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"muc_do_kho\\" label=\\"Mức độ khó\\" rules={[{ required: true, message: 'Chọn mức độ' }]}>\\n                <Select options={Object.entries(mucDoMap).map(([k, v]) => ({ label: v.label, value: k }))} />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"nguon_tao\\" label=\\"Nguồn tạo\\">\\n                <Select options={[{ label: 'Thủ công', value: 'thu_cong' }, { label: 'AI gợi ý', value: 'ai' }]} />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={12}>\\n              <Form.Item name=\\"nganhNgheId\\" label=\\"Ngành nghề\\">\\n                <Select placeholder=\\"Chọn ngành nghề\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={nganhNgheList.map(nn => ({ label: nn.ten_nganh || nn.ten_nganh_nghe, value: nn.id }))} />\\n              </Form.Item>\\n            </Col>\\n            <Col span={12}>\\n              <Form.Item name=\\"bacThoId\\" label=\\"Bậc thợ\\">\\n                <Select placeholder=\\"Chọn bậc thợ\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={bacThoList.map(bt => ({ label: bt.ten_bac || bt.ten_bac_tho, value: bt.id }))} />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Form.Item name=\\"noi_dung\\" label=\\"Nội dung câu hỏi\\" rules={[{ required: true, message: 'Nhập nội dung' }]}>\\n            <Input.TextArea rows={3} placeholder=\\"Nội dung chi tiết câu hỏi...\\" />\\n          </Form.Item>\\n          {selectedHinhThuc === 'trac_nghiem' ? (\\n            <>\\n              <Form.Item name=\\"dap_an\\" label=\\"Các phương án trả lời\\" extra=\\"Mỗi phương án trên 1 dòng (A. ..., B. ..., C. ..., D. ...)\\">\\n                <Input.TextArea rows={4} placeholder={\\"A. Phương án 1\\\\nB. Phương án 2\\\\nC. Phương án 3\\\\nD. Phương án 4\\"} />\\n              </Form.Item>\\n              <Form.Item name=\\"dap_an_dung\\" label=\\"Đáp án đúng\\" extra=\\"Ví dụ: A hoặc A,C (nhiều đáp án)\\">\\n                <Input placeholder=\\"A\\" />\\n              </Form.Item>\\n            </>\\n          ) : (\\n            <>\\n              <Form.Item name=\\"dap_an\\" label=\\"Đáp án mẫu / Gợi ý chấm\\">\\n                <Input.TextArea rows={4} placeholder=\\"Đáp án mẫu hoặc tiêu chí chấm điểm (rubric)...\\" />\\n              </Form.Item>\\n              <Form.Item name=\\"dap_an_dung\\" label=\\"Thang điểm / Rubric\\">\\n                <Input.TextArea rows={2} placeholder=\\"Tiêu chí + thang điểm\\" />\\n              </Form.Item>\\n            </>\\n          )}\\n          <Form.Item name=\\"giai_thich\\" label=\\"Giải thích đáp án\\">\\n            <Input.TextArea rows={2} placeholder=\\"Giải thích tại sao đáp án đúng...\\" />\\n          </Form.Item>\\n        </Form>\\n      </Modal>\\n\\n      <Modal title=\\"Chi tiết câu hỏi\\" open={detailOpen} onCancel={() => { setDetailOpen(false); setDetailRecord(null); }} footer={null} width={750} destroyOnClose>\\n        {detailRecord && (\\n          <div>\\n            <Descriptions bordered size=\\"small\\" column={2} style={{ marginBottom: 16 }}>\\n              <Descriptions.Item label=\\"Mã CH\\">{detailRecord.ma_cau_hoi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Trạng thái\\"><Tag color={(statusMap[detailRecord.trang_thai] || {}).color}>{(statusMap[detailRecord.trang_thai] || {}).label || '-'}</Tag></Descriptions.Item>\\n              <Descriptions.Item label=\\"Hình thức\\"><Tag color={(hinhThucMap[detailRecord.hinh_thuc] || {}).color}>{(hinhThucMap[detailRecord.hinh_thuc] || {}).label || '-'}</Tag></Descriptions.Item>\\n              <Descriptions.Item label=\\"Mức độ\\"><Tag color={(mucDoMap[detailRecord.muc_do_kho] || {}).color}>{(mucDoMap[detailRecord.muc_do_kho] || {}).label || '-'}</Tag></Descriptions.Item>\\n              <Descriptions.Item label=\\"Ngành nghề\\">{detailRecord.nganh_nghe?.ten_nganh || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Bậc thợ\\">{detailRecord.bac_tho?.ten_bac || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Chủ đề\\">{detailRecord.chu_de || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Nguồn\\">{nguonMap[detailRecord.nguon_tao] || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Tên câu hỏi\\" span={2}>{detailRecord.ten_cau_hoi || '-'}</Descriptions.Item>\\n            </Descriptions>\\n            <Divider style={{ margin: '8px 0' }} />\\n            <Typography.Title level={5}><QuestionCircleOutlined /> Nội dung</Typography.Title>\\n            <Card size=\\"small\\" style={{ marginBottom: 12, backgroundColor: '#fafafa' }}>\\n              <Typography.Paragraph style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailRecord.noi_dung || '-'}</Typography.Paragraph>\\n            </Card>\\n            {detailRecord.dap_an && (\\n              <>\\n                <Typography.Title level={5}>{detailRecord.hinh_thuc === 'trac_nghiem' ? 'Phương án trả lời' : 'Đáp án mẫu / Rubric'}</Typography.Title>\\n                <Card size=\\"small\\" style={{ marginBottom: 12 }}>\\n                  <Typography.Paragraph style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{\\n                    detailRecord.hinh_thuc === 'trac_nghiem' && detailRecord.dap_an.includes(';') && !detailRecord.dap_an.includes('\\\\n')\\n                      ? detailRecord.dap_an.split(';').map(s => s.trim()).filter(Boolean).join('\\\\n')\\n                      : detailRecord.dap_an\\n                  }</Typography.Paragraph>\\n                </Card>\\n              </>\\n            )}\\n            {detailRecord.dap_an_dung && (\\n              <>\\n                <Typography.Title level={5}>{detailRecord.hinh_thuc === 'trac_nghiem' ? 'Đáp án đúng' : 'Thang điểm'}</Typography.Title>\\n                <Card size=\\"small\\" style={{ marginBottom: 12, borderColor: '#52c41a' }}>\\n                  <Typography.Text strong style={{ color: '#52c41a' }}>{detailRecord.dap_an_dung}</Typography.Text>\\n                </Card>\\n              </>\\n            )}\\n            {detailRecord.giai_thich && (\\n              <>\\n                <Typography.Title level={5}>Giải thích</Typography.Title>\\n                <Card size=\\"small\\" style={{ backgroundColor: '#f6ffed' }}>\\n                  <Typography.Paragraph style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailRecord.giai_thich}</Typography.Paragraph>\\n                </Card>\\n              </>\\n            )}\\n          </div>\\n        )}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);"}},"__flowSurfaceMeta":{"declaredKey":"question.questionStats"}}}
