l9bni85umj6	l9bni85umj6	{"parentId":"cejw9sr82hj","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê lớp học trực tuyến"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Card, Col, Row, Statistic } = ctx.libs.antd;\\nconst { LaptopOutlined, ClockCircleOutlined, BookOutlined, CheckCircleOutlined } = ctx.libs.antdIcons;\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('lop_hoc');\\n  ctx.resource.setPageSize?.(1000);\\n  await ctx.resource.refresh();\\n  const allRows = (ctx.resource.getData?.() || []).filter((row) => row.is_deleted !== true);\\n  const rows = allRows.filter((row) => row.hinh_thuc === 'truc_tuyen');\\n  const metrics = [\\n    { title: ctx.t('Tổng số lớp'), value: rows.length, color: '#1677ff', icon: <LaptopOutlined /> },\\n    { title: ctx.t('Dự kiến'), value: rows.filter((row) => row.trang_thai === 'du_kien').length, color: '#d48806', icon: <ClockCircleOutlined /> },\\n    { title: ctx.t('Đang học'), value: rows.filter((row) => row.trang_thai === 'dang_hoc').length, color: '#1677ff', icon: <BookOutlined /> },\\n    { title: ctx.t('Hoàn thành'), value: rows.filter((row) => row.trang_thai === 'hoan_thanh').length, color: '#389e0d', icon: <CheckCircleOutlined /> },\\n  ];\\n  ctx.render(\\n    <Row gutter={[12, 12]}>\\n      {metrics.map((metric) => (\\n        <Col key={metric.title} xs={24} sm={12} xl={6}>\\n          <Card size=\\"small\\" bordered>\\n            <Statistic title={metric.title} value={metric.value} prefix={metric.icon} valueStyle={{ color: metric.color }} />\\n          </Card>\\n        </Col>\\n      ))}\\n    </Row>,\\n  );\\n} catch (error) {\\n  ctx.render(<Alert showIcon type=\\"error\\" message={ctx.t('Không tải được thống kê')} description={String(error?.message || error)} />);\\n}"}},"__flowSurfaceMeta":{"declaredKey":"tlTab.tlStats"}},"parent":"cejw9sr82hj","sortIndex":1,"flowRegistry":{}}
