f8s7a8a090i	f8s7a8a090i	{"parentId":"xm8nnfabqb1","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const React = ctx.libs.React;\\nconst { Alert, Card, Descriptions, Empty, Space, Tag, Typography } = ctx.libs.antd;\\nconst { CheckCircleOutlined, MailOutlined } = ctx.libs.antdIcons;\\n\\nconst resource = ctx.makeResource('MultiRecordResource');\\nresource.setResourceName('notificationChannels');\\nresource.setFilter({ notificationType: 'email' });\\nresource.setPageSize(20);\\n\\ntry {\\n  await resource.refresh();\\n  const channel = (resource.getData() || [])[0] || null;\\n  if (!channel) {\\n    ctx.render(\\n      <Card size=\\"small\\" title={<Space><MailOutlined />{ctx.t('Trạng thái Email SMTP')}</Space>} style={{ marginBottom: 16 }}>\\n        <Empty description={ctx.t('Chưa có cấu hình SMTP. Điền biểu mẫu bên dưới để bắt đầu.')} />\\n      </Card>,\\n    );\\n  } else {\\n    const options = channel.options || {};\\n    ctx.render(\\n      <Card size=\\"small\\" title={<Space><MailOutlined />{ctx.t('Trạng thái Email SMTP')}</Space>} style={{ marginBottom: 16 }}>\\n        <Alert\\n          showIcon\\n          type=\\"success\\"\\n          icon={<CheckCircleOutlined />}\\n          message={ctx.t('Kênh email đã sẵn sàng để cấu hình và gửi thử')}\\n          style={{ marginBottom: 12 }}\\n        />\\n        <Descriptions size=\\"small\\" column={{ xs: 1, sm: 2, lg: 4 }}>\\n          <Descriptions.Item label={ctx.t('Kênh')}><Tag color=\\"blue\\">{channel.name}</Tag></Descriptions.Item>\\n          <Descriptions.Item label={ctx.t('Tài khoản')}>{options.account || '—'}</Descriptions.Item>\\n          <Descriptions.Item label={ctx.t('Máy chủ')}>{options.host || '—'}:{options.port || '—'}</Descriptions.Item>\\n          <Descriptions.Item label={ctx.t('Bảo mật')}>{options.secure ? 'SSL/TLS' : 'STARTTLS / thường'}</Descriptions.Item>\\n        </Descriptions>\\n        <Typography.Text type=\\"secondary\\">\\n          {ctx.t('Các quy trình gửi email cần chọn đúng kênh này để dùng tài khoản SMTP đã lưu.')}\\n        </Typography.Text>\\n      </Card>,\\n    );\\n  }\\n} catch (error) {\\n  ctx.render(<Alert showIcon type=\\"error\\" message={ctx.t('Không thể đọc trạng thái SMTP')} description={String(error?.message || error)} />);\\n}\\n"}},"__flowSurfaceMeta":{"declaredKey":"main.statusBlock"}}}
