i3v8cc2udl5	i3v8cc2udl5	{"parentId":"xm8nnfabqb1","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const React = ctx.libs.React;\\nconst { useState } = React;\\nconst {\\n  Alert,\\n  Button,\\n  Card,\\n  Col,\\n  Form,\\n  Input,\\n  InputNumber,\\n  Row,\\n  Select,\\n  Space,\\n  Switch,\\n  Tag,\\n  Typography,\\n  message,\\n} = ctx.libs.antd;\\nconst {\\n  CheckCircleOutlined,\\n  LockOutlined,\\n  MailOutlined,\\n  SaveOutlined,\\n  SendOutlined,\\n  SettingOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst channelResource = ctx.makeResource('MultiRecordResource');\\nchannelResource.setResourceName('notificationChannels');\\nchannelResource.setFilter({ notificationType: 'email' });\\nchannelResource.setPageSize(20);\\n\\nlet initialChannel = null;\\ntry {\\n  await channelResource.refresh();\\n  initialChannel = (channelResource.getData() || [])[0] || null;\\n} catch (error) {\\n  ctx.render(\\n    <Alert\\n      showIcon\\n      type=\\"error\\"\\n      message={ctx.t('Không thể tải cấu hình SMTP')}\\n      description={String(error?.message || error)}\\n    />,\\n  );\\n  return;\\n}\\n\\nconst initialOptions = initialChannel?.options || {};\\nconst splitFrom = (value) => {\\n  const match = String(value || '').match(/^\\\\s*(.*?)\\\\s*<([^>]+)>\\\\s*$/);\\n  return match\\n    ? { senderName: match[1], senderEmail: match[2] }\\n    : { senderName: '', senderEmail: String(value || '') };\\n};\\nconst initialFrom = splitFrom(initialOptions.from);\\n\\nconst SmtpSettings = () => {\\n  const [form] = Form.useForm();\\n  const [channel, setChannel] = useState(initialChannel);\\n  const [saving, setSaving] = useState(false);\\n  const [sending, setSending] = useState(false);\\n  const [result, setResult] = useState(null);\\n\\n  const initialValues = {\\n    host: initialOptions.host || '',\\n    port: Number(initialOptions.port || 587),\\n    secure: initialOptions.secure === true,\\n    account: initialOptions.account || 'hoangduchai@vhmt.vn',\\n    password: '',\\n    senderName: initialFrom.senderName || 'Hệ thống đào tạo an toàn lao động',\\n    senderEmail: initialFrom.senderEmail || initialOptions.account || 'hoangduchai@vhmt.vn',\\n    testRecipient: initialOptions.account || 'hoangduchai@vhmt.vn',\\n  };\\n\\n  const saveConfiguration = async () => {\\n    const values = await form.validateFields();\\n    const password = values.password || channel?.options?.password;\\n    if (!password) {\\n      form.setFields([{ name: 'password', errors: [ctx.t('Vui lòng nhập mật khẩu SMTP hoặc mật khẩu ứng dụng')] }]);\\n      throw new Error(ctx.t('Thiếu mật khẩu SMTP'));\\n    }\\n\\n    const senderName = String(values.senderName || '').trim();\\n    const senderEmail = String(values.senderEmail || '').trim();\\n    const payload = {\\n      name: channel?.name || `s_smtp_${Date.now().toString(36)}`,\\n      title: 'Email SMTP hệ thống',\\n      description: 'Kênh email dùng chung của hệ thống đào tạo an toàn lao động',\\n      notificationType: 'email',\\n      options: {\\n        transport: 'smtp',\\n        host: String(values.host).trim(),\\n        port: Number(values.port),\\n        secure: values.secure === true,\\n        account: String(values.account).trim(),\\n        password,\\n        from: senderName ? `${senderName} <${senderEmail}>` : senderEmail,\\n      },\\n      meta: {\\n        managedBy: 'smtp-settings-page',\\n      },\\n    };\\n\\n    if (channel?.name) {\\n      const updateResource = ctx.makeResource('SingleRecordResource');\\n      updateResource.setResourceName('notificationChannels');\\n      updateResource.setFilterByTk(channel.name);\\n      await updateResource.save(payload);\\n    } else {\\n      const createResource = ctx.makeResource('MultiRecordResource');\\n      createResource.setResourceName('notificationChannels');\\n      await createResource.create(payload);\\n    }\\n\\n    const verifyResource = ctx.makeResource('SingleRecordResource');\\n    verifyResource.setResourceName('notificationChannels');\\n    verifyResource.setFilterByTk(payload.name);\\n    await verifyResource.refresh();\\n    const saved = verifyResource.getData();\\n    if (!saved?.name || saved.notificationType !== 'email') {\\n      throw new Error(ctx.t('Không đọc lại được cấu hình vừa lưu'));\\n    }\\n    setChannel(saved);\\n    form.setFieldValue('password', '');\\n    return { saved, values };\\n  };\\n\\n  const onSave = async () => {\\n    setSaving(true);\\n    setResult(null);\\n    try {\\n      await saveConfiguration();\\n      setResult({ type: 'success', text: ctx.t('Đã lưu và đọc lại cấu hình SMTP thành công.') });\\n      message.success(ctx.t('Đã lưu cấu hình SMTP'));\\n    } catch (error) {\\n      if (error?.errorFields) return;\\n      setResult({ type: 'error', text: String(error?.message || error) });\\n    } finally {\\n      setSaving(false);\\n    }\\n  };\\n\\n  const onSendTest = async () => {\\n    setSending(true);\\n    setResult(null);\\n    try {\\n      const { saved, values } = await saveConfiguration();\\n      const recipient = String(values.testRecipient || '').trim();\\n      const response = await ctx.request({\\n        url: 'messages:send',\\n        method: 'post',\\n        skipNotify: true,\\n        data: {\\n          channelName: saved.name,\\n          triggerFrom: 'manual-smtp-test',\\n          message: {\\n            to: [recipient],\\n            subject: 'Thư kiểm tra cấu hình Email SMTP',\\n            contentType: 'html',\\n            html: '<p>Cấu hình Email SMTP của hệ thống đào tạo an toàn lao động đã gửi thư thành công.</p>',\\n          },\\n        },\\n      });\\n      const sendResult = response?.data?.data || response?.data || {};\\n      if (sendResult.status === 'failure') {\\n        throw new Error(sendResult.reason || ctx.t('Máy chủ từ chối gửi thư'));\\n      }\\n      setResult({\\n        type: 'success',\\n        text: ctx.t('Đã tiếp nhận gửi thư thử tới {{email}}. Vui lòng kiểm tra hộp thư và thư rác.', { email: recipient }),\\n      });\\n      message.success(ctx.t('Đã gửi yêu cầu thử email'));\\n    } catch (error) {\\n      if (error?.errorFields) return;\\n      const detail = error?.response?.data?.errors?.[0]?.message || error?.response?.data?.message || error?.message || error;\\n      setResult({ type: 'error', text: String(detail) });\\n    } finally {\\n      setSending(false);\\n    }\\n  };\\n\\n  return (\\n    <Form form={form} layout=\\"vertical\\" initialValues={initialValues} requiredMark=\\"optional\\">\\n      <Alert\\n        showIcon\\n        type={channel ? 'success' : 'info'}\\n        message={channel ? ctx.t('Đã có kênh email dùng chung') : ctx.t('Chưa có cấu hình SMTP')}\\n        description={\\n          channel\\n            ? ctx.t('Các tính năng gửi email có thể dùng kênh “{{title}}” ({{name}}).', { title: channel.title, name: channel.name })\\n            : ctx.t('Điền thông tin tài khoản email, lưu cấu hình rồi gửi thử ngay tại đây.')\\n        }\\n        style={{ marginBottom: 16 }}\\n      />\\n\\n      <Card\\n        size=\\"small\\"\\n        title={<Space><SettingOutlined />{ctx.t('Máy chủ SMTP')}</Space>}\\n        style={{ marginBottom: 16 }}\\n      >\\n        <Row gutter={16}>\\n          <Col xs={24} md={14}>\\n            <Form.Item label={ctx.t('Máy chủ SMTP')} name=\\"host\\" rules={[{ required: true, message: ctx.t('Vui lòng nhập máy chủ SMTP') }]}>\\n              <Input placeholder=\\"smtp.tenmien.vn\\" autoComplete=\\"off\\" />\\n            </Form.Item>\\n          </Col>\\n          <Col xs={12} md={5}>\\n            <Form.Item label={ctx.t('Cổng')} name=\\"port\\" rules={[{ required: true }]}>\\n              <InputNumber min={1} max={65535} style={{ width: '100%' }} />\\n            </Form.Item>\\n          </Col>\\n          <Col xs={12} md={5}>\\n            <Form.Item label={ctx.t('Mã hóa SSL/TLS')} name=\\"secure\\" valuePropName=\\"checked\\">\\n              <Switch checkedChildren={ctx.t('Bật')} unCheckedChildren={ctx.t('Tắt')} />\\n            </Form.Item>\\n          </Col>\\n        </Row>\\n        <Typography.Text type=\\"secondary\\">\\n          {ctx.t('Thông thường: cổng 465 bật SSL/TLS; cổng 587 tắt mục này để máy chủ nâng cấp kết nối bằng STARTTLS.')}\\n        </Typography.Text>\\n      </Card>\\n\\n      <Card\\n        size=\\"small\\"\\n        title={<Space><LockOutlined />{ctx.t('Tài khoản gửi thư')}</Space>}\\n        style={{ marginBottom: 16 }}\\n      >\\n        <Row gutter={16}>\\n          <Col xs={24} md={12}>\\n            <Form.Item label={ctx.t('Email / tên đăng nhập')} name=\\"account\\" rules={[{ required: true, message: ctx.t('Vui lòng nhập tài khoản SMTP') }]}>\\n              <Input autoComplete=\\"username\\" />\\n            </Form.Item>\\n          </Col>\\n          <Col xs={24} md={12}>\\n            <Form.Item\\n              label={ctx.t('Mật khẩu SMTP')}\\n              name=\\"password\\"\\n              extra={channel?.options?.password ? ctx.t('Để trống nếu không đổi mật khẩu đã lưu.') : ctx.t('Nên dùng mật khẩu ứng dụng do nhà cung cấp email cấp.')}\\n            >\\n              <Input.Password autoComplete=\\"new-password\\" placeholder={channel?.options?.password ? '••••••••' : ''} />\\n            </Form.Item>\\n          </Col>\\n          <Col xs={24} md={12}>\\n            <Form.Item label={ctx.t('Tên người gửi')} name=\\"senderName\\">\\n              <Input />\\n            </Form.Item>\\n          </Col>\\n          <Col xs={24} md={12}>\\n            <Form.Item label={ctx.t('Email người gửi')} name=\\"senderEmail\\" rules={[{ required: true }, { type: 'email', message: ctx.t('Email không hợp lệ') }]}>\\n              <Input />\\n            </Form.Item>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Card\\n        size=\\"small\\"\\n        title={<Space><MailOutlined />{ctx.t('Lưu và gửi thử')}</Space>}\\n      >\\n        <Row gutter={16} align=\\"bottom\\">\\n          <Col xs={24} md={12}>\\n            <Form.Item label={ctx.t('Email nhận thư thử')} name=\\"testRecipient\\" rules={[{ required: true }, { type: 'email', message: ctx.t('Email không hợp lệ') }]}>\\n              <Input />\\n            </Form.Item>\\n          </Col>\\n          <Col xs={24} md={12}>\\n            <Form.Item>\\n              <Space wrap>\\n                <Button type=\\"primary\\" icon={<SaveOutlined />} loading={saving} onClick={onSave}>\\n                  {ctx.t('Lưu cấu hình')}\\n                </Button>\\n                <Button icon={<SendOutlined />} loading={sending} onClick={onSendTest}>\\n                  {ctx.t('Lưu và gửi thử')}\\n                </Button>\\n                {channel && <Tag color=\\"green\\" icon={<CheckCircleOutlined />}>{ctx.t('Đã cấu hình')}</Tag>}\\n              </Space>\\n            </Form.Item>\\n          </Col>\\n        </Row>\\n        {result && <Alert showIcon type={result.type} message={result.text} />}\\n      </Card>\\n    </Form>\\n  );\\n};\\n\\nctx.render(<SmtpSettings />);"}},"__flowSurfaceMeta":{"declaredKey":"main.formBlock"}}}
