qkzw56o3wzw	qkzw56o3wzw	{"parentId":"78a9ibice0e","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê nội dung ôn luyện"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Card, Col, Row, Statistic } = ctx.libs.antd;\\nconst { BookOutlined, ClockCircleOutlined, CheckCircleOutlined, ExclamationCircleOutlined } = ctx.libs.antdIcons;\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('noi_dung_on_luyen');\\n  await ctx.resource.refresh();\\n  const rows = (ctx.resource.getData?.() || []).filter((row) => row.is_deleted !== true);\\n  const metrics = [\\n    { title: ctx.t('Tổng nội dung'), value: rows.length, color: '#1677ff', icon: <BookOutlined /> },\\n    { title: ctx.t('Chưa làm'), value: rows.filter((r) => !r.trang_thai || r.trang_thai === 'chua_lam').length, color: '#8c8c8c', icon: <ExclamationCircleOutlined /> },\\n    { title: ctx.t('Đang làm'), value: rows.filter((r) => r.trang_thai === 'dang_lam').length, color: '#d48806', icon: <ClockCircleOutlined /> },\\n    { title: ctx.t('Đạt'), value: rows.filter((r) => r.trang_thai === 'dat').length, color: '#389e0d', icon: <CheckCircleOutlined /> },\\n  ];\\n  ctx.render(\\n    <Row gutter={[12, 12]}>\\n      {metrics.map((metric) => (\\n        <Col key={metric.title} xs={24} sm={12} xl={6}>\\n          <Card size=\\"small\\" bordered>\\n            <Statistic title={metric.title} value={metric.value} prefix={metric.icon} valueStyle={{ color: metric.color }} />\\n          </Card>\\n        </Col>\\n      ))}\\n    </Row>,\\n  );\\n} catch (error) {\\n  ctx.render(<Alert showIcon type=\\"error\\" message={ctx.t('Error')} description={String(error?.message || error)} />);\\n}"}},"__flowSurfaceMeta":{"declaredKey":"main.statsBlock"}}}
y9hkjwsr03k	y9hkjwsr03k	{"parentId":"78a9ibice0e","subKey":"items","subType":"array","use":"TableBlockModel","props":{},"decoratorProps":{},"stepParams":{"resourceSettings":{"init":{"dataSourceKey":"main","collectionName":"noi_dung_on_luyen"}},"__flowSurfaceMeta":{"declaredKey":"main.table"},"tableSettings":{"pageSize":{"pageSize":20}}}}
fde5q54z0pb	fde5q54z0pb	{"parentId":"78a9ibice0e","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thông tin người dùng"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Card, Descriptions } = ctx.libs.antd;\\nconst { UserOutlined } = ctx.libs.antdIcons;\\ntry {\\n  const currentUser = (await ctx.getVar('ctx.user')) || {};\\n  const roles = currentUser.roles || [];\\n  const roleText = roles.map((r) => r.title || r.name).join(', ');\\n  const items = [\\n    { key: 'nganh_nghe', label: ctx.t('Ngành nghề'), children: currentUser.nganh_nghe?.ten_nganh || ctx.t('Chưa cập nhật') },\\n    { key: 'don_vi', label: ctx.t('Đơn vị'), children: currentUser.don_vi?.ten_don_vi || ctx.t('Chưa cập nhật') },\\n    { key: 'bac_tho', label: ctx.t('Bậc thợ'), children: currentUser.bac_tho?.ten_bac || ctx.t('Chưa cập nhật') },\\n    { key: 'vai_tro', label: ctx.t('Vai trò'), children: roleText || ctx.t('Chưa cập nhật') },\\n  ];\\n  ctx.render(\\n    <Card size=\\"small\\" bordered title={<span><UserOutlined style={{ marginRight: 8 }} />{ctx.t('Thông tin người dùng')}</span>}>\\n      <Descriptions column={{ xs: 1, sm: 2, xl: 4 }} items={items} />\\n    </Card>,\\n  );\\n} catch (error) {\\n  ctx.render(<Alert showIcon type=\\"error\\" message={ctx.t('Error')} description={String(error?.message || error)} />);\\n}"}},"__flowSurfaceMeta":{"declaredKey":"main.userInfoBlock"}}}
