8zwqs8n547t	8zwqs8n547t	{"parentId":"kqvzrimnam7","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê tài liệu"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Card, Col, Row, Statistic } = ctx.libs.antd;\\nconst { FileTextOutlined, ClockCircleOutlined, CheckCircleOutlined, WarningOutlined } = ctx.libs.antdIcons;\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('tai_lieu_huan_luyen');\\n  await ctx.resource.refresh();\\n  const rows = (ctx.resource.getData?.() || []).filter((r) => r.is_deleted !== true);\\n  const metrics = [\\n    { title: ctx.t('Tổng tài liệu'), value: rows.length, color: '#1677ff', icon: <FileTextOutlined /> },\\n    { title: ctx.t('Chờ duyệt'), value: rows.filter((r) => r.trang_thai === 'cho_duyet').length, color: '#d48806', icon: <ClockCircleOutlined /> },\\n    { title: ctx.t('Đã duyệt'), value: rows.filter((r) => r.trang_thai === 'da_duyet').length, color: '#389e0d', icon: <CheckCircleOutlined /> },\\n    { title: ctx.t('Sẵn sàng tra cứu'), value: rows.filter((r) => r.trang_thai_kho === 'san_sang').length, color: '#0958d9', icon: <FileTextOutlined /> },\\n  ];\\n  ctx.render(\\n    <Row gutter={[12, 12]}>\\n      {metrics.map((m) => (\\n        <Col key={m.title} xs={24} sm={12} xl={6}>\\n          <Card size=\\"small\\" bordered>\\n            <Statistic title={m.title} value={m.value} prefix={m.icon} valueStyle={{ color: m.color }} />\\n          </Card>\\n        </Col>\\n      ))}\\n    </Row>,\\n  );\\n} catch (error) {\\n  ctx.render(<Alert showIcon type=\\"error\\" message={ctx.t('Error')} description={String(error?.message || error)} />);\\n}"}},"__flowSurfaceMeta":{"declaredKey":"tab_tai_lieu.statsDocBlock"}}}
