m02w035hduw	m02w035hduw	{"parentId":"18c038ak2f8","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê đối chiếu pháp lý"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Alert, Card, Col, Row, Statistic } = ctx.libs.antd;\\nconst { AuditOutlined, CheckCircleOutlined, CloseCircleOutlined, ExclamationCircleOutlined } = ctx.libs.antdIcons;\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('doi_chieu_phap_ly');\\n  await ctx.resource.refresh();\\n  const rows = (ctx.resource.getData?.() || []).filter((r) => r.is_deleted !== true);\\n  const metrics = [\\n    { title: ctx.t('Tổng nội dung'), value: rows.length, color: '#1677ff', icon: <AuditOutlined /> },\\n    { title: ctx.t('Đạt'), value: rows.filter((r) => r.ket_qua_doi_chieu === 'dat').length, color: '#389e0d', icon: <CheckCircleOutlined /> },\\n    { title: ctx.t('Không đạt'), value: rows.filter((r) => r.ket_qua_doi_chieu === 'khong_dat').length, color: '#cf1322', icon: <CloseCircleOutlined /> },\\n    { title: ctx.t('Cần rà soát'), value: rows.filter((r) => r.ket_qua_doi_chieu === 'can_ra_soat').length, color: '#d48806', icon: <ExclamationCircleOutlined /> },\\n  ];\\n  ctx.render(\\n    <Row gutter={[12, 12]}>\\n      {metrics.map((m) => (\\n        <Col key={m.title} xs={24} sm={12} xl={6}>\\n          <Card size=\\"small\\" bordered>\\n            <Statistic title={m.title} value={m.value} prefix={m.icon} valueStyle={{ color: m.color }} />\\n          </Card>\\n        </Col>\\n      ))}\\n    </Row>,\\n  );\\n} catch (error) {\\n  ctx.render(<Alert showIcon type=\\"error\\" message={ctx.t('Error')} description={String(error?.message || error)} />);\\n}"}},"__flowSurfaceMeta":{"declaredKey":"tab_doi_chieu.statsLegalBlock"}}}
