yy36wixa9ku	yy36wixa9ku	{"parentId":"57oeo0hs8uf","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"const { Button, Alert, Card, Space, Typography, Tag } = ctx.libs.antd;\\nconst { ApiOutlined, CheckCircleOutlined, CloseCircleOutlined } = ctx.libs.antdIcons;\\nconst React = ctx.libs.React;\\n\\nconst TestPanel = () => {\\n  const [state, setState] = React.useState({ status: 'idle', msg: '' });\\n\\n  const findInputByLabel = (patterns) => {\\n    const allInputs = document.querySelectorAll('input');\\n    for (const input of allInputs) {\\n      if (!input.offsetParent) continue;\\n      if (input.type === 'hidden' || input.type === 'checkbox' || input.type === 'radio') continue;\\n      let parent = input.parentElement;\\n      for (let depth = 0; depth < 10 && parent; depth++) {\\n        for (const child of parent.children) {\\n          if (child.contains(input)) continue;\\n          const text = (child.textContent || '').trim();\\n          if (text.length > 120 || text.length < 2) continue;\\n          for (const p of patterns) {\\n            if (p.test(text)) return input.value || '';\\n          }\\n        }\\n        parent = parent.parentElement;\\n      }\\n    }\\n    return '';\\n  };\\n\\n  const onTest = async () => {\\n    setState({ status: 'loading', msg: '' });\\n    const baseUrl = findInputByLabel([/base.?url/i, /địa chỉ dịch vụ/i]);\\n    const apiKey = findInputByLabel([/api.?key/i, /xác thực/i]);\\n    if (!baseUrl || !apiKey) {\\n      const cnt = document.querySelectorAll('input').length;\\n      setState({ status: 'error', msg: 'Không đọc được Base URL hoặc API Key từ biểu mẫu (tìm thấy ' + cnt + ' ô nhập). Vui lòng thử tải lại trang.' });\\n      return;\\n    }\\n    const testUrl = baseUrl.replace(/\\\\/+$/, '') + '/models';\\n    try {\\n      const res = await fetch(testUrl, { method: 'GET', headers: { 'Authorization': 'Bearer ' + apiKey } });\\n      if (res.ok) {\\n        setState({ status: 'success', msg: 'Kết nối thành công! Mã phản hồi: HTTP ' + res.status });\\n      } else {\\n        const body = await res.text().catch(() => '');\\n        setState({ status: 'error', msg: 'Mã lỗi HTTP ' + res.status + (body ? ' — ' + body.substring(0, 200) : '') });\\n      }\\n    } catch (err) {\\n      setState({ status: 'error', msg: 'Không thể kết nối: ' + (err.message || String(err)) });\\n    }\\n  };\\n\\n  return (\\n    <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n      <Space direction=\\"vertical\\" style={{ width: '100%' }}>\\n        <Typography.Text strong>Kiểm tra kết nối</Typography.Text>\\n        <Typography.Text type=\\"secondary\\" style={{ fontSize: 13 }}>Nhập Base URL và API Key ở biểu mẫu trên, sau đó bấm nút kiểm tra.</Typography.Text>\\n        <Space>\\n          <Button type=\\"primary\\" icon={<ApiOutlined />} loading={state.status === 'loading'} onClick={onTest}>Kiểm tra kết nối API</Button>\\n          {state.status === 'success' && <Tag icon={<CheckCircleOutlined />} color=\\"success\\">Đã kết nối</Tag>}\\n          {state.status === 'error' && <Tag icon={<CloseCircleOutlined />} color=\\"error\\">Thất bại</Tag>}\\n        </Space>\\n        {state.status === 'success' && <Alert type=\\"success\\" message={state.msg} showIcon />}\\n        {state.status === 'error' && <Alert type=\\"error\\" message={state.msg} showIcon />}\\n      </Space>\\n    </Card>\\n  );\\n};\\n\\nctx.render(<TestPanel />);\\n"}}}}
