pb9ro6hugpa	pb9ro6hugpa	{"parentId":"8ilo0h5hchb","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"12","code":"const { useState, useEffect, useCallback, useMemo } = ctx.libs.React;\\nconst { Table, Button, Input, Select, Space, Tag, Modal, Form, Tooltip, Popconfirm, Typography, Card, Row, Col, Divider, Descriptions, InputNumber, Transfer } = ctx.libs.antd;\\nconst { SearchOutlined, PlusOutlined, DeleteOutlined, EyeOutlined, ReloadOutlined, EditOutlined, SendOutlined, FileTextOutlined, OrderedListOutlined, CheckCircleOutlined } = ctx.libs.antdIcons;\\n\\nctx.initResource('MultiRecordResource');\\nconst resource = ctx.resource;\\nresource.setResourceName('de_thi');\\nresource.setAppends(['nganh_nghe', 'bac_tho', 'cau_hoi']);\\nresource.setSort(['-createdAt']);\\nresource.setPageSize(15);\\n\\nconst nganhNgheRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nnganhNgheRes?.setResourceName('nganh_nghe');\\nnganhNgheRes?.setPageSize(200);\\n\\nconst bacThoRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nbacThoRes?.setResourceName('bac_tho');\\nbacThoRes?.setPageSize(200);\\n\\nconst cauHoiRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\ncauHoiRes?.setResourceName('cau_hoi');\\ncauHoiRes?.setPageSize(500);\\ncauHoiRes?.setAppends(['nganh_nghe']);\\n\\nconst statusMap = {\\n  nhap: { color: 'default', label: 'Bản nháp' },\\n  cho_phe_duyet: { color: 'gold', label: 'Chờ phê duyệt' },\\n  da_phe_duyet: { color: 'green', label: 'Đã phê duyệt' },\\n  tu_choi: { color: 'red', label: 'Từ chối' }\\n};\\nconst hinhThucMap = { trac_nghiem: 'Trắc nghiệm', tu_luan: 'Tự luận' };\\nconst mucDoMap = { de: 'Dễ', trung_binh: 'TB', kho: 'Khó' };\\n\\nfunction App() {\\n  const [loading, setLoading] = useState(true);\\n  const [data, setData] = useState([]);\\n  const [meta, setMeta] = useState({});\\n  const [search, setSearch] = useState('');\\n  const [filterStatus, setFilterStatus] = useState(null);\\n  const [modalOpen, setModalOpen] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [detailOpen, setDetailOpen] = useState(false);\\n  const [detailRecord, setDetailRecord] = useState(null);\\n  const [saving, setSaving] = useState(false);\\n  const [nganhNgheList, setNganhNgheList] = useState([]);\\n  const [bacThoList, setBacThoList] = useState([]);\\n  const [allCauHoi, setAllCauHoi] = useState([]);\\n  const [selectedCauHoi, setSelectedCauHoi] = useState([]);\\n  const [cauHoiModalOpen, setCauHoiModalOpen] = useState(false);\\n  const [cauHoiFilter, setCauHoiFilter] = useState({ search: '', hinh_thuc: null, muc_do: null });\\n  const [form] = Form.useForm();\\n\\n  const loadOptions = useCallback(async () => {\\n    try {\\n      if (nganhNgheRes) { await nganhNgheRes.refresh(); setNganhNgheList(nganhNgheRes.getData() || []); }\\n      if (bacThoRes) { await bacThoRes.refresh(); setBacThoList(bacThoRes.getData() || []); }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadCauHoi = useCallback(async () => {\\n    try {\\n      if (cauHoiRes) {\\n        cauHoiRes.setFilter({ is_deleted: { $ne: true }, trang_thai: { $eq: 'da_phe_duyet' } });\\n        await cauHoiRes.refresh();\\n        setAllCauHoi(cauHoiRes.getData() || []);\\n      }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadData = useCallback(async (page) => {\\n    setLoading(true);\\n    try {\\n      const filter = { is_deleted: { $ne: true } };\\n      if (search) filter.$or = [\\n        { ten_de_thi: { $includes: search } },\\n        { ma_de_thi: { $includes: search } }\\n      ];\\n      if (filterStatus) filter.trang_thai = { $eq: filterStatus };\\n      resource.setFilter(filter);\\n      if (page) resource.setPage(page);\\n      await resource.refresh();\\n      setData(resource.getData() || []);\\n      setMeta(resource.getMeta() || {});\\n    } catch (e) {\\n      ctx.message.error('Lỗi tải dữ liệu');\\n    }\\n    setLoading(false);\\n  }, [search, filterStatus]);\\n\\n  useEffect(() => { loadData(1); loadOptions(); loadCauHoi(); }, []);\\n\\n  const handleSearch = useCallback(() => { loadData(1); }, [loadData]);\\n\\n  const openDetail = useCallback((record) => {\\n    const ch = record.cau_hoi || [];\\n    const seen = new Set();\\n    const uniqueCh = ch.filter(c => { if (seen.has(c.id)) return false; seen.add(c.id); return true; });\\n    setDetailRecord({ ...record, cau_hoi: uniqueCh });\\n    setDetailOpen(true);\\n  }, []);\\n\\n  const openCreate = useCallback(() => {\\n    setEditRecord(null);\\n    form.resetFields();\\n    setSelectedCauHoi([]);\\n    form.setFieldsValue({ thoi_gian_lam_bai: 60, diem_dat: 5.0 });\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const openEdit = useCallback((record) => {\\n    setEditRecord(record);\\n    const ids = (record.cau_hoi || []).map(ch => ch.id);\\n    setSelectedCauHoi(ids);\\n    form.setFieldsValue({\\n      ten_de_thi: record.ten_de_thi,\\n      mo_ta: record.mo_ta,\\n      nganhNgheId: record.nganhNgheId || (record.nganh_nghe && record.nganh_nghe.id),\\n      bacThoId: record.bacThoId || (record.bac_tho && record.bac_tho.id),\\n      thoi_gian_lam_bai: record.thoi_gian_lam_bai,\\n      diem_dat: record.diem_dat,\\n      phien_ban: record.phien_ban\\n    });\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const handleSave = useCallback(async () => {\\n    try {\\n      const values = await form.validateFields();\\n      setSaving(true);\\n      const payload = {\\n        ten_de_thi: values.ten_de_thi,\\n        mo_ta: values.mo_ta,\\n        nganhNgheId: values.nganhNgheId || null,\\n        bacThoId: values.bacThoId || null,\\n        so_cau_hoi: selectedCauHoi.length,\\n        thoi_gian_lam_bai: values.thoi_gian_lam_bai,\\n        diem_dat: values.diem_dat,\\n        phien_ban: values.phien_ban || 1,\\n        cau_hoi: selectedCauHoi.map(id => ({ id }))\\n      };\\n      if (editRecord) {\\n        payload.trang_thai = 'nhap';\\n        await resource.update(editRecord.id, payload);\\n        ctx.message.success('Cập nhật đề thi thành công, trạng thái đã chuyển về Bản nháp');\\n      } else {\\n        await resource.create({ ...payload, trang_thai: 'nhap', is_deleted: false });\\n        ctx.message.success('Tạo đề thi thành công');\\n      }\\n      setModalOpen(false);\\n      form.resetFields();\\n      setSelectedCauHoi([]);\\n      loadData();\\n    } catch (e) {\\n      if (e.errorFields) { setSaving(false); return; }\\n      ctx.message.error('Lỗi lưu đề thi');\\n    }\\n    setSaving(false);\\n  }, [form, editRecord, selectedCauHoi, loadData]);\\n\\n  const handleDelete = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { is_deleted: true });\\n      ctx.message.success('Đã xoá đề thi');\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi xoá'); }\\n  }, [loadData]);\\n\\n  const handleSendApproval = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'cho_phe_duyet' });\\n      ctx.message.success('Đã gửi duyệt đề thi');\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi gửi duyệt'); }\\n  }, [loadData]);\\n\\n  const handleApprove = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'da_phe_duyet' });\\n      ctx.message.success('Đã phê duyệt đề thi');\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi phê duyệt'); }\\n  }, [loadData]);\\n\\n  const filteredCauHoi = useMemo(() => {\\n    let list = allCauHoi;\\n    if (cauHoiFilter.search) {\\n      const s = cauHoiFilter.search.toLowerCase();\\n      list = list.filter(ch => (ch.ten_cau_hoi || '').toLowerCase().includes(s) || (ch.noi_dung || '').toLowerCase().includes(s) || (ch.ma_cau_hoi || '').toLowerCase().includes(s));\\n    }\\n    if (cauHoiFilter.hinh_thuc) list = list.filter(ch => ch.hinh_thuc === cauHoiFilter.hinh_thuc);\\n    if (cauHoiFilter.muc_do) list = list.filter(ch => ch.muc_do_kho === cauHoiFilter.muc_do);\\n    return list;\\n  }, [allCauHoi, cauHoiFilter]);\\n\\n  const cauHoiColumns = useMemo(() => [\\n    { title: 'Mã', dataIndex: 'ma_cau_hoi', width: 100, ellipsis: true },\\n    { title: 'Tên câu hỏi', dataIndex: 'ten_cau_hoi', ellipsis: true, render: (v, r) => v || (r.noi_dung || '').substring(0, 40) || '-' },\\n    { title: 'Loại', dataIndex: 'hinh_thuc', width: 100, render: v => hinhThucMap[v] || v || '-' },\\n    { title: 'Độ khó', dataIndex: 'muc_do_kho', width: 70, render: v => mucDoMap[v] || v || '-' }\\n  ], []);\\n\\n  const columns = useMemo(() => [\\n    { title: 'Mã đề', dataIndex: 'ma_de_thi', width: 110, ellipsis: true, render: v => v || '-' },\\n    {\\n      title: 'Tên đề thi', dataIndex: 'ten_de_thi', ellipsis: true,\\n      render: (text, record) => (\\n        <Typography.Link onClick={() => openDetail(record)}>\\n          {text || '-'}\\n        </Typography.Link>\\n      )\\n    },\\n    {\\n      title: 'Ngành nghề', dataIndex: 'nganh_nghe', width: 140, ellipsis: true,\\n      render: v => v?.ten_nganh || '-'\\n    },\\n    { title: 'Số CH', dataIndex: 'so_cau_hoi', width: 70, render: v => v || 0 },\\n    { title: 'T.gian (phút)', dataIndex: 'thoi_gian_lam_bai', width: 100, render: v => v || '-' },\\n    { title: 'Điểm đạt', dataIndex: 'diem_dat', width: 80, render: v => v != null ? v : '-' },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', width: 130,\\n      render: v => { const s = statusMap[v] || { color: 'default', label: v || '-' }; return <Tag color={s.color}>{s.label}</Tag>; }\\n    },\\n    {\\n      title: 'Thao tác', width: 200, fixed: 'right',\\n      render: (_, record) => (\\n        <Space size={4}>\\n          <Tooltip title=\\"Xem\\"><Button icon={<EyeOutlined />} onClick={() => openDetail(record)} /></Tooltip>\\n          <Tooltip title=\\"Sửa\\"><Button icon={<EditOutlined />} onClick={() => openEdit(record)} /></Tooltip>\\n          {(!record.trang_thai || record.trang_thai === 'nhap' || record.trang_thai === 'tu_choi') && (\\n            <Tooltip title=\\"Gửi duyệt\\"><Button icon={<SendOutlined />} onClick={() => handleSendApproval(record)} /></Tooltip>\\n          )}\\n          {record.trang_thai === 'cho_phe_duyet' && (\\n            <Popconfirm title=\\"Phê duyệt đề thi này?\\" onConfirm={() => handleApprove(record)} okText=\\"Phê duyệt\\" cancelText=\\"Huỷ\\">\\n              <Tooltip title=\\"Phê duyệt\\"><Button style={{ color: '#52c41a', borderColor: '#52c41a' }} icon={<CheckCircleOutlined />} /></Tooltip>\\n            </Popconfirm>\\n          )}\\n          <Popconfirm title=\\"Xoá đề thi này?\\" onConfirm={() => handleDelete(record)} okText=\\"Xoá\\" cancelText=\\"Huỷ\\">\\n            <Tooltip title=\\"Xoá\\"><Button danger icon={<DeleteOutlined />} /></Tooltip>\\n          </Popconfirm>\\n        </Space>\\n      )\\n    }\\n  ], [openEdit, openDetail, handleDelete, handleSendApproval, handleApprove]);\\n\\n  return (\\n    <div style={{ padding: '0 4px' }}>\\n      <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n        <Row gutter={[12, 12]} align=\\"middle\\">\\n          <Col flex=\\"auto\\">\\n            <Space wrap size={8}>\\n              <Input placeholder=\\"Tìm đề thi...\\" prefix={<SearchOutlined />} value={search} onChange={e => setSearch(e.target.value)} onPressEnter={handleSearch} style={{ width: 200 }} allowClear />\\n              <Select placeholder=\\"Trạng thái\\" value={filterStatus} onChange={setFilterStatus} allowClear style={{ width: 150 }} options={Object.entries(statusMap).map(([k, v]) => ({ label: v.label, value: k }))} />\\n              <Button icon={<SearchOutlined />} type=\\"primary\\" onClick={handleSearch}>Tìm</Button>\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Tooltip title=\\"Tải lại\\"><Button icon={<ReloadOutlined />} onClick={() => loadData()} /></Tooltip>\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={openCreate}>Tạo đề thi</Button>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Table rowKey=\\"id\\" columns={columns} dataSource={data} loading={loading} size=\\"middle\\" scroll={{ x: 1000 }}\\n        pagination={{\\n          current: meta.page || 1, pageSize: meta.pageSize || 15, total: meta.count || 0,\\n          showTotal: (total) => `Tổng ${total} đề thi`, showSizeChanger: true,\\n          onChange: (page, pageSize) => { resource.setPageSize(pageSize); loadData(page); }\\n        }}\\n      />\\n\\n      <Modal title={editRecord ? 'Sửa đề thi' : 'Tạo đề thi mới'} open={modalOpen} onCancel={() => setModalOpen(false)} onOk={handleSave} confirmLoading={saving} okText={editRecord ? 'Cập nhật' : 'Tạo'} cancelText=\\"Huỷ\\" width={850} destroyOnClose>\\n        <Form form={form} layout=\\"vertical\\" style={{ marginTop: 16 }}>\\n          <Row gutter={16}>\\n            <Col span={16}>\\n              <Form.Item name=\\"ten_de_thi\\" label=\\"Tên đề thi\\" rules={[{ required: true, message: 'Nhập tên đề thi' }]}>\\n                <Input placeholder=\\"Tên đề thi\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"phien_ban\\" label=\\"Phiên bản\\">\\n                <InputNumber style={{ width: '100%' }} min={1} placeholder=\\"1\\" />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={12}>\\n              <Form.Item name=\\"nganhNgheId\\" label=\\"Ngành nghề\\">\\n                <Select placeholder=\\"Chọn ngành nghề\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={nganhNgheList.map(nn => ({ label: nn.ten_nganh || nn.ten_nganh_nghe, value: nn.id }))} />\\n              </Form.Item>\\n            </Col>\\n            <Col span={12}>\\n              <Form.Item name=\\"bacThoId\\" label=\\"Bậc thợ\\">\\n                <Select placeholder=\\"Chọn bậc thợ\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={bacThoList.map(bt => ({ label: bt.ten_bac || bt.ten_bac_tho, value: bt.id }))} />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={12}>\\n              <Form.Item name=\\"thoi_gian_lam_bai\\" label=\\"Thời gian (phút)\\" rules={[{ required: true, message: 'Nhập thời gian' }]}>\\n                <InputNumber style={{ width: '100%' }} min={1} placeholder=\\"60\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={12}>\\n              <Form.Item name=\\"diem_dat\\" label=\\"Điểm đạt (thang 10)\\" rules={[{ required: true, message: 'Nhập điểm đạt' }]}>\\n                <InputNumber style={{ width: '100%' }} min={0} max={10} step={0.5} placeholder=\\"5.0\\" />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\">\\n            <Input.TextArea rows={2} placeholder=\\"Mô tả đề thi...\\" />\\n          </Form.Item>\\n\\n          <Divider style={{ margin: '8px 0 16px' }} />\\n          <div style={{ marginBottom: 8 }}>\\n            <Row align=\\"middle\\" justify=\\"space-between\\">\\n              <Col><Typography.Text strong><OrderedListOutlined /> Danh sách câu hỏi ({selectedCauHoi.length} câu)</Typography.Text></Col>\\n              <Col><Button size=\\"small\\" icon={<PlusOutlined />} onClick={() => setCauHoiModalOpen(true)}>Chọn câu hỏi</Button></Col>\\n            </Row>\\n          </div>\\n          {selectedCauHoi.length > 0 && (\\n            <Table rowKey=\\"id\\" size=\\"small\\" dataSource={allCauHoi.filter(ch => selectedCauHoi.includes(ch.id))} pagination={false}\\n              columns={[\\n                { title: 'STT', width: 50, render: (_, __, i) => i + 1 },\\n                { title: 'Mã', dataIndex: 'ma_cau_hoi', width: 100 },\\n                { title: 'Tên câu hỏi', dataIndex: 'ten_cau_hoi', ellipsis: true, render: (v, r) => v || (r.noi_dung || '').substring(0, 50) },\\n                { title: 'Loại', dataIndex: 'hinh_thuc', width: 100, render: v => hinhThucMap[v] || '-' },\\n                { title: 'Độ khó', dataIndex: 'muc_do_kho', width: 80, render: v => mucDoMap[v] || '-' },\\n                {\\n                  title: '', width: 40,\\n                  render: (_, record) => <Button danger icon={<DeleteOutlined />} onClick={() => setSelectedCauHoi(prev => prev.filter(id => id !== record.id))} />\\n                }\\n              ]}\\n            />\\n          )}\\n        </Form>\\n      </Modal>\\n\\n      <Modal title=\\"Chọn câu hỏi cho đề thi\\" open={cauHoiModalOpen} onCancel={() => setCauHoiModalOpen(false)} width={900} footer={[\\n        <Button key=\\"close\\" onClick={() => setCauHoiModalOpen(false)}>Đóng</Button>\\n      ]} destroyOnClose>\\n        <Card size=\\"small\\" style={{ marginBottom: 12 }}>\\n          <Space wrap size={8}>\\n            <Input placeholder=\\"Tìm câu hỏi...\\" prefix={<SearchOutlined />} value={cauHoiFilter.search} onChange={e => setCauHoiFilter(f => ({ ...f, search: e.target.value }))} style={{ width: 200 }} allowClear />\\n            <Select placeholder=\\"Hình thức\\" value={cauHoiFilter.hinh_thuc} onChange={v => setCauHoiFilter(f => ({ ...f, hinh_thuc: v }))} allowClear style={{ width: 130 }} options={[{ label: 'Trắc nghiệm', value: 'trac_nghiem' }, { label: 'Tự luận', value: 'tu_luan' }]} />\\n            <Select placeholder=\\"Mức độ\\" value={cauHoiFilter.muc_do} onChange={v => setCauHoiFilter(f => ({ ...f, muc_do: v }))} allowClear style={{ width: 120 }} options={[{ label: 'Dễ', value: 'de' }, { label: 'Trung bình', value: 'trung_binh' }, { label: 'Khó', value: 'kho' }]} />\\n            <Typography.Text type=\\"secondary\\">Đã chọn: {selectedCauHoi.length}</Typography.Text>\\n          </Space>\\n        </Card>\\n        <Table rowKey=\\"id\\" size=\\"small\\" dataSource={filteredCauHoi} columns={cauHoiColumns} pagination={{ pageSize: 10, showSizeChanger: false, showTotal: t => `${t} câu hỏi` }}\\n          rowSelection={{\\n            selectedRowKeys: selectedCauHoi,\\n            onChange: (keys) => setSelectedCauHoi(keys),\\n            getCheckboxProps: () => ({})\\n          }}\\n        />\\n      </Modal>\\n\\n      <Modal title=\\"Chi tiết đề thi\\" open={detailOpen} onCancel={() => { setDetailOpen(false); setDetailRecord(null); }} footer={null} width={800} destroyOnClose>\\n        {detailRecord && (\\n          <div>\\n            <Descriptions bordered size=\\"small\\" column={2} style={{ marginBottom: 16 }}>\\n              <Descriptions.Item label=\\"Mã đề\\">{detailRecord.ma_de_thi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Trạng thái\\"><Tag color={(statusMap[detailRecord.trang_thai] || {}).color}>{(statusMap[detailRecord.trang_thai] || {}).label || '-'}</Tag></Descriptions.Item>\\n              <Descriptions.Item label=\\"Tên đề thi\\" span={2}>{detailRecord.ten_de_thi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Ngành nghề\\">{detailRecord.nganh_nghe?.ten_nganh || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Bậc thợ\\">{detailRecord.bac_tho?.ten_bac || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Số câu hỏi\\">{(detailRecord.cau_hoi || []).length}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Thời gian\\">{detailRecord.thoi_gian_lam_bai ? `${detailRecord.thoi_gian_lam_bai} phút` : '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Điểm đạt\\">{detailRecord.diem_dat != null ? detailRecord.diem_dat : '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Phiên bản\\">{detailRecord.phien_ban || '-'}</Descriptions.Item>\\n            </Descriptions>\\n            {detailRecord.mo_ta && (\\n              <>\\n                <Typography.Title level={5}><FileTextOutlined /> Mô tả</Typography.Title>\\n                <Card size=\\"small\\" style={{ marginBottom: 12, backgroundColor: '#fafafa' }}>\\n                  <Typography.Paragraph style={{ whiteSpace: 'pre-wrap', margin: 0 }}>{detailRecord.mo_ta}</Typography.Paragraph>\\n                </Card>\\n              </>\\n            )}\\n            {(detailRecord.cau_hoi || []).length > 0 ? (\\n              <>\\n                <Typography.Title level={5}><OrderedListOutlined /> Danh sách câu hỏi ({detailRecord.cau_hoi.length} câu)</Typography.Title>\\n                <Table rowKey=\\"id\\" size=\\"small\\" dataSource={detailRecord.cau_hoi} pagination={false}\\n                  columns={[\\n                    { title: 'STT', width: 50, render: (_, __, i) => i + 1 },\\n                    { title: 'Mã', dataIndex: 'ma_cau_hoi', width: 100 },\\n                    { title: 'Tên câu hỏi', dataIndex: 'ten_cau_hoi', ellipsis: true, render: (v, r) => v || (r.noi_dung || '').substring(0, 50) || '-' },\\n                    { title: 'Loại', dataIndex: 'hinh_thuc', width: 100, render: v => hinhThucMap[v] || '-' },\\n                    { title: 'Độ khó', dataIndex: 'muc_do_kho', width: 80, render: v => mucDoMap[v] || '-' }\\n                  ]}\\n                />\\n              </>\\n            ) : null}\\n          </div>\\n        )}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);"}},"__flowSurfaceMeta":{"declaredKey":"exam.examStats"},"cardSettings":{"blockHeight":{"heightMode":"specifyValue","height":125}}},"parent":"8ilo0h5hchb","sortIndex":2,"flowRegistry":{}}
