w3exw78afac	w3exw78afac	{"parentId":"p1l9v7a9v77","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"12","code":"const { useState, useEffect, useCallback, useMemo } = ctx.libs.React;\\nconst { Table, Button, Input, Select, Space, Tag, Modal, Form, Tooltip, Popconfirm, Typography, Card, Row, Col, InputNumber, DatePicker, Divider, List, Empty, Badge, Descriptions, Checkbox } = ctx.libs.antd;\\nconst { SearchOutlined, PlusOutlined, DeleteOutlined, EyeOutlined, ReloadOutlined, BookOutlined, EditOutlined, SendOutlined, CheckCircleOutlined } = ctx.libs.antdIcons;\\nconst dayjs = ctx.libs.dayjs;\\n\\nctx.initResource('MultiRecordResource');\\nconst resource = ctx.resource;\\nresource.setResourceName('khoa_huan_luyen');\\nresource.setAppends(['chuong_hoc', 'nganh_nghe', 'bac_tho', 'bac_dich', 'don_vi', 'tai_lieu', 'lop_hoc']);\\nresource.setSort(['-createdAt']);\\nresource.setPageSize(15);\\n\\nconst nganhNgheRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nnganhNgheRes?.setResourceName('nganh_nghe');\\nnganhNgheRes?.setPageSize(200);\\n\\nconst bacThoRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nbacThoRes?.setResourceName('bac_tho');\\nbacThoRes?.setPageSize(200);\\n\\nconst countRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\ncountRes?.setResourceName('khoa_huan_luyen');\\ncountRes?.setPageSize(1);\\n\\nconst baiHocRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nbaiHocRes?.setResourceName('chuong_hoc');\\nbaiHocRes?.setFilter({ is_deleted: { $ne: true } });\\nbaiHocRes?.setPageSize(200);\\n\\nconst statusMap = {\\n  nhap: { color: 'default', label: 'Bản nháp' },\\n  cho_phe_duyet: { color: 'processing', label: 'Chờ phê duyệt' },\\n  da_phe_duyet: { color: 'success', label: 'Đã phê duyệt' },\\n  tu_choi: { color: 'error', label: 'Từ chối' },\\n  dang_mo: { color: 'blue', label: 'Đang mở' },\\n  da_dong: { color: 'default', label: 'Đã đóng' }\\n};\\nconst hinhThucMap = {\\n  tai_cho: 'Tại chỗ',\\n  truc_tuyen: 'Trực tuyến',\\n  ket_hop: 'Kết hợp'\\n};\\n\\nfunction App() {\\n  const [loading, setLoading] = useState(true);\\n  const [data, setData] = useState([]);\\n  const [meta, setMeta] = useState({});\\n  const [search, setSearch] = useState('');\\n  const [filterStatus, setFilterStatus] = useState(null);\\n  const [filterForm, setFilterForm] = useState(null);\\n  const [modalOpen, setModalOpen] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [detailOpen, setDetailOpen] = useState(false);\\n  const [detailRecord, setDetailRecord] = useState(null);\\n  const [saving, setSaving] = useState(false);\\n  const [nganhNgheList, setNganhNgheList] = useState([]);\\n  const [bacThoList, setBacThoList] = useState([]);\\n  const [allBaiHoc, setAllBaiHoc] = useState([]);\\n  const [selectedBaiHoc, setSelectedBaiHoc] = useState([]);\\n  const [baiHocPickerOpen, setBaiHocPickerOpen] = useState(false);\\n  const [baiHocSearch, setBaiHocSearch] = useState('');\\n  const [form] = Form.useForm();\\n\\n  const loadOptions = useCallback(async () => {\\n    try {\\n      if (nganhNgheRes) { await nganhNgheRes.refresh(); setNganhNgheList(nganhNgheRes.getData() || []); }\\n      if (bacThoRes) { await bacThoRes.refresh(); setBacThoList(bacThoRes.getData() || []); }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadBaiHoc = useCallback(async () => {\\n    try {\\n      if (baiHocRes) { await baiHocRes.refresh(); setAllBaiHoc(baiHocRes.getData() || []); }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadData = useCallback(async (page) => {\\n    setLoading(true);\\n    try {\\n      const filter = { is_deleted: { $ne: true } };\\n      if (search) filter.ten_khoa_hoc = { $includes: search };\\n      if (filterStatus) filter.trang_thai = { $eq: filterStatus };\\n      if (filterForm) filter.hinh_thuc = { $eq: filterForm };\\n      resource.setFilter(filter);\\n      if (page) resource.setPage(page);\\n      await resource.refresh();\\n      setData(resource.getData() || []);\\n      setMeta(resource.getMeta() || {});\\n    } catch (e) {\\n      ctx.message.error('Lỗi tải dữ liệu');\\n    }\\n    setLoading(false);\\n  }, [search, filterStatus, filterForm]);\\n\\n  useEffect(() => { loadData(1); loadOptions(); loadBaiHoc(); }, []);\\n\\n  const handleSearch = useCallback(() => { loadData(1); }, [loadData]);\\n\\n  const generateMaKhoa = useCallback(async () => {\\n    try {\\n      if (countRes) {\\n        await countRes.refresh();\\n        const total = countRes.getMeta()?.count || 0;\\n        return 'KHL-' + String(total + 1).padStart(6, '0');\\n      }\\n      return 'KHL-' + String(Date.now()).slice(-6);\\n    } catch (e) {\\n      return 'KHL-' + String(Date.now()).slice(-6);\\n    }\\n  }, []);\\n\\n  const openCreate = useCallback(async () => {\\n    setEditRecord(null);\\n    setSelectedBaiHoc([]);\\n    form.resetFields();\\n    const maKhoa = await generateMaKhoa();\\n    form.setFieldsValue({ ma_khoa_hoc: maKhoa });\\n    setModalOpen(true);\\n  }, [form, generateMaKhoa]);\\n\\n  const openEdit = useCallback((record) => {\\n    setEditRecord(record);\\n    const existingBaiHocIds = (record.chuong_hoc || []).filter(c => !c.is_deleted).map(c => c.id);\\n    setSelectedBaiHoc(existingBaiHocIds);\\n    form.setFieldsValue({\\n      ma_khoa_hoc: record.ma_khoa_hoc,\\n      ten_khoa_hoc: record.ten_khoa_hoc,\\n      hinh_thuc: record.hinh_thuc,\\n      doi_tuong: record.doi_tuong,\\n      thoi_luong_gio: record.thoi_luong_gio,\\n      mo_ta: record.mo_ta,\\n      giang_vien: record.giang_vien,\\n      ngay_bat_dau: record.ngay_bat_dau ? dayjs(record.ngay_bat_dau) : null,\\n      ngay_ket_thuc: record.ngay_ket_thuc ? dayjs(record.ngay_ket_thuc) : null,\\n      nganh_nghe: (record.nganh_nghe || []).map(nn => nn.id),\\n      bac_tho: (record.bac_tho || []).map(bt => bt.id)\\n    });\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const handleSave = useCallback(async () => {\\n    try {\\n      const values = await form.validateFields();\\n      setSaving(true);\\n      const payload = {\\n        ma_khoa_hoc: values.ma_khoa_hoc,\\n        ten_khoa_hoc: values.ten_khoa_hoc,\\n        hinh_thuc: values.hinh_thuc,\\n        doi_tuong: values.doi_tuong,\\n        thoi_luong_gio: values.thoi_luong_gio,\\n        mo_ta: values.mo_ta,\\n        giang_vien: values.giang_vien,\\n        ngay_bat_dau: values.ngay_bat_dau ? values.ngay_bat_dau.format('YYYY-MM-DD') : null,\\n        ngay_ket_thuc: values.ngay_ket_thuc ? values.ngay_ket_thuc.format('YYYY-MM-DD') : null,\\n        nganh_nghe: (values.nganh_nghe || []).map(id => ({ id })),\\n        bac_tho: (values.bac_tho || []).map(id => ({ id })),\\n        chuong_hoc: selectedBaiHoc.map(id => ({ id }))\\n      };\\n      if (editRecord) {\\n        payload.trang_thai = 'nhap';\\n        await resource.update(editRecord.id, payload);\\n        ctx.message.success('Cập nhật khóa huấn luyện thành công, trạng thái đã chuyển về Bản nháp');\\n      } else {\\n        await resource.create({ ...payload, trang_thai: 'nhap', is_deleted: false });\\n        ctx.message.success('Tạo khóa huấn luyện thành công');\\n      }\\n      setModalOpen(false);\\n      form.resetFields();\\n      setSelectedBaiHoc([]);\\n      loadData();\\n      loadBaiHoc();\\n    } catch (e) {\\n      if (e.errorFields) { setSaving(false); return; }\\n      ctx.message.error('Lỗi lưu khóa huấn luyện');\\n    }\\n    setSaving(false);\\n  }, [form, editRecord, loadData, loadBaiHoc, selectedBaiHoc]);\\n\\n  const handleDelete = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { is_deleted: true });\\n      ctx.message.success('Đã xoá khóa: ' + record.ten_khoa_hoc);\\n      loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi xoá');\\n    }\\n  }, [loadData]);\\n\\n  const handleSendApproval = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'cho_phe_duyet' });\\n      ctx.message.success('Đã gửi duyệt khóa: ' + record.ten_khoa_hoc);\\n      loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi gửi duyệt');\\n    }\\n  }, [loadData]);\\n\\n  const handleApprove = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'da_phe_duyet' });\\n      ctx.message.success('Đã phê duyệt khóa: ' + record.ten_khoa_hoc);\\n      loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi phê duyệt');\\n    }\\n  }, [loadData]);\\n\\n  const filteredBaiHocForPicker = useMemo(() => {\\n    let list = allBaiHoc;\\n    if (baiHocSearch) {\\n      const s = baiHocSearch.toLowerCase();\\n      list = list.filter(bh => (bh.ten_chuong || '').toLowerCase().includes(s) || (bh.ma_chuong || '').toLowerCase().includes(s));\\n    }\\n    return list;\\n  }, [allBaiHoc, baiHocSearch]);\\n\\n  const selectedBaiHocNames = useMemo(() => {\\n    return allBaiHoc.filter(bh => selectedBaiHoc.includes(bh.id));\\n  }, [allBaiHoc, selectedBaiHoc]);\\n\\n  const columns = useMemo(() => [\\n    {\\n      title: 'Mã khóa',\\n      dataIndex: 'ma_khoa_hoc',\\n      width: 130,\\n      ellipsis: true,\\n      render: (val) => val || '-'\\n    },\\n    {\\n      title: 'Tên khóa huấn luyện',\\n      dataIndex: 'ten_khoa_hoc',\\n      ellipsis: true,\\n      render: (text, record) => (\\n        <Typography.Link onClick={() => { setDetailRecord(record); setDetailOpen(true); }}>\\n          {text}\\n        </Typography.Link>\\n      )\\n    },\\n    {\\n      title: 'Hình thức',\\n      dataIndex: 'hinh_thuc',\\n      width: 120,\\n      render: (val) => hinhThucMap[val] || val || '-'\\n    },\\n    {\\n      title: 'Thời lượng',\\n      dataIndex: 'thoi_luong_gio',\\n      width: 100,\\n      align: 'center',\\n      render: (val) => val ? `${val} giờ` : '-'\\n    },\\n    {\\n      title: 'Bài học',\\n      dataIndex: 'chuong_hoc',\\n      width: 90,\\n      align: 'center',\\n      render: (arr) => {\\n        const count = Array.isArray(arr) ? arr.filter(c => !c.is_deleted).length : 0;\\n        return <Badge count={count} showZero style={{ backgroundColor: count > 0 ? '#1890ff' : '#d9d9d9' }} />;\\n      }\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      width: 130,\\n      render: (val) => {\\n        const s = statusMap[val] || { color: 'default', label: val || '-' };\\n        return <Tag color={s.color}>{s.label}</Tag>;\\n      }\\n    },\\n    {\\n      title: 'Ngày BĐ',\\n      dataIndex: 'ngay_bat_dau',\\n      width: 110,\\n      render: (val) => val ? dayjs(val).format('DD/MM/YYYY') : '-'\\n    },\\n    {\\n      title: 'Ngày KT',\\n      dataIndex: 'ngay_ket_thuc',\\n      width: 110,\\n      render: (val) => val ? dayjs(val).format('DD/MM/YYYY') : '-'\\n    },\\n    {\\n      title: 'Thao tác',\\n      width: 200,\\n      fixed: 'right',\\n      render: (_, record) => (\\n        <Space size={4}>\\n          <Tooltip title=\\"Xem\\">\\n            <Button icon={<EyeOutlined />} onClick={() => { setDetailRecord(record); setDetailOpen(true); }} />\\n          </Tooltip>\\n          <Tooltip title=\\"Sửa\\">\\n            <Button icon={<EditOutlined />} onClick={() => openEdit(record)} />\\n          </Tooltip>\\n          {(!record.trang_thai || record.trang_thai === 'nhap' || record.trang_thai === 'tu_choi') && (\\n            <Tooltip title=\\"Gửi duyệt\\">\\n              <Button icon={<SendOutlined />} onClick={() => handleSendApproval(record)} />\\n            </Tooltip>\\n          )}\\n          {record.trang_thai === 'cho_phe_duyet' && (\\n            <Popconfirm title=\\"Phê duyệt khóa này?\\" onConfirm={() => handleApprove(record)} okText=\\"Phê duyệt\\" cancelText=\\"Huỷ\\">\\n              <Tooltip title=\\"Phê duyệt\\">\\n                <Button style={{ color: '#52c41a', borderColor: '#52c41a' }} icon={<CheckCircleOutlined />} />\\n              </Tooltip>\\n            </Popconfirm>\\n          )}\\n          <Popconfirm title=\\"Xoá khóa huấn luyện này?\\" onConfirm={() => handleDelete(record)} okText=\\"Xoá\\" cancelText=\\"Huỷ\\">\\n            <Tooltip title=\\"Xoá\\">\\n              <Button danger icon={<DeleteOutlined />} />\\n            </Tooltip>\\n          </Popconfirm>\\n        </Space>\\n      )\\n    }\\n  ], [openEdit, handleDelete, handleSendApproval, handleApprove]);\\n\\n  return (\\n    <div style={{ padding: '0 4px' }}>\\n      <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n        <Row gutter={[12, 12]} align=\\"middle\\">\\n          <Col flex=\\"auto\\">\\n            <Space wrap size={8}>\\n              <Input\\n                placeholder=\\"Tìm tên khóa...\\"\\n                prefix={<SearchOutlined />}\\n                value={search}\\n                onChange={e => setSearch(e.target.value)}\\n                onPressEnter={handleSearch}\\n                style={{ width: 220 }}\\n                allowClear\\n              />\\n              <Select\\n                placeholder=\\"Trạng thái\\"\\n                value={filterStatus}\\n                onChange={setFilterStatus}\\n                allowClear\\n                style={{ width: 150 }}\\n                options={Object.entries(statusMap).map(([k, v]) => ({ label: v.label, value: k }))}\\n              />\\n              <Select\\n                placeholder=\\"Hình thức\\"\\n                value={filterForm}\\n                onChange={setFilterForm}\\n                allowClear\\n                style={{ width: 140 }}\\n                options={Object.entries(hinhThucMap).map(([k, v]) => ({ label: v, value: k }))}\\n              />\\n              <Button icon={<SearchOutlined />} type=\\"primary\\" onClick={handleSearch}>Tìm kiếm</Button>\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Tooltip title=\\"Tải lại\\"><Button icon={<ReloadOutlined />} onClick={() => loadData()} /></Tooltip>\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={openCreate}>Tạo khóa mới</Button>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Table\\n        rowKey=\\"id\\"\\n        columns={columns}\\n        dataSource={data}\\n        loading={loading}\\n        size=\\"middle\\"\\n        scroll={{ x: 1200 }}\\n        pagination={{\\n          current: meta.page || 1,\\n          pageSize: meta.pageSize || 15,\\n          total: meta.count || 0,\\n          showTotal: (total) => `Tổng ${total} khóa`,\\n          showSizeChanger: true,\\n          onChange: (page, pageSize) => { resource.setPageSize(pageSize); loadData(page); }\\n        }}\\n      />\\n\\n      <Modal\\n        title={editRecord ? 'Sửa khóa huấn luyện' : 'Tạo khóa huấn luyện mới'}\\n        open={modalOpen}\\n        onCancel={() => { setModalOpen(false); setSelectedBaiHoc([]); }}\\n        onOk={handleSave}\\n        confirmLoading={saving}\\n        okText={editRecord ? 'Cập nhật' : 'Tạo'}\\n        cancelText=\\"Huỷ\\"\\n        width={750}\\n        destroyOnClose\\n      >\\n        <Form form={form} layout=\\"vertical\\" style={{ marginTop: 16 }}>\\n          <Row gutter={16}>\\n            <Col span={8}>\\n              <Form.Item name=\\"ma_khoa_hoc\\" label=\\"Mã khóa\\">\\n                <Input placeholder=\\"Mã khóa (tự tạo)\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={16}>\\n              <Form.Item name=\\"ten_khoa_hoc\\" label=\\"Tên khóa huấn luyện\\" rules={[{ required: true, message: 'Nhập tên khóa' }]}>\\n                <Input placeholder=\\"Nhập tên khóa huấn luyện\\" />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={8}>\\n              <Form.Item name=\\"hinh_thuc\\" label=\\"Hình thức\\" rules={[{ required: true, message: 'Chọn hình thức' }]}>\\n                <Select placeholder=\\"Chọn\\" options={Object.entries(hinhThucMap).map(([k, v]) => ({ label: v, value: k }))} />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"thoi_luong_gio\\" label=\\"Thời lượng (giờ)\\">\\n                <InputNumber min={0} style={{ width: '100%' }} placeholder=\\"Giờ\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"doi_tuong\\" label=\\"Đối tượng\\">\\n                <Input placeholder=\\"Đối tượng huấn luyện\\" />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={12}>\\n              <Form.Item name=\\"nganh_nghe\\" label=\\"Ngành nghề áp dụng\\">\\n                <Select mode=\\"multiple\\" placeholder=\\"Chọn ngành nghề\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={nganhNgheList.map(nn => ({ label: nn.ten_nganh || nn.ten_nganh_nghe, value: nn.id }))}\\n                />\\n              </Form.Item>\\n            </Col>\\n            <Col span={12}>\\n              <Form.Item name=\\"bac_tho\\" label=\\"Bậc thợ áp dụng\\">\\n                <Select mode=\\"multiple\\" placeholder=\\"Chọn bậc thợ\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={bacThoList.map(bt => ({ label: bt.ten_bac || bt.ten_bac_tho, value: bt.id }))}\\n                />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={8}>\\n              <Form.Item name=\\"ngay_bat_dau\\" label=\\"Ngày bắt đầu\\">\\n                <DatePicker style={{ width: '100%' }} format=\\"DD/MM/YYYY\\" placeholder=\\"Chọn ngày\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"ngay_ket_thuc\\" label=\\"Ngày kết thúc\\">\\n                <DatePicker style={{ width: '100%' }} format=\\"DD/MM/YYYY\\" placeholder=\\"Chọn ngày\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"giang_vien\\" label=\\"Giảng viên\\">\\n                <Input placeholder=\\"Tên giảng viên\\" />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\">\\n            <Input.TextArea rows={3} placeholder=\\"Mô tả khóa huấn luyện...\\" />\\n          </Form.Item>\\n          <Divider style={{ margin: '8px 0' }} />\\n          <div style={{ marginBottom: 8 }}>\\n            <Row justify=\\"space-between\\" align=\\"middle\\">\\n              <Col><Typography.Text strong><BookOutlined /> Bài học trong khóa ({selectedBaiHoc.length})</Typography.Text></Col>\\n              <Col><Button icon={<PlusOutlined />} onClick={() => { setBaiHocSearch(''); setBaiHocPickerOpen(true); }}>Chọn bài học</Button></Col>\\n            </Row>\\n          </div>\\n          {selectedBaiHocNames.length > 0 ? (\\n            <Table\\n              rowKey=\\"id\\" size=\\"small\\" pagination={false}\\n              dataSource={selectedBaiHocNames}\\n              columns={[\\n                { title: 'Mã', dataIndex: 'ma_chuong', width: 100, render: v => v || '-' },\\n                { title: 'Tên bài học', dataIndex: 'ten_chuong' },\\n                { title: '', width: 40, render: (_, r) => <Button danger icon={<DeleteOutlined />} onClick={() => setSelectedBaiHoc(prev => prev.filter(id => id !== r.id))} /> }\\n              ]}\\n            />\\n          ) : <Empty description=\\"Chưa chọn bài học\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />}\\n        </Form>\\n      </Modal>\\n\\n      <Modal\\n        title=\\"Chọn bài học\\"\\n        open={baiHocPickerOpen}\\n        onCancel={() => setBaiHocPickerOpen(false)}\\n        onOk={() => setBaiHocPickerOpen(false)}\\n        okText=\\"Xong\\"\\n        cancelText=\\"Huỷ\\"\\n        width={700}\\n        destroyOnClose\\n      >\\n        <Input placeholder=\\"Tìm bài học...\\" prefix={<SearchOutlined />} value={baiHocSearch} onChange={e => setBaiHocSearch(e.target.value)} style={{ marginBottom: 12 }} allowClear />\\n        <Table\\n          rowKey=\\"id\\" size=\\"small\\" pagination={{ pageSize: 10 }}\\n          dataSource={filteredBaiHocForPicker}\\n          rowSelection={{\\n            selectedRowKeys: selectedBaiHoc,\\n            onChange: (keys) => setSelectedBaiHoc(keys),\\n          }}\\n          columns={[\\n            { title: 'Mã', dataIndex: 'ma_chuong', width: 100, render: v => v || '-' },\\n            { title: 'Tên bài học', dataIndex: 'ten_chuong' },\\n            { title: 'Trạng thái', dataIndex: 'trang_thai', width: 120, render: v => v === 'hoat_dong' ? <Tag color=\\"success\\">Hoạt động</Tag> : <Tag>{v || '-'}</Tag> }\\n          ]}\\n        />\\n      </Modal>\\n\\n      <Modal\\n        title={detailRecord ? `Khóa: ${detailRecord.ten_khoa_hoc}` : 'Chi tiết khóa'}\\n        open={detailOpen}\\n        onCancel={() => { setDetailOpen(false); setDetailRecord(null); }}\\n        footer={null}\\n        width={800}\\n        destroyOnClose\\n      >\\n        {detailRecord && (\\n          <div>\\n            <Descriptions bordered size=\\"small\\" column={2} style={{ marginBottom: 16 }}>\\n              <Descriptions.Item label=\\"Mã khóa\\">{detailRecord.ma_khoa_hoc || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Trạng thái\\"><Tag color={(statusMap[detailRecord.trang_thai] || {}).color}>{(statusMap[detailRecord.trang_thai] || {}).label || detailRecord.trang_thai || '-'}</Tag></Descriptions.Item>\\n              <Descriptions.Item label=\\"Hình thức\\">{hinhThucMap[detailRecord.hinh_thuc] || detailRecord.hinh_thuc || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Thời lượng\\">{detailRecord.thoi_luong_gio ? `${detailRecord.thoi_luong_gio} giờ` : '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Ngày bắt đầu\\">{detailRecord.ngay_bat_dau ? dayjs(detailRecord.ngay_bat_dau).format('DD/MM/YYYY') : '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Ngày kết thúc\\">{detailRecord.ngay_ket_thuc ? dayjs(detailRecord.ngay_ket_thuc).format('DD/MM/YYYY') : '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Đối tượng\\">{detailRecord.doi_tuong || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Giảng viên\\">{detailRecord.giang_vien || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Mô tả\\" span={2}>{detailRecord.mo_ta || '-'}</Descriptions.Item>\\n            </Descriptions>\\n\\n            <Row gutter={16} style={{ marginBottom: 12 }}>\\n              <Col span={12}>\\n                <Typography.Text type=\\"secondary\\">Ngành nghề: </Typography.Text>\\n                {(detailRecord.nganh_nghe || []).map(nn => <Tag key={nn.id}>{nn.ten_nganh || nn.ten_nganh_nghe}</Tag>)}\\n                {!(detailRecord.nganh_nghe || []).length && <Typography.Text>-</Typography.Text>}\\n              </Col>\\n              <Col span={12}>\\n                <Typography.Text type=\\"secondary\\">Bậc thợ: </Typography.Text>\\n                {(detailRecord.bac_tho || []).map(bt => <Tag key={bt.id}>{bt.ten_bac || bt.ten_bac_tho}</Tag>)}\\n                {!(detailRecord.bac_tho || []).length && <Typography.Text>-</Typography.Text>}\\n              </Col>\\n            </Row>\\n\\n            <Divider style={{ margin: '8px 0' }} />\\n\\n            <Typography.Title level={5} style={{ marginBottom: 8 }}><BookOutlined /> Danh sách bài học ({(detailRecord.chuong_hoc || []).filter(c => !c.is_deleted).length})</Typography.Title>\\n            {(detailRecord.chuong_hoc || []).filter(c => !c.is_deleted).length > 0 ? (\\n              <List\\n                size=\\"small\\"\\n                bordered\\n                dataSource={(detailRecord.chuong_hoc || []).filter(c => !c.is_deleted).sort((a, b) => (a.thu_tu || 0) - (b.thu_tu || 0))}\\n                renderItem={(ch, idx) => (\\n                  <List.Item>\\n                    <Space>\\n                      <Badge count={idx + 1} style={{ backgroundColor: '#1890ff' }} />\\n                      <Typography.Text strong>{ch.ten_chuong}</Typography.Text>\\n                      {ch.ma_chuong && <Typography.Text type=\\"secondary\\">({ch.ma_chuong})</Typography.Text>}\\n                    </Space>\\n                  </List.Item>\\n                )}\\n              />\\n            ) : <Empty description=\\"Chưa có bài học\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />}\\n          </div>\\n        )}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);"}},"__flowSurfaceMeta":{"declaredKey":"tab_1.jsBlock_1"}}}
o8dr8u9sr2s	o8dr8u9sr2s	{"use":"FormGridModel","subKey":"grid","subType":"object","stepParams":{"gridSettings":{"grid":{"layout":{"version":2,"rows":[{"id":"row1","cells":[{"id":"row1:cell:0","items":["afjgpfu8wf7"]}],"sizes":[24]},{"id":"row2","cells":[{"id":"row2:cell:1","items":["zud6uope3xs"]},{"id":"pae059ik737","items":["j1tbducvqyw"]}],"sizes":[12,12]},{"id":"row3","cells":[{"id":"8m5f94g5z5c","items":["ohimudknwto"]},{"id":"row3:cell:1","items":["ikzckngvh7z"]}],"sizes":[12,12]},{"id":"row4","cells":[{"id":"row4:cell:1:uicsxz8ye0h","items":["EMPTY_COLUMN"]}],"sizes":[24]},{"id":"row5","cells":[{"id":"row5:cell:0","items":["vxp499of2xu"]}],"sizes":[24]},{"id":"row6","cells":[{"id":"row6:cell:0","items":["c1ejbuhoqcw"]}],"sizes":[24]},{"id":"row7","cells":[{"id":"row7:cell:0","items":["ecm94o1aw7o"]}],"sizes":[24]},{"id":"row8","cells":[{"id":"row8:cell:0","items":["er3xb35lqan"]},{"id":"row8:cell:1","items":["1o5kundc99b"]}],"sizes":[12,12]},{"id":"row9","cells":[{"id":"row9:cell:0","items":["k1mxrj2f6a0"]}],"sizes":[24]},{"id":"row10","cells":[{"id":"row10:cell:0","items":["klt6rkes4ps"]},{"id":"row10:cell:1","items":["5mb3xgw2mw9"]}],"sizes":[12,12]},{"id":"row11","cells":[{"id":"row11:cell:0","items":["aynn8ld3hmr"]}],"sizes":[24]},{"id":"row12","cells":[{"id":"row12:cell:0","items":["8smg4jx852t"]},{"id":"row12:cell:1","items":["vldbsw8t51k"]}],"sizes":[12,12]}]}}},"eventSettings":{"linkageRules":{"value":[]}}},"props":{"rows":{"row1":[["afjgpfu8wf7"]],"row2":[["zud6uope3xs"],["j1tbducvqyw"]],"row3":[["ohimudknwto"],["ikzckngvh7z"]],"row4":[["EMPTY_COLUMN"]],"row5":[["vxp499of2xu"]],"row6":[["c1ejbuhoqcw"]],"row7":[["ecm94o1aw7o"]],"row8":[["er3xb35lqan"],["1o5kundc99b"]],"row9":[["k1mxrj2f6a0"]],"row10":[["klt6rkes4ps"],["5mb3xgw2mw9"]],"row11":[["aynn8ld3hmr"]],"row12":[["8smg4jx852t"],["vldbsw8t51k"]]},"sizes":{"row1":[24],"row2":[12,12],"row3":[12,12],"row4":[24],"row5":[24],"row6":[24],"row7":[24],"row8":[12,12],"row9":[24],"row10":[12,12],"row11":[2