wecprvx8v18	wecprvx8v18	{"parentId":"9oyp28g4twa","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"12","code":"const { useState, useEffect, useCallback, useMemo } = ctx.libs.React;\\nconst { Table, Button, Input, Select, Space, Tag, Modal, Form, Tooltip, Popconfirm, Typography, Card, Row, Col, InputNumber, List, Empty, Badge, Descriptions, Divider } = ctx.libs.antd;\\nconst { SearchOutlined, PlusOutlined, DeleteOutlined, EyeOutlined, ReloadOutlined, EditOutlined, FileTextOutlined, SendOutlined, CheckCircleOutlined } = ctx.libs.antdIcons;\\nconst dayjs = ctx.libs.dayjs;\\n\\nctx.initResource('MultiRecordResource');\\nconst resource = ctx.resource;\\nresource.setResourceName('chuong_hoc');\\nresource.setAppends(['khoa_huan_luyen', 'tai_lieu_chuong_hoc', 'tai_lieu_chuong_hoc.phien_ban_tai_lieu', 'tai_lieu_chuong_hoc.phien_ban_tai_lieu.tai_lieu']);\\nresource.setSort(['-createdAt']);\\nresource.setPageSize(15);\\n\\nconst courseRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\ncourseRes?.setResourceName('khoa_huan_luyen');\\ncourseRes?.setFilter({ is_deleted: { $ne: true } });\\ncourseRes?.setPageSize(200);\\n\\nconst taiLieuRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\ntaiLieuRes?.setResourceName('tai_lieu_huan_luyen');\\ntaiLieuRes?.setFilter({ is_deleted: { $ne: true } });\\ntaiLieuRes?.setAppends(['phien_ban']);\\ntaiLieuRes?.setPageSize(200);\\n\\nconst statusMap = {\\n  nhap: { color: 'default', label: 'Bản nháp' },\\n  cho_phe_duyet: { color: 'processing', label: 'Chờ phê duyệt' },\\n  da_phe_duyet: { color: 'success', label: 'Đã phê duyệt' },\\n  tu_choi: { color: 'error', label: 'Từ chối' },\\n  hoat_dong: { color: 'success', label: 'Hoạt động' },\\n  ngung_hoat_dong: { color: 'default', label: 'Ngừng hoạt động' }\\n};\\n\\nconst loaiTaiLieuMap = {\\n  van_ban: 'Văn bản', video: 'Video', hinh_anh: 'Hình ảnh', quy_dinh: 'Quy định',\\n  tai_lieu_dien_tu: 'Tài liệu điện tử', giao_trinh: 'Giáo trình', bai_giang: 'Bài giảng', khac: 'Khác'\\n};\\n\\nfunction App() {\\n  const [loading, setLoading] = useState(true);\\n  const [data, setData] = useState([]);\\n  const [meta, setMeta] = useState({});\\n  const [search, setSearch] = useState('');\\n  const [modalOpen, setModalOpen] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [detailOpen, setDetailOpen] = useState(false);\\n  const [detailRecord, setDetailRecord] = useState(null);\\n  const [saving, setSaving] = useState(false);\\n  const [courses, setCourses] = useState([]);\\n  const [allTaiLieu, setAllTaiLieu] = useState([]);\\n  const [selectedTaiLieu, setSelectedTaiLieu] = useState([]);\\n  const [taiLieuPickerOpen, setTaiLieuPickerOpen] = useState(false);\\n  const [taiLieuSearch, setTaiLieuSearch] = useState('');\\n  const [form] = Form.useForm();\\n\\n  const loadCourses = useCallback(async () => {\\n    try {\\n      if (courseRes) { await courseRes.refresh(); setCourses(courseRes.getData() || []); }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadTaiLieu = useCallback(async () => {\\n    try {\\n      if (taiLieuRes) { await taiLieuRes.refresh(); setAllTaiLieu(taiLieuRes.getData() || []); }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadData = useCallback(async (page) => {\\n    setLoading(true);\\n    try {\\n      const filter = { is_deleted: { $ne: true } };\\n      if (search) filter.ten_chuong = { $includes: search };\\n      resource.setFilter(filter);\\n      if (page) resource.setPage(page);\\n      await resource.refresh();\\n      setData(resource.getData() || []);\\n      setMeta(resource.getMeta() || {});\\n    } catch (e) {\\n      ctx.message.error('Lỗi tải dữ liệu');\\n    }\\n    setLoading(false);\\n  }, [search]);\\n\\n  useEffect(() => { loadData(1); loadCourses(); loadTaiLieu(); }, []);\\n\\n  const handleSearch = useCallback(() => { loadData(1); }, [loadData]);\\n\\n  const openCreate = useCallback(() => {\\n    setEditRecord(null);\\n    setSelectedTaiLieu([]);\\n    form.resetFields();\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const openEdit = useCallback((record) => {\\n    setEditRecord(record);\\n    const existingTaiLieuIds = (record.tai_lieu_chuong_hoc || [])\\n      .filter(t => !t.is_deleted && t.phien_ban_tai_lieu?.tai_lieu)\\n      .map(t => t.phien_ban_tai_lieu.tai_lieu.id);\\n    const uniqueIds = [...new Set(existingTaiLieuIds)];\\n    setSelectedTaiLieu(uniqueIds);\\n    form.setFieldsValue({\\n      ten_chuong: record.ten_chuong,\\n      ma_chuong: record.ma_chuong,\\n      thu_tu: record.thu_tu,\\n      mo_ta: record.mo_ta,\\n      trang_thai: record.trang_thai,\\n      khoaHuanLuyenId: record.khoaHuanLuyenId\\n    });\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const findCurrentPhienBan = useCallback((taiLieu) => {\\n    const versions = taiLieu.phien_ban || [];\\n    const current = versions.find(v => v.la_phien_ban_hien_tai);\\n    if (current) return current.id;\\n    if (versions.length > 0) {\\n      const sorted = [...versions].sort((a, b) => (b.id || 0) - (a.id || 0));\\n      return sorted[0].id;\\n    }\\n    return null;\\n  }, []);\\n\\n  const handleSave = useCallback(async () => {\\n    try {\\n      const values = await form.validateFields();\\n      setSaving(true);\\n      const taiLieuEntries = [];\\n      for (const tlId of selectedTaiLieu) {\\n        const tl = allTaiLieu.find(t => t.id === tlId);\\n        if (tl) {\\n          const pbId = findCurrentPhienBan(tl);\\n          if (pbId) {\\n            taiLieuEntries.push({ phienBanTaiLieuId: pbId });\\n          }\\n        }\\n      }\\n      const payload = { ...values };\\n      payload.tai_lieu_chuong_hoc = taiLieuEntries;\\n      if (editRecord) {\\n        payload.trang_thai = 'nhap';\\n        await resource.update(editRecord.id, payload);\\n        ctx.message.success('Cập nhật bài học thành công, trạng thái đã chuyển về Bản nháp');\\n      } else {\\n        await resource.create({ ...payload, trang_thai: values.trang_thai || 'nhap', is_deleted: false });\\n        ctx.message.success('Tạo bài học thành công');\\n      }\\n      setModalOpen(false);\\n      form.resetFields();\\n      setSelectedTaiLieu([]);\\n      loadData();\\n      loadTaiLieu();\\n    } catch (e) {\\n      if (e.errorFields) { setSaving(false); return; }\\n      ctx.message.error('Lỗi lưu: ' + (e.message || ''));\\n    }\\n    setSaving(false);\\n  }, [form, editRecord, loadData, loadTaiLieu, selectedTaiLieu, allTaiLieu, findCurrentPhienBan]);\\n\\n  const handleDelete = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { is_deleted: true });\\n      ctx.message.success('Đã xoá: ' + record.ten_chuong);\\n      loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi xoá');\\n    }\\n  }, [loadData]);\\n\\n  const handleSendApproval = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'cho_phe_duyet' });\\n      ctx.message.success('Đã gửi duyệt bài học: ' + record.ten_chuong);\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi gửi duyệt'); }\\n  }, [loadData]);\\n\\n  const handleApprove = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { trang_thai: 'da_phe_duyet' });\\n      ctx.message.success('Đã phê duyệt bài học: ' + record.ten_chuong);\\n      loadData();\\n    } catch (e) { ctx.message.error('Lỗi phê duyệt'); }\\n  }, [loadData]);\\n\\n  const filteredTaiLieuForPicker = useMemo(() => {\\n    let list = allTaiLieu;\\n    if (taiLieuSearch) {\\n      const s = taiLieuSearch.toLowerCase();\\n      list = list.filter(tl => (tl.ten_tai_lieu || '').toLowerCase().includes(s) || (tl.ma_tai_lieu || '').toLowerCase().includes(s));\\n    }\\n    return list;\\n  }, [allTaiLieu, taiLieuSearch]);\\n\\n  const selectedTaiLieuNames = useMemo(() => {\\n    return allTaiLieu.filter(tl => selectedTaiLieu.includes(tl.id));\\n  }, [allTaiLieu, selectedTaiLieu]);\\n\\n  const columns = useMemo(() => [\\n    {\\n      title: 'TT',\\n      dataIndex: 'thu_tu',\\n      width: 60,\\n      align: 'center',\\n      sorter: (a, b) => (a.thu_tu || 0) - (b.thu_tu || 0),\\n      render: (val) => val || '-'\\n    },\\n    {\\n      title: 'Mã bài học',\\n      dataIndex: 'ma_chuong',\\n      width: 120,\\n      ellipsis: true\\n    },\\n    {\\n      title: 'Tên bài học',\\n      dataIndex: 'ten_chuong',\\n      ellipsis: true,\\n      render: (text, record) => (\\n        <Typography.Link onClick={() => { setDetailRecord(record); setDetailOpen(true); }}>\\n          {text}\\n        </Typography.Link>\\n      )\\n    },\\n    {\\n      title: 'Khóa huấn luyện',\\n      dataIndex: ['khoa_huan_luyen', 'ten_khoa_hoc'],\\n      width: 200,\\n      ellipsis: true,\\n      render: (val) => val || <Typography.Text type=\\"secondary\\">Chưa gắn</Typography.Text>\\n    },\\n    {\\n      title: 'Tài liệu',\\n      dataIndex: 'tai_lieu_chuong_hoc',\\n      width: 90,\\n      align: 'center',\\n      render: (arr) => {\\n        const count = Array.isArray(arr) ? arr.filter(t => !t.is_deleted).length : 0;\\n        return <Badge count={count} showZero style={{ backgroundColor: count > 0 ? '#1890ff' : '#d9d9d9' }} />;\\n      }\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      width: 130,\\n      render: (val) => {\\n        const s = statusMap[val] || { color: 'default', label: val || '-' };\\n        return <Tag color={s.color}>{s.label}</Tag>;\\n      }\\n    },\\n    {\\n      title: 'Ngày tạo',\\n      dataIndex: 'createdAt',\\n      width: 110,\\n      render: (val) => val ? dayjs(val).format('DD/MM/YYYY') : '-'\\n    },\\n    {\\n      title: 'Thao tác',\\n      width: 200,\\n      fixed: 'right',\\n      render: (_, record) => (\\n        <Space size={4}>\\n          <Tooltip title=\\"Xem\\"><Button icon={<EyeOutlined />} onClick={() => { setDetailRecord(record); setDetailOpen(true); }} /></Tooltip>\\n          <Tooltip title=\\"Sửa\\"><Button icon={<EditOutlined />} onClick={() => openEdit(record)} /></Tooltip>\\n          {(!record.trang_thai || record.trang_thai === 'nhap' || record.trang_thai === 'tu_choi') && (\\n            <Tooltip title=\\"Gửi duyệt\\"><Button icon={<SendOutlined />} onClick={() => handleSendApproval(record)} /></Tooltip>\\n          )}\\n          {record.trang_thai === 'cho_phe_duyet' && (\\n            <Popconfirm title=\\"Phê duyệt bài học này?\\" onConfirm={() => handleApprove(record)} okText=\\"Phê duyệt\\" cancelText=\\"Huỷ\\">\\n              <Tooltip title=\\"Phê duyệt\\"><Button style={{ color: '#52c41a', borderColor: '#52c41a' }} icon={<CheckCircleOutlined />} /></Tooltip>\\n            </Popconfirm>\\n          )}\\n          <Popconfirm title=\\"Xoá bài học này?\\" onConfirm={() => handleDelete(record)} okText=\\"Xoá\\" cancelText=\\"Huỷ\\">\\n            <Tooltip title=\\"Xoá\\"><Button danger icon={<DeleteOutlined />} /></Tooltip>\\n          </Popconfirm>\\n        </Space>\\n      )\\n    }\\n  ], [openEdit, handleDelete, handleSendApproval, handleApprove]);\\n\\n  return (\\n    <div style={{ padding: '0 4px' }}>\\n      <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n        <Row gutter={[12, 12]} align=\\"middle\\">\\n          <Col flex=\\"auto\\">\\n            <Space wrap size={8}>\\n              <Input placeholder=\\"Tìm tên bài học...\\" prefix={<SearchOutlined />} value={search} onChange={e => setSearch(e.target.value)} onPressEnter={handleSearch} style={{ width: 240 }} allowClear />\\n              <Button icon={<SearchOutlined />} type=\\"primary\\" onClick={handleSearch}>Tìm kiếm</Button>\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Tooltip title=\\"Tải lại\\"><Button icon={<ReloadOutlined />} onClick={() => loadData()} /></Tooltip>\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={openCreate}>Thêm bài học</Button>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Table rowKey=\\"id\\" columns={columns} dataSource={data} loading={loading} size=\\"middle\\" scroll={{ x: 1000 }}\\n        pagination={{ current: meta.page || 1, pageSize: meta.pageSize || 15, total: meta.count || 0, showTotal: (t) => `Tổng ${t} bài học`, showSizeChanger: true, onChange: (p, ps) => { resource.setPageSize(ps); loadData(p); } }}\\n      />\\n\\n      <Modal title={editRecord ? 'Sửa bài học' : 'Thêm bài học mới'} open={modalOpen} onCancel={() => { setModalOpen(false); setSelectedTaiLieu([]); }} onOk={handleSave} confirmLoading={saving} okText={editRecord ? 'Cập nhật' : 'Tạo'} cancelText=\\"Huỷ\\" width={700} destroyOnClose>\\n        <Form form={form} layout=\\"vertical\\" style={{ marginTop: 16 }}>\\n          <Row gutter={16}>\\n            <Col span={16}>\\n              <Form.Item name=\\"ten_chuong\\" label=\\"Tên bài học\\" rules={[{ required: true, message: 'Nhập tên bài học' }]}>\\n                <Input placeholder=\\"Tên bài học\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"thu_tu\\" label=\\"Thứ tự\\">\\n                <InputNumber min={1} style={{ width: '100%' }} placeholder=\\"TT\\" />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={12}>\\n              <Form.Item name=\\"ma_chuong\\" label=\\"Mã bài học\\">\\n                <Input placeholder=\\"Mã bài học\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={12}>\\n              <Form.Item name=\\"khoaHuanLuyenId\\" label=\\"Thuộc khóa huấn luyện\\">\\n                <Select placeholder=\\"Chọn khóa\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={courses.map(c => ({ label: c.ten_khoa_hoc, value: c.id }))}\\n                />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả nội dung\\">\\n            <Input.TextArea rows={3} placeholder=\\"Mô tả nội dung bài học...\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"trang_thai\\" label=\\"Trạng thái\\">\\n            <Select placeholder=\\"Chọn\\" options={Object.entries(statusMap).map(([k, v]) => ({ label: v.label, value: k }))} />\\n          </Form.Item>\\n          <Divider style={{ margin: '8px 0' }} />\\n          <div style={{ marginBottom: 8 }}>\\n            <Row justify=\\"space-between\\" align=\\"middle\\">\\n              <Col><Typography.Text strong><FileTextOutlined /> Tài liệu gắn kèm ({selectedTaiLieu.length})</Typography.Text></Col>\\n              <Col><Button icon={<PlusOutlined />} onClick={() => { setTaiLieuSearch(''); setTaiLieuPickerOpen(true); }}>Chọn tài liệu</Button></Col>\\n            </Row>\\n          </div>\\n          {selectedTaiLieuNames.length > 0 ? (\\n            <Table\\n              rowKey=\\"id\\" size=\\"small\\" pagination={false}\\n              dataSource={selectedTaiLieuNames}\\n              columns={[\\n                { title: 'Mã', dataIndex: 'ma_tai_lieu', width: 120, render: v => v || '-' },\\n                { title: 'Tên tài liệu', dataIndex: 'ten_tai_lieu' },\\n                { title: 'Loại', dataIndex: 'loai_tai_lieu', width: 120, render: v => loaiTaiLieuMap[v] || v || '-' },\\n                { title: '', width: 40, render: (_, r) => <Button danger icon={<DeleteOutlined />} onClick={() => setSelectedTaiLieu(prev => prev.filter(id => id !== r.id))} /> }\\n              ]}\\n            />\\n          ) : <Empty description=\\"Chưa chọn tài liệu\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />}\\n        </Form>\\n      </Modal>\\n\\n      <Modal\\n        title=\\"Chọn tài liệu\\"\\n        open={taiLieuPickerOpen}\\n        onCancel={() => setTaiLieuPickerOpen(false)}\\n        onOk={() => setTaiLieuPickerOpen(false)}\\n        okText=\\"Xong\\"\\n        cancelText=\\"Huỷ\\"\\n        width={750}\\n        destroyOnClose\\n      >\\n        <Input placeholder=\\"Tìm tài liệu...\\" prefix={<SearchOutlined />} value={taiLieuSearch} onChange={e => setTaiLieuSearch(e.target.value)} style={{ marginBottom: 12 }} allowClear />\\n        <Table\\n          rowKey=\\"id\\" size=\\"small\\" pagination={{ pageSize: 10 }}\\n          dataSource={filteredTaiLieuForPicker}\\n          rowSelection={{\\n            selectedRowKeys: selectedTaiLieu,\\n            onChange: (keys) => setSelectedTaiLieu(keys),\\n          }}\\n          columns={[\\n            { title: 'Mã', dataIndex: 'ma_tai_lieu', width: 120, render: v => v || '-' },\\n            { title: 'Tên tài liệu', dataIndex: 'ten_tai_lieu' },\\n            { title: 'Loại', dataIndex: 'loai_tai_lieu', width: 120, render: v => loaiTaiLieuMap[v] || v || '-' },\\n            { title: 'Phiên bản', dataIndex: 'phien_ban_hien_tai', width: 90, render: v => v || '-' }\\n          ]}\\n        />\\n      </Modal>\\n\\n      <Modal title={detailRecord ? `Bài học: ${detailRecord.ten_chuong}` : 'Chi tiết'} open={detailOpen} onCancel={() => { setDetailOpen(false); setDetailRecord(null); }} footer={null} width={700} destroyOnClose>\\n        {detailRecord && (\\n          <div>\\n            <Descriptions bordered size=\\"small\\" column={2} style={{ marginBottom: 16 }}>\\n              <Descriptions.Item label=\\"Mã bài học\\">{detailRecord.ma_chuong || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Thứ tự\\">{detailRecord.thu_tu || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Khóa huấn luyện\\">{detailRecord.khoa_huan_luyen?.ten_khoa_hoc || '-'}</Descriptions.Item>\\n              <Descriptions.Item label=\\"Trạng thái\\"><Tag color={(statusMap[detailRecord.trang_thai] || {}).color}>{(statusMap[detailRecord.trang_thai] || {}).label || '-'}</Tag></Descriptions.Item>\\n              <Descriptions.Item label=\\"Mô tả\\" span={2}>{detailRecord.mo_ta || '-'}</Descriptions.Item>\\n            </Descriptions>\\n            <Typography.Title level={5}><FileTextOutlined /> Tài liệu gắn kèm ({(detailRecord.tai_lieu_chuong_hoc || []).filter(t => !t.is_deleted).length})</Typography.Title>\\n            {(detailRecord.tai_lieu_chuong_hoc || []).filter(t => !t.is_deleted).length > 0 ? (\\n              <List size=\\"small\\" bordered\\n                dataSource={(detailRecord.tai_lieu_chuong_hoc || []).filter(t => !t.is_deleted).sort((a, b) => (a.thu_tu || 0) - (b.thu_tu || 0))}\\n                renderItem={(tl, idx) => (\\n                  <List.Item>\\n                    <Space>\\n                      <Badge count={idx + 1} style={{ backgroundColor: '#52c41a' }} />\\n                      <Typography.Text strong>{tl.phien_ban_tai_lieu?.tai_lieu?.ten_tai_lieu || tl.phien_ban_tai_lieu?.tieu_de || 'Tài liệu'}</Typography.Text>\\n                      {tl.bat_buoc && <Tag color=\\"red\\">Bắt buộc</Tag>}\\n                      {tl.ghi_chu && <Typography.Text type=\\"secondary\\"> - {tl.ghi_chu}</Typography.Text>}\\n                    </Space>\\n                  </List.Item>\\n                )}\\n              />\\n            ) : <Empty description=\\"Chưa có tài liệu\\" image={Empty.PRESENTED_IMAGE_SIMPLE} />}\\n          </div>\\n        )}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);"}},"__flowSurfaceMeta":{"declaredKey":"tab_1.jsBlock_1"}}}
tu8tllqr1hx	tu8tllqr1hx	{"parentId":"a6uhzkju6ze","subKey":"page","subType":"object","use":"RootPageModel","props":{"routeId":379360006635520,"title":"Người dùng","enableTabs":true,"displayTitle":true,"icon":"UserSwitchOutlined","enableHeader":false,"headerStyle":{"backgroundColor":"var(--colorBgContainer)"},"tabBarStyle":{"backgroundColor":"var(--colorBgContainer)","marginBottom":0}},"stepParams":{"pageSettings":{"general":{"title":"Người dùng","displayTitle":true,"enableTabs":true,"icon":"UserSwitchOutlined","enableHeader":false,"documentTitle":"Người dùng"}}},"parent":"a6uhzkju6ze","sortIndex":0,"flowRegistry":{}}
hlwkavaz2cr	hlwkavaz2cr	{"use":"FormGridModel","subKey":"grid","subType":"object","stepParams":{"gridSettings":{"grid":{"rows":{"row1":[["fjld7rv7z7y"]],"row2":[["lw8l51ki92i"],["11ik7w5sdhk"]],"row3":[["n6et8fkj53d"],["c3usbgcwcmr"]],"row4":[["hrksdvos7jw"]],"row5":[["xt4vxo04fx4"]],"row6":[["1pz0k0xwe0y"]],"row7":[["uhzpemm7ftw"]],"row8":[["wl1c78ggx2b"],["bzskfs01tzh"]],"row9":[["au5ghk3g51d"]],"row10":[["waczreq3hju"],["67spxq9m0w4"]],"row11":[["qhh619g2hxd"]],"row12":[["au75f4hqtos"],["kjz1kc4wa4i"]]},"sizes":{"row1":[24],"row2":[12,12],"row3":[12,12],"row4":[24],"row5":[24],"row6":[24],"row7":[24],"row8":[12,12],"row9":[24],"row10":[12,12],"row11":[24],"row12":[12,12]},"rowOrder":["row1","row2","row3","row4","row5","row6","row7","row8","row9","row10","row11","row12"]}},"eventSettings":{"linkageRules":{"value":[]}}},"props":{"rows":{"row1":[["fjld7rv7z7y"]],"row2":[["lw8l51ki92i"],["11ik7w5sdhk"]],"row3":[["n6et8fkj53d"],["c3usbgcwcmr"]],"row4":[["hrksdvos7jw"]],"row5":[["xt4vxo04fx4"]],"row6":[["1pz0k0xwe0y"]],"row7":[["uhzpemm7ftw"]],"row8":[["wl1c78ggx2b"],["bzskfs01tzh"]],"row9":[["au5ghk3g51d"]],"row10":[["waczreq3hju"],["67spxq9m0w4"]],"row11":[["qhh619g2hxd"]],"row12":[["au75f4hqtos"],["kjz1kc4wa4i"]]},"sizes":{"row1":[24],"row2":[12,12],"row3":[12,12],"row4":[24],"row5":[24],"row6":[24],"row7":[24],"row8":[12,12],"row9":[24],"row10":[12,12],"row11":[24],"row12":[12,12]},"rowOrder":["row1","row2","row3","row4","row5","row6","row7","row8","row9","row10","row11","row12"]},"parent":"wkqasolespu","parentId":"wkqasolespu","sortIndex":1}
s2ezglrd9ps	s2ezglrd9ps	{"parentId":"8d6mbu8rj7p","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Lịch sử nâng bậc"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ============================================================\\n// JS Block: Lịch sử nâng bậc (B4)\\n// ============================================================\\n\\nconst {\\n  Table, Card, Button, Input, Select, Tag, Space, Row, Col,\\n  Tooltip, Statistic, Typography, Spin, Pagination,\\n  Descriptions, Empty,\\n} = ctx.libs.antd;\\n\\nconst {\\n  SearchOutlined, ReloadOutlined, EyeOutlined,\\n  DownloadOutlined, TrophyOutlined,\\n  ArrowUpOutlined, HistoryOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst { useState, useCallback, useMemo } = ctx.libs.React;\\nconst { Text } = Typography;\\n\\n// -- Data loading ---------------------------------------------\\nasync function fetchLichSu() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('lich_su_nang_bac');\\n  res.setAppends(['nguoi_lao_dong', 'nguoi_lao_dong.don_vi']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\n\\nvar initialData = await fetchLichSu();\\n\\n// -- Helpers --------------------------------------------------\\nfunction formatDate(d) {\\n  if (!d) return '—';\\n  var dt = new Date(d);\\n  var dd = String(dt.getDate()).padStart(2, '0');\\n  var mm = String(dt.getMonth() + 1).padStart(2, '0');\\n  return dd + '/' + mm + '/' + dt.getFullYear();\\n}\\n\\nfunction getBacLabel(bac) {\\n  if (!bac && bac !== 0) return '—';\\n  var bacNum = Number(bac);\\n  if (isNaN(bacNum)) return String(bac);\\n  return 'Bậc ' + bacNum + '/7';\\n}\\n\\n// ============================================================\\n// Main Component\\n// ============================================================\\nfunction LichSuNangBacBlock({ initData }) {\\n  const [allData, setAllData] = useState(initData);\\n  const [loading, setLoading] = useState(false);\\n  const [searchText, setSearchText] = useState('');\\n  const [page, setPage] = useState(1);\\n  const [selectedRecord, setSelectedRecord] = useState(null);\\n  var pageSize = 20;\\n\\n  var stats = useMemo(function() {\\n    var total = allData.length;\\n    var thisMonth = allData.filter(function(r) {\\n      var d = new Date(r.thoi_gian || r.createdAt);\\n      var now = new Date();\\n      return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();\\n    }).length;\\n    return { total: total, thisMonth: thisMonth };\\n  }, [allData]);\\n\\n  var filteredData = useMemo(function() {\\n    if (!searchText) return allData;\\n    var lower = searchText.toLowerCase();\\n    return allData.filter(function(r) {\\n      var nld = r.nguoi_lao_dong || {};\\n      return (nld.ho_ten && nld.ho_ten.toLowerCase().indexOf(lower) !== -1) ||\\n             (nld.so_giay_to && nld.so_giay_to.toLowerCase().indexOf(lower) !== -1);\\n    });\\n  }, [allData, searchText]);\\n\\n  var pagedData = filteredData.slice((page - 1) * pageSize, page * pageSize);\\n\\n  var columns = [\\n    {\\n      title: 'STT', width: 55, align: 'center',\\n      render: function(_, __, i) { return (page - 1) * pageSize + i + 1; },\\n    },\\n    {\\n      title: 'Họ tên', width: 180, ellipsis: true,\\n      render: function(_, r) {\\n        var nld = r.nguoi_lao_dong || {};\\n        return <a onClick={function() { setSelectedRecord(r); }}>{nld.ho_ten || '—'}</a>;\\n      },\\n    },\\n    {\\n      title: 'Số CCCD', width: 140,\\n      render: function(_, r) { return (r.nguoi_lao_dong || {}).so_giay_to || '—'; },\\n    },\\n    {\\n      title: 'Đơn vị', width: 160, ellipsis: true,\\n      render: function(_, r) {\\n        var nld = r.nguoi_lao_dong || {};\\n        return (nld.don_vi || {}).ten_don_vi || '—';\\n      },\\n    },\\n    {\\n      title: 'Bậc cũ', dataIndex: 'bac_cu', width: 100, align: 'center',\\n      render: function(v) { return getBacLabel(v); },\\n    },\\n    {\\n      title: '', width: 40, align: 'center',\\n      render: function() { return <ArrowUpOutlined style={{ color: '#52c41a' }} />; },\\n    },\\n    {\\n      title: 'Bậc mới', dataIndex: 'bac_moi', width: 100, align: 'center',\\n      render: function(v) {\\n        return <Text strong style={{ color: '#1890ff' }}>{getBacLabel(v)}</Text>;\\n      },\\n    },\\n    {\\n      title: 'Ngày nâng bậc', width: 120,\\n      render: function(_, r) { return formatDate(r.thoi_gian || r.createdAt); },\\n    },\\n    {\\n      title: 'Lý do', dataIndex: 'ly_do', ellipsis: true,\\n    },\\n    {\\n      title: 'Mã lượt thi', dataIndex: 'ma_luot_thi', width: 120,\\n    },\\n    {\\n      title: 'Thao tác', width: 80, fixed: 'right',\\n      render: function(_, r) {\\n        return (\\n          <Tooltip title=\\"Xem chi tiết\\">\\n            <Button type=\\"link\\" size=\\"small\\" icon={<EyeOutlined />}\\n              onClick={function() { setSelectedRecord(r); }} />\\n          </Tooltip>\\n        );\\n      },\\n    },\\n  ];\\n\\n  async function handleReload() {\\n    setLoading(true);\\n    var data = await fetchLichSu();\\n    setAllData(data);\\n    setLoading(false);\\n  }\\n\\n  if (selectedRecord) {\\n    var nld = selectedRecord.nguoi_lao_dong || {};\\n    var relatedHistory = allData.filter(function(r) {\\n      return r.nguoi_lao_dong_id === selectedRecord.nguoi_lao_dong_id;\\n    });\\n\\n    return (\\n      <div>\\n        <Button type=\\"link\\" icon={<HistoryOutlined />}\\n          onClick={function() { setSelectedRecord(null); }}\\n          style={{ marginBottom: 8, padding: 0 }}>\\n          Quay lại lịch sử\\n        </Button>\\n\\n        <Card bordered style={{ marginBottom: 16 }} title=\\"Thông tin người lao động\\">\\n          <Descriptions column={{ xs: 1, sm: 2, md: 3 }} size=\\"small\\" bordered>\\n            <Descriptions.Item label=\\"Họ tên\\">{nld.ho_ten || '—'}</Descriptions.Item>\\n            <Descriptions.Item label=\\"Số CCCD\\">{nld.so_giay_to || '—'}</Descriptions.Item>\\n            <Descriptions.Item label=\\"Đơn vị\\">{(nld.don_vi || {}).ten_don_vi || '—'}</Descriptions.Item>\\n          </Descriptions>\\n        </Card>\\n\\n        <Card bordered title=\\"Lịch sử nâng bậc\\">\\n          <Table rowKey=\\"id\\" dataSource={relatedHistory} pagination={false} size=\\"middle\\"\\n            columns={[\\n              {\\n                title: 'STT', width: 55, align: 'center',\\n                render: function(_, __, i) { return i + 1; },\\n              },\\n              {\\n                title: 'Bậc cũ', dataIndex: 'bac_cu', width: 100,\\n                render: function(v) { return getBacLabel(v); },\\n              },\\n              {\\n                title: 'Bậc mới', dataIndex: 'bac_moi', width: 100,\\n                render: function(v) {\\n                  return <Text strong style={{ color: '#1890ff' }}>{getBacLabel(v)}</Text>;\\n                },\\n              },\\n              {\\n                title: 'Ngày', width: 120,\\n                render: function(_, r) { return formatDate(r.thoi_gian || r.createdAt); },\\n              },\\n              { title: 'Lý do', dataIndex: 'ly_do' },\\n              { title: 'Người thực hiện', dataIndex: 'nguoi_thuc_hien', width: 140 },\\n              { title: 'Mã lượt thi', dataIndex: 'ma_luot_thi', width: 120 },\\n            ]} />\\n        </Card>\\n      </div>\\n    );\\n  }\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>\\n        <Col xs={12} sm={8}>\\n          <Card bordered>\\n            <Statistic title=\\"Tổng lượt nâng bậc\\" value={stats.total}\\n              prefix={<TrophyOutlined />} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={8}>\\n          <Card bordered>\\n            <Statistic title=\\"Tháng này\\" value={stats.thisMonth}\\n              valueStyle={{ color: '#52c41a' }}\\n              prefix={<ArrowUpOutlined />} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={8}>\\n          <Card bordered>\\n            <Statistic title=\\"Tổng bản ghi\\" value={filteredData.length}\\n              prefix={<HistoryOutlined />} />\\n          </Card>\\n        </Col>\\n      </Row>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Row gutter={16} align=\\"middle\\" justify=\\"space-between\\">\\n          <Col flex=\\"auto\\">\\n            <Input placeholder=\\"Tìm theo họ tên hoặc CCCD\\"\\n              prefix={<SearchOutlined />} allowClear style={{ width: 300 }}\\n              value={searchText}\\n              onChange={function(e) { setSearchText(e.target.value); setPage(1); }} />\\n          </Col>\\n          <Col>\\n            <Tooltip title=\\"Làm mới\\">\\n              <Button icon={<ReloadOutlined />} onClick={handleReload} />\\n            </Tooltip>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Card bordered>\\n        <Table rowKey=\\"id\\" columns={columns} dataSource={pagedData}\\n          pagination={false} scroll={{ x: 1200 }} size=\\"middle\\" />\\n        {filteredData.length > pageSize && (\\n          <div style={{ textAlign: 'right', marginTop: 16 }}>\\n            <Pagination current={page} total={filteredData.length}\\n              pageSize={pageSize} showSizeChanger={false}\\n              showTotal={function(t) { return 'Tổng: ' + t; }}\\n              onChange={function(p) { setPage(p); }} />\\n          </div>\\n        )}\\n      </Card>\\n    </Spin>\\n  );\\n}\\n\\n// -- Render ---------------------------------------------------\\nctx.render(<LichSuNangBacBlock initData={initialData} />);\\n"}},"__flowSurfaceMeta":{"declaredKey":"lichSuNangBacJsV1"}}}
