bckr18k6hju	bckr18k6hju	{"parentId":"gdjr557mrkl","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Quản lý nhóm quyền"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ============================================================\\n// JS Block: Quản lý nhóm quyền\\n// Collection: nhom_quyen\\n// ============================================================\\n\\nconst {\\n  Table, Card, Button, Input, Select, Tag, Space, Row, Col,\\n  Modal, Form, Drawer, Popconfirm, Tooltip, Statistic, Divider,\\n  Typography, Spin, Pagination, Badge,\\n} = ctx.libs.antd;\\n\\nconst {\\n  PlusOutlined, ReloadOutlined, SearchOutlined,\\n  EyeOutlined, EditOutlined, DeleteOutlined,\\n  TeamOutlined, CheckCircleOutlined, StopOutlined,\\n  CloseCircleOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst { useState, useMemo, useCallback } = ctx.libs.React;\\nconst { Title, Text } = Typography;\\n\\n// ── Top-level data loading (MUST be outside React) ──────────\\nasync function fetchNhomQuyen(filter) {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('nhom_quyen');\\n  if (filter) res.setFilter(filter);\\n  res.setAppends(['vai_tro']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\n\\nvar initialData = await fetchNhomQuyen();\\n\\n// ── React Component ─────────────────────────────────────────\\nfunction NhomQuyenBlock({ initData, reloadFn }) {\\n  // ── state ───────────────────────────────────────────────\\n  const [allData, setAllData] = useState(initData);\\n  const [loading, setLoading] = useState(false);\\n  const [page, setPage] = useState(1);\\n  const pageSize = 20;\\n\\n  const [searchText, setSearchText] = useState('');\\n  const [statusFilter, setStatusFilter] = useState(undefined);\\n\\n  const [viewOpen, setViewOpen] = useState(false);\\n  const [viewRecord, setViewRecord] = useState(null);\\n\\n  const [editOpen, setEditOpen] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [editLoading, setEditLoading] = useState(false);\\n\\n  const [addOpen, setAddOpen] = useState(false);\\n  const [addLoading, setAddLoading] = useState(false);\\n\\n  const [editForm] = Form.useForm();\\n  const [addForm] = Form.useForm();\\n\\n  var activeRows = useMemo(function() {\\n    return allData.filter(function(r) { return !r.is_deleted; });\\n  }, [allData]);\\n\\n  var stats = useMemo(function() {\\n    return {\\n      total: allData.length,\\n      active: allData.filter(function(r) { return r.trang_thai === 'active' && !r.is_deleted; }).length,\\n      inactive: allData.filter(function(r) { return r.trang_thai !== 'active' && !r.is_deleted; }).length,\\n      deleted: allData.filter(function(r) { return !!r.is_deleted; }).length,\\n    };\\n  }, [allData]);\\n\\n  var filteredData = useMemo(function() {\\n    var result = activeRows;\\n    if (searchText) {\\n      var s = searchText.toLowerCase();\\n      result = result.filter(function(r) {\\n        return (r.ma_nhom || '').toLowerCase().includes(s) ||\\n          (r.ten_nhom || '').toLowerCase().includes(s);\\n      });\\n    }\\n    if (statusFilter) {\\n      result = result.filter(function(r) { return r.trang_thai === statusFilter; });\\n    }\\n    return result;\\n  }, [activeRows, searchText, statusFilter]);\\n\\n  var data = useMemo(function() {\\n    var start = (page - 1) * pageSize;\\n    return filteredData.slice(start, start + pageSize);\\n  }, [filteredData, page]);\\n\\n  var total = filteredData.length;\\n\\n  // ── fetch data ──────────────────────────────────────────\\n  const fetchData = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await reloadFn();\\n      setAllData(newData);\\n    } catch (err) {\\n      ctx.message.error('Không thể tải dữ liệu nhóm quyền');\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [reloadFn]);\\n\\n  // ── handlers ────────────────────────────────────────────\\n  const handleView = (record) => {\\n    setViewRecord(record);\\n    setViewOpen(true);\\n  };\\n\\n  const handleEdit = (record) => {\\n    setEditRecord(record);\\n    editForm.setFieldsValue({\\n      ten_nhom: record.ten_nhom,\\n      mo_ta: record.mo_ta,\\n      trang_thai: record.trang_thai,\\n      pham_vi_du_lieu: record.pham_vi_du_lieu,\\n    });\\n    setEditOpen(true);\\n  };\\n\\n  const handleEditSubmit = async () => {\\n    try {\\n      const values = await editForm.validateFields();\\n      setEditLoading(true);\\n      await ctx.request({\\n        url: `nhom_quyen:update/${editRecord.id}`,\\n        method: 'post',\\n        data: values,\\n      });\\n      ctx.message.success('Cập nhật nhóm quyền thành công');\\n      setEditOpen(false);\\n      editForm.resetFields();\\n      fetchData();\\n    } catch (err) {\\n      if (err.errorFields) return; // validation only\\n      console.error(err);\\n      ctx.message.error('Cập nhật nhóm quyền thất bại');\\n    } finally {\\n      setEditLoading(false);\\n    }\\n  };\\n\\n  const handleAddSubmit = async () => {\\n    try {\\n      const values = await addForm.validateFields();\\n      setAddLoading(true);\\n      await ctx.request({\\n        url: 'nhom_quyen:create',\\n        method: 'post',\\n        data: { ...values, is_deleted: false },\\n      });\\n      ctx.message.success('Thêm nhóm quyền thành công');\\n      setAddOpen(false);\\n      addForm.resetFields();\\n      setPage(1);\\n      fetchData();\\n    } catch (err) {\\n      if (err.errorFields) return;\\n      console.error(err);\\n      ctx.message.error('Thêm nhóm quyền thất bại');\\n    } finally {\\n      setAddLoading(false);\\n    }\\n  };\\n\\n  const handleSoftDelete = async (record) => {\\n    try {\\n      await ctx.request({\\n        url: `nhom_quyen:update/${record.id}`,\\n        method: 'post',\\n        data: { is_deleted: true },\\n      });\\n      ctx.message.success('Đã xóa nhóm quyền');\\n      fetchData();\\n    } catch (err) {\\n      console.error(err);\\n      ctx.message.error('Xóa nhóm quyền thất bại');\\n    }\\n  };\\n\\n  // ── columns ─────────────────────────────────────────────\\n  const columns = [\\n    {\\n      title: 'Mã nhóm',\\n      dataIndex: 'ma_nhom',\\n      key: 'ma_nhom',\\n      width: 140,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'Tên nhóm quyền',\\n      dataIndex: 'ten_nhom',\\n      key: 'ten_nhom',\\n      width: 200,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'Mô tả',\\n      dataIndex: 'mo_ta',\\n      key: 'mo_ta',\\n      width: 220,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'Vai trò sử dụng',\\n      dataIndex: 'vai_tro',\\n      key: 'vai_tro',\\n      width: 220,\\n      render: (roles) => {\\n        if (!roles || !roles.length) return '-';\\n        return (\\n          <Space size={4} wrap>\\n            {roles.map((r) => (\\n              <Tag key={r.id} color=\\"blue\\">\\n                {r.ten_vai_tro}\\n              </Tag>\\n            ))}\\n          </Space>\\n        );\\n      },\\n    },\\n    {\\n      title: 'Phạm vi dữ liệu',\\n      dataIndex: 'pham_vi_du_lieu',\\n      key: 'pham_vi_du_lieu',\\n      width: 200,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      key: 'trang_thai',\\n      width: 140,\\n      render: (val) => {\\n        if (val === 'active') return <Tag color=\\"green\\">Đang sử dụng</Tag>;\\n        if (val === 'inactive') return <Tag color=\\"red\\">Ngừng sử dụng</Tag>;\\n        return <Tag>{val || '-'}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Thao tác',\\n      key: 'actions',\\n      fixed: 'right',\\n      width: 150,\\n      render: (_, record) => (\\n        <Space size={4}>\\n          <Tooltip title=\\"Xem chi tiết\\">\\n            <Button\\n              icon={<EyeOutlined />}\\n              size=\\"small\\"\\n              onClick={() => handleView(record)}\\n            />\\n          </Tooltip>\\n          <Tooltip title=\\"Chỉnh sửa\\">\\n            <Button\\n              icon={<EditOutlined />}\\n              size=\\"small\\"\\n              onClick={() => handleEdit(record)}\\n            />\\n          </Tooltip>\\n          <Popconfirm\\n            title=\\"Xóa nhóm quyền\\"\\n            description=\\"Bạn có chắc chắn muốn xóa nhóm quyền này?\\"\\n            onConfirm={() => handleSoftDelete(record)}\\n            okText=\\"Xóa\\"\\n            cancelText=\\"Hủy\\"\\n          >\\n            <Tooltip title=\\"Xóa\\">\\n              <Button\\n                icon={<DeleteOutlined />}\\n                size=\\"small\\"\\n                danger\\n              />\\n            </Tooltip>\\n          </Popconfirm>\\n        </Space>\\n      ),\\n    },\\n  ];\\n\\n  // ── render ──────────────────────────────────────────────\\n  return (\\n    <div style={{ padding: 24 }}>\\n      {/* ── Stats cards ──────────────────────────────── */}\\n      <Row gutter={16} style={{ marginBottom: 24 }}>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Tổng nhóm quyền\\"\\n              value={stats.total}\\n              prefix={<TeamOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Đang hoạt động\\"\\n              value={stats.active}\\n              valueStyle={{ color: '#52c41a' }}\\n              prefix={<CheckCircleOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Ngừng hoạt động\\"\\n              value={stats.inactive}\\n              valueStyle={{ color: '#ff4d4f' }}\\n              prefix={<StopOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Đã xóa\\"\\n              value={stats.deleted}\\n              valueStyle={{ color: '#999' }}\\n              prefix={<CloseCircleOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n      </Row>\\n\\n      {/* ── Search + Actions bar ─────────────────────── */}\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Row gutter={16} align=\\"middle\\" justify=\\"space-between\\">\\n          <Col flex=\\"auto\\">\\n            <Space size={12} wrap>\\n              <Input\\n                placeholder=\\"Tìm theo mã nhóm hoặc tên nhóm quyền\\"\\n                prefix={<SearchOutlined />}\\n                allowClear\\n                style={{ width: 320 }}\\n                value={searchText}\\n                onChange={(e) => {\\n                  setSearchText(e.target.value);\\n                  setPage(1);\\n                }}\\n                onPressEnter={fetchData}\\n              />\\n              <Select\\n                placeholder=\\"Trạng thái\\"\\n                allowClear\\n                style={{ width: 180 }}\\n                value={statusFilter}\\n                onChange={(val) => {\\n                  setStatusFilter(val);\\n                  setPage(1);\\n                }}\\n                options={[\\n                  { label: 'Đang sử dụng', value: 'active' },\\n                  { label: 'Ngừng sử dụng', value: 'inactive' },\\n                ]}\\n              />\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Button\\n                icon={<PlusOutlined />}\\n                type=\\"primary\\"\\n                onClick={() => {\\n                  addForm.resetFields();\\n                  addForm.setFieldsValue({ trang_thai: 'active' });\\n                  setAddOpen(true);\\n                }}\\n              >\\n                Thêm mới\\n              </Button>\\n              <Tooltip title=\\"Làm mới\\">\\n                <Button\\n                  icon={<ReloadOutlined />}\\n                  onClick={fetchData}\\n                />\\n              </Tooltip>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      {/* ── Data table ───────────────────────────────── */}\\n      <Card bordered>\\n        <Spin spinning={loading}>\\n          <Table\\n            rowKey=\\"id\\"\\n            columns={columns}\\n            dataSource={data}\\n            pagination={false}\\n            scroll={{ x: 1200 }}\\n            size=\\"middle\\"\\n            bordered\\n          />\\n          <div\\n            style={{\\n              display: 'flex',\\n              justifyContent: 'flex-end',\\n              marginTop: 16,\\n            }}\\n          >\\n            <Pagination\\n              current={page}\\n              pageSize={pageSize}\\n              total={total}\\n              showSizeChanger={false}\\n              showTotal={(t) => `Tổng ${t} bản ghi`}\\n              onChange={(p) => setPage(p)}\\n            />\\n          </div>\\n        </Spin>\\n      </Card>\\n\\n      {/* ── View Drawer ──────────────────────────────── */}\\n      <Drawer\\n        title=\\"Chi tiết nhóm quyền\\"\\n        width={560}\\n        open={viewOpen}\\n        onClose={() => setViewOpen(false)}\\n      >\\n        {viewRecord && (\\n          <div>\\n            <Divider orientation=\\"left\\" style={{ marginTop: 0 }}>\\n              Thông tin chung\\n            </Divider>\\n\\n            <Row gutter={[16, 16]}>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Mã nhóm</Text>\\n                <div><Text strong>{viewRecord.ma_nhom || '-'}</Text></div>\\n              </Col>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Tên nhóm quyền</Text>\\n                <div><Text strong>{viewRecord.ten_nhom || '-'}</Text></div>\\n              </Col>\\n              <Col span={24}>\\n                <Text type=\\"secondary\\">Mô tả</Text>\\n                <div><Text>{viewRecord.mo_ta || '-'}</Text></div>\\n              </Col>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Trạng thái</Text>\\n                <div>\\n                  {viewRecord.trang_thai === 'active' ? (\\n                    <Tag color=\\"green\\">Đang sử dụng</Tag>\\n                  ) : viewRecord.trang_thai === 'inactive' ? (\\n                    <Tag color=\\"red\\">Ngừng sử dụng</Tag>\\n                  ) : (\\n                    <Tag>{viewRecord.trang_thai || '-'}</Tag>\\n                  )}\\n                </div>\\n              </Col>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Đã xóa</Text>\\n                <div>\\n                  <Text>{viewRecord.is_deleted ? 'Có' : 'Không'}</Text>\\n                </div>\\n              </Col>\\n              <Col span={24}>\\n                <Text type=\\"secondary\\">Phạm vi dữ liệu</Text>\\n                <div><Text>{viewRecord.pham_vi_du_lieu || '-'}</Text></div>\\n              </Col>\\n              <Col span={24}>\\n                <Text type=\\"secondary\\">Vai trò sử dụng</Text>\\n                <div style={{ marginTop: 4 }}>\\n                  {viewRecord.vai_tro && viewRecord.vai_tro.length > 0 ? (\\n                    <Space size={4} wrap>\\n                      {viewRecord.vai_tro.map((r) => (\\n                        <Tag key={r.id} color=\\"blue\\">\\n                          {r.ten_vai_tro}\\n                        </Tag>\\n                      ))}\\n                    </Space>\\n                  ) : (\\n                    <Text>-</Text>\\n                  )}\\n                </div>\\n              </Col>\\n            </Row>\\n          </div>\\n        )}\\n      </Drawer>\\n\\n      {/* ── Edit Modal ───────────────────────────────── */}\\n      <Modal\\n        title=\\"Chỉnh sửa nhóm quyền\\"\\n        open={editOpen}\\n        onCancel={() => {\\n          setEditOpen(false);\\n          editForm.resetFields();\\n        }}\\n        onOk={handleEditSubmit}\\n        confirmLoading={editLoading}\\n        okText=\\"Lưu\\"\\n        cancelText=\\"Hủy\\"\\n        width={600}\\n        destroyOnClose\\n      >\\n        <Form\\n          form={editForm}\\n          layout=\\"vertical\\"\\n          style={{ marginTop: 16 }}\\n        >\\n          <Form.Item\\n            name=\\"ten_nhom\\"\\n            label=\\"Tên nhóm quyền\\"\\n            rules={[{ required: true, message: 'Vui lòng nhập tên nhóm quyền' }]}\\n          >\\n            <Input placeholder=\\"Nhập tên nhóm quyền\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập mô tả\\" />\\n          </Form.Item>\\n          <Form.Item\\n            name=\\"trang_thai\\"\\n            label=\\"Trạng thái\\"\\n            rules={[{ required: true, message: 'Vui lòng chọn trạng thái' }]}\\n          >\\n            <Select\\n              placeholder=\\"Chọn trạng thái\\"\\n              options={[\\n                { label: 'Đang sử dụng', value: 'active' },\\n                { label: 'Ngừng sử dụng', value: 'inactive' },\\n              ]}\\n            />\\n          </Form.Item>\\n          <Form.Item name=\\"pham_vi_du_lieu\\" label=\\"Phạm vi dữ liệu\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập phạm vi dữ liệu\\" />\\n          </Form.Item>\\n        </Form>\\n      </Modal>\\n\\n      {/* ── Add New Modal ────────────────────────────── */}\\n      <Modal\\n        title=\\"Thêm nhóm quyền mới\\"\\n        open={addOpen}\\n        onCancel={() => {\\n          setAddOpen(false);\\n          addForm.resetFields();\\n        }}\\n        onOk={handleAddSubmit}\\n        confirmLoading={addLoading}\\n        okText=\\"Thêm\\"\\n        cancelText=\\"Hủy\\"\\n        width={600}\\n        destroyOnClose\\n      >\\n        <Form\\n          form={addForm}\\n          layout=\\"vertical\\"\\n          initialValues={{ trang_thai: 'active' }}\\n          style={{ marginTop: 16 }}\\n        >\\n          <Form.Item\\n            name=\\"ma_nhom\\"\\n            label=\\"Mã nhóm\\"\\n            rules={[{ required: true, message: 'Vui lòng nhập mã nhóm' }]}\\n          >\\n            <Input placeholder=\\"Nhập mã nhóm\\" />\\n          </Form.Item>\\n          <Form.Item\\n            name=\\"ten_nhom\\"\\n            label=\\"Tên nhóm quyền\\"\\n            rules={[{ required: true, message: 'Vui lòng nhập tên nhóm quyền' }]}\\n          >\\n            <Input placeholder=\\"Nhập tên nhóm quyền\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập mô tả\\" />\\n          </Form.Item>\\n          <Form.Item\\n            name=\\"trang_thai\\"\\n            label=\\"Trạng thái\\"\\n            rules={[{ required: true, message: 'Vui lòng chọn trạng thái' }]}\\n          >\\n            <Select\\n              placeholder=\\"Chọn trạng thái\\"\\n              options={[\\n                { label: 'Đang sử dụng', value: 'active' },\\n                { label: 'Ngừng sử dụng', value: 'inactive' },\\n              ]}\\n            />\\n          </Form.Item>\\n          <Form.Item name=\\"pham_vi_du_lieu\\" label=\\"Phạm vi dữ liệu\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập phạm vi dữ liệu\\" />\\n          </Form.Item>\\n        </Form>\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<NhomQuyenBlock initData={initialData} reloadFn={fetchNhomQuyen} />);\\n"}},"__flowSurfaceMeta":{"declaredKey":"Qu_n_l_nh_m_quy_n.jsBlock_1"}}}
