p7t4zoyl4vk	p7t4zoyl4vk	{"parentId":"o5q5dn9a10j","subKey":"grid","subType":"object","use":"BlockGridModel","props":{"rows":{"row1":[["bifs13vzm2v"]]},"sizes":{"row1":[24]},"rowOrder":["row1"]},"stepParams":{"gridSettings":{"grid":{"rows":{"row1":[["bifs13vzm2v"]]},"sizes":{"row1":[24]},"rowOrder":["row1"]}}}}
bifs13vzm2v	bifs13vzm2v	{"parentId":"p7t4zoyl4vk","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Lịch sử phân quyền"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ===== JS Block: Lịch sử phân quyền =====\\n// Collection: lich_su_phan_quyen\\n// READ-ONLY log table — no add/edit/delete\\n\\nconst { React, antd, antdIcons, dayjs } = ctx.libs;\\nconst { useState, useMemo, useCallback } = React;\\nconst {\\n  Card, Table, Tag, Button, Input, Select, Space, Row, Col,\\n  Drawer, Descriptions, Typography, Tooltip, Statistic, Divider, Empty\\n} = antd;\\nconst {\\n  EyeOutlined, ReloadOutlined, SearchOutlined,\\n  CheckCircleOutlined, CloseCircleOutlined,\\n  HistoryOutlined, SafetyCertificateOutlined\\n} = antdIcons;\\nconst { Text, Title } = Typography;\\n\\n// ===== Top-level data loading =====\\nasync function fetchLichSu() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('lich_su_phan_quyen');\\n  res.setAppends(['nguoi_thuc_hien']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialData = await fetchLichSu();\\n\\n// ===== Constants =====\\nconst LOAI_DOI_TUONG_OPTIONS = {\\n  tai_khoan: { label: 'Tài khoản', color: 'blue' },\\n  vai_tro: { label: 'Vai trò', color: 'purple' },\\n  nhom_quyen: { label: 'Nhóm quyền', color: 'geekblue' },\\n  quyen_chuc_nang: { label: 'Quyền chức năng', color: 'cyan' },\\n  don_vi: { label: 'Đơn vị', color: 'gold' },\\n};\\n\\nconst LOAI_THAY_DOI_OPTIONS = {\\n  gan: { label: 'Gán', color: 'blue' },\\n  go: { label: 'Gỡ', color: 'orange' },\\n  them: { label: 'Thêm', color: 'green' },\\n  sua: { label: 'Sửa', color: 'cyan' },\\n  xoa: { label: 'Xóa/Ngừng sử dụng', color: 'red' },\\n};\\n\\nconst PHAM_VI_OPTIONS = {\\n  ca_nhan: { label: 'Cá nhân', color: 'default' },\\n  don_vi: { label: 'Đơn vị', color: 'blue' },\\n  cap_duoi: { label: 'Cấp dưới', color: 'purple' },\\n  toan_he_thong: { label: 'Toàn hệ thống', color: 'red' },\\n};\\n\\nconst KET_QUA_OPTIONS = {\\n  thanh_cong: { label: 'Thành công', color: 'green' },\\n  that_bai: { label: 'Thất bại', color: 'red' },\\n};\\n\\nconst PAGE_SIZE = 20;\\n\\n// ===== Component =====\\nfunction LichSuPhanQuyen({ initData, reloadFn }) {\\n  const [allData, setAllData] = useState(initData);\\n  const [loading, setLoading] = useState(false);\\n  const [currentPage, setCurrentPage] = useState(1);\\n  const [searchText, setSearchText] = useState('');\\n  const [filterLoaiThayDoi, setFilterLoaiThayDoi] = useState(null);\\n  const [filterKetQua, setFilterKetQua] = useState(null);\\n  const [drawerVisible, setDrawerVisible] = useState(false);\\n  const [selectedRecord, setSelectedRecord] = useState(null);\\n\\n  // Computed stats from allData\\n  const stats = useMemo(() => {\\n    var total = allData.length;\\n    var thanhCong = allData.filter(r => r.ket_qua === 'thanh_cong').length;\\n    var thatBai = allData.filter(r => r.ket_qua === 'that_bai').length;\\n    var ganGo = allData.filter(r => r.loai_thay_doi === 'gan' || r.loai_thay_doi === 'go').length;\\n    return { total, thanhCong, thatBai, ganGo };\\n  }, [allData]);\\n\\n  // Client-side filtered data\\n  const filteredData = useMemo(() => {\\n    var result = allData;\\n    if (searchText) {\\n      var s = searchText.toLowerCase();\\n      result = result.filter(r =>\\n        (r.ten_doi_tuong && r.ten_doi_tuong.toLowerCase().includes(s)) ||\\n        (r.tai_khoan_anh_huong && r.tai_khoan_anh_huong.toLowerCase().includes(s))\\n      );\\n    }\\n    if (filterLoaiThayDoi) {\\n      result = result.filter(r => r.loai_thay_doi === filterLoaiThayDoi);\\n    }\\n    if (filterKetQua) {\\n      result = result.filter(r => r.ket_qua === filterKetQua);\\n    }\\n    return result;\\n  }, [allData, searchText, filterLoaiThayDoi, filterKetQua]);\\n\\n  var total = filteredData.length;\\n\\n  // Paginated data\\n  const paginatedData = useMemo(() => {\\n    return filteredData.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);\\n  }, [filteredData, currentPage]);\\n\\n  // Load data from server\\n  const loadData = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await reloadFn();\\n      setAllData(newData);\\n    } catch (err) {\\n      ctx.message.error('Không thể tải dữ liệu lịch sử phân quyền');\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [reloadFn]);\\n\\n  // Handlers\\n  const handleSearch = useCallback(() => {\\n    setCurrentPage(1);\\n  }, []);\\n\\n  const handleRefresh = useCallback(() => {\\n    setSearchText('');\\n    setFilterLoaiThayDoi(null);\\n    setFilterKetQua(null);\\n    setCurrentPage(1);\\n    loadData();\\n  }, [loadData]);\\n\\n  const handlePageChange = useCallback((page) => {\\n    setCurrentPage(page);\\n  }, []);\\n\\n  const handleView = useCallback((record) => {\\n    setSelectedRecord(record);\\n    setDrawerVisible(true);\\n  }, []);\\n\\n  const handleCloseDrawer = useCallback(() => {\\n    setDrawerVisible(false);\\n    setSelectedRecord(null);\\n  }, []);\\n\\n  // Helpers\\n  const getUserDisplay = (record) => {\\n    const user = record?.nguoi_thuc_hien;\\n    if (!user) return '-';\\n    return user.nickname || user.email || '-';\\n  };\\n\\n  const formatDateTime = (val) => {\\n    if (!val) return '-';\\n    return dayjs(val).format('DD/MM/YYYY HH:mm:ss');\\n  };\\n\\n  const truncateText = (text, maxLen) => {\\n    if (!text) return '-';\\n    if (text.length <= maxLen) return text;\\n    return text.substring(0, maxLen) + '...';\\n  };\\n\\n  const renderTag = (val, optionMap) => {\\n    if (!val) return '-';\\n    const opt = optionMap[val];\\n    if (!opt) return React.createElement(Tag, null, val);\\n    return React.createElement(Tag, { color: opt.color }, opt.label);\\n  };\\n\\n  const renderJson = (val) => {\\n    if (val === null || val === undefined) return '-';\\n    try {\\n      const parsed = typeof val === 'string' ? JSON.parse(val) : val;\\n      return React.createElement(\\n        'pre',\\n        {\\n          style: {\\n            background: '#f5f5f5',\\n            padding: 12,\\n            borderRadius: 6,\\n            maxHeight: 300,\\n            overflow: 'auto',\\n            fontSize: 12,\\n            margin: 0,\\n            whiteSpace: 'pre-wrap',\\n            wordBreak: 'break-all',\\n          },\\n        },\\n        JSON.stringify(parsed, null, 2)\\n      );\\n    } catch {\\n      return React.createElement(Text, { type: 'secondary' }, String(val));\\n    }\\n  };\\n\\n  // Table columns\\n  const columns = useMemo(() => [\\n    {\\n      title: 'Thời gian',\\n      dataIndex: 'thoi_gian',\\n      key: 'thoi_gian',\\n      width: 160,\\n      render: (val) => formatDateTime(val),\\n    },\\n    {\\n      title: 'Người thực hiện',\\n      dataIndex: 'nguoi_thuc_hien',\\n      key: 'nguoi_thuc_hien',\\n      width: 150,\\n      render: (_, record) => getUserDisplay(record),\\n    },\\n    {\\n      title: 'Loại đối tượng',\\n      dataIndex: 'loai_doi_tuong',\\n      key: 'loai_doi_tuong',\\n      width: 140,\\n      render: (val) => renderTag(val, LOAI_DOI_TUONG_OPTIONS),\\n    },\\n    {\\n      title: 'Tên đối tượng',\\n      dataIndex: 'ten_doi_tuong',\\n      key: 'ten_doi_tuong',\\n      width: 160,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'TK chịu ảnh hưởng',\\n      dataIndex: 'tai_khoan_anh_huong',\\n      key: 'tai_khoan_anh_huong',\\n      width: 160,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'Loại thay đổi',\\n      dataIndex: 'loai_thay_doi',\\n      key: 'loai_thay_doi',\\n      width: 140,\\n      render: (val) => renderTag(val, LOAI_THAY_DOI_OPTIONS),\\n    },\\n    {\\n      title: 'Nội dung',\\n      dataIndex: 'noi_dung',\\n      key: 'noi_dung',\\n      width: 200,\\n      ellipsis: true,\\n      render: (val) => truncateText(val, 50),\\n    },\\n    {\\n      title: 'Phạm vi',\\n      dataIndex: 'pham_vi',\\n      key: 'pham_vi',\\n      width: 120,\\n      render: (val) => renderTag(val, PHAM_VI_OPTIONS),\\n    },\\n    {\\n      title: 'Kết quả',\\n      dataIndex: 'ket_qua',\\n      key: 'ket_qua',\\n      width: 110,\\n      render: (val) => renderTag(val, KET_QUA_OPTIONS),\\n    },\\n    {\\n      title: 'Mã bản ghi',\\n      dataIndex: 'ma_ban_ghi',\\n      key: 'ma_ban_ghi',\\n      width: 120,\\n      ellipsis: true,\\n    },\\n    {\\n      title: '',\\n      key: 'actions',\\n      width: 80,\\n      fixed: 'right',\\n      render: (_, record) =>\\n        React.createElement(\\n          Tooltip,\\n          { title: 'Xem chi tiết' },\\n          React.createElement(Button, {\\n            icon: React.createElement(EyeOutlined),\\n            size: 'small',\\n            onClick: () => handleView(record),\\n          })\\n        ),\\n    },\\n  ], [handleView]);\\n\\n  // ===== Render =====\\n  return React.createElement(\\n    'div',\\n    { style: { padding: 0 } },\\n\\n    // Stats cards\\n    React.createElement(\\n      Row,\\n      { gutter: 16, style: { marginBottom: 16 } },\\n      React.createElement(\\n        Col,\\n        { xs: 12, sm: 6 },\\n        React.createElement(\\n          Card,\\n          { size: 'small', bordered: true },\\n          React.createElement(Statistic, {\\n            title: 'Tổng lượt thay đổi',\\n            value: stats.total,\\n            prefix: React.createElement(HistoryOutlined, {\\n              style: { color: '#1890ff' },\\n            }),\\n          })\\n        )\\n      ),\\n      React.createElement(\\n        Col,\\n        { xs: 12, sm: 6 },\\n        React.createElement(\\n          Card,\\n          { size: 'small', bordered: true },\\n          React.createElement(Statistic, {\\n            title: 'Thành công',\\n            value: stats.thanhCong,\\n            valueStyle: { color: '#52c41a' },\\n            prefix: React.createElement(CheckC