ntPage,\\n          pageSize: PAGE_SIZE,\\n          total: total,\\n          onChange: handlePageChange,\\n          showTotal: (t, range) => `${range[0]}-${range[1]} / ${t} bản ghi`,\\n          showSizeChanger: false,\\n        },\\n        locale: {\\n          emptyText: React.createElement(\\n            Empty,\\n            { description: 'Chưa có dữ liệu lịch sử phân quyền' }\\n          ),\\n        },\\n      })\\n    ),\\n\\n    // View Drawer\\n    React.createElement(\\n      Drawer,\\n      {\\n        title: 'Chi tiết lịch sử phân quyền',\\n        open: drawerVisible,\\n        onClose: handleCloseDrawer,\\n        width: 640,\\n        footer: null,\\n      },\\n      selectedRecord\\n        ? React.createElement(\\n            Descriptions,\\n            {\\n              column: 1,\\n              bordered: true,\\n              size: 'small',\\n              labelStyle: { width: 180, fontWeight: 500, background: '#fafafa' },\\n            },\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Thời gian' },\\n              formatDateTime(selectedRecord.thoi_gian)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Người thực hiện' },\\n              getUserDisplay(selectedRecord)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Loại đối tượng' },\\n              renderTag(selectedRecord.loai_doi_tuong, LOAI_DOI_TUONG_OPTIONS)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Mã đối tượng' },\\n              selectedRecord.ma_doi_tuong || '-'\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Tên đối tượng' },\\n              selectedRecord.ten_doi_tuong || '-'\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Tài khoản chịu ảnh hưởng' },\\n              selectedRecord.tai_khoan_anh_huong || '-'\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Đơn vị chịu ảnh hưởng' },\\n              selectedRecord.don_vi_anh_huong || '-'\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Loại thay đổi' },\\n              renderTag(selectedRecord.loai_thay_doi, LOAI_THAY_DOI_OPTIONS)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Nội dung thay đổi' },\\n              selectedRecord.noi_dung || '-'\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Dữ liệu trước thay đổi' },\\n              renderJson(selectedRecord.du_lieu_truoc)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Dữ liệu sau thay đổi' },\\n              renderJson(selectedRecord.du_lieu_sau)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Phạm vi' },\\n              renderTag(selectedRecord.pham_vi, PHAM_VI_OPTIONS)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Kết quả' },\\n              renderTag(selectedRecord.ket_qua, KET_QUA_OPTIONS)\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Lý do thất bại' },\\n              selectedRecord.ly_do_that_bai || '-'\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Địa chỉ mạng (IP)' },\\n              selectedRecord.dia_chi_mang || '-'\\n            ),\\n            React.createElement(\\n              Descriptions.Item,\\n              { label: 'Thiết bị/Trình duyệt' },\\n              selectedRecor