9qtzag6baf1	9qtzag6baf1	{"parentId":"n2hel25jsf9","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// Chứng nhận huấn luyện — JS Block\\n\\nvar React = ctx.libs.React;\\nvar useState = React.useState;\\nvar useMemo = React.useMemo;\\nvar antd = ctx.libs.antd;\\nvar Table = antd.Table;\\nvar Input = antd.Input;\\nvar Tag = antd.Tag;\\nvar Space = antd.Space;\\nvar Tooltip = antd.Tooltip;\\nvar dayjs = ctx.libs.dayjs;\\n\\nvar TRANG_THAI_MAP = {\\n  hieu_luc: { label: 'Còn hiệu lực', color: 'green' },\\n  het_han: { label: 'Hết hạn', color: 'red' },\\n  thu_hoi: { label: 'Đã thu hồi', color: 'volcano' },\\n};\\n\\nfunction cleanEnum(val) {\\n  if (typeof val === 'string' && val.length >= 2 && val.charAt(0) === '\\"' && val.charAt(val.length - 1) === '\\"') {\\n    return val.slice(1, -1);\\n  }\\n  return val;\\n}\\n\\nfunction formatDate(d) {\\n  if (!d) return '—';\\n  return dayjs(d).format('DD/MM/YYYY');\\n}\\n\\nvar res = ctx.makeResource('MultiRecordResource');\\nres.setResourceName('chung_nhan_huan_luyen');\\nres.setAppends(['nguoi_lao_dong', 'bac_tho_dat', 'khoa_huan_luyen', 'ky_thi']);\\nres.setSort(['-createdAt']);\\nres.setPageSize(500);\\nawait res.refresh();\\nvar rawData = res.getData() || [];\\n\\nvar initialData = rawData.map(function(r) {\\n  return Object.assign({}, r, {\\n    trang_thai: cleanEnum(r.trang_thai),\\n  });\\n});\\n\\nfunction ChungNhanHuanLuyenBlock(props) {\\n  var data = props.data;\\n  var searchVal = useState('');\\n  var search = searchVal[0];\\n  var setSearch = searchVal[1];\\n\\n  var stats = useMemo(function() {\\n    var total = data.length;\\n    var hieuLuc = 0;\\n    var hetHan = 0;\\n    var thuHoi = 0;\\n    data.forEach(function(r) {\\n      if (r.trang_thai === 'hieu_luc') hieuLuc++;\\n      else if (r.trang_thai === 'het_han') hetHan++;\\n      else if (r.trang_thai === 'thu_hoi') thuHoi++;\\n    });\\n    return { total: total, hieuLuc: hieuLuc, hetHan: hetHan, thuHoi: thuHoi };\\n  }, [data]);\\n\\n  var filtered = useMemo(function() {\\n    if (!search.trim()) return data;\\n    var s = search.toLowerCase();\\n    return data.filter(function(r) {\\n      var nldName = (r.nguoi_lao_dong && r.nguoi_lao_dong.ho_ten) || '';\\n      var maCN = r.ma_chung_nhan || '';\\n      var bacTho = (r.bac_tho_dat && (r.bac_tho_dat.ten_bac || r.bac_tho_dat.ten)) || '';\\n      return nldName.toLowerCase().indexOf(s) >= 0 ||\\n        maCN.toLowerCase().indexOf(s) >= 0 ||\\n        bacTho.toLowerCase().indexOf(s) >= 0;\\n    });\\n  }, [data, search]);\\n\\n  var columns = [\\n    {\\n      title: 'STT',\\n      width: 60,\\n      align: 'center',\\n      render: function(_, __, i) { return i + 1; },\\n    },\\n    {\\n      title: 'Mã chứng nhận',\\n      dataIndex: 'ma_chung_nhan',\\n      width: 160,\\n      render: function(v) {\\n        if (!v) return '—';\\n        return React.createElement('span', { style: { fontWeight: 500, color: '#1890ff' } }, v);\\n      },\\n    },\\n    {\\n      title: 'Người lao động',\\n      dataIndex: ['nguoi_lao_dong', 'ho_ten'],\\n      width: 180,\\n      render: function(v) { return v || '—'; },\\n    },\\n    {\\n      title: 'Bậc thợ đạt được',\\n      width: 150,\\n      render: function(_, r) {\\n        var bt = r.bac_tho_dat;\\n        if (!bt) return '—';\\n        return bt.ten_bac || bt.ten || bt.name || '—';\\n      },\\n    },\\n    {\\n      title: 'Khóa huấn luyện',\\n      width: 180,\\n      ellipsis: true,\\n      render: function(_, r) {\\n        var khl = r.khoa_huan_luyen;\\n        if (!khl) return '—';\\n        return khl.ten_khoa || khl.ten || khl.name || '—';\\n      },\\n    },\\n    {\\n      title: 'Ngày cấp',\\n      dataIndex: 'ngay_cap',\\n      width: 110,\\n      render: function(v) { return formatDate(v); },\\n    },\\n    {\\n      title: 'Ngày hết hạn',\\n      dataIndex: 'ngay_het_han',\\n      width: 110,\\n      render: function(v) { return formatDate(v); },\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      width: 130,\\n      align: 'center',\\n      render: function(v) {\\n        var info = TRANG_THAI_MAP[v] || { label: v || '—', color: 'default' };\\n        return React.createElement(Tag, { color: info.color }, info.label);\\n      },\\n    },\\n    {\\n      title: 'Ghi chú',\\n      dataIndex: 'ghi_chu',\\n      width: 200,\\n      ellipsis: true,\\n      render: function(v) {\\n        if (!v) return '—';\\n        return React.createElement(Tooltip, { title: v },\\n          React.createElement('span', null, v)\\n        );\\n      },\\n    },\\n  ];\\n\\n  var headerStyle = { marginBottom: 16, display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 };\\n\\n  return React.createElement('div', { style: { padding: 0 } },\\n    React.createElement('div', { style: headerStyle },\\n      React.createElement(Space, { size: 12 },\\n        React.createElement(Tag, { color: 'blue', style: { fontSize: 14, padding: '4px 12px' } }, 'Tổng: ' + stats.total),\\n        React.createElement(Tag, { color: 'green', style: { fontSize: 14, padding: '4px 12px' } }, 'Còn hiệu lực: ' + stats.hieuLuc),\\n        React.createElement(Tag, { color: 'red', style: { fontSize: 14, padding: '4px 12px' } }, 'Hết hạn: ' + stats.hetHan),\\n        stats.thuHoi > 0 ? React.createElement(Tag, { color: 'volcano', style: { fontSize: 14, padding: '4px 12px' } }, 'Thu hồi: ' + stats.thuHoi) : null\\n      ),\\n      React.createElement(Input.Search, {\\n        placeholder: 'Tìm theo mã, họ tên NLĐ, bậc thợ...',\\n        allowClear: true,\\n        style: { width: 320 },\\n        onSearch: function(v) { setSearch(v); },\\n        onChange: function(e) { if (!e.target.value) setSearch(''); },\\n      })\\n    ),\\n    React.createElement(Table, {\\n      dataSource: filtered,\\n      columns: columns,\\n      rowKey: 'id',\\n      size: 'small',\\n      bordered: true,\\n      pagination: { pageSize: 20, showSizeChanger: true, showTotal: function(total) { return 'Tổng ' + total + ' chứng nhận'; } },\\n      scroll: { x: 1400 },\\n    })\\n  );\\n}\\n\\nctx.render(React.createElement(ChungNhanHuanLuyenBlock, { data: initialData }));\\n"}},"__flowSurfaceMeta":{"declaredKey":"chungNhanHuanLuyenJsV1"}}}
