alofbzxh8kx	alofbzxh8kx	{"parentId":"u154v22ynn6","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ============================================================\\n// JS Block: Ho so nguoi lao dong\\n// Collection: nguoi_lao_dong\\n// ============================================================\\n\\n// --- 1. Top-level data loading ---\\nasync function fetchNguoiLaoDong() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('nguoi_lao_dong');\\n  res.setAppends(['doanh_nghiep', 'tai_khoan', 'bac_tho', 'don_vi', 'nganh_nghe']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(1000);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialData = await fetchNguoiLaoDong();\\n\\nasync function fetchDoanhNghiepList() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('doanh_nghiep');\\n  res.setFilter({ is_deleted: { $ne: true }, trang_thai: { $eq: 'hoat_dong' } });\\n  res.setSort(['ten_doanh_nghiep']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialDNList = await fetchDoanhNghiepList();\\n\\nasync function fetchBacThoList() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('bac_tho');\\n  res.setFilter({ is_deleted: { $ne: true } });\\n  res.setSort(['thu_tu']);\\n  res.setPageSize(100);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialBacThoList = await fetchBacThoList();\\n\\nasync function fetchDonViList() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('don_vi');\\n  res.setSort(['ten_don_vi']);\\n  res.setPageSize(200);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialDonViList = await fetchDonViList();\\n\\nasync function fetchNganhNgheList() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('nganh_nghe');\\n  res.setSort(['ten_nganh']);\\n  res.setPageSize(200);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialNganhNgheList = await fetchNganhNgheList();\\n\\n// --- 2. Libs ---\\nconst {\\n  Table, Button, Input, Select, Tag, Space, Card, Row, Col, Modal,\\n  Form, DatePicker, Drawer, Popconfirm, Tooltip, Typography, Statistic,\\n  Descriptions, Pagination, Divider, Steps,\\n} = ctx.libs.antd;\\n\\nconst {\\n  SearchOutlined, PlusOutlined, EditOutlined, EyeOutlined,\\n  DeleteOutlined, ReloadOutlined, UserOutlined, TeamOutlined,\\n  IdcardOutlined, BankOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst React = ctx.libs.React;\\nconst { useState, useCallback, useMemo } = React;\\nconst dayjs = ctx.libs.dayjs;\\n\\n// --- 3. Constants ---\\nconst TRANG_THAI_OPTIONS = [\\n  { value: 'dang_lam_viec', label: 'Đang làm việc', color: 'green' },\\n  { value: 'tam_nghi', label: 'Tạm nghỉ', color: 'gold' },\\n  { value: 'da_nghi_viec', label: 'Đã nghỉ việc', color: 'red' },\\n];\\nconst TRANG_THAI_MAP = {};\\nTRANG_THAI_OPTIONS.forEach(function(o) { TRANG_THAI_MAP[o.value] = o; });\\n\\nconst GIOI_TINH_OPTIONS = [\\n  { value: 'nam', label: 'Nam' },\\n  { value: 'nu', label: 'Nữ' },\\n  { value: 'khac', label: 'Khác' },\\n];\\nconst GIOI_TINH_MAP = { nam: 'Nam', nu: 'Nữ', khac: 'Khác' };\\n\\nconst TRANG_THAI_HL_OPTIONS = [\\n  { value: 'con_han', label: 'Còn hạn', color: 'green' },\\n  { value: 'sap_het_han', label: 'Sắp hết hạn', color: 'gold' },\\n  { value: 'qua_han', label: 'Quá hạn', color: 'red' },\\n  { value: 'chua_huan_luyen', label: 'Chưa huấn luyện', color: 'default' },\\n];\\nconst TRANG_THAI_HL_MAP = {};\\nTRANG_THAI_HL_OPTIONS.forEach(function(o) { TRANG_THAI_HL_MAP[o.value] = o; });\\n\\n// --- 4. React Component ---\\nconst HoSoNLDBlock = ({ initData, reloadFn, dnList, bacThoList, donViList, nganhNgheList }) => {\\n  const [loading, setLoading] = useState(false);\\n  const [allData, setAllData] = useState(initData);\\n  const [page, setPage] = useState(1);\\n  const [pageSize] = useState(20);\\n  const [searchText, setSearchText] = useState('');\\n  const [filterTrangThai, setFilterTrangThai] = useState(null);\\n  const [filterDN, setFilterDN] = useState(null);\\n\\n  const [viewVisible, setViewVisible] = useState(false);\\n  const [viewRecord, setViewRecord] = useState(null);\\n  const [editVisible, setEditVisible] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [addVisible, setAddVisible] = useState(false);\\n  const [addStep, setAddStep] = useState(0);\\n  const [submitting, setSubmitting] = useState(false);\\n\\n  const [editForm] = Form.useForm();\\n  const [addForm] = Form.useForm();\\n\\n  const activeRows = useMemo(() => {\\n    return (allData || []).filter((r) => !r.is_deleted);\\n  }, [allData]);\\n\\n  const stats = useMemo(() => {\\n    var total = 0, dangLamViec = 0, tamNghi = 0, daNghiViec = 0;\\n    for (var i = 0; i < activeRows.length; i++) {\\n      total++;\\n      var r = activeRows[i];\\n      if (r.trang_thai === 'dang_lam_viec') dangLamViec++;\\n      else if (r.trang_thai === 'tam_nghi') tamNghi++;\\n      else if (r.trang_thai === 'da_nghi_viec') daNghiViec++;\\n    }\\n    return { total: total, dangLamViec: dangLamViec, tamNghi: tamNghi, daNghiViec: daNghiViec };\\n  }, [activeRows]);\\n\\n  const filteredData = useMemo(() => {\\n    var rows = activeRows;\\n    if (searchText && searchText.trim()) {\\n      var s = searchText.trim().toLowerCase();\\n      rows = rows.filter((r) =>\\n        (r.ho_ten && r.ho_ten.toLowerCase().indexOf(s) >= 0) ||\\n        (r.so_giay_to && r.so_giay_to.toLowerCase().indexOf(s) >= 0) ||\\n        (r.dien_thoai && r.dien_thoai.toLowerCase().indexOf(s) >= 0) ||\\n        (r.email && r.email.toLowerCase().indexOf(s) >= 0) ||\\n        (r.ma_nguoi_lao_dong && r.ma_nguoi_lao_dong.toLowerCase().indexOf(s) >= 0)\\n      );\\n    }\\n    if (filterTrangThai) {\\n      rows = rows.filter((r) => r.trang_thai === filterTrangThai);\\n    }\\n    if (filterDN) {\\n      rows = rows.filter((r) => r.doanhNghiepId && String(r.doanhNghiepId) === String(filterDN));\\n    }\\n    return rows;\\n  }, [activeRows, searchText, filterTrangThai, filterDN]);\\n\\n  const paginatedData = useMemo(() => {\\n    return filteredData.slice((page - 1) * pageSize, page * pageSize);\\n  }, [filteredData, page, pageSize]);\\n\\n  const fetchData = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await reloadFn();\\n      setAllData(newData);\\n    } catch (err) {\\n      ctx.message.error('Không thể tải dữ liệu');\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [reloadFn]);\\n\\n  const handleView = (record) => {\\n    setViewRecord(record);\\n    setViewVisible(true);\\n  };\\n\\n  const handleEdit = (record) => {\\n    setEditRecord(record);\\n    editForm.setFieldsValue({\\n      ho_ten: record.ho_ten,\\n      so_giay_to: record.so_giay_to,\\n      ngay_sinh: record.ngay_sinh ? dayjs(record.ngay_sinh) : null,\\n      gioi_tinh: record.gioi_tinh,\\n      dien_thoai: record.dien_thoai,\\n      email: record.email,\\n      ngay_vao_lam: record.ngay_vao_lam ? dayjs(record.ngay_vao_lam) : null,\\n      trang_thai: record.trang_thai,\\n      doanhNghiepId: record.doanhNghiepId,\\n      bacThoId: record.bacThoId,\\n      donViId: record.donViId,\\n      nganh_nghe_id: record.nganh_nghe_id,\\n      trang_thai_huan_luyen: record.trang_thai_huan_luyen,\\n      han_huan_luyen_lai: record.han_huan_luyen_lai ? dayjs(record.han_huan_luyen_lai) : null,\\n    });\\n    setEditVisible(true);\\n  };\\n\\n  const handleEditSubmit = async () => {\\n    try {\\n      const values = await editForm.validateFields();\\n      setSubmitting(true);\\n      await ctx.request({\\n        url: 'nguoi_lao_dong:update',\\n        method: 'post',\\n        params: { filterByTk: editRecord.id },\\n        data: {\\n          ...values,\\n          ngay_sinh: values.ngay_sinh ? values.ngay_sinh.format('YYYY-MM-DD') : null,\\n          ngay_vao_lam: values.ngay_vao_lam ? values.ngay_vao_lam.format('YYYY-MM-DD') : null,\\n          han_huan_luyen_lai: values.han_huan_luyen_lai ? values.han_huan_luyen_lai.format('YYYY-MM-DD') : null,\\n        },\\n      });\\n      ctx.message.success('Cập nhật thành công');\\n      setEditVisible(false);\\n      editForm.resetFields();\\n      fetchData();\\n    } catch (err) {\\n      if (err && err.errorFields) return;\\n      ctx.message.error('Cập nhật thất bại');\\n    } finally {\\n      setSubmitting(false);\\n    }\\n  };\\n\\n  const handleAddOpen = () => {\\n    addForm.resetFields();\\n    setAddStep(0);\\n    setAddVisible(true);\\n  };\\n\\n  const handleAddSubmit = async () => {\\n    try {\\n      const values = await addForm.validateFields();\\n      if (!values.doanhNghiepId) {\\n        ctx.message.error('Vui lòng chọn doanh nghiệp');\\n        setAddStep(0);\\n        return;\\n      }\\n      setSubmitting(true);\\n      await ctx.request({\\n        url: 'nguoi_lao_dong:create',\\n        method: 'post',\\n        data: {\\n          ...values,\\n          ngay_sinh: values.ngay_sinh ? values.ngay_sinh.format('YYYY-MM-DD') : null,\\n          ngay_vao_lam: values.ngay_vao_lam ? values.ngay_vao_lam.format('YYYY-MM-DD') : null,\\n          is_deleted: false,\\n        },\\n      });\\n      ctx.message.success('Them moi thanh cong. Tai khoan se duoc tao tu dong boi he thong.');\\n      setAddVisible(false);\\n      addForm.resetFields();\\n      fetchData();\\n    } catch (err) {\\n      if (err && err.errorFields) return;\\n      ctx.message.error('Thêm mới thất bại');\\n    } finally {\\n      setSubmitting(false);\\n    }\\n  };\\n\\n  const handleDelete = async (record) => {\\n    try {\\n      await ctx.request({\\n        url: 'nguoi_lao_dong:update',\\n        method: 'post',\\n        params: { filterByTk: record.id },\\n        data: { is_deleted: true },\\n      });\\n      ctx.message.success('Xóa thành công');\\n      fetchData();\\n    } catch (err) {\\n      ctx.message.error('Xóa thất bại');\\n    }\\n  };\\n\\n  const columns = [\\n    {\\n      title: 'Mã NLĐ',\\n      dataIndex: 'ma_nguoi_lao_dong',\\n      key: 'ma_nguoi_lao_dong',\\n      width: 110,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Họ và tên',\\n      dataIndex: 'ho_ten',\\n      key: 'ho_ten',\\n      width: 180,\\n      ellipsis: true,\\n      render: (text) => React.createElement('span', { style: { fontWeight: 500 } }, text || '-'),\\n    },\\n    {\\n      title: 'Số CCCD',\\n      dataIndex: 'so_giay_to',\\n      key: 'so_giay_to',\\n      width: 140,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Đơn vị / Doanh nghiệp',\\n      key: 'doanh_nghiep',\\n      width: 200,\\n      ellipsis: true,\\n      render: (_, record) => {\\n        var dv = record.don_vi;\\n        if (dv && dv.ten_don_vi) return dv.ten_don_vi;\\n        var dn = record.doanh_nghiep;\\n        return (dn && dn.ten_doanh_nghiep) ? dn.ten_doanh_nghiep : '-';\\n      },\\n    },\\n    {\\n      title: 'Bậc thợ',\\n      key: 'bac_tho',\\n      width: 160,\\n      render: (_, record) => (record.bac_tho && record.bac_tho.ten_bac) ? record.bac_tho.ten_bac : '-',\\n    },\\n    {\\n      title: 'Điện thoại',\\n      dataIndex: 'dien_thoai',\\n      key: 'dien_thoai',\\n      width: 130,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      key: 'trang_thai',\\n      width: 130,\\n      render: (val) => {\\n        var info = TRANG_THAI_MAP[val];\\n        return info ? React.createElement(Tag, { color: info.color }, info.label) : '-';\\n      },\\n    },\\n    {\\n      title: 'Tài khoản',\\n      key: 'tai_khoan',\\n      width: 100,\\n      align: 'center',\\n      render: (_, record) => {\\n        var tk = record.tai_khoan;\\n        if (tk && tk.id) {\\n          return React.createElement(Tag, { color: 'blue' }, 'Có');\\n        }\\n        return React.createElement(Tag, { color: 'default' }, 'Chưa có');\\n      },\\n    },\\n    {\\n      title: 'Thao tác',\\n      key: 'actions',\\n      fixed: 'right',\\n      width: 150,\\n      render: (_, record) =>\\n        React.createElement(Space, { size: 4 },\\n          React.createElement(Tooltip, { title: 'Xem chi tiết' },\\n            React.createElement(Button, {\\n              icon: React.createElement(EyeOutlined),\\n              onClick: () => handleView(record),\\n            })\\n          ),\\n          React.createElement(Tooltip, { title: 'Chỉnh sửa' },\\n            React.createElement(Button, {\\n              icon: React.createElement(EditOutlined),\\n              onClick: () => handleEdit(record),\\n            })\\n          ),\\n          React.createElement(Popconfirm, {\\n            title: 'Xác nhận xóa',\\n            description: 'Ban co chac chan muon xoa ho so nay?',\\n            onConfirm: () => handleDelete(record),\\n            okText: 'Xóa',\\n            cancelText: 'Hủy',\\n          },\\n            React.createElement(Tooltip, { title: 'Xóa' },\\n              React.createElement(Button, {\\n                icon: React.createElement(DeleteOutlined),\\n                danger: true,\\n              })\\n            )\\n          ),\\n        ),\\n    },\\n  ];\\n\\n  const renderEditFormFields = () => {\\n    return React.createElement(React.Fragment, null,\\n      React.createElement(Form.Item, { name: 'doanhNghiepId', label: 'Doanh nghiệp', rules: [{ required: true, message: 'Vui lòng chọn doanh nghiệp' }] },\\n        React.createElement(Select, {\\n          placeholder: 'Chọn doanh nghiệp',\\n          showSearch: true,\\n          optionFilterProp: 'label',\\n          options: dnList.map(function(d) { return { value: d.id, label: d.ten_doanh_nghiep || ('DN #' + d.id) }; }),\\n        })\\n      ),\\n      React.createElement(Form.Item, { name: 'ho_ten', label: 'Họ và tên', rules: [{ required: true, message: 'Vui lòng nhập họ tên' }] },\\n        React.createElement(Input, { placeholder: 'Nhập họ và tên' })\\n      ),\\n      React.createElement(Form.Item, { name: 'so_giay_to', label: 'So CCCD/Ho chieu' },\\n        React.createElement(Input, { placeholder: 'Nhap so CCCD/Ho chieu' })\\n      ),\\n      React.createElement(Form.Item, { name: 'ngay_sinh', label: 'Ngày sinh' },\\n        React.createElement(DatePicker, { style: { width: '100%' }, format: 'DD/MM/YYYY', placeholder: 'Chọn ngày sinh' })\\n      ),\\n      React.createElement(Form.Item, { name: 'gioi_tinh', label: 'Giới tính' },\\n        React.createElement(Select, { placeholder: 'Chọn giới tính', allowClear: true, options: GIOI_TINH_OPTIONS })\\n      ),\\n      React.createElement(Form.Item, { name: 'dien_thoai', label: 'Điện thoại' },\\n        React.createElement(Input, { placeholder: 'Nhập số điện thoại' })\\n      ),\\n      React.createElement(Form.Item, { name: 'email', label: 'Email', rules: [{ type: 'email', message: 'Email không hợp lệ' }] },\\n        React.createElement(Input, { placeholder: 'Nhập email' })\\n      ),\\n      React.createElement(Form.Item, { name: 'ngay_vao_lam', label: 'Ngày vào làm' },\\n        React.createElement(DatePicker, { style: { width: '100%' }, format: 'DD/MM/YYYY', placeholder: 'Chọn ngày vào làm' })\\n      ),\\n      React.createElement(Form.Item, { name: 'donViId', label: 'Đơn vị' },\\n        React.createElement(Select, {\\n          placeholder: 'Chọn đơn vị',\\n          allowClear: true,\\n          showSearch: true,\\n          optionFilterProp: 'label',\\n          options: donViList.map(function(d) { return { value: d.id, label: d.ten_don_vi || ('DV #' + d.id) }; }),\\n        })\\n      ),\\n      React.createElement(Form.Item, { name: 'bacThoId', label: 'Bậc thợ' },\\n        React.createElement(Select, {\\n          placeholder: 'Chọn bậc thợ',\\n          allowClear: true,\\n