1se95gtdsdo	1se95gtdsdo	{"parentId":"8v0ms9bre6v","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v5","code":"// ============================================================\\n// JS Block: Chấm điểm & đánh giá\\n// Views: A1 (DS kỳ thi) → A2 (DS thí sinh) → A3/A4/A5/A6/A7\\n// ============================================================\\n\\nconst {\\n  Table, Card, Button, Input, Select, Tag, Space, Row, Col,\\n  Modal, Form, Drawer, Popconfirm, Tooltip, Statistic, Divider,\\n  Typography, Spin, Pagination, Progress, Badge, Descriptions,\\n  InputNumber, Switch, Alert, Empty, Upload, Tabs, Result,\\n  Checkbox, message, notification,\\n} = ctx.libs.antd;\\n\\nconst {\\n  PlusOutlined, ReloadOutlined, SearchOutlined,\\n  EyeOutlined, EditOutlined, DeleteOutlined,\\n  CheckCircleOutlined, CloseCircleOutlined,\\n  FileTextOutlined, BarChartOutlined,\\n  AuditOutlined, UploadOutlined,\\n  ArrowLeftOutlined, LeftOutlined, RightOutlined,\\n  ExclamationCircleOutlined, DownloadOutlined,\\n  RobotOutlined, FilePdfOutlined,\\n  TeamOutlined, TrophyOutlined, ClockCircleOutlined,\\n  SafetyCertificateOutlined, FilterOutlined,\\n  InboxOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst { useState, useCallback, useMemo, useEffect } = ctx.libs.React;\\nconst React = ctx.libs.React;\\nconst { Text, Title } = Typography;\\n\\n// -- Enum maps ------------------------------------------------\\nvar HINH_THUC_MAP = {\\n  truc_tuyen: { label: 'Trực tuyến', color: 'blue' },\\n  ban_cung: { label: 'Bản cứng', color: 'orange' },\\n  ket_hop: { label: 'Kết hợp', color: 'purple' },\\n  truc_tiep: { label: 'Trực tiếp', color: 'green' },\\n};\\n\\nvar TRANG_THAI_KT_MAP = {\\n  ban_nhap: { label: 'Bản nháp', color: 'default' },\\n  lap_lich: { label: 'Lập lịch', color: 'blue' },\\n  sap_dien_ra: { label: 'Sắp diễn ra', color: 'purple' },\\n  da_duyet: { label: 'Đã duyệt', color: 'cyan' },\\n  da_phe_duyet: { label: 'Đã phê duyệt', color: 'green' },\\n  dang_mo: { label: 'Đang mở', color: 'green' },\\n  dang_thi: { label: 'Đang thi', color: 'processing' },\\n  dang_cham_diem: { label: 'Đang chấm điểm', color: 'orange' },\\n  hoan_thanh: { label: 'Hoàn thành', color: 'green' },\\n  da_huy: { label: 'Đã hủy', color: 'red' },\\n};\\n\\nvar TRANG_THAI_TS_MAP = {\\n  cho_thi: { label: 'Chờ thi', color: 'default' },\\n  da_xep_lich: { label: 'Đã xếp lịch', color: 'blue' },\\n  da_nop_bai: { label: 'Đã nộp bài', color: 'cyan' },\\n  da_nop: { label: 'Đã nộp bài', color: 'cyan' },\\n  dang_cham: { label: 'Đang chấm', color: 'orange' },\\n  da_cham: { label: 'Đã chấm', color: 'gold' },\\n  cho_duyet: { label: 'Chờ duyệt', color: 'gold' },\\n  dat: { label: 'Đạt', color: 'green' },\\n  khong_dat: { label: 'Không đạt', color: 'red' },\\n};\\n\\nvar KET_QUA_MAP = {\\n  chua_co: { label: 'Chưa có', color: 'default' },\\n  chua_xac_dinh: { label: 'Chưa xác định', color: 'default' },\\n  dat: { label: 'Đạt', color: 'green' },\\n  khong_dat: { label: 'Không đạt', color: 'red' },\\n};\\n\\n// -- Top-level data loading -----------------------------------\\nasync function fetchKyThiList() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('ky_thi');\\n  res.setAppends(['de_thi', 'don_vi', 'nganh_nghe']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(200);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\n\\nfunction cleanEnumQuotes(val) {\\n  if (typeof val === 'string' && val.length >= 2 && val.charAt(0) === '\\"' && val.charAt(val.length - 1) === '\\"') {\\n    return val.slice(1, -1);\\n  }\\n  return val;\\n}\\n\\nasync function fetchAllThiSinh() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('ky_thi_thi_sinh');\\n  res.setAppends(['nguoi_lao_dong']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  var data = res.getData() || [];\\n  return data.map(function(r) {\\n    return Object.assign({}, r, {\\n      trang_thai: cleanEnumQuotes(r.trang_thai),\\n      ket_qua: cleanEnumQuotes(r.ket_qua),\\n    });\\n  });\\n}\\n\\nvar initialKyThi = await fetchKyThiList();\\nvar initialThiSinh = await fetchAllThiSinh();\\n\\n// -- Helper functions -----------------------------------------\\nfunction formatDate(d) {\\n  if (!d) return '—';\\n  var dt = new Date(d);\\n  var dd = String(dt.getDate()).padStart(2, '0');\\n  var mm = String(dt.getMonth() + 1).padStart(2, '0');\\n  var yyyy = dt.getFullYear();\\n  return dd + '/' + mm + '/' + yyyy;\\n}\\n\\nfunction formatDateTime(d) {\\n  if (!d) return '—';\\n  var dt = new Date(d);\\n  var dd = String(dt.getDate()).padStart(2, '0');\\n  var mm = String(dt.getMonth() + 1).padStart(2, '0');\\n  var yyyy = dt.getFullYear();\\n  var hh = String(dt.getHours()).padStart(2, '0');\\n  var mi = String(dt.getMinutes()).padStart(2, '0');\\n  return dd + '/' + mm + '/' + yyyy + ' ' + hh + ':' + mi;\\n}\\n\\nfunction getProgressInfo(kyThiId, allThiSinh) {\\n  var ts = allThiSinh.filter(function(s) { return s.ky_thi_id === kyThiId; });\\n  var total = ts.length;\\n  var graded = ts.filter(function(s) {\\n    return ['da_cham', 'cho_duyet', 'dat', 'khong_dat'].indexOf(s.trang_thai) !== -1;\\n  }).length;\\n  var passed = ts.filter(function(s) { return s.ket_qua === 'dat'; }).length;\\n  var failed = ts.filter(function(s) { return s.ket_qua === 'khong_dat'; }).length;\\n  return { total: total, graded: graded, passed: passed, failed: failed };\\n}\\n\\n// ============================================================\\n// A1: Danh sách kỳ thi cần chấm\\n// ============================================================\\nfunction A1_DanhSachKyThi({ kyThiList, allThiSinh, onNavigate, reloadAll }) {\\n  const [searchText, setSearchText] = useState('');\\n  const [hinhThucFilter, setHinhThucFilter] = useState(undefined);\\n  const [trangThaiFilter, setTrangThaiFilter] = useState(undefined);\\n  const [loading, setLoading] = useState(false);\\n  const [page, setPage] = useState(1);\\n  var pageSize = 20;\\n\\n  var stats = useMemo(function() {\\n    var choCham = 0, dangCham = 0, chamXong = 0, daDuyet = 0;\\n    kyThiList.forEach(function(kt) {\\n      var p = getProgressInfo(kt.id, allThiSinh);\\n      if (kt.trang_thai === 'dang_cham_diem' && p.graded === 0) choCham++;\\n      else if (kt.trang_thai === 'dang_cham_diem' && p.graded < p.total) dangCham++;\\n      else if (kt.trang_thai === 'dang_cham_diem' && p.graded >= p.total) chamXong++;\\n      else if (kt.trang_thai === 'hoan_thanh' || kt.trang_thai === 'da_phe_duyet') daDuyet++;\\n    });\\n    return { choCham: choCham, dangCham: dangCham, chamXong: chamXong, daDuyet: daDuyet };\\n  }, [kyThiList, allThiSinh]);\\n\\n  var relevantStatuses = ['dang_cham_diem', 'hoan_thanh', 'da_duyet', 'da_phe_duyet', 'dang_mo', 'dang_thi'];\\n\\n  var filteredData = useMemo(function() {\\n    var rows = kyThiList.filter(function(kt) {\\n      return relevantStatuses.indexOf(kt.trang_thai) !== -1 || getProgressInfo(kt.id, allThiSinh).total > 0;\\n    });\\n    if (searchText) {\\n      var lower = searchText.toLowerCase();\\n      rows = rows.filter(function(r) {\\n        return (r.ma_ky_thi && r.ma_ky_thi.toLowerCase().indexOf(lower) !== -1) ||\\n               (r.ten_ky_thi && r.ten_ky_thi.toLowerCase().indexOf(lower) !== -1);\\n      });\\n    }\\n    if (hinhThucFilter) {\\n      rows = rows.filter(function(r) { return r.hinh_thuc === hinhThucFilter; });\\n    }\\n    if (trangThaiFilter) {\\n      rows = rows.filter(function(r) { return r.trang_thai === trangThaiFilter; });\\n    }\\n    return rows;\\n  }, [kyThiList, allThiSinh, searchText, hinhThucFilter, trangThaiFilter]);\\n\\n  var pagedData = filteredData.slice((page - 1) * pageSize, page * pageSize);\\n\\n  var columns = [\\n    {\\n      title: 'Mã kỳ thi', dataIndex: 'ma_ky_thi', width: 120,\\n      render: function(v, r) {\\n        return <a onClick={() => onNavigate('detail', r)}>{v}</a>;\\n      },\\n    },\\n    { title: 'Tên kỳ thi', dataIndex: 'ten_ky_thi', ellipsis: true },\\n    {\\n      title: 'Hình thức', dataIndex: 'hinh_thuc', width: 120,\\n      render: function(v) {\\n        var m = HINH_THUC_MAP[v] || { label: v, color: 'default' };\\n        return <Tag color={m.color}>{m.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Đơn vị', width: 160, ellipsis: true,\\n      render: function(_, r) { return (r.don_vi && r.don_vi.ten_don_vi) || '—'; },\\n    },\\n    {\\n      title: 'Ngày thi', width: 110,\\n      render: function(_, r) { return formatDate(r.thoi_gian_bat_dau || r.ngay_thi); },\\n    },\\n    {\\n      title: 'Tiến độ chấm', width: 160,\\n      render: function(_, r) {\\n        var p = getProgressInfo(r.id, allThiSinh);\\n        if (p.total === 0) return <Text type=\\"secondary\\">Chưa có thí sinh</Text>;\\n        var pct = Math.round((p.graded / p.total) * 100);\\n        return (\\n          <Space direction=\\"vertical\\" size={2} style={{ width: '100%' }}>\\n            <Text>{p.graded}/{p.total} đã chấm</Text>\\n            <Progress percent={pct} size=\\"small\\" showInfo={false}\\n              strokeColor={pct >= 100 ? '#52c41a' : '#1890ff'} />\\n          </Space>\\n        );\\n      },\\n    },\\n    {\\n      title: '% Đạt', width: 80, align: 'center',\\n      render: function(_, r) {\\n        var p = getProgressInfo(r.id, allThiSinh);\\n        if (p.graded === 0) return '—';\\n        return Math.round((p.passed / p.graded) * 100) + '%';\\n      },\\n    },\\n    {\\n      title: 'Điểm đạt', dataIndex: 'diem_dat', width: 90, align: 'center',\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', width: 140,\\n      render: function(v) {\\n        var m = TRANG_THAI_KT_MAP[v] || { label: v, color: 'default' };\\n        return <Tag color={m.color}>{m.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Thao tác', width: 80, fixed: 'right',\\n      render: function(_, r) {\\n        return (\\n          <Space size={4}>\\n            <Tooltip title=\\"Chấm điểm\\">\\n              <Button icon={<EyeOutlined />}\\n                onClick={() => onNavigate('detail', r)} />\\n            </Tooltip>\\n          </Space>\\n        );\\n      },\\n    },\\n  ];\\n\\n  async function handleReload() {\\n    setLoading(true);\\n    await reloadAll();\\n    setLoading(false);\\n  }\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic title=\\"Chờ chấm\\" value={stats.choCham}\\n              valueStyle={{ color: '#faad14' }}\\n              prefix={<ClockCircleOutlined />} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic title=\\"Đang chấm\\" value={stats.dangCham}\\n              valueStyle={{ color: '#1890ff' }}\\n              prefix={<EditOutlined />} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic title=\\"Chấm xong\\" value={stats.chamXong}\\n              valueStyle={{ color: '#52c41a' }}\\n              prefix={<CheckCircleOutlined />} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic title=\\"Đã duyệt\\" value={stats.daDuyet}\\n              valueStyle={{ color: '#722ed1' }}\\n              prefix={<SafetyCertificateOutlined />} />\\n          </Card>\\n        </Col>\\n      </Row>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Row gutter={16} align=\\"middle\\" justify=\\"space-between\\">\\n          <Col flex=\\"auto\\">\\n            <Space size={12} wrap>\\n              <Input placeholder=\\"Tìm theo mã hoặc tên kỳ thi\\"\\n                prefix={<SearchOutlined />} allowClear style={{ width: 280 }}\\n                value={searchText}\\n                onChange={(e) => { setSearchText(e.target.value); setPage(1); }} />\\n              <Select placeholder=\\"Hình thức thi\\" allowClear style={{ width: 160 }}\\n                value={hinhThucFilter}\\n                onChange={(v) => { setHinhThucFilter(v); setPage(1); }}\\n                options={[\\n                  { label: 'Trực tuyến', value: 'truc_tuyen' },\\n                  { label: 'Bản cứng', value: 'ban_cung' },\\n                  { label: 'Kết hợp', value: 'ket_hop' },\\n                  { label: 'Trực tiếp', value: 'truc_tiep' },\\n                ]} />\\n              <Select placeholder=\\"Trạng thái\\" allowClear style={{ width: 180 }}\\n                value={trangThaiFilter}\\n                onChange={(v) => { setTrangThaiFilter(v); setPage(1); }}\\n                options={[\\n                  { label: 'Đang chấm điểm', value: 'dang_cham_diem' },\\n                  { label: 'Hoàn thành', value: 'hoan_thanh' },\\n                  { label: 'Đã duyệt', value: 'da_duyet' },\\n                  { label: 'Đã phê duyệt', value: 'da_phe_duyet' },\\n                  { label: 'Đang mở', value: 'dang_mo' },\\n                  { label: 'Đang thi', value: 'dang_thi' },\\n                ]} />\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Tooltip title=\\"Làm mới\\">\\n              <Button icon={<ReloadOutlined />} onClick={handleReload} />\\n            </Tooltip>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Card bordered>\\n        <Table rowKey=\\"id\\" columns={columns} dataSource={pagedData}\\n          pagination={false} scroll={{ x: 1200 }} size=\\"middle\\" />\\n        {filteredData.length > pageSize && (\\n          <div style={{ textAlign: 'right', marginTop: 16 }}>\\n            <Pagination current={page} total={filteredData.length}\\n              pageSize={pageSize} showSizeChanger={false} showTotal={(t) => 'Tổng: ' + t}\\n              onChange={(p) => setPage(p)} />\\n          </div>\\n        )}\\n      </Card>\\n    </Spin>\\n  );\\n}\\n\\n// ============================================================\\n// A2: Danh sách thí sinh trong kỳ thi\\n// ============================================================\\nfunction A2_DanhSachThiSinh({ kyThi, allThiSinh, onNavigate, onBack, reloadAll }) {\\n  const [loading, setLoading] = useState(false);\\n  const [statusFilter, setStatusFilter] = useState(undefined);\\n  const [searchText, setSearchText] = useState('');\\n  const [page, setPage] = useState(1);\\n  var pageSize = 20;\\n\\n  var thiSinhList = useMemo(function() {\\n    return allThiSinh.filter(function(s) { return s.ky_thi_id === kyThi.id; });\\n  }, [allThiSinh, kyThi.id]);\\n\\n  var filteredData = useMemo(function() {\\n    var rows = thiSinhList;\\n    if (statusFilter) {\\n      rows = rows.filter(function(s) { return s.trang_thai === statusFilter; });\\n    }\\n    if (searchText) {\\n      var lower = searchText.toLowerCase();\\n      rows = rows.filter(function(s) {\\n        var nld = s.nguoi_lao_dong || {};\\n        return (nld.ho_ten && nld.ho_ten.toLowerCase().indexOf(lower) !== -1) ||\\n               (nld.so_giay_to && nld.so_giay_to.toLowerCase().indexOf(lower) !== -1);\\n      });\\n    }\\n    return rows;\\n  }, [thiSinhList, statusFilter, searchText]);\\n\\n  var progress = useMemo(function() { return getProgressInfo(kyThi.id, allThiSinh); }, [kyThi.id, allThiSinh]);\\n\\n  var pagedData = filteredData.slice((page - 1) * pageSize, page * pageSize);\\n\\n  async function handleSaveScore(record, score) {\\n    try {\\n      var res = ctx.makeResource('SingleRecordResource');\\n      res.setResourceName('ky_thi_thi_sinh');\\n      res.setFilterByTk(record.id);\\n      var ketQua = score >= kyThi.diem_dat ? 'dat' : 'khong_dat';\\n      await res.save({ diem: score, ket_qua: ketQua, trang_thai: 'da_cham' });\\n      message.success('Đã lưu điểm: ' + score);\\n      await reloadAll();\\n    } catch (e) {\\n      message.error('Lỗi lưu điểm: ' + e.message);\\n    }\\n  }\\n\\n  function getScoreColor(score) {\\n    if (score == null) return undefined;\\n    var diemDat = kyThi.diem_dat || 5;\\n    if (score >= diemDat) return '#52c41a';\\n    var threshold = diemDat * 0.95;\\n    if (score >= threshold) return '#faad14';\\n    return '#ff4d4f';\\n  }\\n\\n  var columns = [\\n    {\\n      title: 'STT', width: 55, align: 'center',\\n      render: function(_, __, i) { return (page - 1) * pageSize + i + 1; },\\n    },\\n    {\\n      title: 'Họ tên', width: 180, ellipsis: true,\\n      render: function(_, r) {\\n        var nld = r.nguoi_lao_dong || {};\\n        return <a onClick={() => {\\n          if (kyThi.hinh_thuc === 'truc_tuyen') onNavigate('quiz', { thiSinh: r, kyThi: kyThi });\\n          else onNavigate('essay', { thiSinh: r, kyThi: kyThi });\\n        }}>{nld.ho_ten || '—'}</a>;\\n      },\\n    },\\n    {\\n      title: 'Số CCCD/Hộ chiếu', width: 140,\\n      render: function(_, r) { return (r.nguoi_lao_dong || {}).so_giay_to || '—'; },\\n    },\\n    {\\n      title: 'Lần thi', dataIndex: 'lan_thi', width: 80, align: 'center',\\n    },\\n    {\\n      title: 'Điểm', dataIndex: 'diem', width: 100, align: 'center',\\n      render: function(v, r) {\\n        if (v != null) {\\n          return <Text strong style={{ color: getScoreColor(v), fontSize: 16 }}>{v}</Text>;\\n        }\\n        var canEdit = ['da_nop_bai', 'da_nop', 'dang_cham'].indexOf(r.trang_thai) !== -1;\\n        if (canEdit) {\\n          return <InputNumber size=\\"small\\" min={0} max={10} step={0.5}\\n            style={{ width: 70 }}\\n            onPressEnter={(e) => handleSaveScore(r, Number(e.target.value))}\\n            onBlur={(e) => {\\n              if (e.target.value) handleSaveScore(r, Number(e.target.value));\\n            }}\\n            placeholder=\\"Nhập\\" />;\\n        }\\n        return <Text type=\\"secondary\\">—</Text>;\\n      },\\n    },\\n    {\\n      title: 'Kết quả', width: 110,\\n      render: function(_, r) {\\n        var m = KET_QUA_MAP[r.ket_qua] || { label: r.ket_qua || '—', color: 'default' };\\n        return <Tag color={m.color}>{m.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', width: 130,\\n      render: function(v) {\\n        var m = TRANG_THAI_TS_MAP[v] || { label: v, color: 'default' };\\n        return <Tag color={m.color}>{m.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Thao tác', width: 80, fixed: 'right',\\n      render: function(_, r) {\\n        return (\\n          <Space size={4}>\\n            <Tooltip title=\\"Xem bài làm\\">\\n              <Button icon={<EyeOutlined />}\\n                onClick={() => {\\n                  if (kyThi.hinh_thuc === 'truc_tuyen') onNavigate('quiz', { thiSinh: r, kyThi: kyThi });\\n                  else onNavigate('essay', { thiSinh: r, kyThi: kyThi });\\n                }} />\\n            </Tooltip>\\n          </Space>\\n        );\\n      },\\n    },\\n  ];\\n\\n  async function handleReload() {\\n    setLoading(true);\\n    await reloadAll();\\n    setLoading(false);\\n  }\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại danh sách kỳ thi\\n      </Button>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Descriptions column={{ xs: 1, sm: 2, md: 3 }} size=\\"small\\" bordered>\\n          <Descriptions.Item label=\\"Mã kỳ thi\\">{kyThi.ma_ky_thi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Tên kỳ thi\\">{kyThi.ten_ky_thi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Hình thức\\">\\n            {(() => { var m = HINH_THUC_MAP[kyThi.hinh_thuc] || { label: kyThi.hinh_thuc, color: 'default' }; return <Tag color={m.color}>{m.label}</Tag>; })()}\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Đề thi\\">{(kyThi.de_thi || {}).ten_de_thi || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Điểm đạt\\">{kyThi.diem_dat}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngày thi\\">{formatDate(kyThi.thoi_gian_bat_dau)}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Đơn vị\\">{(kyThi.don_vi || {}).ten_don_vi || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Tổng thí sinh\\">{progress.total}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Tiến độ chấm\\">\\n            <Text strong>{progress.graded}/{progress.total}</Text>\\n            {progress.total > 0 && <Text type=\\"secondary\\"> ({Math.round(progress.graded / progress.total * 100)}%)</Text>}\\n          </Descriptions.Item>\\n        </Descriptions>\\n      </Card>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Row gutter={16} align=\\"middle\\" justify=\\"space-between\\">\\n          <Col flex=\\"auto\\">\\n            <Space size={12} wrap>\\n              <Input placeholder=\\"Tìm theo họ tên hoặc CCCD\\"\\n                prefix={<SearchOutlined />} allowClear style={{ width: 280 }}\\n                value={searchText}\\n                onChange={(e) => { setSearchText(e.target.value); setPage(1); }} />\\n              <Select placeholder=\\"Trạng thái\\" allowClear style={{ width: 160 }}\\n                value={statusFilter}\\n                onChange={(v) => { setStatusFilter(v); setPage(1); }}\\n                options={[\\n                  { label: 'Chờ thi', value: 'cho_thi' },\\n                  { label: 'Đã nộp bài', value: 'da_nop_bai' },\\n                  { label: 'Đang chấm', value: 'dang_cham' },\\n                  { label: 'Đã chấm', value: 'da_cham' },\\n                  { label: 'Đạt', value: 'dat' },\\n                  { label: 'Không đạt', value: 'khong_dat' },\\n                ]} />\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Button icon={<AuditOutlined />}\\n                onClick={() => onNavigate('review', { kyThi: kyThi })}>\\n                Rà soát & duyệt\\n              </Button>\\n              <Button icon={<BarChartOutlined />}\\n                onClick={() => onNavigate('stats', { kyThi: kyThi })}>\\n                Thống kê\\n              </Button>\\n              {kyThi.hinh_thuc !== 'truc_tuyen' && (\\n                <Button icon={<UploadOutlined />}\\n                  onClick={() => onNavigate('upload', { kyThi: kyThi })}>\\n                  Upload bài\\n                </Button>\\n              )}\\n              <Tooltip title=\\"Làm mới\\">\\n                <Button icon={<ReloadOutlined />} onClick={handleReload} />\\n              </Tooltip>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Card bordered>\\n        <Table rowKey=\\"id\\" columns={columns} dataSource={pagedData}\\n          pagination={false} scroll={{ x: 1000 }} size=\\"middle\\" />\\n        {filteredData.length > pageSize && (\\n          <div style={{ textAlign: 'right', marginTop: 16 }}>\\n            <Pagination current={page} total={filteredData.length}\\n              pageSize={pageSize} showSizeChanger={false}\\n              showTotal={(t) => 'Tổng: ' + t} onChange={(p) => setPage(p)} />\\n          </div>\\n        )}\\n      </Card>\\n    </Spin>\\n  );\\n}\\n\\n// ============================================================\\n// A3: Chi tiết bài làm trắc nghiệm\\n// ============================================================\\nfunction A3_BaiTracNghiem({ thiSinh, kyThi, onBack, reloadAll }) {\\n  const [loading, setLoading] = useState(false);\\n  const [manualScore, setManualScore] = useState(thiSinh.diem);\\n  const [note, setNote] = useState('');\\n\\n  var nld = thiSinh.nguoi_lao_dong || {};\\n\\n  async function handleConfirmScore() {\\n    try {\\n      setLoading(true);\\n      var score = manualScore;\\n      if (score == null) { message.warning('Vui lòng nhập điểm'); return; }\\n      var res = ctx.makeResource('SingleRecordResource');\\n      res.setResourceName('ky_thi_thi_sinh');\\n      res.setFilterByTk(thiSinh.id);\\n      var ketQua = score >= kyThi.diem_dat ? 'dat' : 'khong_dat';\\n      await res.save({ diem: score, ket_qua: ketQua, trang_thai: 'da_cham', nhan_xet: note || undefined });\\n      message.success('Đã xác nhận điểm: ' + score + ' — ' + (ketQua === 'dat' ? 'Đạt' : 'Không đạt'));\\n      await reloadAll();\\n      onBack();\\n    } catch (e) {\\n      message.error('Lỗi: ' + e.message);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại danh sách thí sinh\\n      </Button>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Descriptions column={{ xs: 1, sm: 2, md: 3 }} size=\\"small\\" bordered\\n          title=\\"Thông tin thí sinh\\">\\n          <Descriptions.Item label=\\"Họ tên\\">{nld.ho_ten || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Số CCCD/Hộ chiếu\\">{nld.so_giay_to || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Giới tính\\">{nld.gioi_tinh === 'nam' ? 'Nam' : nld.gioi_tinh === 'nu' ? 'Nữ' : '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Kỳ thi\\">{kyThi.ma_ky_thi} — {kyThi.ten_ky_thi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Đề thi\\">{(kyThi.de_thi || {}).ten_de_thi || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Lần thi thứ\\">{thiSinh.lan_thi || 1}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Điểm đạt tối thiểu\\">{kyThi.diem_dat}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Trạng thái\\">\\n            {(() => { var m = TRANG_THAI_TS_MAP[thiSinh.trang_thai] || { label: thiSinh.trang_thai, color: 'default' }; return <Tag color={m.color}>{m.label}</Tag>; })()}\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Kết quả\\">\\n            {(() => { var m = KET_QUA_MAP[thiSinh.ket_qua] || { label: thiSinh.ket_qua || '—', color: 'default' }; return <Tag color={m.color}>{m.label}</Tag>; })()}\\n          </Descriptions.Item>\\n        </Descriptions>\\n      </Card>\\n\\n      <Card bordered style={{ marginBottom: 16 }} title=\\"Chấm điểm\\">\\n        <Alert\\n          message=\\"Chế độ trắc nghiệm trực tuyến\\"\\n          description=\\"Bài thi trắc nghiệm được chấm tự động. Cán bộ có thể điều chỉnh điểm nếu cần.\\"\\n          type=\\"info\\" showIcon style={{ marginBottom: 16 }} />\\n        <Row gutter={16}>\\n          <Col span={8}>\\n            <Text strong>Điểm hiện tại: </Text>\\n            <Text style={{ fontSize: 20, color: thiSinh.diem != null ? (thiSinh.diem >= kyThi.diem_dat ? '#52c41a' : '#ff4d4f') : '#999' }}>\\n              {thiSinh.diem != null ? thiSinh.diem : 'Chưa có'}\\n            </Text>\\n          </Col>\\n          <Col span={8}>\\n            <Space>\\n              <Text strong>Điểm thủ công:</Text>\\n              <InputNumber min={0} max={10} step={0.5}\\n                value={manualScore} onChange={setManualScore}\\n                style={{ width: 100 }} />\\n            </Space>\\n          </Col>\\n          <Col span={8}>\\n            <Text strong>Kết quả: </Text>\\n            {manualScore != null ? (\\n              <Tag color={manualScore >= kyThi.diem_dat ? 'green' : 'red'}>\\n                {manualScore >= kyThi.diem_dat ? 'Đạt' : 'Không đạt'}\\n              </Tag>\\n            ) : <Tag>Chưa xác định</Tag>}\\n          </Col>\\n        </Row>\\n        <Divider />\\n        <div style={{ marginBottom: 16 }}>\\n          <Text strong>Ghi chú cán bộ chấm:</Text>\\n          <Input.TextArea rows={3} value={note} onChange={(e) => setNote(e.target.value)}\\n            placeholder=\\"Nhập lý do điều chỉnh điểm (nếu có)\\" style={{ marginTop: 8 }} />\\n        </div>\\n        <Space>\\n          <Button type=\\"primary\\" icon={<CheckCircleOutlined />}\\n            onClick={handleConfirmScore} loading={loading}>\\n            Xác nhận điểm\\n          </Button>\\n          <Button onClick={onBack}>Quay lại</Button>\\n        </Space>\\n      </Card>\\n    </Spin>\\n  );\\n}\\n\\n// ============================================================\\n// A4: Chi tiết bài làm bản cứng / tự luận\\n// ============================================================\\nfunction A4_BaiBanCung({ thiSinh, kyThi, onBack, reloadAll }) {\\n  const [loading, setLoading] = useState(false);\\n  const [score, setScore] = useState(thiSinh.diem);\\n  const [note, setNote] = useState('');\\n\\n  var nld = thiSinh.nguoi_lao_dong || {};\\n\\n  async function handleConfirmScore() {\\n    try {\\n      setLoading(true);\\n      if (score == null) { message.warning('Vui lòng nhập điểm'); return; }\\n      var res = ctx.makeResource('SingleRecordResource');\\n      res.setResourceName('ky_thi_thi_sinh');\\n      res.setFilterByTk(thiSinh.id);\\n      var ketQua = score >= kyThi.diem_dat ? 'dat' : 'khong_dat';\\n      await res.save({ diem: score, ket_qua: ketQua, trang_thai: 'da_cham', nhan_xet: note || undefined });\\n      message.success('Đã xác nhận điểm');\\n      await reloadAll();\\n      onBack();\\n    } catch (e) {\\n      message.error('Lỗi: ' + e.message);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại danh sách thí sinh\\n      </Button>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Descriptions column={{ xs: 1, sm: 2, md: 3 }} size=\\"small\\" bordered\\n          title=\\"Thông tin thí sinh\\">\\n          <Descriptions.Item label=\\"Họ tên\\">{nld.ho_ten || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Số CCCD/Hộ chiếu\\">{nld.so_giay_to || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Kỳ thi\\">{kyThi.ma_ky_thi} — {kyThi.ten_ky_thi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Đề thi\\">{(kyThi.de_thi || {}).ten_de_thi || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Lần thi thứ\\">{thiSinh.lan_thi || 1}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Điểm đạt tối thiểu\\">{kyThi.diem_dat}</Descriptions.Item>\\n        </Descriptions>\\n      </Card>\\n\\n      <Row gutter={16}>\\n        <Col span={14}>\\n          <Card bordered title=\\"Bài làm\\" style={{ marginBottom: 16 }}>\\n            <Empty description=\\"Chưa có file bài làm. Sử dụng chức năng Upload bài để tải lên.\\"\\n              image={<FilePdfOutlined style={{ fontSize: 48, color: '#bbb' }} />}>\\n              <Button type=\\"link\\" icon={<UploadOutlined />} disabled>\\n                Tải file bài làm\\n              </Button>\\n            </Empty>\\n          </Card>\\n        </Col>\\n        <Col span={10}>\\n          <Card bordered title=\\"Chấm điểm\\" style={{ marginBottom: 16 }}>\\n            <div style={{ marginBottom: 16 }}>\\n              <Text strong>Nhập điểm:</Text>\\n              <InputNumber min={0} max={10} step={0.5}\\n                value={score} onChange={setScore}\\n                style={{ width: '100%', marginTop: 8 }} size=\\"large\\" />\\n            </div>\\n            {score != null && (\\n              <div style={{ marginBottom: 16 }}>\\n                <Text>Kết quả: </Text>\\n                <Tag color={score >= kyThi.diem_dat ? 'green' : 'red'} style={{ fontSize: 14 }}>\\n                  {score >= kyThi.diem_dat ? 'Đạt' : 'Không đạt'}\\n                </Tag>\\n              </div>\\n            )}\\n            <Divider />\\n            <div style={{ marginBottom: 16 }}>\\n              <Text strong>Ghi chú:</Text>\\n              <Input.TextArea rows={3} value={note} onChange={(e) => setNote(e.target.value)}\\n                placeholder=\\"Nhận xét bài làm\\" style={{ marginTop: 8 }} />\\n            </div>\\n            <Divider />\\n            <Button type=\\"default\\" icon={<RobotOutlined />}\\n              style={{ width: '100%', marginBottom: 12 }} disabled>\\n              AI chấm thử (đang phát triển)\\n            </Button>\\n            <Button type=\\"primary\\" icon={<CheckCircleOutlined />}\\n              onClick={handleConfirmScore} loading={loading} style={{ width: '100%' }}>\\n              Xác nhận điểm\\n            </Button>\\n          </Card>\\n        </Col>\\n      </Row>\\n    </Spin>\\n  );\\n}\\n\\n// ============================================================\\n// A5: Đối chiếu và rà soát\\n// ============================================================\\nfunction A5_RaSoat({ kyThi, allThiSinh, onNavigate, onBack, reloadAll }) {\\n  const [loading, setLoading] = useState(false);\\n  const [selectedRowKeys, setSelectedRowKeys] = useState([]);\\n\\n  var thiSinhList = useMemo(function() {\\n    return allThiSinh.filter(function(s) { return s.ky_thi_id === kyThi.id; });\\n  }, [allThiSinh, kyThi.id]);\\n\\n  var gradedList = useMemo(function() {\\n    return thiSinhList.filter(function(s) {\\n      return ['da_cham', 'cho_duyet', 'dat', 'khong_dat'].indexOf(s.trang_thai) !== -1;\\n    });\\n  }, [thiSinhList]);\\n\\n  var progress = getProgressInfo(kyThi.id, allThiSinh);\\n  var avgScore = gradedList.length > 0\\n    ? (gradedList.reduce(function(sum, s) { return sum + (s.diem || 0); }, 0) / gradedList.length).toFixed(1)\\n    : '—';\\n\\n  function getRowStyle(r) {\\n    if (r.diem == null) return { backgroundColor: '#fff1f0' };\\n    var diemDat = kyThi.diem_dat || 5;\\n    if (r.diem === 0 || r.diem === 10) return { backgroundColor: '#fff7e6' };\\n    var threshold = diemDat * 0.95;\\n    if (r.diem >= threshold && r.diem < diemDat) return { backgroundColor: '#fffbe6' };\\n    return {};\\n  }\\n\\n  async function handleApproveAll() {\\n    try {\\n      setLoading(true);\\n      for (var i = 0; i < gradedList.length; i++) {\\n        var s = gradedList[i];\\n        var res = ctx.makeResource('SingleRecordResource');\\n        res.setResourceName('ky_thi_thi_sinh');\\n        res.setFilterByTk(s.id);\\n        await res.save({ trang_thai: s.ket_qua === 'dat' ? 'dat' : 'khong_dat' });\\n      }\\n      var ktRes = ctx.makeResource('SingleRecordResource');\\n      ktRes.setResourceName('ky_thi');\\n      ktRes.setFilterByTk(kyThi.id);\\n      await ktRes.save({ trang_thai: 'hoan_thanh' });\\n      message.success('Đã duyệt toàn bộ kỳ thi');\\n      await reloadAll();\\n    } catch (e) {\\n      message.error('Lỗi: ' + e.message);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }\\n\\n  async function handleRegrade(record) {\\n    try {\\n      setLoading(true);\\n      var res = ctx.makeResource('SingleRecordResource');\\n      res.setResourceName('ky_thi_thi_sinh');\\n      res.setFilterByTk(record.id);\\n      await res.save({ trang_thai: 'dang_cham', diem: null, ket_qua: 'chua_co' });\\n      message.success('Đã yêu cầu chấm lại');\\n      await reloadAll();\\n    } catch (e) {\\n      message.error('Lỗi: ' + e.message);\\n    } finally {\\n      setLoading(false);\\n    }\\n  }\\n\\n  var columns = [\\n    {\\n      title: 'STT', width: 55, align: 'center',\\n      render: function(_, __, i) { return i + 1; },\\n    },\\n    {\\n      title: 'Họ tên', width: 180, ellipsis: true,\\n      render: function(_, r) { return (r.nguoi_lao_dong || {}).ho_ten || '—'; },\\n    },\\n    {\\n      title: 'Điểm', dataIndex: 'diem', width: 80, align: 'center',\\n      render: function(v) {\\n        if (v == null) return <Text type=\\"danger\\">Chưa chấm</Text>;\\n        return <Text strong style={{ color: v >= kyThi.diem_dat ? '#52c41a' : '#ff4d4f' }}>{v}</Text>;\\n      },\\n    },\\n    {\\n      title: 'Kết quả', width: 110,\\n      render: function(_, r) {\\n        var m = KET_QUA_MAP[r.ket_qua] || { label: '—', color: 'default' };\\n        return <Tag color={m.color}>{m.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai', width: 120,\\n      render: function(v) {\\n        var m = TRANG_THAI_TS_MAP[v] || { label: v, color: 'default' };\\n        return <Tag color={m.color}>{m.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Thao tác', width: 120, fixed: 'right',\\n      render: function(_, r) {\\n        return (\\n          <Space size={4}>\\n            <Tooltip title=\\"Xem bài\\">\\n              <Button icon={<EyeOutlined />}\\n                onClick={() => {\\n                  if (kyThi.hinh_thuc === 'truc_tuyen') onNavigate('quiz', { thiSinh: r, kyThi: kyThi });\\n                  else onNavigate('essay', { thiSinh: r, kyThi: kyThi });\\n                }} />\\n            </Tooltip>\\n            <Popconfirm title=\\"Yêu cầu chấm lại thí sinh này?\\"\\n              onConfirm={() => handleRegrade(r)}\\n              okText=\\"Đồng ý\\" cancelText=\\"Hủy\\">\\n              <Tooltip title=\\"Chấm lại\\">\\n                <Button danger icon={<ReloadOutlined />} />\\n              </Tooltip>\\n            </Popconfirm>\\n          </Space>\\n        );\\n      },\\n    },\\n  ];\\n\\n  var allGraded = progress.graded >= progress.total && progress.total > 0;\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại danh sách thí sinh\\n      </Button>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Row gutter={16}>\\n          <Col span={6}>\\n            <Statistic title=\\"Tổng thí sinh\\" value={progress.total} />\\n          </Col>\\n          <Col span={6}>\\n            <Statistic title=\\"Đã chấm\\" value={progress.graded}\\n              suffix={'/ ' + progress.total} />\\n          </Col>\\n          <Col span={6}>\\n            <Statistic title=\\"% Đạt\\"\\n              value={progress.graded > 0 ? Math.round(progress.passed / progress.graded * 100) : 0}\\n              suffix=\\"%\\" valueStyle={{ color: '#52c41a' }} />\\n          </Col>\\n          <Col span={6}>\\n            <Statistic title=\\"Điểm TB\\" value={avgScore} />\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Table rowKey=\\"id\\" columns={columns} dataSource={thiSinhList}\\n          pagination={false} size=\\"middle\\"\\n          rowClassName={function(r) {\\n            if (r.diem == null) return '';\\n            var diemDat = kyThi.diem_dat || 5;\\n            if (r.diem === 0 || r.diem >= 10) return '';\\n            return '';\\n          }}\\n          onRow={function(r) {\\n            return { style: getRowStyle(r) };\\n          }} />\\n      </Card>\\n\\n      <Card bordered>\\n        <Space>\\n          <Popconfirm\\n            title=\\"Duyệt toàn bộ kỳ thi?\\"\\n            description=\\"Sau khi duyệt, trạng thái kỳ thi sẽ chuyển thành 'Hoàn thành' và thí sinh đạt sẽ được đề xuất nâng bậc.\\"\\n            onConfirm={handleApproveAll}\\n            okText=\\"Xác nhận duyệt\\" cancelText=\\"Hủy\\"\\n            disabled={!allGraded}>\\n            <Button type=\\"primary\\" icon={<SafetyCertificateOutlined />}\\n              disabled={!allGraded} size=\\"large\\">\\n              Duyệt toàn bộ kỳ thi\\n            </Button>\\n          </Popconfirm>\\n          {!allGraded && (\\n            <Text type=\\"warning\\">\\n              <ExclamationCircleOutlined /> Còn {progress.total - progress.graded} thí sinh chưa chấm\\n            </Text>\\n          )}\\n        </Space>\\n      </Card>\\n    </Spin>\\n  );\\n}\\n\\n// ============================================================\\n// A6: Thống kê kỳ thi\\n// ============================================================\\nfunction A6_ThongKe({ kyThi, allThiSinh, onBack }) {\\n  var thiSinhList = useMemo(function() {\\n    return allThiSinh.filter(function(s) { return s.ky_thi_id === kyThi.id; });\\n  }, [allThiSinh, kyThi.id]);\\n\\n  var gradedList = thiSinhList.filter(function(s) { return s.diem != null; });\\n  var scores = gradedList.map(function(s) { return s.diem || 0; });\\n\\n  var statsData = useMemo(function() {\\n    if (scores.length === 0) return { avg: 0, max: 0, min: 0, stdDev: 0, passed: 0, failed: 0 };\\n    var sum = scores.reduce(function(a, b) { return a + b; }, 0);\\n    var avg = sum / scores.length;\\n    var maxS = Math.max.apply(null, scores);\\n    var minS = Math.min.apply(null, scores);\\n    var variance = scores.reduce(function(a, b) { return a + Math.pow(b - avg, 2); }, 0) / scores.length;\\n    var stdDev = Math.sqrt(variance);\\n    var passed = gradedList.filter(function(s) { return s.ket_qua === 'dat'; }).length;\\n    var failed = gradedList.filter(function(s) { return s.ket_qua === 'khong_dat'; }).length;\\n    return { avg: avg.toFixed(1), max: maxS, min: minS, stdDev: stdDev.toFixed(2), passed: passed, failed: failed };\\n  }, [scores, gradedList]);\\n\\n  var distribution = useMemo(function() {\\n    var bins = [\\n      { range: '0 – 2', count: 0 },\\n      { range: '2 – 4', count: 0 },\\n      { range: '4 – 6', count: 0 },\\n      { range: '6 – 8', count: 0 },\\n      { range: '8 – 10', count: 0 },\\n    ];\\n    scores.forEach(function(s) {\\n      if (s < 2) bins[0].count++;\\n      else if (s < 4) bins[1].count++;\\n      else if (s < 6) bins[2].count++;\\n      else if (s < 8) bins[3].count++;\\n      else bins[4].count++;\\n    });\\n    return bins;\\n  }, [scores]);\\n\\n  var maxCount = Math.max.apply(null, distribution.map(function(b) { return b.count; })) || 1;\\n\\n  return (\\n    <div>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại danh sách thí sinh\\n      </Button>\\n\\n      <Card bordered style={{ marginBottom: 16 }}\\n        title={'Thống kê: ' + kyThi.ma_ky_thi + ' — ' + kyThi.ten_ky_thi}>\\n\\n        {gradedList.length === 0 ? (\\n          <Empty description=\\"Chưa có dữ liệu chấm điểm\\" />\\n        ) : (\\n          <>\\n            <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>\\n              <Col xs={12} sm={8} md={4}>\\n                <Statistic title=\\"Tổng thí sinh\\" value={thiSinhList.length} />\\n              </Col>\\n              <Col xs={12} sm={8} md={4}>\\n                <Statistic title=\\"Đã chấm\\" value={gradedList.length} />\\n              </Col>\\n              <Col xs={12} sm={8} md={4}>\\n                <Statistic title=\\"Đạt\\" value={statsData.passed}\\n                  valueStyle={{ color: '#52c41a' }} />\\n              </Col>\\n              <Col xs={12} sm={8} md={4}>\\n                <Statistic title=\\"Không đạt\\" value={statsData.failed}\\n                  valueStyle={{ color: '#ff4d4f' }} />\\n              </Col>\\n              <Col xs={12} sm={8} md={4}>\\n                <Statistic title=\\"Điểm TB\\" value={statsData.avg} />\\n              </Col>\\n              <Col xs={12} sm={8} md={4}>\\n                <Statistic title=\\"Cao nhất / Thấp nhất\\"\\n                  value={statsData.max + ' / ' + statsData.min} />\\n              </Col>\\n            </Row>\\n\\n            <Divider>Tỷ lệ đạt / không đạt</Divider>\\n            <Row gutter={16} style={{ marginBottom: 24 }}>\\n              <Col span={12}>\\n                <div style={{ textAlign: 'center' }}>\\n                  <Progress type=\\"circle\\" percent={Math.round(statsData.passed / gradedList.length * 100)}\\n                    format={(p) => p + '% Đạt'}\\n                    strokeColor=\\"#52c41a\\" size={160} />\\n                </div>\\n              </Col>\\n              <Col span={12}>\\n                <div style={{ textAlign: 'center' }}>\\n                  <Progress type=\\"circle\\" percent={Math.round(statsData.failed / gradedList.length * 100)}\\n                    format={(p) => p + '% Không đạt'}\\n                    strokeColor=\\"#ff4d4f\\" size={160} />\\n                </div>\\n              </Col>\\n            </Row>\\n\\n            <Divider>Phân bố điểm</Divider>\\n            <div style={{ marginBottom: 24 }}>\\n              {distribution.map(function(bin, i) {\\n                var pct = Math.round((bin.count / maxCount) * 100);\\n                return (\\n                  <Row key={i} gutter={8} align=\\"middle\\" style={{ marginBottom: 8 }}>\\n                    <Col span={4} style={{ textAlign: 'right' }}>\\n                      <Text>{bin.range}</Text>\\n                    </Col>\\n                    <Col span={16}>\\n                      <div style={{\\n                        height: 28,\\n                        width: pct + '%',\\n                        minWidth: bin.count > 0 ? 24 : 0,\\n                        backgroundColor: i < 2 ? '#ff4d4f' : i < 3 ? '#faad14' : '#52c41a',\\n                        borderRadius: 4,\\n                        display: 'flex', alignItems: 'center', justifyContent: 'center',\\n                      }}>\\n                        {bin.count > 0 && <Text style={{ color: '#fff', fontSize: 12 }}>{bin.count}</Text>}\\n                      </div>\\n                    </Col>\\n                    <Col span={4}>\\n                      <Text type=\\"secondary\\">{bin.count} thí sinh</Text>\\n                    </Col>\\n                  </Row>\\n                );\\n              })}\\n            </div>\\n\\n            <Divider>Độ lệch chuẩn</Divider>\\n            <Text>Độ lệch chuẩn: <Text strong>{statsData.stdDev}</Text></Text>\\n          </>\\n        )}\\n      </Card>\\n    </div>\\n  );\\n}\\n\\n// ============================================================\\n// A7: Upload bài bản cứng\\n// ============================================================\\nfunction A7_UploadBai({ kyThi, allThiSinh, onBack }) {\\n  var thiSinhList = useMemo(function() {\\n    return allThiSinh.filter(function(s) { return s.ky_thi_id === kyThi.id; });\\n  }, [allThiSinh, kyThi.id]);\\n\\n  return (\\n    <div>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại danh sách thí sinh\\n      </Button>\\n\\n      <Card bordered style={{ marginBottom: 16 }}\\n        title={'Upload bài: ' + kyThi.ma_ky_thi + ' — ' + kyThi.ten_ky_thi}>\\n\\n        <Alert\\n          message=\\"Chức năng upload và gắn file bài làm\\"\\n          description=\\"Tải lên file PDF/ảnh bài làm bản cứng, sau đó gắn cho từng thí sinh.\\"\\n          type=\\"info\\" showIcon style={{ marginBottom: 16 }} />\\n\\n        <Card type=\\"inner\\" title=\\"Tải lên bài làm\\" style={{ marginBottom: 16 }}>\\n          <Upload.Dragger\\n            multiple accept=\\".pdf,.jpg,.jpeg,.png\\"\\n            beforeUpload={() => false}\\n            disabled>\\n            <p className=\\"ant-upload-drag-icon\\">\\n              <InboxOutlined />\\n            </p>\\n            <p className=\\"ant-upload-text\\">Kéo thả hoặc nhấn để chọn file</p>\\n            <p className=\\"ant-upload-hint\\">Hỗ trợ PDF, JPG, PNG. Tối đa 20 file cùng lúc.</p>\\n          </Upload.Dragger>\\n        </Card>\\n\\n        <Card type=\\"inner\\" title=\\"Kiểm tra chất lượng AI\\" style={{ marginBottom: 16 }}>\\n          <Button icon={<RobotOutlined />} disabled>\\n            AI kiểm tra chất lượng (đang phát triển)\\n          </Button>\\n          <Text type=\\"secondary\\" style={{ marginLeft: 12 }}>\\n            Tự động kiểm tra độ nét, chiều file, số trang\\n          </Text>\\n        </Card>\\n\\n        <Card type=\\"inner\\" title=\\"Thí sinh chưa có bài\\">\\n          <Table rowKey=\\"id\\" size=\\"small\\" pagination={false}\\n            dataSource={thiSinhList}\\n            columns={[\\n              {\\n                title: 'Họ tên', render: function(_, r) { return (r.nguoi_lao_dong || {}).ho_ten || '—'; },\\n              },\\n              {\\n                title: 'Số CCCD', render: function(_, r) { return (r.nguoi_lao_dong || {}).so_giay_to || '—'; },\\n              },\\n              { title: 'Trạng thái', dataIndex: 'trang_thai',\\n                render: function(v) { var m = TRANG_THAI_TS_MAP[v] || { label: v, color: 'default' }; return <Tag color={m.color}>{m.label}</Tag>; },\\n              },\\n              { title: 'File bài làm', render: function() { return <Text type=\\"secondary\\">Chưa có</Text>; } },\\n            ]} />\\n        </Card>\\n      </Card>\\n    </div>\\n  );\\n}\\n\\n// ============================================================\\n// Main Router Component\\n// ============================================================\\nfunction ChamDiemBlock({ initKyThi, initThiSinh }) {\\n  const [kyThiList, setKyThiList] = useState(initKyThi);\\n  const [allThiSinhData, setAllThiSinhData] = useState(initThiSinh);\\n  const [view, setView] = useState({ name: 'list', data: null });\\n  const [history, setHistory] = useState([]);\\n\\n  var reloadAll = useCallback(async function() {\\n    var kt = await fetchKyThiList();\\n    var ts = await fetchAllThiSinh();\\n    setKyThiList(kt);\\n    setAllThiSinhData(ts);\\n  }, []);\\n\\n  function navigate(viewName, data) {\\n    setHistory(function(prev) { return prev.concat([view]); });\\n    setView({ name: viewName, data: data });\\n  }\\n\\n  function goBack() {\\n    setHistory(function(prev) {\\n      if (prev.length === 0) {\\n        setView({ name: 'list', data: null });\\n        return [];\\n      }\\n      var newHistory = prev.slice(0, -1);\\n      setView(prev[prev.length - 1]);\\n      return newHistory;\\n    });\\n  }\\n\\n  if (view.name === 'list') {\\n    return <A1_DanhSachKyThi kyThiList={kyThiList} allThiSinh={allThiSinhData}\\n      onNavigate={navigate} reloadAll={reloadAll} />;\\n  }\\n\\n  if (view.name === 'detail') {\\n    var kyThiRecord = kyThiList.find(function(kt) { return kt.id === view.data.id; }) || view.data;\\n    return <A2_DanhSachThiSinh kyThi={kyThiRecord} allThiSinh={allThiSinhData}\\n      onNavigate={navigate} onBack={goBack} reloadAll={reloadAll} />;\\n  }\\n\\n  if (view.name === 'quiz') {\\n    var thiSinhRecord = allThiSinhData.find(function(s) { return s.id === view.data.thiSinh.id; }) || view.data.thiSinh;\\n    return <A3_BaiTracNghiem thiSinh={thiSinhRecord} kyThi={view.data.kyThi}\\n      onBack={goBack} reloadAll={reloadAll} />;\\n  }\\n\\n  if (view.name === 'essay') {\\n    var thiSinhRecordE = allThiSinhData.find(function(s) { return s.id === view.data.thiSinh.id; }) || view.data.thiSinh;\\n    return <A4_BaiBanCung thiSinh={thiSinhRecordE} kyThi={view.data.kyThi}\\n      onBack={goBack} reloadAll={reloadAll} />;\\n  }\\n\\n  if (view.name === 'review') {\\n    var kyThiReview = kyThiList.find(function(kt) { return kt.id === view.data.kyThi.id; }) || view.data.kyThi;\\n    return <A5_RaSoat kyThi={kyThiReview} allThiSinh={allThiSinhData}\\n      onNavigate={navigate} onBack={goBack} reloadAll={reloadAll} />;\\n  }\\n\\n  if (view.name === 'stats') {\\n    var kyThiStats = kyThiList.find(function(kt) { return kt.id === view.data.kyThi.id; }) || view.data.kyThi;\\n    return <A6_ThongKe kyThi={kyThiStats} allThiSinh={allThiSinhData}\\n      onBack={goBack} />;\\n  }\\n\\n  if (view.name === 'upload') {\\n    var kyThiUpload = kyThiList.find(function(kt) { return kt.id === view.data.kyThi.id; }) || view.data.kyThi;\\n    return <A7_UploadBai kyThi={kyThiUpload} allThiSinh={allThiSinhData}\\n      onBack={goBack} />;\\n  }\\n\\n  return <A1_DanhSachKyThi kyThiList={kyThiList} allThiSinh={allThiSinhData}\\n    onNavigate={navigate} reloadAll={reloadAll} />;\\n}\\n\\n// -- Render ---------------------------------------------------\\nctx.render(<ChamDiemBlock initKyThi={initialKyThi} initThiSinh={initialThiSinh} />);\\n"}},"__flowSurfaceMeta":{"declaredKey":"chamDiemDanhGiaJsV4"}}}
