bfnrd4vvzlf	bfnrd4vvzlf	{"parentId":"hxllnz4k87n","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v1","code":"const { Alert, Button, Card, Descriptions, Drawer, Form, Input, InputNumber, Modal, Popconfirm, Select, Space, Table, Tag, Tooltip, Typography } = ctx.libs.antd;\\nconst { PlusOutlined, EditOutlined, EyeOutlined, DeleteOutlined, SearchOutlined, ReloadOutlined, UserOutlined } = ctx.libs.antdIcons;\\nconst { useState, useMemo, useCallback } = ctx.React;\\n\\nconst STATUS_OPTIONS = [\\n  { value: 'du_kien', label: 'Dự kiến', color: 'gold' },\\n  { value: 'dang_hoc', label: 'Đang học', color: 'blue' },\\n  { value: 'hoan_thanh', label: 'Hoàn thành', color: 'green' },\\n  { value: 'huy', label: 'Đã hủy', color: 'red' },\\n];\\nconst STATUS_MAP = Object.fromEntries(STATUS_OPTIONS.map((s) => [s.value, s]));\\nconst HINH_THUC = 'truc_tiep';\\nconst ROLE_GIANG_VIEN = 3;\\nconst ROLE_HOC_VIEN = 4;\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('lop_hoc');\\n  ctx.resource.setFilter({ hinh_thuc: { $eq: HINH_THUC }, is_deleted: { $ne: true } });\\n  ctx.resource.setAppends(['don_vi', 'giang_vien_nld', 'khoa_huan_luyen', 'hoc_vien_lop', 'hoc_vien_lop.nguoi_lao_dong']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(200);\\n  await ctx.resource.refresh();\\n  const initialRows = ctx.resource.getData() || [];\\n  const initialTotal = ctx.resource.getMeta?.()?.count ?? initialRows.length;\\n\\n  const donViRes = ctx.makeResource('MultiRecordResource');\\n  donViRes.setResourceName('don_vi');\\n  donViRes.setPageSize(500);\\n  await donViRes.refresh();\\n  const donViList = donViRes.getData() || [];\\n\\n  const khoaRes = ctx.makeResource('MultiRecordResource');\\n  khoaRes.setResourceName('khoa_huan_luyen');\\n  khoaRes.setPageSize(500);\\n  await khoaRes.refresh();\\n  const khoaList = khoaRes.getData() || [];\\n\\n  const gvCandRes = ctx.makeResource('MultiRecordResource');\\n  gvCandRes.setResourceName('nguoi_lao_dong');\\n  gvCandRes.setFilter({ 'vai_tro.id': { $in: [ROLE_GIANG_VIEN] } });\\n  gvCandRes.setPageSize(500);\\n  await gvCandRes.refresh();\\n  const giangVienCandidates = gvCandRes.getData() || [];\\n\\n  const bacThoRes = ctx.makeResource('MultiRecordResource');\\n  bacThoRes.setResourceName('bac_tho');\\n  bacThoRes.setSort(['thu_tu']);\\n  bacThoRes.setPageSize(50);\\n  await bacThoRes.refresh();\\n  const bacThoList = bacThoRes.getData() || [];\\n\\n  const hvCandRes = ctx.makeResource('MultiRecordResource');\\n  hvCandRes.setResourceName('nguoi_lao_dong');\\n  hvCandRes.setFilter({ 'vai_tro.id': { $in: [ROLE_HOC_VIEN] } });\\n  hvCandRes.setAppends(['bac_tho']);\\n  hvCandRes.setPageSize(500);\\n  await hvCandRes.refresh();\\n  const hocVienCandidates = hvCandRes.getData() || [];\\n\\n  const crudRes = ctx.makeResource('MultiRecordResource');\\n  crudRes.setResourceName('lop_hoc');\\n\\n  const hvlRes = ctx.makeResource('MultiRecordResource');\\n  hvlRes.setResourceName('hoc_vien_lop');\\n\\n  async function fetchRows() {\\n    crudRes.setFilter({ hinh_thuc: { $eq: HINH_THUC }, is_deleted: { $ne: true } });\\n    crudRes.setAppends(['don_vi', 'giang_vien_nld', 'khoa_huan_luyen', 'hoc_vien_lop', 'hoc_vien_lop.nguoi_lao_dong']);\\n    crudRes.setSort(['-createdAt']);\\n    crudRes.setPageSize(200);\\n    await crudRes.refresh();\\n    return { rows: crudRes.getData() || [], count: crudRes.getMeta?.()?.count ?? 0 };\\n  }\\n\\n  async function deleteRow(id) {\\n    await crudRes.destroy(id);\\n  }\\n\\n  async function createRow(values) {\\n    await crudRes.create(values);\\n  }\\n\\n  async function updateRow(id, values) {\\n    await crudRes.update(id, values);\\n  }\\n\\n  async function setGiangVienAssoc(lopHocId, nguoiLaoDongIds) {\\n    await ctx.request({\\n      url: 'lop_hoc/' + lopHocId + '/giang_vien_nld:set',\\n      method: 'post',\\n      data: nguoiLaoDongIds.map(function(x) { return Number(x); }),\\n    });\\n  }\\n\\n  async function syncHocVienAssoc(lopHocId, selectedIds, currentHvl) {\\n    var currentNldIds = (currentHvl || []).map(function(h) { return String(h.nguoiLaoDongId); });\\n    var selStr = selectedIds.map(function(x) { return String(x); });\\n    var toAdd = selStr.filter(function(id) { return currentNldIds.indexOf(id) === -1; });\\n    var toRemove = (currentHvl || []).filter(function(h) { return selStr.indexOf(String(h.nguoiLaoDongId)) === -1; });\\n    for (var i = 0; i < toAdd.length; i++) {\\n      await hvlRes.create({ lopHocId: Number(lopHocId), nguoiLaoDongId: Number(toAdd[i]), trang_thai: 'dang_hoc' });\\n    }\\n    for (var j = 0; j < toRemove.length; j++) {\\n      await hvlRes.destroy(toRemove[j].id);\\n    }\\n  }\\n\\n  function formatDate(val) {\\n    if (!val) return '-';\\n    try {\\n      var d = new Date(val);\\n      if (isNaN(d.getTime())) return val;\\n      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();\\n    } catch (e) {\\n      return val;\\n    }\\n  }\\n\\n  function getGiangVienNames(record) {\\n    if (record.giang_vien_nld && record.giang_vien_nld.length > 0) {\\n      return record.giang_vien_nld.map(function(gv) { return gv.ho_ten || gv.name || '-'; }).join(', ');\\n    }\\n    return record.giang_vien || '-';\\n  }\\n\\n  function getHocVienNames(record) {\\n    if (record.hoc_vien_lop && record.hoc_vien_lop.length > 0) {\\n      return record.hoc_vien_lop.map(function(h) { return h.nguoi_lao_dong?.ho_ten || '-'; }).join(', ');\\n    }\\n    return '-';\\n  }\\n\\n  function getHocVienCount(record) {\\n    return (record.hoc_vien_lop || []).length;\\n  }\\n\\n  function PersonPicker(props) {\\n    var title = props.title;\\n    var people = props.people;\\n    var selectedIds = props.selectedIds || [];\\n    var onChange = props.onChange;\\n    var bacThoOptions = props.bacThoOptions;\\n\\n    const [open, setOpen] = useState(false);\\n    const [search, setSearch] = useState('');\\n    const [filterBacTho, setFilterBacTho] = useState(undefined);\\n    const [tempSelected, setTempSelected] = useState([]);\\n\\n    var handleOpen = useCallback(function() {\\n      setTempSelected(selectedIds.map(function(x) { return Number(x); }));\\n      setSearch('');\\n      setFilterBacTho(undefined);\\n      setOpen(true);\\n    }, [selectedIds]);\\n\\n    var handleConfirm = useCallback(function() {\\n      onChange(tempSelected);\\n      setOpen(false);\\n    }, [tempSelected, onChange]);\\n\\n    var sorted = useMemo(function() {\\n      if (!bacThoOptions) return people;\\n      return people.slice().sort(function(a, b) {\\n        var aOrder = a.bac_tho?.thu_tu ?? 9999;\\n        var bOrder = b.bac_tho?.thu_tu ?? 9999;\\n        return aOrder - bOrder;\\n      });\\n    }, [people, bacThoOptions]);\\n\\n    var filtered = useMemo(function() {\\n      var list = sorted;\\n      if (filterBacTho != null) {\\n        list = list.filter(function(p) { return p.bacThoId === filterBacTho; });\\n      }\\n      if (search) {\\n        var s = search.toLowerCase();\\n        list = list.filter(function(p) { return (p.ho_ten || '').toLowerCase().includes(s); });\\n      }\\n      return list;\\n    }, [sorted, search, filterBacTho]);\\n\\n    var selectedNames = useMemo(function() {\\n      return selectedIds.map(function(id) {\\n        var p = people.find(function(x) { return String(x.id) === String(id); });\\n        return p ? p.ho_ten : String(id);\\n      });\\n    }, [selectedIds, people]);\\n\\n    var pickerColumns = [\\n      { title: ctx.t('Họ và tên'), dataIndex: 'ho_ten', key: 'ho_ten', render: function(val) { return val || '-'; } },\\n    ];\\n    if (bacThoOptions) {\\n      pickerColumns.push({\\n        title: ctx.t('Bậc thợ'), key: 'bac_tho', width: 160,\\n        render: function(_, record) { return record.bac_tho?.ten_bac || '-'; },\\n      });\\n    }\\n\\n    return (\\n      <>\\n        <div\\n          onClick={handleOpen}\\n          style={{ border: '1px solid #d9d9d9', borderRadius: 6, padding: '4px 8px', minHeight: 32, cursor: 'pointer', display: 'flex', flexWrap: 'wrap', gap: 4, alignItems: 'center', background: '#fff' }}\\n        >\\n          {selectedNames.length > 0\\n            ? selectedNames.map(function(name, i) { return <Tag key={i} color=\\"blue\\">{name}</Tag>; })\\n            : <span style={{ color: '#bfbfbf' }}>{ctx.t('Ấn để chọn...')}</span>\\n          }\\n        </div>\\n        <Modal\\n          title={title}\\n          open={open}\\n          onOk={handleConfirm}\\n          onCancel={function() { setOpen(false); }}\\n          width={bacThoOptions ? 640 : 560}\\n          okText={ctx.t('Xác nhận')}\\n          cancelText={ctx.t('Hủy')}\\n        >\\n          <Space style={{ marginBottom: 12, width: '100%' }} direction=\\"vertical\\" size={8}>\\n            <Input\\n              placeholder={ctx.t('Tìm kiếm theo tên...')}\\n              prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n              allowClear\\n              onChange={function(e) { setSearch(e.target.value); }}\\n              value={search}\\n            />\\n            {bacThoOptions && (\\n              <Select\\n                allowClear\\n                showSearch\\n                optionFilterProp=\\"label\\"\\n                placeholder={ctx.t('Lọc theo bậc thợ')}\\n                style={{ width: '100%' }}\\n                value={filterBacTho}\\n                onChange={function(val) { setFilterBacTho(val); }}\\n                options={bacThoOptions.map(function(b) { return { value: b.id, label: b.ten_bac }; })}\\n              />\\n            )}\\n          </Space>\\n          <Table\\n            dataSource={filtered}\\n            rowKey=\\"id\\"\\n            size=\\"small\\"\\n            scroll={{ y: 300 }}\\n            pagination={false}\\n            rowSelection={{ selectedRowKeys: tempSelected, onChange: function(keys) { setTempSelected(keys); } }}\\n            columns={pickerColumns}\\n          />\\n          <div style={{ marginTop: 8, color: '#8c8c8c', fontSize: 12 }}>\\n            {ctx.t('Đã chọn')}: {tempSelected.length} / {people.length}\\n          </div>\\n        </Modal>\\n      </>\\n    );\\n  }\\n\\n  function TableApp() {\\n    const [rows, setRows] = useState(initialRows);\\n    const [totalCount, setTotalCount] = useState(initialTotal);\\n    const [searchText, setSearchText] = useState('');\\n    const [currentPage, setCurrentPage] = useState(1);\\n    const [loading, setLoading] = useState(false);\\n    const [viewRecord, setViewRecord] = useState(null);\\n    const [formOpen, setFormOpen] = useState(false);\\n    const [editingId, setEditingId] = useState(null);\\n    const [editingRecord, setEditingRecord] = useState(null);\\n    const [formLoading, setFormLoading] = useState(false);\\n    const [selectedGV, setSelectedGV] = useState([]);\\n    const [selectedHV, setSelectedHV] = useState([]);\\n    const [form] = Form.useForm();\\n    var pageSize = 10;\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var result = await fetchRows();\\n        setRows(result.rows);\\n        setTotalCount(result.count || result.rows.length);\\n      } catch (e) {\\n        ctx.message.error(String(e?.message || e));\\n      }\\n      setLoading(false);\\n    }, []);\\n\\n    var handleDelete = useCallback(async function(id) {\\n      try {\\n        await deleteRow(id);\\n        ctx.message.success(ctx.t('Đã xóa thành công'));\\n        refreshData();\\n      } catch (e) {\\n        ctx.message.error(String(e?.message || e));\\n      }\\n    }, [refreshData]);\\n\\n    var openCreate = useCallback(function() {\\n      setEditingId(null);\\n      setEditingRecord(null);\\n      form.resetFields();\\n      form.setFieldsValue({ hinh_thuc: HINH_THUC, trang_thai: 'du_kien' });\\n      setSelectedGV([]);\\n      setSelectedHV([]);\\n      setFormOpen(true);\\n    }, [form]);\\n\\n    var openEdit = useCallback(function(record) {\\n      setEditingId(record.id);\\n      setEditingRecord(record);\\n      form.resetFields();\\n      form.setFieldsValue({\\n        ten_lop: record.ten_lop,\\n        si_so_toi_da: record.si_so_toi_da,\\n        don_vi_id: record.don_vi_id ? String(record.don_vi_id) : undefined,\\n        khoaHuanLuyenId: record.khoaHuanLuyenId ? String(record.khoaHuanLuyenId) : undefined,\\n        dia_diem: record.dia_diem,\\n        ngay_bat_dau: record.ngay_bat_dau || undefined,\\n        ngay_ket_thuc: record.ngay_ket_thuc || undefined,\\n        trang_thai: record.trang_thai,\\n        hinh_thuc: record.hinh_thuc,\\n      });\\n      setSelectedGV((record.giang_vien_nld || []).map(function(g) { return g.id; }));\\n      setSelectedHV((record.hoc_vien_lop || []).map(function(h) { return h.nguoiLaoDongId; }));\\n      setFormOpen(true);\\n    }, [form]);\\n\\n    var handleSave = useCallback(async function() {\\n      try {\\n        var values = await form.validateFields();\\n        setFormLoading(true);\\n        if (values.don_vi_id) values.don_vi_id = Number(values.don_vi_id);\\n        if (values.khoaHuanLuyenId) values.khoaHuanLuyenId = Number(values.khoaHuanLuyenId);\\n        if (editingId) {\\n          await updateRow(editingId, values);\\n          await setGiangVienAssoc(editingId, selectedGV);\\n          await syncHocVienAssoc(editingId, selectedHV, editingRecord?.hoc_vien_lop);\\n          ctx.message.success(ctx.t('Cập nhật thành công'));\\n        } else {\\n          var createValues = Object.assign({}, values, {\\n            giang_vien_nld: selectedGV.map(function(id) { return { id: Number(id) }; }),\\n            hoc_vien_lop: selectedHV.map(function(id) { return { nguoiLaoDongId: Number(id), trang_thai: 'dang_hoc' }; }),\\n          });\\n          await createRow(createValues);\\n          ctx.message.success(ctx.t('Thêm mới thành công'));\\n        }\\n        setFormOpen(false);\\n        setEditingId(null);\\n        setEditingRecord(null);\\n        form.resetFields();\\n        setSelectedGV([]);\\n        setSelectedHV([]);\\n        refreshData();\\n      } catch (e) {\\n        if (e?.errorFields) return;\\n        ctx.message.error(String(e?.message || e));\\n      } finally {\\n        setFormLoading(false);\\n      }\\n    }, [editingId, editingRecord, form, refreshData, selectedGV, selectedHV]);\\n\\n    var filtered = useMemo(function() {\\n      if (!searchText) return rows;\\n      var s = searchText.toLowerCase();\\n      return rows.filter(function(r) {\\n        return (r.ma_lop || '').toLowerCase().includes(s) ||\\n          (r.ten_lop || '').toLowerCase().includes(s) ||\\n          (r.dia_diem || '').toLowerCase().includes(s) ||\\n          (r.don_vi?.ten_don_vi || '').toLowerCase().includes(s) ||\\n          getGiangVienNames(r).toLowerCase().includes(s);\\n      });\\n    }, [rows, searchText]);\\n\\n    var columns = [\\n      {\\n        title: ctx.t('Mã lớp'), dataIndex: 'ma_lop', key: 'ma_lop', width: 110, fixed: 'left',\\n        render: function(val) { return <Typography.Text strong style={{ color: '#1677ff' }}>{val || '-'}</Typography.Text>; },\\n      },\\n      {\\n        title: ctx.t('Tên lớp'), dataIndex: 'ten_lop', key: 'ten_lop', ellipsis: { showTitle: false },\\n        render: function(val) { return <Tooltip title={val}><span>{val || '-'}</span></Tooltip>; },\\n      },\\n      {\\n        title: ctx.t('Khóa huấn luyện'), key: 'khoa_huan_luyen', ellipsis: true,\\n        render: function(_, record) { return record.khoa_huan_luyen?.ten_khoa_hoc || '-'; },\\n      },\\n      { title: ctx.t('Sĩ số tối đa'), dataIndex: 'si_so_toi_da', key: 'si_so_toi_da', width: 90, align: 'center' },\\n      {\\n        title: ctx.t('Giảng viên'), key: 'giang_vien', ellipsis: true,\\n        render: function(_, record) { return getGiangVienNames(record); },\\n      },\\n      {\\n        title: ctx.t('Học viên'), key: 'hoc_vien', width: 90, align: 'center',\\n        render: function(_, record) {\\n          var count = getHocVienCount(record);\\n          return <Tag icon={<UserOutlined />} color={count > 0 ? 'blue' : 'default'}>{count}</Tag>;\\n        },\\n      },\\n      {\\n        title: ctx.t('Đơn vị'), key: 'don_vi', ellipsis: true,\\n        render: function(_, record) { return record.don_vi?.ten_don_vi || '-'; },\\n      },\\n      {\\n        title: ctx.t('Ngày bắt đầu'), dataIndex: 'ngay_bat_dau', key: 'ngay_bat_dau', width: 110,\\n        render: function(val) { return formatDate(val); },\\n      },\\n      {\\n        title: ctx.t('Ngày kết thúc'), dataIndex: 'ngay_ket_thuc', key: 'ngay_ket_thuc', width: 110,\\n        render: function(val) { return formatDate(val); },\\n      },\\n      {\\n        title: ctx.t('Trạng thái'), dataIndex: 'trang_thai', key: 'trang_thai', width: 110, align: 'center',\\n        render: function(val) { var s = STATUS_MAP[val]; return s ? <Tag color={s.color}>{s.label}</Tag> : <span>{val || '-'}</span>; },\\n      },\\n      {\\n        title: ctx.t('Thao tác'), key: 'actions', width: 160, fixed: 'right',\\n        render: function(_, record) {\\n          return (\\n            <Space size={4}>\\n              <Tooltip title={ctx.t('Xem')}>\\n                <Button icon={<EyeOutlined />} onClick={function() { setViewRecord(record); }} />\\n              </Tooltip>\\n              <Tooltip title={ctx.t('Sửa')}>\\n                <Button icon={<EditOutlined />} onClick={function() { openEdit(record); }} />\\n              </Tooltip>\\n              <Popconfirm title={ctx.t('Xác nhận xóa bản ghi này?')} okText={ctx.t('Xóa')} cancelText={ctx.t('Hủy')} onConfirm={function() { handleDelete(record.id); }}>\\n                <Tooltip title={ctx.t('Xóa')}>\\n                  <Button danger icon={<DeleteOutlined />} />\\n                </Tooltip>\\n              </Popconfirm>\\n            </Space>\\n          );\\n        },\\n      },\\n    ];\\n\\n    var formFields = (\\n      <Form form={form} layout=\\"vertical\\" autoComplete=\\"off\\">\\n        <Form.Item name=\\"ten_lop\\" label={ctx.t('Tên lớp')} rules={[{ required: true, message: ctx.t('Vui lòng nhập tên lớp') }]}>\\n          <Input placeholder={ctx.t('Nhập tên lớp')} />\\n        </Form.Item>\\n        <Form.Item name=\\"khoaHuanLuyenId\\" label={ctx.t('Khóa huấn luyện')}>\\n          <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Chọn khóa huấn luyện')}\\n            options={khoaList.map(function(k) { return { value: String(k.id), label: k.ten_khoa_hoc || k.name || String(k.id) }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"don_vi_id\\" label={ctx.t('Đơn vị')}>\\n          <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Chọn đơn vị')}\\n            options={donViList.map(function(d) { return { value: String(d.id), label: d.ten_don_vi || String(d.id) }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"si_so_toi_da\\" label={ctx.t('Sĩ số tối đa')}>\\n          <InputNumber min={1} style={{ width: '100%' }} placeholder={ctx.t('Nhập sĩ số tối đa')} />\\n        </Form.Item>\\n        <Form.Item label={ctx.t('Giảng viên')}>\\n          <PersonPicker title={ctx.t('Chọn giảng viên')} people={giangVienCandidates} selectedIds={selectedGV} onChange={setSelectedGV} />\\n        </Form.Item>\\n        <Form.Item label={ctx.t('Học viên')}>\\n          <PersonPicker title={ctx.t('Chọn học viên')} people={hocVienCandidates} selectedIds={selectedHV} onChange={setSelectedHV} bacThoOptions={bacThoList} />\\n        </Form.Item>\\n        <Form.Item name=\\"dia_diem\\" label={ctx.t('Địa điểm')}>\\n          <Input placeholder={ctx.t('Nhập địa điểm')} />\\n        </Form.Item>\\n        <Form.Item name=\\"ngay_bat_dau\\" label={ctx.t('Ngày bắt đầu')}>\\n          <Input type=\\"date\\" />\\n        </Form.Item>\\n        <Form.Item name=\\"ngay_ket_thuc\\" label={ctx.t('Ngày kết thúc')}>\\n          <Input type=\\"date\\" />\\n        </Form.Item>\\n        <Form.Item name=\\"trang_thai\\" label={ctx.t('Trạng thái')}>\\n          <Select placeholder={ctx.t('Chọn trạng thái')} options={STATUS_OPTIONS.map(function(s) { return { value: s.value, label: s.label }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"hinh_thuc\\" hidden><Input /></Form.Item>\\n      </Form>\\n    );\\n\\n    return (\\n      <>\\n        <Card size=\\"small\\" styles={{ body: { padding: 0 } }}>\\n          <div style={{ padding: '12px 16px', borderBottom: '1px solid #f0f0f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>\\n            <Space>\\n              <Typography.Text strong style={{ fontSize: 15 }}>\\n                {ctx.t('Danh sách lớp trực tiếp')} ({totalCount})\\n              </Typography.Text>\\n              <Tooltip title={ctx.t('Tải lại')}>\\n                <Button type=\\"text\\" size=\\"small\\" icon={<ReloadOutlined />} onClick={refreshData} loading={loading} />\\n              </Tooltip>\\n            </Space>\\n            <Space size=\\"small\\">\\n              <Input\\n                placeholder={ctx.t('Tìm kiếm theo tên, mã lớp, giảng viên...')}\\n                prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n                allowClear style={{ width: 280 }}\\n                onChange={function(e) { setSearchText(e.target.value); setCurrentPage(1); }}\\n              />\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={openCreate}>{ctx.t('Thêm mới')}</Button>\\n            </Space>\\n          </div>\\n          <Table columns={columns} dataSource={filtered} rowKey=\\"id\\" size=\\"small\\" loading={loading} scroll={{ x: 1400 }}\\n            pagination={{ current: currentPage, pageSize: pageSize, total: filtered.length, showTotal: function(t) { return ctx.t('Tổng') + ': ' + t + ' ' + ctx.t('lớp'); }, showSizeChanger: false, size: 'small', onChange: function(p) { setCurrentPage(p); } }}\\n          />\\n        </Card>\\n\\n        <Modal title={ctx.t('Chi tiết lớp học')} open={!!viewRecord} onCancel={function() { setViewRecord(null); }}\\n          footer={[\\n            <Button key=\\"edit\\" type=\\"primary\\" icon={<EditOutlined />} onClick={function() { var r = viewRecord; setViewRecord(null); openEdit(r); }}>{ctx.t('Sửa')}</Button>,\\n            <Button key=\\"close\\" onClick={function() { setViewRecord(null); }}>{ctx.t('Đóng')}</Button>,\\n          ]}\\n          width={640}\\n        >\\n          {viewRecord && (\\n            <Descriptions column={2} bordered size=\\"small\\">\\n              <Descriptions.Item label={ctx.t('Mã lớp')}>{viewRecord.ma_lop || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Trạng thái')}>\\n                {(function() { var s = STATUS_MAP[viewRecord.trang_thai]; return s ? <Tag color={s.color}>{s.label}</Tag> : viewRecord.trang_thai || '-'; })()}\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Tên lớp')} span={2}>{viewRecord.ten_lop || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Khóa huấn luyện')} span={2}>{viewRecord.khoa_huan_luyen?.ten_khoa_hoc || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Đơn vị')}>{viewRecord.don_vi?.ten_don_vi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Sĩ số tối đa')}>{viewRecord.si_so_toi_da ?? '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Giảng viên')} span={2}>{getGiangVienNames(viewRecord)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Học viên')} span={2}>{getHocVienNames(viewRecord) || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Địa điểm')}>{viewRecord.dia_diem || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ngày bắt đầu')}>{formatDate(viewRecord.ngay_bat_dau)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ngày kết thúc')}>{formatDate(viewRecord.ngay_ket_thuc)}</Descriptions.Item>\\n            </Descriptions>\\n          )}\\n        </Modal>\\n\\n        <Drawer title={editingId ? ctx.t('Sửa lớp học') : ctx.t('Thêm mới lớp học')} open={formOpen}\\n          onClose={function() { setFormOpen(false); setEditingId(null); setEditingRecord(null); form.resetFields(); setSelectedGV([]); setSelectedHV([]); }}\\n          width={480}\\n          extra={\\n            <Space>\\n              <Button onClick={function() { setFormOpen(false); setEditingId(null); setEditingRecord(null); form.resetFields(); setSelectedGV([]); setSelectedHV([]); }}>{ctx.t('Hủy')}</Button>\\n              <Button type=\\"primary\\" onClick={handleSave} loading={formLoading}>{ctx.t('Lưu')}</Button>\\n            </Space>\\n          }\\n        >\\n          {formFields}\\n        </Drawer>\\n      </>\\n    );\\n  }\\n\\n  ctx.render(<TableApp />);\\n} catch (error) {\\n  ctx.render(\\n    <Alert showIcon type=\\"error\\" message={ctx.t('Không tải được danh sách lớp học')} description={String(error?.message || error)} />,\\n  );\\n}\\n"}},"__flowSurfaceMeta":{"declaredKey":"ttTab.ttTableJS"}}}
cxov1xse0ra	cxov1xse0ra	{"parentId":"cejw9sr82hj","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v1","code":"const { Alert, Button, Card, Descriptions, Drawer, Form, Input, InputNumber, Modal, Popconfirm, Progress, Select, Space, Table, Tag, Tooltip, Typography } = ctx.libs.antd;\\nconst { PlusOutlined, EditOutlined, EyeOutlined, DeleteOutlined, SearchOutlined, ReloadOutlined, UserOutlined } = ctx.libs.antdIcons;\\nconst { useState, useMemo, useCallback } = ctx.React;\\n\\nconst STATUS_OPTIONS = [\\n  { value: 'du_kien', label: 'Dự kiến', color: 'gold' },\\n  { value: 'dang_hoc', label: 'Đang học', color: 'blue' },\\n  { value: 'hoan_thanh', label: 'Hoàn thành', color: 'green' },\\n  { value: 'huy', label: 'Đã hủy', color: 'red' },\\n];\\nconst STATUS_MAP = Object.fromEntries(STATUS_OPTIONS.map((s) => [s.value, s]));\\nconst HINH_THUC = 'truc_tuyen';\\nconst ROLE_GIANG_VIEN = 3;\\nconst ROLE_HOC_VIEN = 4;\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('lop_hoc');\\n  ctx.resource.setFilter({ hinh_thuc: { $eq: HINH_THUC }, is_deleted: { $ne: true } });\\n  ctx.resource.setAppends(['don_vi', 'giang_vien_nld', 'khoa_huan_luyen', 'hoc_vien_lop', 'hoc_vien_lop.nguoi_lao_dong']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(200);\\n  await ctx.resource.refresh();\\n  const initialRows = ctx.resource.getData() || [];\\n  const initialTotal = ctx.resource.getMeta?.()?.count ?? initialRows.length;\\n\\n  const donViRes = ctx.makeResource('MultiRecordResource');\\n  donViRes.setResourceName('don_vi');\\n  donViRes.setPageSize(500);\\n  await donViRes.refresh();\\n  const donViList = donViRes.getData() || [];\\n\\n  const khoaRes = ctx.makeResource('MultiRecordResource');\\n  khoaRes.setResourceName('khoa_huan_luyen');\\n  khoaRes.setPageSize(500);\\n  await khoaRes.refresh();\\n  const khoaList = khoaRes.getData() || [];\\n\\n  const gvCandRes = ctx.makeResource('MultiRecordResource');\\n  gvCandRes.setResourceName('nguoi_lao_dong');\\n  gvCandRes.setFilter({ 'vai_tro.id': { $in: [ROLE_GIANG_VIEN] } });\\n  gvCandRes.setPageSize(500);\\n  await gvCandRes.refresh();\\n  const giangVienCandidates = gvCandRes.getData() || [];\\n\\n  const bacThoRes = ctx.makeResource('MultiRecordResource');\\n  bacThoRes.setResourceName('bac_tho');\\n  bacThoRes.setSort(['thu_tu']);\\n  bacThoRes.setPageSize(50);\\n  await bacThoRes.refresh();\\n  const bacThoList = bacThoRes.getData() || [];\\n\\n  const hvCandRes = ctx.makeResource('MultiRecordResource');\\n  hvCandRes.setResourceName('nguoi_lao_dong');\\n  hvCandRes.setFilter({ 'vai_tro.id': { $in: [ROLE_HOC_VIEN] } });\\n  hvCandRes.setAppends(['bac_tho']);\\n  hvCandRes.setPageSize(500);\\n  await hvCandRes.refresh();\\n  const hocVienCandidates = hvCandRes.getData() || [];\\n\\n  const crudRes = ctx.makeResource('MultiRecordResource');\\n  crudRes.setResourceName('lop_hoc');\\n\\n  const hvlRes = ctx.makeResource('MultiRecordResource');\\n  hvlRes.setResourceName('hoc_vien_lop');\\n\\n  async function fetchRows() {\\n    crudRes.setFilter({ hinh_thuc: { $eq: HINH_THUC }, is_deleted: { $ne: true } });\\n    crudRes.setAppends(['don_vi', 'giang_vien_nld', 'khoa_huan_luyen', 'hoc_vien_lop', 'hoc_vien_lop.nguoi_lao_dong']);\\n    crudRes.setSort(['-createdAt']);\\n    crudRes.setPageSize(200);\\n    await crudRes.refresh();\\n    return { rows: crudRes.getData() || [], count: crudRes.getMeta?.()?.count ?? 0 };\\n  }\\n\\n  async function deleteRow(id) {\\n    await crudRes.destroy(id);\\n  }\\n\\n  async function createRow(values) {\\n    await crudRes.create(values);\\n  }\\n\\n  async function updateRow(id, values) {\\n    await crudRes.update(id, values);\\n  }\\n\\n  async function setGiangVienAssoc(lopHocId, nguoiLaoDongIds) {\\n    await ctx.request({\\n      url: 'lop_hoc/' + lopHocId + '/giang_vien_nld:set',\\n      method: 'post',\\n      data: nguoiLaoDongIds.map(function(x) { return Number(x); }),\\n    });\\n  }\\n\\n  async function syncHocVienAssoc(lopHocId, selectedIds, currentHvl) {\\n    var currentNldIds = (currentHvl || []).map(function(h) { return String(h.nguoiLaoDongId); });\\n    var selStr = selectedIds.map(function(x) { return String(x); });\\n    var toAdd = selStr.filter(function(id) { return currentNldIds.indexOf(id) === -1; });\\n    var toRemove = (currentHvl || []).filter(function(h) { return selStr.indexOf(String(h.nguoiLaoDongId)) === -1; });\\n    for (var i = 0; i < toAdd.length; i++) {\\n      await hvlRes.create({ lopHocId: Number(lopHocId), nguoiLaoDongId: Number(toAdd[i]), trang_thai: 'dang_hoc' });\\n    }\\n    for (var j = 0; j < toRemove.length; j++) {\\n      await hvlRes.destroy(toRemove[j].id);\\n    }\\n  }\\n\\n  function formatDate(val) {\\n    if (!val) return '-';\\n    try {\\n      var d = new Date(val);\\n      if (isNaN(d.getTime())) return val;\\n      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();\\n    } catch (e) {\\n      return val;\\n    }\\n  }\\n\\n  function getGiangVienNames(record) {\\n    if (record.giang_vien_nld && record.giang_vien_nld.length > 0) {\\n      return record.giang_vien_nld.map(function(gv) { return gv.ho_ten || gv.name || '-'; }).join(', ');\\n    }\\n    return record.giang_vien || '-';\\n  }\\n\\n  function getHocVienNames(record) {\\n    if (record.hoc_vien_lop && record.hoc_vien_lop.length > 0) {\\n      return record.hoc_vien_lop.map(function(h) { return h.nguoi_lao_dong?.ho_ten || '-'; }).join(', ');\\n    }\\n    return '-';\\n  }\\n\\n  function getHocVienCount(record) {\\n    return (record.hoc_vien_lop || []).length;\\n  }\\n\\n  function PersonPicker(props) {\\n    var title = props.title;\\n    var people = props.people;\\n    var selectedIds = props.selectedIds || [];\\n    var onChange = props.onChange;\\n    var bacThoOptions = props.bacThoOptions;\\n\\n    const [open, setOpen] = useState(false);\\n    const [search, setSearch] = useState('');\\n    const [filterBacTho, setFilterBacTho] = useState(undefined);\\n    const [tempSelected, setTempSelected] = useState([]);\\n\\n    var handleOpen = useCallback(function() {\\n      setTempSelected(selectedIds.map(function(x) { return Number(x); }));\\n      setSearch('');\\n      setFilterBacTho(undefined);\\n      setOpen(true);\\n    }, [selectedIds]);\\n\\n    var handleConfirm = useCallback(function() {\\n      onChange(tempSelected);\\n      setOpen(false);\\n    }, [tempSelected, onChange]);\\n\\n    var sorted = useMemo(function() {\\n      if (!bacThoOptions) return people;\\n      return people.slice().sort(function(a, b) {\\n        var aOrder = a.bac_tho?.thu_tu ?? 9999;\\n        var bOrder = b.bac_tho?.thu_tu ?? 9999;\\n        return aOrder - bOrder;\\n      });\\n    }, [people, bacThoOptions]);\\n\\n    var filtered = useMemo(function() {\\n      var list = sorted;\\n      if (filterBacTho != null) {\\n        list = list.filter(function(p) { return p.bacThoId === filterBacTho; });\\n      }\\n      if (search) {\\n        var s = search.toLowerCase();\\n        list = list.filter(function(p) { return (p.ho_ten || '').toLowerCase().includes(s); });\\n      }\\n      return list;\\n    }, [sorted, search, filterBacTho]);\\n\\n    var selectedNames = useMemo(function() {\\n      return selectedIds.map(function(id) {\\n        var p = people.find(function(x) { return String(x.id) === String(id); });\\n        return p ? p.ho_ten : String(id);\\n      });\\n    }, [selectedIds, people]);\\n\\n    var pickerColumns = [\\n      { title: ctx.t('Họ và tên'), dataIndex: 'ho_ten', key: 'ho_ten', render: function(val) { return val || '-'; } },\\n    ];\\n    if (bacThoOptions) {\\n      pickerColumns.push({\\n        title: ctx.t('Bậc thợ'), key: 'bac_tho', width: 160,\\n        render: function(_, record) { return record.bac_tho?.ten_bac || '-'; },\\n      });\\n    }\\n\\n    return (\\n      <>\\n        <div\\n          onClick={handleOpen}\\n          style={{ border: '1px solid #d9d9d9', borderRadius: 6, padding: '4px 8px', minHeight: 32, cursor: 'pointer', display: 'flex', flexWrap: 'wrap', gap: 4, alignItems: 'center', background: '#fff' }}\\n        >\\n          {selectedNames.length > 0\\n            ? selectedNames.map(function(name, i) { return <Tag key={i} color=\\"blue\\">{name}</Tag>; })\\n            : <span style={{ color: '#bfbfbf' }}>{ctx.t('Ấn để chọn...')}</span>\\n          }\\n        </div>\\n        <Modal\\n          title={title}\\n          open={open}\\n          onOk={handleConfirm}\\n          onCancel={function() { setOpen(false); }}\\n          width={bacThoOptions ? 640 : 560}\\n          okText={ctx.t('Xác nhận')}\\n          cancelText={ctx.t('Hủy')}\\n        >\\n          <Space style={{ marginBottom: 12, width: '100%' }} direction=\\"vertical\\" size={8}>\\n            <Input\\n              placeholder={ctx.t('Tìm kiếm theo tên...')}\\n              prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n              allowClear\\n              onChange={function(e) { setSearch(e.target.value); }}\\n              value={search}\\n            />\\n            {bacThoOptions && (\\n              <Select\\n                allowClear\\n                showSearch\\n                optionFilterProp=\\"label\\"\\n                placeholder={ctx.t('Lọc theo bậc thợ')}\\n                style={{ width: '100%' }}\\n                value={filterBacTho}\\n                onChange={function(val) { setFilterBacTho(val); }}\\n                options={bacThoOptions.map(function(b) { return { value: b.id, label: b.ten_bac }; })}\\n              />\\n            )}\\n          </Space>\\n          <Table\\n            dataSource={filtered}\\n            rowKey=\\"id\\"\\n            size=\\"small\\"\\n            scroll={{ y: 300 }}\\n            pagination={false}\\n            rowSelection={{ selectedRowKeys: tempSelected, onChange: function(keys) { setTempSelected(keys); } }}\\n            columns={pickerColumns}\\n          />\\n          <div style={{ marginTop: 8, color: '#8c8c8c', fontSize: 12 }}>\\n            {ctx.t('Đã chọn')}: {tempSelected.length} / {people.length}\\n          </div>\\n        </Modal>\\n      </>\\n    );\\n  }\\n\\n  function TableApp() {\\n    const [rows, setRows] = useState(initialRows);\\n    const [totalCount, setTotalCount] = useState(initialTotal);\\n    const [searchText, setSearchText] = useState('');\\n    const [currentPage, setCurrentPage] = useState(1);\\n    const [loading, setLoading] = useState(false);\\n    const [viewRecord, setViewRecord] = useState(null);\\n    const [formOpen, setFormOpen] = useState(false);\\n    const [editingId, setEditingId] = useState(null);\\n    const [editingRecord, setEditingRecord] = useState(null);\\n    const [formLoading, setFormLoading] = useState(false);\\n    const [selectedGV, setSelectedGV] = useState([]);\\n    const [selectedHV, setSelectedHV] = useState([]);\\n    const [form] = Form.useForm();\\n    var pageSize = 10;\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var result = await fetchRows();\\n        setRows(result.rows);\\n        setTotalCount(result.count || result.rows.length);\\n      } catch (e) {\\n        ctx.message.error(String(e?.message || e));\\n      }\\n      setLoading(false);\\n    }, []);\\n\\n    var handleDelete = useCallback(async function(id) {\\n      try {\\n        await deleteRow(id);\\n        ctx.message.success(ctx.t('Đã xóa thành công'));\\n        refreshData();\\n      } catch (e) {\\n        ctx.message.error(String(e?.message || e));\\n      }\\n    }, [refreshData]);\\n\\n    var openCreate = useCallback(function() {\\n      setEditingId(null);\\n      setEditingRecord(null);\\n      form.resetFields();\\n      form.setFieldsValue({ hinh_thuc: HINH_THUC, trang_thai: 'du_kien', tien_do: 0 });\\n      setSelectedGV([]);\\n      setSelectedHV([]);\\n      setFormOpen(true);\\n    }, [form]);\\n\\n    var openEdit = useCallback(function(record) {\\n      setEditingId(record.id);\\n      setEditingRecord(record);\\n      form.resetFields();\\n      form.setFieldsValue({\\n        ten_lop: record.ten_lop,\\n        si_so_toi_da: record.si_so_toi_da,\\n        don_vi_id: record.don_vi_id ? String(record.don_vi_id) : undefined,\\n        khoaHuanLuyenId: record.khoaHuanLuyenId ? String(record.khoaHuanLuyenId) : undefined,\\n        dia_diem: record.dia_diem,\\n        ca_hoc: record.ca_hoc,\\n        tien_do: record.tien_do ?? 0,\\n        ngay_bat_dau: record.ngay_bat_dau || undefined,\\n        ngay_ket_thuc: record.ngay_ket_thuc || undefined,\\n        trang_thai: record.trang_thai,\\n        hinh_thuc: record.hinh_thuc,\\n      });\\n      setSelectedGV((record.giang_vien_nld || []).map(function(g) { return g.id; }));\\n      setSelectedHV((record.hoc_vien_lop || []).map(function(h) { return h.nguoiLaoDongId; }));\\n      setFormOpen(true);\\n    }, [form]);\\n\\n    var handleSave = useCallback(async function() {\\n      try {\\n        var values = await form.validateFields();\\n        setFormLoading(true);\\n        if (values.don_vi_id) values.don_vi_id = Number(values.don_vi_id);\\n        if (values.khoaHuanLuyenId) values.khoaHuanLuyenId = Number(values.khoaHuanLuyenId);\\n        if (editingId) {\\n          await updateRow(editingId, values);\\n          await setGiangVienAssoc(editingId, selectedGV);\\n          await syncHocVienAssoc(editingId, selectedHV, editingRecord?.hoc_vien_lop);\\n          ctx.message.success(ctx.t('Cập nhật thành công'));\\n        } else {\\n          var createValues = Object.assign({}, values, {\\n            giang_vien_nld: selectedGV.map(function(id) { return { id: Number(id) }; }),\\n            hoc_vien_lop: selectedHV.map(function(id) { return { nguoiLaoDongId: Number(id), trang_thai: 'dang_hoc' }; }),\\n          });\\n          await createRow(createValues);\\n          ctx.message.success(ctx.t('Thêm mới thành công'));\\n        }\\n        setFormOpen(false);\\n        setEditingId(null);\\n        setEditingRecord(null);\\n        form.resetFields();\\n        setSelectedGV([]);\\n        setSelectedHV([]);\\n        refreshData();\\n      } catch (e) {\\n        if (e?.errorFields) return;\\n        ctx.message.error(String(e?.message || e));\\n      } finally {\\n        setFormLoading(false);\\n      }\\n    }, [editingId, editingRecord, form, refreshData, selectedGV, selectedHV]);\\n\\n    var filtered = useMemo(function() {\\n      if (!searchText) return rows;\\n      var s = searchText.toLowerCase();\\n      return rows.filter(function(r) {\\n        return (r.ma_lop || '').toLowerCase().includes(s) ||\\n          (r.ten_lop || '').toLowerCase().includes(s) ||\\n          (r.dia_diem || '').toLowerCase().includes(s) ||\\n          (r.don_vi?.ten_don_vi || '').toLowerCase().includes(s) ||\\n          getGiangVienNames(r).toLowerCase().includes(s);\\n      });\\n    }, [rows, searchText]);\\n\\n    var columns = [\\n      {\\n        title: ctx.t('Mã lớp'), dataIndex: 'ma_lop', key: 'ma_lop', width: 110, fixed: 'left',\\n        render: function(val) { return <Typography.Text strong style={{ color: '#1677ff' }}>{val || '-'}</Typography.Text>; },\\n      },\\n      {\\n        title: ctx.t('Tên lớp'), dataIndex: 'ten_lop', key: 'ten_lop', ellipsis: { showTitle: false },\\n        render: function(val) { return <Tooltip title={val}><span>{val || '-'}</span></Tooltip>; },\\n      },\\n      {\\n        title: ctx.t('Khóa huấn luyện'), key: 'khoa_huan_luyen', ellipsis: true,\\n        render: function(_, record) { return record.khoa_huan_luyen?.ten_khoa_hoc || '-'; },\\n      },\\n      { title: ctx.t('Sĩ số tối đa'), dataIndex: 'si_so_toi_da', key: 'si_so_toi_da', width: 90, align: 'center' },\\n      {\\n        title: ctx.t('Giảng viên'), key: 'giang_vien', ellipsis: true,\\n        render: function(_, record) { return getGiangVienNames(record); },\\n      },\\n      {\\n        title: ctx.t('Học viên'), key: 'hoc_vien', width: 90, align: 'center',\\n        render: function(_, record) {\\n          var count = getHocVienCount(record);\\n          return <Tag icon={<UserOutlined />} color={count > 0 ? 'blue' : 'default'}>{count}</Tag>;\\n        },\\n      },\\n      {\\n        title: ctx.t('Đơn vị'), key: 'don_vi', ellipsis: true,\\n        render: function(_, record) { return record.don_vi?.ten_don_vi || '-'; },\\n      },\\n      {\\n        title: ctx.t('Tiến độ'), dataIndex: 'tien_do', key: 'tien_do', width: 120,\\n        render: function(val) { return <Progress percent={val || 0} size=\\"small\\" />; },\\n      },\\n      {\\n        title: ctx.t('Ca học'), dataIndex: 'ca_hoc', key: 'ca_hoc', width: 100, ellipsis: true,\\n        render: function(val) { return val || '-'; },\\n      },\\n      {\\n        title: ctx.t('Ngày bắt đầu'), dataIndex: 'ngay_bat_dau', key: 'ngay_bat_dau', width: 110,\\n        render: function(val) { return formatDate(val); },\\n      },\\n      {\\n        title: ctx.t('Ngày kết thúc'), dataIndex: 'ngay_ket_thuc', key: 'ngay_ket_thuc', width: 110,\\n        render: function(val) { return formatDate(val); },\\n      },\\n      {\\n        title: ctx.t('Trạng thái'), dataIndex: 'trang_thai', key: 'trang_thai', width: 110, align: 'center',\\n        render: function(val) { var s = STATUS_MAP[val]; return s ? <Tag color={s.color}>{s.label}</Tag> : <span>{val || '-'}</span>; },\\n      },\\n      {\\n        title: ctx.t('Thao tác'), key: 'actions', width: 160, fixed: 'right',\\n        render: function(_, record) {\\n          return (\\n            <Space size={4}>\\n              <Tooltip title={ctx.t('Xem')}>\\n                <Button icon={<EyeOutlined />} onClick={function() { setViewRecord(record); }} />\\n              </Tooltip>\\n              <Tooltip title={ctx.t('Sửa')}>\\n                <Button icon={<EditOutlined />} onClick={function() { openEdit(record); }} />\\n              </Tooltip>\\n              <Popconfirm title={ctx.t('Xác nhận xóa bản ghi này?')} okText={ctx.t('Xóa')} cancelText={ctx.t('Hủy')} onConfirm={function() { handleDelete(record.id); }}>\\n                <Tooltip title={ctx.t('Xóa')}>\\n                  <Button danger icon={<DeleteOutlined />} />\\n                </Tooltip>\\n              </Popconfirm>\\n            </Space>\\n          );\\n        },\\n      },\\n    ];\\n\\n    var formFields = (\\n      <Form form={form} layout=\\"vertical\\" autoComplete=\\"off\\">\\n        <Form.Item name=\\"ten_lop\\" label={ctx.t('Tên lớp')} rules={[{ required: true, message: ctx.t('Vui lòng nhập tên lớp') }]}>\\n          <Input placeholder={ctx.t('Nhập tên lớp')} />\\n        </Form.Item>\\n        <Form.Item name=\\"khoaHuanLuyenId\\" label={ctx.t('Khóa huấn luyện')}>\\n          <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Chọn khóa huấn luyện')}\\n            options={khoaList.map(function(k) { return { value: String(k.id), label: k.ten_khoa_hoc || k.name || String(k.id) }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"don_vi_id\\" label={ctx.t('Đơn vị')}>\\n          <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Chọn đơn vị')}\\n            options={donViList.map(function(d) { return { value: String(d.id), label: d.ten_don_vi || String(d.id) }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"si_so_toi_da\\" label={ctx.t('Sĩ số tối đa')}>\\n          <InputNumber min={1} style={{ width: '100%' }} placeholder={ctx.t('Nhập sĩ số tối đa')} />\\n        </Form.Item>\\n        <Form.Item label={ctx.t('Giảng viên')}>\\n          <PersonPicker title={ctx.t('Chọn giảng viên')} people={giangVienCandidates} selectedIds={selectedGV} onChange={setSelectedGV} />\\n        </Form.Item>\\n        <Form.Item label={ctx.t('Học viên')}>\\n          <PersonPicker title={ctx.t('Chọn học viên')} people={hocVienCandidates} selectedIds={selectedHV} onChange={setSelectedHV} bacThoOptions={bacThoList} />\\n        </Form.Item>\\n        <Form.Item name=\\"dia_diem\\" label={ctx.t('Địa điểm')}>\\n          <Input placeholder={ctx.t('Nhập địa điểm')} />\\n        </Form.Item>\\n        <Form.Item name=\\"ca_hoc\\" label={ctx.t('Ca học')}>\\n          <Input placeholder={ctx.t('Nhập ca học')} />\\n        </Form.Item>\\n        <Form.Item name=\\"tien_do\\" label={ctx.t('Tiến độ (%)')}>\\n          <InputNumber min={0} max={100} style={{ width: '100%' }} placeholder={ctx.t('Nhập tiến độ')} />\\n        </Form.Item>\\n        <Form.Item name=\\"ngay_bat_dau\\" label={ctx.t('Ngày bắt đầu')}>\\n          <Input type=\\"date\\" />\\n        </Form.Item>\\n        <Form.Item name=\\"ngay_ket_thuc\\" label={ctx.t('Ngày kết thúc')}>\\n          <Input type=\\"date\\" />\\n        </Form.Item>\\n        <Form.Item name=\\"trang_thai\\" label={ctx.t('Trạng thái')}>\\n          <Select placeholder={ctx.t('Chọn trạng thái')} options={STATUS_OPTIONS.map(function(s) { return { value: s.value, label: s.label }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"hinh_thuc\\" hidden><Input /></Form.Item>\\n      </Form>\\n    );\\n\\n    return (\\n      <>\\n        <Card size=\\"small\\" styles={{ body: { padding: 0 } }}>\\n          <div style={{ padding: '12px 16px', borderBottom: '1px solid #f0f0f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>\\n            <Space>\\n              <Typography.Text strong style={{ fontSize: 15 }}>\\n                {ctx.t('Danh sách lớp trực tuyến')} ({totalCount})\\n              </Typography.Text>\\n              <Tooltip title={ctx.t('Tải lại')}>\\n                <Button type=\\"text\\" size=\\"small\\" icon={<ReloadOutlined />} onClick={refreshData} loading={loading} />\\n              </Tooltip>\\n            </Space>\\n            <Space size=\\"small\\">\\n              <Input\\n                placeholder={ctx.t('Tìm kiếm theo tên, mã lớp, giảng viên...')}\\n                prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n                allowClear style={{ width: 280 }}\\n                onChange={function(e) { setSearchText(e.target.value); setCurrentPage(1); }}\\n              />\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={openCreate}>{ctx.t('Thêm mới')}</Button>\\n            </Space>\\n          </div>\\n          <Table columns={columns} dataSource={filtered} rowKey=\\"id\\" size=\\"small\\" loading={loading} scroll={{ x: 1600 }}\\n            pagination={{ current: currentPage, pageSize: pageSize, total: filtered.length, showTotal: function(t) { return ctx.t('Tổng') + ': ' + t + ' ' + ctx.t('lớp'); }, showSizeChanger: false, size: 'small', onChange: function(p) { setCurrentPage(p); } }}\\n          />\\n        </Card>\\n\\n        <Modal title={ctx.t('Chi tiết lớp học')} open={!!viewRecord} onCancel={function() { setViewRecord(null); }}\\n          footer={[\\n            <Button key=\\"edit\\" type=\\"primary\\" icon={<EditOutlined />} onClick={function() { var r = viewRecord; setViewRecord(null); openEdit(r); }}>{ctx.t('Sửa')}</Button>,\\n            <Button key=\\"close\\" onClick={function() { setViewRecord(null); }}>{ctx.t('Đóng')}</Button>,\\n          ]}\\n          width={640}\\n        >\\n          {viewRecord && (\\n            <Descriptions column={2} bordered size=\\"small\\">\\n              <Descriptions.Item label={ctx.t('Mã lớp')}>{viewRecord.ma_lop || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Trạng thái')}>\\n                {(function() { var s = STATUS_MAP[viewRecord.trang_thai]; return s ? <Tag color={s.color}>{s.label}</Tag> : viewRecord.trang_thai || '-'; })()}\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Tên lớp')} span={2}>{viewRecord.ten_lop || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Khóa huấn luyện')} span={2}>{viewRecord.khoa_huan_luyen?.ten_khoa_hoc || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Đơn vị')}>{viewRecord.don_vi?.ten_don_vi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Sĩ số tối đa')}>{viewRecord.si_so_toi_da ?? '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Giảng viên')} span={2}>{getGiangVienNames(viewRecord)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Học viên')} span={2}>{getHocVienNames(viewRecord) || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ca học')}>{viewRecord.ca_hoc || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Tiến độ')}><Progress percent={viewRecord.tien_do || 0} size=\\"small\\" /></Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Địa điểm')}>{viewRecord.dia_diem || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ngày bắt đầu')}>{formatDate(viewRecord.ngay_bat_dau)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ngày kết thúc')}>{formatDate(viewRecord.ngay_ket_thuc)}</Descriptions.Item>\\n            </Descriptions>\\n          )}\\n        </Modal>\\n\\n        <Drawer title={editingId ? ctx.t('Sửa lớp học') : ctx.t('Thêm mới lớp học')} open={formOpen}\\n          onClose={function() { setFormOpen(false); setEditingId(null); setEditingRecord(null); form.resetFields(); setSelectedGV([]); setSelectedHV([]); }}\\n          width={480}\\n          extra={\\n            <Space>\\n              <Button onClick={function() { setFormOpen(false); setEditingId(null); setEditingRecord(null); form.resetFields(); setSelectedGV([]); setSelectedHV([]); }}>{ctx.t('Hủy')}</Button>\\n              <Button type=\\"primary\\" onClick={handleSave} loading={formLoading}>{ctx.t('Lưu')}</Button>\\n            </Space>\\n          }\\n        >\\n          {formFields}\\n        </Drawer>\\n      </>\\n    );\\n  }\\n\\n  ctx.render(<TableApp />);\\n} catch (error) {\\n  ctx.render(\\n    <Alert showIcon type=\\"error\\" message={ctx.t('Không tải được danh sách lớp học')} description={String(error?.message || error)} />,\\n  );\\n}\\n"}},"__flowSurfaceMeta":{"declaredKey":"ttTab2.ttTableJS"}}}
anzm2kk1aau	anzm2kk1aau	{"parentId":"3pfwg5guvkb","subKey":"grid","subType":"object","use":"BlockGridModel","props":{"rows":{"autoRow1":[["uuuyyctceir"]]},"sizes":{"autoRow1":[24]},"rowOrder":["autoRow1"]},"stepParams":{"gridSettings":{"grid":{"rows":{"autoRow1":[["uuuyyctceir"]]},"sizes":{"autoRow1":[24]},"rowOrder":["autoRow1"]}}},"filterManager":[]}
5au1ton4n2d	5au1ton4n2d	{"parentId":"0j5hhgokulo","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"2","code":"const { Alert, Button, Card, Descriptions, Drawer, Form, Input, InputNumber, Modal, Popconfirm, Select, Space, Table, Tabs, Tag, Tooltip, Typography } = ctx.libs.antd;\\nconst { PlusOutlined, EditOutlined, EyeOutlined, DeleteOutlined, SearchOutlined, ReloadOutlined, UserOutlined, TeamOutlined, CheckCircleOutlined, SendOutlined } = ctx.libs.antdIcons;\\nconst { useState, useMemo, useCallback } = ctx.React;\\n\\nvar HINH_THUC_OPTIONS = [\\n  { value: 'truc_tiep', label: 'Trực tiếp', color: 'green' },\\n  { value: 'truc_tuyen', label: 'Trực tuyến', color: 'blue' },\\n];\\nvar HINH_THUC_MAP = Object.fromEntries(HINH_THUC_OPTIONS.map(function(h) { return [h.value, h]; }));\\n\\nvar STATUS_OPTIONS = [\\n  { value: 'ban_nhap', label: 'Bản nháp', color: 'default' },\\n  { value: 'cho_phe_duyet', label: 'Chờ phê duyệt', color: 'processing' },\\n  { value: 'da_phe_duyet', label: 'Đã phê duyệt', color: 'cyan' },\\n  { value: 'tu_choi', label: 'Từ chối', color: 'error' },\\n  { value: 'lap_lich', label: 'Lập lịch', color: 'blue' },\\n  { value: 'sap_dien_ra', label: 'Sắp diễn ra', color: 'purple' },\\n  { value: 'dang_mo', label: 'Đang mở', color: 'green' },\\n  { value: 'dang_cham_diem', label: 'Đang chấm điểm', color: 'orange' },\\n  { value: 'hoan_thanh', label: 'Hoàn thành', color: 'success' },\\n  { value: 'da_huy', label: 'Đã hủy', color: 'red' },\\n];\\nvar STATUS_MAP = Object.fromEntries(STATUS_OPTIONS.map(function(s) { return [s.value, s]; }));\\n\\ntry {\\n  ctx.initResource('MultiRecordResource');\\n  ctx.resource.setResourceName('ky_thi');\\n  ctx.resource.setFilter({ is_deleted: { $ne: true } });\\n  ctx.resource.setAppends(['don_vi', 'nganh_nghe', 'de_thi']);\\n  ctx.resource.setSort(['-createdAt']);\\n  ctx.resource.setPageSize(200);\\n  await ctx.resource.refresh();\\n  var initialRows = ctx.resource.getData() || [];\\n  var initialTotal = ctx.resource.getMeta?.()?.count ?? initialRows.length;\\n\\n  var donViRes = ctx.makeResource('MultiRecordResource');\\n  donViRes.setResourceName('don_vi');\\n  donViRes.setPageSize(500);\\n  await donViRes.refresh();\\n  var donViList = donViRes.getData() || [];\\n\\n  var nganhNgheRes = ctx.makeResource('MultiRecordResource');\\n  nganhNgheRes.setResourceName('nganh_nghe');\\n  nganhNgheRes.setPageSize(500);\\n  await nganhNgheRes.refresh();\\n  var nganhNgheList = nganhNgheRes.getData() || [];\\n\\n  var deThiRes = ctx.makeResource('MultiRecordResource');\\n  deThiRes.setResourceName('de_thi');\\n  deThiRes.setPageSize(500);\\n  await deThiRes.refresh();\\n  var deThiList = deThiRes.getData() || [];\\n\\n  var bacThoRes = ctx.makeResource('MultiRecordResource');\\n  bacThoRes.setResourceName('bac_tho');\\n  bacThoRes.setSort(['thu_tu']);\\n  bacThoRes.setPageSize(50);\\n  await bacThoRes.refresh();\\n  var bacThoList = bacThoRes.getData() || [];\\n\\n  var nldRes = ctx.makeResource('MultiRecordResource');\\n  nldRes.setResourceName('nguoi_lao_dong');\\n  nldRes.setAppends(['bac_tho']);\\n  nldRes.setPageSize(500);\\n  await nldRes.refresh();\\n  var allNld = nldRes.getData() || [];\\n\\n  var lopHocRes = ctx.makeResource('MultiRecordResource');\\n  lopHocRes.setResourceName('lop_hoc');\\n  lopHocRes.setFilter({ is_deleted: { $ne: true } });\\n  lopHocRes.setAppends(['hoc_vien_lop', 'hoc_vien_lop.nguoi_lao_dong']);\\n  lopHocRes.setPageSize(500);\\n  await lopHocRes.refresh();\\n  var lopHocList = lopHocRes.getData() || [];\\n\\n  var crudRes = ctx.makeResource('MultiRecordResource');\\n  crudRes.setResourceName('ky_thi');\\n\\n  async function fetchRows() {\\n    crudRes.setFilter({ is_deleted: { $ne: true } });\\n    crudRes.setAppends(['don_vi', 'nganh_nghe', 'de_thi']);\\n    crudRes.setSort(['-createdAt']);\\n    crudRes.setPageSize(200);\\n    await crudRes.refresh();\\n    return { rows: crudRes.getData() || [], count: crudRes.getMeta?.()?.count ?? 0 };\\n  }\\n\\n  async function deleteRow(id) {\\n    await ctx.request({ url: 'ky_thi:destroy', method: 'post', params: { filterByTk: id } });\\n  }\\n  async function createRow(values) {\\n    var res = await ctx.request({ url: 'ky_thi:create', method: 'post', data: values });\\n    return res?.data?.data || res?.data || res;\\n  }\\n  async function updateRow(id, values) {\\n    await ctx.request({ url: 'ky_thi:update', method: 'post', params: { filterByTk: id }, data: values });\\n  }\\n\\n  async function setThiSinhAssoc(kyThiId, nldIds) {\\n    await ctx.request({\\n      url: 'ky_thi/' + kyThiId + '/thi_sinh:set',\\n      method: 'post',\\n      data: nldIds.map(function(x) { return Number(x); }),\\n    });\\n  }\\n\\n  async function loadThiSinhForKyThi(kyThiId) {\\n    try {\\n      var res = await ctx.request({ url: 'ky_thi/' + kyThiId + '/thi_sinh:list', method: 'get', params: { pageSize: 500 } });\\n      return (res?.data?.data || []).map(function(ts) { return ts.id; });\\n    } catch (e) { return []; }\\n  }\\n\\n  function formatDate(val) {\\n    if (!val) return '-';\\n    try {\\n      var d = new Date(val);\\n      if (isNaN(d.getTime())) return val;\\n      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();\\n    } catch (e) { return val; }\\n  }\\n\\n  function formatDateTime(val) {\\n    if (!val) return '-';\\n    try {\\n      var d = new Date(val);\\n      if (isNaN(d.getTime())) return val;\\n      return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear() + ' ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');\\n    } catch (e) { return val; }\\n  }\\n\\n  function ThiSinhPicker(props) {\\n    var selectedIds = props.selectedIds || [];\\n    var onChange = props.onChange;\\n    const [open, setOpen] = useState(false);\\n    const [tempSelected, setTempSelected] = useState([]);\\n    const [activeTab, setActiveTab] = useState('byClass');\\n    const [searchLop, setSearchLop] = useState('');\\n    const [searchTS, setSearchTS] = useState('');\\n    const [filterBacTho, setFilterBacTho] = useState(undefined);\\n\\n    var handleOpen = useCallback(function() {\\n      setTempSelected(selectedIds.map(function(x) { return Number(x); }));\\n      setSearchLop('');\\n      setSearchTS('');\\n      setFilterBacTho(undefined);\\n      setActiveTab('byClass');\\n      setOpen(true);\\n    }, [selectedIds]);\\n\\n    var handleConfirm = useCallback(function() {\\n      onChange(tempSelected);\\n      setOpen(false);\\n    }, [tempSelected, onChange]);\\n\\n    var toggleClassStudents = useCallback(function(lop, checked) {\\n      var studentIds = (lop.hoc_vien_lop || []).map(function(h) { return h.nguoi_lao_dong ? h.nguoi_lao_dong.id : h.nguoiLaoDongId; }).filter(Boolean).map(Number);\\n      setTempSelected(function(prev) {\\n        if (checked) {\\n          var combined = prev.slice();\\n          studentIds.forEach(function(id) { if (combined.indexOf(id) === -1) combined.push(id); });\\n          return combined;\\n        } else {\\n          return prev.filter(function(id) { return studentIds.indexOf(id) === -1; });\\n        }\\n      });\\n    }, []);\\n\\n    var isClassSelected = useCallback(function(lop) {\\n      var studentIds = (lop.hoc_vien_lop || []).map(function(h) { return h.nguoi_lao_dong ? h.nguoi_lao_dong.id : h.nguoiLaoDongId; }).filter(Boolean).map(Number);\\n      if (studentIds.length === 0) return false;\\n      return studentIds.every(function(id) { return tempSelected.indexOf(id) !== -1; });\\n    }, [tempSelected]);\\n\\n    var filteredLop = useMemo(function() {\\n      if (!searchLop) return lopHocList;\\n      var s = searchLop.toLowerCase();\\n      return lopHocList.filter(function(l) {\\n        return (l.ten_lop || '').toLowerCase().includes(s) || (l.ma_lop || '').toLowerCase().includes(s);\\n      });\\n    }, [searchLop]);\\n\\n    var sortedNld = useMemo(function() {\\n      return allNld.slice().sort(function(a, b) {\\n        var aOrder = a.bac_tho?.thu_tu ?? 9999;\\n        var bOrder = b.bac_tho?.thu_tu ?? 9999;\\n        return aOrder - bOrder;\\n      });\\n    }, []);\\n\\n    var filteredNld = useMemo(function() {\\n      var list = sortedNld;\\n      if (filterBacTho != null) {\\n        list = list.filter(function(p) { return p.bacThoId === filterBacTho; });\\n      }\\n      if (searchTS) {\\n        var s = searchTS.toLowerCase();\\n        list = list.filter(function(p) { return (p.ho_ten || '').toLowerCase().includes(s); });\\n      }\\n      return list;\\n    }, [sortedNld, searchTS, filterBacTho]);\\n\\n    var selectedCount = tempSelected.length;\\n    var selectedNames = useMemo(function() {\\n      if (selectedIds.length === 0) return [];\\n      return selectedIds.slice(0, 5).map(function(id) {\\n        var p = allNld.find(function(x) { return String(x.id) === String(id); });\\n        return p ? p.ho_ten : String(id);\\n      });\\n    }, [selectedIds]);\\n\\n    var lopColumns = [\\n      { title: ctx.t('Tên lớp'), dataIndex: 'ten_lop', key: 'ten_lop', render: function(v) { return v || '-'; } },\\n      { title: ctx.t('Hình thức'), dataIndex: 'hinh_thuc', key: 'hinh_thuc', width: 100,\\n        render: function(v) { var h = HINH_THUC_MAP[v]; return h ? <Tag color={h.color}>{h.label}</Tag> : (v || '-'); } },\\n      { title: ctx.t('Số học viên'), key: 'count', width: 100, align: 'center',\\n        render: function(_, r) { return (r.hoc_vien_lop || []).length; } },\\n    ];\\n\\n    var nldColumns = [\\n      { title: ctx.t('Họ và tên'), dataIndex: 'ho_ten', key: 'ho_ten', render: function(v) { return v || '-'; } },\\n      { title: ctx.t('Bậc thợ'), key: 'bac_tho', width: 160,\\n        render: function(_, r) { return r.bac_tho?.ten_bac || '-'; } },\\n    ];\\n\\n    return (\\n      <>\\n        <div\\n          onClick={handleOpen}\\n          style={{ border: '1px solid #d9d9d9', borderRadius: 6, padding: '4px 8px', minHeight: 32, cursor: 'pointer', display: 'flex', flexWrap: 'wrap', gap: 4, alignItems: 'center', background: '#fff' }}\\n        >\\n          {selectedIds.length > 0\\n            ? <>\\n                {selectedNames.map(function(name, i) { return <Tag key={i} color=\\"blue\\">{name}</Tag>; })}\\n                {selectedIds.length > 5 && <Tag>+{selectedIds.length - 5}</Tag>}\\n              </>\\n            : <span style={{ color: '#bfbfbf' }}>{ctx.t('Ấn để chọn thí sinh...')}</span>\\n          }\\n        </div>\\n        <Modal\\n          title={ctx.t('Chọn danh sách thí sinh')}\\n          open={open}\\n          onOk={handleConfirm}\\n          onCancel={function() { setOpen(false); }}\\n          width={720}\\n          okText={ctx.t('Xác nhận')}\\n          cancelText={ctx.t('Hủy')}\\n        >\\n          <div style={{ marginBottom: 8, color: '#8c8c8c', fontSize: 12 }}>\\n            {ctx.t('Đã chọn')}: {selectedCount} {ctx.t('thí sinh')}\\n          </div>\\n          <Tabs activeKey={activeTab} onChange={setActiveTab} items={[\\n            { key: 'byClass', label: ctx.t('Theo lớp'), children: (\\n              <>\\n                <Input placeholder={ctx.t('Tìm kiếm lớp...')} prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n                  allowClear value={searchLop} onChange={function(e) { setSearchLop(e.target.value); }}\\n                  style={{ marginBottom: 8 }} />\\n                <Table dataSource={filteredLop} rowKey=\\"id\\" size=\\"small\\" scroll={{ y: 300 }} pagination={false}\\n                  columns={lopColumns}\\n                  rowSelection={{\\n                    selectedRowKeys: filteredLop.filter(function(l) { return isClassSelected(l); }).map(function(l) { return l.id; }),\\n                    onSelect: function(record, checked) { toggleClassStudents(record, checked); },\\n                    onSelectAll: function(checked, selectedRows) {\\n                      selectedRows.forEach(function(r) { if (r) toggleClassStudents(r, checked); });\\n                    },\\n                    getCheckboxProps: function(record) {\\n                      return { disabled: (record.hoc_vien_lop || []).length === 0 };\\n                    },\\n                  }}\\n                />\\n              </>\\n            )},\\n            { key: 'byPerson', label: ctx.t('Theo thí sinh'), children: (\\n              <>\\n                <Space style={{ marginBottom: 8, width: '100%' }} direction=\\"vertical\\" size={8}>\\n                  <Input placeholder={ctx.t('Tìm kiếm theo tên...')} prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n                    allowClear value={searchTS} onChange={function(e) { setSearchTS(e.target.value); }} />\\n                  <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Lọc theo bậc thợ')}\\n                    style={{ width: '100%' }} value={filterBacTho} onChange={function(v) { setFilterBacTho(v); }}\\n                    options={bacThoList.map(function(b) { return { value: b.id, label: b.ten_bac }; })} />\\n                </Space>\\n                <Table dataSource={filteredNld} rowKey=\\"id\\" size=\\"small\\" scroll={{ y: 300 }} pagination={false}\\n                  columns={nldColumns}\\n                  rowSelection={{ selectedRowKeys: tempSelected, onChange: function(keys) { setTempSelected(keys); } }}\\n                />\\n              </>\\n            )},\\n          ]} />\\n        </Modal>\\n      </>\\n    );\\n  }\\n\\n  function TableApp() {\\n    const [rows, setRows] = useState(initialRows);\\n    const [totalCount, setTotalCount] = useState(initialTotal);\\n    const [searchText, setSearchText] = useState('');\\n    const [currentPage, setCurrentPage] = useState(1);\\n    const [loading, setLoading] = useState(false);\\n    const [viewRecord, setViewRecord] = useState(null);\\n    const [formOpen, setFormOpen] = useState(false);\\n    const [editingId, setEditingId] = useState(null);\\n    const [formLoading, setFormLoading] = useState(false);\\n    const [selectedTS, setSelectedTS] = useState([]);\\n    const [form] = Form.useForm();\\n    var pageSize = 10;\\n\\n    var stats = useMemo(function() {\\n      var total = rows.length;\\n      var banNhap = rows.filter(function(r) { return r.trang_thai === 'ban_nhap' || r.trang_thai === 'tu_choi'; }).length;\\n      var choPD = rows.filter(function(r) { return r.trang_thai === 'cho_phe_duyet'; }).length;\\n      var daPD = rows.filter(function(r) { return r.trang_thai === 'da_phe_duyet' || r.trang_thai === 'da_duyet'; }).length;\\n      var dangChamHoacXong = rows.filter(function(r) { return r.trang_thai === 'dang_cham_diem' || r.trang_thai === 'hoan_thanh' || r.trang_thai === 'dang_mo' || r.trang_thai === 'sap_dien_ra' || r.trang_thai === 'lap_lich'; }).length;\\n      return { total: total, banNhap: banNhap, choPD: choPD, daPD: daPD, dangChamHoacXong: dangChamHoacXong };\\n    }, [rows]);\\n\\n    var refreshData = useCallback(async function() {\\n      setLoading(true);\\n      try {\\n        var result = await fetchRows();\\n        setRows(result.rows);\\n        setTotalCount(result.count || result.rows.length);\\n      } catch (e) { ctx.message.error(String(e?.message || e)); }\\n      setLoading(false);\\n    }, []);\\n\\n    var handleDelete = useCallback(async function(id) {\\n      try {\\n        await deleteRow(id);\\n        ctx.message.success(ctx.t('Đã xóa thành công'));\\n        refreshData();\\n      } catch (e) { ctx.message.error(String(e?.message || e)); }\\n    }, [refreshData]);\\n\\n    var handleSendApproval = useCallback(async function(id) {\\n      try {\\n        await updateRow(id, { trang_thai: 'cho_phe_duyet' });\\n        ctx.message.success(ctx.t('Đã gửi duyệt kỳ thi'));\\n        refreshData();\\n      } catch (e) { ctx.message.error(ctx.t('Lỗi gửi duyệt: ') + String(e?.message || e)); }\\n    }, [refreshData]);\\n\\n    var handleApprove = useCallback(async function(id) {\\n      try {\\n        await updateRow(id, { trang_thai: 'da_phe_duyet' });\\n        ctx.message.success(ctx.t('Đã phê duyệt kỳ thi'));\\n        refreshData();\\n      } catch (e) { ctx.message.error(ctx.t('Lỗi phê duyệt: ') + String(e?.message || e)); }\\n    }, [refreshData]);\\n\\n    var openCreate = useCallback(function() {\\n      setEditingId(null);\\n      form.resetFields();\\n      form.setFieldsValue({ trang_thai: 'ban_nhap', hinh_thuc: 'truc_tiep' });\\n      setSelectedTS([]);\\n      setFormOpen(true);\\n    }, [form]);\\n\\n    var openEdit = useCallback(async function(record) {\\n      setEditingId(record.id);\\n      form.resetFields();\\n      form.setFieldsValue({\\n        ten_ky_thi: record.ten_ky_thi,\\n        don_vi_id: record.don_vi_id ? String(record.don_vi_id) : undefined,\\n        nganh_nghe_id: record.nganh_nghe_id ? String(record.nganh_nghe_id) : undefined,\\n        hinh_thuc: record.hinh_thuc,\\n        thoi_gian_bat_dau: record.thoi_gian_bat_dau ? record.thoi_gian_bat_dau.substring(0, 16) : undefined,\\n        thoi_gian_ket_thuc: record.thoi_gian_ket_thuc ? record.thoi_gian_ket_thuc.substring(0, 16) : undefined,\\n        de_thi_id: record.de_thi_id ? String(record.de_thi_id) : undefined,\\n        diem_dat: record.diem_dat,\\n        ca_thi: record.ca_thi,\\n        quy_che_thi: record.quy_che_thi,\\n        trang_thai: record.trang_thai,\\n      });\\n      setSelectedTS([]);\\n      setFormOpen(true);\\n      var tsIds = await loadThiSinhForKyThi(record.id);\\n      setSelectedTS(tsIds);\\n    }, [form]);\\n\\n    var handleSave = useCallback(async function() {\\n      try {\\n        var values = await form.validateFields();\\n        setFormLoading(true);\\n        if (values.don_vi_id) values.don_vi_id = Number(values.don_vi_id); else delete values.don_vi_id;\\n        if (values.nganh_nghe_id) values.nganh_nghe_id = Number(values.nganh_nghe_id); else delete values.nganh_nghe_id;\\n        if (values.de_thi_id) values.de_thi_id = Number(values.de_thi_id); else delete values.de_thi_id;\\n        values.so_thi_sinh = selectedTS.length;\\n        if (editingId) {\\n          values.trang_thai = 'ban_nhap';\\n          await updateRow(editingId, values);\\n          if (selectedTS.length > 0) await setThiSinhAssoc(editingId, selectedTS);\\n          ctx.message.success(ctx.t('Cập nhật thành công, trạng thái đã chuyển về Bản nháp'));\\n        } else {\\n          values.trang_thai = 'ban_nhap';\\n          var created = await createRow(values);\\n          var newId = created?.id;\\n          if (newId && selectedTS.length > 0) await setThiSinhAssoc(newId, selectedTS);\\n          ctx.message.success(ctx.t('Thêm mới thành công'));\\n        }\\n        setFormOpen(false);\\n        setEditingId(null);\\n        form.resetFields();\\n        setSelectedTS([]);\\n        refreshData();\\n      } catch (e) {\\n        if (e?.errorFields) return;\\n        ctx.message.error(String(e?.message || e));\\n      } finally { setFormLoading(false); }\\n    }, [editingId, form, refreshData, selectedTS]);\\n\\n    var filtered = useMemo(function() {\\n      if (!searchText) return rows;\\n      var s = searchText.toLowerCase();\\n      return rows.filter(function(r) {\\n        return (r.ma_ky_thi || '').toLowerCase().includes(s) ||\\n          (r.ten_ky_thi || '').toLowerCase().includes(s) ||\\n          (r.don_vi?.ten_don_vi || '').toLowerCase().includes(s) ||\\n          (r.de_thi?.ten_de_thi || '').toLowerCase().includes(s);\\n      });\\n    }, [rows, searchText]);\\n\\n    var columns = [\\n      { title: ctx.t('Mã kỳ thi'), dataIndex: 'ma_ky_thi', key: 'ma_ky_thi', width: 120, fixed: 'left',\\n        render: function(val) { return <Typography.Text strong style={{ color: '#1677ff' }}>{val || '-'}</Typography.Text>; } },\\n      { title: ctx.t('Tên kỳ thi'), dataIndex: 'ten_ky_thi', key: 'ten_ky_thi', ellipsis: { showTitle: false },\\n        render: function(val) { return <Tooltip title={val}><span>{val || '-'}</span></Tooltip>; } },\\n      { title: ctx.t('Hình thức'), dataIndex: 'hinh_thuc', key: 'hinh_thuc', width: 110,\\n        render: function(val) { var h = HINH_THUC_MAP[val]; return h ? <Tag color={h.color}>{h.label}</Tag> : (val || '-'); } },\\n      { title: ctx.t('Đơn vị'), key: 'don_vi', ellipsis: true,\\n        render: function(_, r) { return r.don_vi?.ten_don_vi || '-'; } },\\n      { title: ctx.t('Số thí sinh'), key: 'so_thi_sinh', width: 100, align: 'center',\\n        render: function(_, r) { var c = r.so_thi_sinh || 0; return <Tag icon={<UserOutlined />} color={c > 0 ? 'blue' : 'default'}>{c}</Tag>; } },\\n      { title: ctx.t('Đề thi'), key: 'de_thi', ellipsis: true,\\n        render: function(_, r) { return r.de_thi?.ten_de_thi || '-'; } },\\n      { title: ctx.t('Trạng thái'), dataIndex: 'trang_thai', key: 'trang_thai', width: 110, align: 'center',\\n        render: function(val) { var s = STATUS_MAP[val]; return s ? <Tag color={s.color}>{s.label}</Tag> : (val || '-'); } },\\n      { title: ctx.t('Thời gian bắt đầu'), dataIndex: 'thoi_gian_bat_dau', key: 'thoi_gian_bat_dau', width: 140,\\n        render: function(val) { return formatDateTime(val); } },\\n      { title: ctx.t('Thao tác'), key: 'actions', width: 200, fixed: 'right',\\n        render: function(_, record) {\\n          return (\\n            <Space size={4}>\\n              <Tooltip title={ctx.t('Xem')}><Button icon={<EyeOutlined />} onClick={function() { setViewRecord(record); }} /></Tooltip>\\n              <Tooltip title={ctx.t('Sửa')}><Button icon={<EditOutlined />} onClick={function() { openEdit(record); }} /></Tooltip>\\n              {(!record.trang_thai || record.trang_thai === 'ban_nhap' || record.trang_thai === 'tu_choi') && (\\n                <Tooltip title={ctx.t('Gửi duyệt')}><Button icon={<SendOutlined />} onClick={function() { handleSendApproval(record.id); }} /></Tooltip>\\n              )}\\n              {record.trang_thai === 'cho_phe_duyet' && (\\n                <Popconfirm title={ctx.t('Phê duyệt kỳ thi này?')} onConfirm={function() { handleApprove(record.id); }} okText={ctx.t('Phê duyệt')} cancelText={ctx.t('Huỷ')}>\\n                  <Tooltip title={ctx.t('Phê duyệt')}><Button style={{ color: '#52c41a', borderColor: '#52c41a' }} icon={<CheckCircleOutlined />} /></Tooltip>\\n                </Popconfirm>\\n              )}\\n              <Popconfirm title={ctx.t('Xác nhận xóa kỳ thi này?')} okText={ctx.t('Xóa')} cancelText={ctx.t('Hủy')} onConfirm={function() { handleDelete(record.id); }}>\\n                <Tooltip title={ctx.t('Xóa')}><Button danger icon={<DeleteOutlined />} /></Tooltip>\\n              </Popconfirm>\\n            </Space>\\n          );\\n        },\\n      },\\n    ];\\n\\n    var statCards = (\\n      <div style={{ display: 'flex', gap: 16, marginBottom: 16, flexWrap: 'wrap' }}>\\n        {[\\n          { label: ctx.t('Tổng kỳ thi'), value: stats.total, icon: <TeamOutlined style={{ fontSize: 20, color: '#1677ff' }} />, bg: '#e6f4ff' },\\n          { label: ctx.t('Bản nháp'), value: stats.banNhap, icon: <EditOutlined style={{ fontSize: 20, color: '#faad14' }} />, bg: '#fffbe6' },\\n          { label: ctx.t('Chờ phê duyệt'), value: stats.choPD, icon: <SendOutlined style={{ fontSize: 20, color: '#1677ff' }} />, bg: '#e6f4ff' },\\n          { label: ctx.t('Đã phê duyệt'), value: stats.daPD, icon: <CheckCircleOutlined style={{ fontSize: 20, color: '#52c41a' }} />, bg: '#f6ffed' },\\n          { label: ctx.t('Đang diễn ra'), value: stats.dangChamHoacXong, icon: <EyeOutlined style={{ fontSize: 20, color: '#722ed1' }} />, bg: '#f9f0ff' },\\n        ].map(function(s, i) {\\n          return (\\n            <Card key={i} size=\\"small\\" style={{ flex: '1 1 180px', minWidth: 160 }}>\\n              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>\\n                <div><div style={{ color: '#8c8c8c', fontSize: 13 }}>{s.label}</div><div style={{ fontSize: 24, fontWeight: 600 }}>{s.value}</div></div>\\n                <div style={{ width: 40, height: 40, borderRadius: '50%', background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{s.icon}</div>\\n              </div>\\n            </Card>\\n          );\\n        })}\\n      </div>\\n    );\\n\\n    var formFields = (\\n      <Form form={form} layout=\\"vertical\\" autoComplete=\\"off\\">\\n        <Form.Item name=\\"ten_ky_thi\\" label={ctx.t('Tên kỳ thi')} rules={[{ required: true, message: ctx.t('Vui lòng nhập tên kỳ thi') }]}>\\n          <Input placeholder={ctx.t('Nhập tên kỳ thi')} />\\n        </Form.Item>\\n        <Form.Item name=\\"don_vi_id\\" label={ctx.t('Đơn vị')}>\\n          <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Chọn đơn vị')}\\n            options={donViList.map(function(d) { return { value: String(d.id), label: d.ten_don_vi || String(d.id) }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"nganh_nghe_id\\" label={ctx.t('Ngành nghề')}>\\n          <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Chọn ngành nghề')}\\n            options={nganhNgheList.map(function(n) { return { value: String(n.id), label: n.ten_nganh || n.ma_nganh || String(n.id) }; })} />\\n        </Form.Item>\\n        <Form.Item name=\\"hinh_thuc\\" label={ctx.t('Hình thức')}>\\n          <Select placeholder={ctx.t('Chọn hình thức')} options={HINH_THUC_OPTIONS.map(function(h) { return { value: h.value, label: h.label }; })} />\\n        </Form.Item>\\n        <div style={{ display: 'flex', gap: 12 }}>\\n          <Form.Item name=\\"thoi_gian_bat_dau\\" label={ctx.t('Thời gian bắt đầu')} style={{ flex: 1 }}>\\n            <Input type=\\"datetime-local\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"thoi_gian_ket_thuc\\" label={ctx.t('Thời gian kết thúc')} style={{ flex: 1 }}>\\n            <Input type=\\"datetime-local\\" />\\n          </Form.Item>\\n        </div>\\n        <Form.Item label={ctx.t('Danh sách thí sinh')}>\\n          <ThiSinhPicker selectedIds={selectedTS} onChange={setSelectedTS} />\\n        </Form.Item>\\n        <Form.Item name=\\"de_thi_id\\" label={ctx.t('Đề thi sử dụng')}>\\n          <Select allowClear showSearch optionFilterProp=\\"label\\" placeholder={ctx.t('Chọn đề thi')}\\n            options={deThiList.map(function(d) { return { value: String(d.id), label: d.ten_de_thi || d.ma_de_thi || String(d.id) }; })} />\\n        </Form.Item>\\n        <div style={{ display: 'flex', gap: 12 }}>\\n          <Form.Item name=\\"diem_dat\\" label={ctx.t('Điểm đạt')} style={{ flex: 1 }}>\\n            <InputNumber min={0} max={100} style={{ width: '100%' }} placeholder={ctx.t('Nhập điểm đạt')} />\\n          </Form.Item>\\n          <Form.Item name=\\"ca_thi\\" label={ctx.t('Ca thi')} style={{ flex: 1 }}>\\n            <Input placeholder={ctx.t('Nhập ca thi')} />\\n          </Form.Item>\\n        </div>\\n        <Form.Item name=\\"quy_che_thi\\" label={ctx.t('Quy chế thi')}>\\n          <Input.TextArea rows={3} placeholder={ctx.t('Nhập quy chế thi')} />\\n        </Form.Item>\\n      </Form>\\n    );\\n\\n    return (\\n      <>\\n        {statCards}\\n        <Card size=\\"small\\" styles={{ body: { padding: 0 } }}>\\n          <div style={{ padding: '12px 16px', borderBottom: '1px solid #f0f0f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>\\n            <Space>\\n              <Typography.Text strong style={{ fontSize: 15 }}>\\n                {ctx.t('Danh sách kỳ thi')} ({totalCount})\\n              </Typography.Text>\\n              <Tooltip title={ctx.t('Tải lại')}>\\n                <Button type=\\"text\\" size=\\"small\\" icon={<ReloadOutlined />} onClick={refreshData} loading={loading} />\\n              </Tooltip>\\n            </Space>\\n            <Space size=\\"small\\">\\n              <Input placeholder={ctx.t('Tìm kiếm theo tên, mã kỳ thi...')} prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}\\n                allowClear style={{ width: 280 }}\\n                onChange={function(e) { setSearchText(e.target.value); setCurrentPage(1); }} />\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={openCreate}>{ctx.t('Thêm mới')}</Button>\\n            </Space>\\n          </div>\\n          <Table columns={columns} dataSource={filtered} rowKey=\\"id\\" size=\\"small\\" loading={loading} scroll={{ x: 1400 }}\\n            pagination={{ current: currentPage, pageSize: pageSize, total: filtered.length, showTotal: function(t) { return ctx.t('Tổng') + ': ' + t + ' ' + ctx.t('kỳ thi'); }, showSizeChanger: false, size: 'small', onChange: function(p) { setCurrentPage(p); } }}\\n          />\\n        </Card>\\n\\n        <Modal title={ctx.t('Chi tiết kỳ thi')} open={!!viewRecord} onCancel={function() { setViewRecord(null); }}\\n          footer={[\\n            <Button key=\\"edit\\" type=\\"primary\\" icon={<EditOutlined />} onClick={function() { var r = viewRecord; setViewRecord(null); openEdit(r); }}>{ctx.t('Sửa')}</Button>,\\n            <Button key=\\"close\\" onClick={function() { setViewRecord(null); }}>{ctx.t('Đóng')}</Button>,\\n          ]}\\n          width={700}\\n        >\\n          {viewRecord && (\\n            <Descriptions column={2} bordered size=\\"small\\">\\n              <Descriptions.Item label={ctx.t('Mã kỳ thi')}>{viewRecord.ma_ky_thi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Trạng thái')}>\\n                {(function() { var s = STATUS_MAP[viewRecord.trang_thai]; return s ? <Tag color={s.color}>{s.label}</Tag> : viewRecord.trang_thai || '-'; })()}\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Tên kỳ thi')} span={2}>{viewRecord.ten_ky_thi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Hình thức')}>\\n                {(function() { var h = HINH_THUC_MAP[viewRecord.hinh_thuc]; return h ? <Tag color={h.color}>{h.label}</Tag> : viewRecord.hinh_thuc || '-'; })()}\\n              </Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Đơn vị')}>{viewRecord.don_vi?.ten_don_vi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ngành nghề')}>{viewRecord.nganh_nghe?.ten_nganh || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Đề thi')}>{viewRecord.de_thi?.ten_de_thi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Thời gian bắt đầu')}>{formatDateTime(viewRecord.thoi_gian_bat_dau)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Thời gian kết thúc')}>{formatDateTime(viewRecord.thoi_gian_ket_thuc)}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Số thí sinh')}>{viewRecord.so_thi_sinh || 0}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Điểm đạt')}>{viewRecord.diem_dat ?? '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Ca thi')}>{viewRecord.ca_thi || '-'}</Descriptions.Item>\\n              <Descriptions.Item label={ctx.t('Quy chế thi')} span={2}>{viewRecord.quy_che_thi || '-'}</Descriptions.Item>\\n            </Descriptions>\\n          )}\\n        </Modal>\\n\\n        <Drawer title={editingId ? ctx.t('Sửa kỳ thi') : ctx.t('Thêm mới kỳ thi')} open={formOpen}\\n          onClose={function() { setFormOpen(false); setEditingId(null); form.resetFields(); setSelectedTS([]); }}\\n          width={560}\\n          extra={\\n            <Space>\\n              <Button onClick={function() { setFormOpen(false); setEditingId(null); form.resetFields(); setSelectedTS([]); }}>{ctx.t('Hủy')}</Button>\\n              <Button type=\\"primary\\" onClick={handleSave} loading={formLoading}>{ctx.t('Lưu')}</Button>\\n            </Space>\\n          }\\n        >\\n          {formFields}\\n        </Drawer>\\n      </>\\n    );\\n  }\\n\\n  ctx.render(<TableApp />);\\n} catch (error) {\\n  ctx.render(\\n    <Alert showIcon type=\\"error\\" message={ctx.t('Không tải được danh sách kỳ thi')} description={String(error?.message || error)} />,\\n  );\\n}\\n"}}}}
