x2s46qsmp19	x2s46qsmp19	{"parentId":"a0sajt7zcfl","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Hồ sơ doanh nghiệp"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ============================================================\\n// JS Block: Ho so doanh nghiep\\n// Collection: doanh_nghiep\\n// ============================================================\\n\\n// --- 1. Top-level data loading ---\\nasync function fetchDoanhNghiep() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('doanh_nghiep');\\n  res.setAppends(['nguoi_lao_dong']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialData = await fetchDoanhNghiep();\\n\\n// --- 2. Libs ---\\nconst {\\n  Table, Button, Input, Select, Tag, Space, Card, Row, Col, Modal,\\n  Form, Drawer, Popconfirm, Tooltip, Typography, Statistic,\\n  Descriptions, Pagination, Spin, Divider, Badge,\\n} = ctx.libs.antd;\\n\\nconst {\\n  SearchOutlined, PlusOutlined, EditOutlined, EyeOutlined,\\n  DeleteOutlined, ReloadOutlined, BankOutlined, TeamOutlined,\\n  CheckCircleOutlined, CloseCircleOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst React = ctx.libs.React;\\nconst { useState, useCallback, useMemo } = React;\\nconst dayjs = ctx.libs.dayjs;\\n\\n// --- 3. Constants ---\\nconst TRANG_THAI_OPTIONS = [\\n  { value: 'hoat_dong', label: 'Hoạt động', color: 'green' },\\n  { value: 'ngung_hoat_dong', label: 'Ngừng hoạt động', color: 'red' },\\n];\\n\\nconst TRANG_THAI_MAP = {\\n  hoat_dong: { color: 'green', text: 'Hoạt động' },\\n  ngung_hoat_dong: { color: 'red', text: 'Ngừng hoạt động' },\\n};\\n\\nconst LINH_VUC_OPTIONS = [\\n  { value: 'san_xuat', label: 'Sản xuất', color: 'blue' },\\n  { value: 'xay_dung', label: 'Xây dựng', color: 'orange' },\\n  { value: 'khai_thac_mo', label: 'Khai thác mỏ', color: 'red' },\\n  { value: 'hoa_chat', label: 'Hóa chất', color: 'purple' },\\n  { value: 'dien_luc', label: 'Điện lực', color: 'gold' },\\n  { value: 'giao_thong_van_tai', label: 'Giao thông vận tải', color: 'green' },\\n  { value: 'nong_lam_ngu_nghiep', label: 'Nông lâm ngư nghiệp', color: 'cyan' },\\n  { value: 'khac', label: 'Khác', color: 'default' },\\n];\\n\\nconst LINH_VUC_MAP = {};\\nLINH_VUC_OPTIONS.forEach(function(o) { LINH_VUC_MAP[o.value] = o; });\\n\\n// --- 4. React Component ---\\nconst DoanhNghiepBlock = ({ initData, reloadFn }) => {\\n  const [loading, setLoading] = useState(false);\\n  const [allData, setAllData] = useState(initData);\\n  const [page, setPage] = useState(1);\\n  const [pageSize] = useState(20);\\n  const [searchText, setSearchText] = useState('');\\n  const [filterTrangThai, setFilterTrangThai] = useState(null);\\n\\n  const [viewVisible, setViewVisible] = useState(false);\\n  const [viewRecord, setViewRecord] = useState(null);\\n  const [editVisible, setEditVisible] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [addVisible, setAddVisible] = useState(false);\\n  const [submitting, setSubmitting] = useState(false);\\n\\n  const [editForm] = Form.useForm();\\n  const [addForm] = Form.useForm();\\n\\n  const activeRows = useMemo(() => {\\n    return (allData || []).filter((r) => !r.is_deleted);\\n  }, [allData]);\\n\\n  const stats = useMemo(() => {\\n    var total = 0, hoatDong = 0, ngungHoatDong = 0, tongNLD = 0;\\n    for (var i = 0; i < activeRows.length; i++) {\\n      var r = activeRows[i];\\n      total++;\\n      if (r.trang_thai === 'hoat_dong') hoatDong++;\\n      else if (r.trang_thai === 'ngung_hoat_dong') ngungHoatDong++;\\n      var nld = r.nguoi_lao_dong;\\n      if (nld && Array.isArray(nld)) tongNLD += nld.length;\\n    }\\n    return { total: total, hoatDong: hoatDong, ngungHoatDong: ngungHoatDong, tongNLD: tongNLD };\\n  }, [activeRows]);\\n\\n  const filteredData = useMemo(() => {\\n    var rows = activeRows;\\n    if (searchText && searchText.trim()) {\\n      var s = searchText.trim().toLowerCase();\\n      rows = rows.filter((r) =>\\n        (r.ten_doanh_nghiep && r.ten_doanh_nghiep.toLowerCase().indexOf(s) >= 0) ||\\n        (r.ma_doanh_nghiep && r.ma_doanh_nghiep.toLowerCase().indexOf(s) >= 0) ||\\n        (r.ma_so_thue && r.ma_so_thue.toLowerCase().indexOf(s) >= 0) ||\\n        (r.email && r.email.toLowerCase().indexOf(s) >= 0)\\n      );\\n    }\\n    if (filterTrangThai) {\\n      rows = rows.filter((r) => r.trang_thai === filterTrangThai);\\n    }\\n    return rows;\\n  }, [activeRows, searchText, filterTrangThai]);\\n\\n  const paginatedData = useMemo(() => {\\n    return filteredData.slice((page - 1) * pageSize, page * pageSize);\\n  }, [filteredData, page, pageSize]);\\n\\n  const fetchData = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await reloadFn();\\n      setAllData(newData);\\n    } catch (err) {\\n      ctx.message.error('Không thể tải dữ liệu doanh nghiệp');\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [reloadFn]);\\n\\n  const handleView = (record) => {\\n    setViewRecord(record);\\n    setViewVisible(true);\\n  };\\n\\n  const handleEdit = (record) => {\\n    setEditRecord(record);\\n    editForm.setFieldsValue({\\n      ma_doanh_nghiep: record.ma_doanh_nghiep,\\n      ten_doanh_nghiep: record.ten_doanh_nghiep,\\n      ma_so_thue: record.ma_so_thue,\\n      dia_chi: record.dia_chi,\\n      nguoi_lien_he: record.nguoi_lien_he,\\n      dien_thoai: record.dien_thoai,\\n      email: record.email,\\n      trang_thai: record.trang_thai,\\n      linh_vuc_hoat_dong: record.linh_vuc_hoat_dong,\\n    });\\n    setEditVisible(true);\\n  };\\n\\n  const handleEditSubmit = async () => {\\n    try {\\n      const values = await editForm.validateFields();\\n      setSubmitting(true);\\n      await ctx.request({\\n        url: 'doanh_nghiep:update',\\n        method: 'post',\\n        params: { filterByTk: editRecord.id },\\n        data: values,\\n      });\\n      ctx.message.success('Cập nhật thành công');\\n      setEditVisible(false);\\n      editForm.resetFields();\\n      fetchData();\\n    } catch (err) {\\n      if (err && err.errorFields) return;\\n      ctx.message.error('Cập nhật thất bại');\\n    } finally {\\n      setSubmitting(false);\\n    }\\n  };\\n\\n  const handleAddOpen = () => {\\n    addForm.resetFields();\\n    setAddVisible(true);\\n  };\\n\\n  const handleAddSubmit = async () => {\\n    try {\\n      const values = await addForm.validateFields();\\n      setSubmitting(true);\\n      await ctx.request({\\n        url: 'doanh_nghiep:create',\\n        method: 'post',\\n        data: { ...values, is_deleted: false },\\n      });\\n      ctx.message.success('Thêm mới thành công');\\n      setAddVisible(false);\\n      addForm.resetFields();\\n      fetchData();\\n    } catch (err) {\\n      if (err && err.errorFields) return;\\n      ctx.message.error('Thêm mới thất bại');\\n    } finally {\\n      setSubmitting(false);\\n    }\\n  };\\n\\n  const handleDelete = async (record) => {\\n    try {\\n      await ctx.request({\\n        url: 'doanh_nghiep:update',\\n        method: 'post',\\n        params: { filterByTk: record.id },\\n        data: { is_deleted: true },\\n      });\\n      ctx.message.success('Xóa thành công');\\n      fetchData();\\n    } catch (err) {\\n      ctx.message.error('Xóa thất bại');\\n    }\\n  };\\n\\n  const columns = [\\n    {\\n      title: 'Mã DN',\\n      dataIndex: 'ma_doanh_nghiep',\\n      key: 'ma_doanh_nghiep',\\n      width: 120,\\n      ellipsis: true,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Tên doanh nghiệp',\\n      dataIndex: 'ten_doanh_nghiep',\\n      key: 'ten_doanh_nghiep',\\n      width: 220,\\n      ellipsis: true,\\n      render: (text) => React.createElement('span', { style: { fontWeight: 500 } }, text || '-'),\\n    },\\n    {\\n      title: 'Mã số thuế',\\n      dataIndex: 'ma_so_thue',\\n      key: 'ma_so_thue',\\n      width: 140,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Người liên hệ',\\n      dataIndex: 'nguoi_lien_he',\\n      key: 'nguoi_lien_he',\\n      width: 160,\\n      ellipsis: true,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Điện thoại',\\n      dataIndex: 'dien_thoai',\\n      key: 'dien_thoai',\\n      width: 130,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Email',\\n      dataIndex: 'email',\\n      key: 'email',\\n      width: 200,\\n      ellipsis: true,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Lĩnh vực',\\n      dataIndex: 'linh_vuc_hoat_dong',\\n      key: 'linh_vuc_hoat_dong',\\n      width: 160,\\n      render: (val) => {\\n        var info = LINH_VUC_MAP[val];\\n        if (!info) return '-';\\n        return React.createElement(Tag, { color: info.color }, info.label);\\n      },\\n    },\\n    {\\n      title: 'Số NLĐ',\\n      key: 'so_nld',\\n      width: 80,\\n      align: 'center',\\n      render: (_, record) => {\\n        var nld = record.nguoi_lao_dong;\\n        var count = (nld && Array.isArray(nld)) ? nld.length : 0;\\n        return React.createElement(Badge, { count: count, showZero: true, color: count > 0 ? 'blue' : 'default' });\\n      },\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      key: 'trang_thai',\\n      width: 140,\\n      render: (val) => {\\n        var info = TRANG_THAI_MAP[val];\\n        if (!info) return '-';\\n        return React.createElement(Tag, { color: info.color }, info.text);\\n      },\\n    },\\n    {\\n      title: 'Thao tác',\\n      key: 'actions',\\n      fixed: 'right',\\n      width: 150,\\n      render: (_, record) =>\\n        React.createElement(Space, { size: 4 },\\n          React.createElement(Tooltip, { title: 'Xem chi tiết' },\\n            React.createElement(Button, {\\n              icon: React.createElement(EyeOutlined),\\n              onClick: () => handleView(record),\\n            })\\n          ),\\n          React.createElement(Tooltip, { title: 'Chỉnh sửa' },\\n            React.createElement(Button, {\\n              icon: React.createElement(EditOutlined),\\n              onClick: () => handleEdit(record),\\n            })\\n          ),\\n          React.createElement(Popconfirm, {\\n            title: 'Xác nhận xóa',\\n            description: 'Bạn có chắc chắn muốn xóa doanh nghiệp này?',\\n            onConfirm: () => handleDelete(record),\\n            okText: 'Xóa',\\n            cancelText: 'Hủy',\\n          },\\n            React.createElement(Tooltip, { title: 'Xóa' },\\n              React.createElement(Button, {\\n                icon: React.createElement(DeleteOutlined),\\n                danger: true,\\n              })\\n            )\\n          ),\\n        ),\\n    },\\n  ];\\n\\n  const renderFormFields = () => {\\n    return React.createElement(React.Fragment, null,\\n      React.createElement(Form.Item, {\\n        name: 'ma_doanh_nghiep',\\n        label: 'Mã doanh nghiệp',\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập mã doanh nghiệp' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'ten_doanh_nghiep',\\n        label: 'Tên doanh nghiệp',\\n        rules: [{ required: true, message: 'Vui lòng nhập tên doanh nghiệp' }],\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập tên doanh nghiệp' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'ma_so_thue',\\n        label: 'Mã số thuế',\\n        rules: [{ required: true, message: 'Vui lòng nhập mã số thuế' }],\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập mã số thuế' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'dia_chi',\\n        label: 'Địa chỉ',\\n      },\\n        React.createElement(Input.TextArea, { rows: 2, placeholder: 'Nhập địa chỉ' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'nguoi_lien_he',\\n        label: 'Người liên hệ',\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập người liên hệ' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'dien_thoai',\\n        label: 'Điện thoại',\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập số điện thoại' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'email',\\n        label: 'Email',\\n        rules: [{ type: 'email', message: 'Email không hợp lệ' }],\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập email' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'linh_vuc_hoat_dong',\\n        label: 'Lĩnh vực hoạt động',\\n      },\\n        React.createElement(Select, {\\n          placeholder: 'Chọn lĩnh vực',\\n          allowClear: true,\\n          options: LINH_VUC_OPTIONS.map((o) => ({ value: o.value, label: o.label })),\\n        })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'trang_thai',\\n        label: 'Trạng thái',\\n        rules: [{ required: true, message: 'Vui lòng chọn trạng thái' }],\\n      },\\n        React.createElement(Select, {\\n          placeholder: 'Chọn trạng thái',\\n          options: TRANG_THAI_OPTIONS.map((o) => ({ value: o.value, label: o.label })),\\n        })\\n      ),\\n    );\\n  };\\n\\n  const renderNLDTable = (nldList) => {\\n    if (!nldList || !Array.isArray(nldList) || nldList.length === 0) {\\n      return React.createElement(Typography.Text, { type: 'secondary' }, 'Chưa có người lao động');\\n    }\\n    var nldCols = [\\n      { title: 'Họ tên', dataIndex: 'ho_ten', key: 'ho_ten', width: 180, render: (t) => t || '-' },\\n      { title: 'Số CCCD', dataIndex: 'so_giay_to', key: 'so_giay_to', width: 140, render: (t) => t || '-' },\\n      { title: 'Email', dataIndex: 'email', key: 'email', width: 200, ellipsis: true, render: (t) => t || '-' },\\n      { title: 'Đi