    value: stats.ngungHoatDong,\\n            prefix: React.createElement(CloseCircleOutlined),\\n            valueStyle: { color: '#ff4d4f' },\\n          })\\n        )\\n      ),\\n      React.createElement(Col, { xs: 12, sm: 6 },\\n        React.createElement(Card, { size: 'small', bordered: true },\\n          React.createElement(Statistic, {\\n            title: 'Tổng NLĐ',\\n            value: stats.tongNLD,\\n            prefix: React.createElement(TeamOutlined),\\n            valueStyle: { color: '#722ed1' },\\n          })\\n        )\\n      ),\\n    ),\\n    React.createElement(Card, { size: 'small', style: { marginBottom: 16 } },\\n      React.createElement(Row, { gutter: [12, 12], align: 'middle', justify: 'space-between' },\\n        React.createElement(Col, { flex: 'auto' },\\n          React.createElement(Space, { wrap: true, size: 12 },\\n            React.createElement(Input, {\\n              placeholder: 'Tìm kiếm theo tên, mã DN, MST, email...',\\n              prefix: React.createElement(SearchOutlined),\\n              value: searchText,\\n              onChange: (e) => setSearchText(e.target.value),\\n              onPressEnter: () => setPage(1),\\n              style: { width: 360 },\\n              allowClear: true,\\n            }),\\n            React.createElement(Select, {\\n              placeholder: 'Trạng thái',\\n              value: filterTrangThai,\\n              onChange: (val) => { setFilterTrangThai(val || null); setPage(1); },\\n              allowClear: true,\\n              style: { width: 180 },\\n              options: TRANG_THAI_OPTIONS.map((o) => ({ value: o.value, label: o.label })),\\n            }),\\n          )\\n        ),\\n        React.createElement(Col, null,\\n          React.createElement(Space, { size: 8 },\\n            React.createElement(Button, {\\n              type: 'primary',\\n              icon: React.createElement(PlusOutlined),\\n              onClick: handleAddOpen,\\n            }, 'Thêm mới'),\\n            React.createElement(Tooltip, { title: 'Làm mới dữ liệu' },\\n              React.createElement(Button, {\\n                icon: React.createElement(ReloadOutlined),\\n                onClick: () => fetchData(),\\n              })\\n            ),\\n          )\\n        ),\\n      )\\n    ),\\n    React.createElement(Card, { size: 'small' },\\n      React.createElement(Table, {\\n        columns: columns,\\n        dataSource: paginatedData,\\n        rowKey: 'id',\\n        loading: loading,\\n        pagination: false,\\n        scroll: { x: 1600 },\\n        size: 'middle',\\n      }),\\n      React.createElement('div', {\\n        style: { display: 'flex', justifyContent: 'flex-end', marginTop: 16 },\\n      },\\n        React.createElement(Pagination, {\\n          current: page,\\n          total: filteredData.length,\\n          pageSize: pageSize,\\n          onChange: (p) => setPage(p),\\n          showTotal: (t, range) => range[0] + '-' + range[1] + ' / ' + t + ' bản ghi',\\n          showSizeChanger: false,\\n          size: 'small',\\n        })\\n      ),\\n    ),\\n    React.createElement(Drawer, {\\n      title: 'Chi tiết doanh nghiệp',\\n      open: viewVisible,\\n      onClose: () => { setViewVisible(false); setViewRecord(null); },\\n      width: 680,\\n    },\\n      viewRecord && React.createElement(React.Fragment, null,\\n        React.createElement(Descriptions, {\\n          column: 2,\\n          bordered: true,\\n          size: 'small',\\n          labelStyle: { width: 160, fontWeight: 500 },\\n        },\\n          React.createElement(Descriptions.Item, { label: 'Mã doanh nghiệp' }, viewRecord.ma_doanh_nghiep || '-'),\\n          React.createElement(Descriptions.Item, { label: 'Mã số thuế' }, viewRecord.ma_so_thue || '-'),\\n          React.createElement(Descriptions.Item, { label: 'Tên doanh nghiệp', span: 2 }, viewRecord.ten_doanh_nghiep || '-'),\\n          React.createElement(Descriptions.Item, { label: 'Địa chỉ', span: 2 }, viewRecord.dia_chi || '-'),\\n          React.createElement(Descriptions.Item, { label: 'Người liên hệ' }, viewRecord.nguoi_lien_he || '-'),\\n          React.createElement(Descriptions.Item, { label: 'Điện thoại' }, viewRecord.dien_thoai || '-'),\\n          React.createElement(Descriptions.Item, { label: 'Email' }, viewRecord.email || '-'),\\n          React.createElement(Descriptions.Item, { label: 'Lĩnh vực' }, (() => {\\n            var info = LINH_VUC_MAP[viewRecord.linh_vuc_hoat_dong];\\n            return info ? React.createElement(Tag, { color: info.color }, info.label) : '-';\\n          })()),\\n          React.createElement(Descriptions.Item, { label: 'Trạng thái' }, (() => {\\n            var info = TRANG_THAI_MAP[viewRecord.trang_thai];\\n            return info ? React.createElement(Tag, { color: info.color }, info.text) : '-';\\n          })()),\\n          React.createElement(Descriptions.Item, { label: 'Ngày tạo' },\\n            viewRecord.createdAt ? dayjs(viewRecord.createdAt).format('DD/MM/YYYY HH:mm') : '-'\\n          ),\\n        ),\\n        React.createElement(Divider, null),\\n        React.createElement(Typography.Title, { level: 5 }, 'Danh sách người lao động'),\\n        renderNLDTable(viewRecord.nguoi_lao_dong)\\n      )\\n    ),\\n    React.createElement(Modal, {\\n      title: 'Chỉnh sửa doanh nghiệp',\\n      open: editVisible,\\n      onCancel: () => { setEditVisible(false); editForm.resetFields(); },\\n      onOk: handleEditSubmit,\\n      confirmLoading: submitting,\\n      okText: 'Lưu',\\n      cancelText: 'Hủy',\\n      width: 560,\\n      destroyOnClose: true,\\n    },\\n      React.createElement(Form, { form: editForm, layout: 'vertical', autoComplete: 'off' },\\n        renderFormFields()\\n      )\\n    ),\\n    React.createElement(Modal, {\\n      title: 'Thêm mới doanh nghiệp',\\n      open: addVisible,\\n      onCancel: () => { setAddVisible(false); addForm.resetFields(); },\\n      onOk: handleAddSubmit,\\n    