cwuhduwtyia	cwuhduwtyia	{"parentId":"twfdv1tibxt","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Tài khoản người lao động"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ============================================================\\n// JS Block: Tai khoan nguoi lao dong\\n// Collection: users (filtered by ho_so_nhan_su linked)\\n// ============================================================\\n\\n// --- 1. Top-level data loading ---\\nasync function fetchTaiKhoanNLD() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('users');\\n  res.setAppends(['ho_so_nhan_su', 'roles']);\\n  res.setFilter({ 'ho_so_nhan_su.id': { $ne: null } });\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(1000);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialData = await fetchTaiKhoanNLD();\\n\\n// --- 2. Libs ---\\nconst {\\n  Table, Button, Input, Select, Tag, Space, Card, Row, Col, Modal,\\n  Tooltip, Typography, Statistic, Descriptions, Pagination, Popconfirm,\\n} = ctx.libs.antd;\\n\\nconst {\\n  SearchOutlined, ReloadOutlined, UserOutlined, LockOutlined,\\n  CheckCircleOutlined, StopOutlined, KeyOutlined,\\n  EyeOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst React = ctx.libs.React;\\nconst { useState, useCallback, useMemo } = React;\\nconst dayjs = ctx.libs.dayjs;\\n\\n// --- 3. React Component ---\\nconst TaiKhoanNLDBlock = ({ initData, reloadFn }) => {\\n  const [loading, setLoading] = useState(false);\\n  const [allData, setAllData] = useState(initData);\\n  const [page, setPage] = useState(1);\\n  const [pageSize] = useState(20);\\n  const [searchText, setSearchText] = useState('');\\n\\n  const [viewVisible, setViewVisible] = useState(false);\\n  const [viewRecord, setViewRecord] = useState(null);\\n  const [resetVisible, setResetVisible] = useState(false);\\n  const [resetRecord, setResetRecord] = useState(null);\\n  const [newPassword, setNewPassword] = useState('');\\n  const [submitting, setSubmitting] = useState(false);\\n\\n  const stats = useMemo(() => {\\n    var total = allData.length;\\n    var active = 0;\\n    for (var i = 0; i < allData.length; i++) {\\n      var nld = allData[i].ho_so_nhan_su;\\n      if (nld && nld.trang_thai === 'dang_lam_viec') active++;\\n    }\\n    return { total: total, active: active, inactive: total - active };\\n  }, [allData]);\\n\\n  const filteredData = useMemo(() => {\\n    var rows = allData;\\n    if (searchText && searchText.trim()) {\\n      var s = searchText.trim().toLowerCase();\\n      rows = rows.filter((r) => {\\n        var nld = r.ho_so_nhan_su || {};\\n        return (r.username && r.username.toLowerCase().indexOf(s) >= 0) ||\\n          (r.email && r.email.toLowerCase().indexOf(s) >= 0) ||\\n          (r.nickname && r.nickname.toLowerCase().indexOf(s) >= 0) ||\\n          (r.phone && r.phone.toLowerCase().indexOf(s) >= 0) ||\\n          (nld.ho_ten && nld.ho_ten.toLowerCase().indexOf(s) >= 0) ||\\n          (nld.so_giay_to && nld.so_giay_to.toLowerCase().indexOf(s) >= 0);\\n      });\\n    }\\n    return rows;\\n  }, [allData, searchText]);\\n\\n  const paginatedData = useMemo(() => {\\n    return filteredData.slice((page - 1) * pageSize, page * pageSize);\\n  }, [filteredData, page, pageSize]);\\n\\n  const fetchData = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await reloadFn();\\n      setAllData(newData);\\n    } catch (err) {\\n      ctx.message.error('Không thể tải dữ liệu tài khoản');\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [reloadFn]);\\n\\n  const handleView = (record) => {\\n    setViewRecord(record);\\n    setViewVisible(true);\\n  };\\n\\n  const handleResetPassword = (record) => {\\n    setResetRecord(record);\\n    setNewPassword('');\\n    setResetVisible(true);\\n  };\\n\\n  const handleResetSubmit = async () => {\\n    if (!newPassword || newPassword.length < 6) {\\n      ctx.message.error('Mật khẩu mới phải có ít nhất 6 ký tự');\\n      return;\\n    }\\n    try {\\n      setSubmitting(true);\\n      await ctx.request({\\n        url: 'users:update',\\n        method: 'post',\\n        params: { filterByTk: resetRecord.id },\\n        data: { password: newPassword },\\n      });\\n      ctx.message.success('Reset mật khẩu thành công');\\n      setResetVisible(false);\\n      setResetRecord(null);\\n      setNewPassword('');\\n    } catch (err) {\\n      ctx.message.error('Reset mật khẩu thất bại');\\n    } finally {\\n      setSubmitting(false);\\n    }\\n  };\\n\\n  const columns = [\\n    {\\n      title: 'Họ tên NLĐ',\\n      key: 'ho_ten',\\n      width: 180,\\n      ellipsis: true,\\n      render: (_, record) => {\\n        var nld = record.ho_so_nhan_su || {};\\n        return React.createElement('span', { style: { fontWeight: 500 } }, nld.ho_ten || '-');\\n      },\\n    },\\n    {\\n      title: 'Số CCCD',\\n      key: 'so_giay_to',\\n      width: 140,\\n      render: (_, record) => {\\n        var nld = record.ho_so_nhan_su || {};\\n        return nld.so_giay_to || '-';\\n      },\\n    },\\n    {\\n      title: 'Username',\\n      dataIndex: 'username',\\n      key: 'username',\\n      width: 160,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Email',\\n      dataIndex: 'email',\\n      key: 'email',\\n      width: 220,\\n      ellipsis: true,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Nickname',\\n      dataIndex: 'nickname',\\n      key: 'nickname',\\n      width: 160,\\n      ellipsis: true,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Điện thoại',\\n      dataIndex: 'phone',\\n      key: 'phone',\\n      width: 130,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Vai trò hệ thống',\\n      key: 'roles',\\n      width: 160,\\n      render: (_, record) => {\\n        var roles = record.roles;\\n        if (!roles || !Array.is