uuuyyctceir	uuuyyctceir	{"parentId":"anzm2kk1aau","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Quản lý người lao động"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ============================================================\\n// JS Block: Nguoi Lao Dong (Nguoi dung tab)\\n// Collection: nguoi_lao_dong\\n// ============================================================\\n\\n// --- 1. Top-level data loading (MUST be outside React) ---\\nasync function fetchNguoiLaoDong() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('nguoi_lao_dong');\\n  res.setAppends(['don_vi', 'bac_tho', 'vai_tro']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(1000);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialData = await fetchNguoiLaoDong();\\n\\n// --- 2. Libs ---\\nconst {\\n  Table, Button, Input, Select, Tag, Space, Card, Row, Col, Modal,\\n  Form, DatePicker, Drawer, Popconfirm, Tooltip, Typography, Statistic,\\n  Descriptions, Pagination, Spin, Divider,\\n} = ctx.libs.antd;\\n\\nconst {\\n  SearchOutlined, PlusOutlined, EditOutlined, EyeOutlined,\\n  DeleteOutlined, ReloadOutlined, UserOutlined, TeamOutlined,\\n  PauseCircleOutlined, StopOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst React = ctx.libs.React;\\nconst { useState, useEffect, useCallback, useMemo } = React;\\nconst dayjs = ctx.libs.dayjs;\\n\\n// --- 3. Constants ---\\nconst TRANG_THAI_OPTIONS = [\\n  { value: 'dang_lam_viec', label: 'Đang làm việc', color: 'green', display: 'Đang làm việc' },\\n  { value: 'tam_nghi', label: 'Tạm nghỉ', color: 'orange', display: 'Tạm nghỉ' },\\n  { value: 'da_nghi_viec', label: 'Đã nghỉ việc', color: 'red', display: 'Đã nghỉ việc' },\\n];\\n\\nconst GIOI_TINH_OPTIONS = [\\n  { value: 'nam', label: 'Nam' },\\n  { value: 'nu', label: 'Nữ' },\\n  { value: 'khac', label: 'Khác' },\\n];\\n\\nconst TRANG_THAI_MAP = {\\n  dang_lam_viec: { color: 'green', text: 'Đang làm việc' },\\n  tam_nghi: { color: 'orange', text: 'Tạm nghỉ' },\\n  da_nghi_viec: { color: 'red', text: 'Đã nghỉ việc' },\\n};\\n\\nconst GIOI_TINH_MAP = {\\n  nam: 'Nam',\\n  nu: 'Nữ',\\n  khac: 'Khác',\\n};\\n\\n// --- 4. React Component ---\\nconst NguoiLaoDongBlock = ({ initData, reloadFn }) => {\\n  const [loading, setLoading] = useState(false);\\n  const [allData, setAllData] = useState(initData);\\n  const [page, setPage] = useState(1);\\n  const [pageSize] = useState(20);\\n\\n  // Search & filter state\\n  const [searchText, setSearchText] = useState('');\\n  const [filterTrangThai, setFilterTrangThai] = useState(null);\\n\\n  // Drawer / Modal state\\n  const [viewVisible, setViewVisible] = useState(false);\\n  const [viewRecord, setViewRecord] = useState(null);\\n  const [editVisible, setEditVisible] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [addVisible, setAddVisible] = useState(false);\\n  const [submitting, setSubmitting] = useState(false);\\n\\n  const [editForm] = Form.useForm();\\n  const [addForm] = Form.useForm();\\n\\n  // --- Computed data (client-side filtering/stats) ---\\n  const activeRows = useMemo(() => {\\n    return (allData || []).filter((r) => !r.is_deleted);\\n  }, [allData]);\\n\\n  const stats = useMemo(() => {\\n    var total = 0, dangLamViec = 0, tamNghi = 0, daNghiViec = 0;\\n    for (var i = 0; i < (allData || []).length; i++) {\\n      var r = allData[i];\\n      if (r.is_deleted) continue;\\n      total++;\\n      if (r.trang_thai === 'dang_lam_viec') dangLamViec++;\\n      else if (r.trang_thai === 'tam_nghi') tamNghi++;\\n      else if (r.trang_thai === 'da_nghi_viec') daNghiViec++;\\n    }\\n    return { total: total, dangLamViec: dangLamViec, tamNghi: tamNghi, daNghiViec: daNghiViec };\\n  }, [allData]);\\n\\n  const filteredData = useMemo(() => {\\n    var rows = activeRows;\\n    if (searchText && searchText.trim()) {\\n      var s = searchText.trim().toLowerCase();\\n      rows = rows.filter((r) =>\\n        (r.ho_ten && r.ho_ten.toLowerCase().indexOf(s) >= 0) ||\\n        (r.so_giay_to && r.so_giay_to.toLowerCase().indexOf(s) >= 0) ||\\n        (r.dien_thoai && r.dien_thoai.toLowerCase().indexOf(s) >= 0) ||\\n        (r.email && r.email.toLowerCase().indexOf(s) >= 0)\\n      );\\n    }\\n    if (filterTrangThai) {\\n      rows = rows.filter((r) => r.trang_thai === filterTrangThai);\\n    }\\n    return rows;\\n  }, [activeRows, searchText, filterTrangThai]);\\n\\n  const paginatedData = useMemo(() => {\\n    return filteredData.slice((page - 1) * pageSize, page * pageSize);\\n  }, [filteredData, page, pageSize]);\\n\\n  // --- Fetch data ---\\n  const fetchData = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await reloadFn();\\n      setAllData(newData);\\n    } catch (err) {\\n      ctx.message.error('Không thể tải dữ liệu người lao động');\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [reloadFn]);\\n\\n  // --- Handlers ---\\n  const handleSearch = () => {\\n    setPage(1);\\n  };\\n\\n  const handleFilterChange = (val) => {\\n    setFilterTrangThai(val || null);\\n    setPage(1);\\n  };\\n\\n  const handlePageChange = (newPage) => {\\n    setPage(newPage);\\n  };\\n\\n  const handleRefresh = () => {\\n    fetchData();\\n  };\\n\\n  // --- View ---\\n  const handleView = (record) => {\\n    setViewRecord(record);\\n    setViewVisible(true);\\n  };\\n\\n  // --- Edit ---\\n  const handleEdit = (record) => {\\n    setEditRecord(record);\\n    editForm.setFieldsValue({\\n      ho_ten: record.ho_ten,\\n      so_giay_to: record.so_giay_to,\\n      ngay_sinh: record.ngay_sinh ? dayjs(record.ngay_sinh) : null,\\n      gioi_tinh: record.gioi_tinh,\\n      dien_thoai: record.dien_thoai,\\n      email: record.email,\\n      ngay_vao_lam: record.ngay_vao_lam ? dayjs(record.ngay_vao_lam) : null,\\n      trang_thai: record.trang_thai,\\n    });\\n    setEditVisible(true);\\n  };\\n\\n  const handleEditSubmit = async () => {\\n    try {\\n      const values = await editForm.validateFields();\\n      setSubmitting(true);\\n      await ctx.request({\\n        url: `nguoi_lao_dong:update?filterByTk=${editRecord.id}`,\\n        method: 'post',\\n        data: {\\n          ...values,\\n          ngay_sinh: values.ngay_sinh ? values.ngay_sinh.format('YYYY-MM-DD') : null,\\n          ngay_vao_lam: values.ngay_vao_lam ? values.ngay_vao_lam.format('YYYY-MM-DD') : null,\\n        },\\n      });\\n      ctx.message.success('Cập nhật thành công');\\n      setEditVisible(false);\\n      editForm.resetFields();\\n      handleRefresh();\\n    } catch (err) {\\n      if (err?.errorFields) return;\\n      console.error('Update error:', err);\\n      ctx.message.error('Cập nhật thất bại');\\n    } finally {\\n      setSubmitting(false);\\n    }\\n  };\\n\\n  // --- Add New ---\\n  const handleAddOpen = () => {\\n    addForm.resetFields();\\n    setAddVisible(true);\\n  };\\n\\n  const handleAddSubmit = async () => {\\n    try {\\n      const values = await addForm.validateFields();\\n      setSubmitting(true);\\n      await ctx.request({\\n        url: 'nguoi_lao_dong:create',\\n        method: 'post',\\n        data: {\\n          ...values,\\n          ngay_sinh: values.ngay_sinh ? values.ngay_sinh.format('YYYY-MM-DD') : null,\\n          ngay_vao_lam: values.ngay_vao_lam ? values.ngay_vao_lam.format('YYYY-MM-DD') : null,\\n          is_deleted: false,\\n        },\\n      });\\n      ctx.message.success('Thêm mới thành công');\\n      setAddVisible(false);\\n      addForm.resetFields();\\n      handleRefresh();\\n    } catch (err) {\\n      if (err?.errorFields) return;\\n      console.error('Create error:', err);\\n      ctx.message.error('Thêm mới thất bại');\\n    } finally {\\n      setSubmitting(false);\\n    }\\n  };\\n\\n  // --- Delete (soft) ---\\n  const handleDelete = async (record) => {\\n    try {\\n      await ctx.request({\\n        url: `nguoi_lao_dong:update?filterByTk=${record.id}`,\\n        method: 'post',\\n        data: { is_deleted: true },\\n      });\\n      ctx.message.success('Xóa thành công');\\n      handleRefresh();\\n    } catch (err) {\\n      console.error('Delete error:', err);\\n      ctx.message.error('Xóa thất bại');\\n    }\\n  };\\n\\n  // --- Table columns ---\\n  const columns = [\\n    {\\n      title: 'Họ và tên',\\n      dataIndex: 'ho_ten',\\n      key: 'ho_ten',\\n      width: 180,\\n      ellipsis: true,\\n      render: (text) => React.createElement('span', { style: { fontWeight: 500 } }, text || '-'),\\n    },\\n    {\\n      title: 'Số CCCD/Hộ chiếu',\\n      dataIndex: 'so_giay_to',\\n      key: 'so_giay_to',\\n      width: 150,\\n      ellipsis: true,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Điện thoại',\\n      dataIndex: 'dien_thoai',\\n      key: 'dien_thoai',\\n      width: 130,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Email',\\n      dataIndex: 'email',\\n      key: 'email',\\n      width: 200,\\n      ellipsis: true,\\n      render: (text) => text || '-',\\n    },\\n    {\\n      title: 'Đơn vị',\\n      dataIndex: 'don_vi',\\n      key: 'don_vi',\\n      width: 160,\\n      ellipsis: true,\\n      render: (_, record) => record.don_vi?.ten_don_vi || '-',\\n    },\\n    {\\n      title: 'Bậc thợ',\\n      dataIndex: 'bac_tho',\\n      key: 'bac_tho',\\n      width: 120,\\n      render: (_, record) => record.bac_tho?.ten_bac || '-',\\n    },\\n    {\\n      title: 'Vai trò',\\n      dataIndex: 'vai_tro',\\n      key: 'vai_tro',\\n      width: 180,\\n      render: (_, record) => {\\n        const roles = record.vai_tro;\\n        if (!roles || !Array.isArray(roles) || roles.length === 0) return '-';\\n        return React.createElement(Space, { size: 4, wrap: true },\\n          roles.map((r, i) =>\\n            React.createElement(Tag, { key: r.id || i, color: 'blue' }, r.ten_vai_tro || '-')\\n          )\\n        );\\n      },\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      key: 'trang_thai',\\n      width: 140,\\n      render: (val) => {\\n        const info = TRANG_THAI_MAP[val];\\n        if (!info) return '-';\\n        return React.createElement(Tag, { color: info.color }, info.text);\\n      },\\n    },\\n    {\\n      title: 'Ngày tạo',\\n      dataIndex: 'createdAt',\\n      key: 'createdAt',\\n      width: 160,\\n      render: (val) => val ? dayjs(val).format('DD/MM/YYYY HH:mm') : '-',\\n    },\\n    {\\n      title: 'Thao tác',\\n      key: 'actions',\\n      fixed: 'right',\\n      width: 150,\\n      render: (_, record) =>\\n        React.createElement(Space, { size: 4 },\\n          React.createElement(Tooltip, { title: 'Xem chi tiết' },\\n            React.createElement(Button, {\\n              icon: React.createElement(EyeOutlined),\\n              size: 'small',\\n              onClick: () => handleView(record),\\n            })\\n          ),\\n          React.createElement(Tooltip, { title: 'Chỉnh sửa' },\\n            React.createElement(Button, {\\n              icon: React.createElement(EditOutlined),\\n              size: 'small',\\n              onClick: () => handleEdit(record),\\n            })\\n          ),\\n          React.createElement(Popconfirm, {\\n            title: 'Xác nhận xóa',\\n            description: 'Ban co chac chan muon xoa nguoi lao dong nay?',\\n            onConfirm: () => handleDelete(record),\\n            okText: 'Xóa',\\n            cancelText: 'Hủy',\\n          },\\n            React.createElement(Tooltip, { title: 'Xóa' },\\n              React.createElement(Button, {\\n                icon: React.createElement(DeleteOutlined),\\n                size: 'small',\\n                danger: true,\\n              })\\n            )\\n          ),\\n        ),\\n    },\\n  ];\\n\\n  // --- Form fields helper ---\\n  const renderFormFields = (form) => {\\n    return React.createElement(React.Fragment, null,\\n      React.createElement(Form.Item, {\\n        name: 'ho_ten',\\n        label: 'Họ và tên',\\n        rules: [{ required: true, message: 'Vui lòng nhập họ và tên' }],\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập họ và tên' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'so_giay_to',\\n        label: 'Số CCCD/Hộ chiếu',\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập số CCCD/Hộ chiếu' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'ngay_sinh',\\n        label: 'Ngày sinh',\\n      },\\n        React.createElement(DatePicker, {\\n          style: { width: '100%' },\\n          format: 'DD/MM/YYYY',\\n          placeholder: 'Chọn ngày sinh',\\n        })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'gioi_tinh',\\n        label: 'Giới tính',\\n      },\\n        React.createElement(Select, {\\n          placeholder: 'Chọn giới tính',\\n          allowClear: true,\\n          options: GIOI_TINH_OPTIONS,\\n        })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'dien_thoai',\\n        label: 'Điện thoại',\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập số điện thoại' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'email',\\n        label: 'Email',\\n        rules: [{ type: 'email', message: 'Email không hợp lệ' }],\\n      },\\n        React.createElement(Input, { placeholder: 'Nhập email' })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'ngay_vao_lam',\\n        label: 'Ngày vào làm',\\n      },\\n        React.createElement(DatePicker, {\\n          style: { width: '100%' },\\n          format: 'DD/MM/YYYY',\\n          placeholder: 'Chọn ngày vào làm',\\n        })\\n      ),\\n      React.createElement(Form.Item, {\\n        name: 'trang_thai',\\n        label: 'Trạng thái',\\n        rules: [{ required: true, message: 'Vui lòng chọn trạng thái' }],\\n      },\\n        React.createElement(Select, {\\n          placeholder: 'Chọn trạng thái',\\n          options: TRANG_THAI_OPTIONS.map((o) => ({ value: o.value, label: o.display })),\\n        })\\n      ),\\n    );\\n  };\\n\\n  // --- Render ---\\n  return React.createElement('div', { style: { padding: 0 } },\\n    // Stats cards row\\n    React.createElement(Row, { gutter: [16, 16], style: { marginBottom: 16 } },\\n      React.createElement(Col, { xs: 12, sm: 6 },\\n        React.createElement(Card, { size: 'small', bordered: true },\\n          React.createElement(Statistic, {\\n            title: 'Tổng người lao động',\\n            value: stats.total,\\n            prefix: React.createElement(TeamOutlined),\\n            valueStyle: { color: '#1890ff' },\\n          })\\n        )\\n      ),\\n      React.createElement(Col, { xs: 12, sm: 6 },\\n        React.createElement(Card, { size: 'small', bordered: true },\\n          React.createElement(Statistic, {\\n            title: 'Đang làm việc',\\n            value: stats.dangLamViec,\\n            prefix: React.createElement(UserOutlined),\\n            valueStyle: { color: '#52c41a' },\\n          })\\n        )\\n      ),\\n      React.createElement(Col, { xs: 12, sm: 6 },\\n        React.createElement(Card, { size: 'small', bordered: true },\\n          React.createElement(Statistic, {\\n            title: 'Tạm nghỉ',\\n            value: stats.tamNghi,\\n            prefix: React.createElement(PauseCircleOutlined),\\n            valueStyle: { color: '#faad14' },\\n          })\\n        )\\n      ),\\n      React.createElement(Col, { xs: 12, sm: 6 },\\n        React.createElement(Card, { size: 'small', bordered: true },\\n          React.createElement(Statistic, {\\n            title: 'Đã nghỉ việc',\\n            value: stats.daNghiViec,\\n            prefix: React.createElement(StopOutlined),\\n            valueStyle: { color: '#ff4d4f' },\\n          })\\n        )\\n      ),\\n    ),\\n\\n    // Search bar\\n    React.createElement(Card, { size: 'small', style: { marginBottom: 16 } },\\n      React.createElement(Row, { gutter: [12, 12], align: 'middle', justify: 'space-between' },\\n        React.createElement(Col, { flex: 'auto' },\\n          React.createElement(Space, { wrap: true, size: 12 },\\n            React.createElement(Input, {\\n              placeholder: 'Tìm kiếm theo họ tên, CCCD, điện thoại, email...',\\n              prefix: React.createElement(SearchOutlined),\\n              value: searchText,\\n              onChange: (e) => setSearchText(e.target.value),\\n              onPressEnter: handleSearch,\\n              style: { width: 360 },\\n              allowClear: true,\\n            }),\\n            React.createElement(Select, {\\n              placeholder: 'Trạng thái',\\n              value: filterTrangThai,\\n              onChange: handleFilterChange,\\n              allowClear: true,\\n              style: { width: 180 },\\n              options: TRANG_THAI_OPTIONS.map((o) => ({ value: o.value, label: o.display })),\\n            }),\\n            React.createElement(Button, {\\n              icon: React.createElement(SearchOutlined),\\n              onClick: handleSearch,\\n            }, 'Tìm kiếm'),\\n          )\\n        ),\\n        React.createElement(Col, null,\\n          React.createElement(Space, { size: 8 },\\n            React.createElement(Button, {\\n              type: 'primary',\\n              icon: React.createElement(PlusOutlined),\\n              onClick: handleAddOpen,\\n            }, 'Thêm mới'),\\n            React.createElement(Tooltip, { title: 'Làm mới dữ liệu' },\\n              React.createElement(Button, {\\n                icon: React.createElement(ReloadOutlined),\\n                onClick: handleRefresh,\\n              })\\n            ),\\n          )\\n        ),\\n      )\\n    ),\\n\\n    // Data table\\n    React.createElement(Card, { size: 'small' },\\n      React.createElement(Table, {\\n        columns: columns,\\n        dataSource: paginatedData,\\n        rowKey: 'id',\\n        loading: loading,\\n        pagination: false,\\n        scroll: { x: 1500 },\\n        size: 'middle',\\n      }),\\n      React.createElement('div', {\\n        style: { display: 'flex', justifyContent: 'flex-end', marginTop: 16 },\\n      },\\n        React.createElement(Pagination, {\\n          current: page,\\n          total: filteredData.length,\\n          pageSize: pageSize,\\n          onChange: handlePageChange,\\n          showTotal: (t, range) => `${range[0]}-${range[1]} / ${t} bản ghi`,\\n          showSizeChanger: false,\\n          size: 'small',\\n        })\\n      ),\\n    ),\\n\\n    // View Drawer\\n    React.createElement(Drawer, {\\n      title: 'Chi tiết người lao động',\\n      open: viewVisible,\\n      onClose: () => { setViewVisible(false); setViewRecord(null); },\\n      width: 560,\\n    },\\n      viewRecord && React.createElement(Descriptions, {\\n        column: 1,\\n        bordered: true,\\n        size: 'small',\\n        labelStyle: { width: 180, fontWeight: 500 },\\n      },\\n        React.createElement(Descriptions.Item, { label: 'Họ và tên' },\\n          viewRecord.ho_ten || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Mã người lao động' },\\n          viewRecord.ma_nguoi_lao_dong || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Số CCCD/Hộ chiếu' },\\n          viewRecord.so_giay_to || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Ngày sinh' },\\n          viewRecord.ngay_sinh ? dayjs(viewRecord.ngay_sinh).format('DD/MM/YYYY') : '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Giới tính' },\\n          GIOI_TINH_MAP[viewRecord.gioi_tinh] || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Điện thoại' },\\n          viewRecord.dien_thoai || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Email' },\\n          viewRecord.email || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Ngày vào làm' },\\n          viewRecord.ngay_vao_lam ? dayjs(viewRecord.ngay_vao_lam).format('DD/MM/YYYY') : '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Đơn vị' },\\n          viewRecord.don_vi?.ten_don_vi || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Bậc thợ' },\\n          viewRecord.bac_tho?.ten_bac || '-'\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Vai trò' },\\n          (() => {\\n            const roles = viewRecord.vai_tro;\\n            if (!roles || !Array.isArray(roles) || roles.length === 0) return '-';\\n            return React.createElement(Space, { size: 4, wrap: true },\\n              roles.map((r, i) =>\\n                React.createElement(Tag, { key: r.id || i, color: 'blue' }, r.ten_vai_tro || '-')\\n              )\\n            );\\n          })()\\n        ),\\n        React.createElement(Descriptions.Item, { label: 'Trạng thái' },\\n          (() => {\\n            const info = TRANG_THAI_MAP[viewRecord.trang_thai];\\n            if (!info) return '-';\\n            return React.createElement(Tag, { color: info.color }, info.text);\\n          })()\\n        ),\\n      )\\n    ),\\n\\n    // Edit Modal\\n    React.createElement(Modal, {\\n      title: 'Chỉnh sửa người lao động',\\n      open: editVisible,\\n      onCancel: () => { setEditVisible(false); editForm.resetFields(); },\\n      onOk: handleEditSubmit,\\n      confirmLoading: submitting,\\n      okText: 'Lưu',\\n      cancelText: 'Hủy',\\n      width: 520,\\n      destroyOnClose: true,\\n    },\\n      React.createElement(Form, {\\n        form: editForm,\\n        layout: 'vertical',\\n        autoComplete: 'off',\\n      },\\n        renderFormFields(editForm)\\n      )\\n    ),\\n\\n    // Add New Modal\\n    React.createElement(Modal, {\\n      title: 'Thêm mới người lao động',\\n      open: addVisible,\\n      onCancel: () => { setAddVisible(false); addForm.resetFields(); },\\n      onOk: handleAddSubmit,\\n      confirmLoading: submitting,\\n      okText: 'Thêm',\\n      cancelText: 'Hủy',\\n      width: 520,\\n      destroyOnClose: true,\\n    },\\n      React.createElement(Form, {\\n        form: addForm,\\n        layout: 'vertical',\\n        autoComplete: 'off',\\n        initialValues: { trang_thai: 'dang_lam_viec' },\\n      },\\n        renderFormFields(addForm)\\n      )\\n    ),\\n  );\\n};\\n\\n// --- 5. Render ---\\nctx.render(React.createElement(NguoiLaoDongBlock, { initData: initialData, reloadFn: fetchNguoiLaoDong }));\\n"}},"__flowSurfaceMeta":{"declaredKey":"nguoiDungJsV4"}}}
umb7aozjvjq	umb7aozjvjq	{"parentId":"c8u6covdv81","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v8","code":"// ============================================================\\n// JS Block: Phê duyệt nâng bậc (V7)\\n// Logic: dùng dieu_kien_len_bac (de_thi_ids + khoa_hoc_ids) để xét điều kiện\\n// ============================================================\\n\\nconst {\\n  Table, Card, Button, Input, Select, Tag, Space, Row, Col,\\n  Modal, Form, Popconfirm, Tooltip, Statistic, Divider,\\n  Typography, Spin, Pagination, Descriptions, Alert, Empty,\\n  InputNumber, DatePicker, Timeline, Result,\\n} = ctx.libs.antd;\\n\\nconst {\\n  SearchOutlined, ReloadOutlined, EyeOutlined,\\n  CheckCircleOutlined, CloseCircleOutlined,\\n  ArrowLeftOutlined, SafetyCertificateOutlined,\\n  ExclamationCircleOutlined, ClockCircleOutlined,\\n  TrophyOutlined, FileTextOutlined,\\n  AuditOutlined, TeamOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst { useState, useCallback, useMemo } = ctx.libs.React;\\nconst { Text, Title } = Typography;\\n\\n// -- Enum maps ------------------------------------------------\\nvar TRANG_THAI_DUYET = {\\n  cho_duyet: { label: 'Chờ phê duyệt', color: 'gold' },\\n  da_duyet: { label: 'Đã phê duyệt', color: 'green' },\\n  tu_choi: { label: 'Từ chối', color: 'red' },\\n};\\n\\n// -- Data loading ---------------------------------------------\\nasync function fetchBacThoList() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('bac_tho');\\n  res.setSort(['thu_tu']);\\n  res.setPageSize(50);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\n\\nasync function fetchThiSinhDat() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('ky_thi_thi_sinh');\\n  res.setAppends([\\n    'nguoi_lao_dong', 'nguoi_lao_dong.don_vi',\\n    'nguoi_lao_dong.nganh_nghe', 'nguoi_lao_dong.bac_tho',\\n    'ky_thi',\\n  ]);\\n  res.setFilter({ ket_qua: { $eq: 'dat' } });\\n  res.setSort(['-id']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\n\\nasync function fetchLichSuNangBac() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('lich_su_nang_bac');\\n  res.setAppends(['nguoi_lao_dong', 'bac_cu', 'bac_moi']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\n\\nasync function fetchHocVienLop() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('hoc_vien_lop');\\n  res.setAppends(['lop_hoc']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\n\\nvar initialBacTho = await fetchBacThoList();\\nvar initialDat = await fetchThiSinhDat();\\nvar initialLichSu = await fetchLichSuNangBac();\\nvar initialHocVien = await fetchHocVienLop();\\n\\n// -- Helpers --------------------------------------------------\\nfunction formatDate(d) {\\n  if (!d) return '—';\\n  var dt = new Date(d);\\n  var dd = String(dt.getDate()).padStart(2, '0');\\n  var mm = String(dt.getMonth() + 1).padStart(2, '0');\\n  return dd + '/' + mm + '/' + dt.getFullYear();\\n}\\n\\nfunction buildBacThoMap(list) {\\n  var map = {};\\n  list.forEach(function(b) { map[b.id] = b; });\\n  return map;\\n}\\n\\nfunction getBacLabel(bacId, bacMap) {\\n  if (!bacId && bacId !== 0) return '—';\\n  var b = bacMap[bacId];\\n  return b ? b.ten_bac : ('Bậc ' + bacId);\\n}\\n\\nfunction getNextBacId(currentBacId, bacThoList) {\\n  var mainLevels = bacThoList.filter(function(b) {\\n    return b.thu_tu >= 1 && b.thu_tu <= 7;\\n  }).sort(function(a, b) { return a.thu_tu - b.thu_tu; });\\n\\n  if (!currentBacId) return mainLevels.length > 0 ? mainLevels[0].id : null;\\n\\n  var cur = bacThoList.find(function(b) { return b.id === currentBacId; });\\n  if (!cur) return mainLevels.length > 0 ? mainLevels[0].id : null;\\n\\n  if (cur.thu_tu === 0) return mainLevels.length > 0 ? mainLevels[0].id : null;\\n  if (cur.thu_tu >= 100) return null;\\n\\n  var next = mainLevels.find(function(b) { return b.thu_tu > cur.thu_tu; });\\n  return next ? next.id : null;\\n}\\n\\nfunction parseDieuKien(bacThoList) {\\n  var map = {};\\n  bacThoList.forEach(function(b) {\\n    if (b.dieu_kien_len_bac) {\\n      try {\\n        map[b.id] = JSON.parse(b.dieu_kien_len_bac);\\n      } catch (e) {\\n        map[b.id] = null;\\n      }\\n    }\\n  });\\n  return map;\\n}\\n\\n// ============================================================\\n// B1: Danh sách chờ phê duyệt\\n// ============================================================\\nfunction B1_DanhSachPheDuyet({ datList, lichSuList, bacThoList, hocVienList, onNavigate, reloadAll }) {\\n  const [loading, setLoading] = useState(false);\\n  const [searchText, setSearchText] = useState('');\\n  const [page, setPage] = useState(1);\\n  var pageSize = 20;\\n\\n  var bacThoMap = useMemo(function() { return buildBacThoMap(bacThoList); }, [bacThoList]);\\n  var dieuKienMap = useMemo(function() { return parseDieuKien(bacThoList); }, [bacThoList]);\\n\\n  var processedData = useMemo(function() {\\n    // Lookup for already-approved promotions\\n    var approvedKeys = {};\\n    lichSuList.forEach(function(ls) {\\n      var nldId = ls.nguoiLaoDongId;\\n      var moiId = ls.bacMoiId || (ls.bac_moi && ls.bac_moi.id);\\n      if (nldId && moiId) approvedKeys[nldId + '_' + moiId] = true;\\n    });\\n\\n    // Group thi_sinh by NLD, collect all passed de_thi_ids\\n    var nldGroups = {};\\n    datList.forEach(function(ts) {\\n      var nldId = ts.nguoi_lao_dong_id;\\n      if (!nldId) return;\\n      if (!nldGroups[nldId]) {\\n        nldGroups[nldId] = { records: [], passedDeThiIds: {} };\\n      }\\n      nldGroups[nldId].records.push(ts);\\n      var kyThi = ts.ky_thi || {};\\n      var deThiId = kyThi.de_thi_id;\\n      if (deThiId) {\\n        nldGroups[nldId].passedDeThiIds[deThiId] = true;\\n      }\\n    });\\n\\n    // Group hocVienList by NLD → completed khoaHuanLuyenIds\\n    var nldKhoaHoc = {};\\n    hocVienList.forEach(function(hv) {\\n      var nldId = hv.nguoiLaoDongId;\\n      if (!nldId) return;\\n      if (!nldKhoaHoc[nldId]) nldKhoaHoc[nldId] = {};\\n      var lopHoc = hv.lop_hoc || {};\\n      var khlId = lopHoc.khoaHuanLuyenId;\\n      if (khlId && (hv.ket_qua === 'dat' || hv.trang_thai === 'hoan_thanh')) {\\n        nldKhoaHoc[nldId][khlId] = true;\\n      }\\n    });\\n\\n    var result = [];\\n    var nldIds = Object.keys(nldGroups);\\n    for (var idx = 0; idx < nldIds.length; idx++) {\\n      var nldId = nldIds[idx];\\n      var group = nldGroups[nldId];\\n      var records = group.records.sort(function(a, b) { return b.id - a.id; });\\n      var latest = records[0];\\n      var nld = latest.nguoi_lao_dong || {};\\n\\n      var currentBacId = nld.bacThoId;\\n      var nextBacId = getNextBacId(currentBacId, bacThoList);\\n      if (!nextBacId) continue;\\n\\n      // Check dieu_kien_len_bac for next bac\\n      var conditions = dieuKienMap[nextBacId];\\n      if (!conditions) continue;\\n\\n      var requiredDeThi = conditions.de_thi_ids || [];\\n      var requiredKhoaHoc = conditions.khoa_hoc_ids || [];\\n      if (requiredDeThi.length === 0 && requiredKhoaHoc.length === 0) continue;\\n\\n      // Check ALL required de_thi are passed\\n      var eligible = true;\\n      for (var i = 0; i < requiredDeThi.length; i++) {\\n        if (!group.passedDeThiIds[requiredDeThi[i]]) {\\n          eligible = false;\\n          break;\\n        }\\n      }\\n      if (!eligible) continue;\\n\\n      // Check ALL required khoa_hoc are completed\\n      var completedKH = nldKhoaHoc[nldId] || {};\\n      for (var j = 0; j < requiredKhoaHoc.length; j++) {\\n        if (!completedKH[requiredKhoaHoc[j]]) {\\n          eligible = false;\\n          break;\\n        }\\n      }\\n      if (!eligible) continue;\\n\\n      var isApproved = approvedKeys[nldId + '_' + nextBacId] || false;\\n      var kyThi = latest.ky_thi || {};\\n\\n      result.push({\\n        id: latest.id,\\n        nguoi_lao_dong_id: parseInt(nldId),\\n        ho_ten: nld.ho_ten || '—',\\n        so_giay_to: nld.so_giay_to || '—',\\n        don_vi: (nld.don_vi || {}).ten_don_vi || '—',\\n        nganh_nghe: (nld.nganh_nghe || {}).ten_nganh_nghe || '—',\\n        bac_hien_tai_id: currentBacId,\\n        bac_de_xuat_id: nextBacId,\\n        ten_ky_thi: kyThi.ten_ky_thi || '—',\\n        diem: latest.diem,\\n        ket_qua: latest.ket_qua,\\n        trang_thai_duyet: isApproved ? 'da_duyet' : 'cho_duyet',\\n        thoi_gian_cham: latest.thoi_gian_cham,\\n        ma_luot_thi: latest.ma_luot_thi,\\n        raw: latest,\\n        nld: nld,\\n      });\\n    }\\n\\n    return result;\\n  }, [datList, lichSuList, bacThoList, hocVienList, dieuKienMap]);\\n\\n  var stats = useMemo(function() {\\n    var waiting = processedData.filter(function(d) { return d.trang_thai_duyet === 'cho_duyet'; }).length;\\n    var approved = processedData.filter(function(d) { return d.trang_thai_duyet === 'da_duyet'; }).length;\\n    return { waiting: waiting, approved: approved, total: processedData.length };\\n  }, [processedData]);\\n\\n  var filteredData = useMemo(function() {\\n    if (!searchText) return processedData;\\n    var lower = searchText.toLowerCase();\\n    return processedData.filter(function(d) {\\n      return d.ho_ten.toLowerCase().indexOf(lower) !== -1 ||\\n             d.so_giay_to.toLowerCase().indexOf(lower) !== -1;\\n    });\\n  }, [processedData, searchText]);\\n\\n  var pagedData = filteredData.slice((page - 1) * pageSize, page * pageSize);\\n\\n  var columns = [\\n    {\\n      title: 'STT', width: 55, align: 'center',\\n      render: function(_, __, i) { return (page - 1) * pageSize + i + 1; },\\n    },\\n    {\\n      title: 'Họ tên', dataIndex: 'ho_ten', width: 170, ellipsis: true,\\n      render: function(v, r) {\\n        return <a onClick={function() { onNavigate('detail', r); }}>{v}</a>;\\n      },\\n    },\\n    { title: 'Số CCCD', dataIndex: 'so_giay_to', width: 130 },\\n    { title: 'Đơn vị', dataIndex: 'don_vi', width: 140, ellipsis: true },\\n    {\\n      title: 'Bậc hiện tại', dataIndex: 'bac_hien_tai_id', width: 150, align: 'center',\\n      render: function(v) { return getBacLabel(v, bacThoMap); },\\n    },\\n    {\\n      title: 'Bậc đề xuất', dataIndex: 'bac_de_xuat_id', width: 150, align: 'center',\\n      render: function(v) {\\n        if (!v) return <Text type=\\"secondary\\">Bậc cao nhất</Text>;\\n        return <Text strong style={{ color: '#1890ff' }}>{getBacLabel(v, bacThoMap)}</Text>;\\n      },\\n    },\\n    {\\n      title: 'Kỳ thi', dataIndex: 'ten_ky_thi', width: 150, ellipsis: true,\\n    },\\n    {\\n      title: 'Điểm', dataIndex: 'diem', width: 65, align: 'center',\\n      render: function(v) {\\n        return <Text strong style={{ color: '#52c41a' }}>{v}</Text>;\\n      },\\n    },\\n    {\\n      title: 'Trạng thái', dataIndex: 'trang_thai_duyet', width: 130,\\n      render: function(v) {\\n        var m = TRANG_THAI_DUYET[v] || { label: v, color: 'default' };\\n        return <Tag color={m.color}>{m.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Thao tác', width: 120, fixed: 'right',\\n      render: function(_, r) {\\n        return (\\n          <Space size={4}>\\n            <Tooltip title=\\"Xem hồ sơ\\">\\n              <Button icon={<EyeOutlined />}\\n                onClick={function() { onNavigate('detail', r); }} />\\n            </Tooltip>\\n            {r.trang_thai_duyet === 'cho_duyet' && r.bac_de_xuat_id && (\\n              <Tooltip title=\\"Phê duyệt\\">\\n                <Button icon={<CheckCircleOutlined />}\\n                  onClick={function() { onNavigate('confirm', r); }} />\\n              </Tooltip>\\n            )}\\n          </Space>\\n        );\\n      },\\n    },\\n  ];\\n\\n  async function handleReload() {\\n    setLoading(true);\\n    await reloadAll();\\n    setLoading(false);\\n  }\\n\\n  async function handleApproveAll() {\\n    var pending = processedData.filter(function(d) {\\n      return d.trang_thai_duyet === 'cho_duyet' && d.bac_de_xuat_id;\\n    });\\n    if (pending.length === 0) {\\n      ctx.message.info('Không có hồ sơ nào cần phê duyệt');\\n      return;\\n    }\\n    setLoading(true);\\n    var successCount = 0;\\n    var errorCount = 0;\\n    var errorMessages = [];\\n    for (var i = 0; i < pending.length; i++) {\\n      var r = pending[i];\\n      try {\\n        var lsRes = ctx.makeResource('MultiRecordResource');\\n        lsRes.setResourceName('lich_su_nang_bac');\\n        await lsRes.create({\\n          nguoiLaoDongId: r.nguoi_lao_dong_id,\\n          bacCuId: r.bac_hien_tai_id,\\n          bacMoiId: r.bac_de_xuat_id,\\n          ly_do: 'Phê duyệt hàng loạt — Điểm: ' + r.diem + ' — ' + r.ten_ky_thi,\\n          ma_luot_thi: r.ma_luot_thi || undefined,\\n          thoi_gian: new Date().toISOString(),\\n        }, { refresh: false });\\n\\n        var nldRes = ctx.makeResource('MultiRecordResource');\\n        nldRes.setResourceName('nguoi_lao_dong');\\n        await nldRes.update(r.nguoi_lao_dong_id, { bacThoId: r.bac_de_xuat_id });\\n        successCount++;\\n      } catch (e) {\\n        errorCount++;\\n        errorMessages.push(r.ho_ten + ': ' + (e.message || 'Lỗi không xác định'));\\n      }\\n    }\\n    await reloadAll();\\n    setLoading(false);\\n    if (errorCount === 0) {\\n      ctx.message.success('Đã phê duyệt toàn bộ ' + successCount + ' hồ sơ');\\n    } else if (successCount === 0) {\\n      ctx.message.error('Không thể phê duyệt. Lỗi: ' + errorMessages.join('; '));\\n    } else {\\n      ctx.message.warning('Thành công: ' + successCount + ', Lỗi: ' + errorCount + '. ' + errorMessages.join('; '));\\n    }\\n  }\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>\\n        <Col xs={12} sm={8}>\\n          <Card bordered>\\n            <Statistic title=\\"Chờ phê duyệt\\" value={stats.waiting}\\n              valueStyle={{ color: '#faad14' }}\\n              prefix={<ClockCircleOutlined />} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={8}>\\n          <Card bordered>\\n            <Statistic title=\\"Đã phê duyệt\\" value={stats.approved}\\n              valueStyle={{ color: '#52c41a' }}\\n              prefix={<CheckCircleOutlined />} />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={8}>\\n          <Card bordered>\\n            <Statistic title=\\"Đủ điều kiện\\" value={stats.total}\\n              prefix={<TeamOutlined />} />\\n          </Card>\\n        </Col>\\n      </Row>\\n\\n      {stats.total === 0 && (\\n        <Alert\\n          message=\\"Không có NLĐ nào đủ điều kiện nâng bậc\\"\\n          description=\\"Danh sách này chỉ hiển thị NLĐ đã đỗ đề thi và hoàn thành khóa học theo yêu cầu của bậc tiếp theo (dieu_kien_len_bac). Kiểm tra: bậc tiếp theo có thiết lập điều kiện chưa? NLĐ đã đỗ đúng đề thi chưa?\\"\\n          type=\\"info\\" showIcon style={{ marginBottom: 16 }} />\\n      )}\\n\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Row gutter={16} align=\\"middle\\" justify=\\"space-between\\">\\n          <Col flex=\\"auto\\">\\n            <Input placeholder=\\"Tìm theo họ tên hoặc CCCD\\"\\n              prefix={<SearchOutlined />} allowClear style={{ width: 300 }}\\n              value={searchText}\\n              onChange={function(e) { setSearchText(e.target.value); setPage(1); }} />\\n          </Col>\\n          <Col>\\n            <Space>\\n              {stats.waiting > 0 && (\\n                <Popconfirm\\n                  title={'Phê duyệt toàn bộ ' + stats.waiting + ' hồ sơ?'}\\n                  description=\\"Tất cả NLĐ chờ phê duyệt sẽ được nâng bậc và ghi lịch sử.\\"\\n                  onConfirm={handleApproveAll}\\n                  okText=\\"Xác nhận\\" cancelText=\\"Hủy\\">\\n                  <Button type=\\"primary\\" icon={<CheckCircleOutlined />}>\\n                    Phê duyệt toàn bộ ({stats.waiting})\\n                  </Button>\\n                </Popconfirm>\\n              )}\\n              <Tooltip title=\\"Làm mới\\">\\n                <Button icon={<ReloadOutlined />} onClick={handleReload} />\\n              </Tooltip>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Card bordered>\\n        <Table rowKey=\\"id\\" columns={columns} dataSource={pagedData}\\n          pagination={false} scroll={{ x: 1300 }} size=\\"middle\\" />\\n        {filteredData.length > pageSize && (\\n          <div style={{ textAlign: 'right', marginTop: 16 }}>\\n            <Pagination current={page} total={filteredData.length}\\n              pageSize={pageSize} showSizeChanger={false}\\n              showTotal={function(t) { return 'Tổng: ' + t; }}\\n              onChange={function(p) { setPage(p); }} />\\n          </div>\\n        )}\\n      </Card>\\n    </Spin>\\n  );\\n}\\n\\n// ============================================================\\n// B2: Chi tiết hồ sơ nâng bậc\\n// ============================================================\\nfunction B2_ChiTietHoSo({ record, lichSuList, bacThoMap, onNavigate, onBack }) {\\n  var nld = record.nld || {};\\n  var history = lichSuList.filter(function(ls) {\\n    return ls.nguoiLaoDongId === record.nguoi_lao_dong_id;\\n  });\\n\\n  return (\\n    <div>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại danh sách\\n      </Button>\\n\\n      <Card bordered style={{ marginBottom: 16 }} title=\\"Thông tin người lao động\\">\\n        <Descriptions column={{ xs: 1, sm: 2, md: 3 }} size=\\"small\\" bordered>\\n          <Descriptions.Item label=\\"Họ tên\\">{nld.ho_ten || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Số CCCD/Hộ chiếu\\">{nld.so_giay_to || '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngày sinh\\">{formatDate(nld.ngay_sinh)}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Giới tính\\">{nld.gioi_tinh === 'nam' ? 'Nam' : nld.gioi_tinh === 'nu' ? 'Nữ' : '—'}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Đơn vị\\">{record.don_vi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngành nghề\\">{record.nganh_nghe}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc thợ hiện tại\\">\\n            <Tag color=\\"blue\\">{getBacLabel(record.bac_hien_tai_id, bacThoMap)}</Tag>\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc đề xuất nâng\\">\\n            <Tag color=\\"green\\">{record.bac_de_xuat_id ? getBacLabel(record.bac_de_xuat_id, bacThoMap) : 'Bậc cao nhất'}</Tag>\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Điểm thi\\">\\n            <Text strong style={{ color: '#52c41a', fontSize: 16 }}>{record.diem}</Text>\\n          </Descriptions.Item>\\n        </Descriptions>\\n      </Card>\\n\\n      <Card bordered style={{ marginBottom: 16 }} title=\\"Lịch sử nâng bậc\\">\\n        {history.length === 0 ? (\\n          <Empty description=\\"Chưa có lịch sử nâng bậc\\" />\\n        ) : (\\n          <Timeline mode=\\"left\\">\\n            {history.map(function(h, i) {\\n              var bacCu = h.bac_cu || {};\\n              var bacMoi = h.bac_moi || {};\\n              return (\\n                <Timeline.Item key={i}\\n                  color={(bacMoi.thu_tu || 0) > (bacCu.thu_tu || 0) ? 'green' : 'blue'}\\n                  label={formatDate(h.thoi_gian || h.createdAt)}>\\n                  <Text strong>{bacCu.ten_bac || '—'} → {bacMoi.ten_bac || '—'}</Text>\\n                  <br />\\n                  <Text type=\\"secondary\\">{h.ly_do || 'Nâng bậc theo kết quả thi'}</Text>\\n                </Timeline.Item>\\n              );\\n            })}\\n          </Timeline>\\n        )}\\n      </Card>\\n\\n      <Card bordered style={{ marginBottom: 16 }} title=\\"Kết quả kỳ thi\\">\\n        <Descriptions column={{ xs: 1, sm: 2 }} size=\\"small\\" bordered>\\n          <Descriptions.Item label=\\"Kỳ thi\\">{record.ten_ky_thi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Điểm\\">{record.diem}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Kết quả\\">\\n            <Tag color=\\"green\\">Đạt</Tag>\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Thời gian chấm\\">{formatDate(record.thoi_gian_cham)}</Descriptions.Item>\\n        </Descriptions>\\n      </Card>\\n\\n      {record.trang_thai_duyet === 'cho_duyet' && record.bac_de_xuat_id && (\\n        <Card bordered>\\n          <Space>\\n            <Button type=\\"primary\\" icon={<CheckCircleOutlined />} size=\\"large\\"\\n              onClick={function() { onNavigate('confirm', record); }}>\\n              Phê duyệt nâng bậc\\n            </Button>\\n            <Button danger icon={<CloseCircleOutlined />} size=\\"large\\"\\n              onClick={onBack}>\\n              Từ chối\\n            </Button>\\n          </Space>\\n        </Card>\\n      )}\\n\\n      {record.trang_thai_duyet === 'da_duyet' && (\\n        <Alert message=\\"Hồ sơ này đã được phê duyệt nâng bậc\\"\\n          type=\\"success\\" showIcon style={{ marginTop: 16 }} />\\n      )}\\n    </div>\\n  );\\n}\\n\\n// ============================================================\\n// B3: Xác nhận nâng bậc\\n// ============================================================\\nfunction B3_XacNhanNangBac({ record, bacThoMap, onBack, reloadAll }) {\\n  const [loading, setLoading] = useState(false);\\n  const [confirmed, setConfirmed] = useState(false);\\n\\n  var bacHienTai = getBacLabel(record.bac_hien_tai_id, bacThoMap);\\n  var bacDeXuat = getBacLabel(record.bac_de_xuat_id, bacThoMap);\\n\\n  async function handleConfirm() {\\n    try {\\n      setLoading(true);\\n      var lsRes = ctx.makeResource('MultiRecordResource');\\n      lsRes.setResourceName('lich_su_nang_bac');\\n      await lsRes.create({\\n        nguoiLaoDongId: record.nguoi_lao_dong_id,\\n        bacCuId: record.bac_hien_tai_id,\\n        bacMoiId: record.bac_de_xuat_id,\\n        ly_do: 'Nâng bậc theo kết quả thi — Điểm: ' + record.diem + ' — ' + record.ten_ky_thi,\\n        ma_luot_thi: record.ma_luot_thi || undefined,\\n        thoi_gian: new Date().toISOString(),\\n      }, { refresh: false });\\n\\n      var nldRes = ctx.makeResource('MultiRecordResource');\\n      nldRes.setResourceName('nguoi_lao_dong');\\n      await nldRes.update(record.nguoi_lao_dong_id, { bacThoId: record.bac_de_xuat_id });\\n\\n      setConfirmed(true);\\n      ctx.message.success('Đã phê duyệt nâng bậc thành công');\\n      await reloadAll();\\n    } catch (e) {\\n      ctx.message.error('Lỗi phê duyệt: ' + (e.message || 'Không thể ghi lịch sử nâng bậc. Kiểm tra lại workflow chống trùng.'));\\n    } finally {\\n      setLoading(false);\\n    }\\n  }\\n\\n  if (confirmed) {\\n    return (\\n      <Result status=\\"success\\"\\n        title=\\"Đã phê duyệt nâng bậc thành công\\"\\n        subTitle={record.ho_ten + ': ' + bacHienTai + ' → ' + bacDeXuat}\\n        extra={[\\n          <Button type=\\"primary\\" key=\\"back\\" onClick={onBack}>\\n            Quay lại danh sách\\n          </Button>,\\n        ]} />\\n    );\\n  }\\n\\n  return (\\n    <Spin spinning={loading}>\\n      <Button type=\\"link\\" icon={<ArrowLeftOutlined />}\\n        onClick={onBack} style={{ marginBottom: 8, padding: 0 }}>\\n        Quay lại\\n      </Button>\\n\\n      <Card bordered title=\\"Xác nhận phê duyệt nâng bậc\\" style={{ marginBottom: 16 }}>\\n        <Alert\\n          message=\\"Vui lòng kiểm tra thông tin trước khi xác nhận\\"\\n          description=\\"Sau khi phê duyệt, bậc thợ của người lao động sẽ được cập nhật và ghi vào lịch sử.\\"\\n          type=\\"warning\\" showIcon style={{ marginBottom: 16 }} />\\n\\n        <Descriptions column={{ xs: 1, sm: 2 }} size=\\"small\\" bordered>\\n          <Descriptions.Item label=\\"Họ tên\\">\\n            <Text strong>{record.ho_ten}</Text>\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Số CCCD\\">{record.so_giay_to}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Đơn vị\\">{record.don_vi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Ngành nghề\\">{record.nganh_nghe}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc hiện tại\\">\\n            <Tag color=\\"blue\\">{bacHienTai}</Tag>\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Bậc nâng lên\\">\\n            <Tag color=\\"green\\">{bacDeXuat}</Tag>\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Kỳ thi\\">{record.ten_ky_thi}</Descriptions.Item>\\n          <Descriptions.Item label=\\"Điểm thi\\">\\n            <Text strong style={{ color: '#52c41a' }}>{record.diem}</Text>\\n          </Descriptions.Item>\\n          <Descriptions.Item label=\\"Kết quả\\">\\n            <Tag color=\\"green\\">Đạt</Tag>\\n          </Descriptions.Item>\\n        </Descriptions>\\n\\n        <Divider />\\n\\n        <Space>\\n          <Popconfirm\\n            title=\\"Xác nhận phê duyệt nâng bậc?\\"\\n            description={'Nâng bậc cho ' + record.ho_ten + ': ' + bacHienTai + ' → ' + bacDeXuat}\\n            onConfirm={handleConfirm}\\n            okText=\\"Xác nhận\\" cancelText=\\"Hủy\\">\\n            <Button type=\\"primary\\" icon={<SafetyCertificateOutlined />}\\n              size=\\"large\\" loading={loading}>\\n              Xác nhận phê duyệt\\n            </Button>\\n          </Popconfirm>\\n          <Button onClick={onBack} size=\\"large\\">Hủy</Button>\\n        </Space>\\n      </Card>\\n    </Spin>\\n  );\\n}\\n\\n// ============================================================\\n// Main Router\\n// ============================================================\\nfunction PheDuyetBlock({ initBacTho, initDat, initLichSu, initHocVien }) {\\n  const [bacThoList, setBacThoList] = useState(initBacTho);\\n  const [datList, setDatList] = useState(initDat);\\n  const [lichSuList, setLichSuList] = useState(initLichSu);\\n  const [hocVienList, setHocVienList] = useState(initHocVien);\\n  const [view, setView] = useState({ name: 'list', data: null });\\n  const [history, setHistory] = useState([]);\\n\\n  var bacThoMap = useMemo(function() { return buildBacThoMap(bacThoList); }, [bacThoList]);\\n\\n  var reloadAll = useCallback(async function() {\\n    var bt = await fetchBacThoList();\\n    var d = await fetchThiSinhDat();\\n    var ls = await fetchLichSuNangBac();\\n    var hv = await fetchHocVienLop();\\n    setBacThoList(bt);\\n    setDatList(d);\\n    setLichSuList(ls);\\n    setHocVienList(hv);\\n  }, []);\\n\\n  function navigate(viewName, data) {\\n    setHistory(function(prev) { return prev.concat([view]); });\\n    setView({ name: viewName, data: data });\\n  }\\n\\n  function goBack() {\\n    setHistory(function(prev) {\\n      if (prev.length === 0) {\\n        setView({ name: 'list', data: null });\\n        return [];\\n      }\\n      var newHistory = prev.slice(0, -1);\\n      setView(prev[prev.length - 1]);\\n      return newHistory;\\n    });\\n  }\\n\\n  if (view.name === 'list') {\\n    return <B1_DanhSachPheDuyet datList={datList} lichSuList={lichSuList}\\n      bacThoList={bacThoList} hocVienList={hocVienList}\\n      onNavigate={navigate} reloadAll={reloadAll} />;\\n  }\\n\\n  if (view.name === 'detail') {\\n    return <B2_ChiTietHoSo record={view.data} lichSuList={lichSuList}\\n      bacThoMap={bacThoMap} onNavigate={navigate} onBack={goBack} />;\\n  }\\n\\n  if (view.name === 'confirm') {\\n    return <B3_XacNhanNangBac record={view.data}\\n      bacThoMap={bacThoMap} onBack={goBack} reloadAll={reloadAll} />;\\n  }\\n\\n  return <B1_DanhSachPheDuyet datList={datList} lichSuList={lichSuList}\\n    bacThoList={bacThoList} hocVienList={hocVienList}\\n    onNavigate={navigate} reloadAll={reloadAll} />;\\n}\\n\\n// -- Render ---------------------------------------------------\\nctx.render(<PheDuyetBlock initBacTho={initialBacTho} initDat={initialDat}\\n  initLichSu={initialLichSu} initHocVien={initialHocVien} />);\\n"}},"__flowSurfaceMeta":{"declaredKey":"pheDuyetNangBacJsV7"}}}
