qkoyx3kem18	qkoyx3kem18	{"parentId":"c6zenkj8wjg","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Quản lý vai trò"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// ============================================================\\n// JS Block: Quan ly vai tro\\n// Collection: vai_tro\\n// ============================================================\\n\\nconst {\\n  Table, Card, Button, Input, Select, Tag, Space, Row, Col,\\n  Modal, Form, Drawer, Popconfirm, Tooltip, Statistic, Divider,\\n  Typography, Spin, Pagination,\\n} = ctx.libs.antd;\\n\\nconst {\\n  PlusOutlined, ReloadOutlined, SearchOutlined,\\n  EyeOutlined, EditOutlined, DeleteOutlined,\\n  TeamOutlined, CheckCircleOutlined, DatabaseOutlined,\\n  CloseCircleOutlined,\\n} = ctx.libs.antdIcons;\\n\\nconst { useState, useCallback, useMemo } = ctx.libs.React;\\nconst { Text } = Typography;\\n\\n// -- Top-level data loading (MUST be outside React) -----------\\nasync function fetchVaiTro() {\\n  var res = ctx.makeResource('MultiRecordResource');\\n  res.setResourceName('vai_tro');\\n  res.setAppends(['nhom_quyen_mac_dinh']);\\n  res.setSort(['-createdAt']);\\n  res.setPageSize(500);\\n  await res.refresh();\\n  return res.getData() || [];\\n}\\nvar initialData = await fetchVaiTro();\\n\\n// -- React Component ------------------------------------------\\nfunction VaiTroBlock({ initData, reloadFn }) {\\n  // -- state --------------------------------------------------\\n  const [allData, setAllData] = useState(initData);\\n  const [loading, setLoading] = useState(false);\\n  const [page, setPage] = useState(1);\\n  const pageSize = 20;\\n\\n  const [searchText, setSearchText] = useState('');\\n  const [statusFilter, setStatusFilter] = useState(undefined);\\n\\n  const [viewOpen, setViewOpen] = useState(false);\\n  const [viewRecord, setViewRecord] = useState(null);\\n\\n  const [editOpen, setEditOpen] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [editLoading, setEditLoading] = useState(false);\\n\\n  const [addOpen, setAddOpen] = useState(false);\\n  const [addLoading, setAddLoading] = useState(false);\\n\\n  const [editForm] = Form.useForm();\\n  const [addForm] = Form.useForm();\\n\\n  // -- computed data (client-side) ----------------------------\\n  var activeRows = useMemo(function() {\\n    return allData.filter(function(r) { return !r.is_deleted; });\\n  }, [allData]);\\n\\n  var stats = useMemo(function() {\\n    return {\\n      total: allData.length,\\n      active: allData.filter(function(r) { return r.trang_thai === 'active' && !r.is_deleted; }).length,\\n      system: allData.filter(function(r) { return r.nguon_du_lieu === 'he_thong' && !r.is_deleted; }).length,\\n      deleted: allData.filter(function(r) { return r.is_deleted; }).length,\\n    };\\n  }, [allData]);\\n\\n  var filteredData = useMemo(function() {\\n    var rows = activeRows;\\n    if (searchText) {\\n      var lower = searchText.toLowerCase();\\n      rows = rows.filter(function(r) {\\n        return (r.ma_vai_tro && r.ma_vai_tro.toLowerCase().indexOf(lower) !== -1) ||\\n               (r.ten_vai_tro && r.ten_vai_tro.toLowerCase().indexOf(lower) !== -1);\\n      });\\n    }\\n    if (statusFilter) {\\n      rows = rows.filter(function(r) { return r.trang_thai === statusFilter; });\\n    }\\n    return rows;\\n  }, [activeRows, searchText, statusFilter]);\\n\\n  var total = filteredData.length;\\n\\n  var data = useMemo(function() {\\n    var start = (page - 1) * pageSize;\\n    return filteredData.slice(start, start + pageSize);\\n  }, [filteredData, page, pageSize]);\\n\\n  // -- fetch data ---------------------------------------------\\n  const fetchData = useCallback(async function() {\\n    setLoading(true);\\n    try {\\n      var newData = await reloadFn();\\n      setAllData(newData);\\n    } catch (err) {\\n      ctx.message.error('Không thể tải dữ liệu vai trò');\\n    } finally {\\n      setLoading(false);\\n    }\\n  }, [reloadFn]);\\n\\n  // -- handlers -----------------------------------------------\\n  const handleView = (record) => {\\n    setViewRecord(record);\\n    setViewOpen(true);\\n  };\\n\\n  const handleEdit = (record) => {\\n    setEditRecord(record);\\n    editForm.setFieldsValue({\\n      ten_vai_tro: record.ten_vai_tro,\\n      mo_ta: record.mo_ta,\\n      trang_thai: record.trang_thai,\\n      pham_vi_ap_dung: record.pham_vi_ap_dung,\\n    });\\n    setEditOpen(true);\\n  };\\n\\n  const handleEditSubmit = async () => {\\n    try {\\n      const values = await editForm.validateFields();\\n      setEditLoading(true);\\n      await ctx.request({\\n        url: 'vai_tro:update',\\n        method: 'post',\\n        params: { filterByTk: editRecord.id },\\n        data: values,\\n      });\\n      ctx.message.success('Cập nhật vai trò thành công');\\n      setEditOpen(false);\\n      editForm.resetFields();\\n      fetchData();\\n    } catch (err) {\\n      if (err.errorFields) return;\\n      console.error(err);\\n      ctx.message.error('Cập nhật vai trò thất bại');\\n    } finally {\\n      setEditLoading(false);\\n    }\\n  };\\n\\n  const handleAddSubmit = async () => {\\n    try {\\n      const values = await addForm.validateFields();\\n      setAddLoading(true);\\n      await ctx.request({\\n        url: 'vai_tro:create',\\n        method: 'post',\\n        data: { ...values, is_deleted: false },\\n      });\\n      ctx.message.success('Thêm vai trò thành công');\\n      setAddOpen(false);\\n      addForm.resetFields();\\n      setPage(1);\\n      fetchData();\\n    } catch (err) {\\n      if (err.errorFields) return;\\n      console.error(err);\\n      ctx.message.error('Thêm vai trò thất bại');\\n    } finally {\\n      setAddLoading(false);\\n    }\\n  };\\n\\n  const handleSoftDelete = async (record) => {\\n    try {\\n      await ctx.request({\\n        url: 'vai_tro:update',\\n        method: 'post',\\n        params: { filterByTk: record.id },\\n        data: { is_deleted: true },\\n      });\\n      ctx.message.success('Đã xóa vai trò');\\n      fetchData();\\n    } catch (err) {\\n      console.error(err);\\n      ctx.message.error('Xóa vai trò thất bại');\\n    }\\n  };\\n\\n  // -- nguon du lieu helpers ----------------------------------\\n  const NGUON_DU_LIEU_MAP = {\\n    he_thong: { label: 'Hệ thống', color: 'purple' },\\n    dong_bo: { label: 'Đồng bộ', color: 'cyan' },\\n  };\\n\\n  // -- columns ------------------------------------------------\\n  const columns = [\\n    {\\n      title: 'Mã vai trò',\\n      dataIndex: 'ma_vai_tro',\\n      key: 'ma_vai_tro',\\n      width: 150,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'Tên vai trò',\\n      dataIndex: 'ten_vai_tro',\\n      key: 'ten_vai_tro',\\n      width: 200,\\n      ellipsis: true,\\n    },\\n    {\\n      title: 'Nhóm quyền mặc định',\\n      dataIndex: 'nhom_quyen_mac_dinh',\\n      key: 'nhom_quyen_mac_dinh',\\n      width: 250,\\n      render: (items) => {\\n        if (!items || !items.length) return '-';\\n        return (\\n          <Space size={4} wrap>\\n            {items.map((item) => (\\n              <Tag key={item.id} color=\\"blue\\">\\n                {item.ten_nhom}\\n              </Tag>\\n            ))}\\n          </Space>\\n        );\\n      },\\n    },\\n    {\\n      title: 'Nguồn dữ liệu',\\n      dataIndex: 'nguon_du_lieu',\\n      key: 'nguon_du_lieu',\\n      width: 140,\\n      render: (val) => {\\n        const info = NGUON_DU_LIEU_MAP[val];\\n        if (!info) return <Tag>{val || '-'}</Tag>;\\n        return <Tag color={info.color}>{info.label}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      key: 'trang_thai',\\n      width: 140,\\n      render: (val) => {\\n        if (val === 'active') return <Tag color=\\"green\\">Đang sử dụng</Tag>;\\n        if (val === 'inactive') return <Tag color=\\"red\\">Ngừng sử dụng</Tag>;\\n        return <Tag>{val || '-'}</Tag>;\\n      },\\n    },\\n    {\\n      title: 'Thao tác',\\n      key: 'actions',\\n      fixed: 'right',\\n      width: 150,\\n      render: (_, record) => (\\n        <Space size={4}>\\n          <Tooltip title=\\"Xem chi tiết\\">\\n            <Button\\n              icon={<EyeOutlined />}\\n              size=\\"small\\"\\n              onClick={() => handleView(record)}\\n            />\\n          </Tooltip>\\n          <Tooltip title=\\"Chỉnh sửa\\">\\n            <Button\\n              icon={<EditOutlined />}\\n              size=\\"small\\"\\n              onClick={() => handleEdit(record)}\\n            />\\n          </Tooltip>\\n          <Popconfirm\\n            title=\\"Xóa vai trò\\"\\n            description=\\"Bạn có chắc chắn muốn xóa vai trò này?\\"\\n            onConfirm={() => handleSoftDelete(record)}\\n            okText=\\"Xóa\\"\\n            cancelText=\\"Hủy\\"\\n          >\\n            <Tooltip title=\\"Xóa\\">\\n              <Button\\n                icon={<DeleteOutlined />}\\n                size=\\"small\\"\\n                danger\\n              />\\n            </Tooltip>\\n          </Popconfirm>\\n        </Space>\\n      ),\\n    },\\n  ];\\n\\n  // -- render -------------------------------------------------\\n  return (\\n    <div style={{ padding: 24 }}>\\n      {/* -- Stats cards ------------------------------------ */}\\n      <Row gutter={16} style={{ marginBottom: 24 }}>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Tổng vai trò\\"\\n              value={stats.total}\\n              prefix={<TeamOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Đang sử dụng\\"\\n              value={stats.active}\\n              valueStyle={{ color: '#52c41a' }}\\n              prefix={<CheckCircleOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Nguồn hệ thống\\"\\n              value={stats.system}\\n              valueStyle={{ color: '#722ed1' }}\\n              prefix={<DatabaseOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n        <Col xs={12} sm={6}>\\n          <Card bordered>\\n            <Statistic\\n              title=\\"Đã xóa\\"\\n              value={stats.deleted}\\n              valueStyle={{ color: '#999' }}\\n              prefix={<CloseCircleOutlined />}\\n            />\\n          </Card>\\n        </Col>\\n      </Row>\\n\\n      {/* -- Search + Actions bar --------------------------- */}\\n      <Card bordered style={{ marginBottom: 16 }}>\\n        <Row gutter={16} align=\\"middle\\" justify=\\"space-between\\">\\n          <Col flex=\\"auto\\">\\n            <Space size={12} wrap>\\n              <Input\\n                placeholder=\\"Tìm theo mã hoặc tên vai trò\\"\\n                prefix={<SearchOutlined />}\\n                allowClear\\n                style={{ width: 320 }}\\n                value={searchText}\\n                onChange={(e) => {\\n                  setSearchText(e.target.value);\\n                  setPage(1);\\n                }}\\n                onPressEnter={fetchData}\\n              />\\n              <Select\\n                placeholder=\\"Trạng thái\\"\\n                allowClear\\n                style={{ width: 180 }}\\n                value={statusFilter}\\n                onChange={(val) => {\\n                  setStatusFilter(val);\\n                  setPage(1);\\n                }}\\n                options={[\\n                  { label: 'Đang sử dụng', value: 'active' },\\n                  { label: 'Ngừng sử dụng', value: 'inactive' },\\n                ]}\\n              />\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Button\\n                icon={<PlusOutlined />}\\n                type=\\"primary\\"\\n                onClick={() => {\\n                  addForm.resetFields();\\n                  addForm.setFieldsValue({ trang_thai: 'active' });\\n                  setAddOpen(true);\\n                }}\\n              >\\n                Thêm mới\\n              </Button>\\n              <Tooltip title=\\"Làm mới\\">\\n                <Button\\n                  icon={<ReloadOutlined />}\\n                  onClick={fetchData}\\n                />\\n              </Tooltip>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      {/* -- Data table ------------------------------------- */}\\n      <Card bordered>\\n        <Spin spinning={loading}>\\n          <Table\\n            rowKey=\\"id\\"\\n            columns={columns}\\n            dataSource={data}\\n            pagination={false}\\n            scroll={{ x: 1100 }}\\n            size=\\"middle\\"\\n            bordered\\n          />\\n          <div\\n            style={{\\n              display: 'flex',\\n              justifyContent: 'flex-end',\\n              marginTop: 16,\\n            }}\\n          >\\n            <Pagination\\n              current={page}\\n              pageSize={pageSize}\\n              total={total}\\n              showSizeChanger={false}\\n              showTotal={(t) => `Tổng ${t} bản ghi`}\\n              onChange={(p) => setPage(p)}\\n            />\\n          </div>\\n        </Spin>\\n      </Card>\\n\\n      {/* -- View Drawer ------------------------------------ */}\\n      <Drawer\\n        title=\\"Chi tiết vai trò\\"\\n        width={560}\\n        open={viewOpen}\\n        onClose={() => setViewOpen(false)}\\n      >\\n        {viewRecord && (\\n          <div>\\n            <Divider orientation=\\"left\\" style={{ marginTop: 0 }}>\\n              Thông tin chung\\n            </Divider>\\n\\n            <Row gutter={[16, 16]}>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Mã vai trò</Text>\\n                <div><Text strong>{viewRecord.ma_vai_tro || '-'}</Text></div>\\n              </Col>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Tên vai trò</Text>\\n                <div><Text strong>{viewRecord.ten_vai_tro || '-'}</Text></div>\\n              </Col>\\n              <Col span={24}>\\n                <Text type=\\"secondary\\">Mô tả</Text>\\n                <div><Text>{viewRecord.mo_ta || '-'}</Text></div>\\n              </Col>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Nguồn dữ liệu</Text>\\n                <div>\\n                  {viewRecord.nguon_du_lieu ? (\\n                    <Tag color={NGUON_DU_LIEU_MAP[viewRecord.nguon_du_lieu]?.color}>\\n                      {NGUON_DU_LIEU_MAP[viewRecord.nguon_du_lieu]?.label || viewRecord.nguon_du_lieu}\\n                    </Tag>\\n                  ) : (\\n                    <Text>-</Text>\\n                  )}\\n                </div>\\n              </Col>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Trạng thái</Text>\\n                <div>\\n                  {viewRecord.trang_thai === 'active' ? (\\n                    <Tag color=\\"green\\">Đang sử dụng</Tag>\\n                  ) : viewRecord.trang_thai === 'inactive' ? (\\n                    <Tag color=\\"red\\">Ngừng sử dụng</Tag>\\n                  ) : (\\n                    <Tag>{viewRecord.trang_thai || '-'}</Tag>\\n                  )}\\n                </div>\\n              </Col>\\n              <Col span={24}>\\n                <Text type=\\"secondary\\">Phạm vi áp dụng</Text>\\n                <div><Text>{viewRecord.pham_vi_ap_dung || '-'}</Text></div>\\n              </Col>\\n              <Col span={12}>\\n                <Text type=\\"secondary\\">Đã xóa</Text>\\n                <div>\\n                  <Text>{viewRecord.is_deleted ? 'Có' : 'Không'}</Text>\\n                </div>\\n              </Col>\\n              <Col span={24}>\\n                <Text type=\\"secondary\\">Nhóm quyền mặc định</Text>\\n                <div style={{ marginTop: 4 }}>\\n                  {viewRecord.nhom_quyen_mac_dinh && viewRecord.nhom_quyen_mac_dinh.length > 0 ? (\\n                    <Space size={4} wrap>\\n                      {viewRecord.nhom_quyen_mac_dinh.map((item) => (\\n                        <Tag key={item.id} color=\\"blue\\">\\n                          {item.ten_nhom}\\n                        </Tag>\\n                      ))}\\n                    </Space>\\n                  ) : (\\n                    <Text>-</Text>\\n                  )}\\n                </div>\\n              </Col>\\n            </Row>\\n          </div>\\n        )}\\n      </Drawer>\\n\\n      {/* -- Edit Modal ------------------------------------- */}\\n      <Modal\\n        title=\\"Chỉnh sửa vai trò\\"\\n        open={editOpen}\\n        onCancel={() => {\\n          setEditOpen(false);\\n          editForm.resetFields();\\n        }}\\n        onOk={handleEditSubmit}\\n        confirmLoading={editLoading}\\n        okText=\\"Lưu\\"\\n        cancelText=\\"Hủy\\"\\n        width={600}\\n        destroyOnClose\\n      >\\n        <Form\\n          form={editForm}\\n          layout=\\"vertical\\"\\n          style={{ marginTop: 16 }}\\n        >\\n          <Form.Item\\n            name=\\"ten_vai_tro\\"\\n            label=\\"Tên vai trò\\"\\n            rules={[{ required: true, message: 'Vui lòng nhập tên vai trò' }]}\\n          >\\n            <Input placeholder=\\"Nhập tên vai trò\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập mô tả\\" />\\n          </Form.Item>\\n          <Form.Item\\n            name=\\"trang_thai\\"\\n            label=\\"Trạng thái\\"\\n            rules={[{ required: true, message: 'Vui lòng chọn trạng thái' }]}\\n          >\\n            <Select\\n              placeholder=\\"Chọn trạng thái\\"\\n              options={[\\n                { label: 'Đang sử dụng', value: 'active' },\\n                { label: 'Ngừng sử dụng', value: 'inactive' },\\n              ]}\\n            />\\n          </Form.Item>\\n          <Form.Item name=\\"pham_vi_ap_dung\\" label=\\"Phạm vi áp dụng\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập phạm vi áp dụng\\" />\\n          </Form.Item>\\n        </Form>\\n      </Modal>\\n\\n      {/* -- Add New Modal ---------------------------------- */}\\n      <Modal\\n        title=\\"Thêm vai trò mới\\"\\n        open={addOpen}\\n        onCancel={() => {\\n          setAddOpen(false);\\n          addForm.resetFields();\\n        }}\\n        onOk={handleAddSubmit}\\n        confirmLoading={addLoading}\\n        okText=\\"Thêm\\"\\n        cancelText=\\"Hủy\\"\\n        width={600}\\n        destroyOnClose\\n      >\\n        <Form\\n          form={addForm}\\n          layout=\\"vertical\\"\\n          initialValues={{ trang_thai: 'active' }}\\n          style={{ marginTop: 16 }}\\n        >\\n          <Form.Item\\n            name=\\"ma_vai_tro\\"\\n            label=\\"Mã vai trò\\"\\n            rules={[{ required: true, message: 'Vui lòng nhập mã vai trò' }]}\\n          >\\n            <Input placeholder=\\"Nhập mã vai trò\\" />\\n          </Form.Item>\\n          <Form.Item\\n            name=\\"ten_vai_tro\\"\\n            label=\\"Tên vai trò\\"\\n            rules={[{ required: true, message: 'Vui lòng nhập tên vai trò' }]}\\n          >\\n            <Input placeholder=\\"Nhập tên vai trò\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập mô tả\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"nguon_du_lieu\\" label=\\"Nguồn dữ liệu\\">\\n            <Select\\n              placeholder=\\"Chọn nguồn dữ liệu\\"\\n              allowClear\\n              options={[\\n                { label: 'Hệ thống', value: 'he_thong' },\\n                { label: 'Đồng bộ', value: 'dong_bo' },\\n              ]}\\n            />\\n          </Form.Item>\\n          <Form.Item\\n            name=\\"trang_thai\\"\\n            label=\\"Trạng thái\\"\\n            rules={[{ required: true, message: 'Vui lòng chọn trạng thái' }]}\\n          >\\n            <Select\\n              placeholder=\\"Chọn trạng thái\\"\\n              options={[\\n                { label: 'Đang sử dụng', value: 'active' },\\n                { label: 'Ngừng sử dụng', value: 'inactive' },\\n              ]}\\n            />\\n          </Form.Item>\\n          <Form.Item name=\\"pham_vi_ap_dung\\" label=\\"Phạm vi áp dụng\\">\\n            <Input.TextArea rows={3} placeholder=\\"Nhập phạm vi áp dụng\\" />\\n          </Form.Item>\\n        </Form>\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<VaiTroBlock initData={initialData} reloadFn={fetchVaiTro} />);\\n"}},"__flowSurfaceMeta":{"declaredKey":"vaiTroJsV3"}}}
