c3cd1ivy2i8	c3cd1ivy2i8	{"parentId":"gx41dcgo3bi","subKey":"grid","subType":"object","use":"BlockGridModel","props":{"rows":{"row1":[["htb6ur5vt9u"]]},"sizes":{"row1":[24]},"rowOrder":["row1"]},"stepParams":{"gridSettings":{"grid":{"rows":{"row1":[["htb6ur5vt9u"]]},"sizes":{"row1":[24]},"rowOrder":["row1"]}}}}
htb6ur5vt9u	htb6ur5vt9u	{"parentId":"c3cd1ivy2i8","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"14","code":"const { useState, useEffect, useCallback, useMemo } = ctx.libs.React;\\nconst { Table, Button, Input, Select, Space, Tag, Modal, Form, Upload, Tooltip, Popconfirm, Typography, Card, Row, Col, Spin, Badge } = ctx.libs.antd;\\nconst { SearchOutlined, PlusOutlined, SendOutlined, DeleteOutlined, EyeOutlined, ReloadOutlined, UploadOutlined, EditOutlined, CheckCircleOutlined } = ctx.libs.antdIcons;\\nconst dayjs = ctx.libs.dayjs;\\n\\nctx.initResource('MultiRecordResource');\\nconst resource = ctx.resource;\\nresource.setResourceName('tai_lieu_huan_luyen');\\nresource.setAppends(['nganh_nghe', 'bac_tho', 'nguoi_tai_len', 'nguoi_phe_duyet', 'tep_tai_lieu', 'phien_ban']);\\nresource.setSort(['-createdAt']);\\nresource.setPageSize(15);\\n\\nconst nganhNgheRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nnganhNgheRes?.setResourceName('nganh_nghe');\\nnganhNgheRes?.setPageSize(200);\\n\\nconst bacThoRes = ctx.makeResource ? ctx.makeResource('MultiRecordResource') : null;\\nbacThoRes?.setResourceName('bac_tho');\\nbacThoRes?.setPageSize(200);\\n\\nconst statusColors = {\\n  soan_thao: 'default',\\n  cho_phe_duyet: 'processing',\\n  da_phe_duyet: 'success',\\n  tu_choi: 'error',\\n  yeu_cau_chinh_sua: 'warning',\\n  da_thu_hoi: 'default'\\n};\\nconst statusLabels = {\\n  soan_thao: 'Soạn thảo',\\n  cho_phe_duyet: 'Chờ phê duyệt',\\n  da_phe_duyet: 'Đã phê duyệt',\\n  tu_choi: 'Từ chối',\\n  yeu_cau_chinh_sua: 'Yêu cầu chỉnh sửa',\\n  da_thu_hoi: 'Đã thu hồi'\\n};\\nconst loaiLabels = {\\n  van_ban: 'Văn bản',\\n  video: 'Video',\\n  hinh_anh: 'Hình ảnh',\\n  quy_dinh: 'Quy định / pháp luật',\\n  khac: 'Khác',\\n  tai_lieu_dien_tu: 'Tài liệu điện tử',\\n  giao_trinh: 'Giáo trình',\\n  bai_giang: 'Bài giảng'\\n};\\nconst nhomLabels = {\\n  nhom_1: 'Nhóm 1', nhom_2: 'Nhóm 2', nhom_3: 'Nhóm 3',\\n  nhom_4: 'Nhóm 4', nhom_5: 'Nhóm 5', nhom_6: 'Nhóm 6'\\n};\\n\\nfunction App() {\\n  const [loading, setLoading] = useState(true);\\n  const [data, setData] = useState([]);\\n  const [meta, setMeta] = useState({});\\n  const [searchName, setSearchName] = useState('');\\n  const [filterType, setFilterType] = useState(null);\\n  const [filterStatus, setFilterStatus] = useState(null);\\n  const [filterGroup, setFilterGroup] = useState(null);\\n  const [modalOpen, setModalOpen] = useState(false);\\n  const [editRecord, setEditRecord] = useState(null);\\n  const [detailOpen, setDetailOpen] = useState(false);\\n  const [detailRecord, setDetailRecord] = useState(null);\\n  const [saving, setSaving] = useState(false);\\n  const [fileList, setFileList] = useState([]);\\n  const [nganhNgheList, setNganhNgheList] = useState([]);\\n  const [bacThoList, setBacThoList] = useState([]);\\n  const [form] = Form.useForm();\\n\\n  const loadOptions = useCallback(async () => {\\n    try {\\n      if (nganhNgheRes) { await nganhNgheRes.refresh(); setNganhNgheList(nganhNgheRes.getData() || []); }\\n      if (bacThoRes) { await bacThoRes.refresh(); setBacThoList(bacThoRes.getData() || []); }\\n    } catch (e) { /* ignore */ }\\n  }, []);\\n\\n  const loadData = useCallback(async (page) => {\\n    setLoading(true);\\n    try {\\n      const filter = { is_deleted: { $ne: true } };\\n      if (searchName) filter.ten_tai_lieu = { $includes: searchName };\\n      if (filterType) filter.loai_tai_lieu = { $eq: filterType };\\n      if (filterStatus) filter.trang_thai = { $eq: filterStatus };\\n      if (filterGroup) filter.nhom_huan_luyen = { $eq: filterGroup };\\n      resource.setFilter(filter);\\n      if (page) resource.setPage(page);\\n      await resource.refresh();\\n      setData(resource.getData() || []);\\n      setMeta(resource.getMeta() || {});\\n    } catch (e) {\\n      ctx.message.error('Lỗi tải dữ liệu: ' + (e.message || ''));\\n    }\\n    setLoading(false);\\n  }, [searchName, filterType, filterStatus, filterGroup]);\\n\\n  useEffect(() => { loadData(1); loadOptions(); }, []);\\n\\n  const handleSearch = useCallback(() => { loadData(1); }, [loadData]);\\n\\n  const openEdit = useCallback((record) => {\\n    setEditRecord(record);\\n    form.setFieldsValue({\\n      ten_tai_lieu: record.ten_tai_lieu,\\n      loai_tai_lieu: record.loai_tai_lieu,\\n      nhom_huan_luyen: record.nhom_huan_luyen,\\n      nganhNgheId: record.nganhNgheId,\\n      bacThoId: record.bacThoId,\\n      phien_ban_hien_tai: record.phien_ban_hien_tai,\\n      mo_ta: record.mo_ta,\\n      can_cu_phap_ly: record.can_cu_phap_ly\\n    });\\n    setFileList([]);\\n    setModalOpen(true);\\n  }, [form]);\\n\\n  const handleSave = useCallback(async () => {\\n    try {\\n      const values = await form.validateFields();\\n      setSaving(true);\\n      const attachmentIds = fileList\\n        .filter(f => f.status === 'done' && f.response?.data?.id)\\n        .map(f => ({ id: f.response.data.id }));\\n      if (editRecord) {\\n        const payload = { ...values, trang_thai: 'soan_thao' };\\n        if (attachmentIds.length > 0) payload.tep_tai_lieu = attachmentIds;\\n        await resource.update(editRecord.id, payload);\\n        ctx.message.success('Cập nhật tài liệu thành công, trạng thái đã chuyển về Soạn thảo');\\n      } else {\\n        const payload = { ...values, trang_thai: 'soan_thao', is_deleted: false };\\n        if (attachmentIds.length > 0) payload.tep_tai_lieu = attachmentIds;\\n        await resource.create(payload);\\n        ctx.message.success('Tạo tài liệu thành công');\\n      }\\n      setModalOpen(false);\\n      setEditRecord(null);\\n      form.resetFields();\\n      setFileList([]);\\n      loadData(1);\\n    } catch (e) {\\n      if (e.errorFields) { setSaving(false); return; }\\n      ctx.message.error('Lỗi lưu tài liệu: ' + (e.message || ''));\\n    }\\n    setSaving(false);\\n  }, [form, loadData, fileList, editRecord]);\\n\\n  const handleSendApproval = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, {\\n        trang_thai: 'cho_phe_duyet',\\n        ngay_gui_duyet: dayjs().format('YYYY-MM-DD HH:mm:ss')\\n      });\\n      ctx.message.success('Đã gửi duyệt tài liệu: ' + record.ten_tai_lieu);\\n      loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi gửi duyệt: ' + (e.message || ''));\\n    }\\n  }, [loadData]);\\n\\n  const handleApprove = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, {\\n        trang_thai: 'da_phe_duyet'\\n      });\\n      ctx.message.success('Đã phê duyệt tài liệu: ' + record.ten_tai_lieu);\\n      loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi phê duyệt: ' + (e.message || ''));\\n    }\\n  }, [loadData]);\\n\\n  const handleDelete = useCallback(async (record) => {\\n    try {\\n      await resource.update(record.id, { is_deleted: true });\\n      ctx.message.success('Đã xoá tài liệu: ' + record.ten_tai_lieu);\\n      loadData();\\n    } catch (e) {\\n      ctx.message.error('Lỗi xoá: ' + (e.message || ''));\\n    }\\n  }, [loadData]);\\n\\n  const columns = useMemo(() => [\\n    {\\n      title: 'Mã tài liệu',\\n      dataIndex: 'ma_tai_lieu',\\n      width: 130,\\n      ellipsis: true\\n    },\\n    {\\n      title: 'Tên tài liệu',\\n      dataIndex: 'ten_tai_lieu',\\n      ellipsis: true,\\n      render: (text, record) => (\\n        <Typography.Link onClick={() => { setDetailRecord(record); setDetailOpen(true); }}>\\n          {text}\\n        </Typography.Link>\\n      )\\n    },\\n    {\\n      title: 'Loại',\\n      dataIndex: 'loai_tai_lieu',\\n      width: 160,\\n      ellipsis: true,\\n      render: (val) => loaiLabels[val] || val || '-'\\n    },\\n    {\\n      title: 'Nhóm HL',\\n      dataIndex: 'nhom_huan_luyen',\\n      width: 100,\\n      render: (val) => nhomLabels[val] || val || '-'\\n    },\\n    {\\n      title: 'Trạng thái',\\n      dataIndex: 'trang_thai',\\n      width: 140,\\n      render: (val) => {\\n        const color = statusColors[val] || 'default';\\n        const label = statusLabels[val] || val || '-';\\n        return <Tag color={color}>{label}</Tag>;\\n      }\\n    },\\n    {\\n      title: 'Phiên bản',\\n      dataIndex: 'phien_ban_hien_tai',\\n      width: 100,\\n      align: 'center'\\n    },\\n    {\\n      title: 'Người tải lên',\\n      dataIndex: ['nguoi_tai_len', 'nickname'],\\n      width: 140,\\n      ellipsis: true,\\n      render: (val) => val || '-'\\n    },\\n    {\\n      title: 'Ngày tạo',\\n      dataIndex: 'createdAt',\\n      width: 110,\\n      render: (val) => val ? dayjs(val).format('DD/MM/YYYY') : '-'\\n    },\\n    {\\n      title: 'Thao tác',\\n      width: 200,\\n      fixed: 'right',\\n      render: (_, record) => (\\n        <Space size={4}>\\n          <Tooltip title=\\"Xem chi tiết\\">\\n            <Button icon={<EyeOutlined />} onClick={() => { setDetailRecord(record); setDetailOpen(true); }} />\\n          </Tooltip>\\n          <Tooltip title=\\"Chỉnh sửa\\">\\n            <Button icon={<EditOutlined />} onClick={() => openEdit(record)} />\\n          </Tooltip>\\n          {(record.trang_thai === 'soan_thao' || record.trang_thai === 'tu_choi') && (\\n            <Tooltip title=\\"Gửi duyệt\\">\\n              <Button icon={<SendOutlined />} onClick={() => handleSendApproval(record)} />\\n            </Tooltip>\\n          )}\\n          {record.trang_thai === 'cho_phe_duyet' && (\\n            <Popconfirm title=\\"Phê duyệt tài liệu này?\\" onConfirm={() => handleApprove(record)} okText=\\"Phê duyệt\\" cancelText=\\"Huỷ\\">\\n              <Tooltip title=\\"Phê duyệt\\">\\n                <Button style={{ color: '#52c41a', borderColor: '#52c41a' }} icon={<CheckCircleOutlined />} />\\n              </Tooltip>\\n            </Popconfirm>\\n          )}\\n          <Popconfirm title=\\"Xoá tài liệu này?\\" onConfirm={() => handleDelete(record)} okText=\\"Xoá\\" cancelText=\\"Huỷ\\">\\n            <Tooltip title=\\"Xoá\\">\\n              <Button danger icon={<DeleteOutlined />} />\\n            </Tooltip>\\n          </Popconfirm>\\n        </Space>\\n      )\\n    }\\n  ], [handleSendApproval, handleApprove, handleDelete, openEdit]);\\n\\n  return (\\n    <div style={{ padding: '0 4px' }}>\\n      <Card size=\\"small\\" style={{ marginBottom: 16 }}>\\n        <Row gutter={[12, 12]} align=\\"middle\\">\\n          <Col flex=\\"auto\\">\\n            <Space wrap size={8}>\\n              <Input\\n                placeholder=\\"Tìm tên tài liệu...\\"\\n                prefix={<SearchOutlined />}\\n                value={searchName}\\n                onChange={e => setSearchName(e.target.value)}\\n                onPressEnter={handleSearch}\\n                style={{ width: 220 }}\\n                allowClear\\n              />\\n              <Select\\n                placeholder=\\"Loại tài liệu\\"\\n                value={filterType}\\n                onChange={setFilterType}\\n                allowClear\\n                style={{ width: 180 }}\\n                options={[\\n                  { label: 'Văn bản', value: 'van_ban' },\\n                  { label: 'Video', value: 'video' },\\n                  { label: 'Hình ảnh', value: 'hinh_anh' },\\n                  { label: 'Quy định / pháp luật', value: 'quy_dinh' },\\n                  { label: 'Khác', value: 'khac' }\\n                ]}\\n              />\\n              <Select\\n                placeholder=\\"Trạng thái\\"\\n                value={filterStatus}\\n                onChange={setFilterStatus}\\n                allowClear\\n                style={{ width: 160 }}\\n                options={Object.entries(statusLabels).map(([k, v]) => ({ label: v, value: k }))}\\n              />\\n              <Select\\n                placeholder=\\"Nhóm huấn luyện\\"\\n                value={filterGroup}\\n                onChange={setFilterGroup}\\n                allowClear\\n                style={{ width: 120 }}\\n                options={Object.entries(nhomLabels).map(([k, v]) => ({ label: v, value: k }))}\\n              />\\n              <Button icon={<SearchOutlined />} type=\\"primary\\" onClick={handleSearch}>Tìm kiếm</Button>\\n            </Space>\\n          </Col>\\n          <Col>\\n            <Space size={8}>\\n              <Tooltip title=\\"Tải lại\\">\\n                <Button icon={<ReloadOutlined />} onClick={() => loadData()} />\\n              </Tooltip>\\n              <Button type=\\"primary\\" icon={<PlusOutlined />} onClick={() => { setEditRecord(null); form.resetFields(); setFileList([]); setModalOpen(true); }}>\\n                Thêm tài liệu\\n              </Button>\\n            </Space>\\n          </Col>\\n        </Row>\\n      </Card>\\n\\n      <Table\\n        rowKey=\\"id\\"\\n        columns={columns}\\n        dataSource={data}\\n        loading={loading}\\n        size=\\"middle\\"\\n        scroll={{ x: 1100 }}\\n        pagination={{\\n          current: meta.page || 1,\\n          pageSize: meta.pageSize || 15,\\n          total: meta.count || 0,\\n          showTotal: (total) => `Tổng ${total} tài liệu`,\\n          showSizeChanger: true,\\n          pageSizeOptions: ['10', '15', '20', '50'],\\n          onChange: (page, pageSize) => {\\n            resource.setPageSize(pageSize);\\n            loadData(page);\\n          }\\n        }}\\n      />\\n\\n      <Modal\\n        title={editRecord ? 'Chỉnh sửa tài liệu' : 'Thêm tài liệu đào tạo'}\\n        open={modalOpen}\\n        onCancel={() => { setModalOpen(false); setEditRecord(null); }}\\n        onOk={handleSave}\\n        confirmLoading={saving}\\n        okText={editRecord ? 'Cập nhật' : 'Tạo'}\\n        cancelText=\\"Huỷ\\"\\n        width={640}\\n        destroyOnClose\\n      >\\n        <Form form={form} layout=\\"vertical\\" style={{ marginTop: 16 }}>\\n          <Row gutter={16}>\\n            <Col span={12}>\\n              <Form.Item name=\\"ten_tai_lieu\\" label=\\"Tên tài liệu\\" rules={[{ required: true, message: 'Nhập tên tài liệu' }]}>\\n                <Input placeholder=\\"Nhập tên tài liệu\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={12}>\\n              <Form.Item name=\\"loai_tai_lieu\\" label=\\"Loại tài liệu\\" rules={[{ required: true, message: 'Chọn loại' }]}>\\n                <Select placeholder=\\"Chọn loại\\" options={[\\n                  { label: 'Văn bản', value: 'van_ban' },\\n                  { label: 'Video', value: 'video' },\\n                  { label: 'Hình ảnh', value: 'hinh_anh' },\\n                  { label: 'Quy định / pháp luật', value: 'quy_dinh' },\\n                  { label: 'Khác', value: 'khac' }\\n                ]} />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={8}>\\n              <Form.Item name=\\"nhom_huan_luyen\\" label=\\"Nhóm huấn luyện\\">\\n                <Select placeholder=\\"Chọn nhóm\\" allowClear options={Object.entries(nhomLabels).map(([k, v]) => ({ label: v, value: k }))} />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"nganhNgheId\\" label=\\"Ngành nghề\\">\\n                <Select placeholder=\\"Chọn ngành nghề\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={nganhNgheList.map(n => ({ label: n.ten_nganh || n.ten_nganh_nghe, value: n.id }))}\\n                />\\n              </Form.Item>\\n            </Col>\\n            <Col span={8}>\\n              <Form.Item name=\\"bacThoId\\" label=\\"Bậc thợ\\">\\n                <Select placeholder=\\"Chọn bậc thợ\\" allowClear showSearch optionFilterProp=\\"label\\"\\n                  options={bacThoList.map(b => ({ label: b.ten_bac, value: b.id }))}\\n                />\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Row gutter={16}>\\n            <Col span={12}>\\n              <Form.Item name=\\"phien_ban_hien_tai\\" label=\\"Phiên bản\\" initialValue=\\"1.0\\">\\n                <Input placeholder=\\"Phiên bản\\" />\\n              </Form.Item>\\n            </Col>\\n            <Col span={12}>\\n              <Form.Item label=\\"Tệp đính kèm\\">\\n                <Upload\\n                  action=\\"/api/attachments:create\\"\\n                  multiple\\n                  fileList={fileList}\\n                  onChange={({ fileList: newList }) => setFileList(newList)}\\n                >\\n                  <Button icon={<UploadOutlined />}>Tải file lên</Button>\\n                </Upload>\\n              </Form.Item>\\n            </Col>\\n          </Row>\\n          <Form.Item name=\\"mo_ta\\" label=\\"Mô tả\\">\\n            <Input.TextArea rows={3} placeholder=\\"Mô tả tài liệu...\\" />\\n          </Form.Item>\\n          <Form.Item name=\\"can_cu_phap_ly\\" label=\\"Căn cứ pháp lý\\">\\n            <Input.TextArea rows={2} placeholder=\\"Căn cứ pháp lý áp dụng...\\" />\\n          </Form.Item>\\n        </Form>\\n      </Modal>\\n\\n      <Modal\\n        title={detailRecord ? `Chi tiết: ${detailRecord.ten_tai_lieu}` : 'Chi tiết tài liệu'}\\n        open={detailOpen}\\n        onCancel={() => { setDetailOpen(false); setDetailRecord(null); }}\\n        footer={null}\\n        width={700}\\n        destroyOnClose\\n      >\\n        {detailRecord && (\\n          <div>\\n            <Row gutter={[16, 12]}>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Mã tài liệu:</Typography.Text><br /><Typography.Text strong>{detailRecord.ma_tai_lieu || '-'}</Typography.Text></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Trạng thái:</Typography.Text><br /><Tag color={statusColors[detailRecord.trang_thai] || 'default'}>{statusLabels[detailRecord.trang_thai] || detailRecord.trang_thai || '-'}</Tag></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Loại tài liệu:</Typography.Text><br /><Typography.Text>{loaiLabels[detailRecord.loai_tai_lieu] || detailRecord.loai_tai_lieu || '-'}</Typography.Text></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Nhóm huấn luyện:</Typography.Text><br /><Typography.Text>{nhomLabels[detailRecord.nhom_huan_luyen] || detailRecord.nhom_huan_luyen || '-'}</Typography.Text></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Phiên bản:</Typography.Text><br /><Typography.Text>{detailRecord.phien_ban_hien_tai || '-'}</Typography.Text></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Ngành nghề:</Typography.Text><br /><Typography.Text>{detailRecord.nganh_nghe?.ten_nganh || detailRecord.nganh_nghe?.ten_nganh_nghe || '-'}</Typography.Text></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Bậc thợ:</Typography.Text><br /><Typography.Text>{detailRecord.bac_tho?.ten_bac || '-'}</Typography.Text></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Người tải lên:</Typography.Text><br /><Typography.Text>{detailRecord.nguoi_tai_len?.nickname || '-'}</Typography.Text></Col>\\n              <Col span={24}><Typography.Text type=\\"secondary\\">Mô tả:</Typography.Text><br /><Typography.Text>{detailRecord.mo_ta || 'Chưa có mô tả'}</Typography.Text></Col>\\n              <Col span={24}><Typography.Text type=\\"secondary\\">Căn cứ pháp lý:</Typography.Text><br /><Typography.Text>{detailRecord.can_cu_phap_ly || '-'}</Typography.Text></Col>\\n              {(detailRecord.tep_tai_lieu || []).length > 0 && (\\n                <Col span={24}>\\n                  <Typography.Text type=\\"secondary\\">Tệp đính kèm:</Typography.Text><br />\\n                  {detailRecord.tep_tai_lieu.map((f, i) => (\\n                    <Tag key={f.id || i} color=\\"blue\\" style={{ marginBottom: 4 }}>\\n                      <a href={f.url} target=\\"_blank\\" rel=\\"noopener noreferrer\\">{f.filename || f.title || `File ${i + 1}`}</a>\\n                    </Tag>\\n                  ))}\\n                </Col>\\n              )}\\n              {(detailRecord.trang_thai === 'da_phe_duyet' || detailRecord.trang_thai === 'tu_choi') && (\\n                <>\\n                  <Col span={12}><Typography.Text type=\\"secondary\\">Người phê duyệt:</Typography.Text><br /><Typography.Text>{detailRecord.nguoi_phe_duyet?.nickname || '-'}</Typography.Text></Col>\\n                  <Col span={12}><Typography.Text type=\\"secondary\\">Ngày phê duyệt:</Typography.Text><br /><Typography.Text>{detailRecord.ngay_phe_duyet ? dayjs(detailRecord.ngay_phe_duyet).format('DD/MM/YYYY') : '-'}</Typography.Text></Col>\\n                  <Col span={24}><Typography.Text type=\\"secondary\\">Ý kiến phê duyệt:</Typography.Text><br /><Typography.Text>{detailRecord.y_kien_phe_duyet || '-'}</Typography.Text></Col>\\n                </>\\n              )}\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Ngày tạo:</Typography.Text><br /><Typography.Text>{detailRecord.createdAt ? dayjs(detailRecord.createdAt).format('DD/MM/YYYY HH:mm') : '-'}</Typography.Text></Col>\\n              <Col span={12}><Typography.Text type=\\"secondary\\">Cập nhật:</Typography.Text><br /><Typography.Text>{detailRecord.updatedAt ? dayjs(detailRecord.updatedAt).format('DD/MM/YYYY HH:mm') : '-'}</Typography.Text></Col>\\n            </Row>\\n          </div>\\n        )}\\n      </Modal>\\n    </div>\\n  );\\n}\\n\\nctx.render(<App />);\\n"}},"__flowSurfaceMeta":{"declaredKey":"tab_1.jsBlock_1"}}}
