wjpuxmk03sl	wjpuxmk03sl	{"parentId":"8j8rbonn7is","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"Thống kê bậc thợ"},"stepParams":{"jsSettings":{"runJs":{"version":"1","code":"const { Alert, Card, Col, Row, Skeleton, Statistic } = ctx.libs.antd;\\nctx.render(<Skeleton active paragraph={{ rows: 1 }} />);\\ntry {\\n  const resource = ctx.makeResource('MultiRecordResource');\\n  resource.setResourceName('bac_tho');\\n  resource.setPageSize?.(1000);\\n  await resource.refresh();\\n  const rows = resource.getData?.() || [];\\n  const metrics = [\\n    { key: 'total', title: ctx.t('Tổng bậc thợ'), value: resource.getMeta?.()?.count ?? rows.length, color: '#1677ff' },\\n    { key: 'using', title: ctx.t('Đang sử dụng'), value: rows.filter((row) => !row.is_deleted).length, color: '#52c41a' },\\n    { key: 'deleted', title: ctx.t('Đã ngừng sử dụng'), value: rows.filter((row) => Boolean(row.is_deleted)).length, color: '#fa8c16' },\\n    { key: 'training', title: ctx.t('Yêu cầu huấn luyện'), value: rows.filter((row) => Boolean(row.yeu_cau_huan_luyen)).length, color: '#8c8c8c' },\\n  ];\\n  ctx.render(<Row gutter={[16, 16]}>{metrics.map((metric) => <Col key={metric.key} xs={24} sm={12} lg={6}><Card size=\\"small\\" style={{ borderLeft: `4px solid ${metric.color}`, height: '100%' }}><Statistic title={metric.title} value={metric.value} suffix={ctx.t('Bậc')} /></Card></Col>)}</Row>);\\n} catch (error) { ctx.render(<Alert type=\\"error\\" showIcon message={ctx.t('Không tải được thống kê bậc thợ')} description={String(error?.message || error)} />); }"}},"__flowSurfaceMeta":{"declaredKey":"workerGrades.workerGradeStats"}}}
