CREATE FUNCTION public.fn_delete_user_on_nguoi_lao_dong_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_user_id BIGINT;
    target_email VARCHAR;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_user_id := OLD."taiKhoanId";
        target_email := OLD.email;
    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.is_deleted = true AND (OLD.is_deleted IS NULL OR OLD.is_deleted = false) THEN
            target_user_id := OLD."taiKhoanId";
            target_email := OLD.email;
        ELSE
            RETURN NEW;
        END IF;
    END IF;

    IF target_user_id IS NULL AND target_email IS NOT NULL AND target_email != '' THEN
        SELECT id INTO target_user_id FROM "users" WHERE email = target_email;
    END IF;

    IF target_user_id IS NOT NULL THEN
        DELETE FROM "rolesUsers" WHERE "userId" = target_user_id;
        DELETE FROM "users_vai_tro" WHERE "user_id" = target_user_id;
        DELETE FROM "users_nhom_quyen" WHERE "user_id" = target_user_id;
        DELETE FROM "users_chuc_vu" WHERE "userId" = target_user_id;
        DELETE FROM "usersAuthenticators" WHERE "userId" = target_user_id;
        DELETE FROM "users" WHERE id = target_user_id;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


